import type {
  BaselineStreamCompletePayload,
  BaselineStreamDomain,
  BaselineStreamManifestEntry,
  BaselineStreamManifestPayload,
} from '../../netcode/protocol/BaselineStreaming';
import type {
  IceBaselinePartPayload,
  IceDeltaPayload,
} from '../../netcode/protocol/IceReplication';
import type {
  SnowBaselinePartPayload,
  SnowDeltaPayload,
} from '../../netcode/protocol/SnowReplication';

export interface BaselineStreamingClientDiagnostics {
  readonly activeTransfers: number;
  readonly manifestsAccepted: number;
  readonly transfersCompleted: number;
  readonly transfersCancelled: number;
  readonly stalePartsIgnored: number;
  readonly partsBuffered: number;
  readonly deltasBuffered: number;
  readonly completionFencesRejected: number;
  readonly bufferOverflows: number;
}

type DomainPart = SnowBaselinePartPayload | IceBaselinePartPayload;
type DomainDelta = SnowDeltaPayload | IceDeltaPayload;

interface Transfer {
  manifest: BaselineStreamManifestPayload;
  parts: Map<number, DomainPart>;
  entries: Map<string, BaselineStreamManifestEntry>;
  deltas: DomainDelta[];
}

export type CompletedBaselineStream =
  | Readonly<{
      domain: 'SNOW';
      parts: readonly SnowBaselinePartPayload[];
      deltas: readonly SnowDeltaPayload[];
    }>
  | Readonly<{
      domain: 'ICE';
      parts: readonly IceBaselinePartPayload[];
      deltas: readonly IceDeltaPayload[];
    }>;

const entriesEqual = (
  left: readonly Readonly<BaselineStreamManifestEntry>[],
  right: readonly Readonly<BaselineStreamManifestEntry>[],
): boolean => JSON.stringify(left) === JSON.stringify(right);

/**
 * Client-side completion fence for large baseline domains. Domain adapters do
 * not see partial state: baseline parts and newer reliable deltas are replayed
 * only after the manifest has been satisfied by an explicit complete fence.
 */
export class BaselineStreamingClient {
  private readonly transfers = new Map<BaselineStreamDomain, Transfer>();
  private readonly maximumBufferedDeltas: number;
  private readonly stats = {
    manifestsAccepted: 0,
    transfersCompleted: 0,
    transfersCancelled: 0,
    stalePartsIgnored: 0,
    partsBuffered: 0,
    deltasBuffered: 0,
    completionFencesRejected: 0,
    bufferOverflows: 0,
  };

  public constructor(maximumBufferedDeltas = 256) {
    if (!Number.isSafeInteger(maximumBufferedDeltas) ||
      maximumBufferedDeltas < 8 || maximumBufferedDeltas > 4_096) {
      throw new Error('Invalid staged-baseline delta buffer limit.');
    }
    this.maximumBufferedDeltas = maximumBufferedDeltas;
  }

  public begin(manifest: Readonly<BaselineStreamManifestPayload>): void {
    const previous = this.transfers.get(manifest.domain);
    if (previous && previous.manifest.transferId !== manifest.transferId) {
      this.stats.transfersCancelled += 1;
    }
    this.transfers.set(manifest.domain, {
      manifest: {
        ...manifest,
        entries: manifest.entries.map((entry) => ({ ...entry })),
      },
      parts: new Map(),
      entries: new Map(),
      deltas: [],
    });
    this.stats.manifestsAccepted += 1;
  }

  public hasActive(domain: BaselineStreamDomain): boolean {
    return this.transfers.has(domain);
  }

  public stageSnowPart(payload: Readonly<SnowBaselinePartPayload>): boolean {
    return this.stagePart('SNOW', payload, payload.tiles.map((tile) => ({
      key: `${tile.tileX},${tile.tileZ}`,
      revision: tile.revision,
      checksum: tile.checksum,
    })));
  }

  public stageIcePart(payload: Readonly<IceBaselinePartPayload>): boolean {
    return this.stagePart('ICE', payload, payload.chunks.map((chunk) => ({
      key: `${chunk.chunkX},${chunk.chunkZ}`,
      revision: chunk.revision,
      topologyRevision: chunk.topologyRevision,
      checksum: chunk.checksum,
    })));
  }

  public bufferSnowDelta(payload: Readonly<SnowDeltaPayload>): boolean {
    return this.bufferDelta('SNOW', payload);
  }

  public bufferIceDelta(payload: Readonly<IceDeltaPayload>): boolean {
    return this.bufferDelta('ICE', payload);
  }

  public complete(
    fence: Readonly<BaselineStreamCompletePayload>,
  ): CompletedBaselineStream | undefined {
    const transfer = this.transfers.get(fence.domain);
    if (!transfer ||
      transfer.manifest.transferId !== fence.transferId ||
      transfer.manifest.interestRevision !== fence.interestRevision ||
      transfer.manifest.manifestChecksum !== fence.manifestChecksum ||
      transfer.parts.size !== transfer.manifest.partCount) {
      this.stats.completionFencesRejected += 1;
      return undefined;
    }
    const actualEntries = [...transfer.entries.values()]
      .sort((left, right) => left.key.localeCompare(right.key));
    if (!entriesEqual(actualEntries, transfer.manifest.entries)) {
      this.stats.completionFencesRejected += 1;
      this.transfers.delete(fence.domain);
      return undefined;
    }
    const parts = [...transfer.parts.entries()]
      .sort((left, right) => left[0] - right[0])
      .map((entry) => entry[1]);
    const deltas = [...transfer.deltas];
    this.transfers.delete(fence.domain);
    this.stats.transfersCompleted += 1;
    return fence.domain === 'SNOW'
      ? {
          domain: 'SNOW',
          parts: parts as SnowBaselinePartPayload[],
          deltas: deltas as SnowDeltaPayload[],
        }
      : {
          domain: 'ICE',
          parts: parts as IceBaselinePartPayload[],
          deltas: deltas as IceDeltaPayload[],
        };
  }

  public reset(): void {
    this.transfers.clear();
  }

  public diagnostics(): BaselineStreamingClientDiagnostics {
    return {
      activeTransfers: this.transfers.size,
      ...this.stats,
    };
  }

  private stagePart(
    domain: BaselineStreamDomain,
    payload: Readonly<DomainPart>,
    entries: readonly Readonly<BaselineStreamManifestEntry>[],
  ): boolean {
    const transfer = this.transfers.get(domain);
    if (!transfer) return false;
    if (payload.transferId !== transfer.manifest.transferId) {
      this.stats.stalePartsIgnored += 1;
      return true;
    }
    if (payload.partCount !== transfer.manifest.partCount ||
      transfer.parts.has(payload.partIndex)) {
      return true;
    }
    for (const entry of entries) {
      if (transfer.entries.has(entry.key)) return true;
      transfer.entries.set(entry.key, { ...entry });
    }
    transfer.parts.set(payload.partIndex, payload as DomainPart);
    this.stats.partsBuffered += 1;
    return true;
  }

  private bufferDelta(
    domain: BaselineStreamDomain,
    payload: Readonly<DomainDelta>,
  ): boolean {
    const transfer = this.transfers.get(domain);
    if (!transfer) return false;
    if (transfer.deltas.length >= this.maximumBufferedDeltas) {
      this.stats.bufferOverflows += 1;
      this.transfers.delete(domain);
      return false;
    }
    transfer.deltas.push(payload as DomainDelta);
    this.stats.deltasBuffered += 1;
    return true;
  }
}
