import { type ServerTick, serverTick } from './NetworkPrimitives';

export interface AuthorityClockStep {
  ticks: readonly ServerTick[];
  droppedDebtMs: number;
  accumulatorMs: number;
}

export interface AuthorityClockDiagnostics {
  tickRateHz: number;
  tickDurationMs: number;
  emittedTicks: number;
  catchUpClamps: number;
  droppedDebtMs: number;
  accumulatorMs: number;
}

/** Fixed authority time independent from render cadence or setInterval drift. */
export class AuthorityClock {
  private readonly tickDurationMs: number;
  private accumulatorMs = 0;
  private lastNowMs?: number;
  private nextTickValue = 1;
  private emittedTicks = 0;
  private catchUpClamps = 0;
  private droppedDebtMs = 0;

  public constructor(
    private readonly tickRateHz = 60,
    private readonly maximumCatchUpTicks = 8,
    initialTick: ServerTick = serverTick(0),
  ) {
    if (!Number.isFinite(tickRateHz) || tickRateHz <= 0 || tickRateHz > 240) {
      throw new Error('Authority tick rate must be between zero and 240 Hz.');
    }
    if (!Number.isSafeInteger(maximumCatchUpTicks) || maximumCatchUpTicks < 1) {
      throw new Error('Maximum authority catch-up ticks must be positive.');
    }
    this.tickDurationMs = 1_000 / tickRateHz;
    this.nextTickValue = initialTick + 1;
  }

  public update(nowMs: number): AuthorityClockStep {
    if (!Number.isFinite(nowMs) || nowMs < 0) {
      throw new Error('Authority clock time must be finite and non-negative.');
    }
    if (this.lastNowMs === undefined) {
      this.lastNowMs = nowMs;
      return { ticks: [], droppedDebtMs: 0, accumulatorMs: this.accumulatorMs };
    }
    const elapsed = Math.max(0, nowMs - this.lastNowMs);
    this.lastNowMs = nowMs;
    this.accumulatorMs += elapsed;
    const maximumDebt = this.tickDurationMs * this.maximumCatchUpTicks;
    let droppedDebtMs = 0;
    if (this.accumulatorMs > maximumDebt) {
      droppedDebtMs = this.accumulatorMs - maximumDebt;
      this.accumulatorMs = maximumDebt;
      this.droppedDebtMs += droppedDebtMs;
      this.catchUpClamps += 1;
    }
    const ticks: ServerTick[] = [];
    while (
      ticks.length < this.maximumCatchUpTicks &&
      this.accumulatorMs + 1e-7 >= this.tickDurationMs
    ) {
      ticks.push(serverTick(this.nextTickValue++));
      this.accumulatorMs -= this.tickDurationMs;
      this.emittedTicks += 1;
    }
    return { ticks, droppedDebtMs, accumulatorMs: this.accumulatorMs };
  }

  public reset(nowMs: number, currentTick: ServerTick): void {
    if (!Number.isFinite(nowMs) || nowMs < 0) {
      throw new Error('Authority clock reset time is invalid.');
    }
    this.lastNowMs = nowMs;
    this.accumulatorMs = 0;
    this.nextTickValue = currentTick + 1;
  }

  public diagnostics(): AuthorityClockDiagnostics {
    return {
      tickRateHz: this.tickRateHz,
      tickDurationMs: this.tickDurationMs,
      emittedTicks: this.emittedTicks,
      catchUpClamps: this.catchUpClamps,
      droppedDebtMs: this.droppedDebtMs,
      accumulatorMs: this.accumulatorMs,
    };
  }
}

export interface ClockPingPayload {
  version: 1;
  pingId: number;
  clientSendMs: number;
}

export interface ClockPongPayload extends ClockPingPayload {
  serverReceiveMs: number;
  serverSendMs: number;
  serverTick: ServerTick;
}

export interface ClockSyncEstimate {
  samples: number;
  roundTripMs: number;
  clockOffsetMs: number;
  jitterMs: number;
  estimatedServerTick: number;
}

/** NTP-style low-pass estimate used only for scheduling, never authority. */
export class ClockOffsetEstimator {
  private samples = 0;
  private roundTripMs = 0;
  private clockOffsetMs = 0;
  private jitterMs = 0;
  private lastServerTick = 0;
  private lastServerSendMs = 0;

  public accept(pong: Readonly<ClockPongPayload>, clientReceiveMs: number): void {
    const roundTrip = Math.max(
      0,
      clientReceiveMs - pong.clientSendMs -
        Math.max(0, pong.serverSendMs - pong.serverReceiveMs),
    );
    const offset =
      ((pong.serverReceiveMs - pong.clientSendMs) +
        (pong.serverSendMs - clientReceiveMs)) /
      2;
    const alpha = this.samples === 0 ? 1 : 0.16;
    const previousRtt = this.roundTripMs;
    this.roundTripMs += (roundTrip - this.roundTripMs) * alpha;
    this.clockOffsetMs += (offset - this.clockOffsetMs) * alpha;
    this.jitterMs += (Math.abs(roundTrip - previousRtt) - this.jitterMs) * alpha;
    this.samples += 1;
    this.lastServerTick = pong.serverTick;
    this.lastServerSendMs = pong.serverSendMs;
  }

  public reset(): void {
    this.samples = 0;
    this.roundTripMs = 0;
    this.clockOffsetMs = 0;
    this.jitterMs = 0;
    this.lastServerTick = 0;
    this.lastServerSendMs = 0;
  }

  public estimate(clientNowMs: number, tickRateHz = 60): ClockSyncEstimate {
    const estimatedServerNow = clientNowMs + this.clockOffsetMs;
    return {
      samples: this.samples,
      roundTripMs: this.roundTripMs,
      clockOffsetMs: this.clockOffsetMs,
      jitterMs: this.jitterMs,
      estimatedServerTick:
        this.lastServerTick +
        Math.max(0, estimatedServerNow - this.lastServerSendMs) /
          (1_000 / tickRateHz),
    };
  }
}
