import {
  AdditiveBlending,
  type Camera,
  CanvasTexture,
  DoubleSide,
  LinearFilter,
  MeshBasicMaterial,
  NormalBlending,
  OrthographicCamera,
  PerspectiveCamera,
  Scene,
  SRGBColorSpace,
  Vector3,
} from 'three';
import {
  BatchedRenderer,
  ColorOverLife,
  ColorRange,
  ConstantValue,
  ForceOverLife,
  Gradient,
  type Behavior,
  type IParticleSystem,
  IntervalValue,
  type Particle,
  ParticleSystem,
  RectangleEmitter,
  RenderMode,
  Vector4 as ParticleColor,
} from 'three.quarks';
import { clamp } from '../utils/math';
import {
  calculateWeatherCoverage,
  calculateWeatherSpawnCenter,
} from './WeatherCoverage';

interface SnowLayer {
  system: ParticleSystem;
  emission: ConstantValue;
  forceX: ConstantValue;
  forceZ: ConstantValue;
  shape: RectangleEmitter;
}

interface WindLayer {
  system: ParticleSystem;
  emission: ConstantValue;
  forceX: ConstantValue;
  forceZ: ConstantValue;
  shape: RectangleEmitter;
}

interface CharacterSnowLayer {
  system: ParticleSystem;
  emission: ConstantValue;
  forceX: ConstantValue;
  forceZ: ConstantValue;
  shape: RectangleEmitter;
  spawnHeight: number;
}

export type PrecipitationOcclusionSampler = (
  x: number,
  y: number,
  z: number,
) => boolean;

/** Kills only flakes that physically enter a roofed excavated void. */
class PrecipitationOcclusionBehavior implements Behavior {
  public readonly type = 'IcewayPrecipitationOcclusion';

  public constructor(
    private readonly sampler: () =>
      PrecipitationOcclusionSampler | undefined,
  ) {}

  public initialize(
    _particle: Particle,
    _particleSystem: IParticleSystem,
  ): void {}

  public update(particle: Particle, _delta: number): void {
    const sample = this.sampler();
    if (!sample || !sample(
      particle.position.x,
      particle.position.y,
      particle.position.z,
    )) return;
    particle.age = particle.life;
  }

  public frameUpdate(_delta: number): void {}
  public reset(): void {}
  public toJSON(): unknown {
    return { type: this.type };
  }
  public clone(): Behavior {
    return new PrecipitationOcclusionBehavior(this.sampler);
  }
}

const createSnowflakeTexture = (): CanvasTexture => {
  const canvas = document.createElement('canvas');
  canvas.width = 64;
  canvas.height = 64;
  const context = canvas.getContext('2d');
  if (context) {
    const glow = context.createRadialGradient(32, 32, 1, 32, 32, 31);
    glow.addColorStop(0, 'rgba(255,255,255,1)');
    glow.addColorStop(0.24, 'rgba(245,253,255,0.95)');
    glow.addColorStop(0.58, 'rgba(224,245,255,0.42)');
    glow.addColorStop(1, 'rgba(210,240,255,0)');
    context.fillStyle = glow;
    context.fillRect(0, 0, 64, 64);
  }
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  texture.needsUpdate = true;
  return texture;
};

const createWindTexture = (): CanvasTexture => {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 32;
  const context = canvas.getContext('2d');
  if (context) {
    const glow = context.createLinearGradient(0, 16, 128, 16);
    glow.addColorStop(0, 'rgba(205,241,248,0)');
    glow.addColorStop(0.28, 'rgba(220,248,252,0.42)');
    glow.addColorStop(0.7, 'rgba(232,252,255,0.82)');
    glow.addColorStop(1, 'rgba(232,252,255,0)');
    context.fillStyle = glow;
    context.beginPath();
    context.ellipse(64, 16, 62, 4.5, 0, 0, Math.PI * 2);
    context.fill();
  }
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  texture.needsUpdate = true;
  return texture;
};

export class SnowfallSystem {
  private readonly scene: Scene;
  private readonly renderer = new BatchedRenderer();
  private readonly texture = createSnowflakeTexture();
  private readonly material = new MeshBasicMaterial({
    color: 0xffffff,
    map: this.texture,
    transparent: true,
    opacity: 0.96,
    depthWrite: false,
    // Cave walls and roofs must occlude outdoor precipitation. The previous
    // overlay material drew every flake through solid rock.
    depthTest: true,
    alphaTest: 0.018,
    blending: NormalBlending,
    side: DoubleSide,
  });
  private readonly windTexture = createWindTexture();
  private readonly windMaterial = new MeshBasicMaterial({
    color: 0xd7f5f8,
    map: this.windTexture,
    transparent: true,
    opacity: 0.92,
    depthWrite: false,
    depthTest: true,
    alphaTest: 0.006,
    blending: AdditiveBlending,
    side: DoubleSide,
  });
  private readonly near: SnowLayer;
  private readonly far: SnowLayer;
  private readonly characterNear: CharacterSnowLayer;
  private readonly characterFar: CharacterSnowLayer;
  private readonly wind: WindLayer;
  private readonly cameraUp = new Vector3();
  private readonly snowSpawnCenter = new Vector3();
  private readonly volumeNearCenter = new Vector3();
  private readonly volumeFarCenter = new Vector3();
  private intensity = 0;
  private blowingSnowIntensity = 0;
  private gustStrength = 0;
  private gustRemaining = 0;
  private windStreaksVisible = true;
  private localWeatherVisible = true;
  private volumeViewActive = false;
  private precipitationOcclusionSampler?: PrecipitationOcclusionSampler;

  public constructor(scene: Scene) {
    this.scene = scene;
    this.renderer.name = 'Quarks snowfall batch';
    this.renderer.renderOrder = 7;
    this.scene.add(this.renderer);
    this.far = this.createLayer({
      width: 54,
      depth: 46,
      height: 22,
      lifeMin: 8.5,
      lifeMax: 11.5,
      sizeMin: 0.09,
      sizeMax: 0.18,
      alphaMin: 0.34,
      alphaMax: 0.62,
      gravity: -1.85,
    });
    this.near = this.createLayer({
      width: 34,
      depth: 29,
      height: 19,
      lifeMin: 6.4,
      lifeMax: 8,
      sizeMin: 0.16,
      sizeMax: 0.34,
      alphaMin: 0.58,
      alphaMax: 0.94,
      gravity: -3.2,
    });
    this.characterFar = this.createCharacterLayer({
      width: 84,
      depth: 84,
      spawnHeight: 25,
      lifeMin: 9.5,
      lifeMax: 13.5,
      sizeMin: 0.085,
      sizeMax: 0.19,
      alphaMin: 0.38,
      alphaMax: 0.72,
      gravity: -0.46,
    });
    this.characterNear = this.createCharacterLayer({
      width: 30,
      depth: 30,
      spawnHeight: 12,
      lifeMin: 5.5,
      lifeMax: 8.5,
      sizeMin: 0.14,
      sizeMax: 0.32,
      alphaMin: 0.58,
      alphaMax: 0.96,
      gravity: -0.72,
    });
    this.wind = this.createWindLayer();
  }

  public setLocalWeatherVisible(visible: boolean): void {
    if (visible === this.localWeatherVisible) return;
    this.localWeatherVisible = visible;
    this.renderer.visible = visible;
    // Clear old outdoor particles immediately when entering shelter. Without
    // this, long-lived flakes remain inside the cave for several seconds.
    for (const layer of this.allLayers()) layer.system.restart();
  }

  public setPrecipitationOcclusionSampler(
    sampler: PrecipitationOcclusionSampler | undefined,
  ): void {
    this.precipitationOcclusionSampler = sampler;
  }

  public setIntensity(intensity: number): void {
    this.intensity = clamp(intensity, 0, 1);
  }

  public setBlowingSnowIntensity(windMultiplier: number): void {
    this.blowingSnowIntensity = clamp(
      (windMultiplier - 1.02) / 0.48,
      0,
      1,
    );
  }

  public triggerGust(strength: number, duration: number): void {
    this.gustStrength = Math.max(
      this.gustStrength,
      clamp(strength, 0, 1),
    );
    this.gustRemaining = Math.max(
      this.gustRemaining,
      clamp(duration, 0.5, 12),
    );
  }

  public toggleWindStreaksVisible(): boolean {
    this.windStreaksVisible = !this.windStreaksVisible;
    return this.windStreaksVisible;
  }

  public areWindStreaksVisible(): boolean {
    return this.windStreaksVisible;
  }

  public update(
    deltaSeconds: number,
    camera: Camera,
    windX: number,
    windZ: number,
    windStrength: number,
    characterView = false,
    focus?: Readonly<{ x: number; y?: number; z: number }>,
  ): void {
    const volumeView = characterView || camera instanceof PerspectiveCamera;
    if (volumeView !== this.volumeViewActive) {
      this.volumeViewActive = volumeView;
      for (const layer of this.allLayers()) layer.system.restart();
    }
    const strength = clamp(windStrength, 0, 2);
    if (this.gustRemaining > 0) {
      this.gustRemaining = Math.max(
        0,
        this.gustRemaining - deltaSeconds,
      );
    } else {
      this.gustStrength *= Math.exp(-deltaSeconds * 2.4);
      if (this.gustStrength < 0.002) this.gustStrength = 0;
    }
    const visibleWindIntensity = clamp(
      this.blowingSnowIntensity + this.gustStrength * 0.55,
      0,
      1,
    );
    // Wind is a visible part of snowfall, not just a slow positional drift.
    // The shared gust envelope modulates the slant without changing the
    // deterministic forecast direction.
    const acceleration =
      (0.38 + this.intensity * 0.62) *
      strength *
      (0.72 + this.gustStrength * 0.65);
    const visibleRate = this.localWeatherVisible
      ? Math.pow(this.intensity, 0.82)
      : 0;
    for (const layer of [
      this.far,
      this.near,
      this.characterFar,
      this.characterNear,
    ]) {
      layer.forceX.value = windX * acceleration;
      layer.forceZ.value = windZ * acceleration;
    }

    if (volumeView) {
      this.far.emission.value = 0;
      this.near.emission.value = 0;
      camera.updateMatrixWorld();
      if (focus) {
        const focusY = focus.y ?? 0;
        this.volumeNearCenter.set(
          focus.x,
          focusY + this.characterNear.spawnHeight,
          focus.z,
        );
        this.volumeFarCenter.set(
          focus.x,
          focusY + this.characterFar.spawnHeight,
          focus.z,
        );
      } else {
        this.volumeNearCenter.copy(camera.position);
        this.volumeNearCenter.y += this.characterNear.spawnHeight;
        this.volumeFarCenter.copy(camera.position);
        this.volumeFarCenter.y += this.characterFar.spawnHeight;
      }
      this.characterNear.system.emitter.position.copy(this.volumeNearCenter);
      this.characterFar.system.emitter.position.copy(this.volumeFarCenter);
      this.characterNear.emission.value = visibleRate * 305;
      this.characterFar.emission.value = visibleRate * 248;
      // Flat stretched streaks reveal the emitter plane in a close camera.
      // Wind still influences every volumetric flake in character view.
      this.wind.emission.value = 0;
    } else if (camera instanceof OrthographicCamera) {
      this.characterNear.emission.value = 0;
      this.characterFar.emission.value = 0;
      const coverage = calculateWeatherCoverage(camera);
      this.cameraUp
        .set(0, 1, 0)
        .applyQuaternion(camera.quaternion);
      const viewWidth =
        (camera.right - camera.left) / camera.zoom;
      const viewHeight =
        (camera.top - camera.bottom) / camera.zoom;
      calculateWeatherSpawnCenter(
        camera,
        coverage,
        viewHeight * 0.59 + 3,
        0,
        this.snowSpawnCenter,
      );
      const areaScale = clamp(viewWidth / 54, 1, 2.4);
      this.far.emission.value = visibleRate * areaScale * 48;
      this.near.emission.value = visibleRate * areaScale * 28;
      this.far.shape.width = viewWidth * 1.3;
      this.far.shape.height = 6;
      this.near.shape.width = viewWidth * 1.24;
      this.near.shape.height = 5;
      for (const layer of [this.far, this.near]) {
        layer.system.emitter.position.copy(this.snowSpawnCenter);
        layer.system.emitter.quaternion.copy(camera.quaternion);
      }
      this.wind.system.emitter.position.x = coverage.centerX;
      this.wind.system.emitter.position.z = coverage.centerZ;
      this.wind.shape.width = coverage.width;
      this.wind.shape.height = coverage.depth;
      this.wind.emission.value =
        this.localWeatherVisible && this.windStreaksVisible
          ? visibleWindIntensity * (38 + areaScale * 18)
          : 0;
    } else {
      this.far.emission.value = 0;
      this.near.emission.value = 0;
      this.characterNear.emission.value = 0;
      this.characterFar.emission.value = 0;
      this.wind.emission.value = 0;
    }
    const windAcceleration =
      (2.8 + strength * 2.4) *
      (0.5 + visibleWindIntensity * 0.5);
    this.wind.forceX.value = windX * windAcceleration;
    this.wind.forceZ.value = windZ * windAcceleration;
    this.renderer.update(clamp(deltaSeconds, 0, 0.1));
  }

  public getActiveParticleCount(): number {
    return this.near.system.particleNum + this.far.system.particleNum +
      this.characterNear.system.particleNum +
      this.characterFar.system.particleNum;
  }

  public getActiveWindParticleCount(): number {
    return this.wind.system.particleNum;
  }

  public dispose(): void {
    for (const layer of this.allLayers()) {
      this.renderer.deleteSystem(layer.system);
      this.scene.remove(layer.system.emitter);
      layer.system.dispose();
    }
    this.scene.remove(this.renderer);
    for (const batch of this.renderer.batches) batch.dispose();
    this.material.dispose();
    this.texture.dispose();
    this.windMaterial.dispose();
    this.windTexture.dispose();
  }

  private allLayers(): readonly (
    SnowLayer | CharacterSnowLayer | WindLayer
  )[] {
    return [
      this.near,
      this.far,
      this.characterNear,
      this.characterFar,
      this.wind,
    ];
  }

  private createLayer(options: {
    width: number;
    depth: number;
    height: number;
    lifeMin: number;
    lifeMax: number;
    sizeMin: number;
    sizeMax: number;
    alphaMin: number;
    alphaMax: number;
    gravity: number;
  }): SnowLayer {
    const emission = new ConstantValue(0);
    const forceX = new ConstantValue(0);
    const forceZ = new ConstantValue(0);
    const shape = new RectangleEmitter({
      width: options.width,
      height: options.depth,
      thickness: 1,
    });
    const system = new ParticleSystem({
      looping: true,
      duration: 12,
      worldSpace: true,
      shape,
      startLife: new IntervalValue(options.lifeMin, options.lifeMax),
      startSpeed: new IntervalValue(0.015, 0.075),
      startRotation: new IntervalValue(0, Math.PI * 2),
      startSize: new IntervalValue(options.sizeMin, options.sizeMax),
      startColor: new ColorRange(
        new ParticleColor(0.88, 0.96, 1, options.alphaMin),
        new ParticleColor(1, 1, 1, options.alphaMax),
      ),
      emissionOverTime: emission,
      behaviors: [
        new ForceOverLife(
          forceX,
          new ConstantValue(options.gravity),
          forceZ,
        ),
        new ColorOverLife(
          new Gradient(
            undefined,
            [
              [0, 0],
              [1, 0.08],
              [1, 0.94],
              [0, 1],
            ],
          ),
        ),
      ],
      material: this.material,
      renderMode: RenderMode.BillBoard,
      renderOrder: 7,
    });
    system.emitter.name = 'Snowfall emitter';
    system.emitter.position.y = options.height;
    this.scene.add(system.emitter);
    this.renderer.addSystem(system);
    return { system, emission, forceX, forceZ, shape };
  }

  private createCharacterLayer(options: {
    width: number;
    depth: number;
    spawnHeight: number;
    lifeMin: number;
    lifeMax: number;
    sizeMin: number;
    sizeMax: number;
    alphaMin: number;
    alphaMax: number;
    gravity: number;
  }): CharacterSnowLayer {
    const emission = new ConstantValue(0);
    const forceX = new ConstantValue(0);
    const forceZ = new ConstantValue(0);
    const shape = new RectangleEmitter({
      width: options.width,
      height: options.depth,
      thickness: 1,
    });
    const system = new ParticleSystem({
      looping: true,
      prewarm: true,
      duration: 12,
      worldSpace: true,
      shape,
      startLife: new IntervalValue(options.lifeMin, options.lifeMax),
      // SphereEmitter derives its initial velocity from the spawn radius.
      // Keep it nearly zero so gravity and wind, rather than radial spray,
      // own the visible motion.
      startSpeed: new IntervalValue(0.001, 0.012),
      startRotation: new IntervalValue(0, Math.PI * 2),
      startSize: new IntervalValue(options.sizeMin, options.sizeMax),
      startColor: new ColorRange(
        new ParticleColor(0.88, 0.96, 1, options.alphaMin),
        new ParticleColor(1, 1, 1, options.alphaMax),
      ),
      emissionOverTime: emission,
      behaviors: [
        new ForceOverLife(
          forceX,
          new ConstantValue(options.gravity),
          forceZ,
        ),
        new ColorOverLife(
          new Gradient(
            undefined,
            [
              [0, 0],
              [1, 0.08],
              [1, 0.9],
              [0, 1],
            ],
          ),
        ),
        new PrecipitationOcclusionBehavior(
          () => this.precipitationOcclusionSampler,
        ),
      ],
      material: this.material,
      renderMode: RenderMode.BillBoard,
      renderOrder: 7,
    });
    system.emitter.name = 'Wide character snowfall volume emitter';
    // Emit from a broad horizontal sky sheet. Gravity fills the entire space
    // below it, so orbiting cannot reveal a camera-facing particle plane.
    system.emitter.rotation.x = -Math.PI / 2;
    this.scene.add(system.emitter);
    this.renderer.addSystem(system);
    return {
      system,
      emission,
      forceX,
      forceZ,
      shape,
      spawnHeight: options.spawnHeight,
    };
  }

  private createWindLayer(): WindLayer {
    const emission = new ConstantValue(0);
    const forceX = new ConstantValue(0);
    const forceZ = new ConstantValue(0);
    const shape = new RectangleEmitter({
      width: 100,
      height: 80,
      thickness: 1,
    });
    const system = new ParticleSystem({
      looping: true,
      duration: 4,
      worldSpace: true,
      shape,
      startLife: new IntervalValue(0.7, 1.35),
      startSpeed: new IntervalValue(0.03, 0.1),
      startRotation: new IntervalValue(0, Math.PI * 2),
      startSize: new IntervalValue(0.045, 0.09),
      startColor: new ColorRange(
        new ParticleColor(0.65, 0.9, 0.94, 0.3),
        new ParticleColor(0.92, 1, 1, 0.62),
      ),
      emissionOverTime: emission,
      behaviors: [
        new ForceOverLife(
          forceX,
          new ConstantValue(0.015),
          forceZ,
        ),
      ],
      material: this.windMaterial,
      renderMode: RenderMode.StretchedBillBoard,
      rendererEmitterSettings: {
        speedFactor: 1.8,
        lengthFactor: 6.2,
      },
      renderOrder: 7,
    });
    system.emitter.name = 'Visible wind streak emitter';
    system.emitter.position.y = 7;
    system.emitter.rotation.x = -Math.PI / 2;
    this.scene.add(system.emitter);
    this.renderer.addSystem(system);
    return {
      system,
      emission,
      forceX,
      forceZ,
      shape,
    };
  }
}
