import {
  Color,
  DodecahedronGeometry,
  DynamicDrawUsage,
  InstancedMesh,
  MeshStandardMaterial,
  Object3D,
  Vector3,
  type Scene,
} from 'three';
import { clamp, hash2D } from '../utils/math';

export type LandSnowPresentationMode = 'V3' | 'V4';

export type LandSnowV4FlowKind =
  | 'PLOW'
  | 'THROWER'
  | 'WADE'
  | 'SNOWBOARD'
  | 'ROTOR';

export interface LandSnowV4FlowStamp {
  readonly id: number;
  readonly kind: LandSnowV4FlowKind;
  readonly x: number;
  readonly z: number;
  readonly heading: number;
  readonly width: number;
  readonly intensity: number;
  readonly castSide: -1 | 0 | 1;
  /** Relative moved mass multiplied by motion when the stamp was emitted. */
  readonly flowEnergy?: number;
  /** Optional for backwards-compatible V1 saves. */
  readonly ageSeconds?: number;
}

export interface LandSnowV4SaveData {
  readonly version: 1;
  readonly residualStamps: readonly LandSnowV4FlowStamp[];
}

export interface LandSnowV4Stats {
  readonly mode: LandSnowPresentationMode;
  readonly residualStamps: number;
  readonly activeFlowStamps: number;
  readonly visibleSurfaceClumps: number;
  readonly visibleAirborneClumps: number;
  readonly lastSurfaceRebuildMs: number;
  readonly maximumSurfaceRebuildMs: number;
  readonly surfaceRebuilds: number;
  readonly workErasedStamps: number;
}

interface ActiveFlowStamp extends LandSnowV4FlowStamp {
  ageSeconds: number;
}

interface PersistentFlowStamp extends LandSnowV4FlowStamp {
  readonly createdAtSeconds: number;
}

export interface RecordSnowV4FlowInput {
  readonly kind: LandSnowV4FlowKind;
  readonly x: number;
  readonly z: number;
  readonly heading: number;
  readonly width: number;
  readonly intensity: number;
  readonly castSide?: -1 | 0 | 1;
  readonly massFactor?: number;
  readonly speedMetresPerSecond?: number;
}

export interface LandSnowV4WorkFootprint {
  /** Centre of the blade, bucket mouth or intake in world space. */
  readonly x: number;
  readonly z: number;
  readonly heading: number;
  /** Tool width across its local right axis. */
  readonly width: number;
  /** Contact depth along its local forward axis. */
  readonly depth: number;
  /** New flow survives its own tool pass, then becomes reworkable. */
  readonly minimumStampAgeSeconds?: number;
}

const MODE_STORAGE_KEY = 'iceway.land-snow-presentation';
const MAX_RESIDUAL_STAMPS = 2_048;
const MAX_ACTIVE_STAMPS = 72;
const MAX_SURFACE_CLUMPS = 768;
const MAX_AIRBORNE_CLUMPS = 160;
const SURFACE_FULL_DETAIL_DISTANCE = 22;
const SURFACE_FADE_START_DISTANCE = 48;
const SURFACE_FADE_END_DISTANCE = 64;
const AIRBORNE_DETAIL_DISTANCE = 22;
const SURFACE_UPDATE_INTERVAL_SECONDS = 1 / 12;
const SURFACE_FULL_SHAPE_SECONDS = 300;
const SURFACE_SETTLE_END_SECONDS = 900;
const FLOW_LIFETIME_SECONDS = 2.4;
const PLOW_FLOW_REWORK_GRACE_SECONDS = 1.15;
const SURFACE_SUPPORT_SETTLE_GRACE_SECONDS = 1.05;

/**
 * Converts authoritative moved snow into optional V4 flow detail. A lowered
 * blade still shaves a few millimetres from a visually clear road, but that
 * residual must not create full-sized clumps or a plowing plume.
 */
export const resolveVisiblePlowFlowIntensity = (
  removedSnow: number,
  changedSamples: number,
  toolWidth: number,
  gain: number,
): number => {
  if (removedSnow <= 0 || changedSamples <= 0) return 0;
  const averageCutDepth = removedSnow / changedSamples;
  // changedSamples covers the broad source, front wave and side banks. A
  // genuine starter-plough pass consequently averages about 4–8 mm per
  // touched sample even while moving a large visible mass. Keep a sub-3 mm
  // residual shave invisible without suppressing normal ploughing entirely.
  const depthVisibility = clamp((averageCutDepth - 0.0028) / 0.0065, 0, 1);
  const massFloor = Math.max(0.004, Math.max(0.5, toolWidth) * 0.002);
  const massVisibility = clamp(
    (removedSnow - massFloor) / Math.max(0.008, massFloor * 3),
    0,
    1,
  );
  return clamp(
    removedSnow * Math.max(0, gain) * depthVisibility * massVisibility,
    0,
    1,
  );
};

const validKind = (input: unknown): input is LandSnowV4FlowKind =>
  input === 'PLOW' || input === 'THROWER' || input === 'WADE' ||
  input === 'SNOWBOARD' || input === 'ROTOR';

const readStoredMode = (): LandSnowPresentationMode => {
  if (typeof window === 'undefined') return 'V4';
  return window.localStorage.getItem(MODE_STORAGE_KEY) === 'V3' ? 'V3' : 'V4';
};

/**
 * Optional, non-authoritative near-snow presentation. The V3 field remains
 * the sole source of mass and can be shown instantly by disabling this root.
 */
export class LandSnowV4DetailSystem {
  private readonly root = new Object3D();
  private readonly surfaceGeometry = new DodecahedronGeometry(1, 0);
  private readonly airborneGeometry = new DodecahedronGeometry(1, 0);
  private readonly surfaceMaterial = new MeshStandardMaterial({
    color: new Color(0xf1fbfb),
    roughness: 0.98,
    metalness: 0,
  });
  private readonly airborneMaterial = new MeshStandardMaterial({
    color: new Color(0xf7ffff),
    roughness: 1,
    metalness: 0,
    transparent: true,
    opacity: 0.72,
    depthWrite: false,
  });
  private readonly surfaceMesh = new InstancedMesh(
    this.surfaceGeometry,
    this.surfaceMaterial,
    MAX_SURFACE_CLUMPS,
  );
  private readonly airborneMesh = new InstancedMesh(
    this.airborneGeometry,
    this.airborneMaterial,
    MAX_AIRBORNE_CLUMPS,
  );
  private readonly residualStamps: PersistentFlowStamp[] = [];
  private readonly activeStamps: ActiveFlowStamp[] = [];
  private readonly surfaceClumpSupportHeights = new Map<string, number>();
  private readonly transform = new Object3D();
  private readonly lastSurfaceFocus = new Vector3(
    Number.POSITIVE_INFINITY,
    0,
    Number.POSITIVE_INFINITY,
  );
  private nextId = 1;
  private timelineSeconds = 0;
  private surfaceUpdateAccumulator = SURFACE_UPDATE_INTERVAL_SECONDS;
  private nextPruneSeconds = 10;
  private mode: LandSnowPresentationMode = readStoredMode();
  private visible = false;
  private visibleSurfaceClumps = 0;
  private visibleAirborneClumps = 0;
  private lastSurfaceRebuildMs = 0;
  private maximumSurfaceRebuildMs = 0;
  private surfaceRebuilds = 0;
  private shaderWarmupActive = false;
  private workErasedStamps = 0;
  private dynamicExclusionSampler?: (x: number, z: number) => boolean;

  public constructor(scene: Scene) {
    this.root.name = 'Snow V4 optional local detail';
    this.surfaceMesh.name = 'Snow V4 pooled surface clumps';
    this.airborneMesh.name = 'Snow V4 pooled airborne clumps';
    this.surfaceMesh.instanceMatrix.setUsage(DynamicDrawUsage);
    this.airborneMesh.instanceMatrix.setUsage(DynamicDrawUsage);
    this.surfaceMesh.castShadow = true;
    this.surfaceMesh.receiveShadow = true;
    this.airborneMesh.castShadow = false;
    this.airborneMesh.receiveShadow = false;
    this.surfaceMesh.frustumCulled = false;
    this.airborneMesh.frustumCulled = false;
    this.root.add(this.surfaceMesh, this.airborneMesh);
    this.root.visible = false;
    scene.add(this.root);
    this.clearInstances();
  }

  public getMode(): LandSnowPresentationMode {
    return this.mode;
  }

  public isEnabled(): boolean {
    return this.mode === 'V4';
  }

  public setMode(mode: LandSnowPresentationMode): void {
    this.mode = mode;
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(MODE_STORAGE_KEY, mode);
    }
    this.root.visible = this.shaderWarmupActive ||
      (this.visible && mode === 'V4');
    if (mode === 'V3') this.clearInstances();
  }

  public toggleMode(): LandSnowPresentationMode {
    this.setMode(this.mode === 'V4' ? 'V3' : 'V4');
    return this.mode;
  }

  public setVisible(visible: boolean): void {
    this.visible = visible;
    this.root.visible = this.shaderWarmupActive ||
      (visible && this.mode === 'V4');
  }

  /** Keeps optional clumps out of dynamic holes carved in the V3 surface. */
  public setDynamicExclusionSampler(
    sampler: ((x: number, z: number) => boolean) | undefined,
  ): void {
    this.dynamicExclusionSampler = sampler;
    this.surfaceUpdateAccumulator = SURFACE_UPDATE_INTERVAL_SECONDS;
  }

  /** Gives both opaque and airborne V4 materials one hidden loading-frame. */
  public setShaderWarmupActive(
    active: boolean,
    x = 0,
    z = 0,
    surfaceY = 0,
  ): void {
    this.shaderWarmupActive = active;
    if (active) {
      this.writeInstance(
        this.surfaceMesh,
        0,
        x,
        surfaceY + 0.08,
        z,
        0.12,
        0.07,
        0.14,
        0,
      );
      this.writeInstance(
        this.airborneMesh,
        0,
        x,
        surfaceY + 0.5,
        z,
        0.08,
        0.08,
        0.08,
        0,
      );
      this.surfaceMesh.count = 1;
      this.airborneMesh.count = 1;
      this.surfaceMesh.instanceMatrix.needsUpdate = true;
      this.airborneMesh.instanceMatrix.needsUpdate = true;
    } else if (!active) {
      this.clearInstances();
    }
    this.root.visible = this.shaderWarmupActive ||
      (this.visible && this.mode === 'V4');
  }

  public recordFlow(input: Readonly<RecordSnowV4FlowInput>): void {
    if (
      !this.isEnabled() ||
      ![input.x, input.z, input.heading, input.width, input.intensity]
        .every(Number.isFinite) ||
      input.intensity <= 0.0001
    ) return;
    // Two-sided wading deliberately emits a left and a right stamp at the
    // same position. Compare against a few recent stamps of the same side,
    // not only the final array item, so those sides neither suppress each
    // other nor emit at simulation frequency while the actor stands still.
    const minimumTravel = input.kind === 'WADE'
      ? clamp(input.width * 0.55, 0.36, 0.72)
      : input.kind === 'PLOW'
        ? clamp(input.width * 0.28, 0.42, 1.05)
        : input.kind === 'THROWER'
          ? clamp(input.width * 0.25, 0.28, 0.72)
          : clamp(input.width * 0.18, 0.14, 0.48);
    const minimumAge = input.kind === 'WADE'
      ? 0.42
      : input.kind === 'PLOW'
        ? 0.18
        : input.kind === 'THROWER'
          ? 0.2
          : 0.11;
    for (
      let index = this.activeStamps.length - 1;
      index >= Math.max(0, this.activeStamps.length - 8);
      index -= 1
    ) {
      const recent = this.activeStamps[index]!;
      if (
        recent.kind === input.kind &&
        recent.castSide === (input.castSide ?? 0) &&
        Math.hypot(recent.x - input.x, recent.z - input.z) <
          minimumTravel &&
        recent.ageSeconds < minimumAge
      ) return;
    }
    const stamp: ActiveFlowStamp = {
      id: this.nextId++,
      kind: input.kind,
      x: input.x,
      z: input.z,
      heading: input.heading,
      width: clamp(input.width, 0.18, 8),
      intensity: clamp(input.intensity, 0.04, 1),
      castSide: input.castSide ?? 0,
      flowEnergy: clamp(
        clamp(input.intensity, 0.04, 1) *
          clamp(input.massFactor ?? defaultMassFactor(input.kind), 0.05, 2) *
          (0.72 + clamp(input.speedMetresPerSecond ?? 0, 0, 6) * 0.18),
        0.01,
        1.2,
      ),
      ageSeconds: 0,
    };
    this.activeStamps.push(stamp);
    if (this.activeStamps.length > MAX_ACTIVE_STAMPS) this.activeStamps.shift();
    const residual: PersistentFlowStamp = {
      id: stamp.id,
      kind: stamp.kind,
      x: Math.round(stamp.x * 8) / 8,
      z: Math.round(stamp.z * 8) / 8,
      heading: Math.round(stamp.heading * 128) / 128,
      width: Math.round(stamp.width * 8) / 8,
      intensity: Math.round(stamp.intensity * 255) / 255,
      castSide: stamp.castSide,
      flowEnergy: stamp.flowEnergy,
      createdAtSeconds: this.timelineSeconds,
    };
    // Consecutive passes over the same bank refresh one persistent clump
    // stamp instead of exhausting a short FIFO. This keeps both sides of a
    // road intact while remaining bounded for long sessions.
    let mergedIndex = -1;
    // A wide merge radius made the newest residual replace and move the
    // previous one, so a wading clump visibly followed the penguin and a slow
    // plough could drag its bank along. Merge only genuinely overlapping
    // footprints; forward progress always leaves a new stationary stamp.
    const mergeDistance = residual.kind === 'WADE'
      ? 0.055
      : clamp(residual.width * 0.065, 0.08, 0.2);
    for (
      let index = this.residualStamps.length - 1;
      index >= Math.max(0, this.residualStamps.length - 192);
      index -= 1
    ) {
      const candidate = this.residualStamps[index]!;
      if (
        candidate.kind === residual.kind &&
        candidate.castSide === residual.castSide &&
        Math.cos(candidate.heading - residual.heading) > 0.82 &&
        Math.hypot(candidate.x - residual.x, candidate.z - residual.z) <
          mergeDistance
      ) {
        mergedIndex = index;
        break;
      }
    }
    if (mergedIndex >= 0) {
      const previous = this.residualStamps[mergedIndex]!;
      this.clearSupportForStamp(previous.id);
      this.residualStamps.splice(mergedIndex, 1);
      this.residualStamps.push({
        ...residual,
        id: previous.id,
        x: Math.round((previous.x * 0.35 + residual.x * 0.65) * 8) / 8,
        z: Math.round((previous.z * 0.35 + residual.z * 0.65) * 8) / 8,
      });
    } else {
      this.residualStamps.push(residual);
    }
    if (this.residualStamps.length > MAX_RESIDUAL_STAMPS) {
      const removed = this.residualStamps.splice(
        0,
        this.residualStamps.length - MAX_RESIDUAL_STAMPS,
      );
      for (const stamp of removed) this.clearSupportForStamp(stamp.id);
    }
  }

  /**
   * Invalidates only the presentation stamps touched by a physical snow
   * tool. V3 has already moved the authoritative mass; the next recordFlow
   * call emits a fresh V4 bank at its new location without double-counting.
   */
  public eraseWorkFootprint(
    input: Readonly<LandSnowV4WorkFootprint>,
  ): number {
    if (
      !this.isEnabled() ||
      ![
        input.x,
        input.z,
        input.heading,
        input.width,
        input.depth,
      ].every(Number.isFinite) ||
      input.width <= 0 ||
      input.depth <= 0
    ) return 0;
    const forwardX = Math.sin(input.heading);
    const forwardZ = Math.cos(input.heading);
    const rightX = Math.cos(input.heading);
    const rightZ = -Math.sin(input.heading);
    const halfWidth = input.width * 0.5;
    const halfDepth = input.depth * 0.5;
    const erasedIds = new Set<number>();
    for (const stamp of this.residualStamps) {
      const minimumAge = clamp(
        input.minimumStampAgeSeconds ?? (
          stamp.kind === 'PLOW' ? PLOW_FLOW_REWORK_GRACE_SECONDS : 0.32
        ),
        0,
        2,
      );
      if (this.timelineSeconds - stamp.createdAtSeconds < minimumAge) continue;
      // Most saved stamps are outside the local tool. Reject those before
      // evaluating their deterministic clump positions, keeping the pass
      // cheap even after a long ploughing session.
      const broadRadius = Math.hypot(halfWidth, halfDepth) +
        stamp.width * 1.2 + 1.5;
      if (Math.hypot(stamp.x - input.x, stamp.z - input.z) > broadRadius) {
        continue;
      }
      const count = this.surfaceClumpBaseCount(stamp);
      for (let index = 0; index < count; index += 1) {
        const position = this.surfaceClumpPosition(stamp, index);
        const offsetX = position.x - input.x;
        const offsetZ = position.z - input.z;
        const forward = offsetX * forwardX + offsetZ * forwardZ;
        const lateral = offsetX * rightX + offsetZ * rightZ;
        const radius = this.surfaceClumpRadius(stamp, index);
        if (
          Math.abs(forward) <= halfDepth + radius &&
          Math.abs(lateral) <= halfWidth + radius
        ) {
          erasedIds.add(stamp.id);
          break;
        }
      }
    }
    if (erasedIds.size === 0) return 0;
    const erased = this.removeStampsById(erasedIds);
    this.workErasedStamps += erased;
    this.surfaceUpdateAccumulator = SURFACE_UPDATE_INTERVAL_SECONDS;
    return erased;
  }

  public update(
    deltaSeconds: number,
    focus: Readonly<{ x: number; z: number }>,
    sampleSurfaceHeight: (x: number, z: number) => number,
    wind: Readonly<{ x: number; z: number; strength: number }> = {
      x: 1,
      z: 0,
      strength: 0,
    },
  ): void {
    const stepSeconds = clamp(deltaSeconds, 0, 0.1);
    this.timelineSeconds += stepSeconds;
    this.surfaceUpdateAccumulator += stepSeconds;
    for (const stamp of this.activeStamps) {
      stamp.ageSeconds += stepSeconds;
    }
    while (
      this.activeStamps.length > 0 &&
      this.activeStamps[0]!.ageSeconds > FLOW_LIFETIME_SECONDS
    ) this.activeStamps.shift();
    if (!this.root.visible) return;

    if (this.timelineSeconds >= this.nextPruneSeconds) {
      this.pruneSettledSurfaceStamps();
      this.nextPruneSeconds = this.timelineSeconds + 10;
    }
    const focusMoved = Math.hypot(
      focus.x - this.lastSurfaceFocus.x,
      focus.z - this.lastSurfaceFocus.z,
    ) > 1.5;
    if (
      this.surfaceUpdateAccumulator >= SURFACE_UPDATE_INTERVAL_SECONDS ||
      focusMoved
    ) {
      const rebuildStartedAt = performance.now();
      this.rebuildSurfaceClumps(focus, sampleSurfaceHeight);
      this.lastSurfaceRebuildMs = performance.now() - rebuildStartedAt;
      this.maximumSurfaceRebuildMs = Math.max(
        this.maximumSurfaceRebuildMs,
        this.lastSurfaceRebuildMs,
      );
      this.surfaceRebuilds += 1;
      this.surfaceUpdateAccumulator = 0;
      this.lastSurfaceFocus.set(focus.x, 0, focus.z);
    }

    let airborneIndex = 0;
    const windLength = Math.max(0.0001, Math.hypot(wind.x, wind.z));
    const windX = wind.x / windLength;
    const windZ = wind.z / windLength;
    for (const stamp of this.activeStamps) {
      if (stamp.ageSeconds > 1.55) continue;
      if (Math.hypot(stamp.x - focus.x, stamp.z - focus.z) > AIRBORNE_DETAIL_DISTANCE) {
        continue;
      }
      const life = stamp.ageSeconds / 1.55;
      const flowEnergy = clamp(stamp.flowEnergy ?? stamp.intensity, 0, 1.2);
      const count = stamp.kind === 'PLOW'
        ? 3
        : stamp.kind === 'THROWER'
          ? 1 + (flowEnergy > 0.38 ? 1 : 0)
        : stamp.kind === 'ROTOR'
          ? 4
          : stamp.kind === 'WADE'
            ? 0
            : flowEnergy > 0.18 ? 1 : 0;
      for (let index = 0; index < count && airborneIndex < MAX_AIRBORNE_CLUMPS; index += 1) {
        const seed = stamp.id * 11 + index;
        const cast = stamp.castSide === 0
          ? (hash2D(seed, 3, 61) < 0.5 ? -1 : 1)
          : stamp.castSide;
        const forwardX = Math.sin(stamp.heading);
        const forwardZ = Math.cos(stamp.heading);
        const rightX = Math.cos(stamp.heading);
        const rightZ = -Math.sin(stamp.heading);
        const sideTravel = cast * stamp.width * (0.35 + life * 1.25);
        const forwardTravel = (hash2D(seed, 7, 67) - 0.3) *
          (0.35 + life * 0.9);
        const x = stamp.x + rightX * sideTravel + forwardX * forwardTravel +
          windX * life * clamp(wind.strength, 0, 2.8) * 0.38;
        const z = stamp.z + rightZ * sideTravel + forwardZ * forwardTravel +
          windZ * life * clamp(wind.strength, 0, 2.8) * 0.38;
        const base = 0.055 + hash2D(seed, 13, 71) * 0.095;
        const energyScale = stamp.kind === 'PLOW'
          ? 1
          : 0.4 + Math.sqrt(clamp(flowEnergy, 0, 1)) * 0.6;
        const scale = base * (1 - life * 0.72) *
          (0.55 + stamp.intensity * 0.7) * energyScale;
        const y = sampleSurfaceHeight(x, z) + 0.12 +
          Math.sin(life * Math.PI) *
            (stamp.kind === 'THROWER' ? 0.72 : 0.36) +
          hash2D(seed, 17, 73) * 0.18;
        this.writeInstance(
          this.airborneMesh,
          airborneIndex++,
          x,
          y,
          z,
          scale * 1.3,
          scale,
          scale * 1.1,
          stamp.heading + life * 2.8,
        );
      }
    }
    this.airborneMesh.count = airborneIndex;
    this.visibleAirborneClumps = airborneIndex;
    if (airborneIndex > 0) this.airborneMesh.instanceMatrix.needsUpdate = true;
  }

  public exportState(): LandSnowV4SaveData {
    return {
      version: 1,
      residualStamps: this.residualStamps.map((stamp) => ({
        id: stamp.id,
        kind: stamp.kind,
        x: stamp.x,
        z: stamp.z,
        heading: stamp.heading,
        width: stamp.width,
        intensity: stamp.intensity,
        castSide: stamp.castSide,
        flowEnergy: stamp.flowEnergy,
        ageSeconds: Math.max(0, this.timelineSeconds - stamp.createdAtSeconds),
      })),
    };
  }

  public importState(input: unknown): boolean {
    if (!input || typeof input !== 'object') return false;
    const candidate = input as Partial<LandSnowV4SaveData>;
    if (candidate.version !== 1 || !Array.isArray(candidate.residualStamps)) {
      return false;
    }
    this.residualStamps.length = 0;
    this.activeStamps.length = 0;
    this.surfaceClumpSupportHeights.clear();
    this.workErasedStamps = 0;
    for (const raw of candidate.residualStamps.slice(-MAX_RESIDUAL_STAMPS)) {
      if (
        !raw ||
        !validKind(raw.kind) ||
        ![raw.id, raw.x, raw.z, raw.heading, raw.width, raw.intensity]
          .every(Number.isFinite)
      ) continue;
      const castSide = raw.castSide === -1 || raw.castSide === 1
        ? raw.castSide
        : 0;
      const savedAge = Number.isFinite(raw.ageSeconds)
        ? clamp(raw.ageSeconds ?? 0, 0, SURFACE_SETTLE_END_SECONDS)
        : 0;
      const stamp: PersistentFlowStamp = {
        id: Math.max(0, Math.floor(raw.id)),
        kind: raw.kind,
        x: clamp(raw.x, -1_000_000, 1_000_000),
        z: clamp(raw.z, -1_000_000, 1_000_000),
        heading: raw.heading,
        width: clamp(raw.width, 0.18, 8),
        intensity: clamp(raw.intensity, 0.04, 1),
        castSide,
        flowEnergy: Number.isFinite(raw.flowEnergy)
          ? clamp(raw.flowEnergy ?? 0, 0.01, 1.2)
          : clamp(
              clamp(raw.intensity, 0.04, 1) * defaultMassFactor(raw.kind),
              0.01,
              1.2,
            ),
        createdAtSeconds: this.timelineSeconds - savedAge,
      };
      this.residualStamps.push(stamp);
      this.nextId = Math.max(this.nextId, stamp.id + 1);
    }
    return true;
  }

  public getStats(): LandSnowV4Stats {
    return {
      mode: this.mode,
      residualStamps: this.residualStamps.length,
      activeFlowStamps: this.activeStamps.length,
      visibleSurfaceClumps: this.visibleSurfaceClumps,
      visibleAirborneClumps: this.visibleAirborneClumps,
      lastSurfaceRebuildMs: this.lastSurfaceRebuildMs,
      maximumSurfaceRebuildMs: this.maximumSurfaceRebuildMs,
      surfaceRebuilds: this.surfaceRebuilds,
      workErasedStamps: this.workErasedStamps,
    };
  }

  public dispose(): void {
    this.surfaceMesh.dispose();
    this.airborneMesh.dispose();
    this.surfaceGeometry.dispose();
    this.airborneGeometry.dispose();
    this.surfaceMaterial.dispose();
    this.airborneMaterial.dispose();
    this.root.removeFromParent();
  }

  private writeInstance(
    mesh: InstancedMesh,
    index: number,
    x: number,
    y: number,
    z: number,
    scaleX: number,
    scaleY: number,
    scaleZ: number,
    yaw: number,
  ): void {
    this.transform.position.set(x, y, z);
    this.transform.rotation.set(0, yaw, 0);
    this.transform.scale.set(scaleX, scaleY, scaleZ);
    this.transform.updateMatrix();
    mesh.setMatrixAt(index, this.transform.matrix);
  }

  private surfaceClumpBaseCount(
    stamp: Readonly<LandSnowV4FlowStamp>,
  ): number {
    return stamp.kind === 'PLOW' || stamp.kind === 'THROWER'
      ? stamp.kind === 'PLOW'
        ? 2
        : 1 + Math.round(clamp(stamp.flowEnergy ?? 0.2, 0, 1))
      : stamp.kind === 'SNOWBOARD'
        ? 2
        : stamp.kind === 'WADE'
          ? 1
          : 2;
  }

  private surfaceClumpPosition(
    stamp: Readonly<LandSnowV4FlowStamp>,
    index: number,
  ): Readonly<{ x: number; z: number }> {
    const sideRandom = hash2D(stamp.id, index, 7) * 2 - 1;
    const forwardRandom = hash2D(stamp.id, index, 19) * 2 - 1;
    const cast = stamp.castSide === 0
      ? (sideRandom < 0 ? -1 : 1)
      : stamp.castSide;
    // A plough bank belongs just beyond the physical blade tip. The former
    // 0.38-width minimum placed many clumps inside the blade footprint, so
    // its very next sweep erased the flow it had just emitted.
    const sideDistance = stamp.width * (
      stamp.kind === 'PLOW'
        ? 0.62 + hash2D(index, stamp.id, 29) * 0.2
        : 0.38 + hash2D(index, stamp.id, 29) * 0.42
    ) * cast;
    const forwardDistance = stamp.kind === 'WADE'
      ? 0.1 + (forwardRandom + 1) * 0.12
      : forwardRandom * (stamp.kind === 'THROWER' ? 1.2 : 0.48);
    const forwardX = Math.sin(stamp.heading);
    const forwardZ = Math.cos(stamp.heading);
    const rightX = Math.cos(stamp.heading);
    const rightZ = -Math.sin(stamp.heading);
    return {
      x: stamp.x + rightX * sideDistance + forwardX * forwardDistance,
      z: stamp.z + rightZ * sideDistance + forwardZ * forwardDistance,
    };
  }

  private surfaceClumpRadius(
    stamp: Readonly<LandSnowV4FlowStamp>,
    index: number,
  ): number {
    return clamp(
      (0.07 + hash2D(stamp.id, index, 43) * 0.13) *
        (0.55 + stamp.intensity * 0.72),
      0.025,
      0.24,
    ) * (stamp.kind === 'PLOW'
      ? 0.72
      : stamp.kind === 'WADE'
        ? 0.42 + Math.sqrt(clamp(stamp.flowEnergy ?? 0.2, 0, 1)) * 0.22
        : 0.4 + Math.sqrt(clamp(stamp.flowEnergy ?? 0.2, 0, 1)) * 0.38);
  }

  private clearSupportForStamp(id: number): void {
    const prefix = `${id}:`;
    for (const key of this.surfaceClumpSupportHeights.keys()) {
      if (key.startsWith(prefix)) this.surfaceClumpSupportHeights.delete(key);
    }
  }

  private removeStampsById(ids: ReadonlySet<number>): number {
    let removed = 0;
    let writeIndex = 0;
    for (const stamp of this.residualStamps) {
      if (ids.has(stamp.id)) {
        removed += 1;
        this.clearSupportForStamp(stamp.id);
        continue;
      }
      this.residualStamps[writeIndex++] = stamp;
    }
    this.residualStamps.length = writeIndex;
    let activeWriteIndex = 0;
    for (const stamp of this.activeStamps) {
      if (ids.has(stamp.id)) continue;
      this.activeStamps[activeWriteIndex++] = stamp;
    }
    this.activeStamps.length = activeWriteIndex;
    return removed;
  }

  private rebuildSurfaceClumps(
    focus: Readonly<{ x: number; z: number }>,
    sampleSurfaceHeight: (x: number, z: number) => number,
  ): void {
    let surfaceIndex = 0;
    const unsupportedStampIds = new Set<number>();
    for (
      let stampIndex = this.residualStamps.length - 1;
      stampIndex >= 0 && surfaceIndex < MAX_SURFACE_CLUMPS;
      stampIndex -= 1
    ) {
      const stamp = this.residualStamps[stampIndex]!;
      const distance = Math.hypot(stamp.x - focus.x, stamp.z - focus.z);
      if (distance > SURFACE_FADE_END_DISTANCE) continue;
      const distanceFade = 1 - clamp(
        (distance - SURFACE_FADE_START_DISTANCE) /
          (SURFACE_FADE_END_DISTANCE - SURFACE_FADE_START_DISTANCE),
        0,
        1,
      );
      const ageSeconds = Math.max(
        0,
        this.timelineSeconds - stamp.createdAtSeconds,
      );
      const settle = smoothStep01(
        (ageSeconds - SURFACE_FULL_SHAPE_SECONDS) /
          (SURFACE_SETTLE_END_SECONDS - SURFACE_FULL_SHAPE_SECONDS),
      );
      const supportCanSettle =
        ageSeconds < SURFACE_SUPPORT_SETTLE_GRACE_SECONDS;
      const baseCount = this.surfaceClumpBaseCount(stamp);
      let supported = true;
      for (let index = 0; index < baseCount; index += 1) {
        const position = this.surfaceClumpPosition(stamp, index);
        if (this.dynamicExclusionSampler?.(position.x, position.z)) continue;
        const height = sampleSurfaceHeight(position.x, position.z);
        const supportKey = `${stamp.id}:${index}`;
        const originalHeight = this.surfaceClumpSupportHeights.get(supportKey);
        if (originalHeight === undefined || supportCanSettle) {
          // While the authoritative bank is still receiving the same pass,
          // follow its changing support instead of treating growth as loss.
          this.surfaceClumpSupportHeights.set(supportKey, height);
        } else if (
          height < originalHeight - 0.11 ||
          height > originalHeight + 0.38
        ) {
          supported = false;
          break;
        }
      }
      if (!supported) {
        unsupportedStampIds.add(stamp.id);
        continue;
      }
      const count = distance <= SURFACE_FULL_DETAIL_DISTANCE
        ? baseCount
        : distance <= SURFACE_FADE_START_DISTANCE
          ? Math.min(2, baseCount)
          : 1;
      for (
        let index = 0;
        index < count && surfaceIndex < MAX_SURFACE_CLUMPS;
        index += 1
      ) {
        const sideRandom = hash2D(stamp.id, index, 7) * 2 - 1;
        const position = this.surfaceClumpPosition(stamp, index);
        const x = position.x;
        const z = position.z;
        if (this.dynamicExclusionSampler?.(x, z)) continue;
        const radius = this.surfaceClumpRadius(stamp, index) * distanceFade;
        if (radius < 0.006) continue;
        const settledWidth = 1 + settle * 0.32;
        const settledHeight = 1 - settle * 0.84;
        this.writeInstance(
          this.surfaceMesh,
          surfaceIndex++,
          x,
          sampleSurfaceHeight(x, z) +
            radius * (0.32 - settle * 0.38),
          z,
          radius * (1.15 + hash2D(index, stamp.id, 47) * 0.8) *
            settledWidth,
          radius * 0.52 * settledHeight,
          radius * (0.9 + hash2D(index, stamp.id, 53) * 0.7) *
            settledWidth,
          stamp.heading + sideRandom,
        );
      }
    }
    if (unsupportedStampIds.size > 0) {
      this.workErasedStamps += this.removeStampsById(unsupportedStampIds);
    }
    this.surfaceMesh.count = surfaceIndex;
    this.visibleSurfaceClumps = surfaceIndex;
    if (surfaceIndex > 0) this.surfaceMesh.instanceMatrix.needsUpdate = true;
  }

  private pruneSettledSurfaceStamps(): void {
    const oldestAllowed = this.timelineSeconds - SURFACE_SETTLE_END_SECONDS;
    let writeIndex = 0;
    for (const stamp of this.residualStamps) {
      if (stamp.createdAtSeconds <= oldestAllowed) {
        this.clearSupportForStamp(stamp.id);
        continue;
      }
      this.residualStamps[writeIndex++] = stamp;
    }
    this.residualStamps.length = writeIndex;
  }

  private clearInstances(): void {
    this.surfaceMesh.count = 0;
    this.airborneMesh.count = 0;
    this.visibleSurfaceClumps = 0;
    this.visibleAirborneClumps = 0;
  }
}

const smoothStep01 = (value: number): number => {
  const t = clamp(value, 0, 1);
  return t * t * (3 - 2 * t);
};

const defaultMassFactor = (kind: LandSnowV4FlowKind): number => {
  switch (kind) {
    case 'PLOW': return 1;
    case 'THROWER': return 0.34;
    case 'WADE': return 0.2;
    case 'SNOWBOARD': return 0.48;
    case 'ROTOR': return 0.78;
  }
};
