export const OCEAN_V3_DEBUG_VIEWS = [
  'final',
  'depth',
  'base-color',
  'macro-height',
  'macro-normal',
  'fresnel',
  'sky-response',
  'ice-foam',
  'bathymetry-depth',
  'shore-distance',
  'wave-exposure',
  'authored-override',
  'palette',
] as const;

export type OceanV3DebugView =
  (typeof OCEAN_V3_DEBUG_VIEWS)[number];

export interface OceanV3PaletteState {
  readonly deep: Color;
  readonly mid: Color;
  readonly shallow: Color;
  readonly light: Color;
}

export interface OceanV3PaletteContext {
  night: number;
  warmth: number;
  cloudCover: number;
}

const createPaletteColors = (
  source: Readonly<{
    deep: number;
    mid: number;
    shallow: number;
    light: number;
  }>,
): OceanV3PaletteState => ({
  deep: new Color(source.deep),
  mid: new Color(source.mid),
  shallow: new Color(source.shallow),
  light: new Color(source.light),
});

const DAY_PALETTE = createPaletteColors(
  OCEAN_V3_TUNING.palette.day,
);
const NIGHT_PALETTE = createPaletteColors(
  OCEAN_V3_TUNING.palette.night,
);
const EVENING_PALETTE = createPaletteColors(
  OCEAN_V3_TUNING.palette.evening,
);
const OVERCAST_PALETTE = createPaletteColors(
  OCEAN_V3_TUNING.palette.overcast,
);

export const createOceanV3PaletteState =
  (): OceanV3PaletteState => ({
    deep: new Color(),
    mid: new Color(),
    shallow: new Color(),
    light: new Color(),
  });

export const resolveOceanV3Palette = (
  context: Readonly<OceanV3PaletteContext>,
  target: OceanV3PaletteState = createOceanV3PaletteState(),
): OceanV3PaletteState => {
  const night = Math.max(0, Math.min(1, context.night));
  const warmth =
    Math.max(0, Math.min(1, context.warmth)) *
    (1 - night) *
    OCEAN_V3_TUNING.palette.eveningBlend;
  const overcast =
    Math.max(0, Math.min(1, context.cloudCover)) *
    OCEAN_V3_TUNING.palette.overcastBlend;
  const resolveColor = (
    output: Color,
    day: Color,
    nightColor: Color,
    evening: Color,
    covered: Color,
  ): void => {
    output
      .copy(day)
      .lerp(nightColor, night)
      .lerp(evening, warmth)
      .lerp(covered, overcast * (1 - night * 0.38));
  };

  resolveColor(
    target.deep,
    DAY_PALETTE.deep,
    NIGHT_PALETTE.deep,
    EVENING_PALETTE.deep,
    OVERCAST_PALETTE.deep,
  );
  resolveColor(
    target.mid,
    DAY_PALETTE.mid,
    NIGHT_PALETTE.mid,
    EVENING_PALETTE.mid,
    OVERCAST_PALETTE.mid,
  );
  resolveColor(
    target.shallow,
    DAY_PALETTE.shallow,
    NIGHT_PALETTE.shallow,
    EVENING_PALETTE.shallow,
    OVERCAST_PALETTE.shallow,
  );
  resolveColor(
    target.light,
    DAY_PALETTE.light,
    NIGHT_PALETTE.light,
    EVENING_PALETTE.light,
    OVERCAST_PALETTE.light,
  );
  return target;
};

const OCEAN_V3_DEBUG_VIEW_IDS: Readonly<
  Record<OceanV3DebugView, number>
> = Object.freeze(
  Object.fromEntries(
    OCEAN_V3_DEBUG_VIEWS.map((view, index) => [view, index]),
  ) as Record<OceanV3DebugView, number>,
);

export const getOceanV3DebugViewId = (
  view: OceanV3DebugView,
): number => OCEAN_V3_DEBUG_VIEW_IDS[view];

export class OceanV3DebugController {
  private view: OceanV3DebugView = 'final';

  public cycle(): OceanV3DebugView {
    const index = OCEAN_V3_DEBUG_VIEWS.indexOf(this.view);
    this.view =
      OCEAN_V3_DEBUG_VIEWS[
        (index + 1) % OCEAN_V3_DEBUG_VIEWS.length
      ] ?? 'final';
    return this.view;
  }

  public reset(): void {
    this.view = 'final';
  }

  public getView(): OceanV3DebugView {
    return this.view;
  }

  public getUniformValue(): number {
    return getOceanV3DebugViewId(this.view);
  }
}

const glslFloat = (value: number): string => value.toFixed(4);

export const createOceanV3FragmentContractGLSL = (
  iceCellSize: number,
): string => {
  const bathymetry = OCEAN_V3_TUNING.bathymetry;
  const dynamics = OCEAN_V3_TUNING.dynamics;
  const optics = OCEAN_V3_TUNING.optics;
  const interactions = OCEAN_V3_TUNING.interactions;

  return `
    const float OCEAN_V3_ICE_CELL_SIZE =
      ${glslFloat(iceCellSize)};
    const float OCEAN_V3_EDGE_WARP_SCALE =
      ${glslFloat(interactions.edgeWarpScale)};
    const float OCEAN_V3_EDGE_FOAM_MAX_BLEND =
      ${glslFloat(interactions.edgeFoamMaxBlend)};

    vec2 oceanV3BathymetryWorldToUv(vec2 worldPoint) {
      return worldPoint / uOceanBathymetryWorldSize + 0.5;
    }

    vec4 sampleOceanV3Bathymetry(vec2 worldPoint) {
      return texture2D(
        uOceanBathymetryMap,
        clamp(
          oceanV3BathymetryWorldToUv(worldPoint),
          0.0,
          1.0
        )
      );
    }

    float resolveOceanV3FinalDepth(
      float legacyDepth,
      float staticDepth,
      float staticBathymetryEnabled,
      float depthEnabled
    ) {
      return mix(
        ${glslFloat(bathymetry.neutralDepth)},
        mix(
          legacyDepth,
          staticDepth,
          staticBathymetryEnabled
        ),
        depthEnabled
      );
    }

    vec3 sampleOceanV3Dynamics(
      vec2 macroGradient,
      vec4 horizontalDerivatives
    ) {
      vec3 tangentX = vec3(
        1.0 + horizontalDerivatives.x,
        macroGradient.x,
        horizontalDerivatives.z
      );
      vec3 tangentZ = vec3(
        horizontalDerivatives.y,
        macroGradient.y,
        1.0 + horizontalDerivatives.w
      );
      return normalize(cross(tangentZ, tangentX));
    }

    vec3 applyOceanV3MacroShape(
      vec3 waterColor,
      float macroHeight,
      vec2 macroGradient,
      vec2 lightDirection,
      vec3 skyLightColor,
      float seaState
    ) {
      vec2 normalizedLightDirection = normalize(
        lightDirection + vec2(0.0001)
      );
      float heightSignal = clamp(
        macroHeight * ${glslFloat(dynamics.macroHeightGain)},
        -1.0,
        1.0
      );
      float directionalSlope = clamp(
        dot(macroGradient, normalizedLightDirection) *
          ${glslFloat(dynamics.macroDirectionalSlopeGain)},
        -1.0,
        1.0
      );
      float broadShape = clamp(
        heightSignal * 0.65 + directionalSlope * 0.35,
        -1.0,
        1.0
      );
      float seaStateBlend = smoothstep(
        0.08,
        0.92,
        clamp(seaState, 0.0, 1.0)
      );
      float contrast = mix(
        ${glslFloat(dynamics.macroCalmContrast)},
        ${glslFloat(dynamics.macroRoughContrast)},
        seaStateBlend
      );
      float highlight = max(broadShape, 0.0);
      float shadow = max(-broadShape, 0.0);
      vec3 shapedColor =
        waterColor *
        (
          1.0 +
          highlight * contrast -
          shadow *
            contrast *
            ${glslFloat(dynamics.macroShadowRatio)}
        );
      float slope = smoothstep(
        0.006,
        0.085,
        length(macroGradient)
      );
      float skyTint =
        highlight * ${glslFloat(dynamics.macroCrestTint)} +
        slope *
          seaStateBlend *
          ${glslFloat(dynamics.macroSlopeTint)};
      return mix(
        shapedColor,
        skyLightColor,
        clamp(skyTint, 0.0, 0.12)
      );
    }

    float resolveOceanV3CrestMask(
      float crestPotential,
      vec2 macroGradient,
      float curvature,
      float compression,
      float seaState,
      vec2 worldPoint
    ) {
      float curvatureSignal = smoothstep(
        ${glslFloat(dynamics.crestCurvatureStart)},
        ${glslFloat(dynamics.crestCurvatureEnd)},
        curvature
      );
      float compressionSignal = smoothstep(
        ${glslFloat(dynamics.crestCompressionStart)},
        ${glslFloat(dynamics.crestCompressionEnd)},
        compression
      );
      float crestSlope = 1.0 - smoothstep(
        ${glslFloat(dynamics.crestSlopeStart)},
        ${glslFloat(dynamics.crestSlopeEnd)},
        length(macroGradient)
      );
      float structuralCrest =
        mix(
          0.64,
          1.0,
          max(curvatureSignal, compressionSignal)
        ) *
        mix(0.64, 1.0, crestSlope);
      float breakup =
        noise21(worldPoint * 0.41 + vec2(7.3, -11.8)) * 0.64 +
        noise21(worldPoint * 0.93 + vec2(-19.2, 3.7)) * 0.36;
      float brokenCrest =
        crestPotential *
        structuralCrest *
        mix(0.7, 1.16, breakup);
      float antialiasWidth = max(fwidth(brokenCrest), 0.008);
      float crestMask = smoothstep(
        0.66 - antialiasWidth,
        0.79 + antialiasWidth,
        brokenCrest
      );
      return crestMask * smoothstep(
        0.16,
        0.78,
        clamp(seaState, 0.0, 1.0)
      );
    }

    vec3 applyOceanV3SurfaceLighting(
      vec3 waterColor,
      vec3 macroNormal,
      vec3 viewDirection,
      vec3 sunDirection,
      vec3 moonDirection,
      vec3 sunColor,
      vec3 moonColor,
      float sunIntensity,
      float moonIntensity,
      float seaState
    ) {
      vec2 sunAzimuth = normalize(
        sunDirection.xz + vec2(0.0001)
      );
      vec2 moonAzimuth = normalize(
        moonDirection.xz + vec2(0.0001)
      );
      float sunShape = -dot(
        macroNormal.xz,
        sunAzimuth
      );
      float moonShape = -dot(
        macroNormal.xz,
        moonAzimuth
      );
      float moonDominance = smoothstep(
        sunIntensity * 0.86,
        sunIntensity * 1.14 + 0.0001,
        moonIntensity
      );
      float normalShape = mix(
        sunShape,
        moonShape,
        moonDominance
      );
      float contrast = mix(
        ${glslFloat(dynamics.normalLightCalmContrast)},
        ${glslFloat(dynamics.normalLightRoughContrast)},
        smoothstep(0.1, 0.9, seaState)
      );
      waterColor *=
        1.0 +
        max(normalShape, 0.0) * contrast -
        max(-normalShape, 0.0) *
          contrast *
          ${glslFloat(dynamics.normalLightShadowRatio)};

      vec3 sunHalf = normalize(sunDirection + viewDirection);
      vec3 moonHalf = normalize(moonDirection + viewDirection);
      float specularPower = mix(72.0, 34.0, seaState);
      float broadSpecular = mix(
        ${glslFloat(dynamics.broadSpecularCalm)},
        ${glslFloat(dynamics.broadSpecularRough)},
        seaState
      );
      float sunSpecular = pow(
        max(dot(macroNormal, sunHalf), 0.0),
        specularPower
      );
      float moonSpecular = pow(
        max(dot(macroNormal, moonHalf), 0.0),
        specularPower * 1.35
      );
      waterColor +=
        sunColor *
        sunSpecular *
        sunIntensity *
        broadSpecular;
      waterColor +=
        moonColor *
        moonSpecular *
        moonIntensity *
        broadSpecular *
        0.72;
      return waterColor;
    }

    vec3 applyOceanV3CrestFoam(
      vec3 waterColor,
      vec3 foamColor,
      float crestMask,
      float seaState
    ) {
      float foamBlend = crestMask * mix(
        ${glslFloat(dynamics.crestFoamCalmBlend)},
        ${glslFloat(dynamics.crestFoamRoughBlend)},
        smoothstep(0.18, 0.9, seaState)
      );
      return mix(
        waterColor,
        foamColor,
        clamp(foamBlend, 0.0, 0.2)
      );
    }

    vec3 applyOceanV3CrestReflection(
      vec3 waterColor,
      vec3 skyColor,
      float crestPotential,
      float seaState,
      vec2 worldPoint
    ) {
      float crestRidge = smoothstep(
        0.36,
        0.68,
        crestPotential
      );
      float reflectionBreakup = mix(
        0.68,
        1.0,
        noise21(worldPoint * 0.37 + vec2(5.2, -8.7))
      );
      float reflectionBlend =
        crestRidge *
        reflectionBreakup *
        mix(
          ${glslFloat(dynamics.crestReflectionCalmBlend)},
          ${glslFloat(dynamics.crestReflectionRoughBlend)},
          smoothstep(0.12, 0.88, seaState)
        );
      return mix(
        waterColor,
        skyColor,
        clamp(reflectionBlend, 0.0, 0.12)
      );
    }

    vec3 applyOceanV3Optics(
      float depthSample,
      vec2 worldPoint,
      vec3 shallowColor,
      vec3 midColor,
      vec3 deepColor,
      out vec3 paletteColor
    ) {
      float staticIrregularity =
        (
          noise21(
            worldPoint *
              ${glslFloat(optics.irregularityScale)} +
              vec2(7.31, -4.87)
          ) -
          0.5
        ) *
        ${glslFloat(optics.irregularityStrength)};
      float continuousDepth = clamp(
        depthSample + staticIrregularity,
        0.0,
        1.0
      );
      float shallowToMid = smoothstep(
        ${glslFloat(optics.shallowToMidStart)},
        ${glslFloat(optics.shallowToMidEnd)},
        continuousDepth
      );
      float midToDeep = smoothstep(
        ${glslFloat(optics.midToDeepStart)},
        ${glslFloat(optics.midToDeepEnd)},
        continuousDepth
      );
      paletteColor = mix(
        shallowColor,
        midColor,
        shallowToMid
      );
      vec3 absorbedColor = mix(
        paletteColor,
        deepColor,
        pow(midToDeep, ${glslFloat(optics.deepCurve)}) *
          ${glslFloat(optics.deepMix)}
      );
      float depthBrightness = mix(
        ${glslFloat(optics.shallowBrightness)},
        ${glslFloat(optics.deepBrightness)},
        smoothstep(0.0, 1.0, continuousDepth)
      );
      return absorbedColor * depthBrightness;
    }

    vec3 applyOceanV3Interactions(
      vec3 waterColor,
      vec3 interactionColor,
      float interactionStrength
    ) {
      return mix(
        waterColor,
        interactionColor,
        clamp(
          interactionStrength,
          0.0,
          OCEAN_V3_EDGE_FOAM_MAX_BLEND
        )
      );
    }

    vec3 resolveOceanV3DebugOutput(
      float outputMode,
      vec3 finalColor,
      float depthSample,
      vec4 bathymetryData,
      vec3 paletteColor,
      vec3 baseColor,
      float macroHeight,
      vec3 macroNormal,
      float fresnel,
      vec3 skyResponse,
      float iceFoam
    ) {
      if (outputMode < 0.5) return finalColor;
      if (outputMode < 1.5) return vec3(depthSample);
      if (outputMode < 2.5) return baseColor;
      if (outputMode < 3.5) {
        return vec3(
          clamp(
            0.5 +
              macroHeight *
              ${glslFloat(dynamics.debugHeightScale)},
            0.0,
            1.0
          )
        );
      }
      if (outputMode < 4.5) {
        return macroNormal * 0.5 + 0.5;
      }
      if (outputMode < 5.5) return vec3(fresnel);
      if (outputMode < 6.5) return skyResponse;
      if (outputMode < 7.5) return vec3(iceFoam);
      if (outputMode < 8.5) return vec3(bathymetryData.r);
      if (outputMode < 9.5) return vec3(bathymetryData.g);
      if (outputMode < 10.5) return vec3(bathymetryData.b);
      if (outputMode < 11.5) return vec3(bathymetryData.a);
      return paletteColor;
    }
  `;
};
