import type { SettlementContentRegistry } from './SettlementContentRegistry';
import type {
  SettlementCropPlotRuntimeState,
  SettlementCropPlotSaveData,
  SettlementCropPlotView,
  SettlementSeason,
} from './SettlementTypes';
import type { SettlementWarehouse } from './SettlementWarehouse';

interface MutableCropPlotState {
  plotId: string;
  cropId?: string;
  plantedAt?: number;
  readyAt?: number;
  matured: boolean;
  harvestedCount: number;
  revision: number;
}

export interface SettlementCropMutationResult {
  readonly accepted: boolean;
  readonly status: string;
  readonly stateChanged: boolean;
  readonly quantity?: number;
}

const cloneState = (
  state: Readonly<MutableCropPlotState>,
): SettlementCropPlotRuntimeState => ({ ...state });

/** Timestamped crop plots shared by god mode and direct character play. */
export class SettlementCropSystem {
  private readonly states = new Map<string, MutableCropPlotState>();

  public constructor(
    private readonly registry: SettlementContentRegistry,
    private readonly warehouse: SettlementWarehouse,
    saved?: Readonly<SettlementCropPlotSaveData>,
  ) {
    for (const plot of registry.definitions.cropPlots) {
      this.states.set(plot.id, {
        plotId: plot.id,
        matured: false,
        harvestedCount: 0,
        revision: 0,
      });
    }
    if (saved?.version === 1 && Array.isArray(saved.states)) {
      for (const candidate of saved.states) this.importState(candidate);
    }
  }

  public plant(
    plotId: string,
    cropId: string,
    simulationTime: number,
  ): SettlementCropMutationResult {
    const plot = this.registry.getCropPlot(plotId);
    const crop = this.registry.getCrop(cropId);
    const state = this.states.get(plotId);
    const region = plot ? this.registry.getSeasonRegion(plot.regionId) : undefined;
    if (!plot || !crop || !state || !region || crop.season !== region.season) {
      return { accepted: false, status: 'CROP_OR_PLOT_INVALID', stateChanged: false };
    }
    if (state.cropId) {
      return { accepted: false, status: 'CROP_PLOT_OCCUPIED', stateChanged: false };
    }
    if (!this.isCropUnlocked(crop.id)) {
      return { accepted: false, status: 'CROP_NOT_UNLOCKED', stateChanged: false };
    }
    const now = Math.max(0, simulationTime);
    state.cropId = crop.id;
    state.plantedAt = now;
    state.readyAt = now + crop.growthSeconds;
    state.matured = false;
    state.revision += 1;
    return { accepted: true, status: 'CROP_PLANTED', stateChanged: true };
  }

  public harvest(
    plotId: string,
    simulationTime: number,
  ): SettlementCropMutationResult {
    const state = this.states.get(plotId);
    const crop = state?.cropId ? this.registry.getCrop(state.cropId) : undefined;
    if (!state || !crop) {
      return { accepted: false, status: 'CROP_PLOT_EMPTY', stateChanged: false };
    }
    this.resolveMaturity(state, simulationTime);
    if (!state.matured) {
      return { accepted: false, status: 'CROP_NOT_READY', stateChanged: false };
    }
    if (!this.warehouse.canApply(crop.harvestOutputs, 1) ||
      !this.warehouse.apply(crop.harvestOutputs, 1)) {
      return { accepted: false, status: 'WAREHOUSE_FULL', stateChanged: false };
    }
    const quantity = crop.harvestOutputs.reduce(
      (sum, output) => sum + output.quantity,
      0,
    );
    delete state.cropId;
    delete state.plantedAt;
    delete state.readyAt;
    state.matured = false;
    state.harvestedCount += 1;
    state.revision += 1;
    return { accepted: true, status: 'CROP_HARVESTED', stateChanged: true, quantity };
  }

  public update(simulationTime: number): boolean {
    let changed = false;
    for (const state of this.states.values()) {
      if (this.resolveMaturity(state, simulationTime)) changed = true;
    }
    return changed;
  }

  public getSeasonHarvestCount(
    season: SettlementSeason,
  ): number {
    let total = 0;
    for (const state of this.states.values()) {
      const plot = this.registry.getCropPlot(state.plotId);
      const region = plot ? this.registry.getSeasonRegion(plot.regionId) : undefined;
      if (region?.season === season) total += state.harvestedCount;
    }
    return total;
  }

  public isCropUnlocked(cropId: string): boolean {
    const crop = this.registry.getCrop(cropId);
    if (!crop || this.warehouse.getQuantity(crop.unlockGoodId) <= 0) return false;
    const prerequisite = crop.unlockAfterSeasonHarvests;
    return !prerequisite ||
      this.getSeasonHarvestCount(prerequisite.season) >= prerequisite.count;
  }

  public getView(plotId: string, simulationTime: number): SettlementCropPlotView | undefined {
    const plot = this.registry.getCropPlot(plotId);
    const state = this.states.get(plotId);
    const region = plot ? this.registry.getSeasonRegion(plot.regionId) : undefined;
    if (!plot || !state || !region) return undefined;
    const crop = state.cropId ? this.registry.getCrop(state.cropId) : undefined;
    const unlockedCrops = this.registry.definitions.crops.filter((candidate) =>
      candidate.season === region.season &&
      this.isCropUnlocked(candidate.id));
    const status = crop
      ? state.matured || simulationTime >= (state.readyAt ?? Number.POSITIVE_INFINITY)
        ? 'READY' as const
        : 'GROWING' as const
      : unlockedCrops.length > 0
        ? 'EMPTY' as const
        : 'LOCKED' as const;
    const growth = !crop
      ? 0
      : status === 'READY'
        ? 1
        : Math.max(0, Math.min(1,
            (simulationTime - (state.plantedAt ?? simulationTime)) /
              Math.max(0.001, crop.growthSeconds)));
    return {
      ...cloneState(state),
      displayName: plot.displayName,
      regionId: plot.regionId,
      season: region.season,
      x: plot.x,
      z: plot.z,
      interactionRadius: plot.interactionRadius,
      status,
      growth,
      ...(crop ? { cropDisplayName: crop.displayName } : {}),
      ...(crop ? { cropVisualKind: crop.visualKind } : {}),
      harvestOutputs: crop?.harvestOutputs.map((output) => ({ ...output })) ?? [],
    };
  }

  public getViews(simulationTime: number): readonly SettlementCropPlotView[] {
    return this.registry.definitions.cropPlots.flatMap((plot) => {
      const view = this.getView(plot.id, simulationTime);
      return view ? [view] : [];
    });
  }

  public exportState(): SettlementCropPlotSaveData {
    return {
      version: 1,
      states: [...this.states.values()]
        .sort((left, right) => left.plotId.localeCompare(right.plotId))
        .map(cloneState),
    };
  }

  private resolveMaturity(
    state: MutableCropPlotState,
    simulationTime: number,
  ): boolean {
    if (
      state.matured || !state.cropId || state.readyAt === undefined ||
      simulationTime < state.readyAt
    ) return false;
    state.matured = true;
    state.revision += 1;
    return true;
  }

  private importState(candidate: Readonly<SettlementCropPlotRuntimeState>): void {
    const plot = this.registry.getCropPlot(candidate?.plotId);
    const state = plot ? this.states.get(plot.id) : undefined;
    if (!plot || !state) return;
    state.harvestedCount = Number.isSafeInteger(candidate.harvestedCount) &&
      candidate.harvestedCount >= 0 ? candidate.harvestedCount : 0;
    state.revision = Number.isSafeInteger(candidate.revision) &&
      candidate.revision >= 0 ? candidate.revision : 0;
    const crop = candidate.cropId ? this.registry.getCrop(candidate.cropId) : undefined;
    const region = this.registry.getSeasonRegion(plot.regionId);
    if (
      !crop || !region || crop.season !== region.season ||
      !Number.isFinite(candidate.plantedAt) ||
      !Number.isFinite(candidate.readyAt) ||
      candidate.readyAt! < candidate.plantedAt!
    ) return;
    state.cropId = crop.id;
    state.plantedAt = Math.max(0, candidate.plantedAt!);
    state.readyAt = Math.max(state.plantedAt, candidate.readyAt!);
    state.matured = candidate.matured === true;
  }
}
