import type { MultiplayerSessionClient } from '../client/MultiplayerSessionClient';
import type { MultiplayerPlatformPerformanceEvidence } from '../testing/ProductionMultiplayerReleaseGate';

export interface MultiplayerPlatformEvidenceSamplerOptions {
  readonly platformClass: 'DESKTOP' | 'MOBILE';
  readonly targetId: string;
  readonly buildId: string;
  readonly playerCount: () => 1 | 2 | 3 | 4;
  readonly nowMs?: () => number;
  readonly memoryMb?: () => number;
}

const percentile = (values: readonly number[], ratio: number): number => {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((left, right) => left - right);
  return sorted[Math.min(sorted.length - 1, Math.floor((sorted.length - 1) * ratio))]!;
};

/** Target-device sampler. A release sample remains blocked until it lasts 10 min. */
export class MultiplayerPlatformEvidenceSampler {
  private readonly nowMs: () => number;
  private readonly startedAtMs: number;
  private readonly frameTimes: number[] = [];
  private readonly inputLatencies: number[] = [];
  private readonly bandwidthBuckets: number[] = [];
  private lastInputSampleAtMs?: number;
  private bandwidthBucketStartedAtMs: number;
  private bandwidthBucketBytes = 0;
  private previousNetworkBytes = 0;
  private peakResidentMemoryMb = 0;

  public constructor(
    private readonly client: MultiplayerSessionClient,
    private readonly options: Readonly<MultiplayerPlatformEvidenceSamplerOptions>,
  ) {
    if (!options.targetId.trim() || options.targetId.length > 160) {
      throw new Error('Multiplayer performance target ID is invalid.');
    }
    this.nowMs = options.nowMs ?? (() => performance.now());
    this.startedAtMs = this.nowMs();
    this.bandwidthBucketStartedAtMs = this.startedAtMs;
    this.previousNetworkBytes = this.networkBytes();
  }

  public recordInputSample(atMs = this.nowMs()): void {
    if (Number.isFinite(atMs)) this.lastInputSampleAtMs = atMs;
  }

  public recordFrame(frameMs: number, presentedAtMs = this.nowMs()): void {
    if (!Number.isFinite(frameMs) || frameMs <= 0) return;
    this.pushBounded(this.frameTimes, frameMs, 240_000);
    if (this.lastInputSampleAtMs !== undefined) {
      this.pushBounded(
        this.inputLatencies,
        Math.max(0, presentedAtMs - this.lastInputSampleAtMs),
        60_000,
      );
      this.lastInputSampleAtMs = undefined;
    }
    const networkBytes = this.networkBytes();
    this.bandwidthBucketBytes += Math.max(0, networkBytes - this.previousNetworkBytes);
    this.previousNetworkBytes = networkBytes;
    const bucketDuration = presentedAtMs - this.bandwidthBucketStartedAtMs;
    if (bucketDuration >= 1_000) {
      this.pushBounded(
        this.bandwidthBuckets,
        this.bandwidthBucketBytes / (bucketDuration / 1_000),
        7_200,
      );
      this.bandwidthBucketStartedAtMs = presentedAtMs;
      this.bandwidthBucketBytes = 0;
    }
    const memory = this.options.memoryMb?.() ?? this.browserHeapMemoryMb();
    if (Number.isFinite(memory)) {
      this.peakResidentMemoryMb = Math.max(this.peakResidentMemoryMb, memory);
    }
  }

  public snapshot(): MultiplayerPlatformPerformanceEvidence {
    const duration = Math.max(0, this.nowMs() - this.startedAtMs);
    const p95Frame = percentile(this.frameTimes, 0.95);
    return {
      version: 1,
      platformClass: this.options.platformClass,
      targetId: this.options.targetId,
      buildId: this.options.buildId,
      playerCount: this.options.playerCount(),
      sampleDurationMs: duration,
      fpsP05: p95Frame > 0 ? 1_000 / p95Frame : 0,
      frameP99Ms: percentile(this.frameTimes, 0.99),
      inputToPresentationP95Ms: percentile(this.inputLatencies, 0.95),
      bandwidthP99BytesPerSecond: percentile(this.bandwidthBuckets, 0.99),
      peakResidentMemoryMb: this.peakResidentMemoryMb,
    };
  }

  private networkBytes(): number {
    const transport = this.client.diagnostics().transport;
    return (transport?.sentBytes ?? 0) + (transport?.deliveredBytes ?? 0);
  }

  private browserHeapMemoryMb(): number {
    const memory = (performance as Performance & {
      memory?: { usedJSHeapSize?: number };
    }).memory;
    return typeof memory?.usedJSHeapSize === 'number'
      ? memory.usedJSHeapSize / (1_024 * 1_024)
      : 0;
  }

  private pushBounded(target: number[], value: number, maximum: number): void {
    target.push(value);
    if (target.length > maximum) target.splice(0, target.length - maximum);
  }
}

export const installMultiplayerPlatformEvidenceInspector = (
  sampler: MultiplayerPlatformEvidenceSampler,
): (() => void) => {
  if (typeof window === 'undefined') return () => undefined;
  const target = window as Window & {
    icewayMultiplayerPerformanceEvidence?: () => MultiplayerPlatformPerformanceEvidence;
  };
  target.icewayMultiplayerPerformanceEvidence = () => sampler.snapshot();
  return () => {
    delete target.icewayMultiplayerPerformanceEvidence;
  };
};
