import { clamp, lerp, smoothstep } from '../utils/math';

export type RefreezeStage =
  | 'untouched'
  | 'open'
  | 'slush'
  | 'thin-refreeze'
  | 'young-ice'
  | 'old-channel';

export const classifyRefreezeStage = (
  openness: number,
  channelMemory: number,
): RefreezeStage => {
  if (channelMemory < 0.02) return 'untouched';
  if (openness > 0.82) return 'open';
  if (openness > 0.64) return 'slush';
  if (openness > 0.4) return 'thin-refreeze';
  if (openness > 0.16) return 'young-ice';
  return 'old-channel';
};

export const calculateRefrozenVisualThickness = (
  originalThickness: number,
  openness: number,
  channelMemory: number,
  channelAgeSeconds: number,
): number => {
  if (channelMemory < 0.02) return originalThickness;
  const closure = 1 - clamp(openness, 0, 1);
  const ageing = smoothstep(90, 900, channelAgeSeconds);
  const youngThickness = 0.14 + closure * 0.5 + ageing * 0.12;
  return lerp(
    originalThickness,
    Math.min(originalThickness, youngThickness),
    clamp(channelMemory, 0, 1),
  );
};

export const calculateChannelResistanceMultiplier = (
  channelMemory: number,
  channelAgeSeconds: number,
): number => {
  const retainedMemory =
    clamp(channelMemory, 0, 1) *
    (1 - smoothstep(900, 3600, channelAgeSeconds) * 0.35);
  return 1 - retainedMemory * 0.34;
};
