export type MiningMaterialId =
  | 'STONE'
  | 'COAL'
  | 'IRON_ORE'
  | 'COPPER_ORE'
  | 'QUARTZ'
  | 'COZIUM_TRACE'
  | 'IRON_INGOT'
  | 'COPPER_INGOT'
  | 'GLASS'
  | 'COZIUM_CRYSTAL'
  | 'FORGED_RAIL_CORE'
  | 'SLAG';

export interface MiningMaterialDefinition {
  readonly id: MiningMaterialId;
  readonly displayName: string;
  readonly kind: 'RAW' | 'REFINED' | 'BYPRODUCT';
  readonly color: number;
}

