export interface MiningMaterialSaveData {
  readonly version: 1;
  readonly stock: readonly Readonly<{
    materialId: MiningMaterialId;
    amount: number;
  }>[];
  readonly discoveredMaterialIds: readonly MiningMaterialId[];
  readonly smelter?: Readonly<{
    recipeId: string;
    remainingSeconds: number;
  }>;
  readonly smelterRecipeCursor: number;
}

export interface MiningMaterialSnapshot {
  readonly stock: readonly Readonly<{
    materialId: MiningMaterialId;
    displayName: string;
    amount: number;
  }>[];
  readonly discoveredMaterialIds: readonly MiningMaterialId[];
  readonly activeSmelterJob?: Readonly<{
    recipeId: string;
    displayName: string;
    remainingSeconds: number;
    progress: number;
  }>;
  readonly selectedRecipe: Readonly<{
    id: string;
    displayName: string;
    canStart: boolean;
  }>;
}

export interface MiningSmelterInteraction {
  readonly label: string;
  readonly enabled: boolean;
  readonly kind: 'START' | 'RUNNING' | 'SELECT';
}

interface SmelterJob {
  recipeId: string;
  remainingSeconds: number;
}

const VALID_MATERIAL_IDS = new Set<MiningMaterialId>(
  MINING_MATERIAL_DEFINITIONS.map((definition) => definition.id),
);

const isMaterialId = (input: unknown): input is MiningMaterialId =>
  typeof input === 'string' && VALID_MATERIAL_IDS.has(input as MiningMaterialId);

export const MINING_SMELTER_POSITION = Object.freeze({
  x: BOREALIS_NORTH_RIDGE_QUARRY.smelterX,
  z: BOREALIS_NORTH_RIDGE_QUARRY.smelterZ,
});

/** Compact bulk-material ledger and one prototype smelter. */
export class MiningMaterialSystem {
  private readonly stock = new Map<MiningMaterialId, number>();
  private readonly discovered = new Set<MiningMaterialId>();
  private readonly root = new Group();
  private readonly furnaceGlow: MeshStandardMaterial;
  private readonly light = new PointLight(0xff7b35, 0, 7, 2);
  private job?: SmelterJob;
  private recipeCursor = 0;
  private visible = false;

  public constructor(scene: Scene, terrain: TerrainHeightSystem) {
    this.root.name = 'Prototype cave sorting bench and smelter';
    const ground = terrain.sampleHeight(
      MINING_SMELTER_POSITION.x,
      MINING_SMELTER_POSITION.z,
    );
    this.root.position.set(
      MINING_SMELTER_POSITION.x,
      ground,
      MINING_SMELTER_POSITION.z,
    );
    const iron = new MeshStandardMaterial({
      color: new Color(0x425052), roughness: 0.72, metalness: 0.52,
    });
    const brick = new MeshStandardMaterial({
      color: new Color(0x875344), roughness: 0.94, metalness: 0,
    });
    const wood = new MeshStandardMaterial({
      color: new Color(0x8b623d), roughness: 0.9, metalness: 0,
    });
    this.furnaceGlow = new MeshStandardMaterial({
      color: new Color(0xff9b45),
      emissive: new Color(0xff5c20),
      emissiveIntensity: 0.08,
      roughness: 0.5,
      metalness: 0,
    });
    const furnace = new Mesh(new CylinderGeometry(0.78, 0.92, 1.5, 10), brick);
    furnace.position.set(0.8, 0.75, 0);
    const rim = new Mesh(new TorusGeometry(0.78, 0.08, 7, 12), iron);
    rim.rotation.x = Math.PI / 2;
    rim.position.set(0.8, 1.42, 0);
    const mouth = new Mesh(new BoxGeometry(0.62, 0.48, 0.09), this.furnaceGlow);
    mouth.position.set(0.8, 0.58, -0.82);
    const chimney = new Mesh(new CylinderGeometry(0.18, 0.24, 1.35, 8), iron);
    chimney.position.set(0.8, 2.05, 0.18);
    const bench = new Mesh(new BoxGeometry(2.1, 0.16, 0.82), wood);
    bench.position.set(-0.85, 0.82, 0);
    const legGeometry = new BoxGeometry(0.13, 0.8, 0.13);
    for (const sideX of [-1, 1]) {
      for (const sideZ of [-1, 1]) {
        const leg = new Mesh(legGeometry, iron);
        leg.position.set(-0.85 + sideX * 0.82, 0.4, sideZ * 0.28);
        this.root.add(leg);
      }
    }
    for (const mesh of [furnace, rim, mouth, chimney, bench]) {
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      this.root.add(mesh);
    }
    this.light.position.set(0.8, 0.72, -1.05);
    this.light.castShadow = false;
    this.root.add(this.light);
    this.root.visible = false;
    scene.add(this.root);
  }

  public setVisible(visible: boolean): void {
    this.visible = visible;
    this.root.visible = visible;
  }

  public addRecoveredYield(
    recovered: Readonly<CaveRecoveredMaterialYield>,
  ): Readonly<{ stone: number; ore: number; oreId?: MiningMaterialId }> {
    const stone = Math.max(0, recovered.rockVolume) * 8;
    this.add('STONE', stone);
    const oreId = recovered.mineralId === 'IRON_TRACE' ||
        recovered.mineralId === 'IRON_ORE'
      ? 'IRON_ORE'
      : recovered.mineralId === 'COPPER_ORE'
        ? 'COPPER_ORE'
        : recovered.mineralId === 'COAL'
          ? 'COAL'
          : recovered.mineralId === 'QUARTZ'
            ? 'QUARTZ'
            : recovered.mineralId === 'COZIUM_TRACE'
              ? 'COZIUM_TRACE'
              : undefined;
    const ore = oreId
      ? Math.max(0, recovered.rockVolume) *
        (3.8 + clamp(recovered.mineralGrade, 0, 1) * 5.2)
      : 0;
    if (oreId && ore > 0) this.add(oreId, ore);
    return { stone, ore, ...(oreId ? { oreId } : {}) };
  }

  public update(deltaSeconds: number): string | undefined {
    const active = this.job;
    if (!active) {
      this.furnaceGlow.emissiveIntensity = 0.08;
      this.light.intensity = 0;
      return undefined;
    }
    const recipe = MINING_SMELTER_RECIPES.find((candidate) =>
      candidate.id === active.recipeId);
    if (!recipe) {
      this.job = undefined;
      return undefined;
    }
    active.remainingSeconds = Math.max(
      0,
      active.remainingSeconds - clamp(deltaSeconds, 0, 0.25),
    );
    const pulse = 0.75 + Math.sin(active.remainingSeconds * 4.2) * 0.14;
    this.furnaceGlow.emissiveIntensity = 1.6 * pulse;
    this.light.intensity = this.visible ? 2.4 * pulse : 0;
    if (active.remainingSeconds > 0) return undefined;
    for (const output of recipe.outputs) this.add(output.materialId, output.amount);
    this.job = undefined;
    return `${recipe.displayName} finished. Refined material is ready in the shared mining stock.`;
  }

  public resolveInteraction(x: number, z: number): MiningSmelterInteraction | undefined {
    if (!this.visible || Math.hypot(
      x - MINING_SMELTER_POSITION.x,
      z - MINING_SMELTER_POSITION.z,
    ) > 3.1) return undefined;
    if (this.job) {
      return {
        kind: 'RUNNING',
        label: `SMELTER · ${Math.ceil(this.job.remainingSeconds)} S`,
        enabled: false,
      };
    }
    const recipe = MINING_SMELTER_RECIPES[this.recipeCursor]!;
    return this.canStart(recipe)
      ? { kind: 'START', label: `START · ${recipe.displayName.toUpperCase()}`, enabled: true }
      : { kind: 'SELECT', label: `NEXT RECIPE · ${recipe.displayName.toUpperCase()}`, enabled: true };
  }

  public interact(): string {
    if (this.job) return 'The smelter is already working.';
    const recipe = MINING_SMELTER_RECIPES[this.recipeCursor]!;
    if (!this.canStart(recipe)) {
      this.recipeCursor = (this.recipeCursor + 1) % MINING_SMELTER_RECIPES.length;
      const next = MINING_SMELTER_RECIPES[this.recipeCursor]!;
      return `Smelter recipe selected: ${next.displayName}.`;
    }
    for (const input of recipe.inputs) this.add(input.materialId, -input.amount);
    this.job = { recipeId: recipe.id, remainingSeconds: recipe.durationSeconds };
    return `${recipe.displayName} started. The small furnace will finish in ${recipe.durationSeconds} seconds.`;
  }

  public cycleRecipe(direction: -1 | 1): MiningSmelterRecipe {
    this.recipeCursor = (
      this.recipeCursor + direction + MINING_SMELTER_RECIPES.length
    ) % MINING_SMELTER_RECIPES.length;
    return MINING_SMELTER_RECIPES[this.recipeCursor]!;
  }

  public grantDevSamples(): void {
    this.add('STONE', 24);
    this.add('COAL', 8);
    this.add('IRON_ORE', 12);
    this.add('COPPER_ORE', 12);
    this.add('QUARTZ', 8);
    this.add('COZIUM_TRACE', 5);
  }

  public getAmount(materialId: MiningMaterialId): number {
    return this.amount(materialId);
  }

  /** Used by explicit domain bridges; never silently destroys bulk mass. */
  public consume(materialId: MiningMaterialId, amount: number): boolean {
    if (!Number.isFinite(amount) || amount <= 0 || this.amount(materialId) < amount) {
      return false;
    }
    this.add(materialId, -amount);
    return true;
  }

  public getSnapshot(): MiningMaterialSnapshot {
    const recipe = MINING_SMELTER_RECIPES[this.recipeCursor]!;
    const activeRecipe = this.job
      ? MINING_SMELTER_RECIPES.find((candidate) => candidate.id === this.job!.recipeId)
      : undefined;
    return {
      stock: MINING_MATERIAL_DEFINITIONS
        .map((definition) => ({
          materialId: definition.id,
          displayName: definition.displayName,
          amount: this.amount(definition.id),
        }))
        .filter((entry) => entry.amount > 0.0001),
      discoveredMaterialIds: [...this.discovered].sort(),
      ...(this.job && activeRecipe
        ? {
            activeSmelterJob: {
              recipeId: activeRecipe.id,
              displayName: activeRecipe.displayName,
              remainingSeconds: this.job.remainingSeconds,
              progress: clamp(
                1 - this.job.remainingSeconds / activeRecipe.durationSeconds,
                0,
                1,
              ),
            },
          }
        : {}),
      selectedRecipe: {
        id: recipe.id,
        displayName: recipe.displayName,
        canStart: this.canStart(recipe),
      },
    };
  }

  public exportState(): MiningMaterialSaveData {
    return {
      version: 1,
      stock: [...this.stock]
        .filter(([, amount]) => amount > 0.0001)
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([materialId, amount]) => ({
          materialId,
          amount: Math.round(amount * 1_000) / 1_000,
        })),
      discoveredMaterialIds: [...this.discovered].sort(),
      ...(this.job ? { smelter: { ...this.job } } : {}),
      smelterRecipeCursor: this.recipeCursor,
    };
  }

  public importState(input: unknown): boolean {
    if (!input || typeof input !== 'object') return false;
    const saved = input as Partial<MiningMaterialSaveData>;
    if (saved.version !== 1 || !Array.isArray(saved.stock)) return false;
    this.stock.clear();
    this.discovered.clear();
    for (const entry of saved.stock) {
      if (!entry || !isMaterialId(entry.materialId) || !Number.isFinite(entry.amount)) {
        continue;
      }
      const amount = clamp(entry.amount, 0, 1_000_000);
      if (amount > 0.0001) this.stock.set(entry.materialId, amount);
    }
    if (Array.isArray(saved.discoveredMaterialIds)) {
      for (const id of saved.discoveredMaterialIds) {
        if (isMaterialId(id)) this.discovered.add(id);
      }
    }
    const smelterRecipe = saved.smelter
      ? MINING_SMELTER_RECIPES.find((recipe) => recipe.id === saved.smelter!.recipeId)
      : undefined;
    this.job = smelterRecipe && Number.isFinite(saved.smelter?.remainingSeconds)
      ? {
          recipeId: smelterRecipe.id,
          remainingSeconds: clamp(
            saved.smelter!.remainingSeconds,
            0.01,
            smelterRecipe.durationSeconds,
          ),
        }
      : undefined;
    this.recipeCursor = Number.isInteger(saved.smelterRecipeCursor)
      ? clamp(
          saved.smelterRecipeCursor!,
          0,
          MINING_SMELTER_RECIPES.length - 1,
        )
      : 0;
    return true;
  }

  public dispose(): void {
    this.root.traverse((object) => {
      if (object instanceof Mesh) {
        object.geometry.dispose();
        if (Array.isArray(object.material)) {
          for (const material of object.material) material.dispose();
        } else object.material.dispose();
      }
    });
    this.root.removeFromParent();
  }

  private amount(materialId: MiningMaterialId): number {
    return this.stock.get(materialId) ?? 0;
  }

  private add(materialId: MiningMaterialId, amount: number): void {
    const next = clamp(this.amount(materialId) + amount, 0, 1_000_000);
    if (next <= 0.0001) this.stock.delete(materialId);
    else this.stock.set(materialId, next);
    if (amount > 0) this.discovered.add(materialId);
  }

  private canStart(recipe: Readonly<MiningSmelterRecipe>): boolean {
    return recipe.inputs.every((input) =>
      this.amount(input.materialId) + 0.0001 >= input.amount
    );
  }
}
