import {
  type NetworkEntityId,
  type PlayerId,
  type Revision,
  networkEntityId,
  playerId,
  revision,
} from '../core/NetworkPrimitives';
export type SessionPlayerPermission = 'HOST' | 'PLAYER' | 'DEVELOPER';
export type SessionPlayerPresence = 'CONNECTED' | 'DISCONNECTED';

export interface StaticWorldMarkerPayload {
  /** Stable source identity; no map-only marker ID is allocated. */
  sourceKind: 'PORT' | 'POI' | 'ENTITY';
  sourceId: string;
  kind: 'HARBOR' | 'LANDMARK' | 'DEPOT';
  displayName: string;
  x: number;
  y: number;
  z: number;
}

export interface SessionRosterPlayerPayload {
  playerId: PlayerId;
  displayName: string;
  characterAppearanceId: string;
  permission: SessionPlayerPermission;
  presence: SessionPlayerPresence;
  characterEntityId?: NetworkEntityId;
  revision: Revision;
}

export interface SessionRosterPayload {
  version: 2;
  kind: 'SESSION_ROSTER';
  rosterRevision: number;
  players: readonly SessionRosterPlayerPayload[];
  staticWorldMarkers: readonly StaticWorldMarkerPayload[];
}

export const ICEWAY_PHASE_ONE_STATIC_WORLD_MARKERS: readonly StaticWorldMarkerPayload[] =
  Object.freeze([
    Object.freeze({
      sourceKind: 'PORT' as const,
      sourceId: 'borealis',
      kind: 'HARBOR' as const,
      displayName: 'Borealis Harbor',
      x: -43,
      y: 0.18,
      z: 8.4,
    }),
  ]);

const PERMISSIONS = new Set<SessionPlayerPermission>(['HOST', 'PLAYER', 'DEVELOPER']);
const PRESENCES = new Set<SessionPlayerPresence>(['CONNECTED', 'DISCONNECTED']);
const MARKER_KINDS = new Set<StaticWorldMarkerPayload['kind']>([
  'HARBOR',
  'LANDMARK',
  'DEPOT',
]);
const MARKER_SOURCES = new Set<StaticWorldMarkerPayload['sourceKind']>([
  'PORT',
  'POI',
  'ENTITY',
]);

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

const isBoundedString = (value: unknown, maximum: number): value is string =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maximum;

export const createSessionRosterPayload = (
  rosterRevision: number,
  players: readonly {
    playerId: PlayerId;
    displayName: string;
    characterAppearanceId?: string;
    permission: SessionPlayerPermission;
    presence: SessionPlayerPresence;
    characterEntityId?: NetworkEntityId;
    revision: Revision;
  }[],
  markers: readonly StaticWorldMarkerPayload[] = ICEWAY_PHASE_ONE_STATIC_WORLD_MARKERS,
): SessionRosterPayload => ({
  version: 2,
  kind: 'SESSION_ROSTER',
  rosterRevision,
  players: players.map((record) => ({
    playerId: record.playerId,
    displayName: record.displayName,
    characterAppearanceId:
      record.characterAppearanceId?.trim() || 'character:penguin:default',
    permission: record.permission,
    presence: record.presence,
    characterEntityId: record.characterEntityId,
    revision: record.revision,
  })),
  staticWorldMarkers: markers.map((marker) => ({ ...marker })),
});

export const validateSessionRosterPayload = (
  input: unknown,
): SessionRosterPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 2 ||
    input.kind !== 'SESSION_ROSTER' ||
    typeof input.rosterRevision !== 'number' ||
    !Number.isSafeInteger(input.rosterRevision) ||
    input.rosterRevision < 1 ||
    !Array.isArray(input.players) ||
    input.players.length > 4 ||
    !Array.isArray(input.staticWorldMarkers) ||
    input.staticWorldMarkers.length > 128
  ) {
    return undefined;
  }
  const players: SessionRosterPlayerPayload[] = [];
  const seenPlayers = new Set<string>();
  for (const candidate of input.players) {
    if (
      !isRecord(candidate) ||
      !isBoundedString(candidate.playerId, 160) ||
      seenPlayers.has(candidate.playerId) ||
      !isBoundedString(candidate.displayName, 48) ||
      !isBoundedString(candidate.characterAppearanceId, 96) ||
      typeof candidate.permission !== 'string' ||
      !PERMISSIONS.has(candidate.permission as SessionPlayerPermission) ||
      typeof candidate.presence !== 'string' ||
      !PRESENCES.has(candidate.presence as SessionPlayerPresence) ||
      (candidate.characterEntityId !== undefined &&
        !isBoundedString(candidate.characterEntityId, 160)) ||
      typeof candidate.revision !== 'number' ||
      !Number.isSafeInteger(candidate.revision) ||
      candidate.revision < 0
    ) {
      return undefined;
    }
    seenPlayers.add(candidate.playerId);
    players.push({
      playerId: playerId(candidate.playerId),
      displayName: candidate.displayName,
      characterAppearanceId: candidate.characterAppearanceId,
      permission: candidate.permission as SessionPlayerPermission,
      presence: candidate.presence as SessionPlayerPresence,
      characterEntityId:
        candidate.characterEntityId === undefined
          ? undefined
          : networkEntityId(candidate.characterEntityId),
      revision: revision(candidate.revision),
    });
  }
  const markers: StaticWorldMarkerPayload[] = [];
  const seenMarkers = new Set<string>();
  for (const candidate of input.staticWorldMarkers) {
    const identity = isRecord(candidate)
      ? `${String(candidate.sourceKind)}:${String(candidate.sourceId)}`
      : '';
    if (
      !isRecord(candidate) ||
      typeof candidate.sourceKind !== 'string' ||
      !MARKER_SOURCES.has(
        candidate.sourceKind as StaticWorldMarkerPayload['sourceKind'],
      ) ||
      !isBoundedString(candidate.sourceId, 160) ||
      seenMarkers.has(identity) ||
      typeof candidate.kind !== 'string' ||
      !MARKER_KINDS.has(candidate.kind as StaticWorldMarkerPayload['kind']) ||
      !isBoundedString(candidate.displayName, 160) ||
      typeof candidate.x !== 'number' ||
      !Number.isFinite(candidate.x) ||
      typeof candidate.y !== 'number' ||
      !Number.isFinite(candidate.y) ||
      typeof candidate.z !== 'number' ||
      !Number.isFinite(candidate.z)
    ) {
      return undefined;
    }
    seenMarkers.add(identity);
    markers.push({
      sourceKind:
        candidate.sourceKind as StaticWorldMarkerPayload['sourceKind'],
      sourceId: candidate.sourceId,
      kind: candidate.kind as StaticWorldMarkerPayload['kind'],
      displayName: candidate.displayName,
      x: candidate.x,
      y: candidate.y,
      z: candidate.z,
    });
  }
  return {
    version: 2,
    kind: 'SESSION_ROSTER',
    rosterRevision: input.rosterRevision,
    players,
    staticWorldMarkers: markers,
  };
};
