import { clamp } from '../utils/math';
import {
  gamepadAxis,
  gamepadButtonPressed,
  gamepadButtonValue,
  getPrimaryGamepad,
} from './GamepadInput';

export interface LandMachineControlCommand {
  forward: number;
  lateral: number;
  steering: number;
  yaw: number;
  vertical: number;
  toolTilt: number;
}

const CONTROL_KEYS = new Set([
  'KeyW',
  'KeyA',
  'KeyS',
  'KeyD',
  'KeyQ',
  'KeyE',
  'KeyC',
  'KeyZ',
  'ArrowLeft',
  'ArrowRight',
  'ArrowUp',
  'ArrowDown',
]);

/** Shared direct controls for the separately parked land and air machines. */
export class PlayerLandMachineController {
  private readonly pressed = new Set<string>();
  private enabled = false;
  private virtualForward = 0;
  private virtualLateral = 0;
  private virtualYaw = 0;
  private virtualVertical = 0;
  private virtualToolTilt = 0;

  public constructor() {
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    window.addEventListener('blur', this.onBlur);
  }

  public setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    this.pressed.clear();
    this.virtualForward = 0;
    this.virtualLateral = 0;
    this.virtualYaw = 0;
    this.virtualVertical = 0;
    this.virtualToolTilt = 0;
  }

  public setVirtualMovement(right: number, forward: number): void {
    this.virtualLateral = clamp(right, -1, 1);
    this.virtualForward = clamp(forward, -1, 1);
  }

  public setVirtualFlight(yaw: number, vertical: number): void {
    this.virtualYaw = clamp(yaw, -1, 1);
    this.virtualVertical = clamp(vertical, -1, 1);
  }

  public setVirtualToolTilt(value: number): void {
    this.virtualToolTilt = clamp(value, -1, 1);
  }

  public sampleControls(): LandMachineControlCommand {
    if (!this.enabled) {
      return {
        forward: 0,
        lateral: 0,
        steering: 0,
        yaw: 0,
        vertical: 0,
        toolTilt: 0,
      };
    }
    const gamepad = getPrimaryGamepad();
    const keyboardForward =
      (this.pressed.has('KeyW') ? 1 : 0) -
      (this.pressed.has('KeyS') ? 1 : 0);
    const keyboardLateral =
      (this.pressed.has('KeyD') ? 1 : 0) -
      (this.pressed.has('KeyA') ? 1 : 0);
    const keyboardYaw =
      (this.pressed.has('ArrowRight') ? 1 : 0) -
      (this.pressed.has('ArrowLeft') ? 1 : 0);
    const keyboardVertical =
      (this.pressed.has('KeyE') ? 1 : 0) -
      (this.pressed.has('KeyQ') ? 1 : 0);
    const keyboardToolTilt =
      (this.pressed.has('KeyC') ? 1 : 0) -
      (this.pressed.has('KeyZ') ? 1 : 0);
    const gamepadForward = -gamepadAxis(gamepad, 1);
    const gamepadLateral = gamepadAxis(gamepad, 0);
    const gamepadYaw = gamepadAxis(gamepad, 2);
    const gamepadVertical =
      gamepadButtonValue(gamepad, 7) - gamepadButtonValue(gamepad, 6);
    const forward = Math.abs(keyboardForward) > 0.01
      ? keyboardForward
      : Math.abs(this.virtualForward) > 0.01
        ? this.virtualForward
        : gamepadForward;
    const lateral = Math.abs(keyboardLateral) > 0.01
      ? keyboardLateral
      : Math.abs(this.virtualLateral) > 0.01
        ? this.virtualLateral
        : gamepadLateral;
    const yaw = Math.abs(keyboardYaw) > 0.01
      ? keyboardYaw
      : Math.abs(this.virtualYaw) > 0.01
        ? this.virtualYaw
        : gamepadYaw;
    const vertical = Math.abs(keyboardVertical) > 0.01
      ? keyboardVertical
      : Math.abs(this.virtualVertical) > 0.01
        ? this.virtualVertical
        : gamepadVertical;
    return {
      forward: clamp(forward, -1, 1),
      lateral: clamp(lateral, -1, 1),
      // Ground vehicles steer with A/D; aircraft reserve arrows for yaw.
      steering: clamp(-lateral, -1, 1),
      yaw: clamp(yaw, -1, 1),
      vertical: clamp(vertical, -1, 1),
      toolTilt: clamp(
        Math.abs(keyboardToolTilt) > 0.01
          ? keyboardToolTilt
          : this.virtualToolTilt,
        -1,
        1,
      ),
    };
  }

  public dispose(): void {
    window.removeEventListener('keydown', this.onKeyDown);
    window.removeEventListener('keyup', this.onKeyUp);
    window.removeEventListener('blur', this.onBlur);
  }

  private onKeyDown = (event: KeyboardEvent): void => {
    if (!this.enabled) return;
    if (CONTROL_KEYS.has(event.code)) event.preventDefault();
    this.pressed.add(event.code);
  };

  private onKeyUp = (event: KeyboardEvent): void => {
    this.pressed.delete(event.code);
  };

  private onBlur = (): void => {
    this.pressed.clear();
  };
}
