import type { GlobalPosition } from '../../world/GlobalPosition';
import type { GameplayRegistry } from '../definitions/GameplayRegistry';
import type { MissionStatus } from '../definitions/GameplayTypes';
import { worldTarget } from '../world/WorldTarget';
import type {
  WorldOutcomeDefinition,
  WorldOutcomeRuntimeState,
} from '../simulation/WorldOutcomeSystem';
import type { RadioNetworkRegistry } from './RadioNetworkRegistry';
import type { RadioTowerState } from './RadioNetworkTypes';

export interface RadioTowerRepairDefinition {
  id: string;
  displayName: string;
  towerId: string;
  stationId: string;
  frequencyId: string;
  missionId: string;
  servicePortId: string;
  componentId: string;
  componentDisplayName: string;
  outcomeId: string;
}

export type RadioTowerRepairStatus =
  | 'LOCKED'
  | 'AVAILABLE'
  | 'READY'
  | 'ONLINE';

export interface RadioTowerRepairView {
  id: string;
  displayName: string;
  missionId: string;
  servicePortId: string;
  componentDisplayName: string;
  frequencyId: string;
  towerId: string;
  worldPosition: GlobalPosition;
  towerState: RadioTowerState;
  status: RadioTowerRepairStatus;
  statusLabel: string;
  actionLabel: string;
  canRepair: boolean;
}

export type RadioTowerRepairFailure =
  | 'UNKNOWN_REPAIR'
  | 'WRONG_PORT'
  | 'MISSION_NOT_ACTIVE'
  | 'ALREADY_REPAIRED';

export interface RadioTowerRepairCheck {
  accepted: boolean;
  definition?: Readonly<RadioTowerRepairDefinition>;
  reason?: RadioTowerRepairFailure;
}

export const V1_RADIO_TOWER_REPAIR_DEFINITIONS =
  Object.freeze([
    Object.freeze({
      id: 'aurora-radio-relay-repair',
      displayName: 'Aurora Coast Radio',
      towerId: 'aurora-radio-relay',
      stationId: 'aurora-coast-radio',
      frequencyId: 'aurora-coast-weather',
      missionId: 'restore-aurora-radio-relay',
      servicePortId: 'aurora',
      componentId: 'polar-relay-fuse',
      componentDisplayName: 'Polar Relay Fuse',
      outcomeId: 'aurora-radio-relay-state',
    }),
  ] as const satisfies readonly RadioTowerRepairDefinition[]);

export const V1_RADIO_TOWER_OUTCOME_DEFINITIONS:
  readonly WorldOutcomeDefinition[] = Object.freeze(
  V1_RADIO_TOWER_REPAIR_DEFINITIONS.map((definition) =>
    Object.freeze({
      id: definition.outcomeId,
      allowedStates: Object.freeze(['OFFLINE', 'ONLINE']),
      initialState: 'OFFLINE',
      terminalStates: Object.freeze(['ONLINE']),
      target: worldTarget.object(
        `radio-tower:${definition.towerId}`,
      ),
    }),
  ),
);

export class RadioTowerRepairSystem {
  private readonly definitions = new Map<
    string,
    Readonly<RadioTowerRepairDefinition>
  >();

  public constructor(
    definitions: readonly RadioTowerRepairDefinition[],
    gameplay: GameplayRegistry,
    radio: RadioNetworkRegistry,
  ) {
    for (const definition of definitions) {
      if (this.definitions.has(definition.id)) {
        throw new Error(
          `Duplicate radio tower repair "${definition.id}"`,
        );
      }
      const mission = gameplay.getMission(definition.missionId);
      const tower = radio.getTower(definition.towerId);
      const station = radio.getStation(definition.stationId);
      const frequency = radio.getFrequency(
        definition.frequencyId,
      );
      if (
        !mission ||
        mission.type !== 'DELIVER_SPECIAL_COMPONENT' ||
        mission.linkedPortId !== definition.servicePortId ||
        mission.requiredComponentId !==
          definition.componentId
      ) {
        throw new Error(
          `Invalid repair mission "${definition.missionId}"`,
        );
      }
      if (!gameplay.getPort(definition.servicePortId)) {
        throw new Error(
          `Missing repair port "${definition.servicePortId}"`,
        );
      }
      if (
        !tower ||
        !station ||
        !frequency ||
        frequency.channelType !== 'WEATHER_AND_ICE'
      ) {
        throw new Error(
          `Invalid radio network references for "${definition.id}"`,
        );
      }
      this.definitions.set(
        definition.id,
        Object.freeze({ ...definition }),
      );
    }
  }

  public getDefinition(
    repairId: string,
  ): Readonly<RadioTowerRepairDefinition> | undefined {
    return this.definitions.get(repairId);
  }

  public getDefinitions():
    readonly Readonly<RadioTowerRepairDefinition>[] {
    return [...this.definitions.values()];
  }

  public checkRepair(
    repairId: string,
    portId: string,
    missionStatus: MissionStatus | undefined,
    outcomeState: string | undefined,
  ): RadioTowerRepairCheck {
    const definition = this.definitions.get(repairId);
    if (!definition) {
      return { accepted: false, reason: 'UNKNOWN_REPAIR' };
    }
    if (outcomeState === 'ONLINE') {
      return {
        accepted: false,
        definition,
        reason: 'ALREADY_REPAIRED',
      };
    }
    if (definition.servicePortId !== portId) {
      return {
        accepted: false,
        definition,
        reason: 'WRONG_PORT',
      };
    }
    if (missionStatus !== 'ACTIVE') {
      return {
        accepted: false,
        definition,
        reason: 'MISSION_NOT_ACTIVE',
      };
    }
    return { accepted: true, definition };
  }

  public createView(
    definition: Readonly<RadioTowerRepairDefinition>,
    missionStatus: MissionStatus | undefined,
    outcome: Readonly<WorldOutcomeRuntimeState> | undefined,
    towerState: RadioTowerState,
    worldPosition: Readonly<GlobalPosition>,
  ): RadioTowerRepairView {
    const online =
      outcome?.state === 'ONLINE' &&
      (towerState === 'ONLINE' || towerState === 'UPGRADED');
    const status: RadioTowerRepairStatus = online
      ? 'ONLINE'
      : missionStatus === 'ACTIVE'
        ? 'READY'
        : missionStatus === 'OFFERED'
          ? 'AVAILABLE'
          : 'LOCKED';
    return {
      id: definition.id,
      displayName: definition.displayName,
      missionId: definition.missionId,
      servicePortId: definition.servicePortId,
      componentDisplayName: definition.componentDisplayName,
      frequencyId: definition.frequencyId,
      towerId: definition.towerId,
      worldPosition: structuredClone(worldPosition),
      towerState,
      status,
      statusLabel:
        status === 'ONLINE'
          ? 'TRANSMITTER ONLINE'
          : status === 'READY'
            ? `${definition.componentDisplayName.toUpperCase()} READY`
            : status === 'AVAILABLE'
              ? 'JOB AVAILABLE'
              : 'OFFLINE',
      actionLabel:
        `INSTALL ${definition.componentDisplayName.toUpperCase()} & ACTIVATE`,
      canRepair: status === 'READY',
    };
  }
}
