import {
  cloneGlobalPosition,
  isGlobalPositionInPartition,
  type GlobalPosition,
} from '../../world/GlobalPosition';
import {
  ICEAWAY_TARGET_WORLD_PARTITION,
  isChunkInWorldPartition,
  type WorldChunkAddress,
  type WorldPartitionDefinition,
} from '../../world/WorldPartitionTypes';
import { prototypeLocalToGlobalPosition } from '../../world/PrototypeWorldPositionAdapter';
import type { GameplayRegistry } from '../definitions/GameplayRegistry';
import type {
  GoodType,
  IceType,
  PoiCategory,
} from '../definitions/GameplayTypes';

export interface RegionChunkBounds {
  minimum: WorldChunkAddress;
  maximum: WorldChunkAddress;
}

export interface RegionalPoiHook {
  id: string;
  category: PoiCategory;
  worldPosition: GlobalPosition;
  activation: 'CONTENT_BACKLOG';
}

export interface RegionalIceGate {
  id: string;
  routeId: string;
  iceType: IceType;
  role: 'SHORTCUT' | 'BOTTLENECK' | 'FUTURE_BOUNDARY';
}

export interface RegionalGoodsDependency {
  id: string;
  sourcePortId: string;
  destinationPortId: string;
  good: GoodType;
}

export interface RegionalContentDefinition {
  id: string;
  displayName: string;
  chunkBounds: RegionChunkBounds;
  portIds: readonly string[];
  routeIds: readonly string[];
  poiHooks: readonly RegionalPoiHook[];
  iceGates: readonly RegionalIceGate[];
  goodsDependencies: readonly RegionalGoodsDependency[];
}

const poiHook = (
  id: string,
  category: PoiCategory,
  x: number,
  z: number,
): RegionalPoiHook => ({
  id,
  category,
  worldPosition: prototypeLocalToGlobalPosition({
    x,
    y: 0,
    z,
  }),
  activation: 'CONTENT_BACKLOG',
});

