const chunkKey = (
  chunk: Readonly<WorldChunkAddress>,
): string => `${chunk.x}:${chunk.z}`;

const inBounds = (
  chunk: Readonly<WorldChunkAddress>,
  bounds: Readonly<RegionChunkBounds>,
): boolean =>
  chunk.x >= bounds.minimum.x &&
  chunk.x <= bounds.maximum.x &&
  chunk.z >= bounds.minimum.z &&
  chunk.z <= bounds.maximum.z;

export class RegionalContentCatalog {
  private readonly definitions = new Map<
    string,
    Readonly<RegionalContentDefinition>
  >();
  private readonly regionIdsByChunk = new Map<string, string[]>();

  public constructor(
    definitions: readonly RegionalContentDefinition[],
    gameplay: GameplayRegistry,
    public readonly partition:
      Readonly<WorldPartitionDefinition> =
        ICEAWAY_TARGET_WORLD_PARTITION,
  ) {
    for (const definition of definitions) {
      this.validateDefinition(definition, gameplay);
      if (this.definitions.has(definition.id)) {
        throw new Error(
          `Duplicate regional content definition "${definition.id}"`,
        );
      }
      const frozen = structuredClone(definition);
      this.definitions.set(definition.id, Object.freeze(frozen));
      for (
        let z = definition.chunkBounds.minimum.z;
        z <= definition.chunkBounds.maximum.z;
        z += 1
      ) {
        for (
          let x = definition.chunkBounds.minimum.x;
          x <= definition.chunkBounds.maximum.x;
          x += 1
        ) {
          const key = chunkKey({ x, z });
          const regionIds = this.regionIdsByChunk.get(key) ?? [];
          regionIds.push(definition.id);
          this.regionIdsByChunk.set(key, regionIds);
        }
      }
    }
  }

  public getDefinition(
    regionId: string,
  ): Readonly<RegionalContentDefinition> | undefined {
    const definition = this.definitions.get(regionId);
    return definition
      ? this.cloneDefinition(definition)
      : undefined;
  }

  public getDefinitions():
    readonly Readonly<RegionalContentDefinition>[] {
    return [...this.definitions.values()].map((definition) =>
      this.cloneDefinition(definition),
    );
  }

  public getRegionsAtChunk(
    chunk: Readonly<WorldChunkAddress>,
  ): readonly Readonly<RegionalContentDefinition>[] {
    return (this.regionIdsByChunk.get(chunkKey(chunk)) ?? [])
      .map((regionId) => this.definitions.get(regionId))
      .filter(
        (
          definition,
        ): definition is Readonly<RegionalContentDefinition> =>
          definition !== undefined,
      )
      .map((definition) => this.cloneDefinition(definition));
  }

  private validateDefinition(
    definition: Readonly<RegionalContentDefinition>,
    gameplay: GameplayRegistry,
  ): void {
    if (!definition.id.trim()) {
      throw new Error('Regional content ID must be non-empty');
    }
    const bounds = definition.chunkBounds;
    if (
      !isChunkInWorldPartition(this.partition, bounds.minimum) ||
      !isChunkInWorldPartition(this.partition, bounds.maximum) ||
      bounds.minimum.x > bounds.maximum.x ||
      bounds.minimum.z > bounds.maximum.z
    ) {
      throw new Error(
        `Region "${definition.id}" has invalid chunk bounds`,
      );
    }
    for (const portId of definition.portIds) {
      if (!gameplay.getPort(portId)) {
        throw new Error(
          `Region "${definition.id}" references missing port "${portId}"`,
        );
      }
    }
    for (const routeId of definition.routeIds) {
      if (!gameplay.getRoute(routeId)) {
        throw new Error(
          `Region "${definition.id}" references missing route "${routeId}"`,
        );
      }
    }
    const routeIds = new Set(definition.routeIds);
    for (const gate of definition.iceGates) {
      if (!routeIds.has(gate.routeId)) {
        throw new Error(
          `Ice gate "${gate.id}" is outside region routes`,
        );
      }
    }
    const portIds = new Set(definition.portIds);
    for (const dependency of definition.goodsDependencies) {
      if (
        !portIds.has(dependency.sourcePortId) ||
        !portIds.has(dependency.destinationPortId)
      ) {
        throw new Error(
          `Goods dependency "${dependency.id}" is outside region ports`,
        );
      }
    }
    for (const hook of definition.poiHooks) {
      if (
        !isGlobalPositionInPartition(
          this.partition,
          hook.worldPosition,
        ) ||
        !inBounds(hook.worldPosition.chunk, bounds)
      ) {
        throw new Error(
          `POI hook "${hook.id}" is outside region bounds`,
        );
      }
    }
  }

  private cloneDefinition(
    definition: Readonly<RegionalContentDefinition>,
  ): RegionalContentDefinition {
    return {
      ...definition,
      chunkBounds: {
        minimum: { ...definition.chunkBounds.minimum },
        maximum: { ...definition.chunkBounds.maximum },
      },
      portIds: [...definition.portIds],
      routeIds: [...definition.routeIds],
      poiHooks: definition.poiHooks.map((hook) => ({
        ...hook,
        worldPosition: cloneGlobalPosition(hook.worldPosition),
      })),
      iceGates: definition.iceGates.map((gate) => ({ ...gate })),
      goodsDependencies: definition.goodsDependencies.map(
        (dependency) => ({ ...dependency }),
      ),
    };
  }
}
