import { clamp } from '../utils/math';

export interface AudioSettings {
  effectsVolume: number;
  musicVolume: number;
  musicTrackId: string;
  musicPaused: boolean;
  musicRepeat: boolean;
}

export const AUTOMATIC_MUSIC_TRACK_ID = 'auto';

export const DEFAULT_AUDIO_SETTINGS: Readonly<AudioSettings> =
  Object.freeze({
    effectsVolume: 0.78,
    musicVolume: 0.42,
    musicTrackId: AUTOMATIC_MUSIC_TRACK_ID,
    musicPaused: false,
    musicRepeat: false,
  });

const STORAGE_KEY = 'iceway-audio-v1';

export class AudioSettingsStore {
  public load(): AudioSettings {
    try {
      const raw = window.localStorage.getItem(STORAGE_KEY);
      if (!raw) return { ...DEFAULT_AUDIO_SETTINGS };
      const parsed = JSON.parse(raw) as Partial<AudioSettings>;
      return {
        effectsVolume: Number.isFinite(parsed.effectsVolume)
          ? clamp(parsed.effectsVolume ?? 0, 0, 1)
          : DEFAULT_AUDIO_SETTINGS.effectsVolume,
        musicVolume: Number.isFinite(parsed.musicVolume)
          ? clamp(parsed.musicVolume ?? 0, 0, 1)
          : DEFAULT_AUDIO_SETTINGS.musicVolume,
        musicTrackId:
          typeof parsed.musicTrackId === 'string' &&
          parsed.musicTrackId.trim().length > 0
            ? parsed.musicTrackId
            : DEFAULT_AUDIO_SETTINGS.musicTrackId,
        musicPaused: parsed.musicPaused === true,
        musicRepeat: parsed.musicRepeat === true,
      };
    } catch {
      return { ...DEFAULT_AUDIO_SETTINGS };
    }
  }

  public save(settings: Readonly<AudioSettings>): void {
    try {
      window.localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({
          effectsVolume: clamp(settings.effectsVolume, 0, 1),
          musicVolume: clamp(settings.musicVolume, 0, 1),
          musicTrackId:
            settings.musicTrackId || AUTOMATIC_MUSIC_TRACK_ID,
          musicPaused: settings.musicPaused,
          musicRepeat: settings.musicRepeat,
        }),
      );
    } catch {
      // Audio settings are non-critical when storage is unavailable.
    }
  }
}
