    this.restorePointRevision = this.terrain.getRevision();
    this.versions = this.loadVersions();
    const latestVersion = this.versions[0];
    this.savedVersionSnapshot = latestVersion
      ? this.cloneSnapshot(latestVersion.snapshot)
      : this.snapshot();
    this.activeVersionId = latestVersion?.id;
    this.selectedVersionId = latestVersion?.id;
    this.versionDirty = latestVersion
