const SNOW_MELT_BUCKET_SIZE_METRES = 8;

const snowMeltBucketKey = (x: number, z: number): string =>
  `${Math.floor(x / SNOW_MELT_BUCKET_SIZE_METRES)},${Math.floor(z / SNOW_MELT_BUCKET_SIZE_METRES)}`;

