import { isFiniteGlobalPosition } from '../../world/GlobalPosition';
import type {
  UtilityComponentCondition,
  UtilityComponentDefinition,
  UtilityComponentRuntimeState,
  UtilityConnectionDefinition,
  UtilityConnectionRuntimeState,
  UtilityDefinitionSet,
  UtilityMutationEvent,
  UtilityMutationResult,
  UtilityNetworkRuntimeState,
  UtilityNetworkSaveData,
  UtilityRuntimeSnapshot,
  UtilityServiceRuntimeState,
  UtilityTriggerCondition,
} from './UtilityNetworkTypes';

export interface UtilityDefinitionIssue {
  readonly path: string;
  readonly message: string;
}

export class UtilityDefinitionValidationError extends Error {
  public constructor(public readonly issues: readonly UtilityDefinitionIssue[]) {
    super(`Invalid utility definitions:\n${issues.map((issue) =>
      `- ${issue.path}: ${issue.message}`).join('\n')}`);
    this.name = 'UtilityDefinitionValidationError';
  }
}

const boundedId = (value: unknown): value is string =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= 160;

const uniqueIds = <T extends { readonly id: string }>(
  values: readonly T[],
  path: string,
  issues: UtilityDefinitionIssue[],
): Set<string> => {
  const result = new Set<string>();
  values.forEach((value, index) => {
    if (!boundedId(value.id)) {
      issues.push({ path: `${path}[${index}].id`, message: 'ID must be non-empty and at most 160 characters.' });
    } else if (result.has(value.id)) {
      issues.push({ path: `${path}[${index}].id`, message: `Duplicate ID "${value.id}".` });
    }
    result.add(value.id);
  });
  return result;
};

export const validateUtilityDefinitions = (
  definitions: Readonly<UtilityDefinitionSet>,
): readonly UtilityDefinitionIssue[] => {
  const issues: UtilityDefinitionIssue[] = [];
  if (!boundedId(definitions.id)) {
    issues.push({ path: 'id', message: 'Definition-set ID is invalid.' });
  }
  const networkIds = uniqueIds(definitions.networks, 'networks', issues);
  const componentIds = uniqueIds(definitions.components, 'components', issues);
  const connectionIds = uniqueIds(definitions.connections, 'connections', issues);
  const serviceIds = uniqueIds(definitions.services, 'services', issues);
  const triggerIds = uniqueIds(definitions.oneTimeTriggers ?? [], 'oneTimeTriggers', issues);
  void triggerIds;
  const componentById = new Map(definitions.components.map((component) => [component.id, component]));
  const connectionById = new Map(definitions.connections.map((connection) => [connection.id, connection]));

  definitions.components.forEach((component, index) => {
    const path = `components[${index}]`;
    if (!networkIds.has(component.networkId)) {
      issues.push({ path: `${path}.networkId`, message: `Missing network "${component.networkId}".` });
    }
    const portIds = uniqueIds(component.ports, `${path}.ports`, issues);
    if (portIds.size === 0) issues.push({ path: `${path}.ports`, message: 'At least one port is required.' });
    if (component.role === 'SOURCE' && !(Number(component.supplyCapacity) > 0)) {
      issues.push({ path: `${path}.supplyCapacity`, message: 'A source requires positive capacity.' });
    }
    if (component.role === 'CONSUMER' && !(Number(component.demand) > 0)) {
      issues.push({ path: `${path}.demand`, message: 'A consumer requires positive demand.' });
    }
    if (component.worldPosition && !isFiniteGlobalPosition(component.worldPosition)) {
      issues.push({ path: `${path}.worldPosition`, message: 'World position is invalid.' });
    }
  });

  const validateEndpoint = (
    endpoint: Readonly<{ componentId: string; portId: string }>,
    networkId: string,
    path: string,
  ): void => {
    const component = componentById.get(endpoint.componentId);
    if (!component) {
      issues.push({ path, message: `Missing component "${endpoint.componentId}".` });
      return;
    }
    if (component.networkId !== networkId) {
      issues.push({ path, message: 'Connection endpoint belongs to another network.' });
    }
    if (!component.ports.some((port) => port.id === endpoint.portId)) {
      issues.push({ path, message: `Missing port "${endpoint.portId}" on "${endpoint.componentId}".` });
    }
  };

  definitions.connections.forEach((connection, index) => {
    const path = `connections[${index}]`;
    if (!networkIds.has(connection.networkId)) {
      issues.push({ path: `${path}.networkId`, message: `Missing network "${connection.networkId}".` });
    }
    validateEndpoint(connection.from, connection.networkId, `${path}.from`);
    validateEndpoint(connection.to, connection.networkId, `${path}.to`);
    if (connection.from.componentId === connection.to.componentId) {
      issues.push({ path, message: 'A connection cannot connect a component to itself.' });
    }
    if (connection.worldPosition && !isFiniteGlobalPosition(connection.worldPosition)) {
      issues.push({ path: `${path}.worldPosition`, message: 'World position is invalid.' });
    }
  });

  definitions.services.forEach((service, index) => {
    const path = `services[${index}]`;
    const component = componentById.get(service.componentId);
    if (!networkIds.has(service.networkId)) {
      issues.push({ path: `${path}.networkId`, message: `Missing network "${service.networkId}".` });
    }
    if (!component) {
      issues.push({ path: `${path}.componentId`, message: `Missing component "${service.componentId}".` });
    } else if (component.networkId !== service.networkId) {
      issues.push({ path: `${path}.componentId`, message: 'Service component belongs to another network.' });
    } else if (component.role !== 'CONSUMER') {
      issues.push({ path: `${path}.componentId`, message: 'A service must terminate at a consumer.' });
    }
  });

  (definitions.oneTimeTriggers ?? []).forEach((trigger, index) => {
    const path = `oneTimeTriggers[${index}]`;
    if (trigger.condition.type === 'COMPONENT_SUPPLIED' &&
      !componentIds.has(trigger.condition.componentId)) {
      issues.push({ path: `${path}.condition`, message: `Missing component "${trigger.condition.componentId}".` });
    }
    if (trigger.condition.type === 'SERVICE_STATE' &&
      !serviceIds.has(trigger.condition.serviceId)) {
      issues.push({ path: `${path}.condition`, message: `Missing service "${trigger.condition.serviceId}".` });
    }
    if (trigger.actions.length === 0) {
      issues.push({ path: `${path}.actions`, message: 'A trigger requires at least one action.' });
    }
    trigger.actions.forEach((action, actionIndex) => {
      if (action.type === 'SET_COMPONENT_CONDITION' && !componentIds.has(action.componentId)) {
        issues.push({ path: `${path}.actions[${actionIndex}]`, message: `Missing component "${action.componentId}".` });
      }
      if (action.type === 'SET_CONNECTION_STATE' && !connectionIds.has(action.connectionId)) {
        issues.push({ path: `${path}.actions[${actionIndex}]`, message: `Missing connection "${action.connectionId}".` });
      }
    });
  });
  return issues;
};

const cloneComponent = (state: Readonly<UtilityComponentRuntimeState>): UtilityComponentRuntimeState => ({ ...state });
const cloneConnection = (state: Readonly<UtilityConnectionRuntimeState>): UtilityConnectionRuntimeState => ({ ...state });
const cloneService = (state: Readonly<UtilityServiceRuntimeState>): UtilityServiceRuntimeState => ({ ...state });
const cloneNetwork = (state: Readonly<UtilityNetworkRuntimeState>): UtilityNetworkRuntimeState => ({ ...state });

/**
 * Renderer-free, low-frequency utility graph. It solves only after authored
 * topology or component state changes; meshes and effects remain presentation.
 */
export class UtilityNetworkSystem {
  public readonly definitions: UtilityDefinitionSet;
  private readonly componentDefinitions = new Map<string, UtilityComponentDefinition>();
  private readonly connectionDefinitions = new Map<string, UtilityConnectionDefinition>();
  private readonly components = new Map<string, UtilityComponentRuntimeState>();
  private readonly connections = new Map<string, UtilityConnectionRuntimeState>();
  private readonly services = new Map<string, UtilityServiceRuntimeState>();
  private readonly networks = new Map<string, UtilityNetworkRuntimeState>();
  private readonly appliedTriggerIds = new Set<string>();
  private readonly recentEvents: UtilityMutationEvent[] = [];
  private readonly listeners = new Set<(
    result: Readonly<UtilityMutationResult>,
  ) => void>();
  private revisionValue = 0;
  private eventSequence = 0;

  public constructor(
    source: Readonly<UtilityDefinitionSet>,
    saved?: Readonly<UtilityNetworkSaveData>,
  ) {
    const issues = validateUtilityDefinitions(source);
    if (issues.length > 0) throw new UtilityDefinitionValidationError(issues);
    this.definitions = structuredClone(source);
    for (const definition of this.definitions.components) {
      this.componentDefinitions.set(definition.id, definition);
      this.components.set(definition.id, {
        componentId: definition.id,
        condition: definition.initialCondition,
        enabled: definition.initiallyEnabled !== false,
        supplied: false,
        allocatedCapacity: 0,
        revision: 0,
      });
    }
    for (const definition of this.definitions.connections) {
      this.connectionDefinitions.set(definition.id, definition);
      this.connections.set(definition.id, {
        connectionId: definition.id,
        state: definition.initialState,
        revision: 0,
      });
    }
    for (const definition of this.definitions.services) {
      this.services.set(definition.id, { serviceId: definition.id, state: 'OFFLINE', revision: 0 });
    }
    for (const definition of this.definitions.networks) {
      this.networks.set(definition.id, {
        networkId: definition.id,
        feedState: 'OFFLINE',
        availableCapacity: 0,
        allocatedCapacity: 0,
        revision: 0,
      });
    }
    this.importState(saved);
    this.settle([], 'RESTORE');
  }

  public get revision(): number { return this.revisionValue; }

  public onChange(
    listener: (result: Readonly<UtilityMutationResult>) => void,
  ): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  public getComponentState(componentId: string): UtilityComponentRuntimeState | undefined {
    const state = this.components.get(componentId);
    return state ? cloneComponent(state) : undefined;
  }

  public getConnectionState(connectionId: string): UtilityConnectionRuntimeState | undefined {
    const state = this.connections.get(connectionId);
    return state ? cloneConnection(state) : undefined;
  }

  public getServiceState(serviceId: string): UtilityServiceRuntimeState | undefined {
    const state = this.services.get(serviceId);
    return state ? cloneService(state) : undefined;
  }

  public getNetworkState(networkId: string): UtilityNetworkRuntimeState | undefined {
    const state = this.networks.get(networkId);
    return state ? cloneNetwork(state) : undefined;
  }

  public requiredItemForComponent(componentId: string): string | undefined {
    return this.componentDefinitions.get(componentId)?.repairItemDefinitionId;
  }

  public requiredItemForConnection(connectionId: string): string | undefined {
    return this.connectionDefinitions.get(connectionId)?.repairItemDefinitionId;
  }

  public repairComponent(componentId: string): UtilityMutationResult {
    const state = this.components.get(componentId);
    if (!state) return this.reject('UNKNOWN_COMPONENT');
    if (state.condition === 'OPERATIONAL') return this.reject('COMPONENT_ALREADY_OPERATIONAL');
    const events: UtilityMutationEvent[] = [];
    this.setComponentCondition(componentId, 'OPERATIONAL', events, 'PLAYER_REPAIR');
    this.settle(events, 'PLAYER_REPAIR');
    return this.accept(events);
  }

  public repairConnection(connectionId: string): UtilityMutationResult {
    const state = this.connections.get(connectionId);
    if (!state) return this.reject('UNKNOWN_CONNECTION');
    if (state.state === 'CONNECTED') return this.reject('CONNECTION_ALREADY_CONNECTED');
    const events: UtilityMutationEvent[] = [];
    this.setConnectionState(connectionId, 'CONNECTED', events, 'PLAYER_REPAIR');
    this.settle(events, 'PLAYER_REPAIR');
    return this.accept(events);
  }

  public setComponentEnabled(componentId: string, enabled: boolean): UtilityMutationResult {
    const state = this.components.get(componentId);
    if (!state) return this.reject('UNKNOWN_COMPONENT');
    if (state.enabled === enabled) return this.reject('COMPONENT_ENABLE_STATE_UNCHANGED');
    const events: UtilityMutationEvent[] = [];
    const previousState = state.enabled ? 'ENABLED' : 'DISABLED';
    this.components.set(componentId, { ...state, enabled, revision: state.revision + 1 });
    this.bump();
    events.push(this.event('COMPONENT', componentId, previousState, enabled ? 'ENABLED' : 'DISABLED', 'AUTHORITY_COMMAND'));
    this.settle(events, 'AUTHORITY_COMMAND');
    return this.accept(events);
  }

  public forceComponentCondition(componentId: string, condition: UtilityComponentCondition): UtilityMutationResult {
    const state = this.components.get(componentId);
    if (!state) return this.reject('UNKNOWN_COMPONENT');
    if (state.condition === condition) return this.reject('COMPONENT_CONDITION_UNCHANGED');
    const events: UtilityMutationEvent[] = [];
    this.setComponentCondition(componentId, condition, events, 'DEV_FORCE');
    this.settle(events, 'DEV_FORCE');
    return this.accept(events);
  }

  public resolveFact(factId: string): string | number | boolean | undefined {
    const parts = factId.split('.');
    if (parts[0] !== 'utility') return undefined;
    if (parts[1] === 'component' && parts[3] === 'condition') return this.components.get(parts[2] ?? '')?.condition;
    if (parts[1] === 'component' && parts[3] === 'supplied') return this.components.get(parts[2] ?? '')?.supplied;
    if (parts[1] === 'connection' && parts[3] === 'state') return this.connections.get(parts[2] ?? '')?.state;
    if (parts[1] === 'service' && parts[3] === 'state') return this.services.get(parts[2] ?? '')?.state;
    if (parts[1] === 'network' && parts[3] === 'state') return this.networks.get(parts[2] ?? '')?.feedState;
    if (parts[1] === 'trigger' && parts[3] === 'applied') return this.appliedTriggerIds.has(parts[2] ?? '');
    return undefined;
  }

  public snapshot(): UtilityRuntimeSnapshot {
    return {
      definitionSetId: this.definitions.id,
      revision: this.revisionValue,
      networks: [...this.networks.values()].sort((a, b) => a.networkId.localeCompare(b.networkId)).map(cloneNetwork),
      components: [...this.components.values()].sort((a, b) => a.componentId.localeCompare(b.componentId)).map(cloneComponent),
      connections: [...this.connections.values()].sort((a, b) => a.connectionId.localeCompare(b.connectionId)).map(cloneConnection),
      services: [...this.services.values()].sort((a, b) => a.serviceId.localeCompare(b.serviceId)).map(cloneService),
      appliedTriggerIds: [...this.appliedTriggerIds].sort(),
    };
  }

  public trace(subjectId?: string): readonly UtilityMutationEvent[] {
    return this.recentEvents
      .filter((event) => !subjectId || event.subjectId === subjectId)
      .map((event) => ({ ...event }));
  }

  public exportState(): UtilityNetworkSaveData {
    return {
      version: 1,
      definitionSetId: this.definitions.id,
      revision: this.revisionValue,
      components: [...this.components.values()].map((state) => ({
        componentId: state.componentId,
        condition: state.condition,
        enabled: state.enabled,
        revision: state.revision,
      })),
      connections: [...this.connections.values()].map(cloneConnection),
      services: [...this.services.values()].map(cloneService),
      networks: [...this.networks.values()].map(cloneNetwork),
      appliedTriggerIds: [...this.appliedTriggerIds].sort(),
    };
  }

  private settle(events: UtilityMutationEvent[], reason: string): void {
    for (let pass = 0; pass < 8; pass += 1) {
      this.solve(events, reason);
      const trigger = (this.definitions.oneTimeTriggers ?? []).find((candidate) =>
        !this.appliedTriggerIds.has(candidate.id) && this.triggerConditionMet(candidate.condition));
      if (!trigger) return;
      this.appliedTriggerIds.add(trigger.id);
      this.bump();
      events.push(this.event('TRIGGER', trigger.id, 'ARMED', 'APPLIED', 'AUTHORED_ONE_TIME_TRANSITION'));
      for (const action of trigger.actions) {
        if (action.type === 'SET_COMPONENT_CONDITION') {
          this.setComponentCondition(action.componentId, action.condition, events, `TRIGGER:${trigger.id}`);
        } else {
          this.setConnectionState(action.connectionId, action.state, events, `TRIGGER:${trigger.id}`);
        }
      }
    }
    throw new Error('Utility one-time triggers did not settle within eight passes.');
  }

  private solve(events: UtilityMutationEvent[], reason: string): void {
    for (const network of this.definitions.networks) {
      const componentDefinitions = this.definitions.components.filter((component) => component.networkId === network.id);
      const usable = new Set(componentDefinitions.filter((definition) => {
        const state = this.components.get(definition.id)!;
        return state.enabled && state.condition === 'OPERATIONAL';
      }).map((definition) => definition.id));
      const adjacency = new Map<string, string[]>();
      for (const id of usable) adjacency.set(id, []);
      for (const definition of this.definitions.connections) {
        if (definition.networkId !== network.id || this.connections.get(definition.id)?.state !== 'CONNECTED') continue;
        if (!usable.has(definition.from.componentId) || !usable.has(definition.to.componentId)) continue;
        adjacency.get(definition.from.componentId)!.push(definition.to.componentId);
        adjacency.get(definition.to.componentId)!.push(definition.from.componentId);
      }
      const sources = componentDefinitions.filter((definition) => definition.role === 'SOURCE' && usable.has(definition.id));
      const reachable = new Set<string>(sources.map((source) => source.id));
      const queue = [...reachable];
      while (queue.length > 0) {
        const current = queue.shift()!;
        for (const next of adjacency.get(current) ?? []) {
          if (reachable.has(next)) continue;
          reachable.add(next);
          queue.push(next);
        }
      }
      const availableCapacity = sources.reduce((sum, source) => sum + (source.supplyCapacity ?? 0), 0);
      let remainingCapacity = availableCapacity;
      let allocatedCapacity = 0;
      const allocationById = new Map<string, number>();
      const consumers = componentDefinitions.filter((definition) => definition.role === 'CONSUMER' && reachable.has(definition.id)).sort((left, right) =>
        (right.priority ?? 0) - (left.priority ?? 0) || left.id.localeCompare(right.id));
      for (const consumer of consumers) {
        const demand = consumer.demand ?? 0;
        const allocation = Math.min(demand, remainingCapacity);
        allocationById.set(consumer.id, allocation);
        remainingCapacity -= allocation;
        allocatedCapacity += allocation;
      }
      for (const definition of componentDefinitions) {
        const current = this.components.get(definition.id)!;
        const allocation = allocationById.get(definition.id) ?? 0;
        const supplied = reachable.has(definition.id) &&
          (definition.role !== 'CONSUMER' || allocation > 0);
        if (current.supplied === supplied && Math.abs(current.allocatedCapacity - allocation) < 1e-6) continue;
        this.components.set(definition.id, { ...current, supplied, allocatedCapacity: allocation });
      }
      const serviceStates = this.definitions.services.filter((service) => service.networkId === network.id).map((service) => {
        const componentDefinition = this.componentDefinitions.get(service.componentId)!;
        const component = this.components.get(service.componentId)!;
        const demand = componentDefinition.demand ?? 0;
        const nextState = !component.supplied
          ? 'OFFLINE' as const
          : component.allocatedCapacity + 1e-6 >= demand
            ? 'ONLINE' as const
            : 'DEGRADED' as const;
        const current = this.services.get(service.id)!;
        if (current.state !== nextState) {
          this.services.set(service.id, { ...current, state: nextState, revision: current.revision + 1 });
          this.bump();
          events.push(this.event('SERVICE', service.id, current.state, nextState, reason));
        }
        return nextState;
      });
      const feedState = serviceStates.some((state) => state === 'DEGRADED')
        ? 'BROWNOUT' as const
        : serviceStates.some((state) => state === 'ONLINE')
          ? 'ONLINE' as const
          : 'OFFLINE' as const;
      const currentNetwork = this.networks.get(network.id)!;
      if (currentNetwork.feedState !== feedState ||
        Math.abs(currentNetwork.availableCapacity - availableCapacity) > 1e-6 ||
        Math.abs(currentNetwork.allocatedCapacity - allocatedCapacity) > 1e-6) {
        this.networks.set(network.id, {
          ...currentNetwork,
          feedState,
          availableCapacity,
          allocatedCapacity,
          revision: currentNetwork.revision + 1,
        });
        this.bump();
        if (currentNetwork.feedState !== feedState) {
          events.push(this.event('NETWORK', network.id, currentNetwork.feedState, feedState, reason));
        }
      }
    }
  }

  private triggerConditionMet(condition: Readonly<UtilityTriggerCondition>): boolean {
    if (condition.type === 'COMPONENT_SUPPLIED') {
      return this.components.get(condition.componentId)?.supplied === true;
    }
    return this.services.get(condition.serviceId)?.state === condition.state;
  }

  private setComponentCondition(
    componentId: string,
    condition: UtilityComponentCondition,
    events: UtilityMutationEvent[],
    reason: string,
  ): void {
    const current = this.components.get(componentId)!;
    if (current.condition === condition) return;
    this.components.set(componentId, { ...current, condition, revision: current.revision + 1 });
    this.bump();
    events.push(this.event('COMPONENT', componentId, current.condition, condition, reason));
  }

  private setConnectionState(
    connectionId: string,
    state: UtilityConnectionRuntimeState['state'],
    events: UtilityMutationEvent[],
    reason: string,
  ): void {
    const current = this.connections.get(connectionId)!;
    if (current.state === state) return;
    this.connections.set(connectionId, { ...current, state, revision: current.revision + 1 });
    this.bump();
    events.push(this.event('CONNECTION', connectionId, current.state, state, reason));
  }

  private importState(saved?: Readonly<UtilityNetworkSaveData>): boolean {
    if (saved?.version !== 1 || saved.definitionSetId !== this.definitions.id) return false;
    for (const candidate of saved.components ?? []) {
      const current = this.components.get(candidate.componentId);
      if (!current || !['OPERATIONAL', 'DAMAGED', 'MISSING'].includes(candidate.condition)) continue;
      this.components.set(candidate.componentId, {
        ...current,
        condition: candidate.condition,
        enabled: candidate.enabled === true,
        revision: Number.isSafeInteger(candidate.revision) && candidate.revision >= 0 ? candidate.revision : current.revision,
      });
    }
    for (const candidate of saved.connections ?? []) {
      const current = this.connections.get(candidate.connectionId);
      if (!current || !['CONNECTED', 'BROKEN', 'ISOLATED'].includes(candidate.state)) continue;
      this.connections.set(candidate.connectionId, {
        connectionId: candidate.connectionId,
        state: candidate.state,
        revision: Number.isSafeInteger(candidate.revision) && candidate.revision >= 0 ? candidate.revision : current.revision,
      });
    }
    for (const candidate of saved.services ?? []) {
      const current = this.services.get(candidate.serviceId);
      if (!current || !['OFFLINE', 'DEGRADED', 'ONLINE'].includes(candidate.state)) continue;
      this.services.set(candidate.serviceId, {
        serviceId: candidate.serviceId,
        state: candidate.state,
        revision: Number.isSafeInteger(candidate.revision) && candidate.revision >= 0
          ? candidate.revision
          : current.revision,
      });
    }
    for (const candidate of saved.networks ?? []) {
      const current = this.networks.get(candidate.networkId);
      if (!current || !['OFFLINE', 'BROWNOUT', 'ONLINE'].includes(candidate.feedState)) continue;
      this.networks.set(candidate.networkId, {
        networkId: candidate.networkId,
        feedState: candidate.feedState,
        availableCapacity: Number.isFinite(candidate.availableCapacity)
          ? Math.max(0, candidate.availableCapacity)
          : current.availableCapacity,
        allocatedCapacity: Number.isFinite(candidate.allocatedCapacity)
          ? Math.max(0, candidate.allocatedCapacity)
          : current.allocatedCapacity,
        revision: Number.isSafeInteger(candidate.revision) && candidate.revision >= 0
          ? candidate.revision
          : current.revision,
      });
    }
    for (const triggerId of saved.appliedTriggerIds ?? []) {
      if ((this.definitions.oneTimeTriggers ?? []).some((trigger) => trigger.id === triggerId)) this.appliedTriggerIds.add(triggerId);
    }
    this.revisionValue = Number.isSafeInteger(saved.revision) && saved.revision >= 0 ? saved.revision : 0;
    return true;
  }

  private bump(): void { this.revisionValue += 1; }

  private event(
    subjectKind: UtilityMutationEvent['subjectKind'],
    subjectId: string,
    previousState: string,
    state: string,
    reason: string,
  ): UtilityMutationEvent {
    return { sequence: ++this.eventSequence, subjectKind, subjectId, previousState, state, reason };
  }

  private accept(events: UtilityMutationEvent[]): UtilityMutationResult {
    const result: UtilityMutationResult = {
      accepted: true,
      changed: events.length > 0,
      revision: this.revisionValue,
      events,
    };
    if (result.changed) {
      this.recentEvents.push(...events.map((event) => ({ ...event })));
      if (this.recentEvents.length > 256) {
        this.recentEvents.splice(0, this.recentEvents.length - 256);
      }
      for (const listener of this.listeners) listener(result);
    }
    return result;
  }

  private reject(reason: string): UtilityMutationResult {
    return { accepted: false, changed: false, revision: this.revisionValue, reason, events: [] };
  }
}
