import { revision, type Revision } from '../../netcode/core/NetworkPrimitives';
import type { PackedSnowSample } from '../../land/LandSnowData';
import {
  type SnowBaselinePartPayload,
  type SnowDeltaPayload,
  snowTileChecksum,
  unpackSnowIndexRuns,
  unpackSnowSampleRuns,
} from '../../netcode/protocol/SnowReplication';
import { LAND_SNOW_BASELINE_ID, LAND_SNOW_FORMAT_VERSION } from '../../land/LandSnowData';

export interface ClientSnowTileSnapshot {
  tileX: number;
  tileZ: number;
  revision: Revision;
  checksum: string;
  changes: readonly PackedSnowSample[];
}

export interface SnowReplicationClientDiagnostics {
  completedBaselines: number;
  baselinePartsAccepted: number;
  deltasAccepted: number;
  staleDeltas: number;
  revisionMismatches: number;
  checksumMismatches: number;
  resyncRequests: number;
  replicatedTiles: number;
  stagedBaselineParts: number;
}

interface MutableClientSnowTile {
  tileX: number;
  tileZ: number;
  revision: Revision;
  checksum: string;
  changes: Map<number, PackedSnowSample>;
}

interface BaselineTransfer {
  transferId: string;
  scope: 'FULL' | 'TILE_RESYNC';
  baselineId: string;
  formatVersion: number;
  worldDatasetHash: string;
  partCount: number;
  serverTick: SnowBaselinePartPayload['serverTick'];
  parts: Map<number, SnowBaselinePartPayload>;
}

export interface SnowResyncRequest {
  tileX: number;
  tileZ: number;
  observedRevision: Revision;
}

const key = (tileX: number, tileZ: number): string => `${tileX},${tileZ}`;

/** Canonical sparse snow state with staged baseline and revision convergence. */
export class SnowReplicationClient {
  private readonly tiles = new Map<string, MutableClientSnowTile>();
  private readonly resync = new Map<string, SnowResyncRequest>();
  private transfer?: BaselineTransfer;
  private lastDeltaSequence = 0;
  private readonly stats = {
    completedBaselines: 0,
    baselinePartsAccepted: 0,
    deltasAccepted: 0,
    staleDeltas: 0,
    revisionMismatches: 0,
    checksumMismatches: 0,
    resyncRequests: 0,
  };

  public constructor(private readonly expectedWorldDatasetHash: string) {}

  public applyBaselinePart(
    payload: Readonly<SnowBaselinePartPayload>,
  ): { accepted: boolean; completed: boolean; updatedTiles: readonly ClientSnowTileSnapshot[] } {
    if (
      payload.baselineId !== LAND_SNOW_BASELINE_ID ||
      payload.formatVersion !== LAND_SNOW_FORMAT_VERSION ||
      payload.worldDatasetHash !== this.expectedWorldDatasetHash
    ) return { accepted: false, completed: false, updatedTiles: [] };
    if (!this.transfer || this.transferIdChanged(payload)) {
      this.transfer = {
        baselineId: payload.baselineId,
        transferId: payload.transferId,
        scope: payload.scope,
        formatVersion: payload.formatVersion,
        worldDatasetHash: payload.worldDatasetHash,
        partCount: payload.partCount,
        serverTick: payload.serverTick,
        parts: new Map(),
      };
    }
    if (
      this.transfer.partCount !== payload.partCount ||
      this.transfer.serverTick !== payload.serverTick ||
      this.transfer.parts.has(payload.partIndex)
    ) return { accepted: false, completed: false, updatedTiles: [] };
    this.transfer.parts.set(payload.partIndex, payload as SnowBaselinePartPayload);
    this.stats.baselinePartsAccepted += 1;
    if (this.transfer.parts.size !== this.transfer.partCount) {
      return { accepted: true, completed: false, updatedTiles: [] };
    }
    const next = new Map<string, MutableClientSnowTile>();
    for (let index = 0; index < this.transfer.partCount; index += 1) {
      const part = this.transfer.parts.get(index);
      if (!part) return { accepted: false, completed: false, updatedTiles: [] };
      for (const tile of part.tiles) {
        const changes = unpackSnowSampleRuns(tile.runs);
        if (
          next.has(key(tile.tileX, tile.tileZ)) ||
          snowTileChecksum(tile.tileX, tile.tileZ, tile.revision, changes) !== tile.checksum
        ) {
          this.stats.checksumMismatches += 1;
          this.transfer = undefined;
          return { accepted: false, completed: false, updatedTiles: [] };
        }
        next.set(key(tile.tileX, tile.tileZ), {
          tileX: tile.tileX,
          tileZ: tile.tileZ,
          revision: tile.revision,
          checksum: tile.checksum,
          changes: new Map(changes.map((change) => [change[0], change])),
        });
      }
    }
    const scope = this.transfer.scope;
    if (scope === 'FULL') {
      this.tiles.clear();
      for (const [tileKey, tile] of next) this.tiles.set(tileKey, tile);
      this.resync.clear();
      this.lastDeltaSequence = 0;
    } else {
      for (const [tileKey, tile] of next) {
        this.tiles.set(tileKey, tile);
        this.resync.delete(tileKey);
      }
    }
    this.transfer = undefined;
    this.stats.completedBaselines += 1;
    return {
      accepted: true,
      completed: true,
      updatedTiles: scope === 'TILE_RESYNC'
        ? [...next.values()].map((tile) => this.cloneTile(tile))
        : this.listTiles(),
    };
  }

  public applyDelta(
    payload: Readonly<SnowDeltaPayload>,
  ): { accepted: boolean; updatedTiles: readonly ClientSnowTileSnapshot[] } {
    if (payload.deltaSequence <= this.lastDeltaSequence) {
      this.stats.staleDeltas += 1;
      return { accepted: false, updatedTiles: [] };
    }
    this.lastDeltaSequence = payload.deltaSequence;
    const updated: ClientSnowTileSnapshot[] = [];
    for (const delta of payload.tiles) {
      const tileKey = key(delta.tileX, delta.tileZ);
      const existing = this.tiles.get(tileKey);
      const observedRevision = existing?.revision ?? revision(0);
      if (observedRevision !== delta.baseRevision) {
        this.stats.revisionMismatches += 1;
        this.queueResync(delta.tileX, delta.tileZ, observedRevision);
        continue;
      }
      const changes = new Map(existing?.changes ?? []);
      for (const index of unpackSnowIndexRuns(delta.removedRuns)) {
        changes.delete(index);
      }
      for (const change of unpackSnowSampleRuns(delta.runs)) {
        changes.set(change[0], change);
      }
      const full = [...changes.values()].sort((a, b) => a[0] - b[0]);
      const checksum = snowTileChecksum(
        delta.tileX,
        delta.tileZ,
        delta.revision,
        full,
      );
      if (checksum !== delta.checksum) {
        this.stats.checksumMismatches += 1;
        this.queueResync(delta.tileX, delta.tileZ, observedRevision);
        continue;
      }
      const next: MutableClientSnowTile = {
        tileX: delta.tileX,
        tileZ: delta.tileZ,
        revision: delta.revision,
        checksum,
        changes,
      };
      this.tiles.set(tileKey, next);
      this.resync.delete(tileKey);
      updated.push(this.cloneTile(next));
    }
    this.stats.deltasAccepted += 1;
    return { accepted: true, updatedTiles: updated };
  }

  public listTiles(): readonly ClientSnowTileSnapshot[] {
    return [...this.tiles.values()]
      .sort((a, b) => a.tileZ - b.tileZ || a.tileX - b.tileX)
      .map((tile) => this.cloneTile(tile));
  }

  public drainResyncRequests(): readonly SnowResyncRequest[] {
    const requests = [...this.resync.values()];
    this.resync.clear();
    return requests;
  }

  public diagnostics(): SnowReplicationClientDiagnostics {
    return {
      ...this.stats,
      replicatedTiles: this.tiles.size,
      stagedBaselineParts: this.transfer?.parts.size ?? 0,
    };
  }

  public reset(): void {
    this.tiles.clear();
    this.resync.clear();
    this.transfer = undefined;
    this.lastDeltaSequence = 0;
  }

  private transferIdChanged(payload: Readonly<SnowBaselinePartPayload>): boolean {
    return this.transfer?.transferId !== payload.transferId ||
      this.transfer.scope !== payload.scope;
  }

  private queueResync(tileX: number, tileZ: number, observedRevision: Revision): void {
    const tileKey = key(tileX, tileZ);
    if (this.resync.has(tileKey)) return;
    this.resync.set(tileKey, { tileX, tileZ, observedRevision });
    this.stats.resyncRequests += 1;
  }

  private cloneTile(tile: MutableClientSnowTile): ClientSnowTileSnapshot {
    return {
      tileX: tile.tileX,
      tileZ: tile.tileZ,
      revision: tile.revision,
      checksum: tile.checksum,
      changes: [...tile.changes.values()]
        .sort((a, b) => a[0] - b[0])
        .map((change) => [...change] as PackedSnowSample),
    };
  }
}
