export class WildernessSurvivalSimulation {
  public selectedTool: WildernessTool = 'HANDS';
  /** Presentation-owned focus. It is intentionally transient and not saved. */
  private focusedTargetId?: string;
  public readonly quickSlots: WildernessTool[] = [
    'HANDS',
    'STONE_AXE',
    'FLINT_TOOL',
    'CAMP_CRAFT',
    'BUILD_KIT',
    'TRAP_KIT',
  ];
  public selectedQuickSlot = 0;
  public readonly inventory: WildernessInventory = cloneInventory();
  public readonly toolCondition: WildernessToolCondition = {
    stoneAxe: 28,
    flintTool: 32,
  };
  public readonly condition: WildernessCondition = {
    warmth: 0.78,
    energy: 0.9,
    satiety: 0.86,
    wetness: 0.08,
    sheltered: false,
    nearFire: false,
    elapsedSeconds: 0,
  };
  public readonly resources = resourceNodes();
  public readonly animals = animalStates();
  public readonly firePits: WildernessFirePitState[] = [];
  public readonly shelters: WildernessShelterState[] = [];
  public readonly snares: WildernessSnareState[] = [];
  public readonly fishing: WildernessFishingState = {
    status: 'IDLE',
    elapsedSeconds: 0,
    biteAtSeconds: 0,
    reelProgress: 0,
    reelTarget: 0.5,
    missedPulls: 0,
  };
  public readonly iceHoles: WildernessIceHoleState[] = [];
  public readonly foodBuffs: WildernessFoodBuffState[] = [];
  public readonly progression: WildernessProgressionState =
    createInitialWildernessProgression();
  public readonly ecosystemStocks: WildernessEcosystemStocks = {
    fish: 8,
    smallGame: 5,
  };
  public readonly worldItems: WildernessWorldItemState[] = [];
  private readonly branchMaterials: WildernessWoodMaterial[] = [];
  private readonly logMaterials: WildernessWoodMaterial[] = [];
  private nextFuelPieceId = 1;
  private nextWorldItemId = 1;
  private nextIceHoleId = 1;

  public constructor(saved?: Readonly<WildernessSurvivalSaveData>) {
    if (saved) this.importState(saved);
  }

  public isInside(x: number, z: number, padding = 0): boolean {
    return Math.hypot(
      x - WILDERNESS_SURVIVAL_REGION.centerX,
      z - WILDERNESS_SURVIVAL_REGION.centerZ,
    ) <= WILDERNESS_SURVIVAL_REGION.radius + padding;
  }

  public isNearCreek(x: number, z: number): boolean {
    return isWildernessFrozenWaterAt(x, z);
  }

  public isSkillUnlocked(skill: WildernessSkillId): boolean {
    return this.progression.unlockedSkills.includes(skill);
  }

  public hasMilestone(milestone: WildernessMilestoneId): boolean {
    return this.progression.completedMilestones.includes(milestone);
  }

  public clearPlan(): void {
    if (WILDERNESS_PLAN_ORDER.includes(this.selectedTool)) {
      this.selectTool('HANDS');
    }
  }

  public fishingTiming(): Readonly<{
    marker: number;
    target: number;
    tolerance: number;
    progress: number;
  }> | undefined {
    if (this.fishing.status !== 'HOOKED') return undefined;
    const progress = clamp(this.fishing.reelProgress ?? 0, 0, 1);
    // One calm sweep takes roughly 3.5 seconds. The old 1.5 second sweep was
    // closer to a reaction test than cozy ice fishing.
    const marker = 0.5 +
      Math.sin(this.fishing.elapsedSeconds * (1.55 + progress * 0.22)) * 0.46;
    return {
      marker,
      target: clamp(this.fishing.reelTarget ?? 0.5, 0.18, 0.82),
      tolerance: this.hasFoodBuff('FISHING_FOCUS') ? 0.3 : 0.24,
      progress,
    };
  }

  public hasFoodBuff(id: string): boolean {
    return this.foodBuffs.some((buff) =>
      buff.id === id && buff.remainingSeconds > 0);
  }

  public canWalkAt(x: number, z: number, radius = 0.18): boolean {
    if (isWildernessOpenWaterAt(x, z, radius * 0.7)) return false;
    for (const node of this.resources) {
      if (node.state === 'DEPLETED' || node.kind === 'FALLEN_BRANCHES' ||
        node.kind === 'BERRY_SHRUB') continue;
      const obstacleRadius = node.kind === 'TREE'
        ? 0.42 * node.scale
        : 0.62 * node.scale;
      if (Math.hypot(x - node.x, z - node.z) < obstacleRadius + radius) {
        return false;
      }
    }
    return true;
  }

  public treeGrowthScale(node: Readonly<WildernessResourceNode>): number {
    if (node.kind !== 'TREE') return 1;
    if (node.state !== 'DEPLETED') return 1;
    const age = 1 - clamp(
      node.regrowSeconds / WILDERNESS_TREE_REGROW_SECONDS,
      0,
      1,
    );
    // The stump rests for two days, then a readable sapling grows smoothly
    // through the remaining five rather than popping between models.
    if (age <= 2 / 7) return 0;
    return 0.12 + smoothstep(2 / 7, 1, age) * 0.88;
  }

  /**
   * Dense scenery stays instanced and simulation-free until the player takes
   * an interest in one tree. Promotion makes that exact visual tree a normal,
   * persistent resource without eagerly simulating the whole forest.
   */
  public promoteSceneryTree(index: number): WildernessResourceNode | undefined {
    const scenery = WILDERNESS_SCENERY_TREES[index];
    if (!scenery) return undefined;
    const id = `wild-scenery-tree-${index}`;
    const existing = this.resources.find((node) => node.id === id);
    if (existing) return existing;
    const chopHits = 7 + Math.floor(hash2D(index, 1913, 1931) * 4);
    const node: WildernessResourceNode = {
      id,
      kind: 'TREE',
      x: scenery.x,
      z: scenery.z,
      scale: scenery.scale,
      health: chopHits,
      maxHealth: chopHits,
      state: 'READY',
      fallHeading: scenery.heading,
      fallProgress: 0,
      stock: 0,
      regrowSeconds: 0,
      miningHits: 0,
      woodMaterial: (['SPRUCE', 'PINE', 'BIRCH'] as const)[index % 3],
    };
    this.resources.push(node);
    return node;
  }

  public selectTool(tool: WildernessTool): void {
    this.selectedTool = tool;
    const slot = this.quickSlots.indexOf(tool);
    if (slot >= 0) this.selectedQuickSlot = slot;
  }

  public setFocusedTargetId(targetId: string | undefined): void {
    this.focusedTargetId = targetId;
  }

  public getFocusedTargetId(): string | undefined {
    return this.focusedTargetId;
  }

  public selectQuickSlot(index: number): void {
    const resolved = Math.round(clamp(index, 0, this.quickSlots.length - 1));
    this.selectedQuickSlot = resolved;
    this.selectedTool = this.quickSlots[resolved] ?? 'HANDS';
  }

  public assignQuickSlot(index: number, tool: WildernessTool): void {
    if (!WILDERNESS_TOOL_ORDER.includes(tool)) return;
    const resolved = Math.round(clamp(index, 0, this.quickSlots.length - 1));
    this.quickSlots[resolved] = tool;
    if (this.selectedQuickSlot === resolved) this.selectedTool = tool;
  }

  public dropInventoryItem(
    kind: WildernessPortableItemKind,
    x: number,
    z: number,
    heading: number,
  ): boolean {
    const inventoryKey = this.inventoryKeyForPortableItem(kind);
    if (this.inventory[inventoryKey] <= 0) return false;
    let material: WildernessWoodMaterial = 'SPRUCE';
    if (kind === 'BRANCH' || kind === 'LOG') {
      const taken = this.takeWood(kind, 1);
      if (taken.length === 0) return false;
      material = taken[0]!;
    } else {
      this.inventory[inventoryKey] -= 1;
    }
    this.worldItems.push({
      id: `wild-world-drop-${this.nextWorldItemId++}`,
      kind,
      ...(kind === 'BRANCH' || kind === 'LOG' ? { material } : {}),
      x: x + Math.sin(heading) * 1.05,
      z: z + Math.cos(heading) * 1.05,
      heading: heading + Math.PI * 0.5,
      quantity: 1,
    });
    return true;
  }

  /**
   * Tools are affordances of the nearby target, not abstract quick-slot kits.
   * A selected plan survives while travelling, but any readable world target
   * temporarily wins and supplies its own appropriate tool.
   */
  private resolveContextualTool(
    playerX: number,
    playerZ: number,
  ): WildernessTool {
    const focusedTargetId = this.validFocusedTargetId(playerX, playerZ);
    const hasPickup = this.worldItems.some((item) =>
      Math.hypot(item.x - playerX, item.z - playerZ) <= 2.15 &&
      (!focusedTargetId || item.id === focusedTargetId));
    if (hasPickup) return 'HANDS';

    const focusedResource = focusedTargetId
      ? this.resources.find((node) => node.id === focusedTargetId)
      : undefined;
    if (focusedResource?.kind === 'TREE') return 'STONE_AXE';
    if (focusedResource?.kind === 'ROCK') return 'FLINT_TOOL';
    if (focusedResource) return 'HANDS';

    if (focusedTargetId?.startsWith('wild-fire:')) {
      const fire = this.firePits[Number(focusedTargetId.slice(10))];
      return fire?.stage !== 'LIT' && (fire?.layStage ?? 'HOLLOW') === 'TINDER'
        ? 'FLINT_TOOL'
        : 'HANDS';
    }
    if (
      focusedTargetId?.startsWith('wild-shelter:') ||
      focusedTargetId?.startsWith('wild-snare:') ||
      focusedTargetId?.startsWith('wild-ice-hole:')
    ) return 'HANDS';

    const threat = this.animals.some((animal) =>
      (animal.species === 'WOLF' || animal.species === 'BEAR' ||
        animal.species === 'POLAR_BEAR') &&
      animal.retreatSeconds <= 0 &&
      (animal.behavior === 'WARN' || animal.behavior === 'CHARGE') &&
      Math.hypot(animal.x - playerX, animal.z - playerZ) <= 2.45);
    if (threat) return 'STONE_AXE';

    // A building or trapping plan is an explicit placement intention. It may
    // override a nearby warm camp, otherwise the fire's passive tend/cook
    // action would make it impossible to add a shelter beside that camp.
    if (
      !focusedTargetId &&
      (
        this.selectedTool === 'BUILD_KIT' ||
        this.selectedTool === 'TRAP_KIT'
      )
    ) return this.selectedTool;

    const fire = this.firePits
      .map((candidate) => ({
        candidate,
        distance: Math.hypot(candidate.x - playerX, candidate.z - playerZ),
      }))
      .filter((entry) => entry.distance <= 3.1)
      .filter((entry) => !focusedTargetId ||
        focusedTargetId === `wild-fire:${this.firePits.indexOf(entry.candidate)}`)
      .sort((left, right) => left.distance - right.distance)[0]?.candidate;
    if (fire) {
      return fire.stage !== 'LIT' && (fire.layStage ?? 'HOLLOW') === 'TINDER'
        ? 'FLINT_TOOL'
        : 'HANDS';
    }

    const resource = this.resources
      .filter((node) => {
        if (node.kind === 'TREE') return node.state === 'READY' || node.state === 'FALLING';
        return node.state === 'READY';
      })
      .map((node) => ({
        node,
        distance: Math.hypot(node.x - playerX, node.z - playerZ),
      }))
      .filter((entry) => entry.distance <= (
        entry.node.kind === 'TREE' ? 2.4 : 2.05
      ))
      .filter((entry) => !focusedTargetId || entry.node.id === focusedTargetId)
      .sort((left, right) => left.distance - right.distance)[0]?.node;
    if (resource?.kind === 'TREE') return 'STONE_AXE';
    if (resource?.kind === 'ROCK') return 'FLINT_TOOL';
    if (resource) return 'HANDS';

    if (
      this.isSkillUnlocked('ICE_FISHING') &&
      this.isNearCreek(playerX, playerZ)
    ) {
      const openHole = this.iceHoles.some((hole) =>
        hole.open && Math.hypot(hole.x - playerX, hole.z - playerZ) <= 2.6);
      return openHole ? 'HANDS' : 'STONE_AXE';
    }
    return WILDERNESS_PLAN_ORDER.includes(this.selectedTool)
      ? this.selectedTool
      : 'HANDS';
  }

  public resolveInteraction(
    playerX: number,
    playerZ: number,
    heading: number,
  ): WildernessInteractionView {
    const focusedTargetId = this.validFocusedTargetId(playerX, playerZ);
    const contextTool = this.resolveContextualTool(playerX, playerZ);
    if (contextTool === 'STONE_AXE' && this.toolCondition.stoneAxe <= 0) {
      const enabled = this.inventory.stone >= 1 && this.inventory.fiber >= 1;
      return {
        label: enabled
          ? 'RE-HAFT STONE AXE · 1 STONE + 1 FIBER'
          : 'STONE AXE WORN · NEED 1 STONE + 1 FIBER',
        enabled,
        kind: 'MAINTAIN_TOOL',
        requiredTool: 'STONE_AXE',
      };
    }
    if (contextTool === 'HANDS') {
      const pickup = this.worldItems
        .map((item) => ({
          item,
          distance: Math.hypot(item.x - playerX, item.z - playerZ),
        }))
        .filter((entry) => entry.distance <= 2.15)
        .filter((entry) => !focusedTargetId || entry.item.id === focusedTargetId)
        .sort((left, right) => left.distance - right.distance)[0]?.item;
      if (pickup) {
        return {
          label: pickup.kind === 'LOG'
            ? 'PICK UP FALLEN LOG'
            : pickup.kind === 'TINDER'
              ? 'PICK UP DRY TINDER'
              : 'PICK UP FALLEN BRANCHES',
          enabled: true,
          kind: 'PICKUP_WORLD_ITEM',
          targetId: pickup.id,
          requiredTool: 'HANDS',
        };
      }
    }
    if (contextTool === 'FLINT_TOOL' && this.toolCondition.flintTool <= 0) {
      const usesFlint = this.inventory.flint >= 1;
      const usesChips = this.inventory.stoneChips >= 3;
      const enabled = (usesFlint || usesChips) && this.inventory.fiber >= 1;
      return {
        label: enabled
          ? usesFlint
            ? 'KNAP A NEW FLINT EDGE · 1 FLINT + 1 FIBER'
            : 'BIND A CHIP EDGE · 3 CHIPS + 1 FIBER'
          : 'FLINT EDGE WORN · NEED FLINT OR 3 CHIPS + FIBER',
        enabled,
        kind: 'MAINTAIN_TOOL',
        requiredTool: 'FLINT_TOOL',
      };
    }
    if (contextTool === 'STONE_AXE') {
      const defensiveTarget = this.animals
        .filter((animal) =>
          (animal.species === 'WOLF' || animal.species === 'BEAR' ||
            animal.species === 'POLAR_BEAR') &&
          animal.retreatSeconds <= 0 &&
          (animal.behavior === 'WARN' || animal.behavior === 'CHARGE')
        )
        .map((animal) => ({
          animal,
          distance: Math.hypot(animal.x - playerX, animal.z - playerZ),
        }))
        .filter((entry) => entry.distance <= 2.45)
        .filter((entry) => !focusedTargetId ||
          entry.animal.id === focusedTargetId)
        .sort((a, b) => a.distance - b.distance)[0]?.animal;
      if (defensiveTarget) {
        return {
          label: `DEFEND · DRIVE OFF ${defensiveTarget.species.replace('_', ' ')}`,
          enabled: true,
          kind: 'DEFEND',
          targetId: defensiveTarget.id,
          requiredTool: 'STONE_AXE',
        };
      }
    }
    const targetKinds: readonly WildernessResourceKind[] =
      contextTool === 'HANDS'
        ? ['FALLEN_BRANCHES', 'BERRY_SHRUB', 'BURIED_FOOD']
        : contextTool === 'STONE_AXE'
          ? ['TREE']
          : contextTool === 'FLINT_TOOL'
            ? ['ROCK']
            : [];
    const nearest = this.resources
      .filter((node) =>
        targetKinds.includes(node.kind) && (
          node.kind === 'TREE'
            ? node.state === 'READY' || node.state === 'FALLING'
            : node.state === 'READY'
        ))
      .map((node) => ({
        node,
        distance: Math.hypot(node.x - playerX, node.z - playerZ),
      }))
      .filter((entry) => entry.distance <= (
        entry.node.kind === 'TREE' ? 2.4 : 2.05
      ))
      .filter((entry) => !focusedTargetId || entry.node.id === focusedTargetId)
      .sort((a, b) => a.distance - b.distance)[0]?.node;
    if (contextTool === 'HANDS' && nearest && (
      nearest.kind === 'FALLEN_BRANCHES' || nearest.kind === 'BERRY_SHRUB'
    )) {
      return {
        label: nearest.kind === 'FALLEN_BRANCHES'
          ? 'GATHER DRY BRANCHES'
          : 'PICK FROST BERRIES',
        enabled: true,
        kind: 'GATHER',
        targetId: nearest.id,
        requiredTool: 'HANDS',
      };
    }
    if (contextTool === 'HANDS' && nearest?.kind === 'BURIED_FOOD') {
      return {
        label: 'BRUSH ASIDE SNOW · FORAGE FOR WINTER ROOTS',
        enabled: true,
        kind: 'GATHER_BURIED_FOOD',
        targetId: nearest.id,
        requiredTool: 'HANDS',
      };
    }
    if (contextTool === 'STONE_AXE' && nearest?.kind === 'TREE') {
      return {
        label: nearest.state === 'FALLING' ? 'TREE IS FALLING…' : 'CHOP TREE',
        enabled: nearest.state === 'READY',
        kind: 'CHOP',
        targetId: nearest.id,
        requiredTool: 'STONE_AXE',
      };
    }
    if (contextTool === 'FLINT_TOOL' && nearest?.kind === 'ROCK') {
      return {
        label: 'BREAK SURFACE ROCK',
        enabled: true,
        kind: 'MINE',
        targetId: nearest.id,
        requiredTool: 'FLINT_TOOL',
      };
    }
    const nearbyFireEntry = this.firePits
      .map((fire, index) => ({
        fire,
        index,
        distance: Math.hypot(fire.x - playerX, fire.z - playerZ),
      }))
      .filter((entry) => entry.distance <= 3.1)
      .filter((entry) => !focusedTargetId ||
        focusedTargetId === `wild-fire:${entry.index}`)
      .sort((a, b) => a.distance - b.distance)[0];
    const nearbyFire = nearbyFireEntry?.fire;
    const nearbyFireTargetId = nearbyFireEntry
      ? `wild-fire:${nearbyFireEntry.index}`
      : undefined;
    if (
      nearbyFire &&
      nearbyFire.stage !== 'LIT' &&
      (contextTool === 'HANDS' || contextTool === 'FLINT_TOOL')
    ) {
      const layStage = nearbyFire.layStage ?? 'HOLLOW';
      if (
        contextTool === 'HANDS' &&
        layStage === 'HOLLOW'
      ) {
        return {
          label: this.inventory.branches >= 2
            ? 'PLACE 2 DRY BRANCHES IN THE FIRE LAY'
            : 'GATHER 2 DRY BRANCHES FOR THE FIRE LAY',
          enabled: this.inventory.branches >= 2,
          kind: 'PLACE_FIRE_WOOD',
          targetId: nearbyFireTargetId,
          x: nearbyFire.x,
          z: nearbyFire.z,
          requiredTool: 'HANDS',
        };
      }
      if (
        contextTool === 'HANDS' &&
        layStage === 'WOOD'
      ) {
        return {
          label: this.inventory.tinder >= 1
            ? 'PLACE DRY TINDER OVER THE KINDLING'
            : 'FIND DRY TINDER BENEATH FALLEN BRANCHES',
          enabled: this.inventory.tinder >= 1,
          kind: 'PLACE_TINDER',
          targetId: nearbyFireTargetId,
          x: nearbyFire.x,
          z: nearbyFire.z,
          requiredTool: 'HANDS',
        };
      }
      if (contextTool === 'FLINT_TOOL' && layStage === 'TINDER') {
        const progress = clamp(nearbyFire.ignitionProgress ?? 0, 0, 1);
        return {
          label: progress <= 0
            ? 'STRIKE FLINT INTO THE TINDER'
            : `KEEP THE SPARK ALIVE · ${Math.round(progress * 100)}%`,
          enabled: this.toolCondition.flintTool > 0,
          kind: 'LIGHT_FIRE',
          targetId: nearbyFireTargetId,
          x: nearbyFire.x,
          z: nearbyFire.z,
          requiredTool: 'FLINT_TOOL',
        };
      }
    }
    if (nearbyFire?.stage === 'LIT' && contextTool === 'HANDS') {
      const fireNeedsFuel = (nearbyFire.heatLevel ?? 0) < 0.42 &&
        (this.inventory.branches > 0 || this.inventory.logs > 0);
      if (
        !fireNeedsFuel &&
        this.isSkillUnlocked('COOKING') &&
        (this.inventory.fish > 0 || this.inventory.smallGame > 0 || this.inventory.roots > 0)
      ) {
        return {
          label: this.inventory.fish > 0
            ? 'COOK EMBER FISH'
            : this.inventory.roots > 0
              ? 'ROAST A WINTER ROOT'
              : 'ROAST SMALL GAME',
          enabled: true,
          kind: 'COOK_MEAL',
          targetId: nearbyFireTargetId,
          x: nearbyFire.x,
          z: nearbyFire.z,
          requiredTool: 'HANDS',
        };
      }
      const needsKindling = (nearbyFire.heatLevel ?? 0) < 0.36;
      const fuelForm: WildernessFireFuelForm =
        needsKindling && this.inventory.branches > 0
          ? 'BRANCH'
          : this.inventory.logs > 0
            ? 'LOG'
            : 'BRANCH';
      const amount = fuelForm === 'LOG' ? this.inventory.logs : this.inventory.branches;
      return {
        label: amount > 0
          ? `ADD ${fuelForm === 'LOG' ? 'A LONG-BURNING LOG' : 'QUICK KINDLING'}`
          : `NO ${fuelForm === 'LOG' ? 'LOG' : 'DRY BRANCH'} IN BACKPACK`,
        enabled: amount > 0,
        kind: 'FUEL_FIRE',
        targetId: nearbyFireTargetId,
        x: nearbyFire.x,
        z: nearbyFire.z,
        requiredTool: fuelForm,
        fuelForm,
      };
    }
    const focusedShelterIndex = focusedTargetId?.startsWith('wild-shelter:')
      ? Number(focusedTargetId.slice(15))
      : -1;
    const focusedShelter = focusedShelterIndex >= 0
      ? this.shelters[focusedShelterIndex]
      : undefined;
    if (focusedShelter) {
      return this.resolveShelterInteraction(
        focusedShelter,
        focusedShelterIndex,
        playerX,
        playerZ,
        heading,
      );
    }
    if (
      contextTool === 'HANDS' &&
      this.inventory.berries > 0 &&
      this.condition.satiety < 0.84
    ) {
      return {
        label: 'EAT A HANDFUL OF FROST BERRIES',
        enabled: true,
        kind: 'EAT_BERRIES',
        requiredTool: 'HANDS',
      };
    }
    if (
      this.isSkillUnlocked('ICE_FISHING') &&
      this.isNearCreek(playerX, playerZ)
    ) {
      const nearbyHole = this.iceHoles
        .map((hole) => ({
          hole,
          distance: Math.hypot(hole.x - playerX, hole.z - playerZ),
        }))
        .filter((entry) => entry.distance <= 2.6)
        .sort((left, right) => left.distance - right.distance)[0]?.hole;
      if (!nearbyHole?.open) {
        const targetX = nearbyHole?.x ?? playerX + Math.sin(heading) * 0.82;
        const targetZ = nearbyHole?.z ?? playerZ + Math.cos(heading) * 0.82;
        const validWater = this.isNearCreek(targetX, targetZ);
        const progress = nearbyHole?.progress ?? 0;
        return {
          label: !validWater
            ? 'STEP CLOSER TO SOLID ICE'
            : progress <= 0
              ? 'CHIP A SMALL FISHING HOLE'
              : `KEEP OPENING THE ICE · ${Math.round(progress * 100)}%`,
          enabled: validWater && this.toolCondition.stoneAxe > 0,
          kind: 'CHIP_ICE_HOLE',
          targetId: nearbyHole?.id,
          x: targetX,
          z: targetZ,
          requiredTool: 'STONE_AXE',
        };
      }
      const activeAtThisHole = !this.fishing.activeHoleId ||
        this.fishing.activeHoleId === nearbyHole.id;
      if (activeAtThisHole && this.fishing.status === 'BITE') {
        return {
          label: 'SET THE HOOK!', enabled: true, kind: 'HOOK_FISH',
          targetId: nearbyHole.id, x: nearbyHole.x, z: nearbyHole.z,
          requiredTool: 'HANDS',
        };
      }
      if (activeAtThisHole && this.fishing.status === 'HOOKED') {
        const timing = this.fishingTiming();
        const ready = timing
          ? Math.abs(timing.marker - timing.target) <= timing.tolerance
          : false;
        return {
          label: ready ? 'PULL THE LINE!' : 'LET THE LINE BREATHE…',
          enabled: true,
          kind: 'REEL_FISH',
          targetId: nearbyHole.id,
          x: nearbyHole.x,
          z: nearbyHole.z,
          requiredTool: 'HANDS',
        };
      }
      if (activeAtThisHole && this.fishing.status === 'WAITING') {
        return {
          label: 'WATCH THE LINE FOR A BITE…', enabled: false, kind: 'WAIT',
          targetId: nearbyHole.id, x: nearbyHole.x, z: nearbyHole.z,
        };
      }
      if (this.fishing.status !== 'IDLE') {
        return {
          label: 'YOUR LINE IS ACTIVE AT ANOTHER ICE HOLE',
          enabled: false,
          kind: 'WAIT',
        };
      }
      if (this.ecosystemStocks.fish <= 0) {
        return {
          label: 'THIS WATER NEEDS TIME TO RECOVER',
          enabled: false,
          kind: 'NONE',
        };
      }
      return {
        label: 'LOWER THE HAND LINE THROUGH THE ICE',
        enabled: true,
        kind: 'CAST_LINE',
        targetId: nearbyHole.id,
        x: nearbyHole.x,
        z: nearbyHole.z,
        requiredTool: 'HANDS',
      };
    }
    if (contextTool === 'CAMP_CRAFT') {
      if (!nearbyFire) {
        if (this.firePits.length >= 4) {
          return {
            label: 'FOUR CAMPS MARK THIS PROTOTYPE REGION',
            enabled: false,
            kind: 'NONE',
          };
        }
        const x = playerX + Math.sin(heading) * 1.55;
        const z = playerZ + Math.cos(heading) * 1.55;
        const clear = this.canWalkAt(x, z, 0.72);
        return {
          label: clear ? 'DIG A FIRE PIT IN THE SNOW' : 'FIND A CLEAR PATCH FOR THE FIRE',
          enabled: clear,
          kind: 'DIG_FIRE_PIT',
          x,
          z,
          requiredTool: 'HANDS',
        };
      }
    }
    if (contextTool === 'BUILD_KIT') {
      const shelter = this.shelters
        .find((candidate) => Math.hypot(candidate.x - playerX, candidate.z - playerZ) <= 5);
      return this.resolveShelterInteraction(
        shelter,
        shelter ? this.shelters.indexOf(shelter) : -1,
        playerX,
        playerZ,
        heading,
      );
    }
    if (contextTool === 'TRAP_KIT') {
      const snare = this.snares.find((candidate) =>
        Math.hypot(candidate.x - playerX, candidate.z - playerZ) <= 2.4);
      if (snare?.caught) {
        return { label: 'COLLECT RABBIT FROM SNARE', enabled: true, kind: 'COLLECT_SNARE' };
      }
      const enabled = this.inventory.fiber >= 1 && this.inventory.branches >= 1;
      const x = playerX + Math.sin(heading) * 1.5;
      const z = playerZ + Math.cos(heading) * 1.5;
      const placementClear = this.canWalkAt(x, z, 0.45);
      return {
        label: !placementClear
          ? 'FIND A CLEAR TRACKSIDE PATCH'
          : enabled ? 'PLACE RABBIT SNARE' : 'NEED 1 FIBER + 1 BRANCH',
        enabled: enabled && placementClear,
        kind: 'PLACE_SNARE',
        x,
        z,
        requiredTool: 'HANDS',
      };
    }
    return {
      label: contextTool === 'HANDS'
        ? 'EXPLORE · LOOK FOR BRANCHES, BERRIES AND TRACKS'
        : WILDERNESS_PLAN_ORDER.includes(contextTool)
          ? `MOVE TO A CLEAR PLACE FOR ${WILDERNESS_TOOL_LABEL[contextTool].toUpperCase()}`
          : `NO ${WILDERNESS_TOOL_LABEL[contextTool].toUpperCase()} TARGET NEARBY`,
      enabled: false,
      kind: 'NONE',
    };
  }

  private resolveShelterInteraction(
    shelter: WildernessShelterState | undefined,
    shelterIndex: number,
    playerX: number,
    playerZ: number,
    heading: number,
  ): WildernessInteractionView {
    const targetStage = shelter ? Math.min(3, shelter.stage + 1) : 1;
    const cost = targetStage === 1
      ? { logs: 2, branches: 3 }
      : targetStage === 2
        ? { logs: 2, branches: 4 }
        : { logs: 3, branches: 5 };
    const enabled = this.inventory.logs >= cost.logs &&
      this.inventory.branches >= cost.branches && (!shelter || shelter.stage < 3);
    const x = shelter?.x ?? playerX + Math.sin(heading) * 3.2;
    const z = shelter?.z ?? playerZ + Math.cos(heading) * 3.2;
    const placementClear = Boolean(shelter) || this.canWalkAt(x, z, 1.42);
    return {
      label: shelter?.stage === 3
        ? 'LEAN-TO IS COMPLETE'
        : !placementClear
          ? 'FIND A CLEAR PATCH FOR THE LEAN-TO'
          : enabled
            ? shelter
              ? `IMPROVE LEAN-TO · ${cost.logs} LOGS + ${cost.branches} BRANCHES`
              : `BUILD LEAN-TO · ${cost.logs} LOGS + ${cost.branches} BRANCHES`
            : `NEED ${cost.logs} LOGS + ${cost.branches} BRANCHES`,
      enabled: enabled && placementClear,
      kind: shelter ? 'UPGRADE_SHELTER' : 'BUILD_SHELTER',
      ...(shelterIndex >= 0 ? { targetId: `wild-shelter:${shelterIndex}` } : {}),
      x,
      z,
      requiredTool: 'HANDS',
    };
  }

  private validFocusedTargetId(
    playerX: number,
    playerZ: number,
  ): string | undefined {
    const id = this.focusedTargetId;
    if (!id) return undefined;
    const worldItem = this.worldItems.find((item) => item.id === id);
    if (worldItem) {
      return Math.hypot(worldItem.x - playerX, worldItem.z - playerZ) <= 2.35
        ? id
        : undefined;
    }
    const resource = this.resources.find((node) => node.id === id);
    if (resource) {
      const reach = resource.kind === 'TREE' ? 2.7 : 2.3;
      return Math.hypot(resource.x - playerX, resource.z - playerZ) <= reach
        ? id
        : undefined;
    }
    const indexed = (
      prefix: string,
      values: readonly Readonly<{ x: number; z: number }>[],
      reach: number,
    ): string | undefined => {
      if (!id.startsWith(prefix)) return undefined;
      const target = values[Number(id.slice(prefix.length))];
      return target && Math.hypot(target.x - playerX, target.z - playerZ) <= reach
        ? id
        : undefined;
    };
    return indexed('wild-fire:', this.firePits, 3.35) ??
      indexed('wild-shelter:', this.shelters, 5.3) ??
      indexed('wild-snare:', this.snares, 2.7) ??
      (this.iceHoles.some((hole) =>
        hole.id === id && Math.hypot(hole.x - playerX, hole.z - playerZ) <= 2.85)
        ? id
        : undefined) ??
      (this.animals.some((animal) =>
        animal.id === id && Math.hypot(animal.x - playerX, animal.z - playerZ) <= 2.8)
        ? id
        : undefined);
  }

  public performInteraction(
    playerX: number,
    playerZ: number,
    heading: number,
    windX: number,
    windZ: number,
  ): WildernessActionResult {
    const interaction = this.resolveInteraction(playerX, playerZ, heading);
    if (!interaction.enabled) return { accepted: false, message: interaction.label };
    const node = interaction.targetId
      ? this.resources.find((candidate) => candidate.id === interaction.targetId)
      : undefined;
    const animal = interaction.targetId
      ? this.animals.find((candidate) => candidate.id === interaction.targetId)
      : undefined;
    switch (interaction.kind) {
      case 'PICKUP_WORLD_ITEM': {
        const index = this.worldItems.findIndex((item) =>
          item.id === interaction.targetId);
        if (index < 0) break;
        const item = this.worldItems[index]!;
        this.worldItems.splice(index, 1);
        if (item.kind === 'LOG') this.addWood('LOG', item.material ?? 'SPRUCE', item.quantity);
        else if (item.kind === 'BRANCH') this.addWood('BRANCH', item.material ?? 'SPRUCE', item.quantity);
        else this.inventory[this.inventoryKeyForPortableItem(item.kind)] += item.quantity;
        return {
          accepted: true,
          message: item.kind === 'LOG'
            ? `The fallen ${(item.material ?? 'SPRUCE').toLowerCase()} trunk is secured · +${item.quantity} logs.`
            : `Collected ${item.quantity} × ${WILDERNESS_TOOL_LABEL[item.kind].toLowerCase()}.`,
          tone: 'achievement',
        };
      }
      case 'DEFEND': {
        if (!animal) break;
        this.toolCondition.stoneAxe = Math.max(0, this.toolCondition.stoneAxe - 1);
        animal.health -= 1;
        animal.woundedSeconds = 9;
        animal.warningSeconds = 0;
        animal.behavior = animal.health <= 0 ? 'RETREAT' : 'FLEE';
        animal.retreatSeconds = animal.health <= 0 ? 90 : 0;
        const awayX = animal.x - playerX;
        const awayZ = animal.z - playerZ;
        const length = Math.max(0.001, Math.hypot(awayX, awayZ));
        animal.targetX = animal.x + awayX / length * 24;
        animal.targetZ = animal.z + awayZ / length * 24;
        animal.targetSeconds = 5;
        return {
          accepted: true,
          message: animal.health <= 0
            ? 'The animal retreats deep into the forest. The axe is for defence, not easy harvesting.'
            : 'The flat of the stone axe drives the threat back.',
        };
      }
      case 'GATHER':
        if (!node) break;
        if (node.kind === 'FALLEN_BRANCHES') {
          node.state = 'DEPLETED';
          this.addWood('BRANCH', node.woodMaterial ?? 'SPRUCE', 2);
          this.inventory.tinder += 1;
          this.inventory.fiber += 1;
          return { accepted: true, message: 'Dry branches gathered · +2 branches · +1 tinder · +1 fiber.' };
        }
        node.state = 'HARVESTED';
        node.regrowSeconds = 480;
        this.inventory.berries += Math.max(1, node.stock);
        node.stock = 0;
        this.condition.satiety = clamp(this.condition.satiety + 0.05, 0, 1);
        return { accepted: true, message: 'Only the ripe frost berries are picked. The living bush remains.' };
      case 'GATHER_BURIED_FOOD': {
        if (!node) break;
        node.state = 'DEPLETED';
        this.inventory.roots += 1;
        const sideX = Math.cos(heading);
        const sideZ = -Math.sin(heading);
        return {
          accepted: true,
          message: 'A hardy winter root appears beneath the snow · +1 root.',
          snowMove: {
            sourceX: node.x,
            sourceZ: node.z,
            destinationX: node.x + sideX * 1.25,
            destinationZ: node.z + sideZ * 1.25,
            radius: 0.58,
            maximumMass: 0.75,
            maximumDepth: 0.7,
          },
        };
      }
      case 'CHOP':
        if (!node) break;
        this.toolCondition.stoneAxe = Math.max(0, this.toolCondition.stoneAxe - 1);
        node.health -= 1;
        if (node.health > 0) {
          const progress = 1 - node.health / Math.max(1, node.maxHealth);
          return {
            accepted: true,
            message: progress < 0.34
              ? 'The stone axe bites. Needles tremble and snow shakes loose.'
              : progress < 0.72
                ? 'The cut opens wider. The trunk gives a deep wooden creak.'
                : 'The tree leans into the next blow.',
          };
        }
        node.state = 'FALLING';
        node.fallHeading = heading;
        node.fallProgress = 0;
        return {
          accepted: true,
          message: 'Timber! The trunk must still be collected from where it lands.',
          tone: 'achievement',
        };
      case 'MINE':
        if (!node) break;
        this.toolCondition.flintTool = Math.max(0, this.toolCondition.flintTool - 1);
        node.health -= 1;
        node.miningHits += 1;
        const usableChip = node.miningHits % 4 === 0;
        const usableStone = node.miningHits % 8 === 0;
        const usableFlint = node.miningHits % 25 === 0;
        if (usableChip) this.inventory.stoneChips += 1;
        if (usableStone) this.inventory.stone += 1;
        if (usableFlint) this.inventory.flint += 1;
        if (node.health <= 0) {
          node.state = 'EXHAUSTED';
          return {
            accepted: true,
            message: 'The exposed face is exhausted, but the landmark rock remains in the world.',
            tone: 'achievement',
          };
        }
        return {
          accepted: true,
          message: usableFlint
            ? 'A sharp piece of flint flashes inside the fracture.'
            : usableStone
              ? 'A palm-sized hearth stone breaks free from the upper face.'
              : usableChip
                ? 'A clean stone chip survives the strike. It may hold a temporary edge.'
                : 'Mostly powder and grit this time. The upper face is visibly smaller.',
        };
      case 'MAINTAIN_TOOL':
        if (interaction.requiredTool === 'STONE_AXE') {
          this.inventory.stone -= 1;
          this.inventory.fiber -= 1;
          this.toolCondition.stoneAxe = 28;
          return { accepted: true, message: 'A fresh stone edge is bound firmly to the axe haft.' };
        }
        if (this.inventory.flint > 0) this.inventory.flint -= 1;
        else this.inventory.stoneChips = Math.max(0, this.inventory.stoneChips - 3);
        this.inventory.fiber -= 1;
        this.toolCondition.flintTool = 32;
        return { accepted: true, message: 'A patient knapping pass restores the flint tool.' };
      case 'DIG_FIRE_PIT': {
        const x = interaction.x ?? playerX;
        const z = interaction.z ?? playerZ;
        this.firePits.push({
          x,
          z,
          stage: 'DUG',
          fuelSeconds: 0,
          layStage: 'HOLLOW',
          ignitionProgress: 0,
        });
        this.clearPlan();
        const windLength = Math.max(0.001, Math.hypot(windX, windZ));
        return {
          accepted: true,
          message: 'A sheltered hollow takes shape. The dug snow becomes a low windbreak.',
          tone: 'achievement',
          snowMove: {
            sourceX: x,
            sourceZ: z,
            destinationX: x + windX / windLength * 1.28,
            destinationZ: z + windZ / windLength * 1.28,
            radius: 0.82,
            maximumMass: 1.4,
            maximumDepth: 1.2,
          },
        };
      }
      case 'PLACE_FIRE_WOOD': {
        const fire = this.firePits.find((candidate) =>
          Math.hypot(candidate.x - playerX, candidate.z - playerZ) <= 3.1);
        if (!fire || this.inventory.branches < 2) break;
        const materials = this.takeWood('BRANCH', 2);
        fire.fuelQueue = materials.map((material) =>
          this.createFuelPiece(material, 'BRANCH'));
        fire.layStage = 'WOOD';
        fire.ignitionProgress = 0;
        this.refreshFuelSeconds(fire);
        return {
          accepted: true,
          message: 'Two dry branches are laid across the hollow. They are still only cold wood.',
        };
      }
      case 'PLACE_TINDER': {
        const fire = this.firePits.find((candidate) =>
          Math.hypot(candidate.x - playerX, candidate.z - playerZ) <= 3.1);
        if (!fire || this.inventory.tinder < 1) break;
        this.inventory.tinder -= 1;
        fire.layStage = 'TINDER';
        fire.ignitionProgress = 0;
        return {
          accepted: true,
          message: 'The tinder bundle rests loosely above the kindling. A spark is the natural next step.',
        };
      }
      case 'LIGHT_FIRE': {
        const fire = this.firePits.find((candidate) =>
          Math.hypot(candidate.x - playerX, candidate.z - playerZ) <= 3.1);
        if (!fire) break;
        this.toolCondition.flintTool = Math.max(0, this.toolCondition.flintTool - 1);
        fire.ignitionProgress = clamp(
          (fire.ignitionProgress ?? 0) + 0.29 +
            hash2D(Math.round(fire.x * 10), Math.round(fire.z * 10),
              Math.round((fire.ignitionProgress ?? 0) * 100) + 811) * 0.11,
          0,
          1,
        );
        if (fire.ignitionProgress < 1) {
          return {
            accepted: true,
            message: fire.ignitionProgress < 0.58
              ? 'A scatter of sparks lands in the tinder. A thin thread of smoke appears.'
              : 'One ember glows. Strike again gently and protect it from the wind.',
          };
        }
        fire.stage = 'LIT';
        fire.layStage = 'TINDER';
        fire.heatLevel = Math.max(0.12, fire.heatLevel ?? 0);
        fire.emberSeconds = Math.max(18, fire.emberSeconds ?? 0);
        fire.pendingMeltEnergy = Math.max(0, fire.pendingMeltEnergy ?? 0);
        if (fire.fuelQueue?.[0]) {
          fire.fuelQueue[0].ignitionSecondsRemaining = 0.25;
        }
        this.refreshFuelSeconds(fire);
        return { accepted: true, message: 'The tinder catches. Warm light fills the snow hollow.', tone: 'achievement' };
      }
      case 'FUEL_FIRE': {
        const fire = this.firePits.find((candidate) =>
          Math.hypot(candidate.x - playerX, candidate.z - playerZ) <= 3.1);
        if (!fire) break;
        this.ensureFuelMaterialInventory();
        const needsQuickKindling = (fire.heatLevel ?? 0) < 0.32;
        const form: WildernessFireFuelForm = interaction.fuelForm ?? (
          needsQuickKindling && this.inventory.branches > 0
            ? 'BRANCH'
            : this.inventory.logs > 0
              ? 'LOG'
              : 'BRANCH'
        );
        const material = this.takeWood(form, 1)[0] ?? 'SPRUCE';
        fire.fuelQueue ??= [];
        const piece = this.createFuelPiece(material, form);
        if (form === 'BRANCH') {
          // Kindling catches before a waiting heavy log and gives an
          // immediate readable flare instead of only extending a hidden sum.
          fire.fuelQueue.unshift(piece);
          fire.heatLevel = clamp((fire.heatLevel ?? 0) + 0.2, 0, 1);
          fire.emberSeconds = Math.max(fire.emberSeconds ?? 0, 14);
        } else {
          fire.fuelQueue.push(piece);
        }
        fire.stage = 'LIT';
        this.refreshFuelSeconds(fire);
        const label = `${material.toLowerCase()} ${form.toLowerCase()}`;
        return {
          accepted: true,
          message: form === 'LOG'
            ? `A ${label} warms slowly, then promises a long steady burn.`
            : `A ${label} catches quickly and lifts the flames.`,
        };
      }
      case 'BUILD_SHELTER':
      case 'UPGRADE_SHELTER': {
        const existing = this.shelters.find((candidate) =>
          Math.hypot(candidate.x - playerX, candidate.z - playerZ) <= 5);
        const nextStage = (existing ? Math.min(3, existing.stage + 1) : 1) as 1 | 2 | 3;
        const cost = nextStage === 1
          ? { logs: 2, branches: 3 }
          : nextStage === 2
            ? { logs: 2, branches: 4 }
            : { logs: 3, branches: 5 };
        this.takeWood('LOG', cost.logs);
        this.takeWood('BRANCH', cost.branches);
        if (existing) existing.stage = nextStage;
        else this.shelters.push({
          x: interaction.x ?? playerX,
          z: interaction.z ?? playerZ,
          heading: heading + Math.PI,
          stage: nextStage,
        });
        this.clearPlan();
        return {
          accepted: true,
          message: nextStage === 3
            ? 'The lean-to is weather-tight enough for a peaceful night.'
            : `Lean-to construction reached stage ${nextStage}/3.`,
          tone: 'achievement',
        };
      }
      case 'PLACE_SNARE':
        this.inventory.fiber -= 1;
        this.takeWood('BRANCH', 1);
        this.snares.push({
          x: interaction.x ?? playerX,
          z: interaction.z ?? playerZ,
          ageSeconds: 0,
          caught: false,
        });
        this.clearPlan();
        return { accepted: true, message: 'A simple loop snare waits beside the tracks.' };
      case 'COLLECT_SNARE': {
        const snare = this.snares.find((candidate) =>
          candidate.caught && Math.hypot(candidate.x - playerX, candidate.z - playerZ) <= 2.4);
        if (!snare) break;
        this.inventory.smallGame += 1;
        this.ecosystemStocks.smallGame = Math.max(0, this.ecosystemStocks.smallGame - 1);
        snare.ageSeconds = 0;
        snare.caught = false;
        return { accepted: true, message: 'The snare provides one small-game ration.' };
      }
      case 'CHIP_ICE_HOLE': {
        let hole = interaction.targetId
          ? this.iceHoles.find((candidate) => candidate.id === interaction.targetId)
          : undefined;
        if (!hole) {
          hole = {
            id: `wild-ice-hole-${this.nextIceHoleId++}`,
            x: interaction.x ?? playerX,
            z: interaction.z ?? playerZ,
            progress: 0,
            open: false,
            refreezeProgress: 0,
          };
          this.iceHoles.push(hole);
        }
        this.toolCondition.stoneAxe = Math.max(0, this.toolCondition.stoneAxe - 1);
        hole.refreezeProgress = 0;
        hole.progress = clamp(hole.progress + 0.34, 0, 1);
        if (hole.progress < 1) {
          return {
            accepted: true,
            message: hole.progress < 0.68
              ? 'A pale fracture spreads through the ice.'
              : 'Dark water shows beneath one more thin layer.',
          };
        }
        hole.open = true;
        hole.refreezeProgress = 0;
        return {
          accepted: true,
          message: 'The last ice disk lifts free. Dark, living water opens below.',
          tone: 'achievement',
        };
      }
      case 'CAST_LINE':
        {
          const hole = this.iceHoles.find((candidate) =>
            candidate.id === interaction.targetId);
          if (hole) hole.refreezeProgress = 0;
        }
        this.fishing.status = 'WAITING';
        this.fishing.elapsedSeconds = 0;
        this.fishing.activeHoleId = interaction.targetId;
        this.fishing.reelProgress = 0;
        this.fishing.missedPulls = 0;
        this.fishing.biteAtSeconds = 4.5 + hash2D(
          Math.floor(playerX),
          Math.floor(playerZ),
          Math.floor(this.condition.elapsedSeconds) + 7703,
        ) * 5;
        return { accepted: true, message: 'The line slips into dark water. Watch its gentle movement.' };
      case 'HOOK_FISH':
        this.fishing.status = 'HOOKED';
        this.fishing.elapsedSeconds = 0;
        this.fishing.reelProgress = 0.12;
        this.fishing.missedPulls = 0;
        this.fishing.reelTarget = 0.24 + hash2D(
          Math.floor(playerX * 2),
          Math.floor(playerZ * 2),
          Math.floor(this.condition.elapsedSeconds) + 8819,
        ) * 0.52;
        return {
          accepted: true,
          message: 'Hook set. Let the line breathe, then pull in the calm window.',
        };
      case 'REEL_FISH': {
        const timing = this.fishingTiming();
        if (!timing) break;
        const accuracy = Math.abs(timing.marker - timing.target);
        if (accuracy <= timing.tolerance) {
          const precision = 1 - accuracy / timing.tolerance;
          this.fishing.reelProgress = clamp(
            (this.fishing.reelProgress ?? 0) + 0.28 + precision * 0.16,
            0,
            1,
          );
          this.fishing.reelTarget = 0.2 + hash2D(
            Math.round((this.fishing.reelTarget ?? 0.5) * 100),
            Math.round((this.fishing.reelProgress ?? 0) * 100),
            8893,
          ) * 0.6;
          if ((this.fishing.reelProgress ?? 0) < 1) {
            return {
              accepted: true,
              message: precision > 0.72
                ? 'A clean pull brings the fish close.'
                : 'The line comes in steadily. Wait for the next calm window.',
            };
          }
          this.inventory.fish += 1;
          this.ecosystemStocks.fish = Math.max(0, this.ecosystemStocks.fish - 1);
          this.resetFishing();
          return {
            accepted: true,
            message: 'A bright river fish flashes onto the snow · +1 fish.',
            tone: 'achievement',
          };
        }
        this.fishing.missedPulls = (this.fishing.missedPulls ?? 0) + 1;
        this.fishing.reelProgress = Math.max(
          0,
          (this.fishing.reelProgress ?? 0) - 0.05,
        );
        if ((this.fishing.missedPulls ?? 0) >= 5) {
          this.resetFishing();
          return {
            accepted: true,
            message: 'The line goes light. Nothing is lost except a quiet moment.',
          };
        }
        return {
          accepted: true,
          message: 'Too much tension. Give the fish a moment and try the next window.',
        };
      }
      case 'LAND_FISH':
        this.inventory.fish += 1;
        this.ecosystemStocks.fish = Math.max(0, this.ecosystemStocks.fish - 1);
        this.resetFishing();
        return { accepted: true, message: 'A bright river fish flashes onto the snow · +1 fish.', tone: 'achievement' };
      case 'COOK_MEAL': {
        const cookedFish = this.inventory.fish > 0;
        const cookedRoot = !cookedFish && this.inventory.roots > 0;
        const foodId = cookedFish
          ? 'EMBER_FISH'
          : cookedRoot
            ? 'ROASTED_ROOT'
            : 'SMALL_GAME_ROAST';
        if (cookedFish) this.inventory.fish -= 1;
        else if (cookedRoot) this.inventory.roots -= 1;
        else this.inventory.smallGame -= 1;
        const food = WILDERNESS_FOOD_CATALOG.find((entry) =>
          entry.id === foodId);
        this.condition.satiety = clamp(
          this.condition.satiety + (food?.satiety ?? 0.42),
          0,
          1,
        );
        this.condition.energy = clamp(
          this.condition.energy + (food?.energy ?? 0.16),
          0,
          1,
        );
        this.condition.warmth = clamp(
          this.condition.warmth + (food?.warmth ?? 0.08),
          0,
          1,
        );
        if (food?.bonus && food.durationSeconds) {
          const existing = this.foodBuffs.find((buff) =>
            buff.id === food.bonus);
          if (existing) existing.remainingSeconds = food.durationSeconds;
          else this.foodBuffs.push({
            id: food.bonus,
            remainingSeconds: food.durationSeconds,
          });
        }
        return {
          accepted: true,
          message: cookedFish
            ? 'The fish cooks quickly over the coals. Warmth and energy return.'
            : cookedRoot
              ? 'The buried root turns sweet in the coals. A small discovery becomes a warm meal.'
            : 'A simple hot ration makes the little camp feel like home.',
          tone: 'achievement',
        };
      }
      case 'EAT_BERRIES':
        this.inventory.berries -= 1;
        this.condition.satiety = clamp(this.condition.satiety + 0.1, 0, 1);
        this.condition.energy = clamp(this.condition.energy + 0.025, 0, 1);
        return { accepted: true, message: 'Tart frost berries brighten the cold walk.' };
      default:
        break;
    }
    return { accepted: false, message: 'Nothing happens.' };
  }

  public recordProgress(
    kind: WildernessInteractionView['kind'],
  ): string | undefined {
    if (kind === 'NONE' || kind === 'WAIT') return undefined;
    this.progression.actionCounts[kind] =
      (this.progression.actionCounts[kind] ?? 0) + 1;
    let milestone: WildernessMilestoneId | undefined;
    if (kind === 'GATHER' || kind === 'GATHER_BURIED_FOOD') {
      milestone = 'FIRST_GATHERING';
    } else if (kind === 'LIGHT_FIRE' && this.firePits.some((fire) => fire.stage === 'LIT')) {
      milestone = 'FIRST_EMBER';
    } else if (
      kind === 'CHOP' &&
      this.resources.some((node) =>
        node.kind === 'TREE' && (node.state === 'FALLING' || node.state === 'DEPLETED'))
    ) {
      milestone = 'FIRST_TREE';
    } else if (
      (kind === 'BUILD_SHELTER' || kind === 'UPGRADE_SHELTER') &&
      this.shelters.some((shelter) => shelter.stage >= 3)
    ) {
      milestone = 'SAFE_FIRST_NIGHT';
    } else if (
      (kind === 'REEL_FISH' || kind === 'LAND_FISH') &&
      this.inventory.fish > 0
    ) {
      milestone = 'UNDER_THE_ICE';
    } else if (kind === 'COOK_MEAL') {
      milestone = 'FIRST_HOT_MEAL';
    }
    return milestone ? this.completeMilestone(milestone) : undefined;
  }

  private completeMilestone(milestone: WildernessMilestoneId): string | undefined {
    if (this.hasMilestone(milestone)) return undefined;
    this.progression.completedMilestones.push(milestone);
    const definition = WILDERNESS_MILESTONE_CATALOG.find((entry) =>
      entry.id === milestone);
    for (const skill of definition?.unlocks ?? []) {
      if (!this.progression.unlockedSkills.includes(skill)) {
        this.progression.unlockedSkills.push(skill);
      }
    }
    return definition?.name;
  }

  public update(deltaSeconds: number, context: Readonly<WildernessStepContext>): void {
    const delta = clamp(deltaSeconds, 0, 0.1);
    if (delta <= 0) return;
    this.advancePersistentState(delta);
    const litFires = this.firePits.filter((fire) => fire.stage === 'LIT');
    const fireDistance = litFires.reduce(
      (nearest, fire) => Math.min(nearest, Math.hypot(fire.x - context.playerX, fire.z - context.playerZ)),
      Number.POSITIVE_INFINITY,
    );
    const shelterDistance = this.shelters.reduce(
      (nearest, shelter) => Math.min(nearest, Math.hypot(shelter.x - context.playerX, shelter.z - context.playerZ)),
      Number.POSITIVE_INFINITY,
    );
    this.condition.nearFire = fireDistance <= 7.5;
    this.condition.sheltered = shelterDistance <= 4.8 ||
      this.firePits.some((fire) => Math.hypot(fire.x - context.playerX, fire.z - context.playerZ) <= 2.5);
    const localExposure = clamp(context.localExposure ?? 1, 0.18, 1);
    const exposedWind = context.windStrength *
      (this.condition.sheltered ? 0.24 : localExposure);
    const coldPressure = clamp(
      (-(context.airTemperatureCelsius ?? -8) - 4) / 30,
      0,
      1,
    );
    const activeWarmth = clamp(Math.abs(context.playerSpeed) / 2.2, 0, 1) * 0.0008;
    const nearestFireHeat = litFires.reduce(
      (strongest, fire) => Math.max(
        strongest,
        (fire.heatLevel ?? 0.5) * clamp(
          1 - Math.hypot(fire.x - context.playerX, fire.z - context.playerZ) / 8.5,
          0,
          1,
        ),
      ),
      0,
    );
    const targetWarmth = this.condition.nearFire
      ? 0.76 + nearestFireHeat * 0.22
      : clamp(
          0.74 - exposedWind * 0.12 - coldPressure * 0.14 -
            this.condition.wetness * 0.24 +
            (this.hasFoodBuff('MILD_COLD_RESISTANCE') ? 0.055 : 0),
          0.3,
          0.84,
        );
    this.condition.warmth = damp(
      this.condition.warmth,
      targetWarmth + activeWarmth,
      this.condition.nearFire ? 0.2 : 0.018,
      delta,
    );
    const wetGain = context.snowIntensity * localExposure *
      (0.00022 + Math.abs(context.playerSpeed) * 0.00008) +
      (context.snowDepth > 0.72 ? 0.00012 : 0);
    const dryRate = this.condition.nearFire ? 0.012 + nearestFireHeat * 0.03 : this.condition.sheltered ? 0.002 : 0.0003;
    this.condition.wetness = clamp(
      this.condition.wetness + wetGain * delta - dryRate * delta,
      0,
      1,
    );
    this.condition.energy = clamp(
      this.condition.energy - delta *
        (this.hasFoodBuff('SLOW_ENERGY_DRAIN') ? 0.65 : 1) *
        (0.000055 + Math.abs(context.playerSpeed) * 0.000028),
      0.08,
      1,
    );
    this.condition.satiety = clamp(
      this.condition.satiety - delta * 0.000035,
      0.08,
      1,
    );
    this.updateAnimals(delta, context, litFires);
  }

  /** Timers continue even while the wilderness renderer is off screen. */
  public updatePersistent(deltaSeconds: number): void {
    const delta = clamp(deltaSeconds, 0, 0.1);
    if (delta > 0) this.advancePersistentState(delta);
  }

  private advancePersistentState(delta: number): void {
    this.condition.elapsedSeconds += delta;
    for (let index = this.foodBuffs.length - 1; index >= 0; index -= 1) {
      const buff = this.foodBuffs[index]!;
      buff.remainingSeconds = Math.max(0, buff.remainingSeconds - delta);
      if (buff.remainingSeconds <= 0) this.foodBuffs.splice(index, 1);
    }
    for (const node of this.resources) {
      if (node.kind === 'BERRY_SHRUB' && node.state === 'HARVESTED') {
        node.regrowSeconds = Math.max(0, node.regrowSeconds - delta);
        if (node.regrowSeconds <= 0) {
          node.state = 'READY';
          node.stock = 2;
        }
      }
      if (node.state !== 'FALLING') continue;
      node.fallProgress = clamp(node.fallProgress + delta / 1.25, 0, 1);
      if (node.fallProgress >= 1) {
        node.state = 'DEPLETED';
        node.regrowSeconds = WILDERNESS_TREE_REGROW_SECONDS;
        const forwardX = Math.sin(node.fallHeading);
        const forwardZ = Math.cos(node.fallHeading);
        const material = node.woodMaterial ?? 'SPRUCE';
        this.worldItems.push({
          id: `wild-world-log-${this.nextWorldItemId++}`,
          kind: 'LOG',
          material,
          x: node.x + forwardX * node.scale * 2.15,
          z: node.z + forwardZ * node.scale * 2.15,
          heading: node.fallHeading,
          quantity: 2,
        });
        this.worldItems.push({
          id: `wild-world-branches-${this.nextWorldItemId++}`,
          kind: 'BRANCH',
          material,
          x: node.x + forwardX * node.scale * 3.35,
          z: node.z + forwardZ * node.scale * 3.35,
          heading: node.fallHeading + Math.PI * 0.5,
          quantity: 2,
        });
      }
    }
    for (const node of this.resources) {
      if (node.kind !== 'TREE' || node.state !== 'DEPLETED') continue;
      node.regrowSeconds = Math.max(0, node.regrowSeconds - delta);
      if (node.regrowSeconds > 0) continue;
      node.state = 'READY';
      node.health = node.maxHealth;
      node.fallProgress = 0;
      node.fallHeading = 0;
    }
    for (const fire of this.firePits) {
      this.advanceFire(fire, delta);
    }
    for (const snare of this.snares) {
      if (snare.caught) continue;
      snare.ageSeconds += delta;
      if (this.ecosystemStocks.smallGame > 0 && snare.ageSeconds >= 58 + hash2D(
        Math.floor(snare.x), Math.floor(snare.z), 3119,
      ) * 55) snare.caught = true;
    }
    if (this.fishing.status !== 'IDLE') {
      this.fishing.elapsedSeconds += delta;
      if (
        this.fishing.status === 'WAITING' &&
        this.fishing.elapsedSeconds >= this.fishing.biteAtSeconds
      ) this.fishing.status = 'BITE';
      if (
        this.fishing.status === 'BITE' &&
        this.fishing.elapsedSeconds >= this.fishing.biteAtSeconds + 4.5
      ) {
        this.resetFishing();
      }
      if (
        this.fishing.status === 'HOOKED' &&
        this.fishing.elapsedSeconds >= 24
      ) {
        this.resetFishing();
      }
    }
    for (const hole of this.iceHoles) {
      if (!hole.open) continue;
      const activelyUsed = this.fishing.status !== 'IDLE' &&
        this.fishing.activeHoleId === hole.id;
      if (activelyUsed) {
        hole.refreezeProgress = 0;
        continue;
      }
      hole.refreezeProgress = clamp(
        (hole.refreezeProgress ?? 0) + delta / 360,
        0,
        1,
      );
      if ((hole.refreezeProgress ?? 0) < 1) continue;
      hole.open = false;
      hole.progress = 0.42;
      hole.refreezeProgress = 0;
    }
  }

  private resetFishing(): void {
    this.fishing.status = 'IDLE';
    this.fishing.elapsedSeconds = 0;
    this.fishing.biteAtSeconds = 0;
    this.fishing.activeHoleId = undefined;
    this.fishing.reelProgress = 0;
    this.fishing.reelTarget = 0.5;
    this.fishing.missedPulls = 0;
  }

  private advanceFire(fire: WildernessFirePitState, delta: number): void {
    if (fire.stage === 'DUG') return;
    this.ensureFireState(fire);
    const queue = fire.fuelQueue ?? [];
    let remaining = delta;
    let targetHeat = 0;
    while (remaining > 0.00001) {
      const piece = queue[0];
      if (!piece) {
        const emberStep = Math.min(remaining, fire.emberSeconds ?? 0);
        fire.emberSeconds = Math.max(0, (fire.emberSeconds ?? 0) - emberStep);
        remaining -= emberStep;
        targetHeat = Math.max(
          targetHeat,
          0.2 * clamp((fire.emberSeconds ?? 0) / 24, 0, 1),
        );
        break;
      }
      const fuel = WILDERNESS_FIRE_FUEL_CATALOG[piece.material][piece.form];
      if (piece.ignitionSecondsRemaining > 0) {
        if ((fire.emberSeconds ?? 0) <= 0 && (fire.heatLevel ?? 0) <= 0.025) {
          break;
        }
        const ignitionStep = Math.min(remaining, piece.ignitionSecondsRemaining);
        piece.ignitionSecondsRemaining -= ignitionStep;
        fire.emberSeconds = Math.max(
          0,
          (fire.emberSeconds ?? 0) - ignitionStep * 0.28,
        );
        remaining -= ignitionStep;
        targetHeat = Math.max(targetHeat, 0.1 + (fire.heatLevel ?? 0) * 0.7);
        continue;
      }
      const burnStep = Math.min(remaining, piece.burnSecondsRemaining);
      const fraction = piece.burnSecondsRemaining /
        Math.max(0.001, piece.burnSecondsTotal);
      const endFade = smoothstep(0, 1, fraction / 0.24);
      const startProgress = 1 - fraction;
      const startFade = smoothstep(0, 1, startProgress / 0.12);
      targetHeat = Math.max(targetHeat, fuel.heat * endFade * startFade);
      piece.burnSecondsRemaining = Math.max(
        0,
        piece.burnSecondsRemaining - burnStep,
      );
      fire.emberSeconds = Math.max(fire.emberSeconds ?? 0, fuel.emberSeconds);
      remaining -= burnStep;
      if (piece.burnSecondsRemaining <= 0.00001) queue.shift();
    }
    fire.heatLevel = damp(
      fire.heatLevel ?? 0,
      targetHeat,
      targetHeat > (fire.heatLevel ?? 0) ? 3.4 : 0.72,
      delta,
    );
    fire.pendingMeltEnergy = clamp(
      (fire.pendingMeltEnergy ?? 0) + (fire.heatLevel ?? 0) * delta,
      0,
      180,
    );
    if (
      queue.length === 0 &&
      (fire.emberSeconds ?? 0) <= 0.0001 &&
      (fire.heatLevel ?? 0) <= 0.025
    ) {
      fire.stage = 'COLD';
      fire.heatLevel = 0;
    } else {
      fire.stage = 'LIT';
    }
    this.refreshFuelSeconds(fire);
  }

  private createFuelPiece(
    material: WildernessWoodMaterial,
    form: WildernessFireFuelForm,
    ignitionOverride?: number,
  ): WildernessFireFuelPiece {
    const fuel = WILDERNESS_FIRE_FUEL_CATALOG[material][form];
    return {
      id: this.nextFuelPieceId++,
      material,
      form,
      ignitionSecondsRemaining: ignitionOverride ?? fuel.ignitionSeconds,
      burnSecondsRemaining: fuel.burnSeconds,
      burnSecondsTotal: fuel.burnSeconds,
    };
  }

  private ensureFireState(fire: WildernessFirePitState): void {
    fire.heatLevel = clamp(fire.heatLevel ?? (fire.stage === 'LIT' ? 0.62 : 0), 0, 1);
    fire.emberSeconds = Math.max(0, fire.emberSeconds ?? (fire.stage === 'LIT' ? 18 : 0));
    fire.pendingMeltEnergy = Math.max(0, fire.pendingMeltEnergy ?? 0);
    if (!fire.fuelQueue) {
      fire.fuelQueue = fire.stage === 'LIT' && fire.fuelSeconds > 0
        ? [{
            ...this.createFuelPiece('SPRUCE', 'LOG', 0),
            burnSecondsRemaining: fire.fuelSeconds,
            burnSecondsTotal: Math.max(1, fire.fuelSeconds),
          }]
        : [];
    }
    for (const piece of fire.fuelQueue) {
      this.nextFuelPieceId = Math.max(this.nextFuelPieceId, piece.id + 1);
    }
  }

  private refreshFuelSeconds(fire: WildernessFirePitState): void {
    fire.fuelSeconds = (fire.fuelQueue ?? []).reduce(
      (total, piece) => total + piece.ignitionSecondsRemaining + piece.burnSecondsRemaining,
      fire.emberSeconds ?? 0,
    );
  }

  private addWood(
    form: WildernessFireFuelForm,
    material: WildernessWoodMaterial,
    count: number,
  ): void {
    const destination = form === 'BRANCH'
      ? this.branchMaterials
      : this.logMaterials;
    for (let index = 0; index < count; index += 1) destination.push(material);
    if (form === 'BRANCH') this.inventory.branches += count;
    else this.inventory.logs += count;
  }

  private inventoryKeyForPortableItem(
    kind: WildernessPortableItemKind,
  ): keyof WildernessInventory {
    switch (kind) {
      case 'BRANCH': return 'branches';
      case 'LOG': return 'logs';
      case 'TINDER': return 'tinder';
      case 'STONE': return 'stone';
      case 'STONE_CHIP': return 'stoneChips';
      case 'FLINT': return 'flint';
      case 'FIBER': return 'fiber';
      case 'BERRY': return 'berries';
      case 'FISH': return 'fish';
      case 'SMALL_GAME': return 'smallGame';
      case 'ROOT': return 'roots';
    }
  }

  private normalizeTool(input: unknown): WildernessTool {
    // Save migration: the earliest prototype exposed a magical FIRE_KIT.
    // It now maps only to shaping a snow hollow. Fuel and ignition stay as
    // separate physical inventory actions.
    if (input === 'FIRE_KIT') return 'CAMP_CRAFT';
    return typeof input === 'string' &&
      WILDERNESS_TOOL_ORDER.includes(input as WildernessTool)
      ? input as WildernessTool
      : 'HANDS';
  }

  private takeWood(
    form: WildernessFireFuelForm,
    count: number,
  ): WildernessWoodMaterial[] {
    this.ensureFuelMaterialInventory();
    const source = form === 'BRANCH' ? this.branchMaterials : this.logMaterials;
    const taken = source.splice(0, Math.max(0, count));
    if (form === 'BRANCH') {
      this.inventory.branches = Math.max(0, this.inventory.branches - taken.length);
    } else {
      this.inventory.logs = Math.max(0, this.inventory.logs - taken.length);
    }
    return taken;
  }

  private ensureFuelMaterialInventory(): void {
    while (this.branchMaterials.length < this.inventory.branches) {
      this.branchMaterials.push('SPRUCE');
    }
    while (this.logMaterials.length < this.inventory.logs) {
      this.logMaterials.push('SPRUCE');
    }
    this.branchMaterials.length = this.inventory.branches;
    this.logMaterials.length = this.inventory.logs;
  }

  private updateAnimals(
    delta: number,
    context: Readonly<WildernessStepContext>,
    litFires: readonly Readonly<WildernessFirePitState>[],
  ): void {
    const deer = this.animals.filter((animal) => animal.species === 'DEER');
    for (const animal of this.animals) {
      const defensivePredator = animal.species === 'WOLF' ||
        animal.species === 'BEAR' || animal.species === 'POLAR_BEAR';
      animal.woundedSeconds = Math.max(0, animal.woundedSeconds - delta);
      animal.attackCooldownSeconds = Math.max(0, animal.attackCooldownSeconds - delta);
      animal.retreatSeconds = Math.max(0, animal.retreatSeconds - delta);
      animal.hunger = clamp((animal.hunger ?? 0.2) + delta / 520, 0, 1);
      animal.thirst = clamp((animal.thirst ?? 0.18) + delta / 390, 0, 1);
      animal.fatigue = clamp((animal.fatigue ?? 0.12) + delta / 610, 0, 1);
      animal.activitySeconds = Math.max(0, (animal.activitySeconds ?? 0) - delta);
      animal.homeX ??= animal.x;
      animal.homeZ ??= animal.z;
      if (animal.behavior === 'RETREAT' && animal.retreatSeconds <= 0) {
        animal.behavior = 'WANDER';
        animal.health = animal.species === 'WOLF' ? 2 : defensivePredator ? 4 : 1;
      }
      animal.targetSeconds -= delta;
      const playerDistance = Math.hypot(animal.x - context.playerX, animal.z - context.playerZ);
      const fleeRadius = animal.species === 'RABBIT'
        ? 9
        : animal.species === 'DEER' || animal.species === 'MOOSE'
          ? 15
          : 10;
      const fireDistance = litFires.reduce(
        (nearest, fire) => Math.min(nearest, Math.hypot(animal.x - fire.x, animal.z - fire.z)),
        Number.POSITIVE_INFINITY,
      );
      const nearestFire = litFires.reduce<Readonly<WildernessFirePitState> | undefined>(
        (nearest, fire) => !nearest ||
          Math.hypot(animal.x - fire.x, animal.z - fire.z) <
            Math.hypot(animal.x - nearest.x, animal.z - nearest.z)
          ? fire
          : nearest,
        undefined,
      );
      let desiredSpeed = animal.species === 'RABBIT'
        ? 0.65
        : animal.species === 'DEER' || animal.species === 'MOOSE'
          ? 0.78
          : animal.species === 'BEAR' || animal.species === 'POLAR_BEAR'
            ? 0.42
            : 0.72;
      if (animal.behavior === 'RETREAT') {
        desiredSpeed = 3.4;
      } else if (fireDistance < 13 || (!defensivePredator && playerDistance < fleeRadius)) {
        const threatX = fireDistance < playerDistance
          ? nearestFire?.x ?? context.playerX
          : context.playerX;
        const threatZ = fireDistance < playerDistance
          ? nearestFire?.z ?? context.playerZ
          : context.playerZ;
        const awayX = animal.x - threatX;
        const awayZ = animal.z - threatZ;
        const length = Math.hypot(awayX, awayZ);
        const directionX = length > 0.01
          ? awayX / length
          : Math.sin(animal.heading || 0.73);
        const directionZ = length > 0.01
          ? awayZ / length
          : Math.cos(animal.heading || 0.73);
        animal.targetX = animal.x + directionX * 15;
        animal.targetZ = animal.z + directionZ * 15;
        desiredSpeed = animal.species === 'RABBIT'
          ? 3.4
          : animal.species === 'DEER' || animal.species === 'MOOSE'
            ? 4.5
            : animal.species === 'BEAR' || animal.species === 'POLAR_BEAR'
              ? 2
              : 2.8;
        animal.alert = 1;
        animal.behavior = 'FLEE';
        animal.targetSeconds = 2.2;
      } else if (
        defensivePredator &&
        playerDistance < (animal.species === 'WOLF' ? 6.5 : 7.8) &&
        animal.attackCooldownSeconds <= 0
      ) {
        animal.warningSeconds += delta;
        animal.alert = 1;
        if (animal.warningSeconds < 1.35) {
          animal.behavior = 'WARN';
          animal.targetX = animal.x;
          animal.targetZ = animal.z;
          desiredSpeed = 0;
        } else {
          animal.behavior = 'CHARGE';
          animal.targetX = context.playerX;
          animal.targetZ = context.playerZ;
          desiredSpeed = animal.species === 'WOLF' ? 2.9 : 2.35;
          if (playerDistance < 0.95) {
            this.condition.energy = clamp(this.condition.energy - 0.08, 0.08, 1);
            animal.attackCooldownSeconds = 7;
            animal.warningSeconds = 0;
            animal.behavior = 'FLEE';
            const awayX = animal.x - context.playerX;
            const awayZ = animal.z - context.playerZ;
            const length = Math.max(0.001, Math.hypot(awayX, awayZ));
            animal.targetX = animal.x + awayX / length * 18;
            animal.targetZ = animal.z + awayZ / length * 18;
            animal.targetSeconds = 4;
          }
        }
      } else if (
        !defensivePredator &&
        (animal.thirst ?? 0) > 0.68
      ) {
        animal.warningSeconds = Math.max(0, animal.warningSeconds - delta * 2);
        animal.behavior = 'DRINK';
        let targetZ = clamp(
          animal.z,
          WILDERNESS_SURVIVAL_REGION.centerZ - 60,
          WILDERNESS_SURVIVAL_REGION.centerZ + 60,
        );
        let bestFlow = wildernessCreekFlowAt(targetZ);
        for (const offset of [-15, -10, -5, 5, 10, 15]) {
          const candidateZ = clamp(
            animal.z + offset,
            WILDERNESS_SURVIVAL_REGION.centerZ - 60,
            WILDERNESS_SURVIVAL_REGION.centerZ + 60,
          );
          const flow = wildernessCreekFlowAt(candidateZ) - Math.abs(offset) * 0.008;
          if (flow <= bestFlow) continue;
          bestFlow = flow;
          targetZ = candidateZ;
        }
        animal.targetX = wildernessCreekCenterX(targetZ) +
          (animal.x < wildernessCreekCenterX(targetZ) ? -2.45 : 2.45);
        animal.targetZ = targetZ;
        desiredSpeed = 0.72;
        if (Math.hypot(animal.targetX - animal.x, animal.targetZ - animal.z) < 1.15) {
          animal.thirst = Math.max(0.04, (animal.thirst ?? 0) - delta * 0.3);
          animal.activitySeconds = 1.2;
          desiredSpeed = 0;
        }
      } else if (
        !defensivePredator &&
        (animal.hunger ?? 0) > 0.58
      ) {
        const forage = this.resources
          .filter((node) =>
            node.kind === 'BERRY_SHRUB' &&
            node.state === 'READY' &&
            node.stock > 1)
          .reduce<WildernessResourceNode | undefined>((nearest, node) =>
            !nearest || Math.hypot(node.x - animal.x, node.z - animal.z) <
              Math.hypot(nearest.x - animal.x, nearest.z - animal.z)
              ? node
              : nearest, undefined);
        if (forage) {
          animal.behavior = 'FORAGE';
          animal.targetResourceId = forage.id;
          animal.targetX = forage.x;
          animal.targetZ = forage.z;
          desiredSpeed = 0.58;
          if (Math.hypot(forage.x - animal.x, forage.z - animal.z) < 1.05) {
            animal.hunger = Math.max(0.12, (animal.hunger ?? 0) - 0.34);
            forage.stock = Math.max(1, forage.stock - 1);
            animal.activitySeconds = 2.1;
            desiredSpeed = 0;
          }
        }
      } else if (
        !defensivePredator &&
        (animal.fatigue ?? 0) > 0.74
      ) {
        animal.behavior = 'REST';
        animal.targetX = animal.homeX ?? animal.x;
        animal.targetZ = animal.homeZ ?? animal.z;
        desiredSpeed = 0.45;
        if (Math.hypot(animal.targetX - animal.x, animal.targetZ - animal.z) < 1.4) {
          animal.fatigue = Math.max(0.06, (animal.fatigue ?? 0) - delta * 0.18);
          animal.activitySeconds = 1.4;
          desiredSpeed = 0;
        }
      } else if (animal.species === 'WOLF' && deer.length > 0) {
        animal.warningSeconds = Math.max(0, animal.warningSeconds - delta * 2);
        animal.behavior = 'WANDER';
        const prey = deer.reduce((nearest, candidate) =>
          Math.hypot(candidate.x - animal.x, candidate.z - animal.z) <
          Math.hypot(nearest.x - animal.x, nearest.z - animal.z)
            ? candidate
            : nearest,
        );
        animal.targetX = prey.x;
        animal.targetZ = prey.z;
        desiredSpeed = playerDistance < 20 ? 0.35 : 1.25;
      } else if (animal.species === 'FOX') {
        animal.behavior = 'WANDER';
        const rabbits = this.animals.filter((candidate) =>
          candidate.species === 'RABBIT');
        const prey = rabbits.reduce<WildernessAnimalState | undefined>(
          (nearest, candidate) => !nearest ||
            Math.hypot(candidate.x - animal.x, candidate.z - animal.z) <
              Math.hypot(nearest.x - animal.x, nearest.z - animal.z)
            ? candidate
            : nearest,
          undefined,
        );
        if (prey && playerDistance > 18) {
          animal.targetX = prey.x;
          animal.targetZ = prey.z;
          desiredSpeed = 1.1;
        }
      } else if (animal.targetSeconds <= 0 || Math.hypot(
        animal.targetX - animal.x,
        animal.targetZ - animal.z,
      ) < 1.4) {
        const seed = Math.floor(this.condition.elapsedSeconds / 6) +
          Number(animal.id.match(/\d+$/)?.[0] ?? 0) * 37;
        const angle = hash2D(seed, 97, 10007) * Math.PI * 2;
        const radius = 5 + hash2D(seed, 101, 10009) * 16;
        animal.targetX = clamp(
          animal.x + Math.cos(angle) * radius,
          WILDERNESS_SURVIVAL_REGION.centerX - 68,
          WILDERNESS_SURVIVAL_REGION.centerX + 68,
        );
        animal.targetZ = clamp(
          animal.z + Math.sin(angle) * radius,
          WILDERNESS_SURVIVAL_REGION.centerZ - 68,
          WILDERNESS_SURVIVAL_REGION.centerZ + 68,
        );
        if (animal.species === 'POLAR_BEAR') {
          animal.targetX = clamp(
            animal.targetX,
            WILDERNESS_SURVIVAL_REGION.creekX - 13,
            WILDERNESS_SURVIVAL_REGION.creekX + 13,
          );
        }
        animal.targetSeconds = 3 + hash2D(seed, 103, 10037) * 5;
        animal.behavior = 'WANDER';
      }
      const dx = animal.targetX - animal.x;
      const dz = animal.targetZ - animal.z;
      const distance = Math.max(0.001, Math.hypot(dx, dz));
      const targetHeading = Math.atan2(dx, dz);
      const angleDelta = Math.atan2(
        Math.sin(targetHeading - animal.heading),
        Math.cos(targetHeading - animal.heading),
      );
      animal.heading += angleDelta * (1 - Math.exp(-4.2 * delta));
      animal.speed = damp(animal.speed, desiredSpeed, 2.2, delta);
      animal.x += dx / distance * animal.speed * delta;
      animal.z += dz / distance * animal.speed * delta;
      animal.alert = Math.max(0, animal.alert - delta * 0.22);
    }
  }

  public exportState(): WildernessSurvivalSaveData {
    this.ensureFuelMaterialInventory();
    return {
      version: 1,
      selectedTool: this.selectedTool,
      quickSlots: [...this.quickSlots],
      selectedQuickSlot: this.selectedQuickSlot,
      inventory: { ...this.inventory },
      toolCondition: { ...this.toolCondition },
      condition: { ...this.condition },
      resources: this.resources.map((node) => ({
        id: node.id,
        health: node.health,
        state: node.state,
        fallHeading: node.fallHeading,
        fallProgress: node.fallProgress,
        stock: node.stock,
        regrowSeconds: node.regrowSeconds,
        miningHits: node.miningHits,
      })),
      animals: this.animals.map((animal) => ({ ...animal })),
      firePits: this.firePits.map((fire) => ({
        ...fire,
        fuelQueue: fire.fuelQueue?.map((piece) => ({ ...piece })),
      })),
      shelters: this.shelters.map((shelter) => ({ ...shelter })),
      snares: this.snares.map((snare) => ({ ...snare })),
      fishing: { ...this.fishing },
      ecosystemStocks: { ...this.ecosystemStocks },
      fuelMaterials: {
        branches: [...this.branchMaterials],
        logs: [...this.logMaterials],
      },
      worldItems: this.worldItems.map((item) => ({ ...item })),
      progression: {
        unlockedSkills: [...this.progression.unlockedSkills],
        completedMilestones: [...this.progression.completedMilestones],
        actionCounts: { ...this.progression.actionCounts },
      },
      iceHoles: this.iceHoles.map((hole) => ({ ...hole })),
      foodBuffs: this.foodBuffs.map((buff) => ({ ...buff })),
    };
  }

  public importState(saved: Readonly<WildernessSurvivalSaveData>): void {
    if (saved.version !== 1) return;
    this.selectedTool = this.normalizeTool(saved.selectedTool);
    if (saved.quickSlots?.length === this.quickSlots.length) {
      this.quickSlots.splice(
        0,
        this.quickSlots.length,
        ...saved.quickSlots.map((tool, index) => {
          const normalized = this.normalizeTool(tool);
          return normalized === 'HANDS' && tool !== 'HANDS'
            ? this.quickSlots[index] ?? 'HANDS'
            : normalized;
        }),
      );
    }
    this.selectedQuickSlot = Math.round(clamp(
      saved.selectedQuickSlot ?? Math.max(0, this.quickSlots.indexOf(this.selectedTool)),
      0,
      this.quickSlots.length - 1,
    ));
    Object.assign(this.inventory, cloneInventory(saved.inventory));
    Object.assign(this.toolCondition, {
      stoneAxe: clamp(Math.round(saved.toolCondition?.stoneAxe ?? 28), 0, 28),
      flintTool: clamp(Math.round(saved.toolCondition?.flintTool ?? 32), 0, 32),
    });
    Object.assign(this.condition, {
      warmth: clamp(saved.condition.warmth, 0, 1),
      energy: clamp(saved.condition.energy, 0, 1),
      satiety: clamp(saved.condition.satiety, 0, 1),
      wetness: clamp(saved.condition.wetness, 0, 1),
      sheltered: Boolean(saved.condition.sheltered),
      nearFire: Boolean(saved.condition.nearFire),
      elapsedSeconds: Math.max(0, saved.condition.elapsedSeconds),
    });
    // Recreate lazily promoted forest trees before applying their saved state.
    for (const state of saved.resources) {
      if (!state.id.startsWith('wild-scenery-tree-')) continue;
      const index = Number(state.id.slice('wild-scenery-tree-'.length));
      if (Number.isInteger(index)) this.promoteSceneryTree(index);
    }
    const resources = new Map(saved.resources.map((node) => [node.id, node]));
    for (const node of this.resources) {
      const state = resources.get(node.id);
      if (!state) continue;
      const legacyRock = node.kind === 'ROCK' && state.miningHits === undefined;
      const legacyBerry = node.kind === 'BERRY_SHRUB' && state.stock === undefined;
      node.health = legacyRock
        ? node.maxHealth
        : clamp(Math.round(state.health), 0, node.maxHealth);
      node.state = legacyRock || legacyBerry ? 'READY' : state.state;
      node.fallHeading = Number.isFinite(state.fallHeading) ? state.fallHeading : 0;
      node.fallProgress = clamp(state.fallProgress, 0, 1);
      node.stock = legacyBerry
        ? 2
        : clamp(Math.round(state.stock ?? node.stock), 0, 4);
      node.regrowSeconds = clamp(
        state.regrowSeconds ?? (
          node.kind === 'TREE' && state.state === 'DEPLETED'
            ? WILDERNESS_TREE_REGROW_SECONDS
            : 0
        ),
        0,
        WILDERNESS_TREE_REGROW_SECONDS,
      );
      if (
        node.kind === 'TREE' &&
        node.state === 'DEPLETED' &&
        node.regrowSeconds <= 0
      ) node.regrowSeconds = WILDERNESS_TREE_REGROW_SECONDS;
      node.miningHits = clamp(Math.round(state.miningHits ?? 0), 0, 100);
    }
    const animals = new Map(saved.animals.map((animal) => [animal.id, animal]));
    for (const animal of this.animals) {
      const state = animals.get(animal.id);
      if (!state || state.species !== animal.species) continue;
      Object.assign(animal, {
        x: Number.isFinite(state.x) ? state.x : animal.x,
        z: Number.isFinite(state.z) ? state.z : animal.z,
        heading: Number.isFinite(state.heading) ? state.heading : animal.heading,
        speed: clamp(state.speed, 0, 8),
        targetX: Number.isFinite(state.targetX) ? state.targetX : animal.x,
        targetZ: Number.isFinite(state.targetZ) ? state.targetZ : animal.z,
        targetSeconds: clamp(state.targetSeconds, 0, 12),
        alert: clamp(state.alert, 0, 1),
        behavior: state.behavior ?? 'WANDER',
        health: clamp(
          state.health ?? (animal.species === 'WOLF' ? 2 :
            animal.species === 'BEAR' || animal.species === 'POLAR_BEAR' ? 4 : 1),
          0,
          4,
        ),
        warningSeconds: clamp(state.warningSeconds ?? 0, 0, 3),
        woundedSeconds: clamp(state.woundedSeconds ?? 0, 0, 12),
        attackCooldownSeconds: clamp(state.attackCooldownSeconds ?? 0, 0, 12),
        retreatSeconds: clamp(state.retreatSeconds ?? 0, 0, 120),
        hunger: clamp(state.hunger ?? animal.hunger ?? 0.2, 0, 1),
        thirst: clamp(state.thirst ?? animal.thirst ?? 0.18, 0, 1),
        fatigue: clamp(state.fatigue ?? animal.fatigue ?? 0.12, 0, 1),
        homeX: Number.isFinite(state.homeX) ? state.homeX : animal.homeX,
        homeZ: Number.isFinite(state.homeZ) ? state.homeZ : animal.homeZ,
        activitySeconds: clamp(state.activitySeconds ?? 0, 0, 8),
        targetResourceId: state.targetResourceId,
      });
    }
    this.firePits.splice(0, this.firePits.length, ...saved.firePits.map((fire) => {
      const restored: WildernessFirePitState = {
        x: fire.x,
        z: fire.z,
        stage: fire.stage,
        fuelSeconds: Math.max(0, fire.fuelSeconds),
        heatLevel: clamp(fire.heatLevel ?? (fire.stage === 'LIT' ? 0.62 : 0), 0, 1),
        emberSeconds: Math.max(0, fire.emberSeconds ?? 0),
        pendingMeltEnergy: clamp(fire.pendingMeltEnergy ?? 0, 0, 180),
        layStage: fire.layStage === 'WOOD' || fire.layStage === 'TINDER'
          ? fire.layStage
          : 'HOLLOW',
        ignitionProgress: clamp(fire.ignitionProgress ?? 0, 0, 1),
        fuelQueue: fire.fuelQueue?.filter((piece) =>
          piece &&
          (piece.form === 'BRANCH' || piece.form === 'LOG') &&
          (piece.material === 'SPRUCE' || piece.material === 'PINE' || piece.material === 'BIRCH')
        ).map((piece) => ({
          id: Math.max(1, Math.floor(piece.id)),
          material: piece.material,
          form: piece.form,
          ignitionSecondsRemaining: Math.max(0, piece.ignitionSecondsRemaining),
          burnSecondsRemaining: Math.max(0, piece.burnSecondsRemaining),
          burnSecondsTotal: Math.max(1, piece.burnSecondsTotal),
        })),
      };
      this.ensureFireState(restored);
      return restored;
    }));
    this.branchMaterials.splice(
      0,
      this.branchMaterials.length,
      ...(saved.fuelMaterials?.branches ?? []).filter(
        (material): material is WildernessWoodMaterial =>
          material === 'SPRUCE' || material === 'PINE' || material === 'BIRCH',
      ),
    );
    this.logMaterials.splice(
      0,
      this.logMaterials.length,
      ...(saved.fuelMaterials?.logs ?? []).filter(
        (material): material is WildernessWoodMaterial =>
          material === 'SPRUCE' || material === 'PINE' || material === 'BIRCH',
      ),
    );
    this.ensureFuelMaterialInventory();
    this.worldItems.splice(
      0,
      this.worldItems.length,
      ...(saved.worldItems ?? []).flatMap((item) => {
        if (
          !item ||
          !(['LOG', 'BRANCH', 'TINDER', 'STONE', 'STONE_CHIP', 'FLINT', 'FIBER', 'BERRY', 'FISH', 'SMALL_GAME', 'ROOT'] as const).includes(item.kind) ||
          ((item.kind === 'LOG' || item.kind === 'BRANCH') &&
            item.material !== 'SPRUCE' && item.material !== 'PINE' && item.material !== 'BIRCH') ||
          !Number.isFinite(item.x) || !Number.isFinite(item.z)
        ) return [];
        return [{
          id: String(item.id),
          kind: item.kind,
          ...(item.material ? { material: item.material } : {}),
          x: item.x,
          z: item.z,
          heading: Number.isFinite(item.heading) ? item.heading : 0,
          quantity: clamp(Math.round(item.quantity), 1, 8),
        }];
      }),
    );
    this.nextWorldItemId = Math.max(
      1,
      ...this.worldItems.map((item) => {
        const suffix = Number(item.id.split('-').at(-1));
        return Number.isFinite(suffix) ? suffix + 1 : 1;
      }),
    );
    this.shelters.splice(0, this.shelters.length, ...saved.shelters.map((shelter) => ({
      x: shelter.x,
      z: shelter.z,
      heading: shelter.heading,
      stage: clamp(Math.round(shelter.stage), 1, 3) as 1 | 2 | 3,
    })));
    this.snares.splice(0, this.snares.length, ...saved.snares.map((snare) => ({
      x: snare.x,
      z: snare.z,
      ageSeconds: Math.max(0, snare.ageSeconds),
      caught: Boolean(snare.caught),
    })));
    Object.assign(this.fishing, {
      status: saved.fishing.status === 'HOOKED' ||
        saved.fishing.status === 'BITE' ||
        saved.fishing.status === 'WAITING'
        ? saved.fishing.status
        : 'IDLE',
      elapsedSeconds: Math.max(0, saved.fishing.elapsedSeconds),
      biteAtSeconds: Math.max(0, saved.fishing.biteAtSeconds),
      activeHoleId: saved.fishing.activeHoleId,
      reelProgress: clamp(saved.fishing.reelProgress ?? 0, 0, 1),
      reelTarget: clamp(saved.fishing.reelTarget ?? 0.5, 0.18, 0.82),
      missedPulls: clamp(Math.round(saved.fishing.missedPulls ?? 0), 0, 5),
    });
    Object.assign(this.ecosystemStocks, {
      fish: clamp(Math.round(saved.ecosystemStocks?.fish ?? 8), 0, 8),
      smallGame: clamp(Math.round(saved.ecosystemStocks?.smallGame ?? 5), 0, 5),
    });
    const validSkillIds = new Set(WILDERNESS_MILESTONE_CATALOG.flatMap((entry) =>
      entry.unlocks));
    for (const skill of createInitialWildernessProgression().unlockedSkills) {
      validSkillIds.add(skill);
    }
    const validMilestoneIds = new Set(
      WILDERNESS_MILESTONE_CATALOG.map((entry) => entry.id),
    );
    this.progression.unlockedSkills.splice(
      0,
      this.progression.unlockedSkills.length,
      ...new Set([
        ...createInitialWildernessProgression().unlockedSkills,
        ...(saved.progression?.unlockedSkills ?? []).filter((skill) =>
          validSkillIds.has(skill)),
      ]),
    );
    this.progression.completedMilestones.splice(
      0,
      this.progression.completedMilestones.length,
      ...(saved.progression?.completedMilestones ?? []).filter((milestone) =>
        validMilestoneIds.has(milestone)),
    );
    Object.assign(
      this.progression.actionCounts,
      Object.fromEntries(Object.entries(saved.progression?.actionCounts ?? {})
        .filter(([, count]) => Number.isFinite(count))
        .map(([kind, count]) => [kind, Math.max(0, Math.floor(count))])),
    );
    this.iceHoles.splice(
      0,
      this.iceHoles.length,
      ...(saved.iceHoles ?? []).flatMap((hole) => {
        if (!hole || !Number.isFinite(hole.x) || !Number.isFinite(hole.z)) return [];
        return [{
          id: String(hole.id),
          x: hole.x,
          z: hole.z,
          progress: clamp(hole.progress, 0, 1),
          open: Boolean(hole.open),
          refreezeProgress: clamp(hole.refreezeProgress ?? 0, 0, 1),
        }];
      }),
    );
    this.nextIceHoleId = Math.max(
      1,
      ...this.iceHoles.map((hole) => {
        const suffix = Number(hole.id.split('-').at(-1));
        return Number.isFinite(suffix) ? suffix + 1 : 1;
      }),
    );
    this.foodBuffs.splice(
      0,
      this.foodBuffs.length,
      ...(saved.foodBuffs ?? []).flatMap((buff) => {
        if (
          !buff ||
          !WILDERNESS_FOOD_CATALOG.some((food) => food.bonus === buff.id) ||
          !Number.isFinite(buff.remainingSeconds)
        ) return [];
        return [{
          id: String(buff.id),
          remainingSeconds: clamp(buff.remainingSeconds, 0, 600),
        }];
      }),
    );
  }
}
