import { Color } from 'three';
import type { DayNightState } from './DayNightSystem';
import type { WeatherState } from './WeatherSystem';
import { clamp, smoothstep } from '../utils/math';

export interface EnvironmentPresentationState {
  readonly skyHorizonColor: Color;
  readonly skyZenithColor: Color;
  readonly cloudColor: Color;
  readonly sunColor: Color;
  readonly moonColor: Color;
  readonly fogColor: Color;
  readonly seaDeepColor: Color;
  readonly seaMidColor: Color;
  readonly seaShallowColor: Color;
  readonly seaLightColor: Color;
  readonly oceanCloudColor: Color;
  cloudOpacity: number;
  oceanCloudAmount: number;
  oceanCloudScale: number;
  oceanCloudSpeed: number;
  oceanCloudContrast: number;
  haze: number;
  sunIntensity: number;
  moonIntensity: number;
  fogDensity: number;
  iceContrast: number;
  iceWarmth: number;
  iceWetnessEmphasis: number;
  iceSnowLightResponse: number;
  starVisibility: number;
  auroraVisibility: number;
  artificialLight: number;
  daylight: number;
  night: number;
  twilight: number;
  warmth: number;
}

const CLEAR_SKY = new Color(0x9ed1df);
const COVERED_SKY = new Color(0x718d98);
const EVENING_SKY = new Color(0xe1a16f);
const TWILIGHT_SKY = new Color(0x486786);
const NIGHT_SKY = new Color(0x071b30);
const CLEAR_FOG = new Color(0x92c8d7);
const COVERED_FOG = new Color(0x829ba4);
const EVENING_FOG = new Color(0xb58b78);
const TWILIGHT_FOG = new Color(0x536f89);
const NIGHT_FOG = new Color(0x183149);
const DEEP_SEA = new Color(0x031725);
const COVERED_DEEP_SEA = new Color(0x102a33);
const MID_SEA = new Color(0x073f52);
const COVERED_MID_SEA = new Color(0x294d56);
const SHALLOW_SEA = new Color(0x147781);
const COVERED_SHALLOW_SEA = new Color(0x4f7477);
const SEA_LIGHT = new Color(0x94c4d2);
const COVERED_SEA_LIGHT = new Color(0xa9c2c3);
const NIGHT_DEEP_SEA = new Color(0x031927);
const NIGHT_MID_SEA = new Color(0x0b3446);
const NIGHT_SHALLOW_SEA = new Color(0x225565);
const NIGHT_SEA_LIGHT = new Color(0x6f9fba);
const DAY_SUN = new Color(0xfff5db);
const EVENING_SUN = new Color(0xffad68);
const NIGHT_SUN = new Color(0x9bc9ef);
const MOON = new Color(0x9bcfff);
const CLOUD = new Color(0xd7e2e1);

export const createEnvironmentPresentationState =
  (): EnvironmentPresentationState => ({
    skyHorizonColor: CLEAR_FOG.clone(),
    skyZenithColor: CLEAR_SKY.clone(),
    cloudColor: CLOUD.clone(),
    sunColor: DAY_SUN.clone(),
    moonColor: MOON.clone(),
    fogColor: CLEAR_FOG.clone(),
    seaDeepColor: DEEP_SEA.clone(),
    seaMidColor: MID_SEA.clone(),
    seaShallowColor: SHALLOW_SEA.clone(),
    seaLightColor: SEA_LIGHT.clone(),
    oceanCloudColor: CLOUD.clone(),
    cloudOpacity: 0.04,
    oceanCloudAmount: 0,
    oceanCloudScale: 0.075,
    oceanCloudSpeed: 0.02,
    oceanCloudContrast: 0.3,
    haze: 0,
    sunIntensity: 1,
    moonIntensity: 0,
    fogDensity: 0.0042,
    iceContrast: 1,
    iceWarmth: 0,
    iceWetnessEmphasis: 1,
    iceSnowLightResponse: 1,
    starVisibility: 0,
    auroraVisibility: 0,
    artificialLight: 0.08,
    daylight: 1,
    night: 0,
    twilight: 0,
    warmth: 0,
  });

export const resolveEnvironmentPresentation = (
  weather: Readonly<WeatherState>,
  day: Readonly<DayNightState>,
  target: EnvironmentPresentationState =
    createEnvironmentPresentationState(),
): EnvironmentPresentationState => {
  const cloud = clamp(weather.cloudCover, 0, 1);
  const fogFactor = clamp(
    (weather.fogDensity - 0.0105) / 0.0165,
    0,
    1,
  );
  const night = clamp(day.night, 0, 1);
  const twilight = clamp(day.twilight, 0, 1);
  const warmth = clamp(day.warmth, 0, 1);
  const daylight = clamp(day.daylight, 0.15, 1);
  const weatherMood = clamp(
    cloud * 0.32 + fogFactor * 0.12,
    0,
    0.42,
  );

  target.skyZenithColor
    .copy(CLEAR_SKY)
    .lerp(EVENING_SKY, warmth * 0.76)
    .lerp(TWILIGHT_SKY, twilight * 0.78)
    .lerp(NIGHT_SKY, night * 0.96)
    .lerp(COVERED_SKY, clamp(cloud * 0.62 + fogFactor * 0.18, 0, 0.8));
  target.skyHorizonColor
    .copy(CLEAR_FOG)
    .lerp(EVENING_FOG, warmth * 0.64)
    .lerp(TWILIGHT_FOG, twilight * 0.72)
    .lerp(NIGHT_FOG, night * 0.94)
    .lerp(COVERED_FOG, clamp(cloud * 0.48 + fogFactor * 0.3, 0, 0.82));
  target.fogColor.copy(target.skyHorizonColor);
  target.cloudColor
    .copy(CLOUD)
    .lerp(COVERED_SKY, cloud * 0.38)
    .lerp(NIGHT_SKY, night * 0.72)
    .lerp(EVENING_SKY, warmth * 0.16);
  target.sunColor
    .copy(DAY_SUN)
    .lerp(EVENING_SUN, warmth * 0.88)
    .lerp(NIGHT_SUN, night * 0.7);
  target.moonColor.copy(MOON);

  target.seaDeepColor
    .copy(DEEP_SEA)
    .lerp(NIGHT_DEEP_SEA, night * 0.82)
    .lerp(COVERED_DEEP_SEA, weatherMood);
  target.seaMidColor
    .copy(MID_SEA)
    .lerp(NIGHT_MID_SEA, night * 0.78)
    .lerp(COVERED_MID_SEA, weatherMood);
  target.seaShallowColor
    .copy(SHALLOW_SEA)
    .lerp(NIGHT_SHALLOW_SEA, night * 0.72)
    .lerp(COVERED_SHALLOW_SEA, weatherMood);
  target.seaLightColor
    .copy(SEA_LIGHT)
    .lerp(EVENING_SUN, warmth * 0.18)
    .lerp(NIGHT_SEA_LIGHT, night * 0.74)
    .lerp(COVERED_SEA_LIGHT, weatherMood * 0.76);
  target.oceanCloudColor
    .copy(target.cloudColor)
    .lerp(target.skyHorizonColor, 0.24)
    .lerp(NIGHT_MID_SEA, night * 0.22);

  const sunVisibility = smoothstep(-0.02, 0.22, day.sunHeight);
  target.cloudOpacity = clamp(
    cloud * (0.5 + fogFactor * 0.24),
    0,
    0.92,
  );
  const oceanCloudAmount = smoothstep(0.14, 0.84, cloud);
  const windFactor = smoothstep(
    0.68,
    1.55,
    weather.windMultiplier,
  );
  target.oceanCloudAmount = oceanCloudAmount;
  target.oceanCloudScale =
    0.075 - oceanCloudAmount * 0.038 -
    weather.snowIntensity * 0.01;
  target.oceanCloudSpeed =
    0.018 + windFactor * 0.052;
  target.oceanCloudContrast = clamp(
    0.28 +
      oceanCloudAmount * 0.22 +
      weather.snowIntensity * 0.24 +
      fogFactor * 0.08,
    0.28,
    0.82,
  );
  target.haze = clamp(fogFactor * 0.82 + cloud * 0.18, 0, 1);
  target.sunIntensity =
    sunVisibility * (0.82 + daylight * 0.38) * (1 - cloud * 0.76);
  target.moonIntensity =
    smoothstep(0.2, 0.86, night) * (1 - cloud * 0.58);
  // Fog and a true white-out must materially shorten the readable horizon.
  // The previous compressed range made the dedicated fog profile barely
  // distinguishable from overcast weather in character view.
  target.fogDensity =
    0.0038 + cloud * 0.001 + fogFactor * 0.0062 +
    weather.snowIntensity * 0.00115;
  target.iceContrast = clamp(weather.iceContrast, 0.75, 1.1);
  target.iceWarmth = clamp(
    warmth * 0.72 -
      cloud * 0.12 -
      weather.snowIntensity * 0.18,
    -1,
    1,
  );
  target.iceWetnessEmphasis = clamp(
    0.88 + weather.windMultiplier * 0.08 + fogFactor * 0.16,
    0.75,
    1.35,
  );
  target.iceSnowLightResponse = clamp(
    1.08 - cloud * 0.18 + daylight * 0.08,
    0.72,
    1.18,
  );
  target.starVisibility =
    day.starVisibility * (1 - cloud * 0.96);
  target.auroraVisibility =
    target.starVisibility *
    smoothstep(0.58, 0.96, night) *
    (1 - cloud);
  target.artificialLight = day.artificialLight;
  target.daylight = daylight;
  target.night = night;
  target.twilight = twilight;
  target.warmth = warmth;
  return target;
};
