import type { SettlementContentRegistry } from './SettlementContentRegistry';
import type {
  SettlementGoodAmount,
  SettlementWarehouseSaveData,
  SettlementWarehouseSnapshot,
} from './SettlementTypes';

const validQuantity = (value: number): boolean =>
  Number.isSafeInteger(value) && value >= 0;

/** Atomic integer store for bulk village goods; character inventory stays separate. */
export class SettlementWarehouse {
  private readonly quantities = new Map<string, number>();
  private revision = 0;

  public constructor(
    private readonly registry: SettlementContentRegistry,
    saved?: Readonly<SettlementWarehouseSaveData>,
  ) {
    for (const good of registry.definitions.goods) this.quantities.set(good.id, 0);
    if (saved?.version !== 1 || !Array.isArray(saved.goods)) return;
    this.revision = validQuantity(saved.revision) ? saved.revision : 0;
    for (const entry of saved.goods) {
      const definition = registry.getGood(entry?.goodId);
      if (!definition || !validQuantity(entry.quantity)) continue;
      this.quantities.set(
        entry.goodId,
        Math.min(definition.maximumWarehouseQuantity, entry.quantity),
      );
    }
  }

  public getQuantity(goodId: string): number {
    return this.quantities.get(goodId) ?? 0;
  }

  public canApply(changes: readonly Readonly<SettlementGoodAmount>[], sign: 1 | -1): boolean {
    const totals = this.aggregate(changes, sign);
    if (!totals) return false;
    for (const [goodId, delta] of totals) {
      const definition = this.registry.getGood(goodId);
      if (!definition) return false;
      const next = this.getQuantity(goodId) + delta;
      if (next < 0 || next > definition.maximumWarehouseQuantity) return false;
    }
    return true;
  }

  public apply(changes: readonly Readonly<SettlementGoodAmount>[], sign: 1 | -1): boolean {
    const totals = this.aggregate(changes, sign);
    if (!totals || !this.canApply(changes, sign)) return false;
    let changed = false;
    for (const [goodId, delta] of totals) {
      if (delta === 0) continue;
      this.quantities.set(goodId, this.getQuantity(goodId) + delta);
      changed = true;
    }
    if (changed) this.revision += 1;
    return changed;
  }

  public snapshot(): SettlementWarehouseSnapshot {
    return {
      revision: this.revision,
      goods: this.registry.definitions.goods.map((definition) => ({
        goodId: definition.id,
        quantity: this.getQuantity(definition.id),
      })),
    };
  }

  public exportState(): SettlementWarehouseSaveData {
    return { version: 1, ...this.snapshot() };
  }

  private aggregate(
    changes: readonly Readonly<SettlementGoodAmount>[],
    sign: 1 | -1,
  ): Map<string, number> | undefined {
    if (!Array.isArray(changes)) return undefined;
    const result = new Map<string, number>();
    for (const change of changes) {
      if (!this.registry.getGood(change?.goodId) || !validQuantity(change.quantity)) {
        return undefined;
      }
      result.set(
        change.goodId,
        (result.get(change.goodId) ?? 0) + change.quantity * sign,
      );
    }
    return result;
  }
}
