export class LandSnowSystem {
  private static readonly MAXIMUM_CACHED_TILES = 64;
  private readonly normalMinColumnScratch = new Int16Array(
    LAND_SNOW_SAMPLES,
  );
  private readonly normalMaxColumnScratch = new Int16Array(
    LAND_SNOW_SAMPLES,
  );
  private readonly root = new Group();
  private readonly material = new MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.94,
    metalness: 0,
  });
  private readonly activeTiles = new Map<string, LandSnowTile>();
  private readonly cachedTiles = new Map<string, LandSnowTile>();
  private readonly savedTiles = new Map<string, LandSnowTileSaveData>();
  private readonly pendingDirtyTiles = new Set<LandSnowTile>();
  private readonly prefetchQueue: Array<readonly [number, number]> = [];
  private readonly queuedPrefetchKeys = new Set<string>();
  private prefetchJob?: LandSnowTileBuildJob;
  private centerTileX?: number;
  private centerTileZ?: number;
  private lastCenterX?: number;
  private lastCenterZ?: number;
  private changedSamples = 0;
  private movedSnow = 0;
  private lastRemovedSnow = 0;
  private lastDepositedSnow = 0;
  private tileActivations = 0;
  private meshUpdates = 0;
  private updatedVertices = 0;
  private lastStreamMs = 0;
  private lastPrefetchMs = 0;
  private lastFlushMs = 0;
  private weatherTileCursor = 0;
  private dynamicExclusionSampler?: LandSnowDynamicExclusionSampler;
  private readonly mutationListeners = new Set<LandSnowMutationListener>();
  private readonly detailCoveredTileKeys = new Set<string>();
  private readonly removeTerrainListener: () => void;

  public constructor(
    scene: Scene,
    private readonly activeRadius = 2,
    private readonly trace?: LandSnowTraceSink,
    private readonly terrain: TerrainHeightSystem = new TerrainHeightSystem(),
  ) {
    this.root.name = 'Borealis deformable land snow tiles';
    scene.add(this.root);
    this.removeTerrainListener = this.terrain.addListener((bounds) =>
      this.onTerrainEdited(bounds),
    );
  }

  public setActiveCenter(x: number, z: number): void {
    const centerTileX = Math.floor(x / LAND_SNOW_TILE_SIZE);
    const centerTileZ = Math.floor(z / LAND_SNOW_TILE_SIZE);
    if (
      centerTileX === this.centerTileX &&
      centerTileZ === this.centerTileZ
    ) {
      this.lastCenterX = x;
      this.lastCenterZ = z;
      return;
    }
    const startedAt = performance.now();
    let activatedTiles = 0;
    let reusedTiles = 0;
    let generatedTiles = 0;
    let releasedTiles = 0;
    const movementX = this.lastCenterX === undefined ? 0 : x - this.lastCenterX;
    const movementZ = this.lastCenterZ === undefined ? 0 : z - this.lastCenterZ;
    this.centerTileX = centerTileX;
    this.centerTileZ = centerTileZ;
    this.lastCenterX = x;
    this.lastCenterZ = z;
    const requested = new Set<string>();
    for (
      let tileZ = centerTileZ - this.activeRadius;
      tileZ <= centerTileZ + this.activeRadius;
      tileZ += 1
    ) {
      for (
        let tileX = centerTileX - this.activeRadius;
        tileX <= centerTileX + this.activeRadius;
        tileX += 1
      ) {
        if (!this.tileTouchesLand(tileX, tileZ)) continue;
        const key = tileKey(tileX, tileZ);
        requested.add(key);
        if (!this.activeTiles.has(key)) {
          const source = this.activateTile(tileX, tileZ);
          activatedTiles += 1;
          if (source === 'cache') reusedTiles += 1;
          else generatedTiles += 1;
        }
      }
    }
    for (const [key, tile] of this.activeTiles) {
      if (requested.has(key)) continue;
      this.storeTile(tile);
      this.root.remove(tile.mesh);
      this.pendingDirtyTiles.delete(tile);
      this.activeTiles.delete(key);
      this.cacheTile(key, tile);
      releasedTiles += 1;
    }
    this.queuePrefetchRing(
      centerTileX,
      centerTileZ,
      x,
      z,
      movementX,
      movementZ,
    );
    this.lastStreamMs = performance.now() - startedAt;
    if (activatedTiles > 0 || releasedTiles > 0) {
      this.trace?.(
        'land-snow-stream',
        {
          activatedTiles,
          reusedTiles,
          generatedTiles,
          releasedTiles,
          activeTiles: this.activeTiles.size,
          cachedTiles: this.cachedTiles.size,
          queuedPrefetchTiles: this.prefetchQueue.length +
            (this.prefetchJob ? 1 : 0),
          centerTileX,
          centerTileZ,
        },
        this.lastStreamMs,
      );
    }
  }

  /**
   * Advances dormant tile construction in small row-sized pieces. The hard
   * budget is checked between rows; only final normal/bounds generation may
   * slightly exceed it once per completed tile.
   */
  public processPrefetchBudget(budgetMs = 1.5): number {
    const startedAt = performance.now();
    const deadline = startedAt + clamp(budgetMs, 0.25, 5);
    let completedTiles = 0;
    let processedRows = 0;
    do {
      if (!this.prefetchJob) this.prefetchJob = this.takeNextPrefetchJob();
      const job = this.prefetchJob;
      if (!job) break;
      const completed = this.advanceTileBuild(job);
      processedRows += 1;
      if (completed) {
        this.prefetchJob = undefined;
        this.queuedPrefetchKeys.delete(job.key);
        if (!this.activeTiles.has(job.key)) {
          this.cacheTile(job.key, completed);
          completedTiles += 1;
        } else {
          completed.geometry.dispose();
        }
      }
    } while (performance.now() < deadline);
    this.lastPrefetchMs = performance.now() - startedAt;
    if (completedTiles > 0 || this.lastPrefetchMs >= 4) {
      this.trace?.(
        'land-snow-prefetch',
        {
          completedTiles,
          processedRows,
          cachedTiles: this.cachedTiles.size,
          queuedTiles: this.prefetchQueue.length +
            (this.prefetchJob ? 1 : 0),
        },
        this.lastPrefetchMs,
      );
    }
    return completedTiles;
  }

  /** Flushes all track and blade mutations once after the fixed-step batch. */
  public flushVisualUpdates(): number {
    if (this.pendingDirtyTiles.size === 0) {
      this.lastFlushMs = 0;
      return 0;
    }
    const startedAt = performance.now();
    const dirtyTiles = this.pendingDirtyTiles.size;
    let updatedVertices = 0;
    for (const tile of this.pendingDirtyTiles) {
      const mutationBounds = tile.dirty && tile.dirtyMaxColumn >= tile.dirtyMinColumn
        ? {
            minX: tile.tileX * LAND_SNOW_TILE_SIZE +
              tile.dirtyMinColumn * LAND_SNOW_SPACING,
            maxX: tile.tileX * LAND_SNOW_TILE_SIZE +
              tile.dirtyMaxColumn * LAND_SNOW_SPACING,
            minZ: tile.tileZ * LAND_SNOW_TILE_SIZE +
              tile.dirtyMinRow * LAND_SNOW_SPACING,
            maxZ: tile.tileZ * LAND_SNOW_TILE_SIZE +
              tile.dirtyMaxRow * LAND_SNOW_SPACING,
          }
        : undefined;
      updatedVertices += this.updateTileMesh(tile);
      if (mutationBounds) {
        for (const listener of this.mutationListeners) listener(mutationBounds);
      }
    }
    this.pendingDirtyTiles.clear();
    this.lastFlushMs = performance.now() - startedAt;
    this.meshUpdates += dirtyTiles;
    this.updatedVertices += updatedVertices;
    if (this.lastFlushMs >= 1) {
      this.trace?.(
        'land-snow-mesh-flush',
        { dirtyTiles, updatedVertices },
        this.lastFlushMs,
      );
    }
    return updatedVertices;
  }

  public setVisible(visible: boolean): void {
    this.root.visible = visible;
  }

  public addMutationListener(listener: LandSnowMutationListener): () => void {
    this.mutationListeners.add(listener);
    return () => this.mutationListeners.delete(listener);
  }

  /** Coarse V3 tiles covered by a finer local mesh stay simulated but hidden. */
  public setDetailCoveredTileKeys(keys: ReadonlySet<string>): void {
    this.detailCoveredTileKeys.clear();
    for (const key of keys) this.detailCoveredTileKeys.add(key);
    for (const [key, tile] of this.activeTiles) {
      tile.mesh.visible = !this.detailCoveredTileKeys.has(key);
    }
  }

  public isSnowSurfaceExcludedAt(x: number, z: number): boolean {
    return this.isSnowExcluded(x, z);
  }

  public isTileActiveAt(x: number, z: number): boolean {
    return this.activeTiles.has(tileKey(
      Math.floor(x / LAND_SNOW_TILE_SIZE),
      Math.floor(z / LAND_SNOW_TILE_SIZE),
    ));
  }

  /**
   * Dynamic holes such as excavated cave shafts are not terrain paint. They
   * remove both snow mass and snow-mesh triangles without altering the base
   * world raster, and are rebuilt only when excavation changes.
   */
  public setDynamicExclusionSampler(
    sampler: LandSnowDynamicExclusionSampler | undefined,
  ): void {
    this.dynamicExclusionSampler = sampler;
  }

  public refreshDynamicExclusion(bounds: Readonly<{
    minX: number;
    maxX: number;
    minZ: number;
    maxZ: number;
  }>): void {
    for (const [key, tile] of [...this.cachedTiles]) {
      if (!this.tileIntersectsBounds(tile.tileX, tile.tileZ, bounds)) continue;
      this.cachedTiles.delete(key);
      tile.geometry.dispose();
    }
    if (this.prefetchJob && this.tileIntersectsBounds(
      this.prefetchJob.tileX,
      this.prefetchJob.tileZ,
      bounds,
    )) {
      this.queuedPrefetchKeys.delete(this.prefetchJob.key);
      this.prefetchJob = undefined;
    }
    for (const tile of this.activeTiles.values()) {
      if (!this.tileIntersectsBounds(tile.tileX, tile.tileZ, bounds)) continue;
      for (let row = 0; row < LAND_SNOW_SAMPLES; row += 1) {
        const z = tile.tileZ * LAND_SNOW_TILE_SIZE + row * LAND_SNOW_SPACING;
        for (let column = 0; column < LAND_SNOW_SAMPLES; column += 1) {
          const x = tile.surfaceX[sampleIndex(column, row)] ?? 0;
          if (!this.isSnowExcluded(x, z)) continue;
          const index = sampleIndex(column, row);
          tile.depth[index] = 0;
          tile.compaction[index] = 0;
        }
      }
      const previous = tile.geometry;
      tile.geometry = this.createTileGeometry(
        tile.tileX,
        tile.tileZ,
        tile.depth,
        tile.compaction,
        tile.cellularTint,
        tile.edgeSnowDepth,
        tile.surfaceX,
      );
      tile.mesh.geometry = tile.geometry;
      previous.dispose();
      this.pendingDirtyTiles.delete(tile);
    }
  }

  public sampleDepth(x: number, z: number): number {
    if (this.isSnowExcluded(x, z)) return 0;
    return this.readGridSample(x, z).depth;
  }

  /** Monotonic within one runtime; consumers also compare measurement time after load. */
  public getMutationRevision(): number {
    return this.changedSamples;
  }

  public sampleSurfaceHeight(x: number, z: number): number {
    const minimumX = Math.floor(x / LAND_SNOW_SPACING) * LAND_SNOW_SPACING;
    const minimumZ = Math.floor(z / LAND_SNOW_SPACING) * LAND_SNOW_SPACING;
    const maximumX = minimumX + LAND_SNOW_SPACING;
    const maximumZ = minimumZ + LAND_SNOW_SPACING;
    const blendX = smoothstep(
      0,
      1,
      (x - minimumX) / LAND_SNOW_SPACING,
    );
    const blendZ = smoothstep(
      0,
      1,
      (z - minimumZ) / LAND_SNOW_SPACING,
    );
    const near = lerp(
      this.sampleSurfaceHeightAtGridPoint(minimumX, minimumZ),
      this.sampleSurfaceHeightAtGridPoint(maximumX, minimumZ),
      blendX,
    );
    const far = lerp(
      this.sampleSurfaceHeightAtGridPoint(minimumX, maximumZ),
      this.sampleSurfaceHeightAtGridPoint(maximumX, maximumZ),
      blendX,
    );
    return lerp(near, far, blendZ);
  }

  private sampleSurfaceHeightAtGridPoint(
    x: number,
    z: number,
  ): number {
    if (this.isSnowExcluded(x, z)) {
      return this.terrain.sampleHeight(x, z);
    }
    const tileX = Math.floor(x / LAND_SNOW_TILE_SIZE);
    const tileZ = Math.floor(z / LAND_SNOW_TILE_SIZE);
    const tile = this.activeTiles.get(tileKey(tileX, tileZ));
    if (!tile) {
      const depth = initialSnowDepth(x, z);
      return this.terrain.sampleHeight(x, z) + 0.012 + visualSnowHeight(depth, 0);
    }
    const localX = x - tileX * LAND_SNOW_TILE_SIZE;
    const localZ = z - tileZ * LAND_SNOW_TILE_SIZE;
    const column = clamp(
      Math.round(localX / LAND_SNOW_SPACING),
      0,
      LAND_SNOW_SEGMENTS,
    );
    const row = clamp(
      Math.round(localZ / LAND_SNOW_SPACING),
      0,
      LAND_SNOW_SEGMENTS,
    );
    const index = sampleIndex(column, row);
    const depth = tile.depth[index] ?? 0;
    const packed = tile.compaction[index] ?? 0;
    return (
      this.terrain.sampleHeight(x, z) +
      0.012 +
      visualSnowHeight(depth, packed)
    );
  }

  public plowSweep(
    previousX: number,
    previousZ: number,
    x: number,
    z: number,
    heading: number,
    configuration: LandSnowPlowConfiguration = {
      bladePosition: 1,
      bladeMode: 'STRAIGHT',
      bladeWidth: 2.15,
    },
  ): LandSnowPlowResult {
    const bladeWidth = configuration.bladeWidth ?? 2.15;
    const bladeForwardOffset = Math.max(
      0.7,
      configuration.bladeForwardOffset ?? 1.43,
    );
    const contactDepth = clamp(configuration.contactDepth ?? 0.64, 0.3, 1.2);
    const contactBack = contactDepth * 0.53;
    const contactFront = contactDepth - contactBack;
    const bladePosition = clamp(configuration.bladePosition, 0, 1);
    const maximumPushDepth = Math.max(
      0.08,
      configuration.maximumPushDepth ?? LEGACY_MAXIMUM_SNOW_DEPTH,
    );
    const maximumPileDepth = clamp(
      configuration.maximumPileDepth ?? LEGACY_MAXIMUM_SNOW_DEPTH,
      0.2,
      MAXIMUM_SNOW_DEPTH,
    );
    const massCapacityMultiplier = Math.max(
      0.2,
      configuration.massCapacityMultiplier ?? 1,
    );
    const profile = BULLDOZER_BLADE_PROFILES[configuration.bladeMode];
    const maximumFrontPileDepth = configuration.maximumFrontPileDepth === undefined
      ? Math.min(
          maximumPileDepth,
          Math.max(
            profile.frontPileDepth,
            maximumPileDepth *
              (configuration.bladeMode === 'SCOOP' ? 1 :
                configuration.bladeMode === 'STRAIGHT' ? 0.82 : 0.56),
          ),
        )
      : clamp(
          configuration.maximumFrontPileDepth,
          0.2,
          maximumPileDepth,
        );
    const travel = Math.hypot(x - previousX, z - previousZ);
    if (travel < 0.008) {
      return {
        removedSnow: 0,
        depositedSnow: 0,
        changedSamples: 0,
        resistance: 0,
        peakPileDepth: 0,
        overCapacity: 0,
      };
    }
    const forwardX = Math.sin(heading);
    const forwardZ = Math.cos(heading);
    const rightX = Math.cos(heading);
    const rightZ = -Math.sin(heading);
    const maximumBladeAngle = Math.PI * 0.155;
    const bladeAngle = clamp(
      configuration.bladeAngleRadians ?? 0,
      -maximumBladeAngle,
      maximumBladeAngle,
    );
    const angleStrength = clamp(
      Math.abs(bladeAngle) / maximumBladeAngle,
      0,
      1,
    );
    const dischargeSide = bladeAngle < 0 ? -1 : bladeAngle > 0 ? 1 : 0;
    const bladeCos = Math.cos(bladeAngle);
    const bladeSin = Math.sin(bladeAngle);
    const bladeNormalX = forwardX * bladeCos + rightX * bladeSin;
    const bladeNormalZ = forwardZ * bladeCos + rightZ * bladeSin;
    const bladeTangentX = rightX * bladeCos - forwardX * bladeSin;
    const bladeTangentZ = rightZ * bladeCos - forwardZ * bladeSin;
    const steps = Math.max(
      1,
      Math.ceil(travel / (LAND_SNOW_SPACING * 0.45)),
    );
    const dirtyTiles = new Set<LandSnowTile>();
    let removedSnow = 0;
    let changedSamples = 0;
    let encounteredPileDepth = 0;
    let encounteredPileMass = 0;
    let overCapacity = 0;
    type WeightedDeposit = {
      sample: MutableSample;
      weight: number;
    };
    const sourceSamples = new Map<string, WeightedDeposit>();
    const addWeightedSample = (
      target: Map<string, WeightedDeposit>,
      sample: MutableSample,
      weight: number,
    ): void => {
      if (weight <= 0) return;
      const key =
        `${sample.tile.tileX},${sample.tile.tileZ}:` +
        `${sample.index}`;
      const previous = target.get(key);
      if (previous) previous.weight += weight;
      else target.set(key, { sample, weight });
    };

    for (let step = 1; step <= steps; step += 1) {
      const progress = step / steps;
      const vehicleX = lerp(previousX, x, progress);
      const vehicleZ = lerp(previousZ, z, progress);
      const bladeX = vehicleX + forwardX * bladeForwardOffset;
      const bladeZ = vehicleZ + forwardZ * bladeForwardOffset;
      const samples = this.samplesInRadius(
        bladeX,
        bladeZ,
        bladeWidth * 0.72,
      );
      for (const sample of samples) {
        const offsetX = sample.x - bladeX;
        const offsetZ = sample.z - bladeZ;
        const forward = offsetX * bladeNormalX + offsetZ * bladeNormalZ;
        const lateral = offsetX * bladeTangentX + offsetZ * bladeTangentZ;
        if (
          Math.abs(lateral) > bladeWidth * 0.5 ||
          forward < -contactBack ||
          forward > contactFront
        ) {
          continue;
        }
        const current = sample.tile.depth[sample.index] ?? 0;
        const edgeLift =
          Math.abs(lateral) / Math.max(0.01, bladeWidth * 0.5) * 0.035;
        const target = lerp(0.9, 0.035, bladePosition) + edgeLift;
        if (current <= target) continue;
        const lateralInfluence =
          1 -
          clamp(
            Math.abs(lateral) / Math.max(0.01, bladeWidth * 0.5),
            0,
            1,
          );
        encounteredPileDepth = Math.max(
          encounteredPileDepth,
          current,
        );
        encounteredPileMass +=
          Math.max(0, current - Math.max(target, 0.66)) *
          (0.35 + lateralInfluence * 0.65) /
          steps;
        const engagedDepth = current - target;
        const capacityRatio = clamp(
          maximumPushDepth / Math.max(0.001, engagedDepth),
          0.06,
          1,
        );
        overCapacity = Math.max(
          overCapacity,
          clamp(
            (engagedDepth - maximumPushDepth) /
              Math.max(0.12, maximumPushDepth),
            0,
            1,
          ),
        );
        const removal = Math.min(
          current - target,
          (0.052 + travel * 0.3 / steps) *
            (0.4 + bladePosition * 0.6) *
            capacityRatio *
            massCapacityMultiplier,
        );
        sample.tile.depth[sample.index] = current - removal;
        sample.tile.compaction[sample.index] = Math.max(
          sample.tile.compaction[sample.index] ?? 0,
          0.72,
        );
        removedSnow += removal;
        changedSamples += 1;
        addWeightedSample(sourceSamples, sample, removal);
        this.markTileDirty(sample.tile, sample.index, dirtyTiles);
      }
    }

    let depositedSnow = 0;
    let peakPileDepth = 0;
    let blockedDepositFraction = 0;
    if (removedSnow > 0) {
      const frontSamples = new Map<string, WeightedDeposit>();
      const sideSamples = new Map<string, WeightedDeposit>();
      const depositInto = (
        candidates: ReadonlyMap<string, WeightedDeposit>,
        requestedSnow: number,
        maximumDepth: number,
        compactionFloor: number,
      ): number => {
        let remaining = requestedSnow;
        for (let pass = 0; pass < 3 && remaining > 0.0001; pass += 1) {
          const eligible = [...candidates.values()].filter(
            ({ sample }) =>
              (sample.tile.depth[sample.index] ?? 0) <
              maximumDepth - 0.0001,
          );
          const totalWeight = eligible.reduce(
            (total, candidate) => total + candidate.weight,
            0,
          );
          if (totalWeight <= 0.0001) break;
          const snowAtStart = remaining;
          let applied = 0;
          for (const { sample, weight } of eligible) {
            const current = sample.tile.depth[sample.index] ?? 0;
            const capacity = Math.max(0, maximumDepth - current);
            const addition = Math.min(
              capacity,
              snowAtStart * weight / totalWeight,
            );
            if (addition <= 0.00001) continue;
            sample.tile.depth[sample.index] = current + addition;
            sample.tile.compaction[sample.index] = Math.max(
              (sample.tile.compaction[sample.index] ?? 0) * 0.82,
              compactionFloor,
            );
            applied += addition;
            depositedSnow += addition;
            changedSamples += 1;
            this.markTileDirty(sample.tile, sample.index, dirtyTiles);
          }
          remaining -= applied;
          if (applied <= 0.0001) break;
        }
        return remaining;
      };

      // Blade profiles were authored for the starter blade at 1.43 m. Shift
      // the complete wave with a longer chassis so the pile never forms
      // inside or behind the visible heavy blade.
      const profileForward =
        profile.depositForward + (bladeForwardOffset - 1.43);
      const minimumDepositForward =
        bladeForwardOffset + contactFront + LAND_SNOW_SPACING * 0.18;
      const depositForward = Math.max(profileForward, minimumDepositForward);
      const frontX = x + forwardX * depositForward;
      const frontZ = z + forwardZ * depositForward;
      // A moving wedge is broad and aerated rather than a narrow column. The
      // wider footprint roughly halves early height growth while repeated
      // deliveries can still reach the same physical depth ceiling.
      const frontHalfWidth = bladeWidth * 0.78;
      const frontWaveSpread = profile.frontWaveSpread * 1.2;
      const frontRadius = Math.hypot(
        frontHalfWidth,
        frontWaveSpread,
      );
      for (const sample of this.samplesInRadius(
        frontX,
        frontZ,
        frontRadius,
      )) {
        const offsetX = sample.x - frontX;
        const offsetZ = sample.z - frontZ;
        const lateral = offsetX * rightX + offsetZ * rightZ;
        const forward = offsetX * forwardX + offsetZ * forwardZ;
        const vehicleForward =
          (sample.x - x) * forwardX + (sample.z - z) * forwardZ;
        const lateralDistance = Math.abs(lateral) / frontHalfWidth;
        const forwardDistance =
          Math.abs(forward) / frontWaveSpread;
        if (
          lateralDistance > 1 ||
          forwardDistance > 1 ||
          vehicleForward < minimumDepositForward
        ) continue;
        const crossSection =
          (1 - smoothstep(0.08, 1, lateralDistance)) *
          (1 - smoothstep(0.08, 1, forwardDistance));
        const modeShape =
          configuration.bladeMode === 'SCOOP'
            ? 1.3 - lateralDistance * 0.48
            : configuration.bladeMode === 'V_PLOW'
              ? 0.38 + lateralDistance * 0.92
              : 0.86 + (1 - lateralDistance) * 0.24;
        addWeightedSample(
          frontSamples,
          sample,
          (0.09 + crossSection * 1.08) * modeShape,
        );
      }

      const depositSides =
        configuration.bladeMode === 'SCOOP'
          ? [0]
          : [-1, 1];
      for (const side of depositSides) {
        const lateralDistance = configuration.bladeMode === 'SCOOP'
          ? 0
          : side * (profile.depositLateral + angleStrength * 0.78);
        const sideBias = configuration.bladeMode === 'SCOOP' || angleStrength < 0.001
          ? 1
          : side === dischargeSide
            ? 1 + angleStrength * 2.35
            : Math.max(0, 1 - angleStrength * 1.12);
        const depositX =
          x + forwardX * depositForward + rightX * lateralDistance;
        const depositZ =
          z + forwardZ * depositForward + rightZ * lateralDistance;
        const sideSpread = profile.depositSpread * 1.24;
        for (const sample of this.samplesInRadius(
          depositX,
          depositZ,
          sideSpread,
        )) {
          const distance = Math.hypot(
            sample.x - depositX,
            sample.z - depositZ,
          );
          const normalized = clamp(
            distance / sideSpread,
            0,
            1,
          );
          const vehicleForward =
            (sample.x - x) * forwardX + (sample.z - z) * forwardZ;
          if (vehicleForward < minimumDepositForward) continue;
          const flow = 1 - smoothstep(0.12, 1, normalized);
          const weight = (0.08 + flow * 0.92) * sideBias;
          addWeightedSample(sideSamples, sample, weight);
        }
      }
      // Every cut sample remains in the physical field. The profile controls
      // where the mass flows, never how much survives the operation.
      const retained = removedSnow;
      const effectiveFrontCarry = lerp(
        profile.frontCarryFraction,
        configuration.bladeMode === 'SCOOP' ? 0.5 : 0.045,
        angleStrength,
      );
      const frontRequested = retained * effectiveFrontCarry;
      const frontOverflow = depositInto(
        frontSamples,
        frontRequested,
        maximumFrontPileDepth,
        configuration.bladeMode === 'SCOOP' ? 0.24 : 0.18,
      );
      const blockedSnow = depositInto(
        sideSamples,
        retained - frontRequested + frontOverflow,
        maximumPileDepth,
        0.1,
      );
      blockedDepositFraction = clamp(
        blockedSnow / Math.max(0.0001, removedSnow),
        0,
        1,
      );
      if (blockedSnow > 0.0001) {
        // A saturated bank pushes the unaccepted wedge back into the cut
        // footprint. This makes the tractor stall against real mass instead
        // of silently deleting the overflow.
        depositInto(
          sourceSamples,
          blockedSnow,
          MAXIMUM_SNOW_DEPTH,
          0.72,
        );
      }

      for (const { sample } of [
        ...frontSamples.values(),
        ...sideSamples.values(),
      ]) {
        peakPileDepth = Math.max(
          peakPileDepth,
          sample.tile.depth[sample.index] ?? 0,
        );
      }
    }

    this.settleSteepSamples(dirtyTiles, 'FLOWING');
    peakPileDepth = Math.max(peakPileDepth, encounteredPileDepth);
    this.changedSamples += changedSamples;
    this.movedSnow += removedSnow;
    this.lastRemovedSnow = removedSnow;
    this.lastDepositedSnow = depositedSnow;
    const pileResistance = clamp(
      (peakPileDepth - 0.9) / 1.55,
      0,
      1,
    );
    const packedMassResistance = clamp(
      encounteredPileMass / Math.max(0.32, steps * 0.74),
      0,
      1,
    );
    const movedResistance = clamp(
      removedSnow /
        Math.max(0.4, steps * 0.72 * massCapacityMultiplier),
      0,
      1,
    );
    const resistance = clamp(
      movedResistance * 0.23 +
        pileResistance * pileResistance * 0.46 +
        packedMassResistance * 0.24 +
        overCapacity ** 2 * lerp(
          0.18,
          0.72,
          smoothstep(1.15, 3.2, peakPileDepth),
        ) +
        blockedDepositFraction * 0.88,
      0,
      1,
    );
    return {
      removedSnow,
      depositedSnow,
      changedSamples,
      resistance,
      peakPileDepth,
      overCapacity,
    };
  }

  /** Removes a narrow, shallow cone of loose snow for the handheld blower. */
  public blowCone(
    x: number,
    z: number,
    heading: number,
    deltaSeconds: number,
  ): LandSnowBlowResult {
    const delta = clamp(deltaSeconds, 0, 0.05);
    if (delta <= 0) return { removedSnow: 0, changedSamples: 0 };
    const forwardX = Math.sin(heading);
    const forwardZ = Math.cos(heading);
    const rightX = Math.cos(heading);
    const rightZ = -Math.sin(heading);
    const range = 3.95;
    const centerX = x + forwardX * range * 0.5;
    const centerZ = z + forwardZ * range * 0.5;
    const dirtyTiles = new Set<LandSnowTile>();
    let removedSnow = 0;
    let changedSamples = 0;
    for (const sample of this.samplesInRadius(
      centerX,
      centerZ,
      range * 0.62,
    )) {
      const dx = sample.x - x;
      const dz = sample.z - z;
      const forward = dx * forwardX + dz * forwardZ;
      if (forward < 0.02 || forward > range) continue;
      const lateral = Math.abs(dx * rightX + dz * rightZ);
      const halfWidth = 0.13 + forward * 0.21;
      if (lateral > halfWidth) continue;
      const directionInfluence = 1 - lateral / halfWidth;
      const rangeInfluence = 1 - forward / range;
      const influence =
        directionInfluence * 0.64 + rangeInfluence * 0.36;
      const current = sample.tile.depth[sample.index] ?? 0;
      if (current <= 0.002) continue;
      const removal = Math.min(
        current,
        delta * (0.045 + influence * 0.25),
      );
      sample.tile.depth[sample.index] = current - removal;
      sample.tile.compaction[sample.index] = Math.max(
        0,
        (sample.tile.compaction[sample.index] ?? 0) - delta * 0.18,
      );
      removedSnow += removal;
      changedSamples += 1;
      this.markTileDirty(sample.tile, sample.index, dirtyTiles);
    }
    this.changedSamples += changedSamples;
    this.movedSnow += removedSnow;
    this.lastRemovedSnow = removedSnow;
    this.lastDepositedSnow = 0;
    return { removedSnow, changedSamples };
  }

  /**
   * Mass-conserving intake/chute operation for a future pushed snow blower.
   * Presentation can draw any arc it likes; only accepted destination mass is
   * removed from the narrow auger footprint. A blocked bank returns overflow
   * to the intake instead of deleting it.
   */
  public snowThrowerSweep(
    x: number,
    z: number,
    heading: number,
    chuteSide: -1 | 1,
    deltaSeconds: number,
  ): LandSnowThrowerResult {
    const delta = clamp(deltaSeconds, 0, 0.05);
    if (delta <= 0) {
      return {
        removedSnow: 0,
        thrownSnow: 0,
        restoredSnow: 0,
        changedSamples: 0,
      };
    }
    const forwardX = Math.sin(heading);
    const forwardZ = Math.cos(heading);
    const rightX = Math.cos(heading);
    const rightZ = -Math.sin(heading);
    const intakeX = x + forwardX * 0.72;
    const intakeZ = z + forwardZ * 0.72;
    const maximumThroughput = delta * 2.2;
    const extracted = this.extractSnow(
      intakeX,
      intakeZ,
      0.62,
      maximumThroughput,
      0.025,
    );
    if (extracted.snowMass <= 0.00001) {
      return {
        removedSnow: 0,
        thrownSnow: 0,
        restoredSnow: 0,
        changedSamples: extracted.changedSamples,
      };
    }
    const destinationX = x + forwardX * 0.95 +
      rightX * chuteSide * 2.75;
    const destinationZ = z + forwardZ * 0.95 +
      rightZ * chuteSide * 2.75;
    const deposited = this.depositSnow(
      destinationX,
      destinationZ,
      1.28,
      extracted.snowMass,
      1.6,
      'FLOWING',
    );
    const overflow = extracted.snowMass - deposited.snowMass;
    const restored = overflow > 0.00001
      ? this.depositSnow(intakeX, intakeZ, 0.7, overflow, MAXIMUM_SNOW_DEPTH)
      : { snowMass: 0, changedSamples: 0, peakDepth: 0 };
    return {
      removedSnow: extracted.snowMass,
      thrownSnow: deposited.snowMass,
      restoredSnow: restored.snowMass,
      changedSamples:
        extracted.changedSamples +
        deposited.changedSamples +
        restored.changedSamples,
    };
  }

  /**
   * Low-frequency helicopter downwash. Snow is lifted out of the rotor disc
   * and conserved in one broad, low annulus outside it. Airborne particles
   * provide the violent motion without turning field mass into surface spikes.
   */
  public rotorWash(
    x: number,
    z: number,
    altitude: number,
    rotorSpeed: number,
    deltaSeconds: number,
  ): LandSnowRotorWashResult {
    const delta = clamp(deltaSeconds, 0, 0.25);
    const envelope = resolveHelicopterRotorWash(altitude, rotorSpeed);
    if (delta <= 0 || envelope.strength <= 0.001) {
      return {
        removedSnow: 0,
        depositedSnow: 0,
        changedSamples: 0,
        ...envelope,
      };
    }
    const maximumMovedMass = delta * envelope.strength *
      (7 + envelope.radius * 2.4);
    const retainedDepth = 0.012 + clamp(
      altitude / 6.5,
      0,
      1,
    ) * 0.025;
    const extracted = this.extractSnow(
      x,
      z,
      envelope.radius,
      maximumMovedMass,
      retainedDepth,
    );
    if (extracted.snowMass <= 0.00001) {
      return {
        removedSnow: 0,
        depositedSnow: 0,
        changedSamples: extracted.changedSamples,
        ...envelope,
      };
    }
    const drift = resolveHelicopterRotorWashDrift(envelope.radius, altitude);
    const deposited = this.depositRotorWashDrift(
      x,
      z,
      drift.innerRadius,
      drift.outerRadius,
      extracted.snowMass,
    );
    let remaining = extracted.snowMass - deposited.snowMass;
    let depositedSnow = deposited.snowMass;
    let changedSamples = extracted.changedSamples + deposited.changedSamples;
    if (remaining > 0.00001) {
      // An inactive or saturated outer band must not destroy physical snow.
      // Restore overflow evenly across the evacuated footprint, never at one
      // weighted centre sample.
      const restored = this.depositRotorWashDrift(
        x,
        z,
        0,
        envelope.radius,
        remaining,
      );
      depositedSnow += restored.snowMass;
      changedSamples += restored.changedSamples;
    }
    return {
      removedSnow: extracted.snowMass,
      depositedSnow,
      changedSamples,
      ...envelope,
    };
  }

  /** Distributes conserved rotor-wash mass over a smooth annular field band. */
  private depositRotorWashDrift(
    x: number,
    z: number,
    innerRadius: number,
    outerRadius: number,
    requestedMass: number,
  ): LandSnowMassTransferResult {
    let remaining = Math.max(0, requestedMass);
    const drift = {
      innerRadius: Math.max(0, innerRadius),
      outerRadius: Math.max(innerRadius + LAND_SNOW_SPACING, outerRadius),
    };
    const weighted = this.samplesInRadius(x, z, drift.outerRadius)
      .map((sample) => ({
        sample,
        weight: helicopterRotorWashDriftWeight(
          Math.hypot(sample.x - x, sample.z - z),
          drift,
        ),
      }))
      .filter(({ weight }) => weight > 0);
    const dirtyTiles = new Set<LandSnowTile>();
    let snowMass = 0;
    let changedSamples = 0;
    let peakDepth = 0;
    for (let pass = 0; pass < 4 && remaining > 0.0001; pass += 1) {
      const eligible = weighted.filter(({ sample }) =>
        (sample.tile.depth[sample.index] ?? 0) < MAXIMUM_SNOW_DEPTH - 0.0001
      );
      const totalWeight = eligible.reduce(
        (total, candidate) => total + candidate.weight,
        0,
      );
      if (totalWeight <= 0.0001) break;
      const massAtStart = remaining;
      let depositedThisPass = 0;
      for (const { sample, weight } of eligible) {
        const current = sample.tile.depth[sample.index] ?? 0;
        const requestedDepth =
          (massAtStart * weight / totalWeight) / LAND_SNOW_SPACING ** 2;
        const additionDepth = Math.min(
          MAXIMUM_SNOW_DEPTH - current,
          requestedDepth,
        );
        if (additionDepth <= 0.00001) continue;
        sample.tile.depth[sample.index] = current + additionDepth;
        sample.tile.compaction[sample.index] =
          (sample.tile.compaction[sample.index] ?? 0) * 0.82;
        const depositedMass = additionDepth * LAND_SNOW_SPACING ** 2;
        snowMass += depositedMass;
        depositedThisPass += depositedMass;
        peakDepth = Math.max(peakDepth, current + additionDepth);
        changedSamples += 1;
        this.markTileDirty(sample.tile, sample.index, dirtyTiles);
      }
      remaining -= depositedThisPass;
      if (depositedThisPass <= 0.0001) break;
    }
    this.settleSteepSamples(dirtyTiles);
    this.changedSamples += changedSamples;
    this.movedSnow += snowMass;
    this.lastRemovedSnow = 0;
    this.lastDepositedSnow = snowMass;
    return { snowMass, changedSamples, peakDepth };
  }

  public compactTracks(
    previousX: number,
    previousZ: number,
    x: number,
    z: number,
    heading: number,
    configuration: LandSnowTrackConfiguration = {
      halfWidth: 0.57,
      radius: 0.31,
      compression: 1,
    },
  ): number {
    const travel = Math.hypot(x - previousX, z - previousZ);
    if (travel < 0.012) return 0;
    const rightX = Math.cos(heading);
    const rightZ = -Math.sin(heading);
    const dirtyTiles = new Set<LandSnowTile>();
    let changed = 0;
    const steps = Math.max(
      1,
      Math.ceil(travel / (LAND_SNOW_SPACING * 0.35)),
    );
    for (let step = 1; step <= steps; step += 1) {
      const progress = step / steps;
      const vehicleX = lerp(previousX, x, progress);
      const vehicleZ = lerp(previousZ, z, progress);
      for (const side of [-configuration.halfWidth, configuration.halfWidth]) {
        const trackX = vehicleX + rightX * side;
        const trackZ = vehicleZ + rightZ * side;
        for (const sample of this.samplesInRadius(
          trackX,
          trackZ,
          configuration.radius,
        )) {
          const distance = Math.hypot(sample.x - trackX, sample.z - trackZ);
          const influence =
            1 - clamp(distance / configuration.radius, 0, 1);
          const previous = sample.tile.compaction[sample.index] ?? 0;
          const next = clamp(
            previous + (0.2 + influence * 0.34) * configuration.compression,
            0,
            1,
          );
          const depthBefore = sample.tile.depth[sample.index] ?? 0;
          const depression =
            (0.012 + influence * 0.026) * configuration.compression;
          const depthAfter = Math.max(0, depthBefore - depression);
          if (
            next <= previous + 0.001 &&
            depthAfter >= depthBefore - 0.001
          ) {
            continue;
          }
          sample.tile.compaction[sample.index] = next;
          sample.tile.depth[sample.index] = depthAfter;
          changed += 1;
          this.markTileDirty(sample.tile, sample.index, dirtyTiles);
        }
      }
    }
    this.changedSamples += changed;
    return changed;
  }

  public wadeSweep(
    previousX: number,
    previousZ: number,
    x: number,
    z: number,
    _heading: number,
    strength: number,
  ): LandSnowWadeResult {
    const travel = Math.hypot(x - previousX, z - previousZ);
    const wading = clamp(strength, 0, 1);
    // Deep-snow walking can advance less than one centimetre per fixed step.
    if (travel < 0.002 || wading <= 0.001) {
      return {
        displacedSnow: 0,
        depositedSnow: 0,
        changedSamples: 0,
      };
    }
    const forwardX = (x - previousX) / travel;
    const forwardZ = (z - previousZ) / travel;
    const rightX = forwardZ;
    const rightZ = -forwardX;
    // Keep the trough readable from the normal character camera. At full
    // wading strength it is wider than the feet but still materially smaller
    // than even the starter tractor's track envelope.
    const trailRadius = lerp(0.34, 0.52, wading);
    const sideOffset = trailRadius + lerp(0.13, 0.2, wading);
    const sideRadius = lerp(0.28, 0.4, wading);
    const frontOffset = trailRadius + lerp(0.17, 0.25, wading);
    const frontRadius = lerp(0.27, 0.38, wading);
    const dirtyTiles = new Set<LandSnowTile>();
    const steps = Math.max(
      1,
      Math.ceil(travel / (LAND_SNOW_SPACING * 0.3)),
    );
    let displacedSnow = 0;
    let depositedSnow = 0;
    let changedSamples = 0;
    for (let step = 1; step <= steps; step += 1) {
      const progress = step / steps;
      const centerX = lerp(previousX, x, progress);
      const centerZ = lerp(previousZ, z, progress);
      const centerKeys = new Set<string>();
      let stepDisplacedSnow = 0;
      for (const sample of this.samplesInRadius(
        centerX,
        centerZ,
        trailRadius,
      )) {
        const distance = Math.hypot(
          sample.x - centerX,
          sample.z - centerZ,
        );
        const influence = 1 - clamp(distance / trailRadius, 0, 1);
        const previousPacked =
          sample.tile.compaction[sample.index] ?? 0;
        const targetPacked =
          (0.3 + wading * 0.68) * influence;
        const nextPacked = Math.max(previousPacked, targetPacked);
        const packingGain = nextPacked - previousPacked;
        if (packingGain <= 0.001) continue;
        const currentDepth = sample.tile.depth[sample.index] ?? 0;
        const removal = Math.min(
          currentDepth,
          packingGain * lerp(0.11, 0.54, wading),
        );
        sample.tile.compaction[sample.index] = nextPacked;
        sample.tile.depth[sample.index] = currentDepth - removal;
        centerKeys.add(
          `${sample.tile.tileX},${sample.tile.tileZ}:${sample.index}`,
        );
        stepDisplacedSnow += removal;
        changedSamples += 1;
        this.markTileDirty(sample.tile, sample.index, dirtyTiles);
      }
      displacedSnow += stepDisplacedSnow;
      if (stepDisplacedSnow <= 0) continue;

      const sideSamples = new Map<string, MutableSample>();
      for (const side of [-1, 1]) {
        const sideX = centerX + rightX * sideOffset * side;
        const sideZ = centerZ + rightZ * sideOffset * side;
        for (const sample of this.samplesInRadius(
          sideX,
          sideZ,
          sideRadius,
        )) {
          const key =
            `${sample.tile.tileX},${sample.tile.tileZ}:${sample.index}`;
          if (!centerKeys.has(key)) sideSamples.set(key, sample);
        }
      }
      const frontSamples = new Map<string, MutableSample>();
      const frontX = centerX + forwardX * frontOffset;
      const frontZ = centerZ + forwardZ * frontOffset;
      for (const sample of this.samplesInRadius(
        frontX,
        frontZ,
        frontRadius,
      )) {
        const key =
          `${sample.tile.tileX},${sample.tile.tileZ}:${sample.index}`;
        if (!centerKeys.has(key) && !sideSamples.has(key)) {
          frontSamples.set(key, sample);
        }
      }
      const depositToSamples = (
        samples: ReadonlyMap<string, MutableSample>,
        amount: number,
      ): void => {
        if (samples.size === 0 || amount <= 0) return;
        const addition = amount / samples.size;
        for (const sample of samples.values()) {
          const currentDepth = sample.tile.depth[sample.index] ?? 0;
          const accepted = Math.min(
            addition,
            MAXIMUM_SNOW_DEPTH - currentDepth,
          );
          if (accepted <= 0.0001) continue;
          sample.tile.depth[sample.index] = currentDepth + accepted;
          sample.tile.compaction[sample.index] = Math.max(
            0,
            (sample.tile.compaction[sample.index] ?? 0) - accepted * 1.5,
          );
          depositedSnow += accepted;
          changedSamples += 1;
          this.markTileDirty(sample.tile, sample.index, dirtyTiles);
        }
      };
      // The authoritative V3 field carries the readable character effect:
      // a deeper trough, two persistent side lips and only a low bow wave.
      // Cosmetic V4 clumps can therefore stay sparse without making wading
      // disappear when their presentation budget is exhausted.
      depositToSamples(sideSamples, stepDisplacedSnow * 0.76);
      depositToSamples(frontSamples, stepDisplacedSnow * 0.18);
    }
    this.settleSteepSamples(dirtyTiles, 'FLOWING');
    this.changedSamples += changedSamples;
    this.movedSnow += displacedSnow;
    return { displacedSnow, depositedSnow, changedSamples };
  }

  /** Narrow, mass-conserving board carve layered on the canonical V3 field. */
  public snowboardSweep(
    previousX: number,
    previousZ: number,
    x: number,
    z: number,
    heading: number,
    steering: number,
  ): LandSnowWadeResult {
    const travel = Math.hypot(x - previousX, z - previousZ);
    if (travel < 0.002) {
      return { displacedSnow: 0, depositedSnow: 0, changedSamples: 0 };
    }
    const carve = clamp(steering, -1, 1);
    const changedTracks = this.compactTracks(
      previousX,
      previousZ,
      x,
      z,
      heading,
      { halfWidth: 0.075, radius: 0.16, compression: 0.58 },
    );
    const rightX = Math.cos(heading);
    const rightZ = -Math.sin(heading);
    const maximumMass = travel * (0.014 + Math.abs(carve) * 0.032);
    let depositedSnow = 0;
    let changedSamples = changedTracks;
    if (Math.abs(carve) > 0.08) {
      const moved = this.relocateSnow(
        x,
        z,
        x + rightX * Math.sign(carve) * 0.42,
        z + rightZ * Math.sign(carve) * 0.42,
        0.2,
        maximumMass,
        MAXIMUM_SNOW_DEPTH,
      );
      depositedSnow += moved.snowMass;
      changedSamples += moved.changedSamples;
    } else {
      for (const side of [-1, 1]) {
        const moved = this.relocateSnow(
          x,
          z,
          x + rightX * side * 0.34,
          z + rightZ * side * 0.34,
          0.18,
          maximumMass * 0.5,
          MAXIMUM_SNOW_DEPTH,
        );
        depositedSnow += moved.snowMass;
        changedSamples += moved.changedSamples;
      }
    }
    return {
      displacedSnow: depositedSnow,
      depositedSnow,
      changedSamples,
    };
  }

  /** Removes physical snow mass for loaders, trucks and sling cargo. */
  public extractSnow(
    x: number,
    z: number,
    radius: number,
    capacityCubicMetres: number,
    retainedDepth = 0.035,
  ): LandSnowMassTransferResult {
    let remaining = Math.max(0, capacityCubicMetres);
    const samples = this.samplesInRadius(x, z, Math.max(0.4, radius));
    const dirtyTiles = new Set<LandSnowTile>();
    let snowMass = 0;
    let changedSamples = 0;
    let peakDepth = 0;
    for (let pass = 0; pass < 3 && remaining > 0.0001; pass += 1) {
      const eligible = samples.filter((sample) =>
        (sample.tile.depth[sample.index] ?? 0) > retainedDepth + 0.001
      );
      if (eligible.length === 0) break;
      const requestedDepth =
        remaining / (eligible.length * LAND_SNOW_SPACING ** 2);
      let removedThisPass = 0;
      for (const sample of eligible) {
        const current = sample.tile.depth[sample.index] ?? 0;
        peakDepth = Math.max(peakDepth, current);
        const removalDepth = Math.min(
          current - retainedDepth,
          requestedDepth,
        );
        if (removalDepth <= 0.00001) continue;
        sample.tile.depth[sample.index] = current - removalDepth;
        sample.tile.compaction[sample.index] = Math.max(
          0,
          (sample.tile.compaction[sample.index] ?? 0) - removalDepth * 0.2,
        );
        const removedMass = removalDepth * LAND_SNOW_SPACING ** 2;
        snowMass += removedMass;
        removedThisPass += removedMass;
        changedSamples += 1;
        this.markTileDirty(sample.tile, sample.index, dirtyTiles);
      }
      remaining -= removedThisPass;
      if (removedThisPass <= 0.0001) break;
    }
    this.changedSamples += changedSamples;
    this.movedSnow += snowMass;
    this.lastRemovedSnow = snowMass;
    this.lastDepositedSnow = 0;
    return { snowMass, changedSamples, peakDepth };
  }

  /**
   * Melts a shallow, soft-edged patch without treating heat as a loader.
   * `maximumDepthMetres` is the melt at the hot centre for this update; the
   * falloff deliberately reaches zero before the edge to avoid a circular
   * snow-mesh step. Used by small local heat sources such as campfires.
   */
  public meltSnowRadial(
    x: number,
    z: number,
    radius: number,
    maximumDepthMetres: number,
    retainedDepth = 0.018,
  ): LandSnowMassTransferResult {
    const effectiveRadius = Math.max(LAND_SNOW_SPACING * 1.25, radius);
    const samples = this.samplesInRadius(x, z, effectiveRadius);
    const dirtyTiles = new Set<LandSnowTile>();
    let snowMass = 0;
    let changedSamples = 0;
    let peakDepth = 0;
    for (const sample of samples) {
      const current = sample.tile.depth[sample.index] ?? 0;
      peakDepth = Math.max(peakDepth, current);
      if (current <= retainedDepth + 0.0001) continue;
      const distance = Math.hypot(sample.x - x, sample.z - z);
      const falloff = 1 - smoothstep(
        effectiveRadius * 0.32,
        effectiveRadius,
        distance,
      );
      const removalDepth = Math.min(
        current - retainedDepth,
        Math.max(0, maximumDepthMetres) * falloff,
      );
      if (removalDepth <= 0.00001) continue;
      sample.tile.depth[sample.index] = current - removalDepth;
      sample.tile.compaction[sample.index] = Math.max(
        0,
        (sample.tile.compaction[sample.index] ?? 0) - removalDepth * 0.16,
      );
      snowMass += removalDepth * LAND_SNOW_SPACING ** 2;
      changedSamples += 1;
      this.markTileDirty(sample.tile, sample.index, dirtyTiles);
    }
    this.changedSamples += changedSamples;
    this.movedSnow += snowMass;
    this.lastRemovedSnow = snowMass;
    this.lastDepositedSnow = 0;
    return { snowMass, changedSamples, peakDepth };
  }

  /** Deposits transported snow back into the exact same height field. */
  public depositSnow(
    x: number,
    z: number,
    radius: number,
    snowMassCubicMetres: number,
    maximumDepth = MAXIMUM_SNOW_DEPTH,
    settling: 'NORMAL' | 'FLOWING' = 'NORMAL',
  ): LandSnowMassTransferResult {
    let remaining = Math.max(0, snowMassCubicMetres);
    const effectiveRadius = Math.max(0.45, radius);
    const samples = this.samplesInRadius(x, z, effectiveRadius);
    const weighted = samples.map((sample) => {
      const distance = Math.hypot(sample.x - x, sample.z - z);
      return {
        sample,
        weight: 0.08 + (1 - clamp(distance / effectiveRadius, 0, 1)) ** 2,
      };
    });
    const dirtyTiles = new Set<LandSnowTile>();
    let snowMass = 0;
    let changedSamples = 0;
    let peakDepth = 0;
    const limit = clamp(maximumDepth, 0.2, MAXIMUM_SNOW_DEPTH);
    for (let pass = 0; pass < 4 && remaining > 0.0001; pass += 1) {
      const eligible = weighted.filter(
        ({ sample }) =>
          (sample.tile.depth[sample.index] ?? 0) < limit - 0.0001,
      );
      const totalWeight = eligible.reduce(
        (total, candidate) => total + candidate.weight,
        0,
      );
      if (totalWeight <= 0.0001) break;
      const massAtStart = remaining;
      let depositedThisPass = 0;
      for (const { sample, weight } of eligible) {
        const current = sample.tile.depth[sample.index] ?? 0;
        const requestedMass = massAtStart * weight / totalWeight;
        const additionDepth = Math.min(
          limit - current,
          requestedMass / LAND_SNOW_SPACING ** 2,
        );
        if (additionDepth <= 0.00001) continue;
        sample.tile.depth[sample.index] = current + additionDepth;
        sample.tile.compaction[sample.index] =
          (sample.tile.compaction[sample.index] ?? 0) * 0.82;
        const depositedMass = additionDepth * LAND_SNOW_SPACING ** 2;
        snowMass += depositedMass;
        depositedThisPass += depositedMass;
        peakDepth = Math.max(peakDepth, current + additionDepth);
        changedSamples += 1;
        this.markTileDirty(sample.tile, sample.index, dirtyTiles);
      }
      remaining -= depositedThisPass;
      if (depositedThisPass <= 0.0001) break;
    }
    this.settleSteepSamples(dirtyTiles, settling);
    this.changedSamples += changedSamples;
    this.movedSnow += snowMass;
    this.lastRemovedSnow = 0;
    this.lastDepositedSnow = snowMass;
    return { snowMass, changedSamples, peakDepth };
  }

  /**
   * Moves an existing ground drift from the windward side of an obstacle to
   * its leeward side. Any destination overflow is returned to the source, so
   * obstacle drift shaping never creates or destroys snow mass.
   */
  public relocateSnow(
    sourceX: number,
    sourceZ: number,
    destinationX: number,
    destinationZ: number,
    radius: number,
    maximumMass: number,
    maximumDepth = MAXIMUM_SNOW_DEPTH,
  ): LandSnowMassTransferResult {
    const extracted = this.extractSnow(
      sourceX,
      sourceZ,
      radius,
      Math.max(0, maximumMass),
      0.08,
    );
    if (extracted.snowMass <= 0.00001) return extracted;
    const deposited = this.depositSnow(
      destinationX,
      destinationZ,
      radius,
      extracted.snowMass,
      maximumDepth,
    );
    const overflow = extracted.snowMass - deposited.snowMass;
    let returned: LandSnowMassTransferResult | undefined;
    if (overflow > 0.00001) {
      returned = this.depositSnow(
        sourceX,
        sourceZ,
        radius,
        overflow,
        maximumDepth,
      );
    }
    return {
      snowMass: deposited.snowMass,
      changedSamples:
        extracted.changedSamples +
        deposited.changedSamples +
        (returned?.changedSamples ?? 0),
      peakDepth: deposited.peakDepth,
    };
  }

  /**
   * Conserved low ridge used by obstacle wind shelter. One windward
   * extraction feeds several overlapping downwind lobes, avoiding both a
   * single sharp peak and repeated extraction/return work per obstacle.
   */
  public relocateSnowRidge(
    sourceX: number,
    sourceZ: number,
    destinationX: number,
    destinationZ: number,
    radius: number,
    maximumMass: number,
    maximumDepth: number,
    ridgeLength: number,
    ridgePoints: number,
  ): LandSnowMassTransferResult {
    const extracted = this.extractSnow(
      sourceX,
      sourceZ,
      radius,
      Math.max(0, maximumMass),
      0.08,
    );
    if (extracted.snowMass <= 0.00001) return extracted;
    const deltaX = destinationX - sourceX;
    const deltaZ = destinationZ - sourceZ;
    const directionLength = Math.max(0.0001, Math.hypot(deltaX, deltaZ));
    const directionX = deltaX / directionLength;
    const directionZ = deltaZ / directionLength;
    const pointCount = clamp(Math.round(ridgePoints), 2, 6);
    const length = clamp(ridgeLength, 0.2, 4);
    const totalWeight = pointCount * 0.72;
    let depositedMass = 0;
    let changedSamples = extracted.changedSamples;
    let peakDepth = 0;
    for (let index = 0; index < pointCount; index += 1) {
      const progress = pointCount <= 1 ? 0 : index / (pointCount - 1);
      const share = extracted.snowMass * (1 - progress * 0.56) / totalWeight;
      const deposited = this.depositSnow(
        destinationX + directionX * length * progress,
        destinationZ + directionZ * length * progress,
        radius * (0.94 + progress * 0.22),
        share,
        maximumDepth,
      );
      depositedMass += deposited.snowMass;
      changedSamples += deposited.changedSamples;
      peakDepth = Math.max(peakDepth, deposited.peakDepth);
    }
    const overflow = extracted.snowMass - depositedMass;
    if (overflow > 0.00001) {
      const returned = this.depositSnow(
        sourceX,
        sourceZ,
        radius,
        overflow,
        Math.max(maximumDepth, MAXIMUM_SNOW_DEPTH),
      );
      changedSamples += returned.changedSamples;
    }
    return { snowMass: depositedMass, changedSamples, peakDepth };
  }

  /**
   * Coarse weather pass. It is intentionally called at a low cadence: the
   * snow field changes, while no per-flake or per-track entities accumulate.
   */
  public applyWeather(
    deltaSeconds: number,
    snowIntensity: number,
    sampleProtection: LandSnowProtectionSampler = () => 0,
    wind: Readonly<{
      x: number;
      z: number;
      strength: number;
    }> = { x: 1, z: 0, strength: 0 },
  ): LandSnowWeatherResult {
    const delta = clamp(deltaSeconds, 0, 1);
    if (delta <= 0) {
      return { accumulatedSnow: 0, meltedSnow: 0, changedSamples: 0 };
    }
    const active = [...this.activeTiles.values()];
    if (active.length === 0) {
      return { accumulatedSnow: 0, meltedSnow: 0, changedSamples: 0 };
    }
    const tile = active[this.weatherTileCursor % active.length]!;
    this.weatherTileCursor = (this.weatherTileCursor + 1) % active.length;
    // One tile per pass prevents a snowfall update from rebuilding every
    // active mesh in one frame. Multiplication preserves the total rate.
    const tileDelta = Math.min(10, delta * active.length);
    const snowfallDepth =
      clamp(snowIntensity, 0, 1) * tileDelta * 0.00055;
    const dirtyTiles = new Set<LandSnowTile>();
    let accumulatedSnow = 0;
    let meltedSnow = 0;
    let changedSamples = 0;
    const windLength = Math.max(0.0001, Math.hypot(wind.x, wind.z));
    const windX = wind.x / windLength;
    const windZ = wind.z / windLength;
    const driftStrength = clamp(wind.strength, 0, 2.8) *
      clamp(snowIntensity, 0, 1);
    for (let row = 0; row < LAND_SNOW_SAMPLES; row += 1) {
      const z = tile.tileZ * LAND_SNOW_TILE_SIZE + row * LAND_SNOW_SPACING;
      for (let column = 0; column < LAND_SNOW_SAMPLES; column += 1) {
          const x = tile.tileX * LAND_SNOW_TILE_SIZE + column * LAND_SNOW_SPACING;
          // A render-tile edge has two mesh vertices but only one simulated
          // grid value. Mutate it in its canonical positive-side tile; the
          // dirty path mirrors the result to the adjacent render mesh.
          if (!this.isCanonicalTileSample(tile.tileX, tile.tileZ, x, z)) {
            continue;
          }
          if (!isBorealisLand(x, z)) continue;
          const index = sampleIndex(column, row);
          const current = tile.depth[index] ?? 0;
          const protection = this.isSnowExcluded(x, z)
            ? 1
            : clamp(sampleProtection(x, z), 0, 1);
          // Broad, deterministic wind bands create readable ground drifts
          // without spawning particles or allocating obstacle entities. The
          // signed bias keeps average snowfall close to the original rate.
          const downwind = x * windX + z * windZ;
          const crosswind = -x * windZ + z * windX;
          const driftPattern =
            Math.sin(downwind * 0.17 + Math.sin(crosswind * 0.07) * 1.4) * 0.5 +
            Math.sin(downwind * 0.051 + crosswind * 0.019 + 1.7) * 0.5;
          const driftMultiplier = clamp(
            1 + driftPattern * driftStrength * 0.18,
            0.62,
            1.55,
          );
          const addition = Math.min(
            MAXIMUM_SNOW_DEPTH - current,
            snowfallDepth * driftMultiplier * (1 - protection),
          );
          const melt = Math.min(
            current + addition,
            protection * tileDelta * 0.0045,
          );
          const next = current + addition - melt;
          if (Math.abs(next - current) <= 0.00001) continue;
          tile.depth[index] = next;
          if (addition > 0) {
            tile.compaction[index] =
              (tile.compaction[index] ?? 0) * 0.998;
          }
          accumulatedSnow += addition * LAND_SNOW_SPACING ** 2;
          meltedSnow += melt * LAND_SNOW_SPACING ** 2;
          changedSamples += 1;
          this.markTileDirty(tile, index, dirtyTiles);
      }
    }
    this.changedSamples += changedSamples;
    return { accumulatedSnow, meltedSnow, changedSamples };
  }

  /**
   * Lightweight persistent road service for an NPC that may be outside the
   * rendered tile ring. Cleared mass is banked to both road edges directly in
   * sparse chunk data, so background work is visible when the player returns.
   */
  public serviceCorridor(
    previousX: number,
    previousZ: number,
    x: number,
    z: number,
    heading: number,
    width = 1.85,
  ): LandSnowMassTransferResult {
    const travel = Math.hypot(x - previousX, z - previousZ);
    if (travel < 0.002) {
      return { snowMass: 0, changedSamples: 0, peakDepth: 0 };
    }
    const rightX = Math.cos(heading);
    const rightZ = -Math.sin(heading);
    const visited = new Set<string>();
    const dirtyTiles = new Set<LandSnowTile>();
    const steps = Math.max(1, Math.ceil(travel / LAND_SNOW_SPACING));
    let snowMass = 0;
    let changedSamples = 0;
    let peakDepth = 0;
    for (let step = 1; step <= steps; step += 1) {
      const progress = step / steps;
      const centerX = lerp(previousX, x, progress);
      const centerZ = lerp(previousZ, z, progress);
      for (
        let side = -width * 0.5;
        side <= width * 0.5 + 0.001;
        side += LAND_SNOW_SPACING
      ) {
        const sampleX =
          Math.round((centerX + rightX * side) / LAND_SNOW_SPACING) *
          LAND_SNOW_SPACING;
        const sampleZ =
          Math.round((centerZ + rightZ * side) / LAND_SNOW_SPACING) *
          LAND_SNOW_SPACING;
        const key = `${sampleX},${sampleZ}`;
        if (visited.has(key) || !isBorealisLand(sampleX, sampleZ)) continue;
        visited.add(key);
        const current = this.readGridSample(sampleX, sampleZ).depth;
        peakDepth = Math.max(peakDepth, current);
        const removal = Math.min(Math.max(0, current - 0.07), 0.14);
        if (removal <= 0.0001) continue;
        this.writeGridSample(
          sampleX,
          sampleZ,
          current - removal,
          0.76,
          dirtyTiles,
        );
        const bankOffset = width * 0.5 + 0.72;
        for (const bankSide of [-1, 1]) {
          const bankX =
            Math.round(
              (sampleX + rightX * bankOffset * bankSide) /
                LAND_SNOW_SPACING,
            ) * LAND_SNOW_SPACING;
          const bankZ =
            Math.round(
              (sampleZ + rightZ * bankOffset * bankSide) /
                LAND_SNOW_SPACING,
            ) * LAND_SNOW_SPACING;
          if (!isBorealisLand(bankX, bankZ)) continue;
          const bank = this.readGridSample(bankX, bankZ);
          this.writeGridSample(
            bankX,
            bankZ,
            Math.min(2.2, bank.depth + removal * 0.41),
            Math.max(0.08, bank.compaction * 0.8),
            dirtyTiles,
          );
          changedSamples += 1;
        }
        snowMass += removal * LAND_SNOW_SPACING ** 2;
        changedSamples += 1;
      }
    }
    this.changedSamples += changedSamples;
    this.movedSnow += snowMass;
    return { snowMass, changedSamples, peakDepth };
  }

  public getClearedRatio(
    centerX: number,
    centerZ: number,
    halfWidth: number,
    halfHeight: number,
  ): number {
    let samples = 0;
    let cleared = 0;
    for (
      let z = centerZ - halfHeight;
      z <= centerZ + halfHeight;
      z += LAND_SNOW_SPACING
    ) {
      for (
        let x = centerX - halfWidth;
        x <= centerX + halfWidth;
        x += LAND_SNOW_SPACING
      ) {
        if (!isBorealisLand(x, z)) continue;
        samples += 1;
        if (this.sampleDepth(x, z) <= 0.12) cleared += 1;
      }
    }
    return samples > 0 ? cleared / samples : 0;
  }

  public importState(saved: unknown): boolean {
    if (!saved || typeof saved !== 'object') return false;
    const candidate = saved as Partial<LandSnowSaveData>;
    if (
      (candidate.version !== 1 &&
        candidate.version !== 2 &&
        candidate.version !== 3) ||
      !Array.isArray(candidate.tiles)
    ) {
      return false;
    }
    this.savedTiles.clear();
    for (const tile of candidate.tiles) {
      if (
        !Number.isInteger(tile?.tileX) ||
        !Number.isInteger(tile?.tileZ) ||
        !Array.isArray(tile?.changes)
      ) {
        continue;
      }
      const sampleCount = candidate.version === 3
        ? LAND_SNOW_SAMPLE_COUNT
        : LEGACY_LAND_SNOW_SAMPLE_COUNT;
      const changes: Array<readonly [number, number, number]> =
        tile.changes.filter(
        (change: unknown): change is readonly [number, number, number] =>
          Array.isArray(change) &&
          change.length === 3 &&
          Number.isInteger(change[0]) &&
          change[0] >= 0 &&
          change[0] < sampleCount &&
          Number.isFinite(change[1]) &&
          Number.isFinite(change[2]),
        );
      if (changes.length === 0) continue;
      const normalizedChanges = candidate.version === 3
        ? changes.map(([index, depth, compaction]) => [
            index,
            encodeDepth(decodeDepth(depth)),
            encodeUnit(decodeUnit(compaction)),
          ] as const)
        : refineLegacyLandSnowChanges(
            tile.tileX,
            tile.tileZ,
            changes,
            candidate.version === 1 ? 'U8' : 'U16',
          );
      this.savedTiles.set(tileKey(tile.tileX, tile.tileZ), {
        tileX: tile.tileX,
        tileZ: tile.tileZ,
        changes: normalizedChanges,
      });
    }
    for (const tile of this.activeTiles.values()) {
      this.applySavedTile(tile);
      this.updateTileMesh(tile);
    }
    return true;
  }

  /**
   * Atomically replaces the locally presented field after a join baseline.
   * Multiplayer revisions stay in the replication client; this class only
   * owns the canonical sparse samples and the render mesh derived from them.
   */
  public replaceCanonicalState(
    tiles: readonly Readonly<CanonicalLandSnowTile>[],
  ): number {
    this.savedTiles.clear();
    for (const tile of tiles) {
      const changes = this.validateCanonicalChanges(tile.changes);
      if (changes.length === 0) continue;
      this.savedTiles.set(tileKey(tile.tileX, tile.tileZ), {
        tileX: tile.tileX,
        tileZ: tile.tileZ,
        changes,
      });
    }
    let changed = 0;
    for (const tile of this.activeTiles.values()) {
      changed += this.reconcileActiveTile(tile);
    }
    this.changedSamples += changed;
    return changed;
  }

  /** Reconciles complete sparse snapshots for only the supplied tiles. */
  public applyCanonicalTiles(
    tiles: readonly Readonly<CanonicalLandSnowTile>[],
  ): number {
    let changed = 0;
    for (const incoming of tiles) {
      const key = tileKey(incoming.tileX, incoming.tileZ);
      const changes = this.validateCanonicalChanges(incoming.changes);
      if (changes.length === 0) this.savedTiles.delete(key);
      else {
        this.savedTiles.set(key, {
          tileX: incoming.tileX,
          tileZ: incoming.tileZ,
          changes,
        });
      }
      const active = this.activeTiles.get(key);
      if (active) changed += this.reconcileActiveTile(active);
    }
    this.changedSamples += changed;
    return changed;
  }

  public exportState(): LandSnowSaveData {
    for (const tile of this.activeTiles.values()) this.storeTile(tile);
    return {
      version: 3,
      tiles: [...this.savedTiles.values()].map((tile) => ({
        tileX: tile.tileX,
        tileZ: tile.tileZ,
        changes: tile.changes.map((change) => [...change] as const),
      })),
    };
  }

  public getStats(): LandSnowStats {
    return {
      activeTiles: this.activeTiles.size,
      cachedTiles: this.cachedTiles.size,
      queuedPrefetchTiles: this.prefetchQueue.length +
        (this.prefetchJob ? 1 : 0),
      modifiedTiles: new Set([
        ...this.savedTiles.keys(),
        ...[...this.activeTiles]
          .filter(([, tile]) => tile.modified)
          .map(([key]) => key),
      ]).size,
      pendingDirtyTiles: this.pendingDirtyTiles.size,
      changedSamples: this.changedSamples,
      movedSnow: this.movedSnow,
      lastRemovedSnow: this.lastRemovedSnow,
      lastDepositedSnow: this.lastDepositedSnow,
      tileActivations: this.tileActivations,
      meshUpdates: this.meshUpdates,
      updatedVertices: this.updatedVertices,
      lastStreamMs: this.lastStreamMs,
      lastPrefetchMs: this.lastPrefetchMs,
      lastFlushMs: this.lastFlushMs,
    };
  }

  public writePerformanceTrace(
    target: {
      activeSnowTiles?: number;
      cachedSnowTiles?: number;
      queuedSnowTiles?: number;
      pendingSnowTiles?: number;
      snowMeshUpdates?: number;
      snowUpdatedVertices?: number;
    },
  ): void {
    target.activeSnowTiles = this.activeTiles.size;
    target.cachedSnowTiles = this.cachedTiles.size;
    target.queuedSnowTiles = this.prefetchQueue.length +
      (this.prefetchJob ? 1 : 0);
    target.pendingSnowTiles = this.pendingDirtyTiles.size;
    target.snowMeshUpdates = this.meshUpdates;
    target.snowUpdatedVertices = this.updatedVertices;
  }

  public dispose(): void {
    this.removeTerrainListener();
    for (const tile of this.activeTiles.values()) {
      tile.geometry.dispose();
    }
    this.activeTiles.clear();
    for (const tile of this.cachedTiles.values()) {
      tile.geometry.dispose();
    }
    this.cachedTiles.clear();
    this.prefetchQueue.length = 0;
    this.queuedPrefetchKeys.clear();
    this.prefetchJob = undefined;
    this.savedTiles.clear();
    this.pendingDirtyTiles.clear();
    this.mutationListeners.clear();
    this.detailCoveredTileKeys.clear();
    this.material.dispose();
    this.root.removeFromParent();
  }

  private activateTile(tileX: number, tileZ: number): 'cache' | 'generated' {
    const key = tileKey(tileX, tileZ);
    const cached = this.cachedTiles.get(key);
    if (cached) {
      this.cachedTiles.delete(key);
      this.reconcileActiveTile(cached);
      this.activeTiles.set(key, cached);
      this.root.add(cached.mesh);
      cached.mesh.visible = !this.detailCoveredTileKeys.has(key);
      this.synchronizeActiveTileBorders(cached);
      return 'cache';
    }
    const tile = this.buildTileSynchronously(tileX, tileZ);
    this.activeTiles.set(key, tile);
    this.root.add(tile.mesh);
    tile.mesh.visible = !this.detailCoveredTileKeys.has(key);
    this.synchronizeActiveTileBorders(tile);
    return 'generated';
  }

  private createTileBuildJob(
    tileX: number,
    tileZ: number,
  ): LandSnowTileBuildJob {
    return {
      key: tileKey(tileX, tileZ),
      tileX,
      tileZ,
      depth: new Float32Array(LAND_SNOW_SAMPLE_COUNT),
      compaction: new Float32Array(LAND_SNOW_SAMPLE_COUNT),
      initialDepth: new Float32Array(LAND_SNOW_SAMPLE_COUNT),
      cellularTint: new Float32Array(LAND_SNOW_SAMPLE_COUNT),
      edgeSnowDepth: new Float32Array(LAND_SNOW_SAMPLE_COUNT),
      surfaceX: new Float32Array(LAND_SNOW_SAMPLE_COUNT),
      positions: new Float32Array(LAND_SNOW_SAMPLE_COUNT * 3),
      colors: new Float32Array(LAND_SNOW_SAMPLE_COUNT * 3),
      indices: [],
      stage: 'INITIAL',
      row: 0,
      modified: false,
    };
  }

  private advanceTileBuild(
    job: LandSnowTileBuildJob,
  ): LandSnowTile | undefined {
    if (job.stage === 'INITIAL') {
      const row = job.row;
      const z = job.tileZ * LAND_SNOW_TILE_SIZE + row * LAND_SNOW_SPACING;
      const coastX = borealisCoastX(z);
      const coastEdgeDepth = initialSnowDepth(coastX - 0.08, z);
      for (let column = 0; column < LAND_SNOW_SAMPLES; column += 1) {
        const x =
          job.tileX * LAND_SNOW_TILE_SIZE + column * LAND_SNOW_SPACING;
        const index = sampleIndex(column, row);
        const cellular = snowCellPattern(x, z);
        const initial = this.isSnowExcluded(x, z)
          ? 0
          : initialSnowDepth(x, z, cellular);
        job.depth[index] = initial;
        job.initialDepth[index] = initial;
        job.cellularTint[index] = (cellular - 0.5) * 0.026;
        job.surfaceX[index] = Math.min(x, coastX);
        if (
          initial <= 0 &&
          !isBorealisLand(x, z) &&
          x <= coastX + LAND_SNOW_SPACING * 1.5
        ) {
          job.edgeSnowDepth[index] = coastEdgeDepth;
        }
      }
      job.row += 1;
      if (job.row >= LAND_SNOW_SAMPLES) {
        const saved = this.savedTiles.get(job.key);
        if (saved) {
          for (const [index, depth, compaction] of saved.changes) {
            const savedRow = Math.floor(index / LAND_SNOW_SAMPLES);
            const savedX = job.surfaceX[index] ?? 0;
            const savedZ = job.tileZ * LAND_SNOW_TILE_SIZE +
              savedRow * LAND_SNOW_SPACING;
            if (this.isSnowExcluded(savedX, savedZ)) continue;
            job.depth[index] = decodeDepth(depth);
            job.compaction[index] = decodeUnit(compaction);
          }
          job.modified = saved.changes.length > 0;
        }
        job.stage = 'ATTRIBUTES';
        job.row = 0;
      }
      return undefined;
    }
    if (job.stage === 'ATTRIBUTES') {
      this.writeTileAttributes(
        job.tileZ,
        job.depth,
        job.compaction,
        job.cellularTint,
        job.edgeSnowDepth,
        job.surfaceX,
        job.positions,
        job.colors,
        0,
        job.row,
        LAND_SNOW_SEGMENTS,
        job.row,
      );
      job.row += 1;
      if (job.row >= LAND_SNOW_SAMPLES) {
        job.stage = 'INDICES';
        job.row = 0;
      }
      return undefined;
    }
    const row = job.row;
    for (let column = 0; column < LAND_SNOW_SEGMENTS; column += 1) {
      const centerX =
        job.tileX * LAND_SNOW_TILE_SIZE +
        (column + 0.5) * LAND_SNOW_SPACING;
      const centerZ =
        job.tileZ * LAND_SNOW_TILE_SIZE +
        (row + 0.5) * LAND_SNOW_SPACING;
      if (!isBorealisLand(centerX, centerZ)) continue;
      if (this.terrain.isNearCliff(centerX, centerZ, 0.34)) continue;
      if (this.isSnowExcluded(centerX, centerZ)) {
        continue;
      }
      const a = sampleIndex(column, row);
      const b = sampleIndex(column + 1, row);
      const c = sampleIndex(column, row + 1);
      const d = sampleIndex(column + 1, row + 1);
      job.indices.push(a, c, b, b, c, d);
    }
    job.row += 1;
    return job.row >= LAND_SNOW_SEGMENTS
      ? this.finishTileBuild(job)
      : undefined;
  }

  private finishTileBuild(job: LandSnowTileBuildJob): LandSnowTile {
    const geometry = new BufferGeometry();
    geometry.setAttribute(
      'position',
      new Float32BufferAttribute(job.positions, 3).setUsage(DynamicDrawUsage),
    );
    geometry.setAttribute(
      'color',
      new Float32BufferAttribute(job.colors, 3).setUsage(DynamicDrawUsage),
    );
    geometry.setIndex(job.indices);
    geometry.computeVertexNormals();
    (geometry.getAttribute('normal') as Float32BufferAttribute).setUsage(
      DynamicDrawUsage,
    );
    geometry.computeBoundingSphere();
    if (geometry.boundingSphere) {
      geometry.boundingSphere.radius += MAXIMUM_SNOW_DEPTH * 0.7;
    }
    const mesh = new Mesh(geometry, this.material);
    mesh.name = `Land snow tile ${job.tileX},${job.tileZ}`;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    this.tileActivations += 1;
    return {
      tileX: job.tileX,
      tileZ: job.tileZ,
      depth: job.depth,
      compaction: job.compaction,
      initialDepth: job.initialDepth,
      cellularTint: job.cellularTint,
      edgeSnowDepth: job.edgeSnowDepth,
      surfaceX: job.surfaceX,
      geometry,
      mesh,
      modified: job.modified,
      dirty: false,
      dirtyMinColumn: LAND_SNOW_SAMPLES,
      dirtyMaxColumn: -1,
      dirtyMinRow: LAND_SNOW_SAMPLES,
      dirtyMaxRow: -1,
      dirtyMinColumnByRow: new Int16Array(LAND_SNOW_SAMPLES).fill(
        LAND_SNOW_SAMPLES,
      ),
      dirtyMaxColumnByRow: new Int16Array(LAND_SNOW_SAMPLES).fill(-1),
    };
  }

  private buildTileSynchronously(tileX: number, tileZ: number): LandSnowTile {
    const key = tileKey(tileX, tileZ);
    const usesPrefetchJob = this.prefetchJob?.key === key;
    const job = usesPrefetchJob
      ? this.prefetchJob!
      : this.createTileBuildJob(tileX, tileZ);
    let completed: LandSnowTile | undefined;
    while (!completed) completed = this.advanceTileBuild(job);
    if (usesPrefetchJob) this.prefetchJob = undefined;
    this.queuedPrefetchKeys.delete(key);
    return completed;
  }

  private takeNextPrefetchJob(): LandSnowTileBuildJob | undefined {
    while (this.prefetchQueue.length > 0) {
      const [tileX, tileZ] = this.prefetchQueue.shift()!;
      const key = tileKey(tileX, tileZ);
      if (this.activeTiles.has(key) || this.cachedTiles.has(key)) {
        this.queuedPrefetchKeys.delete(key);
        continue;
      }
      return this.createTileBuildJob(tileX, tileZ);
    }
    return undefined;
  }

  private queuePrefetchRing(
    centerTileX: number,
    centerTileZ: number,
    x: number,
    z: number,
    movementX: number,
    movementZ: number,
  ): void {
    this.prefetchQueue.length = 0;
    this.queuedPrefetchKeys.clear();
    if (this.prefetchJob) this.queuedPrefetchKeys.add(this.prefetchJob.key);
    const radius = this.activeRadius + 1;
    const movementLength = Math.hypot(movementX, movementZ);
    const directionX = movementLength > 0.0001 ? movementX / movementLength : 0;
    const directionZ = movementLength > 0.0001 ? movementZ / movementLength : 0;
    const candidates: Array<{
      tileX: number;
      tileZ: number;
      score: number;
    }> = [];
    for (let offsetZ = -radius; offsetZ <= radius; offsetZ += 1) {
      for (let offsetX = -radius; offsetX <= radius; offsetX += 1) {
        if (Math.max(Math.abs(offsetX), Math.abs(offsetZ)) !== radius) continue;
        const tileX = centerTileX + offsetX;
        const tileZ = centerTileZ + offsetZ;
        const key = tileKey(tileX, tileZ);
        if (
          this.activeTiles.has(key) ||
          this.cachedTiles.has(key) ||
          this.queuedPrefetchKeys.has(key) ||
          !this.tileTouchesLand(tileX, tileZ)
        ) continue;
        const tileCenterX = (tileX + 0.5) * LAND_SNOW_TILE_SIZE;
        const tileCenterZ = (tileZ + 0.5) * LAND_SNOW_TILE_SIZE;
        const deltaX = tileCenterX - x;
        const deltaZ = tileCenterZ - z;
        const distance = Math.hypot(deltaX, deltaZ);
        const forward = deltaX * directionX + deltaZ * directionZ;
        candidates.push({
          tileX,
          tileZ,
          score: distance - Math.max(0, forward) * 0.72,
        });
      }
    }
    candidates.sort((left, right) =>
      left.score - right.score ||
      left.tileZ - right.tileZ ||
      left.tileX - right.tileX
    );
    for (const candidate of candidates) {
      const key = tileKey(candidate.tileX, candidate.tileZ);
      this.queuedPrefetchKeys.add(key);
      this.prefetchQueue.push([candidate.tileX, candidate.tileZ]);
    }
  }

  private cacheTile(key: string, tile: LandSnowTile): void {
    tile.mesh.removeFromParent();
    const previous = this.cachedTiles.get(key);
    if (previous && previous !== tile) previous.geometry.dispose();
    this.cachedTiles.delete(key);
    this.cachedTiles.set(key, tile);
    while (this.cachedTiles.size > LandSnowSystem.MAXIMUM_CACHED_TILES) {
      const oldest = this.cachedTiles.entries().next().value as
        | [string, LandSnowTile]
        | undefined;
      if (!oldest) break;
      this.cachedTiles.delete(oldest[0]);
      oldest[1].geometry.dispose();
    }
  }

  private validateCanonicalChanges(
    input: readonly PackedSnowSample[],
  ): readonly PackedSnowSample[] {
    const changes: PackedSnowSample[] = [];
    const seen = new Set<number>();
    for (const change of input) {
      if (
        !Array.isArray(change) ||
        change.length !== 3 ||
        !Number.isSafeInteger(change[0]) ||
        change[0] < 0 ||
        change[0] >= LAND_SNOW_SAMPLE_COUNT ||
        !Number.isSafeInteger(change[1]) ||
        change[1] < 0 ||
        change[1] > 65_535 ||
        !Number.isSafeInteger(change[2]) ||
        change[2] < 0 ||
        change[2] > 255 ||
        seen.has(change[0])
      ) continue;
      seen.add(change[0]);
      changes.push([change[0], change[1], change[2]]);
    }
    return changes.sort((a, b) => a[0] - b[0]);
  }

  private reconcileActiveTile(tile: LandSnowTile): number {
    const desired = new Map(
      (this.savedTiles.get(tileKey(tile.tileX, tile.tileZ))?.changes ?? [])
        .map((change) => [change[0], change] as const),
    );
    const dirty = new Set<LandSnowTile>();
    let changed = 0;
    for (let index = 0; index < LAND_SNOW_SAMPLE_COUNT; index += 1) {
      const packed = desired.get(index);
      const row = Math.floor(index / LAND_SNOW_SAMPLES);
      const sampleX = tile.surfaceX[index] ?? 0;
      const sampleZ = tile.tileZ * LAND_SNOW_TILE_SIZE +
        row * LAND_SNOW_SPACING;
      const excluded = this.isSnowExcluded(sampleX, sampleZ);
      const depth = excluded
        ? 0
        : packed
        ? decodeDepth(packed[1])
        : (tile.initialDepth[index] ?? 0);
      const compaction = excluded ? 0 : packed ? decodeUnit(packed[2]) : 0;
      if (
        Math.abs((tile.depth[index] ?? 0) - depth) <= 0.00001 &&
        Math.abs((tile.compaction[index] ?? 0) - compaction) <= 0.00001
      ) continue;
      tile.depth[index] = depth;
      tile.compaction[index] = compaction;
      this.markTileDirty(tile, index, dirty);
      changed += 1;
    }
    tile.modified = desired.size > 0;
    return changed;
  }

  private createTileGeometry(
    tileX: number,
    tileZ: number,
    depth: Float32Array,
    compaction: Float32Array,
    cellularTint: Float32Array,
    edgeSnowDepth: Float32Array,
    surfaceX: Float32Array,
  ): BufferGeometry {
    const positions = new Float32Array(LAND_SNOW_SAMPLE_COUNT * 3);
    const colors = new Float32Array(LAND_SNOW_SAMPLE_COUNT * 3);
    this.writeTileAttributes(
      tileZ,
      depth,
      compaction,
      cellularTint,
      edgeSnowDepth,
      surfaceX,
      positions,
      colors,
      0,
      0,
      LAND_SNOW_SEGMENTS,
      LAND_SNOW_SEGMENTS,
    );
    const indices: number[] = [];
    for (let row = 0; row < LAND_SNOW_SEGMENTS; row += 1) {
      for (let column = 0; column < LAND_SNOW_SEGMENTS; column += 1) {
        const centerX =
          tileX * LAND_SNOW_TILE_SIZE +
          (column + 0.5) * LAND_SNOW_SPACING;
        const centerZ =
          tileZ * LAND_SNOW_TILE_SIZE +
          (row + 0.5) * LAND_SNOW_SPACING;
        if (!isBorealisLand(centerX, centerZ)) continue;
        // Leave a narrow exposed rock seam instead of stretching the shared
        // snow heightfield diagonally across an authored vertical cliff.
        if (this.terrain.isNearCliff(centerX, centerZ, 0.34)) continue;
        const a = sampleIndex(column, row);
        const b = sampleIndex(column + 1, row);
        const c = sampleIndex(column, row + 1);
        const d = sampleIndex(column + 1, row + 1);
        const cornerSamples = [
          [surfaceX[a] ?? centerX, tileZ * LAND_SNOW_TILE_SIZE + row * LAND_SNOW_SPACING],
          [surfaceX[b] ?? centerX, tileZ * LAND_SNOW_TILE_SIZE + row * LAND_SNOW_SPACING],
          [surfaceX[c] ?? centerX, tileZ * LAND_SNOW_TILE_SIZE + (row + 1) * LAND_SNOW_SPACING],
          [surfaceX[d] ?? centerX, tileZ * LAND_SNOW_TILE_SIZE + (row + 1) * LAND_SNOW_SPACING],
        ] as const;
        if (
          this.isSnowExcluded(centerX, centerZ) ||
          cornerSamples.some(([x, z]) => this.isSnowExcluded(x, z))
        ) {
          continue;
        }
        indices.push(a, c, b, b, c, d);
      }
    }
    const geometry = new BufferGeometry();
    geometry.setAttribute(
      'position',
      new Float32BufferAttribute(positions, 3).setUsage(DynamicDrawUsage),
    );
    geometry.setAttribute(
      'color',
      new Float32BufferAttribute(colors, 3).setUsage(DynamicDrawUsage),
    );
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    (geometry.getAttribute('normal') as Float32BufferAttribute).setUsage(
      DynamicDrawUsage,
    );
    geometry.computeBoundingSphere();
    if (geometry.boundingSphere) {
      geometry.boundingSphere.radius += MAXIMUM_SNOW_DEPTH * 0.7;
    }
    return geometry;
  }

  private updateTileMesh(tile: LandSnowTile): number {
    if (!tile.dirty || tile.dirtyMaxColumn < tile.dirtyMinColumn) return 0;
    const positions = tile.geometry.getAttribute('position') as Float32BufferAttribute;
    const colors = tile.geometry.getAttribute('color') as Float32BufferAttribute;
    const normals = tile.geometry.getAttribute('normal') as Float32BufferAttribute;
    const minRow = tile.dirtyMinRow;
    const maxRow = tile.dirtyMaxRow;
    positions.clearUpdateRanges();
    colors.clearUpdateRanges();
    const normalMinColumnByRow = this.normalMinColumnScratch;
    const normalMaxColumnByRow = this.normalMaxColumnScratch;
    normalMinColumnByRow.fill(LAND_SNOW_SAMPLES);
    normalMaxColumnByRow.fill(-1);
    let updatedVertices = 0;
    for (let row = minRow; row <= maxRow; row += 1) {
      const minColumn = tile.dirtyMinColumnByRow[row] ?? LAND_SNOW_SAMPLES;
      const maxColumn = tile.dirtyMaxColumnByRow[row] ?? -1;
      if (maxColumn < minColumn) continue;
      this.writeTileAttributes(
        tile.tileZ,
        tile.depth,
        tile.compaction,
        tile.cellularTint,
        tile.edgeSnowDepth,
        tile.surfaceX,
        positions.array as Float32Array,
        colors.array as Float32Array,
        minColumn,
        row,
        maxColumn,
        row,
      );
      const start = sampleIndex(minColumn, row) * 3;
      const count = (maxColumn - minColumn + 1) * 3;
      positions.addUpdateRange(start, count);
      colors.addUpdateRange(start, count);
      updatedVertices += maxColumn - minColumn + 1;
      const normalMinColumn = Math.max(0, minColumn - 1);
      const normalMaxColumn = Math.min(LAND_SNOW_SEGMENTS, maxColumn + 1);
      for (
        let normalRow = Math.max(0, row - 1);
        normalRow <= Math.min(LAND_SNOW_SEGMENTS, row + 1);
        normalRow += 1
      ) {
        normalMinColumnByRow[normalRow] = Math.min(
          normalMinColumnByRow[normalRow] ?? LAND_SNOW_SAMPLES,
          normalMinColumn,
        );
        normalMaxColumnByRow[normalRow] = Math.max(
          normalMaxColumnByRow[normalRow] ?? -1,
          normalMaxColumn,
        );
      }
    }
    if (updatedVertices > 0) {
      positions.needsUpdate = true;
      colors.needsUpdate = true;
    }
    normals.clearUpdateRanges();
    for (let row = 0; row < LAND_SNOW_SAMPLES; row += 1) {
      const normalMinColumn = normalMinColumnByRow[row] ?? LAND_SNOW_SAMPLES;
      const normalMaxColumn = normalMaxColumnByRow[row] ?? -1;
      if (normalMaxColumn < normalMinColumn) continue;
      this.updateTileNormals(
        positions.array as Float32Array,
        normals.array as Float32Array,
        normalMinColumn,
        row,
        normalMaxColumn,
        row,
      );
      normals.addUpdateRange(
        sampleIndex(normalMinColumn, row) * 3,
        (normalMaxColumn - normalMinColumn + 1) * 3,
      );
    }
    if (updatedVertices > 0) normals.needsUpdate = true;
    tile.dirty = false;
    tile.dirtyMinColumn = LAND_SNOW_SAMPLES;
    tile.dirtyMaxColumn = -1;
    tile.dirtyMinRow = LAND_SNOW_SAMPLES;
    tile.dirtyMaxRow = -1;
    tile.dirtyMinColumnByRow.fill(LAND_SNOW_SAMPLES);
    tile.dirtyMaxColumnByRow.fill(-1);
    return updatedVertices;
  }

  private writeTileAttributes(
    tileZ: number,
    depth: Float32Array,
    compaction: Float32Array,
    cellularTint: Float32Array,
    edgeSnowDepth: Float32Array,
    surfaceX: Float32Array,
    positions: Float32Array,
    colors: Float32Array,
    minColumn: number,
    minRow: number,
    maxColumn: number,
    maxRow: number,
  ): void {
    for (let row = minRow; row <= maxRow; row += 1) {
      for (let column = minColumn; column <= maxColumn; column += 1) {
        const index = sampleIndex(column, row);
        const z = tileZ * LAND_SNOW_TILE_SIZE + row * LAND_SNOW_SPACING;
        const x = surfaceX[index] ?? 0;
        const excluded = this.isSnowExcluded(x, z);
        const storedSnowDepth = depth[index] ?? 0;
        const snowDepth =
          excluded
            ? 0
            : storedSnowDepth <= 0
            ? edgeSnowDepth[index] ?? 0
            : storedSnowDepth;
        const packed = compaction[index] ?? 0;
        const tint = cellularTint[index] ?? 0;
        const height =
          this.terrain.sampleHeight(x, z) +
          0.012 +
          visualSnowHeight(snowDepth, packed);
        positions[index * 3] = x;
        positions[index * 3 + 1] = height;
        positions[index * 3 + 2] = z;

        const snow = smoothstep(0.025, 0.18, snowDepth);
        const surfaceMaterial = this.terrain.sampleMaterial(x, z);
        const road = isBorealisTownRoad(x, z) ||
          surfaceMaterial === 'ROAD';
        const sidewalk = surfaceMaterial === 'SIDEWALK';
        const groundR = road ? 0.19 : sidewalk ? 0.45 : surfaceMaterial === 'ROCK' ? 0.34 : surfaceMaterial === 'DIRT' ? 0.35 : 0.22;
        const groundG = road ? 0.205 : sidewalk ? 0.48 : surfaceMaterial === 'ROCK' ? 0.38 : surfaceMaterial === 'DIRT' ? 0.27 : 0.29;
        const groundB = road ? 0.21 : sidewalk ? 0.49 : surfaceMaterial === 'ROCK' ? 0.36 : surfaceMaterial === 'DIRT' ? 0.2 : 0.27;
        const freshR = 0.91 + tint * 0.65;
        const freshG = 0.97 + tint;
        const freshB = 0.965 + tint;
        const pile = smoothstep(0.72, 1.55, snowDepth);
        const packedR = 0.55;
        const packedG = 0.72;
        const packedB = 0.76;
        const snowR = lerp(freshR + pile * 0.055, packedR, packed * 0.9);
        const snowG = lerp(freshG + pile * 0.045, packedG, packed * 0.9);
        const snowB = lerp(freshB + pile * 0.02, packedB, packed * 0.9);
        colors[index * 3] = lerp(groundR, snowR, snow);
        colors[index * 3 + 1] = lerp(groundG, snowG, snow);
        colors[index * 3 + 2] = lerp(groundB, snowB, snow);
      }
    }
  }

  private onTerrainEdited(bounds: TerrainEditBounds): void {
    // Dormant meshes and partially built rows encode the terrain height and
    // material that existed before the edit. Discard only intersecting cache
    // entries, then let the normal outer-ring queue rebuild them gradually.
    for (const [key, tile] of [...this.cachedTiles]) {
      const minX = tile.tileX * LAND_SNOW_TILE_SIZE;
      const minZ = tile.tileZ * LAND_SNOW_TILE_SIZE;
      if (
        minX + LAND_SNOW_TILE_SIZE < bounds.minX ||
        minX > bounds.maxX ||
        minZ + LAND_SNOW_TILE_SIZE < bounds.minZ ||
        minZ > bounds.maxZ
      ) continue;
      this.cachedTiles.delete(key);
      tile.geometry.dispose();
    }
    if (this.prefetchJob && this.tileIntersectsBounds(
      this.prefetchJob.tileX,
      this.prefetchJob.tileZ,
      bounds,
    )) {
      this.queuedPrefetchKeys.delete(this.prefetchJob.key);
      this.prefetchJob = undefined;
    }
    this.prefetchQueue.length = 0;
    this.queuedPrefetchKeys.clear();
    for (const tile of this.activeTiles.values()) {
      const minX = tile.tileX * LAND_SNOW_TILE_SIZE;
      const minZ = tile.tileZ * LAND_SNOW_TILE_SIZE;
      if (
        minX + LAND_SNOW_TILE_SIZE < bounds.minX ||
        minX > bounds.maxX ||
        minZ + LAND_SNOW_TILE_SIZE < bounds.minZ ||
        minZ > bounds.maxZ
      ) continue;
      if (bounds.kind === 'SURFACE' || bounds.kind === 'IMPORT') {
        for (let row = 0; row < LAND_SNOW_SAMPLES; row += 1) {
          const z = minZ + row * LAND_SNOW_SPACING;
          for (let column = 0; column < LAND_SNOW_SAMPLES; column += 1) {
            const x = minX + column * LAND_SNOW_SPACING;
            if (
              x < bounds.minX || x > bounds.maxX ||
              z < bounds.minZ || z > bounds.maxZ ||
              !isBorealisLand(x, z)
            ) continue;
            const index = sampleIndex(column, row);
            if (this.isSnowExcluded(x, z)) {
              tile.depth[index] = 0;
              tile.initialDepth[index] = 0;
              tile.compaction[index] = 0;
            } else if ((tile.initialDepth[index] ?? 0) <= 0.0001) {
              const restored = initialSnowDepth(x, z, snowCellPattern(x, z));
              tile.initialDepth[index] = restored;
              tile.depth[index] = restored;
            }
          }
        }
      }
      const previous = tile.geometry;
      const replacement = this.createTileGeometry(
        tile.tileX,
        tile.tileZ,
        tile.depth,
        tile.compaction,
        tile.cellularTint,
        tile.edgeSnowDepth,
        tile.surfaceX,
      );
      tile.geometry = replacement;
      tile.mesh.geometry = replacement;
      previous.dispose();
      tile.dirty = false;
      tile.dirtyMinColumn = LAND_SNOW_SAMPLES;
      tile.dirtyMaxColumn = -1;
      tile.dirtyMinRow = LAND_SNOW_SAMPLES;
      tile.dirtyMaxRow = -1;
      tile.dirtyMinColumnByRow.fill(LAND_SNOW_SAMPLES);
      tile.dirtyMaxColumnByRow.fill(-1);
      this.pendingDirtyTiles.delete(tile);
    }
    if (this.centerTileX !== undefined && this.centerTileZ !== undefined) {
      const centerX = (this.centerTileX + 0.5) * LAND_SNOW_TILE_SIZE;
      const centerZ = (this.centerTileZ + 0.5) * LAND_SNOW_TILE_SIZE;
      this.queuePrefetchRing(
        this.centerTileX,
        this.centerTileZ,
        centerX,
        centerZ,
        0,
        0,
      );
    }
  }

  private tileIntersectsBounds(
    tileX: number,
    tileZ: number,
    bounds: Readonly<Pick<
      TerrainEditBounds,
      'minX' | 'maxX' | 'minZ' | 'maxZ'
    >>,
  ): boolean {
    const minX = tileX * LAND_SNOW_TILE_SIZE;
    const minZ = tileZ * LAND_SNOW_TILE_SIZE;
    return !(
      minX + LAND_SNOW_TILE_SIZE < bounds.minX ||
      minX > bounds.maxX ||
      minZ + LAND_SNOW_TILE_SIZE < bounds.minZ ||
      minZ > bounds.maxZ
    );
  }

  private updateTileNormals(
    positions: Float32Array,
    normals: Float32Array,
    minColumn: number,
    minRow: number,
    maxColumn: number,
    maxRow: number,
  ): void {
    for (let row = minRow; row <= maxRow; row += 1) {
      for (let column = minColumn; column <= maxColumn; column += 1) {
        const left = sampleIndex(Math.max(0, column - 1), row) * 3;
        const right =
          sampleIndex(Math.min(LAND_SNOW_SEGMENTS, column + 1), row) * 3;
        const near = sampleIndex(column, Math.max(0, row - 1)) * 3;
        const far =
          sampleIndex(column, Math.min(LAND_SNOW_SEGMENTS, row + 1)) * 3;
        const tangentXx =
          (positions[right] ?? 0) - (positions[left] ?? 0);
        const tangentXy =
          (positions[right + 1] ?? 0) - (positions[left + 1] ?? 0);
        const tangentXz =
          (positions[right + 2] ?? 0) - (positions[left + 2] ?? 0);
        const tangentZx =
          (positions[far] ?? 0) - (positions[near] ?? 0);
        const tangentZy =
          (positions[far + 1] ?? 0) - (positions[near + 1] ?? 0);
        const tangentZz =
          (positions[far + 2] ?? 0) - (positions[near + 2] ?? 0);
        let nx = tangentZy * tangentXz - tangentZz * tangentXy;
        let ny = tangentZz * tangentXx - tangentZx * tangentXz;
        let nz = tangentZx * tangentXy - tangentZy * tangentXx;
        const length = Math.hypot(nx, ny, nz);
        if (length > 0.00001) {
          nx /= length;
          ny /= length;
          nz /= length;
        } else {
          nx = 0;
          ny = 1;
          nz = 0;
        }
        const index = sampleIndex(column, row) * 3;
        normals[index] = nx;
        normals[index + 1] = ny;
        normals[index + 2] = nz;
      }
    }
  }

  private samplesInRadius(
    x: number,
    z: number,
    radius: number,
  ): MutableSample[] {
    const samples: MutableSample[] = [];
    const minTileX = Math.floor((x - radius) / LAND_SNOW_TILE_SIZE);
    const maxTileX = Math.floor((x + radius) / LAND_SNOW_TILE_SIZE);
    const minTileZ = Math.floor((z - radius) / LAND_SNOW_TILE_SIZE);
    const maxTileZ = Math.floor((z + radius) / LAND_SNOW_TILE_SIZE);
    const radiusSquared = radius * radius;
    for (let tileZ = minTileZ; tileZ <= maxTileZ; tileZ += 1) {
      for (let tileX = minTileX; tileX <= maxTileX; tileX += 1) {
        const tile = this.activeTiles.get(tileKey(tileX, tileZ));
        if (!tile) continue;
        const minColumn = clamp(
          Math.floor((x - radius - tileX * LAND_SNOW_TILE_SIZE) / LAND_SNOW_SPACING),
          0,
          LAND_SNOW_SEGMENTS,
        );
        const maxColumn = clamp(
          Math.ceil((x + radius - tileX * LAND_SNOW_TILE_SIZE) / LAND_SNOW_SPACING),
          0,
          LAND_SNOW_SEGMENTS,
        );
        const minRow = clamp(
          Math.floor((z - radius - tileZ * LAND_SNOW_TILE_SIZE) / LAND_SNOW_SPACING),
          0,
          LAND_SNOW_SEGMENTS,
        );
        const maxRow = clamp(
          Math.ceil((z + radius - tileZ * LAND_SNOW_TILE_SIZE) / LAND_SNOW_SPACING),
          0,
          LAND_SNOW_SEGMENTS,
        );
        for (let row = minRow; row <= maxRow; row += 1) {
          for (let column = minColumn; column <= maxColumn; column += 1) {
            const sampleX = tileX * LAND_SNOW_TILE_SIZE + column * LAND_SNOW_SPACING;
            const sampleZ = tileZ * LAND_SNOW_TILE_SIZE + row * LAND_SNOW_SPACING;
            if (!this.isCanonicalTileSample(
              tileX,
              tileZ,
              sampleX,
              sampleZ,
            )) continue;
            const dx = sampleX - x;
            const dz = sampleZ - z;
            if (dx * dx + dz * dz > radiusSquared) continue;
            if (!isBorealisLand(sampleX, sampleZ)) continue;
            if (this.isSnowExcluded(sampleX, sampleZ)) continue;
            samples.push({
              tile,
              index: sampleIndex(column, row),
              x: sampleX,
              z: sampleZ,
            });
          }
        }
      }
    }
    return samples;
  }

  private readGridSample(
    x: number,
    z: number,
  ): { depth: number; compaction: number } {
    if (this.isSnowExcluded(x, z)) return { depth: 0, compaction: 0 };
    const tileX = Math.floor(x / LAND_SNOW_TILE_SIZE);
    const tileZ = Math.floor(z / LAND_SNOW_TILE_SIZE);
    const localX = x - tileX * LAND_SNOW_TILE_SIZE;
    const localZ = z - tileZ * LAND_SNOW_TILE_SIZE;
    const index = sampleIndex(
      clamp(Math.round(localX / LAND_SNOW_SPACING), 0, LAND_SNOW_SEGMENTS),
      clamp(Math.round(localZ / LAND_SNOW_SPACING), 0, LAND_SNOW_SEGMENTS),
    );
    const active = this.activeTiles.get(tileKey(tileX, tileZ));
    if (active) {
      return {
        depth: active.depth[index] ?? 0,
        compaction: active.compaction[index] ?? 0,
      };
    }
    const stored = this.savedTiles
      .get(tileKey(tileX, tileZ))
      ?.changes.find((change) => change[0] === index);
    return stored
      ? { depth: decodeDepth(stored[1]), compaction: decodeUnit(stored[2]) }
      : {
          depth: this.isSnowExcluded(x, z)
            ? 0
            : initialSnowDepth(x, z),
          compaction: 0,
        };
  }

  private writeGridSample(
    x: number,
    z: number,
    depth: number,
    compaction: number,
    dirtyTiles: Set<LandSnowTile>,
  ): void {
    if (this.isSnowExcluded(x, z)) {
      depth = 0;
      compaction = 0;
    }
    const tileX = Math.floor(x / LAND_SNOW_TILE_SIZE);
    const tileZ = Math.floor(z / LAND_SNOW_TILE_SIZE);
    const localX = x - tileX * LAND_SNOW_TILE_SIZE;
    const localZ = z - tileZ * LAND_SNOW_TILE_SIZE;
    const index = sampleIndex(
      clamp(Math.round(localX / LAND_SNOW_SPACING), 0, LAND_SNOW_SEGMENTS),
      clamp(Math.round(localZ / LAND_SNOW_SPACING), 0, LAND_SNOW_SEGMENTS),
    );
    const active = this.activeTiles.get(tileKey(tileX, tileZ));
    if (active) {
      active.depth[index] = clamp(depth, 0, MAXIMUM_SNOW_DEPTH);
      active.compaction[index] = clamp(compaction, 0, 1);
      this.markTileDirty(active, index, dirtyTiles);
      return;
    }
    const key = tileKey(tileX, tileZ);
    const saved = this.savedTiles.get(key);
    const changes = saved ? [...saved.changes] : [];
    const existingIndex = changes.findIndex((change) => change[0] === index);
    const initial = this.isSnowExcluded(x, z)
      ? 0
      : initialSnowDepth(x, z);
    if (Math.abs(depth - initial) < 0.008 && compaction < 0.008) {
      if (existingIndex >= 0) changes.splice(existingIndex, 1);
    } else {
      const change = [
        index,
        encodeDepth(depth),
        encodeUnit(compaction),
      ] as const;
      if (existingIndex >= 0) changes[existingIndex] = change;
      else changes.push(change);
    }
    if (changes.length === 0) this.savedTiles.delete(key);
    else {
      this.savedTiles.set(key, { tileX, tileZ, changes });
    }
  }

  private settleSteepSamples(
    tiles: Set<LandSnowTile>,
    profile: 'NORMAL' | 'FLOWING' = 'NORMAL',
  ): void {
    for (const tile of tiles) {
      const rounds = profile === 'FLOWING' ? 3 : 1;
      for (let round = 0; round < rounds; round += 1) {
        const transfers: Array<readonly [number, number, number]> = [];
        const minRow = Math.max(1, tile.dirtyMinRow - 1);
        const maxRow = Math.min(
          LAND_SNOW_SEGMENTS - 1,
          tile.dirtyMaxRow + 1,
        );
        const minColumn = Math.max(1, tile.dirtyMinColumn - 1);
        const maxColumn = Math.min(
          LAND_SNOW_SEGMENTS - 1,
          tile.dirtyMaxColumn + 1,
        );
        for (let row = minRow; row <= maxRow; row += 1) {
          for (let column = minColumn; column <= maxColumn; column += 1) {
            const index = sampleIndex(column, row);
            const depth = tile.depth[index] ?? 0;
            let lowestIndex = index;
            let lowest = depth;
            for (const [offsetX, offsetZ] of [
              [-1, 0],
              [1, 0],
              [0, -1],
              [0, 1],
            ] as const) {
              const neighbor = sampleIndex(column + offsetX, row + offsetZ);
              const neighborX = tile.tileX * LAND_SNOW_TILE_SIZE +
                (column + offsetX) * LAND_SNOW_SPACING;
              const neighborZ = tile.tileZ * LAND_SNOW_TILE_SIZE +
                (row + offsetZ) * LAND_SNOW_SPACING;
              if (this.isSnowExcluded(neighborX, neighborZ)) continue;
              const neighborDepth = tile.depth[neighbor] ?? 0;
              if (neighborDepth < lowest) {
                lowest = neighborDepth;
                lowestIndex = neighbor;
              }
            }
            const packed = tile.compaction[index] ?? 0;
            const stableDifference = profile === 'FLOWING'
              ? lerp(0.24, 0.38, packed)
              : 0.42;
            const excess = depth - lowest - stableDifference;
            if (excess > 0) {
              transfers.push([
                index,
                lowestIndex,
                profile === 'FLOWING'
                  ? Math.min(0.065, excess * 0.22)
                  : Math.min(0.045, (depth - lowest) * 0.09),
              ]);
            }
          }
        }
        if (transfers.length === 0) break;
        for (const [from, to, amount] of transfers) {
          const accepted = Math.min(
            amount,
            Math.max(0, MAXIMUM_SNOW_DEPTH - (tile.depth[to] ?? 0)),
          );
          if (accepted <= 0.000001) continue;
          tile.depth[from] = Math.max(0, (tile.depth[from] ?? 0) - accepted);
          tile.depth[to] = (tile.depth[to] ?? 0) + accepted;
          this.markTileDirty(tile, from, tiles);
          this.markTileDirty(tile, to, tiles);
        }
      }
    }
  }

  private markTileDirty(
    tile: LandSnowTile,
    index: number,
    dirtyTiles: Set<LandSnowTile>,
  ): void {
    this.markTileDirtyLocal(tile, index, dirtyTiles);
    this.synchronizeSharedGridSample(tile, index, dirtyTiles);
  }

  private markTileDirtyLocal(
    tile: LandSnowTile,
    index: number,
    dirtyTiles: Set<LandSnowTile>,
  ): void {
    const column = index % LAND_SNOW_SAMPLES;
    const row = Math.floor(index / LAND_SNOW_SAMPLES);
    tile.modified = true;
    tile.dirty = true;
    tile.dirtyMinColumn = Math.min(tile.dirtyMinColumn, column);
    tile.dirtyMaxColumn = Math.max(tile.dirtyMaxColumn, column);
    tile.dirtyMinRow = Math.min(tile.dirtyMinRow, row);
    tile.dirtyMaxRow = Math.max(tile.dirtyMaxRow, row);
    tile.dirtyMinColumnByRow[row] = Math.min(
      tile.dirtyMinColumnByRow[row] ?? LAND_SNOW_SAMPLES,
      column,
    );
    tile.dirtyMaxColumnByRow[row] = Math.max(
      tile.dirtyMaxColumnByRow[row] ?? -1,
      column,
    );
    dirtyTiles.add(tile);
    this.pendingDirtyTiles.add(tile);
  }

  /**
   * Each self-contained 16 m mesh duplicates its outer vertex row. Keep the
   * active copies bit-identical so a drift operation cannot expose a vertical
   * crack at the tile boundary.
   */
  private synchronizeSharedGridSample(
    changedTile: LandSnowTile,
    changedIndex: number,
    dirtyTiles: Set<LandSnowTile>,
  ): void {
    const changedColumn = changedIndex % LAND_SNOW_SAMPLES;
    const changedRow = Math.floor(changedIndex / LAND_SNOW_SAMPLES);
    if (
      changedColumn !== 0 && changedColumn !== LAND_SNOW_SEGMENTS &&
      changedRow !== 0 && changedRow !== LAND_SNOW_SEGMENTS
    ) return;

    const worldX = changedTile.tileX * LAND_SNOW_TILE_SIZE +
      changedColumn * LAND_SNOW_SPACING;
    const worldZ = changedTile.tileZ * LAND_SNOW_TILE_SIZE +
      changedRow * LAND_SNOW_SPACING;
    const ownerTileX = Math.floor(worldX / LAND_SNOW_TILE_SIZE);
    const ownerTileZ = Math.floor(worldZ / LAND_SNOW_TILE_SIZE);
    const owner = this.activeTiles.get(tileKey(ownerTileX, ownerTileZ));
    const ownerColumn = clamp(
      Math.round(
        (worldX - ownerTileX * LAND_SNOW_TILE_SIZE) / LAND_SNOW_SPACING,
      ),
      0,
      LAND_SNOW_SEGMENTS,
    );
    const ownerRow = clamp(
      Math.round(
        (worldZ - ownerTileZ * LAND_SNOW_TILE_SIZE) / LAND_SNOW_SPACING,
      ),
      0,
      LAND_SNOW_SEGMENTS,
    );
    const ownerIndex = sampleIndex(ownerColumn, ownerRow);
    const source = owner ?? changedTile;
    const sourceIndex = owner ? ownerIndex : changedIndex;
    const depth = source.depth[sourceIndex] ?? 0;
    const compaction = source.compaction[sourceIndex] ?? 0;
    const candidateTileXs = ownerColumn === 0
      ? [ownerTileX - 1, ownerTileX]
      : [ownerTileX];
    const candidateTileZs = ownerRow === 0
      ? [ownerTileZ - 1, ownerTileZ]
      : [ownerTileZ];

    for (const tileZ of candidateTileZs) {
      for (const tileX of candidateTileXs) {
        const target = this.activeTiles.get(tileKey(tileX, tileZ));
        if (!target) continue;
        const column = clamp(
          Math.round(
            (worldX - tileX * LAND_SNOW_TILE_SIZE) / LAND_SNOW_SPACING,
          ),
          0,
          LAND_SNOW_SEGMENTS,
        );
        const row = clamp(
          Math.round(
            (worldZ - tileZ * LAND_SNOW_TILE_SIZE) / LAND_SNOW_SPACING,
          ),
          0,
          LAND_SNOW_SEGMENTS,
        );
        const index = sampleIndex(column, row);
        if (
          Math.abs((target.depth[index] ?? 0) - depth) <= 0.000001 &&
          Math.abs((target.compaction[index] ?? 0) - compaction) <= 0.000001
        ) continue;
        target.depth[index] = depth;
        target.compaction[index] = compaction;
        this.markTileDirtyLocal(target, index, dirtyTiles);
      }
    }
  }

  private synchronizeActiveTileBorders(tile: LandSnowTile): void {
    const dirtyTiles = new Set<LandSnowTile>();
    for (let row = 0; row < LAND_SNOW_SAMPLES; row += 1) {
      this.synchronizeSharedGridSample(
        tile,
        sampleIndex(0, row),
        dirtyTiles,
      );
      this.synchronizeSharedGridSample(
        tile,
        sampleIndex(LAND_SNOW_SEGMENTS, row),
        dirtyTiles,
      );
    }
    for (let column = 1; column < LAND_SNOW_SEGMENTS; column += 1) {
      this.synchronizeSharedGridSample(
        tile,
        sampleIndex(column, 0),
        dirtyTiles,
      );
      this.synchronizeSharedGridSample(
        tile,
        sampleIndex(column, LAND_SNOW_SEGMENTS),
        dirtyTiles,
      );
    }
  }

  private isCanonicalTileSample(
    tileX: number,
    tileZ: number,
    x: number,
    z: number,
  ): boolean {
    return Math.floor(x / LAND_SNOW_TILE_SIZE) === tileX &&
      Math.floor(z / LAND_SNOW_TILE_SIZE) === tileZ;
  }

  private isSnowExcluded(x: number, z: number): boolean {
    return this.terrain.sampleMaterial(x, z) === 'SNOW_EXCLUSION' ||
      (this.dynamicExclusionSampler?.(x, z) ?? false);
  }

  private tileTouchesLand(tileX: number, tileZ: number): boolean {
    const baseX = tileX * LAND_SNOW_TILE_SIZE;
    const baseZ = tileZ * LAND_SNOW_TILE_SIZE;
    for (let row = 0; row <= 4; row += 1) {
      for (let column = 0; column <= 4; column += 1) {
        if (
          isBorealisLand(
            baseX + column * LAND_SNOW_TILE_SIZE / 4,
            baseZ + row * LAND_SNOW_TILE_SIZE / 4,
          )
        ) {
          return true;
        }
      }
    }
    return false;
  }

  private storeTile(tile: LandSnowTile): void {
    if (!tile.modified) return;
    const changes: Array<readonly [number, number, number]> = [];
    for (let row = 0; row < LAND_SNOW_SAMPLES; row += 1) {
      for (let column = 0; column < LAND_SNOW_SAMPLES; column += 1) {
        const index = sampleIndex(column, row);
        const initial = tile.initialDepth[index] ?? 0;
        const depth = tile.depth[index] ?? 0;
        const compaction = tile.compaction[index] ?? 0;
        if (Math.abs(depth - initial) < 0.008 && compaction < 0.008) continue;
        changes.push([index, encodeDepth(depth), encodeUnit(compaction)]);
      }
    }
    const key = tileKey(tile.tileX, tile.tileZ);
    if (changes.length === 0) {
      this.savedTiles.delete(key);
      return;
    }
    this.savedTiles.set(key, {
      tileX: tile.tileX,
      tileZ: tile.tileZ,
      changes,
    });
  }

  private applySavedTile(tile: LandSnowTile): void {
    const saved = this.savedTiles.get(tileKey(tile.tileX, tile.tileZ));
    if (!saved) return;
    for (const [index, depth, compaction] of saved.changes) {
      const row = Math.floor(index / LAND_SNOW_SAMPLES);
      const x = tile.surfaceX[index] ?? 0;
      const z = tile.tileZ * LAND_SNOW_TILE_SIZE + row * LAND_SNOW_SPACING;
      if (this.isSnowExcluded(x, z)) continue;
      tile.depth[index] = decodeDepth(depth);
      tile.compaction[index] = decodeUnit(compaction);
    }
    tile.modified = true;
    tile.dirty = true;
    tile.dirtyMinColumn = 0;
    tile.dirtyMaxColumn = LAND_SNOW_SEGMENTS;
    tile.dirtyMinRow = 0;
    tile.dirtyMaxRow = LAND_SNOW_SEGMENTS;
    tile.dirtyMinColumnByRow.fill(0);
    tile.dirtyMaxColumnByRow.fill(LAND_SNOW_SEGMENTS);
  }
}
