import type { BulldozerControlCommand } from '../input/PlayerBulldozerController';
import { clamp, damp, lerp, smoothstep } from '../utils/math';
import {
  BOREALIS_STARTER_TRACTOR_DEPLOYMENT,
  isBorealisLand,
} from './BorealisLand';
import type {
  LandSnowPlowConfiguration,
  LandSnowPlowResult,
  LandSnowTrackConfiguration,
} from './LandSnowSystem';
import {
  BULLDOZER_BLADE_PROFILES,
  DEFAULT_BULLDOZER_CAPABILITIES,
  MAX_BULLDOZER_BLADE_ANGLE_RADIANS,
  nextBulldozerBladeMode,
  type BulldozerBladeMode,
  type BulldozerCapabilities,
} from './BulldozerUpgrades';

export interface BulldozerState {
  x: number;
  z: number;
  heading: number;
  speed: number;
  steering: number;
  bladePosition: number;
  bladeDown: boolean;
  /** Normalized complete-blade yaw: -1 left, 0 straight, +1 right. */
  bladeAngle: number;
  bladeMode: BulldozerBladeMode;
  beaconOn: boolean;
  bladeLoad: number;
  tractionSlip: number;
  engineRpm: number;
  engineLoad: number;
  snowDepth: number;
  attachment: 'PLOW' | 'BUCKET';
  bucketTilt: number;
  bucketMass: number;
}

export interface BulldozerSaveData {
  version: 1 | 2 | 3 | 4;
  x: number;
  z: number;
  heading: number;
  bladePosition?: number;
  bladeAngle?: number;
  bladeMode?: BulldozerBladeMode;
  beaconOn?: boolean;
  attachment?: 'PLOW' | 'BUCKET';
  bucketTilt?: number;
  bucketMass?: number;
}

export interface BulldozerSnowSurface {
  sampleDepth(x: number, z: number): number;
  compactTracks(
    previousX: number,
    previousZ: number,
    x: number,
    z: number,
    heading: number,
    configuration?: LandSnowTrackConfiguration,
  ): number;
  plowSweep(
    previousX: number,
    previousZ: number,
    x: number,
    z: number,
    heading: number,
    configuration?: LandSnowPlowConfiguration,
  ): LandSnowPlowResult;
  extractSnow(
    x: number,
    z: number,
    radius: number,
    capacityCubicMetres: number,
    retainedDepth?: number,
  ): { snowMass: number };
}

export interface BulldozerStepResult {
  travelled: number;
  plow: LandSnowPlowResult;
  blockedByShore: boolean;
}

const EMPTY_PLOW_RESULT: LandSnowPlowResult = Object.freeze({
  removedSnow: 0,
  depositedSnow: 0,
  changedSamples: 0,
  resistance: 0,
  peakPileDepth: 0,
  overCapacity: 0,
});

const BLADE_TRAVEL_PER_SECOND = 0.72;
const BLADE_ANGLE_TRAVEL_PER_SECOND = 0.92;
const RETURNED_PLOW_EFFORT_MULTIPLIER = 1.15;

const approach = (
  current: number,
  target: number,
  maximumDelta: number,
): number =>
  current < target
    ? Math.min(target, current + maximumDelta)
    : Math.max(target, current - maximumDelta);

export class BulldozerSimulation {
  public readonly state: BulldozerState = {
    ...BOREALIS_STARTER_TRACTOR_DEPLOYMENT,
    speed: 0,
    steering: 0,
    bladePosition: 0,
    bladeDown: false,
    bladeAngle: 0,
    bladeMode: 'STRAIGHT',
    beaconOn: false,
    bladeLoad: 0,
    tractionSlip: 0,
    engineRpm: 0.18,
    engineLoad: 0,
    snowDepth: 0,
    attachment: 'PLOW',
    bucketTilt: 0.82,
    bucketMass: 0,
  };
  private capabilities: BulldozerCapabilities = {
    ...DEFAULT_BULLDOZER_CAPABILITIES,
  };

  public step(
    command: Readonly<BulldozerControlCommand>,
    deltaSeconds: number,
    snow: BulldozerSnowSurface,
  ): BulldozerStepResult {
    const delta = clamp(deltaSeconds, 0, 0.05);
    if (delta <= 0) {
      return {
        travelled: 0,
        plow: EMPTY_PLOW_RESULT,
        blockedByShore: false,
      };
    }
    const state = this.state;
    state.bladePosition = clamp(
      state.bladePosition +
        command.bladeMotion * BLADE_TRAVEL_PER_SECOND * delta,
      0,
      1,
    );
    state.bladeDown = state.bladePosition > 0.025;
    if (state.attachment === 'PLOW') {
      state.bladeAngle = clamp(
        state.bladeAngle +
          command.bladeAngleMotion * BLADE_ANGLE_TRAVEL_PER_SECOND * delta,
        -1,
        1,
      );
    }
    if (state.attachment === 'PLOW' && command.cycleBladeMode) {
      this.cycleBladeMode();
    }
    if (state.attachment === 'BUCKET') {
      state.bucketTilt = clamp(
        state.bucketTilt + command.bucketTiltMotion * 0.82 * delta,
        0,
        1,
      );
    }
    if (command.toggleBeacon) this.toggleBeacon();
    state.snowDepth = snow.sampleDepth(state.x, state.z);
    const deepSnow = clamp((state.snowDepth - 0.32) / 0.85, 0, 1);
    const bladeEngagement = clamp(
      (state.bladePosition - 0.025) / 0.975,
      0,
      1,
    );
    const bladeProfile = BULLDOZER_BLADE_PROFILES[state.bladeMode];
    const trackSnowRelief = this.capabilities.chainTracks
      ? 0.48
      : this.capabilities.wideTracks
        ? 0.66
        : 1;
    const pushOverload = state.attachment === 'PLOW'
      ? clamp(
          (state.snowDepth - this.capabilities.maximumPushDepth) /
            Math.max(0.12, this.capabilities.maximumPushDepth),
          0,
          1,
        ) * bladeEngagement
      : 0;
    const bladeDrag =
      state.attachment === 'PLOW'
        ? bladeEngagement * (0.18 + deepSnow * 0.34) *
          RETURNED_PLOW_EFFORT_MULTIPLIER
        : state.bucketMass / 0.72 * 0.24;
    const loadDrag = state.bladeLoad * 0.42;
    const tractionOverload = state.attachment === 'PLOW' && state.bladeDown
      ? clamp(
          (state.bladeLoad - this.capabilities.tractionLimit) / 0.38,
          0,
          1,
        )
      : 0;
    state.tractionSlip = damp(
      state.tractionSlip,
      tractionOverload,
      tractionOverload > state.tractionSlip ? 8.5 : 3.1,
      delta,
    );
    const tractionSpeedMultiplier = 1 - state.tractionSlip * 0.93;
    const maximumForward =
      2.9 *
      bladeProfile.speedMultiplier *
      (1 - deepSnow * 0.2 * trackSnowRelief - bladeDrag * 0.22) *
      (1 - loadDrag) *
      tractionSpeedMultiplier *
      (1 - pushOverload * 0.82);
    const targetSpeed =
      command.throttle >= 0
        ? command.throttle * maximumForward
        : command.throttle * 1.55;
    const acceleration =
      (state.bladeDown ? 2.15 : 2.9) *
      (1 - deepSnow * 0.34 * trackSnowRelief) *
      (1 - state.bladeLoad * 0.48) *
      (1 - pushOverload * 0.72);
    const speedResponse = Math.abs(targetSpeed) < Math.abs(state.speed)
      ? 3.8 + state.bladeLoad * 2.2
      : acceleration;
    state.speed = approach(
      state.speed,
      targetSpeed,
      speedResponse * delta,
    );
    if (Math.abs(command.throttle) < 0.01) {
      state.speed = damp(state.speed, 0, 2.8 + deepSnow * 1.5, delta);
    }
    state.steering = damp(
      state.steering,
      command.steering,
      7.5,
      delta,
    );
    const direction = state.speed >= 0 ? 1 : -1;
    const turnAuthority =
      clamp(Math.abs(state.speed) / 0.55, 0, 1) *
      (0.48 + Math.min(1.2, Math.abs(state.speed)) * 0.18);
    state.heading +=
      state.steering * turnAuthority * direction * delta;

    const previousX = state.x;
    const previousZ = state.z;
    const nextX =
      state.x + Math.sin(state.heading) * state.speed * delta;
    const nextZ =
      state.z + Math.cos(state.heading) * state.speed * delta;
    let blockedByShore = false;
    if (isBorealisLand(nextX, nextZ)) {
      state.x = nextX;
      state.z = nextZ;
    } else {
      state.speed *= -0.12;
      blockedByShore = true;
    }
    const travelled = Math.hypot(
      state.x - previousX,
      state.z - previousZ,
    );
    if (travelled > 0) {
      snow.compactTracks(
        previousX,
        previousZ,
        state.x,
        state.z,
        state.heading,
        this.trackConfiguration(),
      );
    }
    const plow =
      state.attachment === 'PLOW' && state.bladeDown && state.speed > 0.08
        ? snow.plowSweep(
            previousX,
            previousZ,
            state.x,
            state.z,
            state.heading,
            {
              bladePosition: state.bladePosition,
              bladeAngleRadians:
                state.bladeAngle * MAX_BULLDOZER_BLADE_ANGLE_RADIANS,
              bladeMode: state.bladeMode,
              bladeWidth: this.capabilities.heavyChassis ? 2.7 : 2.15,
              bladeForwardOffset: this.capabilities.heavyChassis ? 1.78 : 1.43,
              contactDepth: this.capabilities.heavyChassis ? 0.74 : 0.64,
              maximumPushDepth: this.capabilities.maximumPushDepth,
              maximumFrontPileDepth:
                this.capabilities.maximumFrontPileDepth,
              maximumPileDepth: this.capabilities.maximumPileDepth,
              massCapacityMultiplier:
                this.capabilities.massCapacityMultiplier,
            },
          )
        : EMPTY_PLOW_RESULT;
    if (
      state.attachment === 'BUCKET' &&
      state.bladePosition > 0.72 &&
      state.bucketTilt > 0.54 &&
      state.speed > 0.08 &&
      travelled > 0 &&
      state.bucketMass < 0.72
    ) {
      const forwardX = Math.sin(state.heading);
      const forwardZ = Math.cos(state.heading);
      const intake = snow.extractSnow(
        state.x + forwardX * 1.62,
        state.z + forwardZ * 1.62,
        0.68,
        Math.min(0.72 - state.bucketMass, travelled * 0.9),
        0.025,
      );
      state.bucketMass += intake.snowMass;
    }
    const targetBladeLoad = state.attachment === 'BUCKET'
      ? clamp(state.bucketMass / 0.72, 0, 1)
      : state.bladeDown && state.speed > 0.08
        ? Math.max(
            plow.resistance * RETURNED_PLOW_EFFORT_MULTIPLIER,
            // Capacity pressure should become punishing near a genuinely
            // over-height bank, but an ordinary fresh drift no longer jumps
            // straight to full drivetrain load. This curve is approximately
            // half the former load through the normal starter-snow range and
            // still reaches one at the physical limit.
            plow.overCapacity ** 2.15 * lerp(
              0.28,
              1,
              smoothstep(1.15, 3.2, plow.peakPileDepth),
            ),
          ) *
          lerp(
            0.5,
            1,
            smoothstep(3.4, 4.6, plow.peakPileDepth),
          ) *
          bladeProfile.resistanceMultiplier
        : 0;
    state.bladeLoad = damp(
      state.bladeLoad,
      clamp(targetBladeLoad, 0, 1),
      targetBladeLoad > state.bladeLoad ? 7.5 : 2.3,
      delta,
    );
    const plowLoad = clamp(
      plow.removedSnow * 0.62 + state.bladeLoad * 0.72,
      0,
      1,
    );
    state.engineLoad = clamp(
      Math.abs(command.throttle) * 0.35 +
        deepSnow * 0.28 +
        bladeEngagement * 0.16 +
        plowLoad * 0.45,
      0,
      1,
    );
    state.engineRpm = clamp(
      0.18 +
        (Math.abs(state.speed) / 3.1) * 0.58 +
        state.engineLoad * 0.24,
      0.16,
      1,
    );
    return { travelled, plow, blockedByShore };
  }

  public setBladeDown(down: boolean): void {
    this.setBladePosition(down ? 1 : 0);
  }

  public setAttachment(attachment: 'PLOW' | 'BUCKET'): void {
    this.state.attachment = attachment;
    this.state.speed = 0;
    if (attachment === 'PLOW') {
      this.state.bucketMass = 0;
      this.state.bucketTilt = 0.82;
    } else {
      this.state.bladeMode = 'STRAIGHT';
      this.state.bladePosition = 0;
      this.state.bladeDown = false;
    }
  }

  public getBucketDumpPoint(): { x: number; z: number; height: number } {
    const forwardX = Math.sin(this.state.heading);
    const forwardZ = Math.cos(this.state.heading);
    return {
      x: this.state.x + forwardX * 1.72,
      z: this.state.z + forwardZ * 1.72,
      height: 0.38 + (1 - this.state.bladePosition) * 2.25,
    };
  }

  public removeBucketMass(maximumMass: number): number {
    const removed = Math.min(this.state.bucketMass, Math.max(0, maximumMass));
    this.state.bucketMass -= removed;
    return removed;
  }

  public setBladePosition(position: number): void {
    this.state.bladePosition = clamp(position, 0, 1);
    this.state.bladeDown = this.state.bladePosition > 0.025;
  }

  public nudgeBlade(amount: number): void {
    this.setBladePosition(this.state.bladePosition + amount);
  }

  public cycleBladeMode(): BulldozerBladeMode {
    if (!this.capabilities.adjustableWingPlow) {
      this.state.bladeMode = 'STRAIGHT';
      return this.state.bladeMode;
    }
    this.state.bladeMode = nextBulldozerBladeMode(
      this.state.bladeMode,
    );
    return this.state.bladeMode;
  }

  public toggleBeacon(): boolean {
    if (!this.capabilities.amberBeacon) {
      this.state.beaconOn = false;
      return false;
    }
    this.state.beaconOn = !this.state.beaconOn;
    return this.state.beaconOn;
  }

  public setCapabilities(
    capabilities: Readonly<BulldozerCapabilities>,
  ): void {
    this.capabilities = { ...capabilities };
    if (!this.capabilities.adjustableWingPlow) {
      this.state.bladeMode = 'STRAIGHT';
    }
    if (!this.capabilities.amberBeacon) this.state.beaconOn = false;
  }

  public importState(saved: unknown): boolean {
    if (!saved || typeof saved !== 'object') return false;
    const candidate = saved as Partial<BulldozerSaveData>;
    if (
      (candidate.version !== 1 &&
        candidate.version !== 2 &&
        candidate.version !== 3 &&
        candidate.version !== 4) ||
      !Number.isFinite(candidate.x) ||
      !Number.isFinite(candidate.z) ||
      !Number.isFinite(candidate.heading) ||
      !isBorealisLand(candidate.x!, candidate.z!)
    ) {
      return false;
    }
    this.state.x = candidate.x!;
    this.state.z = candidate.z!;
    this.state.heading = candidate.heading!;
    this.state.speed = 0;
    this.setBladePosition(
      candidate.version >= 2 &&
        Number.isFinite(candidate.bladePosition)
        ? candidate.bladePosition!
        : 0,
    );
    this.state.bladeMode =
      candidate.version >= 2 &&
      (candidate.bladeMode === 'STRAIGHT' ||
        candidate.bladeMode === 'SCOOP' ||
        candidate.bladeMode === 'V_PLOW')
        ? candidate.bladeMode
        : 'STRAIGHT';
    this.state.beaconOn =
      candidate.version >= 3 && candidate.beaconOn === true;
    this.state.attachment =
      candidate.version >= 4 && candidate.attachment === 'BUCKET'
        ? 'BUCKET'
        : 'PLOW';
    this.state.bucketTilt =
      candidate.version >= 4 && Number.isFinite(candidate.bucketTilt)
        ? clamp(candidate.bucketTilt!, 0, 1)
        : 0.82;
    this.state.bucketMass =
      candidate.version >= 4 && Number.isFinite(candidate.bucketMass)
        ? clamp(candidate.bucketMass!, 0, 0.72)
        : 0;
    this.state.bladeAngle =
      candidate.version >= 4 && Number.isFinite(candidate.bladeAngle)
        ? clamp(candidate.bladeAngle!, -1, 1)
        : 0;
    this.state.bladeLoad = 0;
    this.state.tractionSlip = 0;
    return true;
  }

  public exportState(): BulldozerSaveData {
    return {
      version: 4,
      x: this.state.x,
      z: this.state.z,
      heading: this.state.heading,
      bladePosition: this.state.bladePosition,
      bladeAngle: this.state.bladeAngle,
      bladeMode: this.state.bladeMode,
      beaconOn: this.state.beaconOn,
      attachment: this.state.attachment,
      bucketTilt: this.state.bucketTilt,
      bucketMass: this.state.bucketMass,
    };
  }

  private trackConfiguration(): LandSnowTrackConfiguration {
    if (this.capabilities.heavyChassis) {
      return {
        halfWidth: this.capabilities.wideTracks ? 0.88 : 0.78,
        radius: this.capabilities.wideTracks ? 0.5 : 0.43,
        compression: this.capabilities.wideTracks ? 1.48 : 1.34,
      };
    }
    return this.capabilities.wideTracks
      ? {
          halfWidth: this.capabilities.chainTracks ? 0.69 : 0.66,
          radius: this.capabilities.chainTracks ? 0.43 : 0.4,
          compression: this.capabilities.chainTracks ? 1.34 : 1.22,
        }
      : { halfWidth: 0.57, radius: 0.31, compression: 1 };
  }
}
