import { clamp } from '../utils/math';

const STICK_DEAD_ZONE = 0.14;

export const getPrimaryGamepad = (): Gamepad | undefined => {
  try {
    if (
      typeof navigator === 'undefined' ||
      typeof navigator.getGamepads !== 'function'
    ) {
      return undefined;
    }
    const pads = navigator.getGamepads();
    return (
      [...pads].find(
        (pad): pad is Gamepad =>
          pad !== null && pad.connected && pad.mapping === 'standard',
      ) ??
      [...pads].find(
        (pad): pad is Gamepad => pad !== null && pad.connected,
      )
    );
  } catch {
    return undefined;
  }
};

export const gamepadButtonValue = (
  gamepad: Readonly<Gamepad> | undefined,
  index: number,
): number => {
  const button = gamepad?.buttons[index];
  return button
    ? clamp(Math.max(button.value, button.pressed ? 1 : 0), 0, 1)
    : 0;
};

export const gamepadButtonPressed = (
  gamepad: Readonly<Gamepad> | undefined,
  index: number,
): boolean => gamepadButtonValue(gamepad, index) > 0.5;

export const gamepadAxis = (
  gamepad: Readonly<Gamepad> | undefined,
  index: number,
): number => {
  const raw = clamp(gamepad?.axes[index] ?? 0, -1, 1);
  const magnitude = Math.abs(raw);
  if (magnitude <= STICK_DEAD_ZONE) return 0;
  return (
    Math.sign(raw) *
    (magnitude - STICK_DEAD_ZONE) /
    (1 - STICK_DEAD_ZONE)
  );
};
