import {
  serverTick,
  type ServerTick,
} from '../core/NetworkPrimitives';

export type BaselineStreamDomain = 'SNOW' | 'ICE';

export interface BaselineStreamManifestEntry {
  readonly key: string;
  readonly revision: number;
  readonly topologyRevision?: number;
  readonly checksum: string;
}

export interface BaselineStreamManifestPayload {
  readonly version: 1;
  readonly kind: 'BASELINE_STREAM_MANIFEST';
  readonly domain: BaselineStreamDomain;
  readonly scope: string;
  readonly transferId: string;
  readonly interestRevision: number;
  readonly serverTick: ServerTick;
  readonly partCount: number;
  readonly entries: readonly BaselineStreamManifestEntry[];
  readonly manifestChecksum: string;
}

export interface BaselineStreamCompletePayload {
  readonly version: 1;
  readonly kind: 'BASELINE_STREAM_COMPLETE';
  readonly domain: BaselineStreamDomain;
  readonly transferId: string;
  readonly interestRevision: number;
  readonly manifestChecksum: string;
  readonly serverTick: ServerTick;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const boundedText = (value: unknown, maximum: number): value is string =>
  typeof value === 'string' && value.length > 0 && value.length <= maximum;
const natural = (value: unknown, maximum = Number.MAX_SAFE_INTEGER): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) &&
  value >= 0 && value <= maximum;
const isDomain = (value: unknown): value is BaselineStreamDomain =>
  value === 'SNOW' || value === 'ICE';

const appendText = (initial: number, value: string): number => {
  let hash = initial;
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    hash ^= code & 0xff;
    hash = Math.imul(hash, 0x01000193) >>> 0;
    hash ^= code >>> 8;
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash;
};

export const canonicalBaselineManifestEntries = (
  entries: readonly Readonly<BaselineStreamManifestEntry>[],
): readonly BaselineStreamManifestEntry[] => [...entries]
  .map((entry) => ({
    key: entry.key,
    revision: entry.revision,
    ...(entry.topologyRevision === undefined
      ? {}
      : { topologyRevision: entry.topologyRevision }),
    checksum: entry.checksum,
  }))
  .sort((left, right) => left.key.localeCompare(right.key));

export const baselineStreamManifestChecksum = (
  input: Readonly<Omit<BaselineStreamManifestPayload, 'manifestChecksum'>>,
): string => {
  let hash = 0x811c9dc5;
  for (const value of [
    input.domain,
    input.scope,
    input.transferId,
    String(input.interestRevision),
    String(input.serverTick),
    String(input.partCount),
  ]) hash = appendText(hash, value);
  for (const entry of canonicalBaselineManifestEntries(input.entries)) {
    for (const value of [
      entry.key,
      String(entry.revision),
      String(entry.topologyRevision ?? -1),
      entry.checksum,
    ]) hash = appendText(hash, value);
  }
  return hash.toString(16).padStart(8, '0');
};

export const createBaselineStreamManifest = (
  input: Readonly<Omit<
    BaselineStreamManifestPayload,
    'version' | 'kind' | 'manifestChecksum' | 'entries'
  >> & Readonly<{ entries: readonly Readonly<BaselineStreamManifestEntry>[] }>,
): BaselineStreamManifestPayload => {
  const base = {
    version: 1 as const,
    kind: 'BASELINE_STREAM_MANIFEST' as const,
    domain: input.domain,
    scope: input.scope,
    transferId: input.transferId,
    interestRevision: input.interestRevision,
    serverTick: input.serverTick,
    partCount: input.partCount,
    entries: canonicalBaselineManifestEntries(input.entries),
  };
  return {
    ...base,
    manifestChecksum: baselineStreamManifestChecksum(base),
  };
};

const validateEntry = (
  value: unknown,
): BaselineStreamManifestEntry | undefined => {
  if (!isRecord(value) ||
    !boundedText(value.key, 160) ||
    !natural(value.revision) ||
    !boundedText(value.checksum, 128) ||
    (value.topologyRevision !== undefined &&
      !natural(value.topologyRevision))) return undefined;
  return {
    key: value.key,
    revision: value.revision,
    ...(value.topologyRevision === undefined
      ? {}
      : { topologyRevision: value.topologyRevision as number }),
    checksum: value.checksum,
  };
};

export const validateBaselineStreamManifestPayload = (
  input: unknown,
): BaselineStreamManifestPayload | undefined => {
  if (!isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'BASELINE_STREAM_MANIFEST' ||
    !isDomain(input.domain) ||
    !boundedText(input.scope, 48) ||
    !boundedText(input.transferId, 160) ||
    !natural(input.interestRevision) ||
    !natural(input.serverTick) ||
    !natural(input.partCount, 256) ||
    input.partCount < 1 ||
    !Array.isArray(input.entries) ||
    input.entries.length > 256 ||
    !boundedText(input.manifestChecksum, 128)) return undefined;
  const entries = input.entries.map(validateEntry);
  if (entries.some((entry) => !entry)) return undefined;
  const canonical = canonicalBaselineManifestEntries(
    entries as BaselineStreamManifestEntry[],
  );
  if (new Set(canonical.map((entry) => entry.key)).size !== canonical.length) {
    return undefined;
  }
  const manifest: BaselineStreamManifestPayload = {
    version: 1,
    kind: 'BASELINE_STREAM_MANIFEST',
    domain: input.domain,
    scope: input.scope,
    transferId: input.transferId,
    interestRevision: input.interestRevision,
    serverTick: serverTick(input.serverTick),
    partCount: input.partCount,
    entries: canonical,
    manifestChecksum: input.manifestChecksum,
  };
  return baselineStreamManifestChecksum(manifest) === manifest.manifestChecksum
    ? manifest
    : undefined;
};

export const createBaselineStreamComplete = (
  manifest: Readonly<BaselineStreamManifestPayload>,
  completionTick: ServerTick,
): BaselineStreamCompletePayload => ({
  version: 1,
  kind: 'BASELINE_STREAM_COMPLETE',
  domain: manifest.domain,
  transferId: manifest.transferId,
  interestRevision: manifest.interestRevision,
  manifestChecksum: manifest.manifestChecksum,
  serverTick: completionTick,
});

export const validateBaselineStreamCompletePayload = (
  input: unknown,
): BaselineStreamCompletePayload | undefined => {
  if (!isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'BASELINE_STREAM_COMPLETE' ||
    !isDomain(input.domain) ||
    !boundedText(input.transferId, 160) ||
    !natural(input.interestRevision) ||
    !boundedText(input.manifestChecksum, 128) ||
    !natural(input.serverTick)) return undefined;
  return {
    version: 1,
    kind: 'BASELINE_STREAM_COMPLETE',
    domain: input.domain,
    transferId: input.transferId,
    interestRevision: input.interestRevision,
    manifestChecksum: input.manifestChecksum,
    serverTick: serverTick(input.serverTick),
  };
};
