const ROOF_SNOW_VOLUME_FACTOR = 0.72;

const stableUnitForId = (id: string): number => {
  let hash = 2166136261;
  for (let index = 0; index < id.length; index += 1) {
    hash ^= id.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0) / 0xffffffff;
};

const roofSnowVisualBucket = (depth: number): number =>
  Math.floor(Math.max(0, depth) / ROOF_SNOW_VISUAL_STEP);

const chunkKey = (chunk: Readonly<RuntimeWorldChunkDescriptor>): string =>
  `${chunk.address.x},${chunk.address.z}`;

const facadeFrame = (building: Readonly<BorealisTownBuildingLot>) => {
  const normal = borealisBuildingFrontVector(building.front);
  const tangent = { x: normal.z, z: -normal.x };
  const halfExtent = Math.abs(normal.x) > 0
    ? building.width * 0.5
    : building.depth * 0.5;
  const rotationY = Math.atan2(normal.x, normal.z);
  return {
    normal,
    tangent,
    halfExtent,
    rotationY,
    point: (side: number, outward: number) => ({
      x: building.x + tangent.x * side + normal.x * (halfExtent + outward),
      z: building.z + tangent.z * side + normal.z * (halfExtent + outward),
    }),
  };
};

