    this.root.add(this.resourceRoot);
    this.createCropPresentations();
    this.root.add(this.cropRoot);
    this.createCultivationPresentations();
    this.root.add(this.cultivationRoot);
    this.createAnimalPresentations();
    this.root.add(this.animalRoot);
    this.foliageMaterial.onBeforeCompile = (shader) => {
      shader.uniforms.uIcewayWindTime = { value: this.windTime };
      shader.uniforms.uIcewayWindDirection = { value: [this.windX, this.windZ] };
      shader.uniforms.uIcewayWindStrength = { value: this.windStrength };
      shader.vertexShader = shader.vertexShader.replace(
        '#include <common>',
        `#include <common>
uniform float uIcewayWindTime;
uniform vec2 uIcewayWindDirection;
uniform float uIcewayWindStrength;`,
      ).replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
float icewayTownWindPhase = uIcewayWindTime * 1.18 +
  position.y * 1.55 + position.x * 0.49 + position.z * 0.31;
float icewayTownWindPulse = sin(icewayTownWindPhase) * 0.7 +
  sin(icewayTownWindPhase * 0.41 + 2.1) * 0.3;
float icewayTownWindHeight = smoothstep(-0.45, 0.86, position.y);
vec2 icewayTownWindOffset = uIcewayWindDirection * icewayTownWindPulse *
  uIcewayWindStrength * icewayTownWindHeight * 0.09;
transformed.x += icewayTownWindOffset.x;
transformed.z += icewayTownWindOffset.y;`,
      );
      this.foliageMaterial.userData.icewayWindShader = shader;
    };
    this.foliageMaterial.customProgramCacheKey = () => 'iceway-town-wind-v1';
    this.lawnMaterial.onBeforeCompile = (shader) => {
      shader.uniforms.uIcewayWindTime = { value: this.windTime };
      shader.uniforms.uIcewayWindDirection = { value: [this.windX, this.windZ] };
      shader.uniforms.uIcewayWindStrength = { value: this.windStrength };
      shader.vertexShader = shader.vertexShader.replace(
        '#include <common>',
        `#include <common>
uniform float uIcewayWindTime;
uniform vec2 uIcewayWindDirection;
uniform float uIcewayWindStrength;`,
      ).replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
float icewayGrassWave = sin(uIcewayWindTime * 1.45 +
  position.x * 1.7 + position.z * 1.13) * 0.72 +
  sin(uIcewayWindTime * 0.57 + position.x * 0.38) * 0.28;
float icewayGrassRootWeight = smoothstep(-0.48, 0.5, position.y);
vec2 icewayGrassOffset = uIcewayWindDirection * icewayGrassWave *
  uIcewayWindStrength * icewayGrassRootWeight * 0.065;
transformed.x += icewayGrassOffset.x;
transformed.z += icewayGrassOffset.y;`,
      );
      this.lawnMaterial.userData.icewayWindShader = shader;
    };
    this.lawnMaterial.customProgramCacheKey = () => 'iceway-grass-wind-v1';
