import { clamp } from '../utils/math';

export type SavedIceBond = [
  axis: 0 | 1,
  index: number,
  damageByte: number,
];

const BOND_DAMAGE_VISUAL_STEPS = 12;

export const getBondDamageVisualBand = (
  damage: number,
): number =>
  Math.floor(
    clamp(damage, 0, 1) * BOND_DAMAGE_VISUAL_STEPS,
  );

export class IceBondGrid {
  private readonly horizontal: Float32Array;
  private readonly vertical: Float32Array;

  public constructor(
    private readonly columns: number,
    private readonly rows: number,
  ) {
    this.horizontal = new Float32Array(
      Math.max(0, columns - 1) * rows,
    );
    this.vertical = new Float32Array(
      columns * Math.max(0, rows - 1),
    );
  }

  public getDamage(
    columnA: number,
    rowA: number,
    columnB: number,
    rowB: number,
  ): number {
    const bond = this.locate(
      columnA,
      rowA,
      columnB,
      rowB,
    );
    return bond ? bond.array[bond.index] ?? 0 : 0;
  }

  public damage(
    columnA: number,
    rowA: number,
    columnB: number,
    rowB: number,
    amount: number,
  ): number {
    const bond = this.locate(
      columnA,
      rowA,
      columnB,
      rowB,
    );
    if (!bond) return 1;
    const next = clamp(
      (bond.array[bond.index] ?? 0) + Math.max(0, amount),
      0,
      1,
    );
    bond.array[bond.index] = next;
    return next;
  }

  public setDamage(
    columnA: number,
    rowA: number,
    columnB: number,
    rowB: number,
    damage: number,
  ): number {
    const bond = this.locate(
      columnA,
      rowA,
      columnB,
      rowB,
    );
    if (!bond) return 0;
    const next = clamp(damage, 0, 1);
    bond.array[bond.index] = next;
    return next;
  }

  public repair(
    columnA: number,
    rowA: number,
    columnB: number,
    rowB: number,
    amount: number,
  ): number {
    const bond = this.locate(
      columnA,
      rowA,
      columnB,
      rowB,
    );
    if (!bond) return 0;
    const next = Math.max(
      0,
      (bond.array[bond.index] ?? 0) - Math.max(0, amount),
    );
    bond.array[bond.index] = next;
    return next;
  }

  public maximumDamageAround(
    column: number,
    row: number,
  ): number {
    return Math.max(
      this.getDamage(column, row, column - 1, row),
      this.getDamage(column, row, column + 1, row),
      this.getDamage(column, row, column, row - 1),
      this.getDamage(column, row, column, row + 1),
    );
  }

  public heal(
    amount: number,
    canHeal: (
      columnA: number,
      rowA: number,
      columnB: number,
      rowB: number,
    ) => boolean,
    onHealed?: (
      columnA: number,
      rowA: number,
      columnB: number,
      rowB: number,
      previous: number,
      next: number,
    ) => void,
  ): number {
    let maximumChange = 0;
    const healArray = (
      array: Float32Array,
      axis: 0 | 1,
    ): void => {
      for (let index = 0; index < array.length; index += 1) {
        const previous = array[index] ?? 0;
        if (previous <= 0) continue;
        const coordinates = this.coordinates(axis, index);
        if (!canHeal(...coordinates)) continue;
        const next = Math.max(0, previous - amount);
        array[index] = next;
        if (next !== previous) {
          onHealed?.(...coordinates, previous, next);
        }
        maximumChange = Math.max(
          maximumChange,
          previous - next,
        );
      }
    };
    healArray(this.horizontal, 0);
    healArray(this.vertical, 1);
    return maximumChange;
  }

  public exportSparse(): SavedIceBond[] {
    const result: SavedIceBond[] = [];
    const append = (
      array: Float32Array,
      axis: 0 | 1,
    ): void => {
      for (let index = 0; index < array.length; index += 1) {
        const damage = array[index] ?? 0;
        if (damage < 0.004) continue;
        result.push([
          axis,
          index,
          Math.round(clamp(damage, 0, 1) * 255),
        ]);
      }
    };
    append(this.horizontal, 0);
    append(this.vertical, 1);
    return result;
  }

  public importSparse(saved: readonly SavedIceBond[]): void {
    this.clear();
    for (const entry of saved) {
      if (
        !Array.isArray(entry) ||
        entry.length !== 3 ||
        (entry[0] !== 0 && entry[0] !== 1) ||
        !Number.isInteger(entry[1]) ||
        !Number.isFinite(entry[2])
      ) {
        continue;
      }
      const array =
        entry[0] === 0 ? this.horizontal : this.vertical;
      if (entry[1] < 0 || entry[1] >= array.length) continue;
      array[entry[1]] = clamp(entry[2], 0, 255) / 255;
    }
  }

  public clear(): void {
    this.horizontal.fill(0);
    this.vertical.fill(0);
  }

  private locate(
    columnA: number,
    rowA: number,
    columnB: number,
    rowB: number,
  ): { array: Float32Array; index: number } | undefined {
    if (
      !this.inside(columnA, rowA) ||
      !this.inside(columnB, rowB)
    ) {
      return undefined;
    }
    if (rowA === rowB && Math.abs(columnA - columnB) === 1) {
      const column = Math.min(columnA, columnB);
      return {
        array: this.horizontal,
        index: rowA * (this.columns - 1) + column,
      };
    }
    if (
      columnA === columnB &&
      Math.abs(rowA - rowB) === 1
    ) {
      const row = Math.min(rowA, rowB);
      return {
        array: this.vertical,
        index: row * this.columns + columnA,
      };
    }
    return undefined;
  }

  private coordinates(
    axis: 0 | 1,
    index: number,
  ): [number, number, number, number] {
    if (axis === 0) {
      const width = this.columns - 1;
      const row = Math.floor(index / width);
      const column = index % width;
      return [column, row, column + 1, row];
    }
    const row = Math.floor(index / this.columns);
    const column = index % this.columns;
    return [column, row, column, row + 1];
  }

  private inside(column: number, row: number): boolean {
    return (
      column >= 0 &&
      row >= 0 &&
      column < this.columns &&
      row < this.rows
    );
  }
}
