import type { ProtocolVersion } from './ProtocolEnvelope';

export type DeploymentReleaseChannel = 'DEVELOPMENT' | 'CANARY' | 'STABLE';

export type CompatibilityRecoveryAction =
  | 'UPDATE_CLIENT'
  | 'RETRY_LATER'
  | 'CONTACT_HOST';

export interface SessionDeploymentPolicyPayload {
  readonly version: 1;
  readonly rolloutId: string;
  readonly releaseChannel: DeploymentReleaseChannel;
  readonly regionId: string;
  readonly nodeId: string;
  readonly minimumClientProtocol: ProtocolVersion;
  /** Empty means build selection is governed by requireExactBuild only. */
  readonly acceptedClientBuildIds: readonly string[];
  readonly updateUrl?: string;
  readonly supportUrl?: string;
}

export interface CompatibilityRejectionNoticePayload {
  readonly version: 1;
  readonly code: string;
  readonly message: string;
  readonly action: CompatibilityRecoveryAction;
  readonly retryable: boolean;
  readonly targetBuildId: string;
  readonly updateUrl?: string;
  readonly supportUrl?: string;
}

const RELEASE_CHANNELS = new Set<DeploymentReleaseChannel>([
  'DEVELOPMENT',
  'CANARY',
  'STABLE',
]);

const record = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

const text = (value: unknown, maximum: number): value is string =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maximum;

const optionalHttpUrl = (value: unknown): value is string | undefined => {
  if (value === undefined) return true;
  if (!text(value, 512)) return false;
  try {
    const url = new URL(value);
    return url.protocol === 'https:' || url.protocol === 'http:';
  } catch {
    return false;
  }
};

const protocol = (value: unknown): value is ProtocolVersion =>
  record(value) &&
  Number.isSafeInteger(value.major) &&
  Number.isSafeInteger(value.minor) &&
  (value.major as number) >= 0 &&
  (value.minor as number) >= 0;

const normalized = (values: readonly string[]): readonly string[] =>
  [...new Set(values)].sort();

export const validateSessionDeploymentPolicyPayload = (
  input: unknown,
): SessionDeploymentPolicyPayload | undefined => {
  if (
    !record(input) ||
    input.version !== 1 ||
    !text(input.rolloutId, 160) ||
    typeof input.releaseChannel !== 'string' ||
    !RELEASE_CHANNELS.has(input.releaseChannel as DeploymentReleaseChannel) ||
    !text(input.regionId, 96) ||
    !text(input.nodeId, 160) ||
    !protocol(input.minimumClientProtocol) ||
    !Array.isArray(input.acceptedClientBuildIds) ||
    input.acceptedClientBuildIds.length > 32 ||
    !input.acceptedClientBuildIds.every((value) => text(value, 160)) ||
    !optionalHttpUrl(input.updateUrl) ||
    !optionalHttpUrl(input.supportUrl)
  ) return undefined;

  return {
    version: 1,
    rolloutId: input.rolloutId,
    releaseChannel: input.releaseChannel as DeploymentReleaseChannel,
    regionId: input.regionId,
    nodeId: input.nodeId,
    minimumClientProtocol: {
      major: input.minimumClientProtocol.major as number,
      minor: input.minimumClientProtocol.minor as number,
    },
    acceptedClientBuildIds: normalized(input.acceptedClientBuildIds as string[]),
    ...(input.updateUrl === undefined ? {} : { updateUrl: input.updateUrl as string }),
    ...(input.supportUrl === undefined ? {} : { supportUrl: input.supportUrl as string }),
  };
};

export const createCompatibilityRejectionNotice = (
  reason: string,
  targetBuildId: string,
  deployment: Readonly<SessionDeploymentPolicyPayload>,
): CompatibilityRejectionNoticePayload => {
  const updateRequired = reason === 'PROTOCOL_MAJOR_MISMATCH' ||
    reason === 'CLIENT_PROTOCOL_TOO_OLD' ||
    reason === 'BUILD_MISMATCH' ||
    reason === 'WORLD_DATASET_MISMATCH' ||
    reason === 'DEFINITION_SET_MISMATCH' ||
    reason === 'CHECKPOINT_VERSION_MISMATCH' ||
    reason === 'MISSING_REQUIRED_CAPABILITY';
  const retryable = reason === 'CLIENT_PROTOCOL_TOO_NEW';
  const action: CompatibilityRecoveryAction = updateRequired
    ? 'UPDATE_CLIENT'
    : retryable
      ? 'RETRY_LATER'
      : 'CONTACT_HOST';
  const message = updateRequired
    ? 'This multiplayer room requires a newer compatible game version.'
    : retryable
      ? 'This multiplayer server has not been updated for your game version yet.'
      : 'The multiplayer room could not accept this client. Contact the room host.';
  return {
    version: 1,
    code: reason.slice(0, 160),
    message,
    action,
    retryable,
    targetBuildId,
    ...(deployment.updateUrl ? { updateUrl: deployment.updateUrl } : {}),
    ...(deployment.supportUrl ? { supportUrl: deployment.supportUrl } : {}),
  };
};

export const validateCompatibilityRejectionNotice = (
  input: unknown,
): CompatibilityRejectionNoticePayload | undefined => {
  if (
    !record(input) ||
    input.version !== 1 ||
    !text(input.code, 160) ||
    !text(input.message, 320) ||
    (input.action !== 'UPDATE_CLIENT' &&
      input.action !== 'RETRY_LATER' &&
      input.action !== 'CONTACT_HOST') ||
    typeof input.retryable !== 'boolean' ||
    !text(input.targetBuildId, 160) ||
    !optionalHttpUrl(input.updateUrl) ||
    !optionalHttpUrl(input.supportUrl)
  ) return undefined;
  return {
    version: 1,
    code: input.code,
    message: input.message,
    action: input.action,
    retryable: input.retryable,
    targetBuildId: input.targetBuildId,
    ...(input.updateUrl === undefined ? {} : { updateUrl: input.updateUrl as string }),
    ...(input.supportUrl === undefined ? {} : { supportUrl: input.supportUrl as string }),
  };
};
