import {
  cloneGlobalPosition,
  globalPositionFromAbsoluteMetres,
  globalPositionToAbsoluteMetres,
  type GlobalPosition,
} from '../../world/GlobalPosition';
import { ICEAWAY_TARGET_WORLD_PARTITION } from '../../world/WorldPartitionTypes';

export const emergentPositionDistance = (
  left: Readonly<GlobalPosition>,
  right: Readonly<GlobalPosition>,
): number => {
  const a = globalPositionToAbsoluteMetres(ICEAWAY_TARGET_WORLD_PARTITION, left);
  const b = globalPositionToAbsoluteMetres(ICEAWAY_TARGET_WORLD_PARTITION, right);
  return Math.hypot(b.xMetres - a.xMetres, b.yMetres - a.yMetres, b.zMetres - a.zMetres);
};

export const interpolateEmergentPosition = (
  left: Readonly<GlobalPosition>,
  right: Readonly<GlobalPosition>,
  progress: number,
): GlobalPosition => {
  const a = globalPositionToAbsoluteMetres(ICEAWAY_TARGET_WORLD_PARTITION, left);
  const b = globalPositionToAbsoluteMetres(ICEAWAY_TARGET_WORLD_PARTITION, right);
  const t = Math.max(0, Math.min(1, progress));
  return globalPositionFromAbsoluteMetres(ICEAWAY_TARGET_WORLD_PARTITION, {
    xMetres: a.xMetres + (b.xMetres - a.xMetres) * t,
    yMetres: a.yMetres + (b.yMetres - a.yMetres) * t,
    zMetres: a.zMetres + (b.zMetres - a.zMetres) * t,
  });
};

export const emergentPolylineLength = (
  points: readonly Readonly<GlobalPosition>[],
): number => {
  let result = 0;
  for (let index = 1; index < points.length; index += 1) {
    result += emergentPositionDistance(points[index - 1]!, points[index]!);
  }
  return result;
};

export const sampleEmergentPolyline = (
  points: readonly Readonly<GlobalPosition>[],
  progress: number,
): GlobalPosition => {
  if (points.length === 0) {
    return { chunk: { x: 0, z: 0 }, local: { xMetres: 0, yMetres: 0, zMetres: 0 } };
  }
  if (points.length === 1) return cloneGlobalPosition(points[0]!);
  const length = emergentPolylineLength(points);
  let remaining = Math.max(0, Math.min(1, progress)) * length;
  for (let index = 1; index < points.length; index += 1) {
    const from = points[index - 1]!;
    const to = points[index]!;
    const segmentLength = emergentPositionDistance(from, to);
    if (remaining <= segmentLength || index === points.length - 1) {
      return interpolateEmergentPosition(from, to, segmentLength > 0 ? remaining / segmentLength : 1);
    }
    remaining -= segmentLength;
  }
  return cloneGlobalPosition(points[points.length - 1]!);
};

