import type {
  PortDockDefinition,
  Vec3Like,
} from '../definitions/GameplayTypes';

export type DockingAvailability =
  | 'OUT_OF_RANGE'
  | 'TOO_FAST'
  | 'AVAILABLE'
  | 'DOCKED';

export interface DockingPortDefinition {
  id: string;
  displayName: string;
  shortName: string;
  dock: PortDockDefinition;
}

export interface DockingState {
  availability: DockingAvailability;
  portId?: string;
  portName?: string;
  distance?: number;
  maximumSpeed?: number;
}

export type DockingRequestFailure =
  | 'OUT_OF_RANGE'
  | 'TOO_FAST'
  | 'ALREADY_DOCKED';

export interface DockingRequestResult {
  success: boolean;
  portId?: string;
  reason?: DockingRequestFailure;
}

const OUT_OF_RANGE_STATE: DockingState = {
  availability: 'OUT_OF_RANGE',
};

export class DockingSystem {
  private readonly ports: readonly DockingPortDefinition[];
  private state: DockingState = OUT_OF_RANGE_STATE;
  private dockedPortId?: string;

  public constructor(ports: readonly DockingPortDefinition[]) {
    this.ports = ports;
  }

  public update(
    position: Readonly<Vec3Like>,
    speed: number,
  ): DockingState {
    if (this.dockedPortId) {
      const port = this.ports.find(
        (candidate) => candidate.id === this.dockedPortId,
      );
      this.state = {
        availability: 'DOCKED',
        portId: port?.id ?? this.dockedPortId,
        portName: port?.shortName ?? port?.displayName,
        distance: 0,
        maximumSpeed: port?.dock.maximumSpeed,
      };
      return this.getState();
    }

    let nearest:
      | {
          port: DockingPortDefinition;
          distance: number;
        }
      | undefined;
    for (const port of this.ports) {
      const distance = Math.hypot(
        position.x - port.dock.worldPosition.x,
        position.z - port.dock.worldPosition.z,
      );
      if (
        distance <= port.dock.radius &&
        (!nearest || distance < nearest.distance)
      ) {
        nearest = { port, distance };
      }
    }
    if (!nearest) {
      this.state = OUT_OF_RANGE_STATE;
      return this.getState();
    }

    this.state = {
      availability:
        Math.max(0, speed) <= nearest.port.dock.maximumSpeed
          ? 'AVAILABLE'
          : 'TOO_FAST',
      portId: nearest.port.id,
      portName:
        nearest.port.shortName || nearest.port.displayName,
      distance: nearest.distance,
      maximumSpeed: nearest.port.dock.maximumSpeed,
    };
    return this.getState();
  }

  public requestDock(): DockingRequestResult {
    if (this.dockedPortId) {
      return {
        success: false,
        portId: this.dockedPortId,
        reason: 'ALREADY_DOCKED',
      };
    }
    if (
      this.state.availability !== 'AVAILABLE' ||
      !this.state.portId
    ) {
      return {
        success: false,
        portId: this.state.portId,
        reason:
          this.state.availability === 'TOO_FAST'
            ? 'TOO_FAST'
            : 'OUT_OF_RANGE',
      };
    }
    this.dockedPortId = this.state.portId;
    this.state = {
      ...this.state,
      availability: 'DOCKED',
      distance: 0,
    };
    return {
      success: true,
      portId: this.dockedPortId,
    };
  }

  public undock(): string | undefined {
    const previousPortId = this.dockedPortId;
    this.dockedPortId = undefined;
    this.state = OUT_OF_RANGE_STATE;
    return previousPortId;
  }

  public isDocked(): boolean {
    return this.dockedPortId !== undefined;
  }

  public getDockedPortId(): string | undefined {
    return this.dockedPortId;
  }

  public getState(): DockingState {
    return { ...this.state };
  }
}
