export const CONSTRUCTION_ASSET_SCHEMA_VERSION = 1 as const;

export type ConstructionAssetUnits =
  | 'metres'
  | 'centimetres'
  | 'millimetres'
  | 'inches';

export type ConstructionAssetAxis =
  | '+X'
  | '-X'
  | '+Y'
  | '-Y'
  | '+Z'
  | '-Z';

export interface ConstructionAssetAnimation {
  node: string;
  axis: 'x' | 'y' | 'z';
  speed: number;
}

export interface ConstructionAssetSocketContract {
  id: string;
  node: string;
}

export interface ConstructionAssetDecalContract {
  slotId: string;
  node: string;
}

export interface ConstructionAssetMaterialContract {
  sourceMaterial: string;
  mode: 'paint' | 'preserve';
}

export interface ConstructionAssetSidecar {
  schemaVersion: typeof CONSTRUCTION_ASSET_SCHEMA_VERSION;
  moduleId: string;
  source: string;
  units: ConstructionAssetUnits;
  upAxis: ConstructionAssetAxis;
  forwardAxis: ConstructionAssetAxis;
  normalization: 'embedded-dae' | 'sidecar';
  pivotNode?: string;
  replaceProcedural: boolean;
  visualNodes?: string[];
  collisionNodes?: string[];
  sockets: ConstructionAssetSocketContract[];
  decalSlots?: ConstructionAssetDecalContract[];
  materials?: ConstructionAssetMaterialContract[];
  animations?: ConstructionAssetAnimation[];
}

export interface ConstructionAssetManifestEntry
  extends ConstructionAssetSidecar {
  assetUrl: string;
  sidecarUrl: string;
}

export interface ConstructionAssetManifest {
  version: typeof CONSTRUCTION_ASSET_SCHEMA_VERSION;
  generatedAt: string;
  assets: ConstructionAssetManifestEntry[];
}

export interface ConstructionAssetValidation {
  accepted: boolean;
  errors: readonly string[];
  sidecar?: ConstructionAssetSidecar;
}

const units = new Set<ConstructionAssetUnits>([
  'metres',
  'centimetres',
  'millimetres',
  'inches',
]);
const axes = new Set<ConstructionAssetAxis>([
  '+X',
  '-X',
  '+Y',
  '-Y',
  '+Z',
  '-Z',
]);

export const constructionUnitsToMetres = (
  value: ConstructionAssetUnits,
): number => {
  if (value === 'centimetres') return 0.01;
  if (value === 'millimetres') return 0.001;
  if (value === 'inches') return 0.0254;
  return 1;
};

const namedNodeArray = (
  value: unknown,
  label: string,
  errors: string[],
): string[] | undefined => {
  if (value === undefined) return undefined;
  if (
    !Array.isArray(value) ||
    value.some((node) => typeof node !== 'string' || node.length === 0)
  ) {
    errors.push(`${label} must be an array of non-empty node names.`);
    return undefined;
  }
  return [...new Set(value)];
};

export const validateConstructionAssetSidecar = (
  value: unknown,
): ConstructionAssetValidation => {
  const errors: string[] = [];
  if (!value || typeof value !== 'object') {
    return { accepted: false, errors: ['Sidecar must be a JSON object.'] };
  }
  const candidate = value as Partial<ConstructionAssetSidecar>;
  if (candidate.schemaVersion !== CONSTRUCTION_ASSET_SCHEMA_VERSION) {
    errors.push(`schemaVersion must be ${CONSTRUCTION_ASSET_SCHEMA_VERSION}.`);
  }
  if (typeof candidate.moduleId !== 'string' || candidate.moduleId.length === 0) {
    errors.push('moduleId is required.');
  }
  if (
    typeof candidate.source !== 'string' ||
    !candidate.source.toLowerCase().endsWith('.dae')
  ) {
    errors.push('source must point to a .dae file.');
  } else if (
    candidate.source.startsWith('/') ||
    candidate.source.includes('..') ||
    /^[a-z]+:/i.test(candidate.source)
  ) {
    errors.push('source must be a safe path relative to its sidecar.');
  }
  if (!units.has(candidate.units as ConstructionAssetUnits)) {
    errors.push('units must be metres, centimetres, millimetres or inches.');
  }
  if (!axes.has(candidate.upAxis as ConstructionAssetAxis)) {
    errors.push('upAxis is invalid.');
  }
  if (!axes.has(candidate.forwardAxis as ConstructionAssetAxis)) {
    errors.push('forwardAxis is invalid.');
  }
  if (
    candidate.normalization !== 'embedded-dae' &&
    candidate.normalization !== 'sidecar'
  ) {
    errors.push('normalization must be embedded-dae or sidecar.');
  }
  if (
    typeof candidate.upAxis === 'string' &&
    typeof candidate.forwardAxis === 'string' &&
    candidate.upAxis.slice(1) === candidate.forwardAxis.slice(1)
  ) {
    errors.push('upAxis and forwardAxis must be perpendicular.');
  }
  if (typeof candidate.replaceProcedural !== 'boolean') {
    errors.push('replaceProcedural must be boolean.');
  }
  const visualNodes = namedNodeArray(
    candidate.visualNodes,
    'visualNodes',
    errors,
  );
  const collisionNodes = namedNodeArray(
    candidate.collisionNodes,
    'collisionNodes',
    errors,
  );
  const sockets: ConstructionAssetSocketContract[] = [];
  if (!Array.isArray(candidate.sockets)) {
    errors.push('sockets must be an array (empty is allowed).');
  } else {
    for (const socket of candidate.sockets) {
      if (
        !socket ||
        typeof socket.id !== 'string' ||
        socket.id.length === 0 ||
        typeof socket.node !== 'string' ||
        socket.node.length === 0
      ) {
        errors.push('Each socket needs non-empty id and node values.');
      } else {
        sockets.push({ id: socket.id, node: socket.node });
      }
    }
  }
  if (new Set(sockets.map((socket) => socket.id)).size !== sockets.length) {
    errors.push('Socket ids must be unique.');
  }
  const animations: ConstructionAssetAnimation[] = [];
  if (candidate.animations !== undefined) {
    if (!Array.isArray(candidate.animations)) {
      errors.push('animations must be an array.');
    } else {
      for (const animation of candidate.animations) {
        if (
          !animation ||
          typeof animation.node !== 'string' ||
          animation.node.length === 0 ||
          (animation.axis !== 'x' &&
            animation.axis !== 'y' &&
            animation.axis !== 'z') ||
          typeof animation.speed !== 'number' ||
          !Number.isFinite(animation.speed)
        ) {
          errors.push('Each animation needs node, x/y/z axis and finite speed.');
        } else {
          animations.push({ ...animation });
        }
      }
    }
  }
  const materials: ConstructionAssetMaterialContract[] = [];
  if (candidate.materials !== undefined) {
    if (!Array.isArray(candidate.materials)) {
      errors.push('materials must be an array.');
    } else {
      for (const material of candidate.materials) {
        if (
          !material ||
          typeof material.sourceMaterial !== 'string' ||
          material.sourceMaterial.length === 0 ||
          (material.mode !== 'paint' && material.mode !== 'preserve')
        ) {
          errors.push('Each material needs sourceMaterial and paint/preserve mode.');
        } else {
          materials.push({ ...material });
        }
      }
    }
  }
  const decalSlots: ConstructionAssetDecalContract[] = [];
  if (candidate.decalSlots !== undefined) {
    if (!Array.isArray(candidate.decalSlots)) {
      errors.push('decalSlots must be an array.');
    } else {
      for (const decal of candidate.decalSlots) {
        if (
          !decal ||
          typeof decal.slotId !== 'string' ||
          decal.slotId.length === 0 ||
          typeof decal.node !== 'string' ||
          decal.node.length === 0
        ) {
          errors.push('Each decal slot needs non-empty slotId and node values.');
        } else {
          decalSlots.push({ ...decal });
        }
      }
    }
  }
  if (errors.length > 0) return { accepted: false, errors };
  return {
    accepted: true,
    errors: [],
    sidecar: {
      schemaVersion: CONSTRUCTION_ASSET_SCHEMA_VERSION,
      moduleId: candidate.moduleId!,
      source: candidate.source!,
      units: candidate.units!,
      upAxis: candidate.upAxis!,
      forwardAxis: candidate.forwardAxis!,
      normalization: candidate.normalization!,
      pivotNode:
        typeof candidate.pivotNode === 'string' && candidate.pivotNode.length > 0
          ? candidate.pivotNode
          : undefined,
      replaceProcedural: candidate.replaceProcedural!,
      visualNodes,
      collisionNodes,
      sockets,
      decalSlots,
      materials,
      animations,
    },
  };
};

export const constructionAssetNodeConvention = {
  socket: 'SOCKET__<id>',
  collider: 'COLLIDER__<id>',
  animation: 'ANIM__<id>',
  decal: 'DECAL__<slot-id>',
  visual: 'MODEL__LOD0',
} as const;
