export type AssetBudgetClass =
  | 'SMALL_PROP'
  | 'STREET_PROP'
  | 'TREE'
  | 'BUILDING'
  | 'VEHICLE'
  | 'CHARACTER';

export interface AssetPerformanceFacts {
  readonly id: string;
  readonly budgetClass: AssetBudgetClass;
  readonly triangles: number;
  readonly materials: number;
  readonly texturePixels: number;
  readonly colliderPrimitives: number;
  readonly hasLods: boolean;
  readonly instancingEligible: boolean;
}

export interface AssetBudgetIssue {
  readonly severity: 'WARNING' | 'ERROR';
  readonly field: keyof AssetPerformanceFacts;
  readonly message: string;
}

export interface AssetBudgetInspection {
  readonly assetId: string;
  readonly score: 'GREEN' | 'AMBER' | 'RED';
  readonly issues: readonly AssetBudgetIssue[];
}

interface AssetBudgetLimits {
  readonly triangles: number;
  readonly materials: number;
  readonly texturePixels: number;
  readonly colliderPrimitives: number;
  readonly lodRequiredAboveTriangles: number;
}

const LIMITS: Readonly<Record<AssetBudgetClass, AssetBudgetLimits>> = {
  SMALL_PROP: {
    triangles: 1_000,
    materials: 2,
    texturePixels: 1024 ** 2,
    colliderPrimitives: 2,
    lodRequiredAboveTriangles: 800,
  },
  STREET_PROP: {
    triangles: 1_500,
    materials: 3,
    texturePixels: 1024 ** 2,
    colliderPrimitives: 3,
    lodRequiredAboveTriangles: 1_000,
  },
  TREE: {
    triangles: 2_000,
    materials: 3,
    texturePixels: 2048 ** 2,
    colliderPrimitives: 2,
    lodRequiredAboveTriangles: 1_000,
  },
  BUILDING: {
    triangles: 12_000,
    materials: 6,
    texturePixels: 4096 ** 2,
    colliderPrimitives: 12,
    lodRequiredAboveTriangles: 4_000,
  },
  VEHICLE: {
    triangles: 12_000,
    materials: 6,
    texturePixels: 4096 ** 2,
    colliderPrimitives: 12,
    lodRequiredAboveTriangles: 7_000,
  },
  CHARACTER: {
    triangles: 15_000,
    materials: 5,
    texturePixels: 4096 ** 2,
    colliderPrimitives: 4,
    lodRequiredAboveTriangles: 8_000,
  },
};

export const inspectAssetPerformanceBudget = (
  facts: Readonly<AssetPerformanceFacts>,
): AssetBudgetInspection => {
  const limits = LIMITS[facts.budgetClass];
  const issues: AssetBudgetIssue[] = [];
  const check = (
    field: keyof AssetPerformanceFacts,
    value: number,
    limit: number,
    label: string,
  ): void => {
    if (!Number.isFinite(value) || value < 0) {
      issues.push({ severity: 'ERROR', field, message: `${label} is invalid.` });
    } else if (value > limit) {
      issues.push({
        severity: value > limit * 1.5 ? 'ERROR' : 'WARNING',
        field,
        message: `${label} ${Math.round(value)} exceeds ${Math.round(limit)}.`,
      });
    }
  };
  check('triangles', facts.triangles, limits.triangles, 'Triangle count');
  check('materials', facts.materials, limits.materials, 'Material count');
  check('texturePixels', facts.texturePixels, limits.texturePixels, 'Texture pixels');
  check(
    'colliderPrimitives',
    facts.colliderPrimitives,
    limits.colliderPrimitives,
    'Collider primitive count',
  );
  if (facts.triangles > limits.lodRequiredAboveTriangles && !facts.hasLods) {
    issues.push({
      severity: 'WARNING',
      field: 'hasLods',
      message: 'LOD chain is recommended for this triangle count.',
    });
  }
  if ((facts.budgetClass === 'TREE' || facts.budgetClass === 'STREET_PROP') &&
    !facts.instancingEligible) {
    issues.push({
      severity: 'WARNING',
      field: 'instancingEligible',
      message: 'Repeated scenery should share geometry and material for instancing.',
    });
  }
  return Object.freeze({
    assetId: facts.id,
    score: issues.some((issue) => issue.severity === 'ERROR')
      ? 'RED'
      : issues.length > 0
        ? 'AMBER'
        : 'GREEN',
    issues: Object.freeze(issues),
  });
};
