export type WildernessSkillId =
  | 'GATHERING'
  | 'TOOL_USE'
  | 'FIRECRAFT'
  | 'COOKING'
  | 'SHELTERCRAFT'
  | 'BUILDING'
  | 'ICE_FISHING'
  | 'TRACKING'
  | 'TRAPPING'
  | 'WOODCRAFT'
  | 'LEATHERWORK'
  | 'RIVERCRAFT'
  | 'STONEWORK'
  | 'METALWORK';

export type WildernessMilestoneId =
  | 'FIRST_GATHERING'
  | 'FIRST_EMBER'
  | 'FIRST_TREE'
  | 'SAFE_FIRST_NIGHT'
  | 'UNDER_THE_ICE'
  | 'FIRST_HOT_MEAL'
  | 'READ_THE_WINTER'
  | 'FIRST_HIDE'
  | 'CAMP_BECOMES_HOME'
  | 'MOVING_WATER'
  | 'PATIENT_HUNTER'
  | 'OLD_PLACES';

export type WildernessRecipeCategory =
  | 'FIELDCRAFT'
  | 'FIRECRAFT'
  | 'COOKING'
  | 'WOODCRAFT'
  | 'LEATHERWORK'
  | 'FISHING'
  | 'BUILDING'
  | 'STONE_AND_METAL';

export interface WildernessSkillDefinition {
  readonly id: WildernessSkillId;
  readonly name: string;
  readonly description: string;
  readonly initiallyUnlocked?: boolean;
  readonly unlockedBy?: WildernessMilestoneId;
}

export interface WildernessMilestoneDefinition {
  readonly id: WildernessMilestoneId;
  readonly name: string;
  readonly description: string;
  readonly unlocks: readonly WildernessSkillId[];
}

export interface WildernessRecipeIngredient {
  readonly itemId: string;
  readonly amount: number;
}

export interface WildernessRecipeDefinition {
  readonly id: string;
  readonly name: string;
  readonly category: WildernessRecipeCategory;
  readonly skill: WildernessSkillId;
  readonly station: string;
  readonly ingredients: readonly WildernessRecipeIngredient[];
  readonly durationSeconds: number;
  readonly outputId: string;
  readonly outputAmount: number;
  readonly description: string;
  readonly future?: boolean;
}

export interface WildernessFoodDefinition {
  readonly id: string;
  readonly name: string;
  readonly satiety: number;
  readonly energy: number;
  readonly warmth: number;
  readonly bonus?: string;
  readonly durationSeconds?: number;
}

export interface WildernessProgressionState {
  readonly unlockedSkills: WildernessSkillId[];
  readonly completedMilestones: WildernessMilestoneId[];
  readonly actionCounts: Record<string, number>;
}

