import type { RadioMessage } from '../gameplay/radio/RadioSystem';
import type { RadioNetworkRegistry } from '../gameplay/radio/RadioNetworkRegistry';

export interface RadioVoiceAssetDefinition {
  id: string;
  url: string;
  durationSeconds: number;
}

export const V1_RADIO_VOICE_ASSETS:
  readonly RadioVoiceAssetDefinition[] = Object.freeze([]);

export type RadioVoicePlaybackPlan =
  | {
      mode: 'AUDIO';
      messageId: string;
      assetId: string;
      url: string;
      pitchSemitones: number;
      playbackRate: number;
      eqProfileId: string;
      radioNoiseProfileId: string;
      compressionProfileId: string;
    }
  | {
      mode: 'TEXT_ONLY';
      messageId: string;
      reason:
        | 'NO_VOICE_PROFILE'
        | 'MISSING_ASSET_METADATA'
        | 'MISSING_ASSET';
    };

export interface RadioVoiceProductionStatus {
  audioReadyProfiles: readonly string[];
  textOnlyProfiles: readonly string[];
  missingAssetIds: readonly string[];
}

export class RadioVoiceSystem {
  private readonly assets = new Map<
    string,
    Readonly<RadioVoiceAssetDefinition>
  >();

  public constructor(
    private readonly network: RadioNetworkRegistry,
    assets: readonly RadioVoiceAssetDefinition[] =
      V1_RADIO_VOICE_ASSETS,
  ) {
    for (const asset of assets) {
      if (
        !asset.id.trim() ||
        !asset.url.trim() ||
        !Number.isFinite(asset.durationSeconds) ||
        asset.durationSeconds <= 0 ||
        this.assets.has(asset.id)
      ) {
        throw new Error(
          `Invalid radio voice asset "${asset.id}"`,
        );
      }
      this.assets.set(asset.id, Object.freeze({ ...asset }));
    }
  }

  public createPlaybackPlan(
    message: Readonly<RadioMessage>,
  ): RadioVoicePlaybackPlan {
    if (!message.voiceProfileId) {
      return {
        mode: 'TEXT_ONLY',
        messageId: message.id,
        reason: 'NO_VOICE_PROFILE',
      };
    }
    const profile = this.network.getVoiceProfile(
      message.voiceProfileId,
    );
    if (!profile?.baseVoiceAssetId) {
      return {
        mode: 'TEXT_ONLY',
        messageId: message.id,
        reason: 'MISSING_ASSET_METADATA',
      };
    }
    const asset = this.assets.get(profile.baseVoiceAssetId);
    if (!asset) {
      return {
        mode: 'TEXT_ONLY',
        messageId: message.id,
        reason: 'MISSING_ASSET',
      };
    }
    return {
      mode: 'AUDIO',
      messageId: message.id,
      assetId: asset.id,
      url: asset.url,
      pitchSemitones: profile.pitchSemitones,
      playbackRate: profile.playbackRate,
      eqProfileId: profile.eqProfileId,
      radioNoiseProfileId: profile.radioNoiseProfileId,
      compressionProfileId:
        profile.compressionProfileId,
    };
  }

  public getProductionStatus():
    RadioVoiceProductionStatus {
    const audioReadyProfiles: string[] = [];
    const textOnlyProfiles: string[] = [];
    const missingAssetIds = new Set<string>();
    for (const profile of (
      this.network.definitions.voiceProfiles
    )) {
      if (
        profile.baseVoiceAssetId &&
        this.assets.has(profile.baseVoiceAssetId)
      ) {
        audioReadyProfiles.push(profile.id);
      } else {
        textOnlyProfiles.push(profile.id);
        if (profile.baseVoiceAssetId) {
          missingAssetIds.add(profile.baseVoiceAssetId);
        }
      }
    }
    return {
      audioReadyProfiles: audioReadyProfiles.sort(),
      textOnlyProfiles: textOnlyProfiles.sort(),
      missingAssetIds: [...missingAssetIds].sort(),
    };
  }
}
