import {
  DataTexture,
  LinearFilter,
  RGBAFormat,
  RepeatWrapping,
  UnsignedByteType,
} from 'three';
import { clamp, hash2D } from '../utils/math';

export const OCEAN_VORONOI_TEXTURE_SIZE = 256;

interface VoronoiSample {
  tone: number;
  interior: number;
}

const wrapCell = (value: number, cellCount: number): number =>
  ((value % cellCount) + cellCount) % cellCount;

const samplePeriodicVoronoi = (
  u: number,
  v: number,
  cellCount: number,
  seed: number,
): VoronoiSample => {
  const pointX = u * cellCount;
  const pointY = v * cellCount;
  const baseX = Math.floor(pointX);
  const baseY = Math.floor(pointY);
  let nearestDistance = Number.POSITIVE_INFINITY;
  let secondDistance = Number.POSITIVE_INFINITY;
  let nearestWrappedX = 0;
  let nearestWrappedY = 0;

  for (let offsetY = -1; offsetY <= 1; offsetY += 1) {
    for (let offsetX = -1; offsetX <= 1; offsetX += 1) {
      const cellX = baseX + offsetX;
      const cellY = baseY + offsetY;
      const wrappedX = wrapCell(cellX, cellCount);
      const wrappedY = wrapCell(cellY, cellCount);
      const featureX =
        cellX + 0.14 + hash2D(wrappedX, wrappedY, seed) * 0.72;
      const featureY =
        cellY +
        0.14 +
        hash2D(wrappedX, wrappedY, seed + 1) * 0.72;
      const deltaX = featureX - pointX;
      const deltaY = featureY - pointY;
      const distance = deltaX * deltaX + deltaY * deltaY;

      if (distance < nearestDistance) {
        secondDistance = nearestDistance;
        nearestDistance = distance;
        nearestWrappedX = wrappedX;
        nearestWrappedY = wrappedY;
      } else if (distance < secondDistance) {
        secondDistance = distance;
      }
    }
  }

  const edgeGap =
    Math.sqrt(secondDistance) - Math.sqrt(nearestDistance);
  return {
    tone: hash2D(nearestWrappedX, nearestWrappedY, seed + 2),
    interior: clamp(edgeGap * 1.42, 0, 1),
  };
};

export const generateOceanVoronoiData = (
  size = OCEAN_VORONOI_TEXTURE_SIZE,
): Uint8Array => {
  const safeSize = Math.max(2, Math.floor(size));
  const data = new Uint8Array(safeSize * safeSize * 4);

  for (let y = 0; y < safeSize; y += 1) {
    for (let x = 0; x < safeSize; x += 1) {
      const u = (x + 0.5) / safeSize;
      const v = (y + 0.5) / safeSize;
      const lower = samplePeriodicVoronoi(u, v, 7, 481);
      const surface = samplePeriodicVoronoi(u, v, 13, 947);
      const offset = (y * safeSize + x) * 4;

      data[offset] = Math.round(lower.tone * 255);
      data[offset + 1] = Math.round(lower.interior * 255);
      data[offset + 2] = Math.round(surface.tone * 255);
      data[offset + 3] = Math.round(surface.interior * 255);
    }
  }

  return data;
};

export const createOceanVoronoiTexture = (): DataTexture => {
  const texture = new DataTexture(
    generateOceanVoronoiData(),
    OCEAN_VORONOI_TEXTURE_SIZE,
    OCEAN_VORONOI_TEXTURE_SIZE,
    RGBAFormat,
    UnsignedByteType,
  );
  texture.name = 'Ocean V2 deterministic Voronoi fields';
  texture.wrapS = RepeatWrapping;
  texture.wrapT = RepeatWrapping;
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  texture.generateMipmaps = false;
  texture.needsUpdate = true;
  return texture;
};
