import type {
  GameplayRegistry,
  GameplayRegistryIssue,
} from '../definitions/GameplayRegistry';
import type { WorldOperationalEvent } from '../events/WorldDomainEvent';
import {
  validateWorldTargetRef,
  type WorldTargetRef,
} from '../world/WorldTarget';

export interface WorldOutcomeDefinition {
  id: string;
  allowedStates: readonly string[];
  initialState: string;
  terminalStates?: readonly string[];
  target?: WorldTargetRef;
}

export interface WorldOutcomeRuntimeState {
  outcomeId: string;
  state: string;
  changedAt: number;
  sourceEventId?: string;
}

export interface WorldOutcomeSaveData {
  version: 1;
  outcomes: WorldOutcomeRuntimeState[];
}

export type WorldOutcomeTransitionFailure =
  | 'UNKNOWN_OUTCOME'
  | 'INVALID_STATE'
  | 'TERMINAL_STATE';

export interface WorldOutcomeTransitionResult {
  changed: boolean;
  state?: WorldOutcomeRuntimeState;
  event?: Extract<
    WorldOperationalEvent,
    { type: 'WORLD_OUTCOME_CHANGED' }
  >;
  reason?: WorldOutcomeTransitionFailure;
}

export class WorldOutcomeValidationError extends Error {
  public constructor(
    public readonly issues: readonly GameplayRegistryIssue[],
  ) {
    super(
      `Invalid world outcome definitions:\n${issues
        .map(
          (issue) => `- ${issue.path}: ${issue.message}`,
        )
        .join('\n')}`,
    );
    this.name = 'WorldOutcomeValidationError';
  }
}

export const validateWorldOutcomeDefinitions = (
  definitions: readonly WorldOutcomeDefinition[],
  registry: GameplayRegistry,
): readonly GameplayRegistryIssue[] => {
  const issues: GameplayRegistryIssue[] = [];
  const ids = new Set<string>();
  for (const [index, definition] of definitions.entries()) {
    const path = `outcomes[${index}]`;
    if (!definition.id.trim()) {
      issues.push({
        path: `${path}.id`,
        message: 'Outcome ID must be a non-empty string',
      });
    } else if (ids.has(definition.id)) {
      issues.push({
        path: `${path}.id`,
        message: `Duplicate outcome ID "${definition.id}"`,
      });
    }
    ids.add(definition.id);

    const states = new Set<string>();
    for (const [stateIndex, state] of (
      definition.allowedStates
    ).entries()) {
      if (!state.trim()) {
        issues.push({
          path: `${path}.allowedStates[${stateIndex}]`,
          message: 'Outcome state must be non-empty',
        });
      } else if (states.has(state)) {
        issues.push({
          path: `${path}.allowedStates[${stateIndex}]`,
          message: `Duplicate outcome state "${state}"`,
        });
      }
      states.add(state);
    }
    if (states.size === 0) {
      issues.push({
        path: `${path}.allowedStates`,
        message: 'At least one outcome state is required',
      });
    }
    if (!states.has(definition.initialState)) {
      issues.push({
        path: `${path}.initialState`,
        message:
          `Initial state "${definition.initialState}" ` +
          'must be allowed',
      });
    }
    for (const [terminalIndex, terminalState] of (
      definition.terminalStates ?? []
    ).entries()) {
      if (!states.has(terminalState)) {
        issues.push({
          path:
            `${path}.terminalStates[${terminalIndex}]`,
          message:
            `Terminal state "${terminalState}" ` +
            'must be allowed',
        });
      }
    }
    if (definition.target) {
      issues.push(
        ...validateWorldTargetRef(
          definition.target,
          registry,
          `${path}.target`,
        ),
      );
    }
  }
  return issues;
};

const cloneDefinition = (
  definition: Readonly<WorldOutcomeDefinition>,
): WorldOutcomeDefinition => {
  const target = definition.target
    ? structuredClone(definition.target)
    : undefined;
  if (target?.kind === 'WORLD_POSITION') {
    Object.freeze(target.position);
  }
  if (target) Object.freeze(target);
  return Object.freeze({
    ...definition,
    allowedStates: Object.freeze([
      ...definition.allowedStates,
    ]),
    terminalStates: definition.terminalStates
      ? Object.freeze([...definition.terminalStates])
      : undefined,
    target,
  });
};

const isSavedOutcomeState = (
  value: unknown,
): value is WorldOutcomeRuntimeState => {
  if (!value || typeof value !== 'object') return false;
  const state = value as Partial<WorldOutcomeRuntimeState>;
  return (
    typeof state.outcomeId === 'string' &&
    typeof state.state === 'string' &&
    Number.isFinite(state.changedAt) &&
    (state.sourceEventId === undefined ||
      typeof state.sourceEventId === 'string')
  );
};

export class WorldOutcomeSystem {
  public readonly definitions:
    readonly WorldOutcomeDefinition[];

  private readonly definitionsById =
    new Map<string, WorldOutcomeDefinition>();
  private readonly states =
    new Map<string, WorldOutcomeRuntimeState>();

  public constructor(
    definitions: readonly WorldOutcomeDefinition[],
    registry: GameplayRegistry,
    saved?: Readonly<WorldOutcomeSaveData>,
  ) {
    const issues = validateWorldOutcomeDefinitions(
      definitions,
      registry,
    );
    if (issues.length > 0) {
      throw new WorldOutcomeValidationError(issues);
    }
    this.definitions = Object.freeze(
      definitions.map(cloneDefinition),
    );
    const savedOutcomes: readonly unknown[] =
      saved?.version === 1 &&
      Array.isArray(saved.outcomes)
        ? saved.outcomes
        : [];
    const savedStates = new Map(
      savedOutcomes
        .filter(isSavedOutcomeState)
        .map((state) => [state.outcomeId, state]),
    );
    for (const definition of this.definitions) {
      this.definitionsById.set(definition.id, definition);
      const restored = savedStates.get(definition.id);
      const validRestored =
        restored &&
        definition.allowedStates.includes(restored.state)
          ? restored
          : undefined;
      this.states.set(definition.id, {
        outcomeId: definition.id,
        state:
          validRestored?.state ?? definition.initialState,
        changedAt:
          validRestored &&
          Number.isFinite(validRestored.changedAt)
            ? Math.max(0, validRestored.changedAt)
            : 0,
        ...(typeof validRestored?.sourceEventId === 'string' &&
        validRestored.sourceEventId
          ? {
              sourceEventId:
                validRestored.sourceEventId,
            }
          : {}),
      });
    }
  }

  public getState(
    outcomeId: string,
  ): WorldOutcomeRuntimeState | undefined {
    const state = this.states.get(outcomeId);
    return state ? { ...state } : undefined;
  }

  public getStates(): readonly WorldOutcomeRuntimeState[] {
    return [...this.states.values()].map((state) => ({
      ...state,
    }));
  }

  public transition(
    outcomeId: string,
    nextState: string,
    occurredAt: number,
    sourceEventId?: string,
  ): WorldOutcomeTransitionResult {
    const definition = this.definitionsById.get(outcomeId);
    const current = this.states.get(outcomeId);
    if (!definition || !current) {
      return {
        changed: false,
        reason: 'UNKNOWN_OUTCOME',
      };
    }
    if (!definition.allowedStates.includes(nextState)) {
      return {
        changed: false,
        state: { ...current },
        reason: 'INVALID_STATE',
      };
    }
    if (current.state === nextState) {
      return {
        changed: false,
        state: { ...current },
      };
    }
    if (
      definition.terminalStates?.includes(current.state)
    ) {
      return {
        changed: false,
        state: { ...current },
        reason: 'TERMINAL_STATE',
      };
    }

    const changedAt = Math.max(
      0,
      Number.isFinite(occurredAt) ? occurredAt : 0,
    );
    const state: WorldOutcomeRuntimeState = {
      outcomeId,
      state: nextState,
      changedAt,
      ...(sourceEventId ? { sourceEventId } : {}),
    };
    this.states.set(outcomeId, state);
    const event: Extract<
      WorldOperationalEvent,
      { type: 'WORLD_OUTCOME_CHANGED' }
    > = {
      type: 'WORLD_OUTCOME_CHANGED',
      eventId:
        `outcome:${outcomeId}:${current.state}:` +
        `${nextState}:` +
        Math.round(changedAt * 1000),
      occurredAt: changedAt,
      source: 'WORLD_SIMULATION',
      outcomeId,
      previousState: current.state,
      state: nextState,
      ...(sourceEventId ? { sourceEventId } : {}),
      ...(definition.target
        ? { targetRefs: [definition.target] }
        : {}),
    };
    return {
      changed: true,
      state: { ...state },
      event,
    };
  }

  public exportState(): WorldOutcomeSaveData {
    return {
      version: 1,
      outcomes: this.getStates().map((state) => ({
        ...state,
      })),
    };
  }
}
