import {
  DEFAULT_NETWORK_ENVELOPE_LIMITS,
  type NetworkEnvelope,
  type NetworkEnvelopeLimits,
  decodeNetworkEnvelope,
  encodeNetworkEnvelope,
} from '../protocol/ProtocolEnvelope';
import type {
  SessionTransportDiagnostics,
  SessionTransportEndpoint,
  SessionTransportStatus,
  TransportMessageListener,
  TransportSendResult,
  TransportStatusListener,
} from './SessionTransport';

export interface WebSocketClientTransportOptions {
  protocols?: string | readonly string[];
  maxBufferedBytes?: number;
  envelopeLimits?: Readonly<NetworkEnvelopeLimits>;
  socketFactory?: (url: string, protocols?: string | string[]) => WebSocket;
}

const createDiagnostics = (): SessionTransportDiagnostics => ({
  sentMessages: 0,
  sentBytes: 0,
  deliveredMessages: 0,
  deliveredBytes: 0,
  coalescedMessages: 0,
  droppedMessages: 0,
  rejectedMessages: 0,
  listenerErrors: 0,
  queuedMessages: 0,
  queuedBytes: 0,
});

/** Browser transport adapter. Gameplay sees only SessionTransportEndpoint. */
export class WebSocketClientTransport implements SessionTransportEndpoint {
  public readonly side = 'CLIENT' as const;

  private readonly socket: WebSocket;
  private readonly messageListeners = new Set<TransportMessageListener>();
  private readonly statusListeners = new Set<TransportStatusListener>();
  private readonly stats = createDiagnostics();
  private readonly maxBufferedBytes: number;
  private readonly envelopeLimits: Readonly<NetworkEnvelopeLimits>;
  private currentStatus: SessionTransportStatus = 'CONNECTING';
  private decodeChain = Promise.resolve();

  public constructor(
    url: string,
    options: Readonly<WebSocketClientTransportOptions> = {},
  ) {
    if (!/^wss?:\/\//i.test(url)) {
      throw new Error('WebSocket transport URL must use ws:// or wss://.');
    }
    this.maxBufferedBytes = options.maxBufferedBytes ?? 512 * 1024;
    this.envelopeLimits = options.envelopeLimits ?? DEFAULT_NETWORK_ENVELOPE_LIMITS;
    const factory =
      options.socketFactory ??
      ((targetUrl: string, protocols?: string | string[]) =>
        protocols ? new WebSocket(targetUrl, protocols) : new WebSocket(targetUrl));
    const protocols = typeof options.protocols === 'string'
      ? options.protocols
      : options.protocols
        ? [...options.protocols]
        : undefined;
    this.socket = factory(url, protocols);
    this.socket.binaryType = 'arraybuffer';
    this.socket.addEventListener('open', this.onOpen);
    this.socket.addEventListener('message', this.onSocketMessage);
    this.socket.addEventListener('close', this.onClose);
    this.socket.addEventListener('error', this.onError);
  }

  public get status(): SessionTransportStatus {
    return this.currentStatus;
  }

  public send(
    envelope: Readonly<NetworkEnvelope<string, unknown>>,
  ): TransportSendResult {
    if (this.currentStatus === 'CLOSED') {
      this.stats.rejectedMessages += 1;
      return { accepted: false, reason: 'ENDPOINT_CLOSED' };
    }
    if (this.currentStatus !== 'OPEN' || this.socket.readyState !== 1) {
      this.stats.rejectedMessages += 1;
      return { accepted: false, reason: 'NOT_OPEN' };
    }
    let encoded: string;
    try {
      encoded = encodeNetworkEnvelope(envelope, this.envelopeLimits);
    } catch {
      this.stats.rejectedMessages += 1;
      return { accepted: false, reason: 'INVALID_MESSAGE' };
    }
    const encodedBytes = new TextEncoder().encode(encoded).byteLength;
    if (this.socket.bufferedAmount + encodedBytes > this.maxBufferedBytes) {
      this.stats.rejectedMessages += 1;
      return { accepted: false, reason: 'QUEUE_FULL' };
    }
    this.socket.send(encoded);
    this.stats.sentMessages += 1;
    this.stats.sentBytes += encodedBytes;
    this.refreshBufferedStats();
    return { accepted: true, encodedBytes, coalesced: false };
  }

  public onMessage(listener: TransportMessageListener): () => void {
    this.messageListeners.add(listener);
    return () => this.messageListeners.delete(listener);
  }

  public onStatus(listener: TransportStatusListener): () => void {
    this.statusListeners.add(listener);
    return () => this.statusListeners.delete(listener);
  }

  public close(reason = 'Client closed'): void {
    if (this.currentStatus === 'CLOSED') return;
    this.socket.close(1000, reason.slice(0, 120));
    this.setStatus('CLOSED', reason);
  }

  public diagnostics(): SessionTransportDiagnostics {
    this.refreshBufferedStats();
    return { ...this.stats };
  }

  private onOpen = (): void => {
    this.setStatus('OPEN');
  };

  private onSocketMessage = (event: MessageEvent<unknown>): void => {
    this.decodeChain = this.decodeChain.then(async () => {
      let encoded: string;
      if (typeof event.data === 'string') encoded = event.data;
      else if (event.data instanceof ArrayBuffer) {
        encoded = new TextDecoder().decode(event.data);
      } else if (
        typeof Blob !== 'undefined' &&
        event.data instanceof Blob
      ) encoded = await event.data.text();
      else {
        this.stats.droppedMessages += 1;
        return;
      }
      const decoded = decodeNetworkEnvelope(encoded, this.envelopeLimits);
      if (!decoded.ok) {
        this.stats.droppedMessages += 1;
        return;
      }
      this.stats.deliveredMessages += 1;
      this.stats.deliveredBytes += decoded.encodedBytes;
      for (const listener of [...this.messageListeners]) {
        try {
          listener(decoded.value);
        } catch {
          this.stats.listenerErrors += 1;
        }
      }
    }).catch(() => {
      this.stats.droppedMessages += 1;
    });
  };

  private onClose = (event: CloseEvent): void => {
    this.setStatus('CLOSED', event.reason || `WebSocket closed (${event.code}).`);
  };

  private onError = (): void => {
    if (this.socket.readyState === 3) {
      this.setStatus('CLOSED', 'WebSocket connection error.');
    }
  };

  private setStatus(status: SessionTransportStatus, reason?: string): void {
    if (this.currentStatus === status) return;
    this.currentStatus = status;
    for (const listener of [...this.statusListeners]) listener(status, reason);
  }

  private refreshBufferedStats(): void {
    this.stats.queuedBytes = this.socket.bufferedAmount;
    this.stats.queuedMessages = this.socket.bufferedAmount > 0 ? 1 : 0;
  }
}
