export interface FloeOffset {
  x: number;
  z: number;
}

export interface FloeFrame {
  centerX: number;
  centerZ: number;
  offsetX: number;
  offsetZ: number;
}

export const recenterFloeOffset = (
  previousCenterX: number,
  previousCenterZ: number,
  nextCenterX: number,
  nextCenterZ: number,
  previousOffsetX: number,
  previousOffsetZ: number,
  angle: number,
): FloeOffset => {
  const cosine = Math.cos(angle);
  const sine = Math.sin(angle);
  const centerDeltaX = previousCenterX - nextCenterX;
  const centerDeltaZ = previousCenterZ - nextCenterZ;
  return {
    x:
      previousOffsetX +
      (1 - cosine) * centerDeltaX +
      sine * centerDeltaZ,
    z:
      previousOffsetZ -
      sine * centerDeltaX +
      (1 - cosine) * centerDeltaZ,
  };
};

export const translateFloeFrame = (
  centerX: number,
  centerZ: number,
  offsetX: number,
  offsetZ: number,
  deltaX: number,
  deltaZ: number,
): FloeFrame => ({
  centerX: centerX + deltaX,
  centerZ: centerZ + deltaZ,
  offsetX: offsetX - deltaX,
  offsetZ: offsetZ - deltaZ,
});
