export const ACHIEVEMENT_STAT_IDS = [
  'DISTANCE_TRAVELLED_KM',
  'ICE_CELLS_BROKEN',
  'FUEL_USED',
  'TIME_AT_HELM_SECONDS',
  'PORTS_CLEARED',
  'ROUTES_OPENED',
  'MISSIONS_COMPLETED',
] as const;

export type AchievementStatId =
  (typeof ACHIEVEMENT_STAT_IDS)[number];

export type AchievementStatFormat =
  | 'DECIMAL'
  | 'INTEGER'
  | 'DURATION';

export interface AchievementStatPresentation {
  statId: AchievementStatId;
  label: string;
  shortLabel: string;
  format: AchievementStatFormat;
  suffix?: string;
}

export interface AchievementDefinition {
  id: string;
  title: string;
  description: string;
  statId: AchievementStatId;
  threshold: number;
}

// Direct-control distances are intentionally measured in stylized world
// kilometres. The conversion can be changed later without touching tracking.
export const WORLD_UNIT_KILOMETRES = 1;

