import {
  BoxGeometry,
  ConeGeometry,
  CylinderGeometry,
  Group,
  Mesh,
  MeshStandardMaterial,
  TorusGeometry,
  type Scene,
} from 'three';
import { BOREALIS_WORLD_ANCHORS } from '../../world/BorealisWorldLayout';
import { BOREALIS_ARRIVAL_SNOW_PATCH } from './BorealisArrivalDefinitions';
import { BOREALIS_VERTICAL_SLICE_ASSETS } from './BorealisVerticalSliceAssetCatalog';

/** Small replaceable landmarks that make the first ten minutes readable. */
export class BorealisVerticalSliceLandmarks {
  private readonly root = new Group();
  private readonly squareWorksite = new Group();
  private readonly depotMarker = new Group();
  private readonly materials: MeshStandardMaterial[] = [];

  public constructor(scene: Scene) {
    this.root.name = 'Borealis vertical-slice landmarks';
    this.createSquareSupplyBox();
    this.createDepotMarker();
    this.root.add(this.squareWorksite, this.depotMarker);
    this.root.visible = false;
    scene.add(this.root);
  }

  public setVisible(visible: boolean): void {
    this.root.visible = visible;
  }

  public update(
    elapsedSeconds: number,
    activeStageId: string | undefined,
    squareClearedRatio: number,
    starterTractorStarted: boolean,
  ): void {
    const squareActive = activeStageId === 'clear-landing-drift';
    const depotActive = activeStageId === 'wake-the-old-tractor';
    this.squareWorksite.visible = squareActive && squareClearedRatio < 0.98;
    this.depotMarker.visible = depotActive && !starterTractorStarted;
    const squarePulse = squareActive
      ? 1 + Math.sin(elapsedSeconds * 3.2) * 0.045
      : 1;
    const depotPulse = depotActive
      ? 1 + Math.sin(elapsedSeconds * 2.6) * 0.075
      : 1;
    this.squareWorksite.scale.setScalar(squarePulse);
    this.depotMarker.scale.setScalar(depotPulse);
  }

  public dispose(): void {
    this.root.traverse((object) => {
      if (object instanceof Mesh) object.geometry.dispose();
    });
    this.materials.forEach((material) => material.dispose());
    this.root.removeFromParent();
  }

  private createSquareSupplyBox(): void {
    const teal = this.material(0x4b8790, 0.72, 0.08);
    const dark = this.material(0x26383b, 0.82, 0.14);
    const orange = this.material(0xf0a33b, 0.68, 0.04, 0xd66a18);
    const snow = this.material(0xdceced, 0.94, 0);
    const supplyX = -BOREALIS_ARRIVAL_SNOW_PATCH.halfWidth - 0.78;
    const box = new Mesh(new BoxGeometry(0.95, 0.5, 0.62), teal);
    box.position.set(supplyX, 0.32, 0);
    const lid = new Mesh(new BoxGeometry(1.02, 0.1, 0.69), dark);
    lid.position.set(supplyX, 0.61, 0);
    const snowCap = new Mesh(new BoxGeometry(0.98, 0.09, 0.65), snow);
    snowCap.position.set(supplyX, 0.69, 0);
    const latch = new Mesh(new BoxGeometry(0.14, 0.2, 0.06), orange);
    latch.position.set(supplyX, 0.43, 0.34);
    this.squareWorksite.add(box, lid, snowCap, latch);
    const corners = [
      [-BOREALIS_ARRIVAL_SNOW_PATCH.halfWidth, -BOREALIS_ARRIVAL_SNOW_PATCH.halfHeight],
      [BOREALIS_ARRIVAL_SNOW_PATCH.halfWidth, -BOREALIS_ARRIVAL_SNOW_PATCH.halfHeight],
      [-BOREALIS_ARRIVAL_SNOW_PATCH.halfWidth, BOREALIS_ARRIVAL_SNOW_PATCH.halfHeight],
      [BOREALIS_ARRIVAL_SNOW_PATCH.halfWidth, BOREALIS_ARRIVAL_SNOW_PATCH.halfHeight],
    ] as const;
    for (const [x, z] of corners) {
      const stake = new Mesh(new CylinderGeometry(0.025, 0.035, 0.58, 7), orange);
      stake.position.set(x, 0.29, z);
      const flag = new Mesh(new BoxGeometry(0.32, 0.12, 0.025), orange);
      flag.position.set(x + 0.16, 0.48, z);
      this.squareWorksite.add(stake, flag);
    }
    this.squareWorksite.position.set(
      BOREALIS_ARRIVAL_SNOW_PATCH.centerX,
      0.08,
      BOREALIS_ARRIVAL_SNOW_PATCH.centerZ,
    );
    this.squareWorksite.name = 'Marta first snow worksite';
    this.squareWorksite.userData.assetBankId =
      BOREALIS_VERTICAL_SLICE_ASSETS.shovel.id;
  }

  private createDepotMarker(): void {
    const wood = this.material(0x795337, 0.88, 0.01);
    const orange = this.material(0xe89032, 0.65, 0.05, 0xc86119);
    const pale = this.material(0xdbe8e4, 0.86, 0);
    const pole = new Mesh(new CylinderGeometry(0.075, 0.095, 2.6, 8), wood);
    pole.position.y = 1.3;
    const board = new Mesh(new BoxGeometry(1.5, 0.62, 0.12), orange);
    board.position.set(0.56, 2.08, 0);
    const arrow = new Mesh(new ConeGeometry(0.24, 0.55, 3), pale);
    arrow.position.set(0.98, 2.08, 0.09);
    arrow.rotation.z = -Math.PI / 2;
    const wrenchRing = new Mesh(new TorusGeometry(0.19, 0.045, 6, 10), pale);
    wrenchRing.position.set(0.22, 2.08, 0.09);
    const wrenchHandle = new Mesh(new BoxGeometry(0.08, 0.42, 0.055), pale);
    wrenchHandle.position.set(0.22, 1.84, 0.09);
    this.depotMarker.add(pole, board, arrow, wrenchRing, wrenchHandle);
    this.depotMarker.position.set(
      BOREALIS_WORLD_ANCHORS.abandonedDepot.x - 4.7,
      0.06,
      BOREALIS_WORLD_ANCHORS.starterTractor.z,
    );
    this.depotMarker.rotation.y = Math.PI / 2;
    this.depotMarker.name = 'Abandoned municipal depot marker';
    this.depotMarker.userData.assetBankId =
      BOREALIS_VERTICAL_SLICE_ASSETS.depotMarker.id;
  }

  private material(
    color: number,
    roughness: number,
    metalness: number,
    emissive = 0x000000,
  ): MeshStandardMaterial {
    const material = new MeshStandardMaterial({
      color,
      roughness,
      metalness,
      emissive,
      emissiveIntensity: emissive ? 0.14 : 0,
    });
    this.materials.push(material);
    return material;
  }
}
