/**
 * Explicit tester affordances. Production progression remains unchanged unless
 * the build is deliberately created with VITE_ICEWAY_PLAYTEST=true.
 */
export const ICEWAY_PLAYTEST_MODE =
  import.meta.env.DEV || import.meta.env.VITE_ICEWAY_PLAYTEST === 'true';

/** Visible identifier so testers can report the exact browser build in use. */
export const ICEWAY_BUILD_ID =
  import.meta.env.VITE_ICEWAY_BUILD_ID?.trim() ||
  (import.meta.env.DEV ? 'DEV SOURCE' : 'PRODUCTION');
