export type PlatformRenderProfileId = 'PHONE' | 'TABLET' | 'DESKTOP';

export interface PlatformCapabilitySample {
  readonly viewportWidth: number;
  readonly viewportHeight: number;
  readonly devicePixelRatio: number;
  readonly coarsePointer: boolean;
  readonly hardwareConcurrency?: number;
  readonly deviceMemoryGb?: number;
}

export interface PlatformRenderProfile {
  readonly id: PlatformRenderProfileId;
  readonly maxPixelRatio: number;
  readonly targetFrameRate: 30 | 60;
  readonly nearParticleMultiplier: number;
  readonly vegetationDensityMultiplier: number;
}

/** Presentation-only startup profile: authoritative game rules stay identical. */
export const resolvePlatformRenderProfile = (
  sample: Readonly<PlatformCapabilitySample>,
): PlatformRenderProfile => {
  const shortEdge = Math.min(sample.viewportWidth, sample.viewportHeight);
  const cores = sample.hardwareConcurrency ?? 4;
  const memory = sample.deviceMemoryGb ?? 4;
  if (sample.coarsePointer && shortEdge < 700) return Object.freeze({
    id: 'PHONE',
    maxPixelRatio: 1.1,
    targetFrameRate: 30,
    nearParticleMultiplier: 0.55,
    vegetationDensityMultiplier: 0.58,
  });
  if (sample.coarsePointer || cores <= 4 || memory <= 4) return Object.freeze({
    id: 'TABLET',
    maxPixelRatio: 1.25,
    targetFrameRate: 30,
    nearParticleMultiplier: 0.72,
    vegetationDensityMultiplier: 0.76,
  });
  return Object.freeze({
    id: 'DESKTOP',
    maxPixelRatio: 1.5,
    targetFrameRate: 60,
    nearParticleMultiplier: 1,
    vegetationDensityMultiplier: 1,
  });
};

export const readBrowserPlatformRenderProfile = (): PlatformRenderProfile => {
  const navigatorWithMemory = navigator as Navigator & { deviceMemory?: number };
  return resolvePlatformRenderProfile({
    viewportWidth: window.innerWidth,
    viewportHeight: window.innerHeight,
    devicePixelRatio: window.devicePixelRatio,
    coarsePointer: window.matchMedia('(pointer: coarse)').matches,
    hardwareConcurrency: navigator.hardwareConcurrency,
    deviceMemoryGb: navigatorWithMemory.deviceMemory,
  });
};
