import {
  BoxGeometry,
  BufferGeometry,
  Color,
  CylinderGeometry,
  Group,
  LineBasicMaterial,
  LineSegments,
  Mesh,
  MeshStandardMaterial,
  SphereGeometry,
  Vector3,
  type Scene,
} from 'three';
import { clamp, damp, lerp } from '../utils/math';
import type { TerrainHeightSystem } from './TerrainHeightSystem';

export type PlayerTraversalMode = 'NONE' | 'PARAGLIDER' | 'SNOWBOARD';

export interface PlayerTraversalControl {
  readonly right: number;
  readonly forward: number;
  readonly jump: boolean;
  readonly flip: number;
  readonly spin: number;
}

export interface TraversalWind {
  readonly x: number;
  readonly z: number;
  readonly strength: number;
}

export interface ParagliderState {
  x: number;
  y: number;
  z: number;
  heading: number;
  airspeed: number;
  verticalSpeed: number;
  roll: number;
  pitch: number;
  airborne: boolean;
}

export interface SnowboardState {
  x: number;
  y: number;
  z: number;
  heading: number;
  velocityX: number;
  velocityZ: number;
  verticalSpeed: number;
  airborne: boolean;
  pitchRotation: number;
  yawRotation: number;
  roll: number;
  landingQuality: number;
}

export interface PlayerTraversalSaveData {
  readonly version: 1;
  readonly mode: PlayerTraversalMode;
  readonly paraglider: Readonly<ParagliderState>;
  readonly snowboard: Readonly<SnowboardState>;
}

export interface PlayerTraversalStepResult {
  readonly mode: PlayerTraversalMode;
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly heading: number;
  readonly speed: number;
  readonly airborne: boolean;
  readonly landed: boolean;
  readonly jumped: boolean;
  readonly carveStrength: number;
  readonly pitch: number;
  readonly yawOffset: number;
  readonly roll: number;
}

const EMPTY_CONTROL: PlayerTraversalControl = {
  right: 0,
  forward: 0,
  jump: false,
  flip: 0,
  spin: 0,
};

const safeControl = (
  input: Readonly<PlayerTraversalControl>,
): PlayerTraversalControl => ({
  right: clamp(input.right, -1, 1),
  forward: clamp(input.forward, -1, 1),
  jump: input.jump,
  flip: clamp(input.flip, -1, 1),
  spin: clamp(input.spin, -1, 1),
});

/** Fixed-step character traversal authority plus a tiny pooled presenter. */
export class PlayerTraversalSystem {
  private readonly root = new Group();
  private readonly paragliderRoot = new Group();
  private readonly snowboardRoot = new Group();
  private readonly canopyMaterial = new MeshStandardMaterial({
    color: new Color(0xf09b50),
    roughness: 0.76,
    metalness: 0,
    side: 2,
  });
  private readonly boardMaterial = new MeshStandardMaterial({
    color: new Color(0x4abfc4),
    roughness: 0.52,
    metalness: 0.08,
  });
  private readonly lineMaterial = new LineBasicMaterial({
    color: new Color(0xe8e1cc),
    transparent: true,
    opacity: 0.76,
  });
  private readonly lineGeometry = new BufferGeometry();
  private mode: PlayerTraversalMode = 'NONE';
  private visible = false;
  private jumpLatch = false;
  private paraglider: ParagliderState = {
    x: 0,
    y: 0,
    z: 0,
    heading: 0,
    airspeed: 6.4,
    verticalSpeed: -0.4,
    roll: 0,
    pitch: 0,
    airborne: false,
  };
  private snowboard: SnowboardState = {
    x: 0,
    y: 0,
    z: 0,
    heading: 0,
    velocityX: 0,
    velocityZ: 0,
    verticalSpeed: 0,
    airborne: false,
    pitchRotation: 0,
    yawRotation: 0,
    roll: 0,
    landingQuality: 1,
  };

  public constructor(
    scene: Scene,
    private readonly terrain: TerrainHeightSystem,
    private readonly sampleSnowSurface: (x: number, z: number) => number,
  ) {
    this.root.name = 'Player paraglider and snowboard traversal';
    this.createParaglider();
    this.createSnowboard();
    this.root.add(this.paragliderRoot, this.snowboardRoot);
    this.root.visible = false;
    scene.add(this.root);
  }

  public getMode(): PlayerTraversalMode {
    return this.mode;
  }

  public setVisible(visible: boolean): void {
    this.visible = visible;
    this.root.visible = visible;
    this.syncVisibility();
  }

  public beginParaglider(
    x: number,
    z: number,
    heading: number,
    launchAltitude = 12,
  ): void {
    const ground = this.sampleSnowSurface(x, z);
    this.mode = 'PARAGLIDER';
    this.paraglider = {
      x,
      y: ground + Math.max(1.2, launchAltitude),
      z,
      heading,
      airspeed: 6.6,
      verticalSpeed: -0.28,
      roll: 0,
      pitch: 0,
      airborne: true,
    };
    this.jumpLatch = false;
    this.syncVisibility();
  }

  public beginSnowboard(x: number, z: number, heading: number): void {
    const surface = this.sampleSnowSurface(x, z);
    this.mode = 'SNOWBOARD';
    this.snowboard = {
      x,
      y: surface + 0.08,
      z,
      heading,
      velocityX: Math.sin(heading) * 0.5,
      velocityZ: Math.cos(heading) * 0.5,
      verticalSpeed: 0,
      airborne: false,
      pitchRotation: 0,
      yawRotation: 0,
      roll: 0,
      landingQuality: 1,
    };
    this.jumpLatch = false;
    this.syncVisibility();
  }

  public stop(): void {
    this.mode = 'NONE';
    this.jumpLatch = false;
    this.syncVisibility();
  }

  public step(
    deltaSeconds: number,
    input: Readonly<PlayerTraversalControl> = EMPTY_CONTROL,
    wind: Readonly<TraversalWind> = { x: 1, z: 0, strength: 0 },
  ): PlayerTraversalStepResult | undefined {
    const delta = clamp(deltaSeconds, 0, 0.05);
    if (this.mode === 'NONE' || delta <= 0) return undefined;
    const control = safeControl(input);
    return this.mode === 'PARAGLIDER'
      ? this.stepParaglider(delta, control, wind)
      : this.stepSnowboard(delta, control);
  }

  public updatePresentation(): void {
    if (!this.visible || this.mode === 'NONE') return;
    if (this.mode === 'PARAGLIDER') {
      const state = this.paraglider;
      this.paragliderRoot.position.set(state.x, state.y, state.z);
      this.paragliderRoot.rotation.set(
        state.pitch * 0.35,
        state.heading,
        -state.roll * 0.56,
      );
    } else {
      const state = this.snowboard;
      this.snowboardRoot.position.set(state.x, state.y + 0.035, state.z);
      this.snowboardRoot.rotation.set(
        state.pitchRotation,
        state.heading + state.yawRotation,
        state.roll,
      );
    }
  }

  public exportState(): PlayerTraversalSaveData {
    return {
      version: 1,
      mode: this.mode,
      paraglider: { ...this.paraglider },
      snowboard: { ...this.snowboard },
    };
  }

  public importState(input: unknown): boolean {
    if (!input || typeof input !== 'object') return false;
    const saved = input as Partial<PlayerTraversalSaveData>;
    if (saved.version !== 1 || !saved.paraglider || !saved.snowboard) {
      return false;
    }
    const paragliderValues = Object.values(saved.paraglider);
    const snowboardValues = Object.values(saved.snowboard);
    if (
      !paragliderValues.filter((value) => typeof value === 'number').every(Number.isFinite) ||
      !snowboardValues.filter((value) => typeof value === 'number').every(Number.isFinite)
    ) return false;
    this.paraglider = { ...saved.paraglider };
    this.snowboard = { ...saved.snowboard };
    // A page reload never resumes an uncontrolled airborne character. The
    // state remains available for debugging, but play resumes safely on foot.
    this.mode = 'NONE';
    this.syncVisibility();
    return true;
  }

  public dispose(): void {
    this.root.traverse((object) => {
      if (object instanceof Mesh) object.geometry.dispose();
    });
    this.canopyMaterial.dispose();
    this.boardMaterial.dispose();
    this.lineMaterial.dispose();
    this.lineGeometry.dispose();
    this.root.removeFromParent();
  }

  private stepParaglider(
    delta: number,
    control: Readonly<PlayerTraversalControl>,
    wind: Readonly<TraversalWind>,
  ): PlayerTraversalStepResult {
    const state = this.paraglider;
    const windLength = Math.max(0.0001, Math.hypot(wind.x, wind.z));
    const windX = wind.x / windLength;
    const windZ = wind.z / windLength;
    const windSpeed = clamp(wind.strength, 0, 2.8) * 2.25;
    const turnRate = 0.72 + state.airspeed * 0.055;
    state.heading += control.right * turnRate * delta;
    state.roll = damp(state.roll, control.right * 0.72, 5.4, delta);
    state.pitch = damp(state.pitch, control.forward * 0.26, 3.8, delta);
    const targetAirspeed = clamp(
      6.4 + control.forward * 2.2 + Math.abs(control.right) * 0.35,
      4.4,
      10.5,
    );
    state.airspeed = damp(state.airspeed, targetAirspeed, 1.6, delta);
    const forwardX = Math.sin(state.heading);
    const forwardZ = Math.cos(state.heading);
    const headwind = Math.max(0, -(forwardX * windX + forwardZ * windZ)) *
      windSpeed;
    const aheadTerrain = this.terrain.sampleHeight(
      state.x + windX * 5,
      state.z + windZ * 5,
    );
    const behindTerrain = this.terrain.sampleHeight(
      state.x - windX * 5,
      state.z - windZ * 5,
    );
    const ridgeLift = clamp((aheadTerrain - behindTerrain) / 7, 0, 1) *
      clamp(windSpeed / 4, 0, 1) * 1.05;
    const lift = headwind * 0.16 + ridgeLift +
      Math.max(0, -control.forward) * 0.2;
    const sink = 0.72 + Math.abs(control.right) ** 2 * 0.62 +
      Math.max(0, control.forward) * 0.42;
    state.verticalSpeed = damp(
      state.verticalSpeed,
      clamp(lift - sink, -2.2, 0.85),
      1.8,
      delta,
    );
    state.x += (forwardX * state.airspeed + windX * windSpeed) * delta;
    state.z += (forwardZ * state.airspeed + windZ * windSpeed) * delta;
    state.y += state.verticalSpeed * delta;
    const ground = this.sampleSnowSurface(state.x, state.z) + 0.08;
    let landed = false;
    if (state.y <= ground) {
      state.y = ground;
      state.airborne = false;
      landed = true;
      this.stop();
    }
    return {
      mode: 'PARAGLIDER',
      x: state.x,
      y: state.y,
      z: state.z,
      heading: state.heading,
      speed: state.airspeed,
      airborne: state.airborne,
      landed,
      jumped: false,
      carveStrength: 0,
      pitch: state.pitch,
      yawOffset: 0,
      roll: state.roll,
    };
  }

  private stepSnowboard(
    delta: number,
    control: Readonly<PlayerTraversalControl>,
  ): PlayerTraversalStepResult {
    const state = this.snowboard;
    let jumped = false;
    let landed = false;
    const jumpPressed = control.jump && !this.jumpLatch;
    this.jumpLatch = control.jump;
    if (!state.airborne) {
      const surface = this.terrain.sampleSurface(state.x, state.z);
      const speed = Math.hypot(state.velocityX, state.velocityZ);
      const downhillX = 9.81 * surface.normalX * surface.normalY;
      const downhillZ = 9.81 * surface.normalZ * surface.normalY;
      state.velocityX += downhillX * delta;
      state.velocityZ += downhillZ * delta;
      const steeringAuthority = clamp(0.72 + speed * 0.09, 0.72, 1.8);
      state.heading += control.right * steeringAuthority * delta;
      const forwardX = Math.sin(state.heading);
      const forwardZ = Math.cos(state.heading);
      const gentleKick = Math.max(0, control.forward) * 0.78;
      state.velocityX += forwardX * gentleKick * delta;
      state.velocityZ += forwardZ * gentleKick * delta;
      const along = state.velocityX * forwardX + state.velocityZ * forwardZ;
      const targetSpeed = Math.max(0.2, along);
      const edgeDrag = 0.18 + Math.abs(control.right) * 0.42 +
        Math.max(0, -control.forward) * 0.38;
      state.velocityX = lerp(
        state.velocityX,
        forwardX * targetSpeed,
        clamp(delta * (1.3 + Math.abs(control.right) * 2.2), 0, 1),
      ) * Math.exp(-edgeDrag * delta);
      state.velocityZ = lerp(
        state.velocityZ,
        forwardZ * targetSpeed,
        clamp(delta * (1.3 + Math.abs(control.right) * 2.2), 0, 1),
      ) * Math.exp(-edgeDrag * delta);
      if (jumpPressed && speed > 1.4) {
        state.airborne = true;
        state.verticalSpeed = 2.25 + Math.min(1.7, speed * 0.12);
        jumped = true;
      }
      state.roll = damp(state.roll, -control.right * 0.35, 7, delta);
      state.pitchRotation = damp(
        state.pitchRotation,
        Math.atan2(
          -(surface.normalX * forwardX + surface.normalZ * forwardZ),
          surface.normalY,
        ),
        8,
        delta,
      );
      state.y = this.sampleSnowSurface(state.x, state.z) + 0.08;
    } else {
      state.verticalSpeed -= 9.25 * delta;
      state.pitchRotation += control.flip * 3.25 * delta;
      state.yawRotation += control.spin * 3.5 * delta;
      state.roll = damp(state.roll, -control.right * 0.42, 2.8, delta);
    }
    const previousX = state.x;
    const previousZ = state.z;
    state.x += state.velocityX * delta;
    state.z += state.velocityZ * delta;
    if (state.airborne) state.y += state.verticalSpeed * delta;
    const nextSurface = this.sampleSnowSurface(state.x, state.z) + 0.08;
    if (!state.airborne) {
      const ledgeDrop = state.y - nextSurface;
      if (ledgeDrop > 0.22 && Math.hypot(state.velocityX, state.velocityZ) > 2.4) {
        state.airborne = true;
        state.verticalSpeed = Math.max(0.15, state.verticalSpeed);
        jumped = true;
      } else state.y = nextSurface;
    } else if (state.y <= nextSurface && state.verticalSpeed <= 0) {
      const pitchError = Math.abs(
        Math.atan2(Math.sin(state.pitchRotation), Math.cos(state.pitchRotation)),
      );
      const yawError = Math.abs(
        Math.atan2(Math.sin(state.yawRotation), Math.cos(state.yawRotation)),
      );
      state.landingQuality = clamp(
        1 - pitchError / 1.4 - yawError / 2.8 -
          Math.max(0, -state.verticalSpeed - 2.2) * 0.12,
        0.18,
        1,
      );
      state.velocityX *= lerp(0.42, 0.94, state.landingQuality);
      state.velocityZ *= lerp(0.42, 0.94, state.landingQuality);
      state.y = nextSurface;
      state.verticalSpeed = 0;
      state.airborne = false;
      state.pitchRotation = 0;
      state.yawRotation = 0;
      landed = true;
    }
    const travel = Math.hypot(state.x - previousX, state.z - previousZ);
    return {
      mode: 'SNOWBOARD',
      x: state.x,
      y: state.y,
      z: state.z,
      heading: state.heading,
      speed: Math.hypot(state.velocityX, state.velocityZ),
      airborne: state.airborne,
      landed,
      jumped,
      carveStrength: state.airborne
        ? 0
        : clamp(Math.abs(control.right) * 0.72 + travel * 5, 0.08, 1),
      pitch: state.pitchRotation,
      yawOffset: state.yawRotation,
      roll: state.roll,
    };
  }

  private createParaglider(): void {
    this.paragliderRoot.name = 'Wind-reactive paraglider';
    const panels = 7;
    for (let index = 0; index < panels; index += 1) {
      const normalized = panels <= 1 ? 0 : index / (panels - 1) * 2 - 1;
      const panel = new Mesh(new SphereGeometry(0.62, 8, 5), this.canopyMaterial);
      panel.position.set(normalized * 0.58, 2.45 + (1 - normalized * normalized) * 0.34, 0);
      panel.scale.set(0.88, 0.22, 0.62);
      panel.castShadow = true;
      this.paragliderRoot.add(panel);
    }
    const linePoints: Vector3[] = [];
    for (const side of [-1, 1]) {
      linePoints.push(
        new Vector3(side * 1.55, 2.45, 0),
        new Vector3(side * 0.24, 0.48, 0),
        new Vector3(side * 0.58, 2.62, 0.08),
        new Vector3(side * 0.16, 0.48, 0.05),
      );
    }
    this.lineGeometry.setFromPoints(linePoints);
    this.paragliderRoot.add(new LineSegments(this.lineGeometry, this.lineMaterial));
  }

  private createSnowboard(): void {
    this.snowboardRoot.name = 'Carving low-poly snowboard';
    const board = new Mesh(new BoxGeometry(0.28, 0.055, 1.38), this.boardMaterial);
    board.position.y = 0.015;
    board.castShadow = true;
    board.receiveShadow = true;
    const nose = new Mesh(new CylinderGeometry(0.14, 0.14, 0.055, 10), this.boardMaterial);
    nose.rotation.z = Math.PI / 2;
    nose.position.set(0, 0.05, 0.68);
    const tail = nose.clone();
    tail.position.z = -0.68;
    this.snowboardRoot.add(board, nose, tail);
  }

  private syncVisibility(): void {
    this.paragliderRoot.visible = this.visible && this.mode === 'PARAGLIDER';
    this.snowboardRoot.visible = this.visible && this.mode === 'SNOWBOARD';
  }
}
