import type {
  SettlementAnimalHabitatDefinition,
  SettlementAnimalSpeciesDefinition,
  SettlementBuildingDefinition,
  SettlementBuildingStageDefinition,
  SettlementContentDefinitionSet,
  SettlementCropDefinition,
  SettlementCropPlotDefinition,
  SettlementCultivationPatchDefinition,
  SettlementGoodAmount,
  SettlementGoodDefinition,
  SettlementPlantDefinition,
  SettlementRecipeDefinition,
  SettlementResourceNodeDefinition,
  SettlementSeasonRegionDefinition,
} from './SettlementTypes';

export interface SettlementContentIssue {
  readonly path: string;
  readonly message: string;
}

const ID_PATTERN = /^[a-z0-9][a-z0-9._-]{0,159}$/;
const MAXIMUM_GOOD_QUANTITY = 1_000_000;

const isPositiveInteger = (value: number): boolean =>
  Number.isSafeInteger(value) && value > 0 && value <= MAXIMUM_GOOD_QUANTITY;

const issueAmounts = (
  amounts: readonly SettlementGoodAmount[],
  path: string,
  goodIds: ReadonlySet<string>,
  allowEmpty: boolean,
): readonly SettlementContentIssue[] => {
  const issues: SettlementContentIssue[] = [];
  if (!Array.isArray(amounts) || (!allowEmpty && amounts.length === 0)) {
    issues.push({ path, message: allowEmpty ? 'Amounts must be an array.' : 'At least one amount is required.' });
    return issues;
  }
  const seen = new Set<string>();
  amounts.forEach((amount, index) => {
    const amountPath = `${path}[${index}]`;
    if (!goodIds.has(amount.goodId)) {
      issues.push({ path: `${amountPath}.goodId`, message: `Unknown good "${amount.goodId}".` });
    }
    if (seen.has(amount.goodId)) {
      issues.push({ path: amountPath, message: `Duplicate good "${amount.goodId}".` });
    }
    seen.add(amount.goodId);
    if (!isPositiveInteger(amount.quantity)) {
      issues.push({ path: `${amountPath}.quantity`, message: 'Quantity must be a positive bounded integer.' });
    }
  });
  return issues;
};

const duplicateIssues = <T extends { readonly id: string }>(
  values: readonly T[],
  path: string,
): readonly SettlementContentIssue[] => {
  const seen = new Set<string>();
  const issues: SettlementContentIssue[] = [];
  values.forEach((value, index) => {
    if (!ID_PATTERN.test(value.id)) {
      issues.push({ path: `${path}[${index}].id`, message: `Invalid stable ID "${value.id}".` });
    }
    if (seen.has(value.id)) {
      issues.push({ path: `${path}[${index}].id`, message: `Duplicate ID "${value.id}".` });
    }
    seen.add(value.id);
  });
  return issues;
};

/** Validated, immutable lookup layer for settlement content. */
export class SettlementContentRegistry {
  private readonly goods = new Map<string, Readonly<SettlementGoodDefinition>>();
  private readonly buildings = new Map<string, Readonly<SettlementBuildingDefinition>>();
  private readonly recipes = new Map<string, Readonly<SettlementRecipeDefinition>>();
  private readonly resourceNodes = new Map<string, Readonly<SettlementResourceNodeDefinition>>();
  private readonly seasonRegions = new Map<string, Readonly<SettlementSeasonRegionDefinition>>();
  private readonly crops = new Map<string, Readonly<SettlementCropDefinition>>();
  private readonly cropPlots = new Map<string, Readonly<SettlementCropPlotDefinition>>();
  private readonly plants = new Map<string, Readonly<SettlementPlantDefinition>>();
  private readonly cultivationPatches = new Map<string, Readonly<SettlementCultivationPatchDefinition>>();
  private readonly animalSpecies = new Map<string, Readonly<SettlementAnimalSpeciesDefinition>>();
  private readonly animalHabitats = new Map<string, Readonly<SettlementAnimalHabitatDefinition>>();

  public constructor(public readonly definitions: Readonly<SettlementContentDefinitionSet>) {
    const issues = SettlementContentRegistry.validate(definitions);
    if (issues.length > 0) {
      throw new Error(
        `Invalid settlement content "${definitions.id}":\n` +
        issues.map((issue) => `- ${issue.path}: ${issue.message}`).join('\n'),
      );
    }
    definitions.goods.forEach((definition) => this.goods.set(definition.id, definition));
    definitions.buildings.forEach((definition) => this.buildings.set(definition.id, definition));
    definitions.recipes.forEach((definition) => this.recipes.set(definition.id, definition));
    definitions.resourceNodes.forEach((definition) => this.resourceNodes.set(definition.id, definition));
    definitions.seasonRegions.forEach((definition) => this.seasonRegions.set(definition.id, definition));
    definitions.crops.forEach((definition) => this.crops.set(definition.id, definition));
    definitions.cropPlots.forEach((definition) => this.cropPlots.set(definition.id, definition));
    (definitions.plants ?? []).forEach((definition) => this.plants.set(definition.id, definition));
    (definitions.cultivationPatches ?? []).forEach((definition) =>
      this.cultivationPatches.set(definition.id, definition));
    (definitions.animalSpecies ?? []).forEach((definition) =>
      this.animalSpecies.set(definition.id, definition));
    (definitions.animalHabitats ?? []).forEach((definition) =>
      this.animalHabitats.set(definition.id, definition));
  }

  public getGood(id: string): Readonly<SettlementGoodDefinition> | undefined {
    return this.goods.get(id);
  }

  public getBuilding(id: string): Readonly<SettlementBuildingDefinition> | undefined {
    return this.buildings.get(id);
  }

  public getRecipe(id: string): Readonly<SettlementRecipeDefinition> | undefined {
    return this.recipes.get(id);
  }

  public getResourceNode(id: string): Readonly<SettlementResourceNodeDefinition> | undefined {
    return this.resourceNodes.get(id);
  }

  public getSeasonRegion(id: string): Readonly<SettlementSeasonRegionDefinition> | undefined {
    return this.seasonRegions.get(id);
  }

  public getCrop(id: string): Readonly<SettlementCropDefinition> | undefined {
    return this.crops.get(id);
  }

  public getCropPlot(id: string): Readonly<SettlementCropPlotDefinition> | undefined {
    return this.cropPlots.get(id);
  }

  public getPlant(id: string): Readonly<SettlementPlantDefinition> | undefined {
    return this.plants.get(id);
  }

  public getCultivationPatch(id: string): Readonly<SettlementCultivationPatchDefinition> | undefined {
    return this.cultivationPatches.get(id);
  }

  public getAnimalSpecies(id: string): Readonly<SettlementAnimalSpeciesDefinition> | undefined {
    return this.animalSpecies.get(id);
  }

  public getAnimalHabitat(id: string): Readonly<SettlementAnimalHabitatDefinition> | undefined {
    return this.animalHabitats.get(id);
  }

  public recipesForBuilding(buildingId: string): readonly Readonly<SettlementRecipeDefinition>[] {
    return this.definitions.recipes.filter((recipe) => recipe.buildingId === buildingId);
  }

  public maximumBuildingLevel(buildingId: string): number {
    return this.getBuilding(buildingId)?.stages.at(-1)?.level ?? 0;
  }

  public static validate(
    definitions: Readonly<SettlementContentDefinitionSet>,
  ): readonly SettlementContentIssue[] {
    const issues: SettlementContentIssue[] = [];
    if (!ID_PATTERN.test(definitions.id)) {
      issues.push({ path: 'id', message: `Invalid definition-set ID "${definitions.id}".` });
    }
    issues.push(...duplicateIssues(definitions.goods, 'goods'));
    issues.push(...duplicateIssues(definitions.buildings, 'buildings'));
    issues.push(...duplicateIssues(definitions.recipes, 'recipes'));
    issues.push(...duplicateIssues(definitions.resourceNodes, 'resourceNodes'));
    issues.push(...duplicateIssues(definitions.seasonRegions, 'seasonRegions'));
    issues.push(...duplicateIssues(definitions.crops, 'crops'));
    issues.push(...duplicateIssues(definitions.cropPlots, 'cropPlots'));
    issues.push(...duplicateIssues(definitions.plants ?? [], 'plants'));
    issues.push(...duplicateIssues(definitions.cultivationPatches ?? [], 'cultivationPatches'));
    issues.push(...duplicateIssues(definitions.animalSpecies ?? [], 'animalSpecies'));
    issues.push(...duplicateIssues(definitions.animalHabitats ?? [], 'animalHabitats'));

    const goodIds = new Set(definitions.goods.map((value) => value.id));
    const buildingIds = new Set(definitions.buildings.map((value) => value.id));
    const seasonRegionIds = new Set(definitions.seasonRegions.map((value) => value.id));
    const animalSpeciesIds = new Set((definitions.animalSpecies ?? []).map((value) => value.id));
    definitions.goods.forEach((good, index) => {
      if (!good.displayName.trim()) {
        issues.push({ path: `goods[${index}].displayName`, message: 'Display name is required.' });
      }
      if (!isPositiveInteger(good.maximumWarehouseQuantity)) {
        issues.push({ path: `goods[${index}].maximumWarehouseQuantity`, message: 'Warehouse maximum must be a positive bounded integer.' });
      }
    });

    definitions.buildings.forEach((building, buildingIndex) => {
      const path = `buildings[${buildingIndex}]`;
      if (!building.displayName.trim() || !building.worldObjectId.trim()) {
        issues.push({ path, message: 'Display name and world object ID are required.' });
      }
      if (!Number.isSafeInteger(building.initialStructuralLevel) || building.initialStructuralLevel < 0) {
        issues.push({ path: `${path}.initialStructuralLevel`, message: 'Initial level must be a non-negative integer.' });
      }
      let expectedLevel = building.initialStructuralLevel + 1;
      building.stages.forEach((stage: SettlementBuildingStageDefinition, stageIndex) => {
        const stagePath = `${path}.stages[${stageIndex}]`;
        if (stage.level !== expectedLevel) {
          issues.push({ path: `${stagePath}.level`, message: `Expected contiguous level ${expectedLevel}.` });
        }
        expectedLevel += 1;
        if (!stage.displayName.trim()) {
          issues.push({ path: `${stagePath}.displayName`, message: 'Display name is required.' });
        }
        if (!Number.isFinite(stage.workDurationSeconds) || stage.workDurationSeconds < 0 || stage.workDurationSeconds > 86_400) {
          issues.push({ path: `${stagePath}.workDurationSeconds`, message: 'Work duration must be between 0 and 86400 seconds.' });
        }
        issues.push(...issueAmounts(stage.costs, `${stagePath}.costs`, goodIds, true));
      });
      const maximumLevel = building.stages.at(-1)?.level ??
        building.initialStructuralLevel;
      if (
        building.serviceMinimumLevel !== undefined &&
        (!Number.isSafeInteger(building.serviceMinimumLevel) ||
          building.serviceMinimumLevel < building.initialStructuralLevel ||
          building.serviceMinimumLevel > maximumLevel)
      ) {
        issues.push({
          path: `${path}.serviceMinimumLevel`,
          message: `Service level must be between ${building.initialStructuralLevel} and ${maximumLevel}.`,
        });
      }
    });

    definitions.recipes.forEach((recipe, recipeIndex) => {
      const path = `recipes[${recipeIndex}]`;
      const building = definitions.buildings.find((value) => value.id === recipe.buildingId);
      if (!building) {
        issues.push({ path: `${path}.buildingId`, message: `Unknown building "${recipe.buildingId}".` });
      } else {
        const maximumLevel = building.stages.at(-1)?.level ?? building.initialStructuralLevel;
        if (!Number.isSafeInteger(recipe.minimumBuildingLevel) || recipe.minimumBuildingLevel < 0 || recipe.minimumBuildingLevel > maximumLevel) {
          issues.push({ path: `${path}.minimumBuildingLevel`, message: `Level must be between 0 and ${maximumLevel}.` });
        }
        if (recipe.requiresAssignedNpcPresent && !building.assignedNpcId) {
          issues.push({ path: `${path}.requiresAssignedNpcPresent`, message: 'Recipe requires staff but the building has no assigned NPC.' });
        }
      }
      if (!Number.isFinite(recipe.durationSeconds) || recipe.durationSeconds <= 0 || recipe.durationSeconds > 86_400) {
        issues.push({ path: `${path}.durationSeconds`, message: 'Duration must be greater than 0 and at most 86400 seconds.' });
      }
      issues.push(...issueAmounts(recipe.inputs, `${path}.inputs`, goodIds, false));
      issues.push(...issueAmounts(recipe.outputs, `${path}.outputs`, goodIds, false));
    });

    definitions.seasonRegions.forEach((region, index) => {
      if (!region.displayName.trim()) {
        issues.push({ path: `seasonRegions[${index}].displayName`, message: 'Display name is required.' });
      }
    });
    definitions.resourceNodes.forEach((node, index) => {
      const path = `resourceNodes[${index}]`;
      if (!node.displayName.trim()) {
        issues.push({ path: `${path}.displayName`, message: 'Display name is required.' });
      }
      if (!seasonRegionIds.has(node.regionId)) {
        issues.push({ path: `${path}.regionId`, message: `Unknown season region "${node.regionId}".` });
      }
      if (!Number.isFinite(node.x) || !Number.isFinite(node.z)) {
        issues.push({ path, message: 'Resource node position must be finite.' });
      }
      if (!Number.isFinite(node.interactionRadius) || node.interactionRadius <= 0 || node.interactionRadius > 32) {
        issues.push({ path: `${path}.interactionRadius`, message: 'Interaction radius must be between 0 and 32 metres.' });
      }
      if (
        node.regrowthSeconds !== undefined &&
        (!Number.isFinite(node.regrowthSeconds) || node.regrowthSeconds <= 0 || node.regrowthSeconds > 31_536_000)
      ) {
        issues.push({ path: `${path}.regrowthSeconds`, message: 'Regrowth must be positive and at most one year.' });
      }
      issues.push(...issueAmounts(node.yields, `${path}.yields`, goodIds, false));
    });
    definitions.crops.forEach((crop, index) => {
      const path = `crops[${index}]`;
      if (!crop.displayName.trim()) {
        issues.push({ path: `${path}.displayName`, message: 'Display name is required.' });
      }
      if (!goodIds.has(crop.unlockGoodId)) {
        issues.push({ path: `${path}.unlockGoodId`, message: `Unknown unlock good "${crop.unlockGoodId}".` });
      }
      if (
        crop.unlockAfterSeasonHarvests &&
        (!Number.isSafeInteger(crop.unlockAfterSeasonHarvests.count) ||
          crop.unlockAfterSeasonHarvests.count <= 0)
      ) {
        issues.push({
          path: `${path}.unlockAfterSeasonHarvests.count`,
          message: 'Season harvest prerequisite must be a positive integer.',
        });
      }
      if (!Number.isFinite(crop.growthSeconds) || crop.growthSeconds <= 0 || crop.growthSeconds > 31_536_000) {
        issues.push({ path: `${path}.growthSeconds`, message: 'Growth must be positive and at most one year.' });
      }
      issues.push(...issueAmounts(crop.harvestOutputs, `${path}.harvestOutputs`, goodIds, false));
    });
    definitions.cropPlots.forEach((plot, index) => {
      const path = `cropPlots[${index}]`;
      if (!plot.displayName.trim()) {
        issues.push({ path: `${path}.displayName`, message: 'Display name is required.' });
      }
      if (!seasonRegionIds.has(plot.regionId)) {
        issues.push({ path: `${path}.regionId`, message: `Unknown season region "${plot.regionId}".` });
      }
      if (!Number.isFinite(plot.x) || !Number.isFinite(plot.z)) {
        issues.push({ path, message: 'Crop plot position must be finite.' });
      }
      if (!Number.isFinite(plot.interactionRadius) || plot.interactionRadius <= 0 || plot.interactionRadius > 32) {
        issues.push({ path: `${path}.interactionRadius`, message: 'Interaction radius must be between 0 and 32 metres.' });
      }
    });

    (definitions.plants ?? []).forEach((plant, index) => {
      const path = `plants[${index}]`;
      if (!plant.displayName.trim()) {
        issues.push({ path: `${path}.displayName`, message: 'Display name is required.' });
      }
      if (plant.requiredGround.length === 0) {
        issues.push({ path: `${path}.requiredGround`, message: 'At least one compatible ground kind is required.' });
      }
      if (plant.unlockGoodId && !goodIds.has(plant.unlockGoodId)) {
        issues.push({ path: `${path}.unlockGoodId`, message: `Unknown unlock good "${plant.unlockGoodId}".` });
      }
      if (!Number.isFinite(plant.growthSeconds) || plant.growthSeconds <= 0 || plant.growthSeconds > 31_536_000) {
        issues.push({ path: `${path}.growthSeconds`, message: 'Growth must be positive and at most one year.' });
      }
      if (plant.lifecycle === 'PERENNIAL_REGROW' &&
        (!Number.isFinite(plant.regrowthSeconds) || (plant.regrowthSeconds ?? 0) <= 0 ||
          (plant.regrowthSeconds ?? 0) > 31_536_000)) {
        issues.push({ path: `${path}.regrowthSeconds`, message: 'Perennials require positive regrowth of at most one year.' });
      }
      issues.push(...issueAmounts(plant.harvestOutputs, `${path}.harvestOutputs`, goodIds, false));
    });

    (definitions.cultivationPatches ?? []).forEach((patch, index) => {
      const path = `cultivationPatches[${index}]`;
      if (!patch.displayName.trim()) {
        issues.push({ path: `${path}.displayName`, message: 'Display name is required.' });
      }
      if (!seasonRegionIds.has(patch.regionId)) {
        issues.push({ path: `${path}.regionId`, message: `Unknown season region "${patch.regionId}".` });
      }
      if (!Number.isFinite(patch.x) || !Number.isFinite(patch.z)) {
        issues.push({ path, message: 'Cultivation patch position must be finite.' });
      }
      if (!Number.isFinite(patch.sizeMetres) || patch.sizeMetres < 1 || patch.sizeMetres > 64) {
        issues.push({ path: `${path}.sizeMetres`, message: 'Patch size must be between 1 and 64 metres.' });
      }
      if (patch.subdivision !== 3) {
        issues.push({ path: `${path}.subdivision`, message: 'The cozy cultivation foundation requires a 3x3 subdivision.' });
      }
      if (!Number.isFinite(patch.interactionRadius) || patch.interactionRadius <= 0 || patch.interactionRadius > 32) {
        issues.push({ path: `${path}.interactionRadius`, message: 'Interaction radius must be between 0 and 32 metres.' });
      }
      if (patch.initialLeafDensity !== undefined &&
        (!Number.isFinite(patch.initialLeafDensity) || patch.initialLeafDensity < 0 || patch.initialLeafDensity > 1)) {
        issues.push({ path: `${path}.initialLeafDensity`, message: 'Leaf density must be between 0 and 1.' });
      }
    });

    (definitions.animalSpecies ?? []).forEach((species, index) => {
      const path = `animalSpecies[${index}]`;
      const [youngAt, adultAt] = species.growthStageSeconds;
      if (!species.displayName.trim()) {
        issues.push({ path: `${path}.displayName`, message: 'Display name is required.' });
      }
      if (!Number.isFinite(youngAt) || !Number.isFinite(adultAt) ||
        youngAt <= 0 || adultAt <= youngAt || adultAt > 31_536_000) {
        issues.push({ path: `${path}.growthStageSeconds`, message: 'Animal stages must be positive, ascending and at most one year.' });
      }
      if (!Number.isFinite(species.product.intervalSeconds) ||
        species.product.intervalSeconds <= 0 || species.product.intervalSeconds > 31_536_000) {
        issues.push({ path: `${path}.product.intervalSeconds`, message: 'Product interval must be positive and at most one year.' });
      }
      issues.push(...issueAmounts(species.product.outputs, `${path}.product.outputs`, goodIds, false));
    });

    (definitions.animalHabitats ?? []).forEach((habitat, index) => {
      const path = `animalHabitats[${index}]`;
      if (!habitat.displayName.trim()) {
        issues.push({ path: `${path}.displayName`, message: 'Display name is required.' });
      }
      if (!seasonRegionIds.has(habitat.regionId)) {
        issues.push({ path: `${path}.regionId`, message: `Unknown season region "${habitat.regionId}".` });
      }
      if (!animalSpeciesIds.has(habitat.speciesId)) {
        issues.push({ path: `${path}.speciesId`, message: `Unknown animal species "${habitat.speciesId}".` });
      }
      if (!Number.isFinite(habitat.x) || !Number.isFinite(habitat.z)) {
        issues.push({ path, message: 'Animal habitat position must be finite.' });
      }
      if (!Number.isFinite(habitat.interactionRadius) || habitat.interactionRadius <= 0 || habitat.interactionRadius > 32) {
        issues.push({ path: `${path}.interactionRadius`, message: 'Interaction radius must be between 0 and 32 metres.' });
      }
      if (!Number.isSafeInteger(habitat.initialAnimalCount) || habitat.initialAnimalCount <= 0 || habitat.initialAnimalCount > 32) {
        issues.push({ path: `${path}.initialAnimalCount`, message: 'Initial animal count must be between 1 and 32.' });
      }
      let expectedLevel = 1;
      let previousCapacity = habitat.initialAnimalCount;
      habitat.upgrades.forEach((upgrade, upgradeIndex) => {
        const upgradePath = `${path}.upgrades[${upgradeIndex}]`;
        if (upgrade.level !== expectedLevel) {
          issues.push({ path: `${upgradePath}.level`, message: `Expected contiguous level ${expectedLevel}.` });
        }
        expectedLevel += 1;
        if (!upgrade.displayName.trim()) {
          issues.push({ path: `${upgradePath}.displayName`, message: 'Display name is required.' });
        }
        if (!Number.isSafeInteger(upgrade.capacity) || upgrade.capacity < previousCapacity || upgrade.capacity > 64) {
          issues.push({ path: `${upgradePath}.capacity`, message: 'Capacity must not decrease and may be at most 64.' });
        }
        previousCapacity = upgrade.capacity;
        if (!Number.isFinite(upgrade.productIntervalMultiplier) ||
          upgrade.productIntervalMultiplier < 0.25 || upgrade.productIntervalMultiplier > 1) {
          issues.push({ path: `${upgradePath}.productIntervalMultiplier`, message: 'Interval multiplier must be between 0.25 and 1.' });
        }
        if (!Number.isSafeInteger(upgrade.productQuantityBonus) ||
          upgrade.productQuantityBonus < 0 || upgrade.productQuantityBonus > 10) {
          issues.push({ path: `${upgradePath}.productQuantityBonus`, message: 'Quantity bonus must be between 0 and 10.' });
        }
        issues.push(...issueAmounts(upgrade.costs, `${upgradePath}.costs`, goodIds, true));
      });
    });

    const train = definitions.train;
    if (!train || !ID_PATTERN.test(train.id) || !ID_PATTERN.test(train.manifestId)) {
      issues.push({ path: 'train', message: 'Train and manifest require stable IDs.' });
    } else {
      if (!buildingIds.has(train.stationBuildingId)) {
        issues.push({ path: 'train.stationBuildingId', message: 'Unknown station building.' });
      }
      issues.push(...issueAmounts(train.manifestGoods, 'train.manifestGoods', goodIds, false));
      issues.push(...issueAmounts(train.returnGoods, 'train.returnGoods', goodIds, false));
      if (
        !Number.isFinite(train.outboundDurationSeconds) ||
        train.outboundDurationSeconds <= 0 ||
        !Number.isFinite(train.returnDurationSeconds) ||
        train.returnDurationSeconds <= 0
      ) {
        issues.push({ path: 'train', message: 'Train journey durations must be positive.' });
      }
    }

    const externalIds = new Set<string>();
    definitions.externallyObtainableGoodIds.forEach((goodId, index) => {
      if (!goodIds.has(goodId)) {
        issues.push({ path: `externallyObtainableGoodIds[${index}]`, message: `Unknown good "${goodId}".` });
      }
      if (externalIds.has(goodId)) {
        issues.push({ path: `externallyObtainableGoodIds[${index}]`, message: `Duplicate external source "${goodId}".` });
      }
      externalIds.add(goodId);
    });

    if (issues.length === 0) {
      issues.push(...this.validateReachability(definitions, externalIds, buildingIds));
    }
    return issues;
  }

  private static validateReachability(
    definitions: Readonly<SettlementContentDefinitionSet>,
    externallyObtainable: ReadonlySet<string>,
    buildingIds: ReadonlySet<string>,
  ): readonly SettlementContentIssue[] {
    const reachableGoods = new Set(externallyObtainable);
    const reachableLevels = new Map(
      definitions.buildings.map((building) => [building.id, building.initialStructuralLevel]),
    );
    let changed = true;
    while (changed) {
      changed = false;
      for (const building of definitions.buildings) {
        const currentLevel = reachableLevels.get(building.id) ?? 0;
        const stage = building.stages.find((candidate) => candidate.level === currentLevel + 1);
        if (stage && stage.costs.every((cost) => reachableGoods.has(cost.goodId))) {
          reachableLevels.set(building.id, stage.level);
          changed = true;
        }
      }
      for (const recipe of definitions.recipes) {
        if (!buildingIds.has(recipe.buildingId)) continue;
        if ((reachableLevels.get(recipe.buildingId) ?? 0) < recipe.minimumBuildingLevel) continue;
        if (!recipe.inputs.every((input) => reachableGoods.has(input.goodId))) continue;
        for (const output of recipe.outputs) {
          if (!reachableGoods.has(output.goodId)) {
            reachableGoods.add(output.goodId);
            changed = true;
          }
        }
      }
      for (const crop of definitions.crops) {
        if (!reachableGoods.has(crop.unlockGoodId)) continue;
        for (const output of crop.harvestOutputs) {
          if (!reachableGoods.has(output.goodId)) {
            reachableGoods.add(output.goodId);
            changed = true;
          }
        }
      }
      for (const plant of definitions.plants ?? []) {
        if (plant.unlockGoodId && !reachableGoods.has(plant.unlockGoodId)) continue;
        for (const output of plant.harvestOutputs) {
          if (!reachableGoods.has(output.goodId)) {
            reachableGoods.add(output.goodId);
            changed = true;
          }
        }
      }
      for (const species of definitions.animalSpecies ?? []) {
        for (const output of species.product.outputs) {
          if (!reachableGoods.has(output.goodId)) {
            reachableGoods.add(output.goodId);
            changed = true;
          }
        }
      }
    }
    const issues: SettlementContentIssue[] = [];
    for (const building of definitions.buildings) {
      const maximumLevel = building.stages.at(-1)?.level ?? building.initialStructuralLevel;
      if ((reachableLevels.get(building.id) ?? 0) < maximumLevel) {
        issues.push({
          path: `buildings.${building.id}`,
          message: `Progression cannot reach structural level ${maximumLevel}.`,
        });
      }
    }
    return issues;
  }
}
