import { clamp } from '../utils/math';

export type SnowObstacleOwner =
  | 'TOWN'
  | 'PARK'
  | 'WORLD_ASSET'
  | 'TERRAIN'
  | 'GAMEPLAY';

export interface SnowObstacleDescriptor {
  readonly id: string;
  readonly owner: SnowObstacleOwner;
  readonly x: number;
  readonly z: number;
  readonly width: number;
  readonly depth: number;
  readonly height: number;
  readonly yawRadians?: number;
  /** 0 is a solid wall, 1 lets all wind-driven snow through. */
  readonly porosity?: number;
  /** Warm obstacles receive no persistent ground bank. */
  readonly warmth?: number;
  readonly snowCatch?: number;
}

export interface SnowObstacleDriftResult {
  readonly processed: number;
  readonly shaped: number;
  readonly movedSnow: number;
}

const SERVICE_INTERVAL_SECONDS = 0.2;
// Snow relocation settles a real 25 cm mass field. Two obstacles per service
// tick keep authored wind banks converging in the background without letting
// eight independent ridge operations monopolize one animation frame.
const SERVICE_BUDGET = 2;

const validDescriptor = (
  descriptor: Readonly<SnowObstacleDescriptor>,
): boolean =>
  descriptor.id.length > 0 &&
  [
    descriptor.x,
    descriptor.z,
    descriptor.width,
    descriptor.depth,
    descriptor.height,
  ].every(Number.isFinite) &&
  descriptor.width > 0 &&
  descriptor.depth > 0 &&
  descriptor.height > 0;

/**
 * One low-frequency drift contract for built-in and authored obstacles.
 *
 * The operation converges toward a stable leeward depth advantage. It never
 * creates snow: callers provide the canonical mass relocation function.
 */
export class SnowObstacleRegistry {
  private readonly descriptors = new Map<string, SnowObstacleDescriptor>();
  private orderedIds: readonly string[] = [];
  private cursor = 0;
  private accumulator = 0;

  public replaceOwner(
    owner: SnowObstacleOwner,
    descriptors: readonly Readonly<SnowObstacleDescriptor>[],
  ): void {
    for (const [id, descriptor] of this.descriptors) {
      if (descriptor.owner === owner) this.descriptors.delete(id);
    }
    for (const descriptor of descriptors) {
      if (descriptor.owner !== owner || !validDescriptor(descriptor)) continue;
      this.descriptors.set(descriptor.id, {
        ...descriptor,
        width: clamp(descriptor.width, 0.08, 80),
        depth: clamp(descriptor.depth, 0.08, 80),
        height: clamp(descriptor.height, 0.08, 80),
        yawRadians: descriptor.yawRadians ?? 0,
        porosity: clamp(descriptor.porosity ?? 0, 0, 1),
        warmth: clamp(descriptor.warmth ?? 0, 0, 1),
        snowCatch: clamp(descriptor.snowCatch ?? 1, 0, 2),
      });
    }
    this.rebuildOrder();
  }

  public upsert(descriptor: Readonly<SnowObstacleDescriptor>): boolean {
    if (!validDescriptor(descriptor)) return false;
    this.descriptors.set(descriptor.id, {
      ...descriptor,
      yawRadians: descriptor.yawRadians ?? 0,
      porosity: clamp(descriptor.porosity ?? 0, 0, 1),
      warmth: clamp(descriptor.warmth ?? 0, 0, 1),
      snowCatch: clamp(descriptor.snowCatch ?? 1, 0, 2),
    });
    this.rebuildOrder();
    return true;
  }

  public remove(id: string): boolean {
    const removed = this.descriptors.delete(id);
    if (removed) this.rebuildOrder();
    return removed;
  }

  public count(): number {
    return this.descriptors.size;
  }

  public list(): readonly Readonly<SnowObstacleDescriptor>[] {
    return this.orderedIds.flatMap((id) => {
      const descriptor = this.descriptors.get(id);
      return descriptor ? [{ ...descriptor }] : [];
    });
  }

  public service(
    deltaSeconds: number,
    wind: Readonly<{ x: number; z: number; strength: number }>,
    sampleDepth: (x: number, z: number) => number,
    relocateSnow: (
      sourceX: number,
      sourceZ: number,
      destinationX: number,
      destinationZ: number,
      radius: number,
      maximumMass: number,
      maximumDepth: number,
      ridgeLength: number,
      ridgePoints: number,
    ) => number,
    focus?: Readonly<{ x: number; z: number; radius: number }>,
  ): SnowObstacleDriftResult {
    this.accumulator += clamp(deltaSeconds, 0, 0.25);
    if (
      this.accumulator < SERVICE_INTERVAL_SECONDS ||
      this.orderedIds.length === 0
    ) return { processed: 0, shaped: 0, movedSnow: 0 };
    const elapsed = this.accumulator;
    this.accumulator = 0;
    const windLength = Math.hypot(wind.x, wind.z);
    const strength = clamp(wind.strength, 0, 2.8);
    if (windLength < 0.0001 || strength < 0.08) {
      return { processed: 0, shaped: 0, movedSnow: 0 };
    }
    const windX = wind.x / windLength;
    const windZ = wind.z / windLength;
    let processed = 0;
    let shaped = 0;
    let movedSnow = 0;
    for (
      let serviced = 0;
      serviced < Math.min(SERVICE_BUDGET, this.orderedIds.length);
      serviced += 1
    ) {
      const id = this.orderedIds[this.cursor % this.orderedIds.length]!;
      this.cursor = (this.cursor + 1) % this.orderedIds.length;
      const obstacle = this.descriptors.get(id);
      if (!obstacle || (obstacle.warmth ?? 0) >= 0.72) continue;
      if (
        focus &&
        Math.hypot(obstacle.x - focus.x, obstacle.z - focus.z) > focus.radius
      ) continue;
      processed += 1;
      const yaw = obstacle.yawRadians ?? 0;
      const localWindX = windX * Math.cos(yaw) - windZ * Math.sin(yaw);
      const localWindZ = windX * Math.sin(yaw) + windZ * Math.cos(yaw);
      const projectedSpan =
        Math.abs(localWindX) * obstacle.width +
        Math.abs(localWindZ) * obstacle.depth;
      const footprint = clamp(
        Math.max(0.15, projectedSpan),
        0.15,
        18,
      );
      const porosity = clamp(obstacle.porosity ?? 0, 0, 1);
      const catchStrength = clamp(obstacle.snowCatch ?? 1, 0, 2);
      const slenderObstacle = footprint < 0.7;
      const targetLeeAdvantage = clamp(
        (0.035 + obstacle.height * 0.027 + footprint * 0.012) *
          strength * (1 - porosity * 0.82) * catchStrength,
        0.025,
        slenderObstacle ? 0.24 : 0.72,
      );
      // A sub-grid pole cannot form a stable radial mound on a 25 cm field.
      // Give every obstacle a multi-sample footprint and trail it downwind,
      // yielding one broad low ridge rather than repeatedly feeding one peak.
      const radius = clamp(
        footprint * (slenderObstacle ? 1.6 : 0.3),
        slenderObstacle ? 0.52 : 0.68,
        1.75,
      );
      const offset = footprint * 0.5 + radius * 0.42;
      const sourceX = obstacle.x - windX * offset;
      const sourceZ = obstacle.z - windZ * offset;
      const destinationX = obstacle.x + windX * offset;
      const destinationZ = obstacle.z + windZ * offset;
      const sourceDepth = sampleDepth(sourceX, sourceZ);
      const destinationDepth = sampleDepth(destinationX, destinationZ);
      const deficit = targetLeeAdvantage - (destinationDepth - sourceDepth);
      if (deficit <= 0.016 || sourceDepth <= 0.075) continue;
      const request = Math.min(
        slenderObstacle ? 0.28 : 1.8,
        deficit * Math.PI * radius * radius * 0.5 *
          clamp(elapsed / SERVICE_INTERVAL_SECONDS, 0.7, 1.3),
      );
      const ridgePoints = slenderObstacle ? 3 : 4;
      const ridgeLength = clamp(
        footprint * 0.18 + obstacle.height * 0.075,
        0.45,
        2.2,
      );
      const bankCap = Math.max(sourceDepth, destinationDepth) +
        targetLeeAdvantage * 1.06;
      const moved = clamp(
        relocateSnow(
          sourceX,
          sourceZ,
          destinationX,
          destinationZ,
          radius,
          request,
          bankCap,
          ridgeLength,
          ridgePoints,
        ),
        0,
        request,
      );
      if (moved <= 0.00001) continue;
      shaped += 1;
      movedSnow += moved;
    }
    return { processed, shaped, movedSnow };
  }

  private rebuildOrder(): void {
    this.orderedIds = [...this.descriptors.keys()].sort();
    this.cursor = this.orderedIds.length > 0
      ? this.cursor % this.orderedIds.length
      : 0;
  }
}
