import type { EmergentWorldRegistry } from './EmergentWorldRegistry';
import type { IncidentSystem } from './IncidentSystem';
import type { NpcSimulationSystem } from './NpcSimulationSystem';
import type { RoadConditionSystem } from './RoadConditionSystem';
import type { ServiceSimulationSystem } from './ServiceSimulationSystem';
import type { TravelSystem } from './TravelSystem';
import type {
  StoryQuestActionDefinition,
  StoryQuestRuntimeState,
  StoryQuestStatus,
  StoryWorldConditionDefinition,
} from './EmergentWorldTypes';

export interface StoryQuestTransition {
  questId: string;
  previousStatus: StoryQuestStatus;
  status: StoryQuestStatus;
  previousStageId?: string;
  stageId?: string;
  occurredAt: number;
  reason: string;
}

interface StoryQuestSaveData { version: 1; states: StoryQuestRuntimeState[]; }

export type StoryWorldFactResolver = (
  factId: string,
) => string | number | boolean | undefined;

const cloneState = (state: Readonly<StoryQuestRuntimeState>): StoryQuestRuntimeState => ({
  ...state,
  appliedActionIds: [...state.appliedActionIds],
});

/**
 * A deliberately small authored-story layer. It observes real domain state;
 * it does not manufacture road, travel, service or incident outcomes.
 */
export class StoryQuestSystem {
  private readonly states = new Map<string, StoryQuestRuntimeState>();

  public constructor(
    private readonly registry: EmergentWorldRegistry,
    private readonly roads: RoadConditionSystem,
    private readonly travel: TravelSystem,
    private readonly npcs: NpcSimulationSystem,
    private readonly services: ServiceSimulationSystem,
    private readonly incidents: IncidentSystem,
    saved?: unknown,
    private readonly resolveWorldFact: StoryWorldFactResolver = () => undefined,
  ) {
    for (const definition of registry.definitions.storyQuests) {
      const startsImmediately = definition.autoStart &&
        !(definition.startConditions?.length);
      this.states.set(definition.id, {
        questId: definition.id,
        status: startsImmediately ? 'ACTIVE' : 'LOCKED',
        currentStageId: startsImmediately ? definition.initialStageId : undefined,
        startedAt: startsImmediately ? 0 : undefined,
        stageEnteredAt: startsImmediately ? 0 : undefined,
        appliedActionIds: [],
      });
    }
    this.importState(saved);
  }

  public start(questId: string, simulationTime: number): boolean {
    const definition = this.registry.getStoryQuest(questId);
    const state = this.states.get(questId);
    if (!definition || !state || state.status !== 'LOCKED') return false;
    state.status = 'ACTIVE';
    state.currentStageId = definition.initialStageId;
    state.startedAt = simulationTime;
    state.stageEnteredAt = simulationTime;
    return true;
  }

  public cancel(questId: string, simulationTime: number): boolean {
    const state = this.states.get(questId);
    if (!state || state.status !== 'ACTIVE') return false;
    state.status = 'CANCELLED';
    state.cancelledAt = simulationTime;
    return true;
  }

  public update(simulationTime: number): readonly StoryQuestTransition[] {
    const transitions: StoryQuestTransition[] = [];
    for (const definition of this.registry.definitions.storyQuests) {
      const state = this.states.get(definition.id)!;
      if (
        state.status === 'LOCKED' &&
        definition.startConditions?.length &&
        definition.startConditions.every((condition) =>
          this.conditionMet(condition))
      ) {
        if (this.start(definition.id, simulationTime)) {
          transitions.push({
            questId: definition.id,
            previousStatus: 'LOCKED',
            status: 'ACTIVE',
            stageId: definition.initialStageId,
            occurredAt: simulationTime,
            reason: 'START_CONDITIONS_MET',
          });
        }
      }
      if (state.status !== 'ACTIVE' || !state.currentStageId) continue;
      // The bound supports already-satisfied save migrations without allowing a content cycle to hang a tick.
      for (let pass = 0; pass < Math.min(8, definition.stages.length + 1); pass += 1) {
        const stage = definition.stages.find((value) => value.id === state.currentStageId);
        if (!stage) break;
        this.applyStageActions(definition.id, stage.id, stage.onEnterActions ?? [], state, simulationTime);
        if (!stage.completionConditions.every((condition) => this.conditionMet(condition))) break;
        const previousStageId = stage.id;
        this.applyStageActions(
          definition.id,
          stage.id,
          stage.onCompleteActions ?? [],
          state,
          simulationTime,
          'complete',
        );
        if (!stage.nextStageId) {
          state.status = 'COMPLETED';
          state.currentStageId = undefined;
          state.completedAt = simulationTime;
          transitions.push({
            questId: definition.id,
            previousStatus: 'ACTIVE',
            status: 'COMPLETED',
            previousStageId,
            occurredAt: simulationTime,
            reason: 'FINAL_STAGE_CONDITIONS_MET',
          });
          break;
        }
        state.currentStageId = stage.nextStageId;
        state.stageEnteredAt = simulationTime;
        transitions.push({
          questId: definition.id,
          previousStatus: 'ACTIVE',
          status: 'ACTIVE',
          previousStageId,
          stageId: stage.nextStageId,
          occurredAt: simulationTime,
          reason: 'STAGE_CONDITIONS_MET',
        });
      }
    }
    return transitions;
  }

  public getState(questId: string): StoryQuestRuntimeState | undefined {
    const state = this.states.get(questId);
    return state ? cloneState(state) : undefined;
  }

  public getStates(): readonly StoryQuestRuntimeState[] {
    return [...this.states.values()].sort((a, b) => a.questId.localeCompare(b.questId)).map(cloneState);
  }

  public exportState(): StoryQuestSaveData { return { version: 1, states: this.getStates().map(cloneState) }; }

  private conditionMet(condition: Readonly<StoryWorldConditionDefinition>): boolean {
    switch (condition.type) {
      case 'ROAD_STATUS':
        return condition.statuses.includes(this.roads.getState(condition.segmentId)?.status ?? 'UNKNOWN');
      case 'ROAD_TRAVERSABLE': {
        const profile = this.registry.getMobilityProfile(condition.mobilityProfileId);
        return profile ? this.roads.assess(condition.segmentId, profile).traversable : false;
      }
      case 'NPC_AT_LOCATION': {
        const state = this.travel.getState(condition.npcId);
        return state?.status === 'AT_LOCATION' && state.currentLocationId === condition.locationId;
      }
      case 'NPC_TRAVEL_STATUS':
        return condition.statuses.includes(this.travel.getState(condition.npcId)?.status ?? 'AT_LOCATION');
      case 'SERVICE_AVAILABILITY':
        return this.services.getState(condition.serviceId)?.availability === condition.availability;
      case 'INCIDENT_STATUS':
        return this.incidents.getStates().some((incident) =>
          incident.subjectId === condition.subjectId && condition.statuses.includes(incident.status),
        );
      case 'WORLD_FACT': {
        const fact = this.resolveWorldFact(condition.factId);
        if (condition.operator === 'EQUALS') return fact === condition.value;
        if (typeof fact !== 'number' || typeof condition.value !== 'number') return false;
        return condition.operator === 'LESS_THAN_OR_EQUAL'
          ? fact <= condition.value
          : fact >= condition.value;
      }
    }
  }

  private applyStageActions(
    questId: string,
    stageId: string,
    actions: readonly StoryQuestActionDefinition[],
    state: StoryQuestRuntimeState,
    simulationTime: number,
    phase = 'enter',
  ): void {
    actions.forEach((action, index) => {
      const actionId = `${questId}:${stageId}:${phase}:action:${index}`;
      if (state.appliedActionIds.includes(actionId)) return;
      if (action.type === 'SET_NPC_GOAL') {
        this.npcs.setGoalOverride(action.npcId, action.goalId, simulationTime);
      } else if (action.type === 'CREATE_INCIDENT') {
        const location = this.registry.getLocation(action.locationId);
        if (location) {
          this.incidents.createAuthoredIncident({
            incidentId: action.incidentId,
            type: action.incidentType,
            subjectId: action.subjectId,
            location: location.worldPosition,
            simulationTime,
            ruleId: 'story.authored-stage.creates-incident',
            storyCritical: action.storyCritical,
            evidence: (action.evidence ?? []).map((value) => ({
              fact: value.fact,
              subjectId: action.subjectId,
              ...(value.value !== undefined ? { value: value.value } : {}),
            })),
          });
        }
      } else if (action.type === 'RESOLVE_INCIDENT') {
        this.incidents.resolveAuthoredIncident(
          action.incidentId,
          simulationTime,
        );
      }
      state.appliedActionIds.push(actionId);
    });
  }

  private importState(saved: unknown): boolean {
    const candidate = saved as Partial<StoryQuestSaveData> | undefined;
    if (candidate?.version !== 1 || !Array.isArray(candidate.states)) return false;
    for (const state of candidate.states) {
      const definition = this.registry.getStoryQuest(state?.questId);
      if (!definition || !['LOCKED', 'ACTIVE', 'COMPLETED', 'CANCELLED'].includes(state.status)) continue;
      if (state.currentStageId && !definition.stages.some((stage) => stage.id === state.currentStageId)) continue;
      this.states.set(state.questId, cloneState(state));
    }
    return true;
  }
}
