import type { WorldContributionEvent } from '../events/WorldContributionEvent';
import type { WorldDomainEvent } from '../events/WorldDomainEvent';
import type {
  MissionDefinition,
  MissionPrerequisiteDefinition,
  MissionSource,
  MissionStatus,
  PortState,
  RouteState,
} from '../definitions/GameplayTypes';
import {
  ROUTE_OPENNESS_THRESHOLD,
  ROUTE_WIDTH_THRESHOLDS,
} from './RouteRuntimeSystem';
import type { PortClearanceState } from './PortClearanceSystem';

export type MissionTriggerReason =
  | 'SCRIPTED'
  | 'ROUTE_CLOSED'
  | 'ROUTE_TOO_NARROW'
  | 'ROUTE_NEEDS_SERVICE'
  | 'PORT_NEEDS_ACCESS'
  | 'WORLD_EVENT';

export interface MissionRuntimeState {
  missionId: string;
  source: MissionSource;
  status: MissionStatus;
  triggerReason: MissionTriggerReason;
  linkedWorldState?: {
    type: 'ROUTE' | 'PORT' | 'POI';
    id: string;
  };
  offeredAt?: number;
  acceptedAt?: number;
  completedAt?: number;
  expiredAt?: number;
  cancelledAt?: number;
}

export interface MissionWorldSnapshot {
  routes: readonly RouteState[];
  ports: readonly PortState[];
  portClearances: readonly PortClearanceState[];
  discoveredPoiIds: ReadonlySet<string>;
  ownedUpgradeIds: ReadonlySet<string>;
}

interface SerializedMissionRuntimeState
  extends Omit<MissionRuntimeState, 'status'> {
  status: MissionStatus | 'AVAILABLE';
}

export interface MissionSystemSaveData {
  version: 1 | 2;
  missions: SerializedMissionRuntimeState[];
}

export interface MissionUpdateResult {
  offeredMissionIds: string[];
  availableMissionIds: string[];
  completedMissionIds: string[];
  expiredMissionIds: string[];
  contributionEvents: WorldContributionEvent[];
}

const linkedWorldState = (
  definition: Readonly<MissionDefinition>,
): MissionRuntimeState['linkedWorldState'] => {
  if (definition.linkedRouteId) {
    return {
      type: 'ROUTE',
      id: definition.linkedRouteId,
    };
  }
  if (definition.linkedPortId) {
    return {
      type: 'PORT',
      id: definition.linkedPortId,
    };
  }
  if (definition.linkedPoiId) {
    return {
      type: 'POI',
      id: definition.linkedPoiId,
    };
  }
  return undefined;
};

const linkedRoutes = (
  definition: Readonly<MissionDefinition>,
  snapshot: Readonly<MissionWorldSnapshot>,
): readonly RouteState[] => {
  const routeIds =
    definition.linkedRouteIds ??
    (definition.linkedRouteId
      ? [definition.linkedRouteId]
      : []);
  const wanted = new Set(routeIds);
  return snapshot.routes.filter((route) =>
    wanted.has(route.id),
  );
};

const isOpenRoute = (route: Readonly<RouteState>): boolean =>
  route.openness >= ROUTE_OPENNESS_THRESHOLD &&
  route.measuredWidth >= ROUTE_WIDTH_THRESHOLDS.small;

const hasClearedPort = (
  portId: string,
  snapshot: Readonly<MissionWorldSnapshot>,
): boolean =>
  snapshot.portClearances.some(
    (state) =>
      state.portId === portId &&
      state.status === 'CLEARED',
  );

const hasRequiredPortClearance = (
  definition: Readonly<MissionDefinition>,
  snapshot: Readonly<MissionWorldSnapshot>,
): boolean => {
  const requiresClearance =
    definition.requiresPortClearance ??
    (definition.type === 'OPEN_ROUTE' &&
      Boolean(definition.linkedPortId));
  return (
    !requiresClearance ||
    Boolean(
      definition.linkedPortId &&
        hasClearedPort(
          definition.linkedPortId,
          snapshot,
        ),
    )
  );
};

const finiteTime = (
  value: number | undefined,
): number | undefined =>
  value === undefined || !Number.isFinite(value)
    ? undefined
    : Math.max(0, value);

export class MissionSystem {
  private readonly definitions = new Map<
    string,
    MissionDefinition
  >();
  private readonly states =
    new Map<string, MissionRuntimeState>();

  public constructor(
    definitions: readonly MissionDefinition[],
    saved?: Readonly<MissionSystemSaveData>,
  ) {
    for (const definition of definitions) {
      this.definitions.set(definition.id, definition);
      const initiallyOffered =
        definition.source === 'SCRIPTED' &&
        (definition.prerequisites?.length ?? 0) === 0;
      this.states.set(definition.id, {
        missionId: definition.id,
        source: definition.source,
        status: initiallyOffered ? 'OFFERED' : 'LOCKED',
        triggerReason:
          definition.source === 'SCRIPTED'
            ? 'SCRIPTED'
            : 'WORLD_EVENT',
        linkedWorldState: linkedWorldState(definition),
        offeredAt: initiallyOffered ? 0 : undefined,
      });
    }
    if (saved) this.importState(saved);
  }

  public getDefinition(
    missionId: string,
  ): MissionDefinition | undefined {
    return this.definitions.get(missionId);
  }

  public getState(
    missionId: string,
  ): MissionRuntimeState | undefined {
    const state = this.states.get(missionId);
    return state
      ? {
          ...state,
          linkedWorldState: state.linkedWorldState
            ? { ...state.linkedWorldState }
            : undefined,
        }
      : undefined;
  }

  public getStates(): readonly MissionRuntimeState[] {
    return [...this.states.values()].map((state) => ({
      ...state,
      linkedWorldState: state.linkedWorldState
        ? { ...state.linkedWorldState }
        : undefined,
    }));
  }

  public getOfferedAtPort(
    portId: string,
  ): readonly MissionRuntimeState[] {
    return this.getStates().filter((state) => {
      if (state.status !== 'OFFERED') return false;
      const definition = this.definitions.get(
        state.missionId,
      );
      return Boolean(
        definition?.offerAtPortIds?.includes(portId),
      );
    });
  }

  public getJobsAtPort(
    portId: string,
  ): readonly MissionRuntimeState[] {
    return this.getStates().filter((state) => {
      if (
        state.status !== 'OFFERED' &&
        state.status !== 'ACTIVE'
      ) {
        return false;
      }
      const definition = this.definitions.get(
        state.missionId,
      );
      return Boolean(
        definition?.offerAtPortIds?.includes(portId),
      );
    });
  }

  public accept(
    missionId: string,
    simulationTime: number,
  ): boolean {
    const state = this.states.get(missionId);
    if (!state || state.status !== 'OFFERED') return false;
    state.status = 'ACTIVE';
    state.acceptedAt = Math.max(0, simulationTime);
    return true;
  }

  public cancel(
    missionId: string,
    simulationTime: number,
  ): boolean {
    const state = this.states.get(missionId);
    if (
      !state ||
      (state.status !== 'OFFERED' &&
        state.status !== 'ACTIVE')
    ) {
      return false;
    }
    state.status = 'CANCELLED';
    state.cancelledAt = Math.max(0, simulationTime);
    return true;
  }

  public refreshOffers(
    simulationTime: number,
    snapshot: Readonly<MissionWorldSnapshot>,
  ): readonly string[] {
    const offeredMissionIds: string[] = [];
    for (const definition of this.definitions.values()) {
      const state = this.states.get(definition.id);
      if (
        !state ||
        state.status !== 'LOCKED' ||
        !this.prerequisitesMet(
          definition.prerequisites ?? [],
          snapshot,
        )
      ) {
        continue;
      }
      const reason =
        definition.source === 'SCRIPTED'
          ? 'SCRIPTED'
          : this.simulationTrigger(definition, snapshot);
      if (!reason) continue;
      state.status = 'OFFERED';
      state.triggerReason = reason;
      state.offeredAt = Math.max(0, simulationTime);
      offeredMissionIds.push(definition.id);
    }
    return offeredMissionIds;
  }

  public update(
    simulationTime: number,
    snapshot: Readonly<MissionWorldSnapshot>,
    contributions: readonly WorldContributionEvent[] = [],
    domainEvents: readonly WorldDomainEvent[] = [],
  ): MissionUpdateResult {
    const offeredMissionIds = [
      ...this.refreshOffers(simulationTime, snapshot),
      ...this.refreshWorldEventOffers(
        simulationTime,
        snapshot,
        domainEvents,
      ),
    ];
    const completedMissionIds: string[] = [];
    const expiredMissionIds: string[] = [];
    const contributionEvents: WorldContributionEvent[] = [];

    for (const state of this.states.values()) {
      const definition = this.definitions.get(state.missionId);
      if (!definition) continue;
      if (
        state.status === 'OFFERED' &&
        definition.offerExpiresAfterSeconds !== undefined &&
        simulationTime -
          (state.offeredAt ?? simulationTime) >=
          definition.offerExpiresAfterSeconds
      ) {
        state.status = 'EXPIRED';
        state.expiredAt = Math.max(0, simulationTime);
        expiredMissionIds.push(definition.id);
        continue;
      }
      if (
        (
          state.status !== 'ACTIVE' &&
          !(
            state.status === 'OFFERED' &&
            definition.type === 'RESCUE_STUCK_SHIP'
          )
        ) ||
        !this.isComplete(
          definition,
          state,
          snapshot,
          contributions,
        )
      ) {
        continue;
      }
      state.status = 'COMPLETED';
      state.completedAt = Math.max(0, simulationTime);
      completedMissionIds.push(definition.id);
      contributionEvents.push({
        type: 'MISSION_COMPLETED',
        eventId: `mission:${definition.id}:completed`,
        occurredAt: state.completedAt,
        source: 'WORLD_SIMULATION',
        missionId: definition.id,
        rewardMoney:
          definition.type === 'RESCUE_STUCK_SHIP'
            ? 0
            : definition.rewardMoney,
        rewardUpgradeId: definition.rewardUpgradeId,
      });
    }

    if (completedMissionIds.length > 0) {
      offeredMissionIds.push(
        ...this.refreshOffers(simulationTime, snapshot),
      );
    }

    return {
      offeredMissionIds,
      availableMissionIds: [...offeredMissionIds],
      completedMissionIds,
      expiredMissionIds,
      contributionEvents,
    };
  }

  public exportState(): MissionSystemSaveData {
    return {
      version: 2,
      missions: this.getStates().map((state) => ({
        ...state,
        linkedWorldState: state.linkedWorldState
          ? { ...state.linkedWorldState }
          : undefined,
      })),
    };
  }

  public importState(
    saved: Readonly<MissionSystemSaveData>,
  ): boolean {
    if (
      ![1, 2].includes(saved.version) ||
      !Array.isArray(saved.missions)
    ) {
      return false;
    }
    const validStatuses = new Set<string>([
      'LOCKED',
      'OFFERED',
      'ACTIVE',
      'COMPLETED',
      'EXPIRED',
      'CANCELLED',
      'AVAILABLE',
    ]);
    for (const candidate of saved.missions) {
      const definition = this.definitions.get(
        candidate.missionId,
      );
      if (
        !definition ||
        !validStatuses.has(candidate.status)
      ) {
        continue;
      }
      const status: MissionStatus =
        candidate.status === 'AVAILABLE'
          ? 'OFFERED'
          : candidate.status;
      this.states.set(definition.id, {
        missionId: definition.id,
        source: definition.source,
        status,
        triggerReason:
          candidate.triggerReason ??
          (definition.source === 'SCRIPTED'
            ? 'SCRIPTED'
            : 'WORLD_EVENT'),
        linkedWorldState: linkedWorldState(definition),
        offeredAt:
          finiteTime(candidate.offeredAt) ??
          (status === 'OFFERED' ? 0 : undefined),
        acceptedAt: finiteTime(candidate.acceptedAt),
        completedAt: finiteTime(candidate.completedAt),
        expiredAt: finiteTime(candidate.expiredAt),
        cancelledAt: finiteTime(candidate.cancelledAt),
      });
    }
    let inferredCompletion = true;
    while (inferredCompletion) {
      inferredCompletion = false;
      for (const definition of this.definitions.values()) {
        const state = this.states.get(definition.id);
        if (state?.status !== 'COMPLETED') continue;
        for (const prerequisite of (
          definition.prerequisites ?? []
        )) {
          if (
            prerequisite.type !== 'MISSION_COMPLETED'
          ) {
            continue;
          }
          const prerequisiteState = this.states.get(
            prerequisite.missionId,
          );
          if (
            !prerequisiteState ||
            prerequisiteState.status === 'COMPLETED'
          ) {
            continue;
          }
          prerequisiteState.status = 'COMPLETED';
          prerequisiteState.completedAt =
            state.completedAt ?? 0;
          inferredCompletion = true;
        }
      }
    }
    return true;
  }

  private prerequisitesMet(
    prerequisites: readonly MissionPrerequisiteDefinition[],
    snapshot: Readonly<MissionWorldSnapshot>,
  ): boolean {
    return prerequisites.every((prerequisite) => {
      switch (prerequisite.type) {
        case 'MISSION_COMPLETED':
          return (
            this.states.get(prerequisite.missionId)
              ?.status === 'COMPLETED'
          );
        case 'PORT_CLEARED':
          return hasClearedPort(
            prerequisite.portId,
            snapshot,
          );
        case 'POI_DISCOVERED':
          return snapshot.discoveredPoiIds.has(
            prerequisite.poiId,
          );
        case 'UPGRADE_OWNED':
          return snapshot.ownedUpgradeIds.has(
            prerequisite.upgradeId,
          );
      }
    });
  }

  private refreshWorldEventOffers(
    simulationTime: number,
    snapshot: Readonly<MissionWorldSnapshot>,
    domainEvents: readonly WorldDomainEvent[],
  ): readonly string[] {
    const stuckShips = domainEvents.flatMap((event) =>
      event.type === 'SHIP_STUCK'
        ? [
            {
              routeId: event.routeId,
              shipId: event.shipId,
            },
          ]
        : [],
    );
    if (stuckShips.length === 0) return [];

    const offeredMissionIds: string[] = [];
    for (const definition of this.definitions.values()) {
      const state = this.states.get(definition.id);
      if (
        !state ||
        state.status !== 'LOCKED' ||
        definition.source !== 'SIMULATION' ||
        definition.type !== 'RESCUE_STUCK_SHIP' ||
        !definition.linkedRouteId ||
        !stuckShips.some(
          (incident) =>
            incident.routeId ===
              definition.linkedRouteId &&
            (
              !definition.linkedShipId ||
              incident.shipId === definition.linkedShipId
            ),
        ) ||
        !this.prerequisitesMet(
          definition.prerequisites ?? [],
          snapshot,
        )
      ) {
        continue;
      }
      state.status = 'OFFERED';
      state.triggerReason = 'WORLD_EVENT';
      state.offeredAt = Math.max(0, simulationTime);
      offeredMissionIds.push(definition.id);
    }
    return offeredMissionIds;
  }

  private simulationTrigger(
    definition: Readonly<MissionDefinition>,
    snapshot: Readonly<MissionWorldSnapshot>,
  ): MissionTriggerReason | undefined {
    const routes = linkedRoutes(definition, snapshot);
    const route = routes[0];
    if (
      definition.type === 'OPEN_ROUTE' &&
      routes.length > 0
    ) {
      return !routes.some(isOpenRoute)
        ? 'ROUTE_CLOSED'
        : undefined;
    }
    if (definition.type === 'WIDEN_ROUTE' && route) {
      return route.openness >= ROUTE_OPENNESS_THRESHOLD &&
        route.measuredWidth <
          ROUTE_WIDTH_THRESHOLDS.standard
        ? 'ROUTE_TOO_NARROW'
        : undefined;
    }
    if (definition.type === 'SERVICE_ROUTE' && route) {
      return route.openness < 0.72
        ? 'ROUTE_NEEDS_SERVICE'
        : undefined;
    }
    if (definition.linkedPortId) {
      const port = snapshot.ports.find(
        (candidate) =>
          candidate.portId === definition.linkedPortId,
      );
      if (port && port.accessibility < 0.42) {
        return 'PORT_NEEDS_ACCESS';
      }
    }
    return undefined;
  }

  private isComplete(
    definition: Readonly<MissionDefinition>,
    state: Readonly<MissionRuntimeState>,
    snapshot: Readonly<MissionWorldSnapshot>,
    contributions: readonly WorldContributionEvent[],
  ): boolean {
    const routes = linkedRoutes(definition, snapshot);
    const route = routes[0];
    switch (definition.type) {
      case 'CLEAR_PORT':
        return Boolean(
          definition.linkedPortId &&
            hasClearedPort(
              definition.linkedPortId,
              snapshot,
            ),
        );
      case 'OPEN_ROUTE':
        return (
          routes.some(isOpenRoute) &&
          hasRequiredPortClearance(definition, snapshot)
        );
      case 'WIDEN_ROUTE':
        return Boolean(
          route &&
            route.openness >= ROUTE_OPENNESS_THRESHOLD &&
            route.measuredWidth >=
              ROUTE_WIDTH_THRESHOLDS.standard,
        );
      case 'SERVICE_ROUTE':
        return Boolean(
          route &&
            route.lastServicedAt >=
              (state.acceptedAt ??
                Number.POSITIVE_INFINITY),
        );
      case 'DISCOVER_POI':
        return Boolean(
          definition.linkedPoiId &&
            snapshot.discoveredPoiIds.has(
              definition.linkedPoiId,
            ),
        );
      case 'ESCORT_SHIP':
        return contributions.some(
          (event) =>
            event.type === 'SHIP_ESCORTED' &&
            (
              !definition.linkedShipId ||
              event.shipId === definition.linkedShipId
            ),
        );
      case 'RESCUE_STUCK_SHIP':
        return contributions.some(
          (event) =>
            event.type === 'SHIP_RESCUED' &&
            (
              !definition.linkedRouteId ||
              event.routeId === definition.linkedRouteId
            ) &&
            (
              !definition.linkedShipId ||
              event.shipId === definition.linkedShipId
            ),
        );
      case 'RECOVER_UPGRADE_PART':
        return contributions.some(
          (event) =>
            event.type === 'UPGRADE_PART_RECOVERED',
        );
      case 'DELIVER_SPECIAL_COMPONENT':
        return contributions.some(
          (event) =>
            event.type ===
              'SPECIAL_COMPONENT_DELIVERED' &&
            (!definition.linkedPortId ||
              event.portId === definition.linkedPortId) &&
            (!definition.requiredComponentId ||
              event.componentId ===
                definition.requiredComponentId),
        );
    }
  }
}
