import './styles.css';
import './construction/construction.css';
import './land/world-editor.css';
import './authoring/content-authoring.css';
import './land/land-expedition.css';
import './multiplayer/multiplayer-ui.css';
import { Game } from './core/Game';
import { initializeBorealisLandRaster } from './land/BorealisLand';

const root = document.querySelector<HTMLElement>('#app');
if (!root) throw new Error('ICEWAY could not find the #app root element.');

try {
  await initializeBorealisLandRaster();
} catch (error) {
  console.warn(
    'ICE-A-WAY Borealis coast rasters could not be loaded. Using the deterministic fallback coast.',
    error,
  );
}

const game = new Game(root);

window.addEventListener('beforeunload', () => game.dispose(), { once: true });
