export type RuntimeWorkLane =
  | 'CRITICAL'
  | 'NEAR_PRESENTATION'
  | 'BACKGROUND';

export interface RuntimeFrameWorkBudget {
  readonly frameIntervalMs: number;
  readonly pressure: number;
  readonly criticalMs: number;
  readonly nearPresentationMs: number;
  readonly backgroundMs: number;
}

const clamp01 = (value: number): number => Math.max(0, Math.min(1, value));

/**
 * Converts observed frame pacing into small, predictable work lanes. Systems
 * still own their queues; this coordinator prevents snow streaming,
 * vegetation presentation and future editor previews from each assuming that
 * the whole spare frame belongs to them.
 */
export class AdaptiveFrameWorkBudget {
  private pressure = 0;
  private last: RuntimeFrameWorkBudget = {
    frameIntervalMs: 16.67,
    pressure: 0,
    criticalMs: 2.5,
    nearPresentationMs: 2,
    backgroundMs: 1.5,
  };

  public constructor(
    private readonly targetFrameMs = 16.67,
    private readonly smoothing = 0.12,
  ) {}

  public beginFrame(
    frameIntervalMs: number,
    hidden = false,
  ): RuntimeFrameWorkBudget {
    const safeInterval = Number.isFinite(frameIntervalMs)
      ? Math.max(0, frameIntervalMs)
      : this.targetFrameMs;
    const instantaneousPressure = clamp01(
      (safeInterval - this.targetFrameMs * 0.82) /
      Math.max(1, this.targetFrameMs * 1.5),
    );
    this.pressure +=
      (instantaneousPressure - this.pressure) * clamp01(this.smoothing);
    const headroom = 1 - this.pressure;
    this.last = Object.freeze({
      frameIntervalMs: safeInterval,
      pressure: this.pressure,
      criticalMs: hidden ? 0.4 : 1.25 + headroom * 1.75,
      nearPresentationMs: hidden ? 0.25 : 0.55 + headroom * 1.7,
      backgroundMs: hidden ? 0.25 : 0.25 + headroom * 1.5,
    });
    return this.last;
  }

  public getBudget(lane: RuntimeWorkLane): number {
    if (lane === 'CRITICAL') return this.last.criticalMs;
    if (lane === 'NEAR_PRESENTATION') return this.last.nearPresentationMs;
    return this.last.backgroundMs;
  }

  public snapshot(): RuntimeFrameWorkBudget {
    return this.last;
  }
}
