import { clamp } from '../utils/math';

export const ICE_RUNTIME_TUNING = Object.freeze({
  driftStrength: Object.freeze({
    defaultValue: 1.6,
    minimum: 0.25,
    maximum: 3,
  }),
  refreezeSpeed: Object.freeze({
    defaultValue: 0.75,
    minimum: 0.25,
    maximum: 4,
  }),
  contactBondSeconds: 8,
  thermalAnchorSeconds: 82,
  contactGraceSeconds: 5,
  thermalAnchorDelaySeconds: 18,
});

export const clampDriftStrength = (value: number): number =>
  clamp(
    Number.isFinite(value)
      ? value
      : ICE_RUNTIME_TUNING.driftStrength.defaultValue,
    ICE_RUNTIME_TUNING.driftStrength.minimum,
    ICE_RUNTIME_TUNING.driftStrength.maximum,
  );

export const clampRefreezeSpeed = (value: number): number =>
  clamp(
    Number.isFinite(value)
      ? value
      : ICE_RUNTIME_TUNING.refreezeSpeed.defaultValue,
    ICE_RUNTIME_TUNING.refreezeSpeed.minimum,
    ICE_RUNTIME_TUNING.refreezeSpeed.maximum,
  );
