import { OrthographicCamera, Vector3 } from 'three';
import { clamp, damp, dampVector3 } from '../utils/math';
import type { WorldPoint } from '../world/WorldPoint';

export interface FollowCameraTarget {
  position: Readonly<WorldPoint> & { readonly y?: number };
  velocityX: number;
  velocityZ: number;
  speed: number;
}

export type CameraSpringArmDistanceResolver = (
  anchor: Readonly<Vector3>,
  desiredCameraPosition: Readonly<Vector3>,
) => number;

const FOLLOW_ZOOM_BASE = 2.3;
const FOLLOW_ZOOM_MINIMUM = 1.15;
const FOLLOW_ZOOM_MAXIMUM = 2.95;
const CHARACTER_ZOOM_BASE = 4.4;
const CHARACTER_ZOOM_MINIMUM = 2.3;
const CHARACTER_ZOOM_MAXIMUM = 8.9;
const MANUAL_ZOOM_MINIMUM = -2.1;
const MANUAL_ZOOM_MAXIMUM = 4.5;
const CHARACTER_OVERVIEW_ELEVATION_OFFSET = 0.06;
// A shallow default keeps both the actor and the work face readable. Tool
// pitch can still travel from almost horizontal to a steep floor view.
const CHARACTER_TOOL_ELEVATION_TARGET = -0.55;
// Includes a genuine upward view for ceilings and a steep downward view for
// shafts. These offsets are relative to the authored isometric base angle.
const CHARACTER_TOOL_ELEVATION_MINIMUM = -1.3;
const CHARACTER_TOOL_ELEVATION_MAXIMUM = 0.52;
const CHARACTER_TOOL_CAMERA_RADIUS = 10.5;
const CHARACTER_TOOL_ZOOM = 6.15;
const CHARACTER_TOOL_ZOOM_MINIMUM = 3.65;
const CHARACTER_TOOL_ZOOM_MAXIMUM = 12.9;
const CHARACTER_TOOL_FOCUS_FORWARD = 0.85;
const CHARACTER_TOOL_FOCUS_RIGHT = 0.22;
// Once the camera gained a real shoulder-height elevation, the focus also
// had to move down so the actor sits around the lower quarter, not on the
// bottom edge of the frame.
const CHARACTER_TOOL_FOCUS_UP = 0.36;
const CAMERA_NEAR_DEFAULT = 0.1;
const EDITOR_ORBIT_ELEVATION_MINIMUM = -0.58;
const EDITOR_ORBIT_ELEVATION_MAXIMUM = 0.62;
const EDITOR_TOP_DOWN_ZOOM_MINIMUM = 0.045;
const EDITOR_TOP_DOWN_ZOOM_MAXIMUM = 7.5;
const EDITOR_GROUND_INSPECT_ELEVATION = 0.24;
const EDITOR_GROUND_INSPECT_RADIUS_SCALE = 0.72;

export class FollowCameraSystem {
  private readonly focus = new Vector3();
  private readonly desiredFocus = new Vector3();
  private readonly cameraOffset = new Vector3(38, 48, 43);
  private readonly resolvedCameraOffset = new Vector3();
  private readonly desiredCameraPosition = new Vector3();
  private readonly springArmAnchor = new Vector3();
  private readonly springArmDirection = new Vector3();
  private mode: 'overview' | 'follow' = 'overview';
  private currentZoom = 1;
  private manualZoomOffset = 0;
  private followFramingScale = 1;
  private followLookAheadScale = 1;
  private followTargetKind: 'vehicle' | 'character' = 'vehicle';
  private inspectOrbitActive = false;
  private inspectYawTarget = 0;
  private inspectElevationTarget = 0;
  private inspectYaw = 0;
  private inspectElevation = 0;
  private characterOrbitPersistent = false;
  private characterToolAimActive = false;
  private readonly editorFocusOffset = new Vector3();
  private editorActive = false;
  private editorTopDown = false;
  private editorGroundInspect = false;
  private editorTopDownZoom = 0.72;
  private currentCameraNear = CAMERA_NEAR_DEFAULT;
  private springArmDistanceResolver?: CameraSpringArmDistanceResolver;
  private cinematicZoom?: number;

  public setMode(mode: 'overview' | 'follow'): void {
    this.mode = mode;
    if (mode !== 'follow') this.endInspectOrbit();
  }

  public adjustZoom(delta: number): void {
    if (this.editorActive && this.editorTopDown) {
      this.editorTopDownZoom = clamp(
        this.editorTopDownZoom * Math.exp(delta * 1.55),
        EDITOR_TOP_DOWN_ZOOM_MINIMUM,
        EDITOR_TOP_DOWN_ZOOM_MAXIMUM,
      );
      return;
    }
    this.manualZoomOffset = clamp(
      this.manualZoomOffset + delta,
      MANUAL_ZOOM_MINIMUM,
      MANUAL_ZOOM_MAXIMUM,
    );
  }

  public setFollowFramingScale(scale: number): void {
    this.followFramingScale = Math.max(1, scale);
  }

  public setFollowLookAheadScale(scale: number): void {
    this.followLookAheadScale = clamp(scale, 0, 1);
  }

  public setFollowTargetKind(kind: 'vehicle' | 'character'): void {
    this.followTargetKind = kind;
  }

  /** Smooth orthographic framing override used by short authored moments. */
  public setCinematicZoom(zoom: number | undefined): void {
    this.cinematicZoom = zoom === undefined
      ? undefined
      : clamp(zoom, 0.35, 14);
  }

  /** Places a newly-authored follow moment on screen without a stale-world pan. */
  public snapFocus(
    position: Readonly<{ x: number; y: number; z: number }>,
    zoom?: number,
  ): void {
    this.focus.set(position.x, position.y, position.z);
    this.desiredFocus.copy(this.focus);
    if (zoom !== undefined) {
      this.currentZoom = clamp(zoom, 0.35, 14);
    }
  }

  public setCharacterOrbitPersistent(persistent: boolean): void {
    this.characterOrbitPersistent = persistent;
    if (!persistent && !this.editorActive) {
      this.inspectYawTarget = 0;
      this.inspectElevationTarget = 0;
    }
  }

  public setCharacterToolAim(active: boolean): void {
    if (this.characterToolAimActive === active) return;
    this.characterToolAimActive = active;
    if (!this.editorActive) {
      this.inspectElevationTarget = active
        ? CHARACTER_TOOL_ELEVATION_TARGET
        : 0;
    }
  }

  /** Starts an OTS tool view behind the facing direction, then leaves orbit free. */
  public orientCharacterCameraBehind(heading: number): void {
    const baseAzimuth = Math.atan2(this.cameraOffset.x, this.cameraOffset.z);
    let yaw = heading + Math.PI - baseAzimuth;
    yaw = Math.atan2(Math.sin(yaw), Math.cos(yaw));
    this.inspectYaw = yaw;
    this.inspectYawTarget = yaw;
  }

  public setSpringArmDistanceResolver(
    resolver: CameraSpringArmDistanceResolver | undefined,
  ): void {
    this.springArmDistanceResolver = resolver;
    if (!resolver) this.currentCameraNear = CAMERA_NEAR_DEFAULT;
  }

  public setWorldEditorActive(active: boolean): void {
    this.editorActive = active;
    if (!active) {
      this.editorFocusOffset.set(0, 0, 0);
      this.inspectOrbitActive = false;
      this.inspectYawTarget = 0;
      this.inspectElevationTarget = 0;
    }
  }

  public setWorldEditorTopDown(active: boolean): void {
    this.editorTopDown = active;
    if (active) this.editorGroundInspect = false;
    if (active) this.endInspectOrbit();
  }

  public setWorldEditorGroundInspect(active: boolean): void {
    this.editorGroundInspect = active;
    if (active) {
      this.editorTopDown = false;
      this.inspectElevation = 0;
      this.inspectElevationTarget = 0;
    }
  }

  public panWorldEditor(deltaX: number, deltaZ: number): void {
    if (!this.editorActive) return;
    this.editorFocusOffset.x += deltaX;
    this.editorFocusOffset.z += deltaZ;
  }

  public beginInspectOrbit(): void {
    if (this.mode !== 'follow') return;
    this.inspectOrbitActive = true;
    this.inspectYawTarget = this.inspectYaw;
    // Equipping a cave tool may still be blending toward its low OTS angle.
    // Do not cancel that target merely because the first orbit drag starts.
    if (!this.characterToolAimActive) {
      this.inspectElevationTarget = this.inspectElevation;
    }
  }

  public adjustInspectOrbit(deltaX: number, deltaY: number): void {
    if (!this.inspectOrbitActive) {
      // Precision mouse-look owns a persistent camera stream. A secondary
      // pointer/gamepad lifecycle may still call endInspectOrbit while Chrome
      // keeps Pointer Lock active; self-heal that contradictory state on the
      // next relative movement instead of silently discarding every delta.
      if (this.mode !== 'follow' || !this.characterToolAimActive) return;
      this.inspectOrbitActive = true;
    }
    if (this.editorActive) {
      this.inspectYawTarget -= deltaX * 0.006;
      this.inspectElevationTarget = clamp(
        this.inspectElevationTarget - deltaY * 0.0045,
        EDITOR_ORBIT_ELEVATION_MINIMUM,
        EDITOR_ORBIT_ELEVATION_MAXIMUM,
      );
      if (Math.abs(this.inspectYawTarget) > Math.PI * 8) {
        const revolutions = Math.trunc(this.inspectYawTarget / (Math.PI * 2));
        const offset = revolutions * Math.PI * 2;
        this.inspectYawTarget -= offset;
        this.inspectYaw -= offset;
      }
      return;
    }
    if (this.characterOrbitPersistent) {
      this.inspectYawTarget -= deltaX * 0.006;
      // Character inspect is an unlimited azimuth orbit. Keeping elevation,
      // zoom and radius independent of drag preserves the authored isometric
      // composition and avoids the perspective-like breathing that made the
      // previous free orbit uncomfortable. A held cave tool is the deliberate
      // exception: its stable OTS rig pitches so the reticle can reach floor,
      // walls and ceiling without changing zoom, focus offset or boom length.
      if (this.characterToolAimActive) {
        this.inspectElevationTarget = clamp(
          this.inspectElevationTarget + deltaY * 0.0036,
          CHARACTER_TOOL_ELEVATION_MINIMUM,
          CHARACTER_TOOL_ELEVATION_MAXIMUM,
        );
      }
      if (Math.abs(this.inspectYawTarget) > Math.PI * 8) {
        const revolutions = Math.trunc(this.inspectYawTarget / (Math.PI * 2));
        const offset = revolutions * Math.PI * 2;
        this.inspectYawTarget -= offset;
        this.inspectYaw -= offset;
      }
      return;
    }
    // Vehicle inspect can be dragged freely around the vehicle, but release
    // resolves to one of two authored isometric views (canonical or its 180°
    // mirror). Vertical drag intentionally has no effect.
    this.inspectYawTarget -= deltaX * 0.006;
    void deltaY;
  }

  public endInspectOrbit(): void {
    this.inspectOrbitActive = false;
    if (this.editorActive || this.characterOrbitPersistent) {
      return;
    }
    this.inspectYawTarget = Math.round(this.inspectYawTarget / Math.PI) *
      Math.PI;
    this.inspectElevationTarget = 0;
  }

  public isInspectOrbitActive(): boolean {
    return this.inspectOrbitActive;
  }

  public update(
    camera: OrthographicCamera,
    deltaSeconds: number,
    target?: Readonly<FollowCameraTarget>,
  ): void {
    let targetZoom = 1;
    const characterFollow =
      this.mode === 'follow' && this.followTargetKind === 'character';
    if (this.mode === 'follow' && target) {
      const character = characterFollow;
      const lookAhead = (character
        ? clamp(1.85 + target.speed * 0.7, 1.85, 3.4)
        : clamp(1.5 + target.speed * 0.8, 1.5, 4.2)) *
        this.followLookAheadScale;
      const velocityLength = Math.hypot(target.velocityX, target.velocityZ);
      const directionX = velocityLength > 0.08 ? target.velocityX / velocityLength : 0;
      const directionZ = velocityLength > 0.08 ? target.velocityZ / velocityLength : 0;
      this.desiredFocus.set(
        target.position.x + directionX * lookAhead + this.editorFocusOffset.x,
        target.position.y ?? 0,
        target.position.z + directionZ * lookAhead + this.editorFocusOffset.z,
      );
      targetZoom =
        clamp(
          (character ? CHARACTER_ZOOM_BASE : FOLLOW_ZOOM_BASE) -
            target.speed * (character ? 0.08 : 0.055) +
            this.manualZoomOffset,
          character ? CHARACTER_ZOOM_MINIMUM : FOLLOW_ZOOM_MINIMUM,
          character ? CHARACTER_ZOOM_MAXIMUM : FOLLOW_ZOOM_MAXIMUM,
        ) * this.followFramingScale;
      if (character && this.characterToolAimActive) {
        const baseAzimuth = Math.atan2(
          this.cameraOffset.x,
          this.cameraOffset.z,
        );
        const azimuth = baseAzimuth + this.inspectYaw;
        const forwardX = -Math.sin(azimuth);
        const forwardZ = -Math.cos(azimuth);
        const rightX = Math.cos(azimuth);
        const rightZ = -Math.sin(azimuth);
        const toolZoom = clamp(
          CHARACTER_TOOL_ZOOM + this.manualZoomOffset * 1.5,
          CHARACTER_TOOL_ZOOM_MINIMUM,
          CHARACTER_TOOL_ZOOM_MAXIMUM,
        ) * this.followFramingScale;
        const framingCompensation =
          (CHARACTER_TOOL_ZOOM * this.followFramingScale) / toolZoom;
        this.desiredFocus.x +=
          (forwardX * CHARACTER_TOOL_FOCUS_FORWARD +
            rightX * CHARACTER_TOOL_FOCUS_RIGHT) *
          framingCompensation;
        this.desiredFocus.y +=
          CHARACTER_TOOL_FOCUS_UP * framingCompensation;
        this.desiredFocus.z +=
          (forwardZ * CHARACTER_TOOL_FOCUS_FORWARD +
            rightZ * CHARACTER_TOOL_FOCUS_RIGHT) *
          framingCompensation;
        targetZoom = toolZoom;
      }
    } else {
      this.desiredFocus.set(0, 0, 0);
    }
    if (this.editorActive && this.editorTopDown) {
      targetZoom = this.editorTopDownZoom;
    } else if (this.cinematicZoom !== undefined) {
      targetZoom = this.cinematicZoom * this.followFramingScale;
    }

    dampVector3(this.focus, this.desiredFocus, this.mode === 'follow' ? 2.4 : 1.5, deltaSeconds);
    this.currentZoom = damp(this.currentZoom, targetZoom, 2.2, deltaSeconds);
    const orbitResponse = this.inspectOrbitActive ? 12 : 3.8;
    this.inspectYaw = damp(
      this.inspectYaw,
      this.inspectYawTarget,
      orbitResponse,
      deltaSeconds,
    );
    this.inspectElevation = damp(
      this.inspectElevation,
      this.inspectElevationTarget,
      orbitResponse,
      deltaSeconds,
    );
    const radius = this.cameraOffset.length();
    if (this.editorActive && this.editorTopDown) {
      this.resolvedCameraOffset.set(0, radius, 0);
      camera.up.set(0, 0, -1);
    } else {
      const baseAzimuth = Math.atan2(
        this.cameraOffset.x,
        this.cameraOffset.z,
      );
      const baseElevation = Math.asin(this.cameraOffset.y / radius);
      const azimuth = baseAzimuth + this.inspectYaw;
      const elevation = this.editorActive && this.editorGroundInspect
        ? EDITOR_GROUND_INSPECT_ELEVATION
        : baseElevation + (
        characterFollow
          ? this.characterToolAimActive
            ? this.inspectElevation
            : CHARACTER_OVERVIEW_ELEVATION_OFFSET
          : 0
      );
      const resolvedRadius = this.editorActive && this.editorGroundInspect
        ? radius * EDITOR_GROUND_INSPECT_RADIUS_SCALE
        : characterFollow && this.characterToolAimActive
        ? CHARACTER_TOOL_CAMERA_RADIUS
        : radius;
      const horizontalRadius = Math.cos(elevation) * resolvedRadius;
      this.resolvedCameraOffset.set(
        Math.sin(azimuth) * horizontalRadius,
        Math.sin(elevation) * resolvedRadius,
        Math.cos(azimuth) * horizontalRadius,
      );
      camera.up.set(0, 1, 0);
    }
    camera.zoom = this.currentZoom;
    this.desiredCameraPosition
      .copy(this.focus)
      .add(this.resolvedCameraOffset);
    if (
      this.springArmDistanceResolver &&
      this.mode === 'follow' &&
      target &&
      !this.editorActive
    ) {
      this.springArmAnchor.set(
        target.position.x,
        (target.position.y ?? 0) + 0.95,
        target.position.z,
      );
      this.springArmDirection
        .copy(this.desiredCameraPosition)
        .sub(this.springArmAnchor);
      const fullLength = this.springArmDirection.length();
      if (fullLength > 0.001) {
        // The resolver updates domain-specific occlusion (the cave uses a
        // rock-only clipping plane). Keeping the orthographic camera at its
        // canonical position prevents boom contraction from changing its aim
        // angle or entering adjacent geometry.
        this.springArmDistanceResolver(
          this.springArmAnchor,
          this.desiredCameraPosition,
        );
        camera.position.copy(this.desiredCameraPosition);
        this.currentCameraNear = CAMERA_NEAR_DEFAULT;
      } else {
        camera.position.copy(this.desiredCameraPosition);
        this.currentCameraNear = CAMERA_NEAR_DEFAULT;
      }
    } else {
      this.currentCameraNear = CAMERA_NEAR_DEFAULT;
      camera.position.copy(this.desiredCameraPosition);
    }
    camera.near = Math.min(this.currentCameraNear, camera.far - 1);
    camera.lookAt(this.focus);
    camera.updateProjectionMatrix();
  }
}
