import type {
  ConstructionBlueprint,
  ConstructionPlacement,
} from './ConstructionBlueprint';
import {
  getConstructionModule,
  type ConstructionModuleDefinition,
} from './ConstructionModuleCatalog';

export interface ConstructionPlacementBounds {
  minX: number;
  maxX: number;
  minY: number;
  maxY: number;
  minZ: number;
  maxZ: number;
}

export interface ConstructionPlacementResult {
  accepted: boolean;
  reason?: string;
}

const BUILD_RADIUS_CELLS = 80;
const BUILD_HEIGHT_CELLS = 64;

const resolvedHorizontalFootprint = (
  definition: Readonly<ConstructionModuleDefinition>,
  yawDegrees: number,
): { width: number; length: number } => {
  const radians = (yawDegrees * Math.PI) / 180;
  const cosine = Math.abs(Math.cos(radians));
  const sine = Math.abs(Math.sin(radians));
  return {
    width:
      definition.footprint.widthCells * cosine +
      definition.footprint.lengthCells * sine,
    length:
      definition.footprint.widthCells * sine +
      definition.footprint.lengthCells * cosine,
  };
};

export const constructionPlacementBounds = (
  placement: Readonly<ConstructionPlacement>,
  definition: Readonly<ConstructionModuleDefinition>,
): ConstructionPlacementBounds => {
  const horizontal = resolvedHorizontalFootprint(
    definition,
    placement.yawDegrees,
  );
  return {
    minX: placement.position.x - horizontal.width * 0.5,
    maxX: placement.position.x + horizontal.width * 0.5,
    minY: placement.position.y,
    maxY:
      placement.position.y + definition.footprint.heightCells,
    minZ: placement.position.z - horizontal.length * 0.5,
    maxZ: placement.position.z + horizontal.length * 0.5,
  };
};

const overlaps = (
  left: Readonly<ConstructionPlacementBounds>,
  right: Readonly<ConstructionPlacementBounds>,
): boolean =>
  left.minX < right.maxX - 0.01 &&
  left.maxX > right.minX + 0.01 &&
  left.minY < right.maxY - 0.01 &&
  left.maxY > right.minY + 0.01 &&
  left.minZ < right.maxZ - 0.01 &&
  left.maxZ > right.minZ + 0.01;

export const validateConstructionPlacement = (
  blueprint: Readonly<ConstructionBlueprint>,
  placement: Readonly<ConstructionPlacement>,
): ConstructionPlacementResult => {
  const definition = getConstructionModule(placement.moduleId);
  if (!definition) {
    return { accepted: false, reason: 'Unknown construction module.' };
  }
  if (
    (!Number.isInteger(placement.position.x) ||
      !Number.isInteger(placement.position.y) ||
      !Number.isInteger(placement.position.z)) &&
    !(
      placement.mount.kind === 'grid' &&
      placement.mount.connection !== undefined
    )
  ) {
    return { accepted: false, reason: 'Placement is off the fine grid.' };
  }
  if (
    Math.abs(placement.position.x) > BUILD_RADIUS_CELLS ||
    Math.abs(placement.position.z) > BUILD_RADIUS_CELLS ||
    placement.position.y < 0 ||
    placement.position.y > BUILD_HEIGHT_CELLS
  ) {
    return { accepted: false, reason: 'Placement is outside the shipyard.' };
  }
  if (blueprint.placements.some((item) => item.id === placement.id)) {
    return { accepted: false, reason: 'Placement id already exists.' };
  }
  if (definition.mountMode === 'vertical-surface') {
    if (placement.mount.kind !== 'surface') {
      return {
        accepted: false,
        reason: 'This detail must be mounted on a vertical surface.',
      };
    }
    const surfaceMount = placement.mount;
    const host = blueprint.placements.find(
      (item) => item.id === surfaceMount.hostPlacementId,
    );
    const hostDefinition = host
      ? getConstructionModule(host.moduleId)
      : undefined;
    if (!host || !hostDefinition?.canHostAttachments) {
      return {
        accepted: false,
        reason: 'The selected surface cannot host attachments.',
      };
    }
    if (
      Math.abs(surfaceMount.normal.y) > 0.55 ||
      Math.hypot(surfaceMount.normal.x, surfaceMount.normal.z) < 0.5
    ) {
      return {
        accepted: false,
        reason: 'Attachments currently require a vertical face.',
      };
    }
    return { accepted: true };
  }
  if (placement.mount.kind !== 'grid') {
    return { accepted: false, reason: 'Structural modules use the grid.' };
  }

  const candidateBounds = constructionPlacementBounds(
    placement,
    definition,
  );
  const connectedHostId =
    placement.mount.kind === 'grid'
      ? placement.mount.connection?.hostPlacementId
      : undefined;
  for (const existing of blueprint.placements) {
    if (existing.mount.kind === 'surface') continue;
    if (existing.id === connectedHostId) continue;
    const existingDefinition = getConstructionModule(existing.moduleId);
    if (!existingDefinition) continue;
    if (
      overlaps(
        candidateBounds,
        constructionPlacementBounds(existing, existingDefinition),
      )
    ) {
      return {
        accepted: false,
        reason: 'Another structural module occupies this volume.',
      };
    }
  }
  return { accepted: true };
};

export const removeConstructionPlacementTree = (
  blueprint: ConstructionBlueprint,
  placementId: string,
): string[] => {
  const removed = new Set([placementId]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const placement of blueprint.placements) {
      if (
        placement.mount.kind === 'surface' &&
        removed.has(placement.mount.hostPlacementId) &&
        !removed.has(placement.id)
      ) {
        removed.add(placement.id);
        changed = true;
      }
    }
  }
  for (const placement of blueprint.placements) {
    if (
      placement.mount.kind === 'grid' &&
      placement.mount.connection &&
      removed.has(placement.mount.connection.hostPlacementId)
    ) {
      placement.mount = { kind: 'grid' };
    }
  }
  blueprint.placements = blueprint.placements.filter(
    (placement) => !removed.has(placement.id),
  );
  return [...removed];
};
