import type {
  ContentAuthoringVersionRecord,
  IcewayContentAuthoringDocument,
} from './ContentAuthoringTypes';

interface StoredAuthoringVersions {
  readonly version: 1;
  readonly records: readonly ContentAuthoringVersionRecord[];
}

const STORAGE_KEY = 'iceway-content-authoring-versions-v1';
const VERSION_LIMIT = 24;

const validDocument = (value: unknown): value is IcewayContentAuthoringDocument => {
  const candidate = value as Partial<IcewayContentAuthoringDocument> | undefined;
  return candidate?.version === 1 && typeof candidate.id === 'string' &&
    Array.isArray(candidate.quests) && Array.isArray(candidate.dialogues) &&
    Array.isArray(candidate.materials) && Array.isArray(candidate.scenarios) &&
    Array.isArray(candidate.assets) && Array.isArray(candidate.locations);
};

export class ContentAuthoringStore {
  public loadVersions(): readonly ContentAuthoringVersionRecord[] {
    try {
      const parsed = JSON.parse(window.localStorage.getItem(STORAGE_KEY) ?? '') as
        Partial<StoredAuthoringVersions>;
      if (parsed.version !== 1 || !Array.isArray(parsed.records)) return [];
      return parsed.records.filter((record): record is ContentAuthoringVersionRecord =>
        typeof record?.id === 'string' && typeof record?.name === 'string' &&
        typeof record?.createdAt === 'string' && validDocument(record.document));
    } catch {
      return [];
    }
  }

  public saveVersion(
    document: Readonly<IcewayContentAuthoringDocument>,
    name: string,
  ): ContentAuthoringVersionRecord {
    const record: ContentAuthoringVersionRecord = {
      id: `authoring-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      name: name.trim().slice(0, 64) || `Authoring ${new Date().toLocaleString()}`,
      createdAt: new Date().toISOString(),
      document: structuredClone(document),
    };
    const records = [record, ...this.loadVersions()].slice(0, VERSION_LIMIT);
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ version: 1, records }));
    } catch {
      // The editor remains usable through JSON export when storage is full.
    }
    return record;
  }

  public parseDocument(text: string): IcewayContentAuthoringDocument | undefined {
    try {
      const parsed = JSON.parse(text) as unknown;
      return validDocument(parsed) ? structuredClone(parsed) : undefined;
    } catch {
      return undefined;
    }
  }
}
