import type { BrowserMultiplayerLaunchConfig } from './BrowserMultiplayerBootstrap';
import type { MultiplayerSessionClient } from './MultiplayerSessionClient';
import { createMultiplayerPlatformViewModel } from './MultiplayerPlatformUX';

export interface MultiplayerSessionUIActions {
  readonly onLeave: () => void;
  readonly onInviteShared?: (message: string) => void;
}

/** DOM-only platform panel; it never owns simulation or authority state. */
export class MultiplayerSessionUI {
  private readonly element: HTMLElement;
  private readonly toggle: HTMLButtonElement;
  private readonly panel: HTMLElement;
  private readonly phase: HTMLElement;
  private readonly title: HTMLElement;
  private readonly detail: HTMLElement;
  private readonly quality: HTMLElement;
  private readonly retry: HTMLButtonElement;
  private readonly invite: HTMLButtonElement;
  private readonly leave: HTMLButtonElement;
  private readonly updateLink: HTMLAnchorElement;
  private readonly supportLink: HTMLAnchorElement;
  private readonly politeLive: HTMLElement;
  private readonly assertiveLive: HTMLElement;
  private client?: MultiplayerSessionClient;
  private unsubscribe?: () => void;
  private timer?: ReturnType<typeof setInterval>;
  private inviteUrl?: string;
  private userExpanded = false;
  private lastAnnouncement = '';
  private lastHardCorrections = 0;
  private gamepadButtons: boolean[] = [];
  private gamepadFocus = 0;

  public constructor(
    root: HTMLElement,
    private readonly config: Readonly<BrowserMultiplayerLaunchConfig>,
    private readonly actions: Readonly<MultiplayerSessionUIActions>,
  ) {
    this.element = document.createElement('aside');
    this.element.className = 'multiplayer-session-ui';
    this.element.setAttribute('aria-label', 'Multiplayer connection');
    this.element.innerHTML = `
      <button class="multiplayer-session-toggle" type="button" aria-expanded="true" aria-controls="multiplayer-session-panel">
        <i aria-hidden="true"></i><span>CONNECTING</span>
      </button>
      <section id="multiplayer-session-panel" class="multiplayer-session-panel" aria-labelledby="multiplayer-session-title">
        <small data-mp="phase">CONNECTING</small>
        <strong id="multiplayer-session-title" data-mp="title">Connecting to room</strong>
        <p data-mp="detail">Opening a secure authority connection.</p>
        <output data-mp="quality">No live authority link</output>
        <div class="multiplayer-session-actions">
          <button type="button" data-mp-action="retry">RETRY NOW</button>
          <button type="button" data-mp-action="invite">SHARE INVITE</button>
          <a data-mp-action="update" target="_blank" rel="noopener noreferrer">UPDATE GAME</a>
          <a data-mp-action="support" target="_blank" rel="noopener noreferrer">SUPPORT</a>
          <button type="button" data-mp-action="leave">LEAVE ROOM</button>
        </div>
      </section>
      <div class="sr-only" role="status" aria-live="polite" aria-atomic="true" data-mp-live="polite"></div>
      <div class="sr-only" role="alert" aria-live="assertive" aria-atomic="true" data-mp-live="assertive"></div>
    `;
    root.appendChild(this.element);
    this.toggle = this.require<HTMLButtonElement>('.multiplayer-session-toggle');
    this.panel = this.require('.multiplayer-session-panel');
    this.phase = this.require('[data-mp="phase"]');
    this.title = this.require('[data-mp="title"]');
    this.detail = this.require('[data-mp="detail"]');
    this.quality = this.require('[data-mp="quality"]');
    this.retry = this.require<HTMLButtonElement>('[data-mp-action="retry"]');
    this.invite = this.require<HTMLButtonElement>('[data-mp-action="invite"]');
    this.leave = this.require<HTMLButtonElement>('[data-mp-action="leave"]');
    this.updateLink = this.require<HTMLAnchorElement>('[data-mp-action="update"]');
    this.supportLink = this.require<HTMLAnchorElement>('[data-mp-action="support"]');
    this.politeLive = this.require('[data-mp-live="polite"]');
    this.assertiveLive = this.require('[data-mp-live="assertive"]');
    this.toggle.addEventListener('click', this.toggleExpanded);
    this.retry.addEventListener('click', this.retryNow);
    this.invite.addEventListener('click', this.shareInvite);
    this.leave.addEventListener('click', this.actions.onLeave);
    this.retry.hidden = true;
    this.invite.hidden = true;
    this.updateLink.hidden = true;
    this.supportLink.hidden = true;
    this.render();
  }

  public bind(client: MultiplayerSessionClient, inviteUrl: string): void {
    this.client = client;
    this.inviteUrl = inviteUrl;
    this.unsubscribe?.();
    this.unsubscribe = client.onState(() => this.render());
    if (this.timer) clearInterval(this.timer);
    this.timer = setInterval(() => {
      this.render();
      this.pollGamepad();
    }, 250);
    this.render();
  }

  public showBootstrapFailure(message: string, updateUrl?: string): void {
    this.element.dataset.tone = 'danger';
    this.phase.textContent = updateUrl ? 'UPDATE REQUIRED' : 'JOIN FAILED';
    this.title.textContent = 'Multiplayer unavailable';
    this.detail.textContent = message;
    this.quality.textContent = 'No live authority link';
    this.retry.hidden = true;
    this.invite.hidden = true;
    this.updateLink.hidden = !updateUrl;
    if (updateUrl) this.updateLink.href = updateUrl;
    this.supportLink.hidden = true;
    this.setExpanded(true);
    this.announce(message, true);
  }

  public dispose(): void {
    this.unsubscribe?.();
    if (this.timer) clearInterval(this.timer);
    this.toggle.removeEventListener('click', this.toggleExpanded);
    this.retry.removeEventListener('click', this.retryNow);
    this.invite.removeEventListener('click', this.shareInvite);
    this.leave.removeEventListener('click', this.actions.onLeave);
    this.element.remove();
  }

  private render(): void {
    const client = this.client;
    if (!client) {
      this.setExpanded(true);
      return;
    }
    const diagnostics = client.diagnostics();
    const view = createMultiplayerPlatformViewModel(
      client.state(),
      diagnostics,
      client.clockEstimate(),
      performance.now(),
    );
    this.element.dataset.tone = view.tone.toLowerCase();
    this.element.classList.toggle('is-busy', view.busy);
    this.phase.textContent = view.phaseLabel;
    this.title.textContent = view.title;
    this.detail.textContent = view.detail;
    this.quality.textContent = view.qualityDetail;
    this.toggle.querySelector('span')!.textContent = view.phaseLabel;
    this.retry.hidden = !view.canRetry;
    this.invite.hidden = !view.canInvite || !this.inviteUrl;
    this.leave.hidden = !view.canLeave;
    this.updateLink.hidden = !view.updateUrl;
    if (view.updateUrl) this.updateLink.href = view.updateUrl;
    this.supportLink.hidden = !view.supportUrl;
    if (view.supportUrl) this.supportLink.href = view.supportUrl;
    this.setExpanded(view.expanded || this.userExpanded);
    this.announce(`${view.title}. ${view.detail}`, view.assertive);
    const hardCorrections = diagnostics.replication.hardCorrections;
    if (hardCorrections > this.lastHardCorrections) {
      this.element.classList.add('is-correcting');
      this.politeLive.textContent = 'Network position correction applied.';
      setTimeout(() => this.element.classList.remove('is-correcting'), 700);
    }
    this.lastHardCorrections = hardCorrections;
  }

  private announce(message: string, assertive: boolean): void {
    if (message === this.lastAnnouncement) return;
    this.lastAnnouncement = message;
    (assertive ? this.assertiveLive : this.politeLive).textContent = message;
  }

  private toggleExpanded = (): void => {
    this.userExpanded = this.panel.hidden;
    this.setExpanded(this.userExpanded);
  };

  private setExpanded(expanded: boolean): void {
    this.panel.hidden = !expanded;
    this.toggle.setAttribute('aria-expanded', String(expanded));
  }

  private retryNow = (): void => {
    const state = this.client?.state();
    if (state?.phase === 'SUSPENDED') this.client?.resumeFromSuspension();
    else this.client?.forceReconnect('Player requested immediate reconnect.');
  };

  private shareInvite = (): void => {
    if (!this.inviteUrl) return;
    const inviteUrl = this.inviteUrl;
    const shared = async (): Promise<void> => {
      if (navigator.share) {
        await navigator.share({
          title: 'ICE-A-WAY co-op room',
          text: `Join ${this.config.displayName}'s ICE-A-WAY room`,
          url: inviteUrl,
        });
      } else {
        await navigator.clipboard.writeText(inviteUrl);
      }
      this.actions.onInviteShared?.('Multiplayer invite ready to share.');
      this.politeLive.textContent = 'Invite link shared or copied.';
    };
    void shared().catch(() => {
      this.politeLive.textContent = 'Could not share the invite link.';
    });
  };

  private pollGamepad(): void {
    const gamepad = navigator.getGamepads?.().find((value) => value) ?? undefined;
    if (!gamepad) return;
    const pressed = gamepad.buttons.map((button) => button.pressed);
    const edge = (index: number): boolean =>
      pressed[index] === true && this.gamepadButtons[index] !== true;
    if (edge(9)) this.toggleExpanded();
    if (!this.panel.hidden) {
      const controls = this.focusableControls();
      if (edge(12)) this.gamepadFocus = Math.max(0, this.gamepadFocus - 1);
      if (edge(13)) this.gamepadFocus = Math.min(controls.length - 1, this.gamepadFocus + 1);
      if (edge(12) || edge(13)) controls[this.gamepadFocus]?.focus();
      if (edge(0)) controls[this.gamepadFocus]?.click();
      if (edge(1)) {
        this.userExpanded = false;
        this.setExpanded(false);
      }
    }
    this.gamepadButtons = pressed;
  }

  private focusableControls(): (HTMLButtonElement | HTMLAnchorElement)[] {
    return [this.retry, this.invite, this.updateLink, this.supportLink, this.leave]
      .filter((element) => !element.hidden);
  }

  private require<T extends HTMLElement = HTMLElement>(selector: string): T {
    const element = this.element.querySelector<T>(selector);
    if (!element) throw new Error(`Missing multiplayer UI element ${selector}.`);
    return element;
  }
}
