import { clamp, damp, lerp, smoothstep } from '../utils/math';

export interface PushSnowThrowerMovementState {
  readonly x: number;
  readonly z: number;
  readonly heading: number;
  readonly speed: number;
}

export interface PushSnowThrowerMovementResult
  extends PushSnowThrowerMovementState {
  readonly playerX: number;
  readonly playerZ: number;
  readonly travelled: number;
  readonly blocked: boolean;
}

const POWERED_SPEED = 0.92;
const HANDLE_OFFSET = 0.82;

/**
 * Powered walk-behind motion. The machine is the kinematic pivot and the
 * character follows its handles; steering never rotates the whole rig around
 * the character.
 */
export const stepPushSnowThrowerMovement = (
  state: Readonly<PushSnowThrowerMovementState>,
  steering: number,
  powered: boolean,
  deltaSeconds: number,
  canOccupy: (x: number, z: number, radius: number) => boolean,
): PushSnowThrowerMovementResult => {
  const delta = clamp(deltaSeconds, 0, 0.05);
  const targetSpeed = powered ? POWERED_SPEED : 0;
  const speed = damp(
    state.speed,
    targetSpeed,
    powered ? 4.8 : 8.5,
    delta,
  );
  const steeringAuthority = smoothstep(0.04, 0.48, speed);
  const steeringRate = lerp(0.34, 0.92, steeringAuthority);
  const heading = state.heading +
    clamp(steering, -1, 1) * steeringRate * delta *
      (powered ? 1 : 0);
  const forwardX = Math.sin(heading);
  const forwardZ = Math.cos(heading);
  const nextX = state.x + forwardX * speed * delta;
  const nextZ = state.z + forwardZ * speed * delta;
  const playerX = nextX - forwardX * HANDLE_OFFSET;
  const playerZ = nextZ - forwardZ * HANDLE_OFFSET;
  const allowed =
    canOccupy(nextX, nextZ, 0.5) &&
    canOccupy(playerX, playerZ, 0.18);
  if (!allowed) {
    const currentForwardX = Math.sin(state.heading);
    const currentForwardZ = Math.cos(state.heading);
    return {
      ...state,
      speed: 0,
      playerX: state.x - currentForwardX * HANDLE_OFFSET,
      playerZ: state.z - currentForwardZ * HANDLE_OFFSET,
      travelled: 0,
      blocked: true,
    };
  }
  return {
    x: nextX,
    z: nextZ,
    heading,
    speed,
    playerX,
    playerZ,
    travelled: Math.hypot(nextX - state.x, nextZ - state.z),
    blocked: false,
  };
};

