import { clamp, smoothstep } from '../utils/math';

export const OCEAN_ICE_VISIBILITY_TUNING = Object.freeze({
  waveExposureStart: 0.12,
  waveExposureEnd: 0.78,
  waveSampleThreshold: 0.002,
  revealSeconds: 0.56,
});

export const advanceOceanWaterReveal = (
  progress: number,
  deltaSeconds: number,
): number =>
  clamp(
    progress +
      Math.max(0, deltaSeconds) /
        OCEAN_ICE_VISIBILITY_TUNING.revealSeconds,
    0,
    1,
  );

export const resolveOceanIceWaveExposure = (
  openness: number,
  reveal: number,
  insideIceField = true,
): number => {
  if (!insideIceField) return 1;
  return (
    smoothstep(
      OCEAN_ICE_VISIBILITY_TUNING.waveExposureStart,
      OCEAN_ICE_VISIBILITY_TUNING.waveExposureEnd,
      clamp(openness, 0, 1),
    ) * clamp(reveal, 0, 1)
  );
};

export const shouldSampleOceanWaves = (
  exposure: number,
  layerStrength = 1,
): boolean =>
  exposure * layerStrength >=
  OCEAN_ICE_VISIBILITY_TUNING.waveSampleThreshold;

const glslFloat = (value: number): string => value.toFixed(4);

export const createOceanIceVisibilityGLSL = (): string => {
  const tuning = OCEAN_ICE_VISIBILITY_TUNING;
  return `
    float resolveOceanIceWaveExposure(
      float openness,
      float reveal,
      float insideIceField
    ) {
      float openWaterExposure = smoothstep(
        ${glslFloat(tuning.waveExposureStart)},
        ${glslFloat(tuning.waveExposureEnd)},
        clamp(openness, 0.0, 1.0)
      ) * clamp(reveal, 0.0, 1.0);
      return mix(1.0, openWaterExposure, insideIceField);
    }

    float resolveOceanWaveSampleGate(
      float exposure,
      float layerStrength
    ) {
      return step(
        ${glslFloat(tuning.waveSampleThreshold)},
        exposure * layerStrength
      );
    }
  `;
};
