import type { EmergentWorldRegistry } from './EmergentWorldRegistry';
import type { TravelSystem } from './TravelSystem';
import type { ServiceAvailability, ServiceRuntimeState } from './EmergentWorldTypes';

export interface ServiceTransition {
  serviceId: string;
  previousAvailability: ServiceAvailability;
  availability: ServiceAvailability;
  occurredAt: number;
  reason: string;
}

interface ServiceSystemSaveData { version: 1; states: ServiceRuntimeState[]; }

export type ServiceExternalGateResolver = (
  serviceId: string,
) => Readonly<{ available: boolean; reason?: string }>;

export class ServiceSimulationSystem {
  private readonly states = new Map<string, ServiceRuntimeState>();

  public constructor(
    private readonly registry: EmergentWorldRegistry,
    private readonly travel: TravelSystem,
    saved?: unknown,
    private readonly resolveExternalGate: ServiceExternalGateResolver = () => ({
      available: true,
    }),
  ) {
    for (const definition of registry.definitions.services) {
      this.states.set(definition.id, {
        serviceId: definition.id,
        availability: 'CLOSED',
        previousAvailability: 'CLOSED',
        stateChangedAt: 0,
        revision: 0,
        reason: 'NOT_EVALUATED',
      });
    }
    this.importState(saved);
  }

  public update(simulationTime: number): readonly ServiceTransition[] {
    const transitions: ServiceTransition[] = [];
    for (const definition of this.registry.definitions.services) {
      const state = this.states.get(definition.id)!;
      const owner = definition.ownerNpcId ? this.travel.getState(definition.ownerNpcId) : undefined;
      const gate = this.resolveExternalGate(definition.id);
      const staffed = !definition.openWhenStaffed ||
        (owner?.status === 'AT_LOCATION' &&
          owner.currentLocationId === definition.locationId);
      const next: ServiceAvailability = !gate.available
        ? 'CLOSED'
        : staffed
          ? 'OPEN'
          : 'UNSTAFFED';
      const reason = !gate.available
        ? gate.reason ?? 'EXTERNAL_SERVICE_GATE_CLOSED'
        : next === 'OPEN'
          ? 'REQUIRED_STAFF_PRESENT'
          : 'REQUIRED_STAFF_ABSENT';
      if (state.availability === next) continue;
      const previousAvailability = state.availability;
      state.previousAvailability = previousAvailability;
      state.availability = next;
      state.stateChangedAt = simulationTime;
      state.revision += 1;
      state.reason = reason;
      transitions.push({ serviceId: definition.id, previousAvailability, availability: next, occurredAt: simulationTime, reason });
    }
    return transitions;
  }

  public getState(serviceId: string): ServiceRuntimeState | undefined {
    const state = this.states.get(serviceId);
    return state ? { ...state } : undefined;
  }

  public getStates(): readonly ServiceRuntimeState[] {
    return [...this.states.values()].sort((a, b) => a.serviceId.localeCompare(b.serviceId)).map((state) => ({ ...state }));
  }

  public getAvailabilityCount(availability: ServiceAvailability): number {
    let count = 0;
    for (const state of this.states.values()) {
      if (state.availability === availability) count += 1;
    }
    return count;
  }

  public exportState(): ServiceSystemSaveData { return { version: 1, states: this.getStates().map((state) => ({ ...state })) }; }

  private importState(saved: unknown): boolean {
    const candidate = saved as Partial<ServiceSystemSaveData> | undefined;
    if (candidate?.version !== 1 || !Array.isArray(candidate.states)) return false;
    for (const state of candidate.states) {
      if (!this.registry.getService(state?.serviceId) || !['CLOSED', 'UNSTAFFED', 'OPEN'].includes(state.availability)) continue;
      this.states.set(state.serviceId, { ...state });
    }
    return true;
  }
}
