import { ICE_THICKNESS_THRESHOLDS } from '../ice/IceThicknessProfile';

export type IceShadowQuality = 'off' | 'near' | 'wide';

export interface IceShadowQualitySettings {
  enabled: boolean;
  casterRadius: number;
  cameraHalfWidth: number;
  cameraHalfHeight: number;
  mapSize: number;
  waterShadowStrength: number;
}

export const DEFAULT_ICE_SHADOW_QUALITY: IceShadowQuality = 'near';
export const ICE_SHADOW_CULL_HYSTERESIS = 4;

export const ICE_SHADOW_QUALITY_SETTINGS: Readonly<
  Record<IceShadowQuality, Readonly<IceShadowQualitySettings>>
> = Object.freeze({
  off: Object.freeze({
    enabled: false,
    casterRadius: 0,
    cameraHalfWidth: 26,
    cameraHalfHeight: 22,
    mapSize: 1024,
    waterShadowStrength: 0,
  }),
  near: Object.freeze({
    enabled: true,
    casterRadius: 26,
    cameraHalfWidth: 23,
    cameraHalfHeight: 18,
    mapSize: 2048,
    waterShadowStrength: 0.18,
  }),
  wide: Object.freeze({
    enabled: true,
    casterRadius: 52,
    cameraHalfWidth: 42,
    cameraHalfHeight: 34,
    mapSize: 2048,
    waterShadowStrength: 0.15,
  }),
});

const ICE_SHADOW_QUALITIES: readonly IceShadowQuality[] = [
  'off',
  'near',
  'wide',
];

export const cycleIceShadowQuality = (
  quality: IceShadowQuality,
): IceShadowQuality => {
  const index = ICE_SHADOW_QUALITIES.indexOf(quality);
  return ICE_SHADOW_QUALITIES[
    (index + 1) % ICE_SHADOW_QUALITIES.length
  ] ?? DEFAULT_ICE_SHADOW_QUALITY;
};

export const castsIceEdgeShadow = (thickness: number): boolean =>
  Number.isFinite(thickness) &&
  thickness >= ICE_THICKNESS_THRESHOLDS.medium;

export const isInsideIceShadowRange = (
  centerX: number,
  centerZ: number,
  boundingRadius: number,
  focusX: number,
  focusZ: number,
  casterRadius: number,
): boolean =>
  Math.hypot(centerX - focusX, centerZ - focusZ) <=
  Math.max(0, casterRadius) + Math.max(0, boundingRadius);

interface Point3 {
  x: number;
  y: number;
  z: number;
}

interface MutablePoint3 extends Point3 {
  x: number;
  y: number;
  z: number;
}

export const stabilizeIceShadowFocus = (
  focus: Readonly<Point3>,
  lightDirection: Readonly<Point3>,
  settings: Readonly<IceShadowQualitySettings>,
  target: MutablePoint3,
): MutablePoint3 => {
  const directionLength = Math.max(
    0.000001,
    Math.hypot(
      lightDirection.x,
      lightDirection.y,
      lightDirection.z,
    ),
  );
  const directionX = lightDirection.x / directionLength;
  const directionY = lightDirection.y / directionLength;
  const directionZ = lightDirection.z / directionLength;
  const horizontalLength = Math.max(
    0.000001,
    Math.hypot(directionX, directionZ),
  );

  const rightX = directionZ / horizontalLength;
  const rightZ = -directionX / horizontalLength;
  const upX = directionY * rightZ;
  const upY =
    directionZ * rightX -
    directionX * rightZ;
  const upZ = -directionY * rightX;

  const projectedRight =
    focus.x * rightX + focus.z * rightZ;
  const projectedUp =
    focus.x * upX + focus.y * upY + focus.z * upZ;
  const projectedDepth =
    focus.x * directionX +
    focus.y * directionY +
    focus.z * directionZ;
  const texelWidth =
    (settings.cameraHalfWidth * 2) / settings.mapSize;
  const texelHeight =
    (settings.cameraHalfHeight * 2) / settings.mapSize;
  const snappedRight =
    Math.round(projectedRight / texelWidth) * texelWidth;
  const snappedUp =
    Math.round(projectedUp / texelHeight) * texelHeight;

  target.x =
    rightX * snappedRight +
    upX * snappedUp +
    directionX * projectedDepth;
  target.y =
    upY * snappedUp +
    directionY * projectedDepth;
  target.z =
    rightZ * snappedRight +
    upZ * snappedUp +
    directionZ * projectedDepth;
  return target;
};
