import {
  globalPositionToAbsoluteMetres,
  normalizeGlobalPosition,
  type GlobalPosition,
} from './GlobalPosition';
import { ICEAWAY_TARGET_WORLD_PARTITION } from './WorldPartitionTypes';

export interface PrototypeLocalPosition {
  x: number;
  y: number;
  z: number;
}

export const ICEAWAY_PROTOTYPE_WORLD_ORIGIN: Readonly<GlobalPosition> =
  Object.freeze({
    chunk: Object.freeze({ x: 12, z: 16 }),
    local: Object.freeze({
      xMetres: 64,
      yMetres: 0,
      zMetres: 64,
    }),
  });

export const prototypeLocalToGlobalPosition = (
  position: Readonly<PrototypeLocalPosition>,
): GlobalPosition =>
  normalizeGlobalPosition(
    ICEAWAY_TARGET_WORLD_PARTITION,
    {
      chunk: { ...ICEAWAY_PROTOTYPE_WORLD_ORIGIN.chunk },
      local: {
        xMetres:
          ICEAWAY_PROTOTYPE_WORLD_ORIGIN.local.xMetres +
          position.x,
        yMetres:
          ICEAWAY_PROTOTYPE_WORLD_ORIGIN.local.yMetres +
          position.y,
        zMetres:
          ICEAWAY_PROTOTYPE_WORLD_ORIGIN.local.zMetres +
          position.z,
      },
    },
  );

export const prototypeGlobalToLocalPosition = (
  position: Readonly<GlobalPosition>,
): PrototypeLocalPosition => {
  const origin = globalPositionToAbsoluteMetres(
    ICEAWAY_TARGET_WORLD_PARTITION,
    ICEAWAY_PROTOTYPE_WORLD_ORIGIN,
  );
  const absolute = globalPositionToAbsoluteMetres(
    ICEAWAY_TARGET_WORLD_PARTITION,
    position,
  );
  return {
    x: absolute.xMetres - origin.xMetres,
    y: absolute.yMetres - origin.yMetres,
    z: absolute.zMetres - origin.zMetres,
  };
};
