import type { EmergentWorldRegistry } from './EmergentWorldRegistry';
import type { TravelSystem, TravelTransition } from './TravelSystem';
import type {
  NpcGoalDefinition,
  NpcRuntimeState,
  TravelAgentState,
} from './EmergentWorldTypes';

interface NpcSystemSaveData { version: 1; states: NpcRuntimeState[]; }

const cloneState = (state: Readonly<NpcRuntimeState>): NpcRuntimeState => ({
  ...state,
  completedGoalIds: [...state.completedGoalIds],
});

export interface NpcPresentationState {
  npcId: string;
  displayName: string;
  travel: TravelAgentState;
  activeGoalId?: string;
  color: number;
  scale: number;
}

export class NpcSimulationSystem {
  private readonly states = new Map<string, NpcRuntimeState>();

  public constructor(
    private readonly registry: EmergentWorldRegistry,
    private readonly travel: TravelSystem,
    saved?: unknown,
    private readonly goalAvailable: (
      goal: Readonly<NpcGoalDefinition>,
    ) => boolean = () => true,
  ) {
    for (const npc of registry.definitions.npcs) {
      this.states.set(npc.id, {
        npcId: npc.id,
        completedGoalIds: [],
        stateChangedAt: 0,
        lastDecision: 'WAITING_FOR_GOAL',
      });
    }
    this.importState(saved);
  }

  public plan(simulationTime: number): readonly TravelTransition[] {
    const transitions: TravelTransition[] = [];
    for (const definition of [...this.registry.definitions.npcs].sort((a, b) => a.id.localeCompare(b.id))) {
      const state = this.states.get(definition.id)!;
      const travelState = this.travel.getState(definition.id)!;
      if (travelState.status !== 'AT_LOCATION') continue;
      const unfinishedActiveGoalId =
        state.activeGoalId &&
        !state.completedGoalIds.includes(state.activeGoalId)
          ? state.activeGoalId
          : undefined;
      const requestedGoalId = state.goalOverrideId ?? unfinishedActiveGoalId;
      const goal = requestedGoalId
        ? definition.goals.find((value) => value.id === requestedGoalId)
        : [...definition.goals]
            .filter((value) => simulationTime >= (value.startAfterSeconds ?? 0))
            .filter((value) => !state.completedGoalIds.includes(value.id))
            .filter((value) => this.goalAvailable(value))
            .sort((a, b) => b.priority - a.priority || a.id.localeCompare(b.id))[0];
      if (!goal) continue;
      if (travelState.currentLocationId === goal.targetLocationId) {
        if (!state.completedGoalIds.includes(goal.id)) state.completedGoalIds.push(goal.id);
        state.activeGoalId = goal.id;
        state.lastDecision = `GOAL_SATISFIED_${goal.id}`;
        continue;
      }
      state.activeGoalId = goal.id;
      state.stateChangedAt = simulationTime;
      state.lastDecision = `REQUESTED_TRIP_FOR_${goal.id}`;
      const transition = this.travel.requestTrip(definition.id, goal.targetLocationId, simulationTime);
      if (transition) transitions.push(transition);
    }
    return transitions;
  }

  public reconcile(transitions: readonly TravelTransition[], simulationTime: number): void {
    for (const transition of transitions) {
      const state = this.states.get(transition.agentId);
      const definition = this.registry.getNpc(transition.agentId);
      if (!state || !definition) continue;
      state.stateChangedAt = simulationTime;
      state.lastDecision = transition.reason;
      if (transition.status !== 'AT_LOCATION' || !state.activeGoalId) continue;
      const goal = definition.goals.find((value) => value.id === state.activeGoalId);
      if (goal && transition.locationId === goal.targetLocationId && !state.completedGoalIds.includes(goal.id)) {
        state.completedGoalIds.push(goal.id);
      }
    }
  }

  /** Story quests may temporarily select an authored goal without rewriting AI state. */
  public setGoalOverride(npcId: string, goalId?: string, simulationTime = 0): boolean {
    const state = this.states.get(npcId);
    const definition = this.registry.getNpc(npcId);
    if (!state || !definition || (goalId && !definition.goals.some((goal) => goal.id === goalId))) return false;
    if (state.goalOverrideId === goalId) return false;
    state.goalOverrideId = goalId;
    state.stateChangedAt = simulationTime;
    state.lastDecision = goalId ? `STORY_GOAL_OVERRIDE_${goalId}` : 'STORY_GOAL_OVERRIDE_RELEASED';
    return true;
  }

  public getState(npcId: string): NpcRuntimeState | undefined {
    const state = this.states.get(npcId);
    return state ? cloneState(state) : undefined;
  }

  public getStates(): readonly NpcRuntimeState[] {
    return [...this.states.values()].sort((a, b) => a.npcId.localeCompare(b.npcId)).map(cloneState);
  }

  public getPresentationStates(): readonly NpcPresentationState[] {
    return this.registry.definitions.npcs.flatMap((definition) => {
      const state = this.states.get(definition.id);
      const travel = this.travel.getState(definition.id);
      if (!state || !travel) return [];
      return [{
        npcId: definition.id,
        displayName: definition.displayName,
        travel,
        activeGoalId: state.activeGoalId,
        color: definition.presentation?.color ?? 0x6d8f98,
        scale: definition.presentation?.scale ?? 1,
      }];
    });
  }

  public exportState(): NpcSystemSaveData { return { version: 1, states: this.getStates().map(cloneState) }; }

  private importState(saved: unknown): boolean {
    const candidate = saved as Partial<NpcSystemSaveData> | undefined;
    if (candidate?.version !== 1 || !Array.isArray(candidate.states)) return false;
    for (const value of candidate.states) {
      if (!this.registry.getNpc(value?.npcId)) continue;
      this.states.set(value.npcId, cloneState(value));
    }
    return true;
  }
}
