import type { SnowEmergencyPlowClass } from './SnowEmergencyCityLayout';
import type { SnowEmergencyCityStats } from './SnowEmergencyCitySystem';

export interface SnowEmergencyCityHUDActions {
  readonly onSelectCompact: () => void;
  readonly onSelectStandard: () => void;
  readonly onSelectHeavy: () => void;
  readonly onToggleCamera: () => void;
}

/**
 * A deliberately compact, scenario-local HUD. It keeps traffic and snow
 * consequences readable without burying the normal driving HUD in city-only
 * controls.
 */
export class SnowEmergencyCityHUD {
  private readonly element: HTMLElement;
  private readonly traffic: HTMLElement;
  private readonly roads: HTMLElement;
  private readonly plow: HTMLElement;
  private readonly camera: HTMLElement;

  public constructor(
    host: HTMLElement,
    actions: Readonly<SnowEmergencyCityHUDActions>,
  ) {
    this.element = document.createElement('aside');
    this.element.className = 'snow-city-hud is-hidden';
    this.element.setAttribute('aria-label', 'Northbridge snow emergency');
    this.element.innerHTML = `
      <header><span>✦</span><div><small>SNOW EMERGENCY</small><strong>NORTHBRIDGE</strong></div></header>
      <div class="snow-city-hud__row"><small>TRAFFIC</small><b data-city-traffic>360 LOGICAL</b></div>
      <div class="snow-city-hud__row"><small>PRIORITY ROADS</small><b data-city-roads>OBSERVING</b></div>
      <div class="snow-city-hud__row"><small>SURFACE</small><b data-city-plow>STANDARD PLOW</b></div>
      <div class="snow-city-hud__tools" aria-label="Snow emergency test vehicles">
        <button type="button" data-city-tool="compact"><b>1</b><span>SIDEWALK</span><small>COMPACT</small></button>
        <button type="button" data-city-tool="standard"><b>2</b><span>STREETS</span><small>STANDARD</small></button>
        <button type="button" data-city-tool="heavy"><b>3</b><span>BOULEVARD</span><small>HEAVY</small></button>
      </div>
      <button class="snow-city-hud__camera" type="button" data-city-camera><span>CAMERA</span><b data-city-camera-state>ISOMETRIC · Y</b></button>
      <p>Clear lanes before snow and packed ice stop traffic. Driver behaviour changes following distance, speed and crash risk.</p>
    `;
    host.append(this.element);
    this.traffic = this.require('[data-city-traffic]');
    this.roads = this.require('[data-city-roads]');
    this.plow = this.require('[data-city-plow]');
    this.camera = this.require('[data-city-camera-state]');
    this.element.querySelector('[data-city-tool="compact"]')
      ?.addEventListener('click', actions.onSelectCompact);
    this.element.querySelector('[data-city-tool="standard"]')
      ?.addEventListener('click', actions.onSelectStandard);
    this.element.querySelector('[data-city-tool="heavy"]')
      ?.addEventListener('click', actions.onSelectHeavy);
    this.element.querySelector('[data-city-camera]')
      ?.addEventListener('click', actions.onToggleCamera);
  }

  public setVisible(visible: boolean): void {
    this.element.classList.toggle('is-hidden', !visible);
  }

  public update(
    stats: Readonly<SnowEmergencyCityStats>,
    requiredPlow: SnowEmergencyPlowClass | undefined,
    cameraMode: 'ISOMETRIC' | 'CAB',
  ): void {
    this.traffic.textContent =
      `${stats.movingAgents} MOVE · ${stats.waitingAgents} WAIT · ${stats.crashedAgents} CRASH / ${stats.logicalAgents}`;
    this.roads.textContent =
      `${stats.passablePrioritySegments}/${stats.totalPrioritySegments} OPEN`;
    this.plow.textContent = requiredPlow
      ? `${requiredPlow} PLOW REQUIRED`
      : 'OFF THE ROAD';
    this.plow.dataset.plow = requiredPlow?.toLowerCase() ?? 'none';
    this.camera.textContent = `${cameraMode} · Y`;
  }

  public dispose(): void {
    this.element.remove();
  }

  private require(selector: string): HTMLElement {
    const element = this.element.querySelector<HTMLElement>(selector);
    if (!element) throw new Error(`Snow city HUD element missing: ${selector}`);
    return element;
  }
}
