import type { PenguinControlCommand } from '../input/PlayerPenguinController';
import { clamp, damp, smoothstep } from '../utils/math';
import { BOREALIS_ARRIVAL_LANDING, isBorealisLand } from './BorealisLand';

export interface PenguinState {
  x: number;
  z: number;
  heading: number;
  speed: number;
  blowerActive: boolean;
  snowDepth: number;
  /** Runtime-only height above the sampled walk surface. */
  verticalOffset: number;
  verticalVelocity: number;
  grounded: boolean;
}

export interface PenguinSaveData {
  version: 1;
  x: number;
  z: number;
  heading: number;
}

export interface PenguinWalkSurface {
  sampleDepth(x: number, z: number): number;
  /** Terrain slope in radians. Steeper, still-walkable ground slows feet. */
  sampleSlope?(x: number, z: number): number;
  canWalkAt?(x: number, z: number, verticalOffset: number): boolean;
}

export interface PenguinMovementIntent {
  moveX: number;
  moveZ: number;
  aimHeading?: number;
}

export interface PenguinStepResult {
  travelled: number;
  blocked: boolean;
}

export interface PenguinSnowResponse {
  speedMultiplier: number;
  sinkDepth: number;
  trailStrength: number;
}

export const resolvePenguinSnowResponse = (
  snowDepth: number,
): PenguinSnowResponse => {
  const depth = Math.max(0, snowDepth);
  const resistance = smoothstep(0.18, 1, depth);
  const wading = smoothstep(0.31, 0.66, depth);
  return {
    speedMultiplier: 1 - resistance * 0.58,
    sinkDepth:
      wading * clamp((depth - 0.28) * 0.52, 0, 0.36),
    trailStrength: smoothstep(0.32, 0.64, depth),
  };
};

export const writeHeadingRelativePenguinMovement = (
  right: number,
  forward: number,
  heading: number,
  target: PenguinMovementIntent,
): void => {
  const forwardX = Math.sin(heading);
  const forwardZ = Math.cos(heading);
  const rightX = Math.cos(heading);
  const rightZ = -Math.sin(heading);
  target.moveX = forwardX * forward + rightX * right;
  target.moveZ = forwardZ * forward + rightZ * right;
};

const WALK_SPEED = 1.38;
const RUN_SPEED = 2.18;

const angleDifference = (from: number, to: number): number =>
  Math.atan2(Math.sin(to - from), Math.cos(to - from));

export class PenguinSimulation {
  public readonly state: PenguinState = {
    x: BOREALIS_ARRIVAL_LANDING.x - 1.2,
    z: BOREALIS_ARRIVAL_LANDING.z + 1.5,
    heading: BOREALIS_ARRIVAL_LANDING.heading,
    speed: 0,
    blowerActive: false,
    snowDepth: 0,
    verticalOffset: 0,
    verticalVelocity: 0,
    grounded: true,
  };

  public step(
    command: Readonly<PenguinControlCommand>,
    deltaSeconds: number,
    surface: PenguinWalkSurface,
    intent: Readonly<PenguinMovementIntent>,
  ): PenguinStepResult {
    const delta = clamp(deltaSeconds, 0, 0.05);
    if (delta <= 0) return { travelled: 0, blocked: false };
    const state = this.state;
    state.blowerActive = command.blower;
    state.snowDepth = surface.sampleDepth(state.x, state.z);
    const snowResponse = resolvePenguinSnowResponse(state.snowDepth);
    const slopeRadians = Math.max(
      0,
      surface.sampleSlope?.(state.x, state.z) ?? 0,
    );
    // A moderate incline should feel laborious, not like an invisible wall.
    // The terrain walkability limit remains responsible for truly unsafe
    // faces; this multiplier gives the entire approach a readable gradient.
    const slopeSpeedMultiplier = 1 -
      smoothstep(Math.PI * 0.075, Math.PI * 0.267, slopeRadians) * 0.62;
    const maximumForward =
      (command.run ? RUN_SPEED : WALK_SPEED) *
      snowResponse.speedMultiplier *
      slopeSpeedMultiplier *
      (state.blowerActive ? 0.56 : 1);
    const movementMagnitude = clamp(
      Math.hypot(intent.moveX, intent.moveZ),
      0,
      1,
    );
    const targetSpeed = movementMagnitude * maximumForward;
    state.speed = damp(state.speed, targetSpeed, 8.5, delta);
    if (movementMagnitude < 0.01) {
      state.speed = damp(state.speed, 0, 11, delta);
    }
    if (command.jump && state.grounded) {
      state.verticalVelocity = 3.75;
      state.grounded = false;
    }
    if (!state.grounded) {
      state.verticalVelocity -= 9.4 * delta;
      state.verticalOffset += state.verticalVelocity * delta;
      if (state.verticalOffset <= 0) {
        state.verticalOffset = 0;
        state.verticalVelocity = 0;
        state.grounded = true;
      }
    }

    const movementHeading = movementMagnitude > 0.01
      ? Math.atan2(intent.moveX, intent.moveZ)
      : undefined;
    const targetHeading = intent.aimHeading ?? movementHeading;
    if (targetHeading !== undefined) {
      const response = intent.aimHeading === undefined ? 13 : 18;
      state.heading +=
        angleDifference(state.heading, targetHeading) *
        (1 - Math.exp(-response * delta));
    }

    const previousX = state.x;
    const previousZ = state.z;
    const directionScale = movementMagnitude > 0.001
      ? 1 / movementMagnitude
      : 0;
    const nextX =
      state.x + intent.moveX * directionScale * state.speed * delta;
    const nextZ =
      state.z + intent.moveZ * directionScale * state.speed * delta;
    const allowed =
      isBorealisLand(nextX, nextZ) &&
      (surface.canWalkAt?.(nextX, nextZ, state.verticalOffset) ?? true);
    let slid = false;
    if (allowed) {
      state.x = nextX;
      state.z = nextZ;
    } else {
      // A binary diagonal rejection makes a rounded cave wall feel sticky:
      // the blocked component also cancels the tangential component. Try the
      // two cardinal components independently so the actor glides along the
      // actual Surface Nets boundary instead of catching on every triangle.
      const canMoveX = Math.abs(nextX - previousX) > 0.000001 &&
        isBorealisLand(nextX, previousZ) &&
        (surface.canWalkAt?.(
          nextX,
          previousZ,
          state.verticalOffset,
        ) ?? true);
      if (canMoveX) {
        state.x = nextX;
        slid = true;
      }
      const canMoveZ = Math.abs(nextZ - previousZ) > 0.000001 &&
        isBorealisLand(state.x, nextZ) &&
        (surface.canWalkAt?.(
          state.x,
          nextZ,
          state.verticalOffset,
        ) ?? true);
      if (canMoveZ) {
        state.z = nextZ;
        slid = true;
      }
      if (!slid) state.speed = 0;
    }
    return {
      travelled: Math.hypot(state.x - previousX, state.z - previousZ),
      blocked: !allowed && !slid,
    };
  }

  public deployBesideVehicle(
    vehicle: Readonly<{ x: number; z: number; heading: number }>,
    canStandAt: (x: number, z: number) => boolean = () => true,
  ): void {
    const rightX = Math.cos(vehicle.heading);
    const rightZ = -Math.sin(vehicle.heading);
    const forwardX = Math.sin(vehicle.heading);
    const forwardZ = Math.cos(vehicle.heading);
    const candidates = [
      { side: 1.75, rear: 0 },
      { side: -1.75, rear: 0 },
      { side: 1.5, rear: -1.25 },
      { side: -1.5, rear: -1.25 },
    ];
    for (const candidate of candidates) {
      const x =
        vehicle.x + rightX * candidate.side + forwardX * candidate.rear;
      const z =
        vehicle.z + rightZ * candidate.side + forwardZ * candidate.rear;
      if (!isBorealisLand(x, z) || !canStandAt(x, z)) continue;
      this.state.x = x;
      this.state.z = z;
      this.state.heading = vehicle.heading;
      this.state.speed = 0;
      this.state.blowerActive = false;
      this.resetJump();
      return;
    }
    this.state.x = vehicle.x;
    this.state.z = vehicle.z;
    this.state.heading = vehicle.heading;
    this.state.speed = 0;
    this.state.blowerActive = false;
    this.resetJump();
  }

  public importState(saved: unknown): boolean {
    if (!saved || typeof saved !== 'object') return false;
    const candidate = saved as Partial<PenguinSaveData>;
    if (
      candidate.version !== 1 ||
      !Number.isFinite(candidate.x) ||
      !Number.isFinite(candidate.z) ||
      !Number.isFinite(candidate.heading) ||
      !isBorealisLand(candidate.x!, candidate.z!)
    ) {
      return false;
    }
    this.state.x = candidate.x!;
    this.state.z = candidate.z!;
    this.state.heading = candidate.heading!;
    this.state.speed = 0;
    this.state.blowerActive = false;
    this.resetJump();
    return true;
  }

  public exportState(): PenguinSaveData {
    return {
      version: 1,
      x: this.state.x,
      z: this.state.z,
      heading: this.state.heading,
    };
  }

  private resetJump(): void {
    this.state.verticalOffset = 0;
    this.state.verticalVelocity = 0;
    this.state.grounded = true;
  }
}
