import type { EmergentCausalityRecord } from './EmergentWorldTypes';

export class EmergentCausalityTrace {
  private readonly records: EmergentCausalityRecord[] = [];
  private sequence = 0;

  public constructor(private readonly maximumRecords = 1024) {}

  public record(input: Omit<EmergentCausalityRecord, 'sequence'>): void {
    this.records.push(Object.freeze({
      ...input,
      sequence: ++this.sequence,
      evidence: Object.freeze(input.evidence.map((value) => Object.freeze({ ...value }))),
    }));
    if (this.records.length > this.maximumRecords) {
      this.records.splice(0, this.records.length - this.maximumRecords);
    }
  }

  public inspect(subjectId?: string): readonly EmergentCausalityRecord[] {
    const values = subjectId
      ? this.records.filter((record) => record.subjectId === subjectId)
      : this.records;
    return Object.freeze([...values]);
  }

  public explain(subjectId: string): EmergentCausalityRecord | undefined {
    return [...this.records].reverse().find((record) => record.subjectId === subjectId);
  }

  public clear(): void {
    this.records.length = 0;
  }
}

