import { Matrix4, Quaternion, Vector3 } from 'three';
import { clamp } from '../utils/math';

export interface TerrainVehicleSurfaceNormal {
  readonly normalX: number;
  readonly normalY: number;
  readonly normalZ: number;
}

const FLAT_SURFACE: TerrainVehicleSurfaceNormal = Object.freeze({
  normalX: 0,
  normalY: 1,
  normalZ: 0,
});

/**
 * A reusable, allocation-free terrain pose for one heavy vehicle root.
 * Heading is preserved in the horizontal plane, then projected onto the
 * surface so local up follows the terrain normal. Rotation is spring-like but
 * angular-rate limited: a two-metre terrain vertex cannot instantly snap a
 * multi-ton machine onto a new slope.
 */
export class TerrainVehicleAttitude {
  private readonly current = new Quaternion();
  private readonly target = new Quaternion();
  private readonly normal = new Vector3(0, 1, 0);
  private readonly forward = new Vector3(0, 0, 1);
  private readonly right = new Vector3(1, 0, 0);
  private readonly basis = new Matrix4();
  private initialized = false;

  public update(
    heading: number,
    surface: Readonly<TerrainVehicleSurfaceNormal> = FLAT_SURFACE,
    deltaSeconds = 0,
    response = 3.6,
    maximumAngularSpeed = 0.72,
    maximumTiltRadians = Math.PI * 0.145,
  ): Quaternion {
    this.writeTarget(heading, surface, maximumTiltRadians);
    const delta = clamp(deltaSeconds, 0, 0.05);
    if (!this.initialized || delta <= 0) {
      this.current.copy(this.target);
      this.initialized = true;
      return this.current;
    }
    const angle = this.current.angleTo(this.target);
    if (angle <= 0.000001) return this.current;
    const springFraction = 1 - Math.exp(-Math.max(0.01, response) * delta);
    const rateFraction = Math.min(
      1,
      Math.max(0.01, maximumAngularSpeed) * delta / angle,
    );
    this.current.slerp(this.target, Math.min(springFraction, rateFraction));
    return this.current;
  }

  private writeTarget(
    heading: number,
    surface: Readonly<TerrainVehicleSurfaceNormal>,
    maximumTiltRadians: number,
  ): void {
    this.normal.set(
      Number.isFinite(surface.normalX) ? surface.normalX : 0,
      Number.isFinite(surface.normalY) ? surface.normalY : 1,
      Number.isFinite(surface.normalZ) ? surface.normalZ : 0,
    );
    if (this.normal.lengthSq() < 0.0001) this.normal.set(0, 1, 0);
    else this.normal.normalize();
    if (this.normal.y < 0) this.normal.multiplyScalar(-1);

    const maximumTilt = clamp(maximumTiltRadians, 0, Math.PI * 0.24);
    const tilt = Math.acos(clamp(this.normal.y, -1, 1));
    if (tilt > maximumTilt) {
      const horizontalLength = Math.hypot(this.normal.x, this.normal.z);
      if (horizontalLength > 0.0001) {
        const horizontalScale = Math.sin(maximumTilt) / horizontalLength;
        this.normal.set(
          this.normal.x * horizontalScale,
          Math.cos(maximumTilt),
          this.normal.z * horizontalScale,
        );
      } else {
        this.normal.set(0, 1, 0);
      }
    }

    this.forward.set(Math.sin(heading), 0, Math.cos(heading));
    this.forward.addScaledVector(
      this.normal,
      -this.forward.dot(this.normal),
    );
    if (this.forward.lengthSq() < 0.0001) {
      this.forward.set(Math.sin(heading), 0, Math.cos(heading));
    }
    this.forward.normalize();
    this.right.crossVectors(this.normal, this.forward).normalize();
    // Rebuild forward from the other two axes to eliminate accumulated
    // floating-point skew before constructing the quaternion basis.
    this.forward.crossVectors(this.right, this.normal).normalize();
    this.basis.makeBasis(this.right, this.normal, this.forward);
    this.target.setFromRotationMatrix(this.basis).normalize();
  }
}
