import {
  type NetworkEntityId,
  type PlayerId,
  type ServerTick,
  serverTick,
} from '../../netcode/core/NetworkPrimitives';
import type { PlayerCommandFrame } from '../../netcode/protocol/AuthorityIngress';
import {
  cloneReplicatedEntity,
  type EntityBaselinePayload,
  type EntityReliableDeltaPayload,
  type EntitySnapshotBatchPayload,
  type ReplicatedControlLeaseSnapshot,
  type ReplicatedEntitySnapshot,
} from '../../netcode/protocol/EntityReplication';
import { stepReplicatedEntityCommand } from '../replication/EntityKinematics';

export interface EntityReplicationClientDiagnostics {
  baselinesApplied: number;
  reliableDeltasApplied: number;
  snapshotBatchesApplied: number;
  stalePacketsDiscarded: number;
  predictedCommands: number;
  acknowledgedPredictedCommands: number;
  softCorrections: number;
  hardCorrections: number;
  largestCorrectionDistance: number;
  bufferedPredictedCommands: number;
  replicatedEntities: number;
}

interface SnapshotHistory {
  previous?: { tick: ServerTick; entity: ReplicatedEntitySnapshot };
  current: { tick: ServerTick; entity: ReplicatedEntitySnapshot };
}

interface PredictionRecord {
  predicted: ReplicatedEntitySnapshot;
  commands: Array<{ frame: PlayerCommandFrame; stepCount: number }>;
  lastActionBits: number;
  lastPredictedTick: ServerTick;
}

const angleDelta = (from: number, to: number): number =>
  Math.atan2(Math.sin(to - from), Math.cos(to - from));
const interpolate = (a: number, b: number, alpha: number): number =>
  a + (b - a) * alpha;
const cloneLease = (
  lease: Readonly<ReplicatedControlLeaseSnapshot>,
): ReplicatedControlLeaseSnapshot => ({ ...lease });
const leaseKey = (lease: Readonly<ReplicatedControlLeaseSnapshot>): string =>
  `${lease.entityId}\u001f${lease.slotId}`;

/** Client-owned canonical history, interpolation and bounded local prediction. */
export class EntityReplicationClient {
  private readonly entities = new Map<NetworkEntityId, SnapshotHistory>();
  private readonly leases = new Map<string, ReplicatedControlLeaseSnapshot>();
  private readonly predictions = new Map<NetworkEntityId, PredictionRecord>();
  private baselineRevision = 0;
  private deltaRevision = 0;
  private snapshotSequence = 0;
  private latestTick = serverTick(0);
  private readonly stats: Omit<
    EntityReplicationClientDiagnostics,
    'bufferedPredictedCommands' | 'replicatedEntities'
  > = {
    baselinesApplied: 0,
    reliableDeltasApplied: 0,
    snapshotBatchesApplied: 0,
    stalePacketsDiscarded: 0,
    predictedCommands: 0,
    acknowledgedPredictedCommands: 0,
    softCorrections: 0,
    hardCorrections: 0,
    largestCorrectionDistance: 0,
  };

  public constructor(
    private readonly localPlayer: () => PlayerId | undefined,
    private readonly fixedDeltaSeconds = 1 / 60,
    private readonly interpolationDelayTicks = 6,
  ) {}

  public applyBaseline(payload: Readonly<EntityBaselinePayload>): boolean {
    if (payload.baselineRevision < this.baselineRevision) {
      this.stats.stalePacketsDiscarded += 1;
      return false;
    }
    this.entities.clear();
    for (const entity of payload.entities) {
      this.entities.set(entity.entityId, {
        current: { tick: payload.serverTick, entity: cloneReplicatedEntity(entity) },
      });
    }
    this.replaceLeases(payload.leases);
    this.baselineRevision = payload.baselineRevision;
    this.deltaRevision = 0;
    this.snapshotSequence = 0;
    this.latestTick = payload.serverTick;
    this.predictions.clear();
    this.stats.baselinesApplied += 1;
    return true;
  }

  public applyReliableDelta(payload: Readonly<EntityReliableDeltaPayload>): boolean {
    if (payload.deltaRevision <= this.deltaRevision) {
      this.stats.stalePacketsDiscarded += 1;
      return false;
    }
    for (const entityId of payload.removedEntityIds) {
      this.entities.delete(entityId);
      this.predictions.delete(entityId);
    }
    for (const entity of payload.entities) this.acceptEntity(entity, payload.serverTick);
    this.replaceLeases(payload.leases);
    this.deltaRevision = payload.deltaRevision;
    if (payload.serverTick > this.latestTick) this.latestTick = payload.serverTick;
    this.stats.reliableDeltasApplied += 1;
    return true;
  }

  public applySnapshotBatch(payload: Readonly<EntitySnapshotBatchPayload>): boolean {
    if (payload.snapshotSequence <= this.snapshotSequence) {
      this.stats.stalePacketsDiscarded += 1;
      return false;
    }
    for (const entity of payload.entities) {
      this.acceptEntity(entity, payload.serverTick);
      this.reconcilePrediction(entity);
    }
    this.snapshotSequence = payload.snapshotSequence;
    if (payload.serverTick > this.latestTick) this.latestTick = payload.serverTick;
    this.stats.snapshotBatchesApplied += 1;
    return true;
  }

  public recordPredictedCommand(command: Readonly<PlayerCommandFrame>): void {
    const local = this.localPlayer();
    if (!local || command.playerId !== local || !command.controlledEntityId) return;
    const history = this.entities.get(command.controlledEntityId);
    if (!history) return;
    const prediction = this.predictions.get(command.controlledEntityId) ?? {
      predicted: cloneReplicatedEntity(history.current.entity),
      commands: [],
      lastActionBits: 0,
      lastPredictedTick: history.current.tick,
    };
    const cloned: PlayerCommandFrame = {
      ...command,
      movement: { ...command.movement },
      tool: { ...command.tool },
    };
    const stepCount = Math.max(
      1,
      Math.min(8, cloned.predictedTick - prediction.lastPredictedTick),
    );
    prediction.commands.push({ frame: cloned, stepCount });
    while (prediction.commands.length > 256) prediction.commands.shift();
    for (let step = 0; step < stepCount; step += 1) {
      stepReplicatedEntityCommand(
        prediction.predicted,
        cloned,
        this.fixedDeltaSeconds,
        prediction.lastActionBits,
      );
    }
    prediction.lastActionBits = cloned.actionBits;
    prediction.lastPredictedTick = cloned.predictedTick;
    this.predictions.set(command.controlledEntityId, prediction);
    this.stats.predictedCommands += 1;
  }

  public canonical(entityId: NetworkEntityId): ReplicatedEntitySnapshot | undefined {
    const entity = this.entities.get(entityId)?.current.entity;
    return entity ? cloneReplicatedEntity(entity) : undefined;
  }

  public predicted(entityId: NetworkEntityId): ReplicatedEntitySnapshot | undefined {
    const entity = this.predictions.get(entityId)?.predicted;
    return entity ? cloneReplicatedEntity(entity) : this.canonical(entityId);
  }

  public sample(
    entityId: NetworkEntityId,
    renderTick: number = this.latestTick - this.interpolationDelayTicks,
  ): ReplicatedEntitySnapshot | undefined {
    const history = this.entities.get(entityId);
    if (!history) return undefined;
    const previous = history.previous;
    const current = history.current;
    if (!previous || current.tick <= previous.tick) return cloneReplicatedEntity(current.entity);
    const alpha = Math.max(0, Math.min(1, (renderTick - previous.tick) / (current.tick - previous.tick)));
    const sampled = cloneReplicatedEntity(current.entity);
    const a = previous.entity.root;
    const b = current.entity.root;
    sampled.root.x = interpolate(a.x, b.x, alpha);
    sampled.root.y = interpolate(a.y, b.y, alpha);
    sampled.root.z = interpolate(a.z, b.z, alpha);
    sampled.root.heading = a.heading + angleDelta(a.heading, b.heading) * alpha;
    sampled.root.pitch = interpolate(a.pitch, b.pitch, alpha);
    sampled.root.roll = interpolate(a.roll, b.roll, alpha);
    sampled.root.velocityX = interpolate(a.velocityX, b.velocityX, alpha);
    sampled.root.velocityY = interpolate(a.velocityY, b.velocityY, alpha);
    sampled.root.velocityZ = interpolate(a.velocityZ, b.velocityZ, alpha);
    sampled.tool.primaryPosition = interpolate(
      previous.entity.tool.primaryPosition,
      current.entity.tool.primaryPosition,
      alpha,
    );
    sampled.tool.secondaryPosition = interpolate(
      previous.entity.tool.secondaryPosition,
      current.entity.tool.secondaryPosition,
      alpha,
    );
    return sampled;
  }

  public listCanonical(): readonly ReplicatedEntitySnapshot[] {
    return [...this.entities.values()]
      .map((history) => cloneReplicatedEntity(history.current.entity))
      .sort((a, b) => a.entityId.localeCompare(b.entityId));
  }

  public listLeases(): readonly ReplicatedControlLeaseSnapshot[] {
    return [...this.leases.values()].map(cloneLease);
  }

  public controlledEntityForLocalPlayer(): NetworkEntityId | undefined {
    const player = this.localPlayer();
    if (!player) return undefined;
    return [...this.leases.values()].find(
      (lease) => lease.state === 'HELD' && lease.holderPlayerId === player,
    )?.entityId;
  }

  public diagnostics(): EntityReplicationClientDiagnostics {
    let bufferedPredictedCommands = 0;
    for (const prediction of this.predictions.values()) {
      bufferedPredictedCommands += prediction.commands.length;
    }
    return {
      ...this.stats,
      bufferedPredictedCommands,
      replicatedEntities: this.entities.size,
    };
  }

  /** Drops every old-epoch interpolation and prediction input. */
  public reset(): void {
    this.entities.clear();
    this.leases.clear();
    this.predictions.clear();
    this.baselineRevision = 0;
    this.deltaRevision = 0;
    this.snapshotSequence = 0;
    this.latestTick = serverTick(0);
  }

  private acceptEntity(entity: Readonly<ReplicatedEntitySnapshot>, tick: ServerTick): void {
    const existing = this.entities.get(entity.entityId);
    if (existing && tick < existing.current.tick) return;
    this.entities.set(entity.entityId, {
      previous: existing?.current,
      current: { tick, entity: cloneReplicatedEntity(entity) },
    });
  }

  private reconcilePrediction(canonical: Readonly<ReplicatedEntitySnapshot>): void {
    const prediction = this.predictions.get(canonical.entityId);
    if (!prediction || canonical.lastProcessedCommandSequence === undefined) return;
    const acknowledged = canonical.lastProcessedCommandSequence;
    const predictedBefore = prediction.predicted;
    const correctionDistance = Math.hypot(
      predictedBefore.root.x - canonical.root.x,
      predictedBefore.root.y - canonical.root.y,
      predictedBefore.root.z - canonical.root.z,
    );
    this.stats.largestCorrectionDistance = Math.max(
      this.stats.largestCorrectionDistance,
      correctionDistance,
    );
    if (correctionDistance > 2) this.stats.hardCorrections += 1;
    else if (correctionDistance > 0.05) this.stats.softCorrections += 1;
    const beforeCount = prediction.commands.length;
    prediction.commands = prediction.commands.filter(
      ({ frame }) => frame.commandSequence > acknowledged,
    );
    this.stats.acknowledgedPredictedCommands += beforeCount - prediction.commands.length;
    prediction.predicted = cloneReplicatedEntity(canonical);
    prediction.lastActionBits = 0;
    for (const { frame, stepCount } of prediction.commands) {
      for (let step = 0; step < stepCount; step += 1) {
        stepReplicatedEntityCommand(
          prediction.predicted,
          frame,
          this.fixedDeltaSeconds,
          prediction.lastActionBits,
        );
      }
      prediction.lastActionBits = frame.actionBits;
      prediction.lastPredictedTick = frame.predictedTick;
    }
    if (prediction.commands.length === 0) this.predictions.delete(canonical.entityId);
  }

  private replaceLeases(leases: readonly ReplicatedControlLeaseSnapshot[]): void {
    this.leases.clear();
    for (const lease of leases) this.leases.set(leaseKey(lease), cloneLease(lease));
  }
}
