import { deterministicStateHash } from '../../netcode/core/DeterministicStateHash';
import {
  cloneInfrastructureMachine,
  cloneInfrastructureManifest,
  cloneInfrastructureService,
  cloneInfrastructureSite,
  validateInfrastructureSiteRuntime,
  type InfrastructureMachineRuntimeSnapshot,
  type InfrastructureServiceRuntimeSnapshot,
  type InfrastructureSiteRuntimeManifest,
  type InfrastructureSiteRuntimeSnapshot,
  type InfrastructureStateBaselinePartPayload,
  type InfrastructureStateDeltaPartPayload,
  type InfrastructureStateResyncRequestPayload,
} from '../../netcode/protocol/InfrastructureReplication';

export interface InfrastructureReplicationClientDiagnostics {
  revision: number;
  sites: number;
  machines: number;
  services: number;
  completedBaselines: number;
  appliedDeltas: number;
  staleDeltas: number;
  rejectedBaselines: number;
  rejectedDeltas: number;
  resyncRequests: number;
  pendingBaselineTransfers: number;
  pendingDeltaTransfers: number;
}

export type InfrastructureReplicationClientEvent =
  | {
      readonly kind: 'BASELINE';
      readonly payload: Readonly<InfrastructureStateBaselinePartPayload>;
      readonly sites: readonly InfrastructureSiteRuntimeSnapshot[];
    }
  | {
      readonly kind: 'DELTA';
      readonly payload: Readonly<InfrastructureStateDeltaPartPayload>;
      readonly site: Readonly<InfrastructureSiteRuntimeSnapshot>;
    };

interface PendingInfrastructureBaseline {
  readonly transferId: string;
  readonly revision: number;
  readonly partCount: number;
  readonly serverTick: number;
  readonly manifestsHash: string;
  readonly manifests: readonly InfrastructureSiteRuntimeManifest[];
  readonly totalMachineCount: number;
  readonly totalServiceCount: number;
  readonly parts: Map<number, InfrastructureStateBaselinePartPayload>;
}

interface PendingInfrastructureDelta {
  readonly transferId: string;
  readonly baseRevision: number;
  readonly revision: number;
  readonly partCount: number;
  readonly serverTick: number;
  readonly manifestHash: string;
  readonly manifest: InfrastructureSiteRuntimeManifest;
  readonly parts: Map<number, InfrastructureStateDeltaPartPayload>;
}

const recordHash = (record: object): string => deterministicStateHash({
  ...record,
  runtimeRevision: 0,
});

const baselineHeaderHash = (
  manifests: readonly Readonly<InfrastructureSiteRuntimeManifest>[],
): string => deterministicStateHash(manifests);

const manifestHash = (
  manifest: Readonly<InfrastructureSiteRuntimeManifest>,
): string => deterministicStateHash(manifest);

/** Atomically applies complete infrastructure baselines and multipart deltas. */
export class InfrastructureReplicationClient {
  private readonly sites = new Map<string, InfrastructureSiteRuntimeSnapshot>();
  private readonly pendingBaselines = new Map<
    string,
    PendingInfrastructureBaseline
  >();
  private readonly pendingDeltas = new Map<string, PendingInfrastructureDelta>();
  private pendingResync?: InfrastructureStateResyncRequestPayload;
  private revisionValue = 0;
  private completedBaselines = 0;
  private appliedDeltas = 0;
  private staleDeltas = 0;
  private rejectedBaselines = 0;
  private rejectedDeltas = 0;
  private resyncRequestCount = 0;

  public constructor(
    private readonly expectedWorldDatasetHash: string,
    private readonly requestResync?: (
      request: Readonly<InfrastructureStateResyncRequestPayload>,
    ) => void,
  ) {}

  public get revision(): number {
    return this.revisionValue;
  }

  public listSites(): readonly InfrastructureSiteRuntimeSnapshot[] {
    return [...this.sites.values()]
      .sort((left, right) => left.siteId.localeCompare(right.siteId))
      .map(cloneInfrastructureSite);
  }

  public getSite(siteId: string): InfrastructureSiteRuntimeSnapshot | undefined {
    const site = this.sites.get(siteId);
    return site ? cloneInfrastructureSite(site) : undefined;
  }

  public diagnostics(): InfrastructureReplicationClientDiagnostics {
    return {
      revision: this.revisionValue,
      sites: this.sites.size,
      machines: [...this.sites.values()].reduce(
        (total, site) => total + site.machineCount,
        0,
      ),
      services: [...this.sites.values()].reduce(
        (total, site) => total + site.serviceCount,
        0,
      ),
      completedBaselines: this.completedBaselines,
      appliedDeltas: this.appliedDeltas,
      staleDeltas: this.staleDeltas,
      rejectedBaselines: this.rejectedBaselines,
      rejectedDeltas: this.rejectedDeltas,
      resyncRequests: this.resyncRequestCount,
      pendingBaselineTransfers: this.pendingBaselines.size,
      pendingDeltaTransfers: this.pendingDeltas.size,
    };
  }

  public applyBaselinePart(
    payload: Readonly<InfrastructureStateBaselinePartPayload>,
  ): InfrastructureReplicationClientEvent | undefined {
    if (
      payload.worldDatasetHash !== this.expectedWorldDatasetHash ||
      payload.revision < this.revisionValue
    ) {
      this.rejectedBaselines += 1;
      return undefined;
    }
    const headerHash = baselineHeaderHash(payload.sites);
    let transfer = this.pendingBaselines.get(payload.transferId);
    if (!transfer) {
      transfer = {
        transferId: payload.transferId,
        revision: payload.revision,
        partCount: payload.partCount,
        serverTick: payload.serverTick,
        manifestsHash: headerHash,
        manifests: payload.sites.map(cloneInfrastructureManifest),
        totalMachineCount: payload.totalMachineCount,
        totalServiceCount: payload.totalServiceCount,
        parts: new Map(),
      };
      this.pendingBaselines.set(payload.transferId, transfer);
      this.trimPending(this.pendingBaselines);
    }
    if (
      transfer.revision !== payload.revision ||
      transfer.partCount !== payload.partCount ||
      transfer.serverTick !== payload.serverTick ||
      transfer.manifestsHash !== headerHash ||
      transfer.totalMachineCount !== payload.totalMachineCount ||
      transfer.totalServiceCount !== payload.totalServiceCount
    ) {
      this.rejectBaseline(payload.transferId);
      return undefined;
    }
    const existing = transfer.parts.get(payload.partIndex);
    if (existing && deterministicStateHash(existing) !== deterministicStateHash(payload)) {
      this.rejectBaseline(payload.transferId);
      return undefined;
    }
    if (!existing) transfer.parts.set(payload.partIndex, this.cloneBaselinePart(payload));
    if (transfer.parts.size !== transfer.partCount) return undefined;
    this.pendingBaselines.delete(payload.transferId);
    const assembled = this.assembleBaseline(transfer);
    if (!assembled) {
      this.rejectedBaselines += 1;
      this.queueResync();
      return undefined;
    }
    this.sites.clear();
    for (const site of assembled) this.sites.set(site.siteId, site);
    this.revisionValue = payload.revision;
    this.completedBaselines += 1;
    this.pendingDeltas.clear();
    this.pendingResync = undefined;
    return {
      kind: 'BASELINE',
      payload,
      sites: this.listSites(),
    };
  }

  public applyDeltaPart(
    payload: Readonly<InfrastructureStateDeltaPartPayload>,
  ): InfrastructureReplicationClientEvent | undefined {
    if (payload.revision <= this.revisionValue) {
      this.staleDeltas += 1;
      return undefined;
    }
    if (payload.baseRevision !== this.revisionValue) {
      this.rejectedDeltas += 1;
      this.pendingDeltas.delete(payload.transferId);
      this.queueResync();
      return undefined;
    }
    const headerHash = manifestHash(payload.site);
    let transfer = this.pendingDeltas.get(payload.transferId);
    if (!transfer) {
      transfer = {
        transferId: payload.transferId,
        baseRevision: payload.baseRevision,
        revision: payload.revision,
        partCount: payload.partCount,
        serverTick: payload.serverTick,
        manifestHash: headerHash,
        manifest: cloneInfrastructureManifest(payload.site),
        parts: new Map(),
      };
      this.pendingDeltas.set(payload.transferId, transfer);
      this.trimPending(this.pendingDeltas);
    }
    if (
      transfer.baseRevision !== payload.baseRevision ||
      transfer.revision !== payload.revision ||
      transfer.partCount !== payload.partCount ||
      transfer.serverTick !== payload.serverTick ||
      transfer.manifestHash !== headerHash
    ) {
      this.rejectDelta(payload.transferId);
      return undefined;
    }
    const existing = transfer.parts.get(payload.partIndex);
    if (existing && deterministicStateHash(existing) !== deterministicStateHash(payload)) {
      this.rejectDelta(payload.transferId);
      return undefined;
    }
    if (!existing) transfer.parts.set(payload.partIndex, this.cloneDeltaPart(payload));
    if (transfer.parts.size !== transfer.partCount) return undefined;
    this.pendingDeltas.delete(payload.transferId);
    const site = this.assembleDelta(transfer);
    if (!site || !this.hasContiguousRuntimeRevisions(site)) {
      this.rejectedDeltas += 1;
      this.queueResync();
      return undefined;
    }
    this.sites.set(site.siteId, site);
    this.revisionValue = payload.revision;
    this.appliedDeltas += 1;
    this.pendingResync = undefined;
    return {
      kind: 'DELTA',
      payload,
      site: cloneInfrastructureSite(site),
    };
  }

  public drainResyncRequests(): readonly InfrastructureStateResyncRequestPayload[] {
    if (this.requestResync || !this.pendingResync) return [];
    const request = this.pendingResync;
    this.pendingResync = undefined;
    return [request];
  }

  public reset(): void {
    this.sites.clear();
    this.pendingBaselines.clear();
    this.pendingDeltas.clear();
    this.pendingResync = undefined;
    this.revisionValue = 0;
  }

  private assembleBaseline(
    transfer: Readonly<PendingInfrastructureBaseline>,
  ): InfrastructureSiteRuntimeSnapshot[] | undefined {
    const records = this.assembleRecords(
      transfer.parts.values(),
      transfer.totalMachineCount,
      transfer.totalServiceCount,
    );
    if (!records) return undefined;
    if (
      transfer.manifests.reduce((total, site) => total + site.machineCount, 0) !==
        transfer.totalMachineCount ||
      transfer.manifests.reduce((total, site) => total + site.serviceCount, 0) !==
        transfer.totalServiceCount
    ) return undefined;
    const machinesBySite = new Map<string, InfrastructureMachineRuntimeSnapshot[]>();
    const servicesBySite = new Map<string, InfrastructureServiceRuntimeSnapshot[]>();
    for (const machine of records.machines) {
      const list = machinesBySite.get(machine.siteId) ?? [];
      list.push(machine);
      machinesBySite.set(machine.siteId, list);
    }
    for (const service of records.services) {
      const list = servicesBySite.get(service.siteId) ?? [];
      list.push(service);
      servicesBySite.set(service.siteId, list);
    }
    const manifestIds = new Set(transfer.manifests.map((site) => site.siteId));
    if (
      [...machinesBySite.keys()].some((siteId) => !manifestIds.has(siteId)) ||
      [...servicesBySite.keys()].some((siteId) => !manifestIds.has(siteId))
    ) return undefined;
    const sites = transfer.manifests.map((manifest) => ({
      ...cloneInfrastructureManifest(manifest),
      machines: (machinesBySite.get(manifest.siteId) ?? [])
        .sort((left, right) => left.pieceId.localeCompare(right.pieceId)),
      services: (servicesBySite.get(manifest.siteId) ?? [])
        .sort((left, right) => left.serviceId.localeCompare(right.serviceId)),
    }));
    return sites.every((site) => !validateInfrastructureSiteRuntime(site))
      ? sites
      : undefined;
  }

  private assembleDelta(
    transfer: Readonly<PendingInfrastructureDelta>,
  ): InfrastructureSiteRuntimeSnapshot | undefined {
    const records = this.assembleRecords(
      transfer.parts.values(),
      transfer.manifest.machineCount,
      transfer.manifest.serviceCount,
    );
    if (!records) return undefined;
    const site: InfrastructureSiteRuntimeSnapshot = {
      ...cloneInfrastructureManifest(transfer.manifest),
      machines: records.machines.sort((left, right) =>
        left.pieceId.localeCompare(right.pieceId)),
      services: records.services.sort((left, right) =>
        left.serviceId.localeCompare(right.serviceId)),
    };
    return validateInfrastructureSiteRuntime(site) ? undefined : site;
  }

  private assembleRecords(
    parts: Iterable<
      Readonly<
        InfrastructureStateBaselinePartPayload | InfrastructureStateDeltaPartPayload
      >
    >,
    machineCount: number,
    serviceCount: number,
  ): {
    machines: InfrastructureMachineRuntimeSnapshot[];
    services: InfrastructureServiceRuntimeSnapshot[];
  } | undefined {
    const machines = new Array<InfrastructureMachineRuntimeSnapshot | undefined>(
      machineCount,
    );
    const services = new Array<InfrastructureServiceRuntimeSnapshot | undefined>(
      serviceCount,
    );
    for (const part of [...parts].sort(
      (left, right) => left.partIndex - right.partIndex,
    )) {
      for (let index = 0; index < part.machines.length; index += 1) {
        const target = part.machineOffset + index;
        if (target >= machines.length || machines[target]) return undefined;
        machines[target] = cloneInfrastructureMachine(part.machines[index]!);
      }
      for (let index = 0; index < part.services.length; index += 1) {
        const target = part.serviceOffset + index;
        if (target >= services.length || services[target]) return undefined;
        services[target] = cloneInfrastructureService(part.services[index]!);
      }
    }
    if (machines.some((item) => !item) || services.some((item) => !item)) {
      return undefined;
    }
    return {
      machines: machines as InfrastructureMachineRuntimeSnapshot[],
      services: services as InfrastructureServiceRuntimeSnapshot[],
    };
  }

  private hasContiguousRuntimeRevisions(
    next: Readonly<InfrastructureSiteRuntimeSnapshot>,
  ): boolean {
    const current = this.sites.get(next.siteId);
    if (!current) {
      return next.revision === 0 &&
        next.machines.every((machine) => machine.runtimeRevision === 0) &&
        next.services.every((service) => service.runtimeRevision === 0);
    }
    if (next.revision !== current.revision + 1) return false;
    const currentMachines = new Map(
      current.machines.map((machine) => [machine.pieceId, machine] as const),
    );
    const currentServices = new Map(
      current.services.map((service) => [service.serviceId, service] as const),
    );
    for (const machine of next.machines) {
      const previous = currentMachines.get(machine.pieceId);
      if (!this.recordRevisionIsValid(previous, machine)) return false;
    }
    for (const service of next.services) {
      const previous = currentServices.get(service.serviceId);
      if (!this.recordRevisionIsValid(previous, service)) return false;
    }
    return true;
  }

  private recordRevisionIsValid(
    previous: Readonly<{ runtimeRevision: number }> | undefined,
    next: Readonly<{ runtimeRevision: number }>,
  ): boolean {
    if (!previous) return next.runtimeRevision === 0;
    const changed = recordHash(previous) !== recordHash(next);
    return next.runtimeRevision === previous.runtimeRevision + (changed ? 1 : 0);
  }

  private rejectBaseline(transferId: string): void {
    this.pendingBaselines.delete(transferId);
    this.rejectedBaselines += 1;
    this.queueResync();
  }

  private rejectDelta(transferId: string): void {
    this.pendingDeltas.delete(transferId);
    this.rejectedDeltas += 1;
    this.queueResync();
  }

  private queueResync(): void {
    if (this.pendingResync) return;
    const request: InfrastructureStateResyncRequestPayload = {
      version: 1,
      kind: 'INFRASTRUCTURE_STATE_RESYNC_REQUEST',
      observedRevision: this.revisionValue,
    };
    this.pendingResync = request;
    this.resyncRequestCount += 1;
    this.requestResync?.(request);
  }

  private trimPending<T>(map: Map<string, T>): void {
    while (map.size > 4) {
      const oldest = map.keys().next().value as string | undefined;
      if (!oldest) break;
      map.delete(oldest);
    }
  }

  private cloneBaselinePart(
    payload: Readonly<InfrastructureStateBaselinePartPayload>,
  ): InfrastructureStateBaselinePartPayload {
    return {
      ...payload,
      sites: payload.sites.map(cloneInfrastructureManifest),
      machines: payload.machines.map(cloneInfrastructureMachine),
      services: payload.services.map(cloneInfrastructureService),
    };
  }

  private cloneDeltaPart(
    payload: Readonly<InfrastructureStateDeltaPartPayload>,
  ): InfrastructureStateDeltaPartPayload {
    return {
      ...payload,
      site: cloneInfrastructureManifest(payload.site),
      machines: payload.machines.map(cloneInfrastructureMachine),
      services: payload.services.map(cloneInfrastructureService),
    };
  }
}
