export interface PortableInventoryContainerCheckpoint {
  readonly containerId: string;
  readonly worldPosition: GlobalPosition;
  readonly slots: readonly PortableInventorySlotDefinition[];
}

export interface InventoryTransactionJournalEntry {
  readonly requestId: TransactionId;
  readonly fingerprint: string;
  readonly result: Omit<InventoryAuthorityOperationResult, 'replayed'>;
}

export interface MultiplayerInventoryAuthorityCheckpoint {
  readonly version: 1;
  readonly revision: number;
  readonly nextItemSequence: number;
  readonly containers: readonly PortableInventoryContainerCheckpoint[];
  readonly items: readonly PortableItemSnapshot[];
  readonly contents: readonly InventoryContentSnapshot[];
  readonly transactionJournal: readonly InventoryTransactionJournalEntry[];
}

export interface InventoryAuthorityOperationContext {
  readonly serverTick: ServerTick;
  readonly actorPosition: Readonly<GlobalPosition>;
  readonly resolvePlayerPosition: (
    playerId: PlayerId,
  ) => Readonly<GlobalPosition> | undefined;
  readonly resolveEntityPosition: (
    entityId: NetworkEntityId,
  ) => Readonly<GlobalPosition> | undefined;
}

export interface MultiplayerInventoryAuthorityOptions {
  readonly checkpoint?: Readonly<MultiplayerInventoryAuthorityCheckpoint>;
  readonly initialItems?: readonly Readonly<PortableItemSnapshot>[];
  readonly initialContents?: readonly Readonly<InventoryContentSnapshot>[];
  readonly containers?: readonly Readonly<PortableWorldContainerDefinition>[];
  readonly itemDefinitions?: ReadonlyMap<string, Readonly<PortableItemDefinition>>;
  readonly maximumItems?: number;
  readonly maximumContents?: number;
  readonly maximumRememberedTransactions?: number;
  readonly interactionRadiusMetres?: number;
  /** Give every player one personal starter blower in a quick slot. */
  readonly grantStarterFieldKit?: boolean;
}

export interface InventoryAuthorityOperationResult {
  readonly accepted: boolean;
  readonly status: string;
  readonly stateChanged: boolean;
  readonly revision: number;
  readonly itemRevision?: number;
  readonly delta?: InventoryStateDeltaPayload;
  readonly replayed: boolean;
}

