const PORTABLE_OPERATIONS = new Set<InventoryStateDeltaPayload['operation']>([
  'PICKUP_ITEM',
  'PLACE_ITEM',
  'STORE_ITEM',
  'TAKE_ITEM',
  'GIVE_ITEM',
  'MOVE_ITEM',
  'CONSUME_ITEM',
]);

const jsonClone = <T>(value: T): T =>
  JSON.parse(JSON.stringify(value)) as T;

const boundedId = (value: unknown, maximum = 160): value is string =>
  typeof value === 'string' &&
  value.trim().length > 0 &&
  value.length <= maximum;

const natural = (value: unknown): value is number =>
  typeof value === 'number' &&
  Number.isSafeInteger(value) &&
  value >= 0;

const cloneSlotDefinition = (
  slot: Readonly<PortableInventorySlotDefinition>,
): PortableInventorySlotDefinition => ({
  slotId: slot.slotId,
  ...(slot.acceptedTags
    ? { acceptedTags: [...slot.acceptedTags] }
    : {}),
});

const cloneContainer = (
  container: Readonly<PortableWorldContainerDefinition>,
): MutableContainerDefinition => ({
  containerId: container.containerId,
  worldPosition: cloneGlobalPosition(container.worldPosition),
  slots: container.slots.map(cloneSlotDefinition),
});

const emptyContent = (
  owner: Readonly<InventoryContentOwner>,
  slots: readonly Readonly<PortableInventorySlotDefinition>[],
): InventoryContentSnapshot => ({
  contentId: inventoryContentIdForOwner(owner),
  owner: { ...owner },
  revision: 0,
  slots: slots.map((slot) => ({
    slotId: slot.slotId,
    slotRevision: 0,
  })),
});

