const parentOwner = (
  parent: Readonly<PortableItemParent>,
): InventoryContentOwner | undefined => {
  switch (parent.kind) {
    case 'PLAYER':
      return { kind: 'PLAYER', playerId: parent.playerId };
    case 'VEHICLE_SLOT':
      return { kind: 'VEHICLE', entityId: parent.entityId };
    case 'CONTAINER_SLOT':
      return { kind: 'CONTAINER', containerId: parent.containerId };
    case 'WORLD':
    case 'CONSUMED':
      return undefined;
  }
};

const parentSlotId = (
  parent: Readonly<PortableItemParent>,
): string | undefined =>
  parent.kind === 'PLAYER' ||
  parent.kind === 'VEHICLE_SLOT' ||
  parent.kind === 'CONTAINER_SLOT'
    ? parent.slotId
    : undefined;

/** Renderer-free ownership authority for portable tools, supplies and equipment. */
export class MultiplayerInventoryAuthority {
  private readonly items = new Map<string, PortableItemSnapshot>();
  private readonly contents = new Map<string, InventoryContentSnapshot>();
  private readonly containers = new Map<string, MutableContainerDefinition>();
  private readonly transactionJournal = new Map<
    TransactionId,
    InventoryTransactionJournalEntry
  >();
  private readonly transactionOrder: TransactionId[] = [];
  private readonly itemDefinitions: ReadonlyMap<
    string,
    Readonly<PortableItemDefinition>
  >;
  private readonly maximumItems: number;
  private readonly maximumContents: number;
  private readonly maximumRememberedTransactions: number;
  private readonly interactionRadiusMetres: number;
  private readonly grantStarterFieldKit: boolean;
  private revisionValue = 0;
  private nextItemSequence = 1;

  public constructor(
    options: Readonly<MultiplayerInventoryAuthorityOptions> = {},
  ) {
    this.maximumItems = options.maximumItems ?? MAX_PORTABLE_ITEMS;
    this.maximumContents = options.maximumContents ?? MAX_INVENTORY_CONTENTS;
    this.maximumRememberedTransactions =
      options.maximumRememberedTransactions ?? 2_048;
    this.interactionRadiusMetres = options.interactionRadiusMetres ?? 4;
    this.grantStarterFieldKit = options.grantStarterFieldKit ?? false;
    this.itemDefinitions = options.itemDefinitions ?? V1_PORTABLE_ITEM_DEFINITIONS;
    if (
      !Number.isSafeInteger(this.maximumItems) ||
      this.maximumItems < 1 ||
      this.maximumItems > MAX_PORTABLE_ITEMS ||
      !Number.isSafeInteger(this.maximumContents) ||
      this.maximumContents < 1 ||
      this.maximumContents > MAX_INVENTORY_CONTENTS ||
      !Number.isSafeInteger(this.maximumRememberedTransactions) ||
      this.maximumRememberedTransactions < 128 ||
      !Number.isFinite(this.interactionRadiusMetres) ||
      this.interactionRadiusMetres < 0.5 ||
      this.interactionRadiusMetres > 32
    ) throw new Error('Invalid multiplayer portable inventory limits.');

    for (const container of options.containers ?? V1_PORTABLE_WORLD_CONTAINERS) {
      this.restoreContainer(container);
    }
    if (options.checkpoint) {
      this.restoreCheckpoint(options.checkpoint);
      return;
    }
    const state = options.initialItems || options.initialContents
      ? {
          items: options.initialItems ?? [],
          contents: options.initialContents ?? [],
        }
      : defaultState();
    this.restoreState(state.items, state.contents);
  }

  public get revision(): number {
    return this.revisionValue;
  }

  public listItems(): readonly PortableItemSnapshot[] {
    return [...this.items.values()]
      .sort((left, right) => left.itemId.localeCompare(right.itemId))
      .map(clonePortableItemSnapshot);
  }

  public listContents(): readonly InventoryContentSnapshot[] {
    return [...this.contents.values()]
      .sort((left, right) => left.contentId.localeCompare(right.contentId))
      .map(cloneInventoryContentSnapshot);
  }

  public getItem(itemId: string): PortableItemSnapshot | undefined {
    const item = this.items.get(itemId);
    return item ? clonePortableItemSnapshot(item) : undefined;
  }

  public getContent(contentId: string): InventoryContentSnapshot | undefined {
    const content = this.contents.get(contentId);
    return content ? cloneInventoryContentSnapshot(content) : undefined;
  }

  public playerContent(playerId: PlayerId): InventoryContentSnapshot | undefined {
    return this.getContent(inventoryContentIdForOwner({ kind: 'PLAYER', playerId }));
  }

  /**
   * Adds the stable player inventory before join baselines. Existing ownership
   * is never reset, which is the reconnect/disconnect recovery contract.
   */
  public ensurePlayer(playerId: PlayerId): boolean {
    const owner: InventoryContentOwner = { kind: 'PLAYER', playerId };
    const contentId = inventoryContentIdForOwner(owner);
    let changed = false;
    if (!this.contents.has(contentId)) {
      if (this.contents.size >= this.maximumContents) {
        throw new Error('Portable inventory content limit reached.');
      }
      this.contents.set(
        contentId,
        emptyContent(owner, PLAYER_PORTABLE_INVENTORY_SLOTS),
      );
      changed = true;
    }
    if (this.grantStarterFieldKit) {
      changed = this.ensureStarterLeafBlower(playerId, contentId) || changed;
    }
    if (changed) this.revisionValue += 1;
    return changed;
  }

  /** Idempotent authored grant used by dialogue/quest rewards. */
  public grantPlayerItem(input: Readonly<{
    playerId: PlayerId;
    definitionId: string;
    preferredSlotId?: string;
    serverTick: ServerTick;
    requestId: TransactionId;
  }>): InventoryAuthorityOperationResult {
    const definition = this.itemDefinitions.get(input.definitionId);
    const content = this.playerContent(input.playerId);
    if (!definition) {
      return {
        accepted: false, status: 'UNKNOWN_PORTABLE_ITEM_DEFINITION',
        stateChanged: false, revision: this.revisionValue, replayed: false,
      };
    }
    if (!content) {
      return {
        accepted: false, status: 'PLAYER_INVENTORY_UNAVAILABLE',
        stateChanged: false, revision: this.revisionValue, replayed: false,
      };
    }
    const alreadyOwned = [...this.items.values()].some((item) =>
      item.definitionId === input.definitionId &&
      item.parent.kind === 'PLAYER' &&
      item.parent.playerId === input.playerId);
    if (alreadyOwned) {
      return {
        accepted: true, status: 'PORTABLE_ITEM_ALREADY_GRANTED',
        stateChanged: false, revision: this.revisionValue, replayed: false,
      };
    }
    if (this.items.size >= this.maximumItems) {
      return {
        accepted: false, status: 'PORTABLE_ITEM_LIMIT',
        stateChanged: false, revision: this.revisionValue, replayed: false,
      };
    }
    const preferredSlots = [
      input.preferredSlotId,
      'quick-1', 'quick-2', 'quick-3', 'quick-4', 'hand',
      'backpack-1', 'backpack-2', 'backpack-3', 'backpack-4', 'radio',
    ].filter((value): value is string => Boolean(value));
    const destination = preferredSlots
      .map((slotId) => content.slots.find((slot) => slot.slotId === slotId))
      .find((slot) => {
        if (!slot || slot.itemId) return false;
        const slotDefinition = PLAYER_PORTABLE_INVENTORY_SLOTS.find(
          (candidate) => candidate.slotId === slot.slotId,
        );
        return slotDefinition ? itemFitsPortableSlot(definition, slotDefinition) : false;
      });
    if (!destination) {
      return {
        accepted: false, status: 'PLAYER_INVENTORY_FULL',
        stateChanged: false, revision: this.revisionValue, replayed: false,
      };
    }
    const itemId = `portable-item:authored:${deterministicStateHash({
      playerId: input.playerId,
      definitionId: input.definitionId,
    })}`;
    if (this.items.has(itemId)) {
      return {
        accepted: false, status: 'PORTABLE_ITEM_ID_COLLISION',
        stateChanged: false, revision: this.revisionValue, replayed: false,
      };
    }
    const item: PortableItemSnapshot = {
      itemId,
      definitionId: input.definitionId,
      revision: 0,
      parent: {
        kind: 'PLAYER',
        playerId: input.playerId,
        slotId: destination.slotId,
      },
      durability: 1,
    };
    const nextContent: InventoryContentSnapshot = {
      ...content,
      revision: content.revision + 1,
      slots: content.slots.map((slot) => slot.slotId === destination.slotId
        ? { ...slot, slotRevision: slot.slotRevision + 1, itemId }
        : { ...slot }),
    };
    const graphFailure = validateInventoryOwnershipGraph(
      [...this.items.values(), item],
      [...this.contents.values()].map((candidate) =>
        candidate.contentId === nextContent.contentId ? nextContent : candidate),
    );
    if (graphFailure) {
      return {
        accepted: false, status: 'INVALID_PORTABLE_GRANT_GRAPH',
        stateChanged: false, revision: this.revisionValue, replayed: false,
      };
    }
    const baseRevision = this.revisionValue;
    this.items.set(itemId, item);
    this.contents.set(nextContent.contentId, nextContent);
    this.revisionValue += 1;
    return {
      accepted: true,
      status: 'PORTABLE_ITEM_GRANTED',
      stateChanged: true,
      revision: this.revisionValue,
      itemRevision: item.revision,
      replayed: false,
      delta: {
        version: 1,
        kind: 'INVENTORY_STATE_DELTA',
        baseRevision,
        revision: this.revisionValue,
        serverTick: input.serverTick,
        requestId: input.requestId,
        actorPlayerId: input.playerId,
        operation: 'GIVE_ITEM',
        changedItems: [clonePortableItemSnapshot(item)],
        changedContents: [cloneInventoryContentSnapshot(nextContent)],
      },
    };
  }

  private ensureStarterLeafBlower(
    playerId: PlayerId,
    contentId: string,
  ): boolean {
    const alreadyOwned = [...this.items.values()].some((item) =>
      item.definitionId === 'portable.leaf-blower' &&
      item.parent.kind === 'PLAYER' &&
      item.parent.playerId === playerId);
    if (alreadyOwned) return false;
    if (this.items.size >= this.maximumItems) return false;
    const content = this.contents.get(contentId);
    if (!content) return false;
    const preferredSlots = [
      'quick-1',
      'quick-2',
      'quick-3',
      'quick-4',
      'hand',
      'backpack-1',
      'backpack-2',
      'backpack-3',
      'backpack-4',
    ];
    const destination = preferredSlots
      .map((slotId) => content.slots.find((slot) => slot.slotId === slotId))
      .find((slot) => slot !== undefined && !slot.itemId);
    if (!destination) return false;
    const itemId = `portable-item:starter:${deterministicStateHash({
      playerId,
      definitionId: 'portable.leaf-blower',
    })}`;
    const item: PortableItemSnapshot = {
      itemId,
      definitionId: 'portable.leaf-blower',
      revision: 0,
      parent: {
        kind: 'PLAYER',
        playerId,
        slotId: destination.slotId,
      },
      durability: 1,
    };
    const slots = content.slots.map((slot) =>
      slot.slotId === destination.slotId
        ? {
            ...slot,
            slotRevision: slot.slotRevision + 1,
            itemId,
          }
        : slot);
    const nextContent: InventoryContentSnapshot = {
      ...content,
      revision: content.revision + 1,
      slots,
    };
    const graphFailure = validateInventoryOwnershipGraph(
      [...this.items.values(), item],
      [
        ...[...this.contents.values()].filter((value) =>
          value.contentId !== contentId),
        nextContent,
      ],
    );
    if (graphFailure) {
      throw new Error(`Starter field kit would invalidate inventory: ${graphFailure}`);
    }
    this.items.set(itemId, item);
    this.contents.set(contentId, nextContent);
    return true;
  }

  public equippedRadioUpgradeIds(playerId: PlayerId): readonly string[] {
    const content = this.playerContent(playerId);
    if (!content) return [];
    const result = new Set<string>();
    for (const slot of content.slots) {
      if (!slot.itemId) continue;
      const item = this.items.get(slot.itemId);
      const definition = item && this.itemDefinitions.get(item.definitionId);
      if (definition?.radioUpgradeId) result.add(definition.radioUpgradeId);
    }
    return [...result].sort();
  }

  public isPortableOperation(operation: string): boolean {
    return PORTABLE_OPERATIONS.has(
      operation as InventoryStateDeltaPayload['operation'],
    );
  }

  /**
   * Synchronously reserves/refunds inventory-backed building resources. The
   * caller invokes this only after structural validation and commits the
   * blueprint in the same authority turn, making the cross-domain transition
   * atomic from every network client's point of view.
   */
  public applyConstructionResourceMutation(
    mutation: Readonly<ConstructionResourceMutation>,
  ): InventoryConstructionResourceResult {
    if (mutation.site.resources.mode !== 'AUTHORITY_INVENTORY') {
      return { accepted: true, status: 'DEV_UNLIMITED' };
    }
    const owner: InventoryContentOwner = {
      kind: 'CONTAINER',
      containerId: mutation.site.resources.containerId,
    };
    const contentId = inventoryContentIdForOwner(owner);
    const currentContent = this.contents.get(contentId);
    if (!currentContent) {
      return { accepted: false, status: 'RESOURCE_CONTAINER_UNAVAILABLE' };
    }
    if (currentContent.revision !== mutation.site.resources.contentRevision) {
      return {
        accepted: false,
        status: 'STALE_RESOURCE_CONTENT_REVISION',
        contentRevision: currentContent.revision,
      };
    }
    const pieceDelta =
      mutation.after.placements.length - mutation.before.placements.length;
    if (pieceDelta === 0) {
      return {
        accepted: true,
        status: 'RESOURCE_STATE_UNCHANGED',
        contentRevision: currentContent.revision,
      };
    }
    if (Math.abs(pieceDelta) > 64) {
      return { accepted: false, status: 'RESOURCE_MUTATION_LIMIT' };
    }
    const content = cloneInventoryContentSnapshot(currentContent);
    const changedItems: PortableItemSnapshot[] = [];
    let nextSequence = this.nextItemSequence;
    if (pieceDelta > 0) {
      const available = content.slots.flatMap((slot) => {
        if (!slot.itemId) return [];
        const item = this.items.get(slot.itemId);
        const definition = item && this.itemDefinitions.get(item.definitionId);
        return item && definition?.tags.includes('CONSTRUCTION_RESOURCE')
          ? [{ slot, item }]
          : [];
      });
      if (available.length < pieceDelta) {
        return { accepted: false, status: 'INSUFFICIENT_CONSTRUCTION_RESOURCES' };
      }
      const consumed = available.slice(0, pieceDelta);
      const consumedIds = new Set(consumed.map(({ item }) => item.itemId));
      Object.assign(content, { slots: content.slots.map((slot) =>
        slot.itemId && consumedIds.has(slot.itemId)
          ? { slotId: slot.slotId, slotRevision: slot.slotRevision + 1 }
          : { ...slot }) });
      for (const { item } of consumed) {
        changedItems.push({
          ...clonePortableItemSnapshot(item),
          revision: item.revision + 1,
          parent: { kind: 'CONSUMED', consumedAtTick: mutation.serverTick },
        });
      }
    } else {
      const refundCount = -pieceDelta;
      const freeSlots = content.slots.filter((slot) => !slot.itemId);
      if (freeSlots.length < refundCount) {
        return { accepted: false, status: 'RESOURCE_CONTAINER_FULL' };
      }
      if (this.items.size + refundCount > this.maximumItems) {
        return { accepted: false, status: 'PORTABLE_ITEM_LIMIT' };
      }
      const assignment = new Map<string, string>();
      for (let index = 0; index < refundCount; index += 1) {
        let itemId = `portable-item:authority:${nextSequence++}`;
        while (this.items.has(itemId) || changedItems.some((item) => item.itemId === itemId)) {
          itemId = `portable-item:authority:${nextSequence++}`;
        }
        const slot = freeSlots[index]!;
        assignment.set(slot.slotId, itemId);
        changedItems.push({
          itemId,
          definitionId: 'portable.construction-bundle',
          revision: 0,
          parent: {
            kind: 'CONTAINER_SLOT',
            containerId: mutation.site.resources.containerId,
            slotId: slot.slotId,
          },
          durability: 1,
        });
      }
      Object.assign(content, { slots: content.slots.map((slot) => {
        const itemId = assignment.get(slot.slotId);
        return itemId
          ? {
              slotId: slot.slotId,
              slotRevision: slot.slotRevision + 1,
              itemId,
            }
          : { ...slot };
      }) });
    }
    Object.assign(content, { revision: content.revision + 1 });
    const changedById = new Map(
      changedItems.map((item) => [item.itemId, item] as const),
    );
    const prospectiveItems = this.listItems().map((item) =>
      changedById.get(item.itemId) ?? item);
    for (const item of changedItems) {
      if (!this.items.has(item.itemId)) prospectiveItems.push(item);
    }
    const prospectiveContents = this.listContents().map((candidate) =>
      candidate.contentId === content.contentId ? content : candidate);
    const graphFailure = validateInventoryOwnershipGraph(
      prospectiveItems,
      prospectiveContents,
    );
    if (graphFailure) {
      return {
        accepted: false,
        status: `RESOURCE_GRAPH_REJECTED:${graphFailure}`,
      };
    }
    for (const item of changedItems) {
      this.items.set(item.itemId, clonePortableItemSnapshot(item));
    }
    this.contents.set(content.contentId, cloneInventoryContentSnapshot(content));
    this.nextItemSequence = nextSequence;
    const baseRevision = this.revisionValue;
    this.revisionValue += 1;
    const delta: InventoryStateDeltaPayload = {
      version: 1,
      kind: 'INVENTORY_STATE_DELTA',
      baseRevision,
      revision: this.revisionValue,
      serverTick: mutation.serverTick,
      requestId: mutation.requestId,
      actorPlayerId: mutation.actorPlayerId,
      operation: 'CONSTRUCTION_RESERVATION',
      changedItems: changedItems.map(clonePortableItemSnapshot),
      changedContents: [cloneInventoryContentSnapshot(content)],
    };
    return {
      accepted: true,
      status: pieceDelta > 0
        ? 'CONSTRUCTION_RESOURCES_RESERVED'
        : 'CONSTRUCTION_RESOURCES_REFUNDED',
      contentRevision: content.revision,
      delta,
    };
  }

  public processOperation(
    operation: Readonly<ReliableAuthorityOperation>,
    context: Readonly<InventoryAuthorityOperationContext>,
  ): InventoryAuthorityOperationResult {
    if (!this.isPortableOperation(operation.operation)) {
      return this.reject('UNSUPPORTED_PORTABLE_INVENTORY_OPERATION');
    }
    const fingerprint = deterministicStateHash({
      playerId: operation.playerId,
      channel: operation.channel,
      operation: operation.operation,
      observedRevision: operation.observedRevision,
      payload: operation.payload,
    });
    const remembered = this.transactionJournal.get(operation.requestId);
    if (remembered) {
      if (remembered.fingerprint !== fingerprint) {
        return this.reject('OPERATION_ID_CONFLICT', true);
      }
      return { ...jsonClone(remembered.result), replayed: true };
    }
    if (operation.channel !== 'INVENTORY') {
      return this.remember(operation.requestId, fingerprint, this.reject(
        'INVALID_PORTABLE_INVENTORY_CHANNEL',
      ));
    }
    if (!isGlobalPositionInPartition(
      ICEAWAY_TARGET_WORLD_PARTITION,
      context.actorPosition,
    )) {
      return this.remember(operation.requestId, fingerprint, this.reject(
        'INVALID_ACTOR_POSITION',
      ));
    }
    const itemId = operation.payload.itemId;
    if (!boundedId(itemId)) {
      return this.remember(operation.requestId, fingerprint, this.reject(
        'INVALID_PORTABLE_ITEM_ID',
      ));
    }
    const item = this.items.get(itemId);
    if (!item) {
      return this.remember(operation.requestId, fingerprint, this.reject(
        'UNKNOWN_PORTABLE_ITEM',
      ));
    }
    if (
      operation.observedRevision === undefined ||
      Number(operation.observedRevision) !== item.revision
    ) {
      return this.remember(operation.requestId, fingerprint, this.reject(
        'STALE_PORTABLE_ITEM_REVISION',
        false,
        item.revision,
      ));
    }
    if (!this.contents.has(inventoryContentIdForOwner({
      kind: 'PLAYER',
      playerId: operation.playerId,
    }))) {
      return this.remember(operation.requestId, fingerprint, this.reject(
        'PLAYER_INVENTORY_UNAVAILABLE',
      ));
    }

    const plan = this.prepareTransfer(operation, item, context);
    if (typeof plan === 'string') {
      return this.remember(
        operation.requestId,
        fingerprint,
        this.reject(plan, false, item.revision),
      );
    }
    const committed = this.commitTransfer(operation, plan, context.serverTick);
    if (typeof committed === 'string') {
      return this.remember(
        operation.requestId,
        fingerprint,
        this.reject(committed, false, item.revision),
      );
    }
    return this.remember(operation.requestId, fingerprint, committed);
  }

  public resultFor(
    operation: Readonly<ReliableAuthorityOperation>,
  ): InventoryAuthorityOperationResult | undefined {
    const entry = this.transactionJournal.get(operation.requestId);
    if (!entry) return undefined;
    const fingerprint = deterministicStateHash({
      playerId: operation.playerId,
      channel: operation.channel,
      operation: operation.operation,
      observedRevision: operation.observedRevision,
      payload: operation.payload,
    });
    return entry.fingerprint === fingerprint
      ? { ...jsonClone(entry.result), replayed: true }
      : this.reject('OPERATION_ID_CONFLICT', true);
  }

  public exportCheckpoint(): MultiplayerInventoryAuthorityCheckpoint {
    return {
      version: 1,
      revision: this.revisionValue,
      nextItemSequence: this.nextItemSequence,
      containers: [...this.containers.values()]
        .sort((left, right) => left.containerId.localeCompare(right.containerId))
        .map((container) => ({
          containerId: container.containerId,
          worldPosition: cloneGlobalPosition(container.worldPosition),
          slots: container.slots.map(cloneSlotDefinition),
        })),
      items: this.listItems(),
      contents: this.listContents(),
      transactionJournal: this.transactionOrder.map((requestId) =>
        jsonClone(this.transactionJournal.get(requestId)!)),
    };
  }

  private prepareTransfer(
    operation: Readonly<ReliableAuthorityOperation>,
    item: Readonly<PortableItemSnapshot>,
    context: Readonly<InventoryAuthorityOperationContext>,
  ): TransferPlan | string {
    switch (operation.operation) {
      case 'PICKUP_ITEM':
        return this.preparePickup(operation, item, context);
      case 'PLACE_ITEM':
        return this.preparePlace(operation, item, context);
      case 'STORE_ITEM':
        return this.prepareStore(operation, item, context);
      case 'TAKE_ITEM':
        return this.prepareTake(operation, item, context);
      case 'GIVE_ITEM':
        return this.prepareGive(operation, item, context);
      case 'MOVE_ITEM':
        return this.prepareMove(operation, item);
      case 'CONSUME_ITEM':
        return this.prepareConsume(operation, item, context.serverTick);
      default:
        return 'UNSUPPORTED_PORTABLE_INVENTORY_OPERATION';
    }
  }

  private preparePickup(
    operation: Readonly<ReliableAuthorityOperation>,
    item: Readonly<PortableItemSnapshot>,
    context: Readonly<InventoryAuthorityOperationContext>,
  ): TransferPlan | string {
    if (item.parent.kind !== 'WORLD') return 'ITEM_NOT_IN_WORLD';
    if (!this.inRange(context.actorPosition, item.parent.worldPosition)) {
      return 'PORTABLE_ITEM_OUT_OF_RANGE';
    }
    const destination = this.playerDestination(
      operation.playerId,
      operation.payload.destinationSlotId,
    );
    if (typeof destination === 'string') return destination;
    const revisionFailure = this.validateDestinationRevisions(
      destination.content,
      destination.slot,
      operation.payload,
    );
    if (revisionFailure) return revisionFailure;
    return {
      operation: 'PICKUP_ITEM',
      item: clonePortableItemSnapshot(item),
      destination: {
        kind: 'PLAYER',
        playerId: operation.playerId,
        slotId: destination.slot.slotId,
      },
      destinationContent: destination.content,
    };
  }

  private preparePlace(
    operation: Readonly<ReliableAuthorityOperation>,
    item: Readonly<PortableItemSnapshot>,
    context: Readonly<InventoryAuthorityOperationContext>,
  ): TransferPlan | string {
    const source = this.actorSource(operation.playerId, item);
    if (typeof source === 'string') return source;
    const revisionFailure = this.validateSourceRevisions(
      source.content,
      source.slot,
      operation.payload,
    );
    if (revisionFailure) return revisionFailure;
    const position = operation.payload.worldPosition as unknown;
    if (
      !position ||
      typeof position !== 'object' ||
      !isGlobalPositionInPartition(
        ICEAWAY_TARGET_WORLD_PARTITION,
        position as GlobalPosition,
      )
    ) return 'INVALID_WORLD_PLACEMENT';
    if (!this.inRange(context.actorPosition, position as GlobalPosition)) {
      return 'WORLD_PLACEMENT_OUT_OF_RANGE';
    }
    return {
      operation: 'PLACE_ITEM',
      item: clonePortableItemSnapshot(item),
      destination: {
        kind: 'WORLD',
        worldPosition: cloneGlobalPosition(position as GlobalPosition),
      },
      sourceContent: source.content,
    };
  }

  private prepareStore(
    operation: Readonly<ReliableAuthorityOperation>,
    item: Readonly<PortableItemSnapshot>,
    context: Readonly<InventoryAuthorityOperationContext>,
  ): TransferPlan | string {
    const source = this.actorSource(operation.playerId, item);
    if (typeof source === 'string') return source;
    const sourceFailure = this.validateSourceRevisions(
      source.content,
      source.slot,
      operation.payload,
    );
    if (sourceFailure) return sourceFailure;
    const targetKind = operation.payload.targetKind;
    const targetId = operation.payload.targetId;
    const slotId = operation.payload.destinationSlotId;
    if (
      (targetKind !== 'VEHICLE' && targetKind !== 'CONTAINER') ||
      !boundedId(targetId) ||
      !boundedId(slotId, 64)
    ) return 'INVALID_STORAGE_TARGET';
    const owner: InventoryContentOwner = targetKind === 'VEHICLE'
      ? { kind: 'VEHICLE', entityId: targetId as NetworkEntityId }
      : { kind: 'CONTAINER', containerId: targetId };
    const targetPosition = targetKind === 'VEHICLE'
      ? context.resolveEntityPosition(targetId as NetworkEntityId)
      : this.containers.get(targetId)?.worldPosition;
    if (!targetPosition) return 'UNKNOWN_STORAGE_TARGET';
    if (!this.inRange(context.actorPosition, targetPosition)) {
      return 'STORAGE_TARGET_OUT_OF_RANGE';
    }
    const destination = this.destinationForOwner(owner, slotId, true);
    if (typeof destination === 'string') return destination;
    const destinationFailure = this.validateDestinationRevisions(
      destination.content,
      destination.slot,
      operation.payload,
    );
    if (destinationFailure) return destinationFailure;
    return {
      operation: 'STORE_ITEM',
      item: clonePortableItemSnapshot(item),
      destination: targetKind === 'VEHICLE'
        ? {
            kind: 'VEHICLE_SLOT',
            entityId: targetId as NetworkEntityId,
            slotId,
          }
        : { kind: 'CONTAINER_SLOT', containerId: targetId, slotId },
      sourceContent: source.content,
      destinationContent: destination.content,
    };
  }

  private prepareTake(
    operation: Readonly<ReliableAuthorityOperation>,
    item: Readonly<PortableItemSnapshot>,
    context: Readonly<InventoryAuthorityOperationContext>,
  ): TransferPlan | string {
    if (
      item.parent.kind !== 'VEHICLE_SLOT' &&
      item.parent.kind !== 'CONTAINER_SLOT'
    ) return 'ITEM_NOT_IN_STORAGE';
    const source = this.sourceForParent(item.parent);
    if (typeof source === 'string') return source;
    const sourceFailure = this.validateSourceRevisions(
      source.content,
      source.slot,
      operation.payload,
    );
    if (sourceFailure) return sourceFailure;
    const targetPosition = item.parent.kind === 'VEHICLE_SLOT'
      ? context.resolveEntityPosition(item.parent.entityId)
      : this.containers.get(item.parent.containerId)?.worldPosition;
    if (!targetPosition) return 'UNKNOWN_STORAGE_TARGET';
    if (!this.inRange(context.actorPosition, targetPosition)) {
      return 'STORAGE_TARGET_OUT_OF_RANGE';
    }
    const destination = this.playerDestination(
      operation.playerId,
      operation.payload.destinationSlotId,
    );
    if (typeof destination === 'string') return destination;
    const destinationFailure = this.validateDestinationRevisions(
      destination.content,
      destination.slot,
      operation.payload,
    );
    if (destinationFailure) return destinationFailure;
    return {
      operation: 'TAKE_ITEM',
      item: clonePortableItemSnapshot(item),
      destination: {
        kind: 'PLAYER',
        playerId: operation.playerId,
        slotId: destination.slot.slotId,
      },
      sourceContent: source.content,
      destinationContent: destination.content,
    };
  }

  private prepareGive(
    operation: Readonly<ReliableAuthorityOperation>,
    item: Readonly<PortableItemSnapshot>,
    context: Readonly<InventoryAuthorityOperationContext>,
  ): TransferPlan | string {
    const source = this.actorSource(operation.playerId, item);
    if (typeof source === 'string') return source;
    const sourceFailure = this.validateSourceRevisions(
      source.content,
      source.slot,
      operation.payload,
    );
    if (sourceFailure) return sourceFailure;
    const targetPlayerId = operation.payload.targetPlayerId;
    if (
      !boundedId(targetPlayerId) ||
      targetPlayerId === operation.playerId
    ) return 'INVALID_GIVE_TARGET';
    const targetPosition = context.resolvePlayerPosition(targetPlayerId as PlayerId);
    if (!targetPosition) return 'GIVE_TARGET_UNAVAILABLE';
    if (!this.inRange(context.actorPosition, targetPosition)) {
      return 'GIVE_TARGET_OUT_OF_RANGE';
    }
    const destination = this.playerDestination(
      targetPlayerId as PlayerId,
      operation.payload.destinationSlotId,
    );
    if (typeof destination === 'string') return destination;
    const destinationFailure = this.validateDestinationRevisions(
      destination.content,
      destination.slot,
      operation.payload,
    );
    if (destinationFailure) return destinationFailure;
    return {
      operation: 'GIVE_ITEM',
      item: clonePortableItemSnapshot(item),
      destination: {
        kind: 'PLAYER',
        playerId: targetPlayerId as PlayerId,
        slotId: destination.slot.slotId,
      },
      sourceContent: source.content,
      destinationContent: destination.content,
    };
  }

  private prepareMove(
    operation: Readonly<ReliableAuthorityOperation>,
    item: Readonly<PortableItemSnapshot>,
  ): TransferPlan | string {
    const source = this.actorSource(operation.playerId, item);
    if (typeof source === 'string') return source;
    const sourceFailure = this.validateSourceRevisions(
      source.content,
      source.slot,
      operation.payload,
    );
    if (sourceFailure) return sourceFailure;
    const destination = this.playerDestination(
      operation.playerId,
      operation.payload.destinationSlotId,
    );
    if (typeof destination === 'string') return destination;
    if (destination.slot.slotId === source.slot.slotId) {
      return 'NO_INVENTORY_CHANGE';
    }
    const destinationFailure = this.validateDestinationRevisions(
      destination.content,
      destination.slot,
      operation.payload,
    );
    if (destinationFailure) return destinationFailure;
    return {
      operation: 'MOVE_ITEM',
      item: clonePortableItemSnapshot(item),
      destination: {
        kind: 'PLAYER',
        playerId: operation.playerId,
        slotId: destination.slot.slotId,
      },
      sourceContent: source.content,
      destinationContent: destination.content,
    };
  }

  private prepareConsume(
    operation: Readonly<ReliableAuthorityOperation>,
    item: Readonly<PortableItemSnapshot>,
    tick: ServerTick,
  ): TransferPlan | string {
    const source = this.actorSource(operation.playerId, item);
    if (typeof source === 'string') return source;
    const sourceFailure = this.validateSourceRevisions(
      source.content,
      source.slot,
      operation.payload,
    );
    if (sourceFailure) return sourceFailure;
    const definition = this.itemDefinitions.get(item.definitionId);
    if (!definition?.consumable) return 'ITEM_NOT_CONSUMABLE';
    return {
      operation: 'CONSUME_ITEM',
      item: clonePortableItemSnapshot(item),
      destination: {
        kind: 'CONSUMED',
        consumedAtTick: tick,
      },
      sourceContent: source.content,
    };
  }

  private commitTransfer(
    operation: Readonly<ReliableAuthorityOperation>,
    plan: Readonly<TransferPlan>,
    tick: ServerTick,
  ): InventoryAuthorityOperationResult | string {
    const contentChanges = new Map<string, InventoryContentSnapshot>();
    const mutableContent = (
      content: Readonly<InventoryContentSnapshot>,
    ): InventoryContentSnapshot => {
      const existing = contentChanges.get(content.contentId);
      if (existing) return existing;
      const clone = cloneInventoryContentSnapshot(content);
      contentChanges.set(content.contentId, clone);
      return clone;
    };
    if (plan.sourceContent) {
      const source = mutableContent(plan.sourceContent);
      const sourceSlotId = parentSlotId(plan.item.parent)!;
      const slotIndex = source.slots.findIndex((slot) => slot.slotId === sourceSlotId);
      if (slotIndex < 0 || source.slots[slotIndex]!.itemId !== plan.item.itemId) {
        return 'SOURCE_OWNERSHIP_CHANGED';
      }
      const slot = source.slots[slotIndex]!;
      const slots = [...source.slots];
      slots[slotIndex] = {
        slotId: slot.slotId,
        slotRevision: slot.slotRevision + 1,
      };
      Object.assign(source, { slots });
    }
    if (plan.destinationContent) {
      const destination = mutableContent(plan.destinationContent);
      const destinationSlotId = parentSlotId(plan.destination)!;
      const slotIndex = destination.slots.findIndex(
        (slot) => slot.slotId === destinationSlotId,
      );
      if (slotIndex < 0 || destination.slots[slotIndex]!.itemId) {
        return 'DESTINATION_SLOT_CHANGED';
      }
      const slot = destination.slots[slotIndex]!;
      const slots = [...destination.slots];
      slots[slotIndex] = {
        slotId: slot.slotId,
        slotRevision: slot.slotRevision + 1,
        itemId: plan.item.itemId,
      };
      Object.assign(destination, { slots });
    }
    for (const [contentId, content] of contentChanges) {
      const canonical = this.contents.get(contentId);
      Object.assign(content, { revision: (canonical?.revision ?? 0) + 1 });
    }
    const changedItem: PortableItemSnapshot = {
      ...clonePortableItemSnapshot(plan.item),
      revision: plan.item.revision + 1,
      parent: clonePortableItemParent(plan.destination),
    };
    const prospectiveItems = this.listItems().map((item) =>
      item.itemId === changedItem.itemId ? changedItem : item);
    const changedContentIds = new Set(contentChanges.keys());
    const prospectiveContents = this.listContents()
      .filter((content) => !changedContentIds.has(content.contentId));
    prospectiveContents.push(...contentChanges.values());
    const graphFailure = validateInventoryOwnershipGraph(
      prospectiveItems,
      prospectiveContents,
    );
    if (graphFailure) return `INVENTORY_GRAPH_REJECTED:${graphFailure}`;

    this.items.set(changedItem.itemId, changedItem);
    for (const content of contentChanges.values()) {
      this.contents.set(content.contentId, cloneInventoryContentSnapshot(content));
    }
    const baseRevision = this.revisionValue;
    this.revisionValue += 1;
    const delta: InventoryStateDeltaPayload = {
      version: 1,
      kind: 'INVENTORY_STATE_DELTA',
      baseRevision,
      revision: this.revisionValue,
      serverTick: tick,
      requestId: operation.requestId,
      actorPlayerId: operation.playerId,
      operation: plan.operation,
      changedItems: [clonePortableItemSnapshot(changedItem)],
      changedContents: [...contentChanges.values()]
        .sort((left, right) => left.contentId.localeCompare(right.contentId))
        .map(cloneInventoryContentSnapshot),
    };
    return {
      accepted: true,
      status: 'PORTABLE_INVENTORY_COMMITTED',
      stateChanged: true,
      revision: this.revisionValue,
      itemRevision: changedItem.revision,
      delta,
      replayed: false,
    };
  }

  private actorSource(
    playerId: PlayerId,
    item: Readonly<PortableItemSnapshot>,
  ):
    | { content: InventoryContentSnapshot; slot: InventorySlotSnapshot }
    | string {
    if (item.parent.kind !== 'PLAYER' || item.parent.playerId !== playerId) {
      return 'ITEM_NOT_OWNED_BY_ACTOR';
    }
    return this.sourceForParent(item.parent);
  }

  private sourceForParent(
    parent: Readonly<PortableItemParent>,
  ):
    | { content: InventoryContentSnapshot; slot: InventorySlotSnapshot }
    | string {
    const owner = parentOwner(parent);
    const slotId = parentSlotId(parent);
    if (!owner || !slotId) return 'ITEM_HAS_NO_SOURCE_SLOT';
    const content = this.contents.get(inventoryContentIdForOwner(owner));
    const slot = content?.slots.find((candidate) => candidate.slotId === slotId);
    if (!content || !slot) return 'SOURCE_SLOT_UNAVAILABLE';
    return {
      content: cloneInventoryContentSnapshot(content),
      slot: { ...slot },
    };
  }

  private playerDestination(
    playerId: PlayerId,
    slotId: unknown,
  ):
    | { content: InventoryContentSnapshot; slot: InventorySlotSnapshot }
    | string {
    if (!boundedId(slotId, 64)) return 'INVALID_DESTINATION_SLOT';
    return this.destinationForOwner(
      { kind: 'PLAYER', playerId },
      slotId,
      false,
    );
  }

  private destinationForOwner(
    owner: Readonly<InventoryContentOwner>,
    slotId: string,
    allowCreate: boolean,
  ):
    | { content: InventoryContentSnapshot; slot: InventorySlotSnapshot }
    | string {
    const definitions = this.slotDefinitions(owner);
    if (!definitions) return 'UNKNOWN_INVENTORY_OWNER';
    const slotDefinition = definitions.find((slot) => slot.slotId === slotId);
    if (!slotDefinition) return 'INVALID_DESTINATION_SLOT';
    const contentId = inventoryContentIdForOwner(owner);
    const existing = this.contents.get(contentId);
    if (!existing && !allowCreate) return 'DESTINATION_CONTENT_UNAVAILABLE';
    if (!existing && this.contents.size >= this.maximumContents) {
      return 'INVENTORY_CONTENT_LIMIT';
    }
    const content = existing
      ? cloneInventoryContentSnapshot(existing)
      : emptyContent(owner, definitions);
    const slot = content.slots.find((candidate) => candidate.slotId === slotId)!;
    if (slot.itemId) return 'DESTINATION_SLOT_OCCUPIED';
    return { content, slot: { ...slot } };
  }

  private validateSourceRevisions(
    content: Readonly<InventoryContentSnapshot>,
    slot: Readonly<InventorySlotSnapshot>,
    payload: Readonly<Record<string, unknown>>,
  ): string | undefined {
    if (
      !natural(payload.sourceContentRevision) ||
      payload.sourceContentRevision !== content.revision
    ) return 'STALE_SOURCE_CONTENT_REVISION';
    if (
      !natural(payload.sourceSlotRevision) ||
      payload.sourceSlotRevision !== slot.slotRevision
    ) return 'STALE_SOURCE_SLOT_REVISION';
    return undefined;
  }

  private validateDestinationRevisions(
    content: Readonly<InventoryContentSnapshot>,
    slot: Readonly<InventorySlotSnapshot>,
    payload: Readonly<Record<string, unknown>>,
  ): string | undefined {
    if (
      !natural(payload.destinationContentRevision) ||
      payload.destinationContentRevision !== content.revision
    ) return 'STALE_DESTINATION_CONTENT_REVISION';
    if (
      !natural(payload.destinationSlotRevision) ||
      payload.destinationSlotRevision !== slot.slotRevision
    ) return 'STALE_DESTINATION_SLOT_REVISION';
    const item = this.items.get(
      typeof payload.itemId === 'string' ? payload.itemId : '',
    );
    const definition = item && this.itemDefinitions.get(item.definitionId);
    const slotDefinition = this.slotDefinitions(content.owner)?.find(
      (candidate) => candidate.slotId === slot.slotId,
    );
    if (!definition || !slotDefinition) return 'UNKNOWN_ITEM_DEFINITION';
    if (!itemFitsPortableSlot(definition, slotDefinition)) {
      return 'ITEM_INCOMPATIBLE_WITH_SLOT';
    }
    return undefined;
  }

  private slotDefinitions(
    owner: Readonly<InventoryContentOwner>,
  ): readonly Readonly<PortableInventorySlotDefinition>[] | undefined {
    switch (owner.kind) {
      case 'PLAYER':
        return PLAYER_PORTABLE_INVENTORY_SLOTS;
      case 'VEHICLE':
        return VEHICLE_PORTABLE_INVENTORY_SLOTS;
      case 'CONTAINER':
        return this.containers.get(owner.containerId)?.slots;
    }
  }

  private inRange(
    left: Readonly<GlobalPosition>,
    right: Readonly<GlobalPosition>,
  ): boolean {
    return isGlobalPositionInPartition(ICEAWAY_TARGET_WORLD_PARTITION, right) &&
      globalPositionDistanceMetres(
        ICEAWAY_TARGET_WORLD_PARTITION,
        left,
        right,
      ) <= this.interactionRadiusMetres;
  }

  private restoreCheckpoint(
    checkpoint: Readonly<MultiplayerInventoryAuthorityCheckpoint>,
  ): void {
    if (
      checkpoint.version !== 1 ||
      !natural(checkpoint.revision) ||
      !natural(checkpoint.nextItemSequence) ||
      checkpoint.nextItemSequence < 1 ||
      checkpoint.containers.length > this.maximumContents ||
      checkpoint.items.length > this.maximumItems ||
      checkpoint.contents.length > this.maximumContents ||
      checkpoint.transactionJournal.length > this.maximumRememberedTransactions
    ) throw new Error('Invalid multiplayer inventory checkpoint.');
    this.containers.clear();
    for (const container of checkpoint.containers) this.restoreContainer(container);
    this.restoreState(checkpoint.items, checkpoint.contents);
    let maximumAuthorityItemSequence = 0;
    for (const item of checkpoint.items) {
      const prefix = 'portable-item:authority:';
      if (!item.itemId.startsWith(prefix)) continue;
      const sequence = Number(item.itemId.slice(prefix.length));
      if (!Number.isSafeInteger(sequence) || sequence < 1) {
        throw new Error('Inventory checkpoint contains an invalid stable item ID.');
      }
      maximumAuthorityItemSequence = Math.max(
        maximumAuthorityItemSequence,
        sequence,
      );
    }
    if (checkpoint.nextItemSequence <= maximumAuthorityItemSequence) {
      throw new Error('Inventory checkpoint would reuse a stable item ID.');
    }
    const maximumRecordRevision = Math.max(
      0,
      ...checkpoint.items.map((item) => item.revision),
      ...checkpoint.contents.flatMap((content) => [
        content.revision,
        ...content.slots.map((slot) => slot.slotRevision),
      ]),
    );
    if (checkpoint.revision < maximumRecordRevision) {
      throw new Error('Inventory checkpoint revision precedes a record revision.');
    }
    const requestIds = new Set<TransactionId>();
    for (const entry of checkpoint.transactionJournal) {
      const result = entry.result;
      if (
        requestIds.has(entry.requestId) ||
        !boundedId(entry.fingerprint, 256) ||
        typeof result?.accepted !== 'boolean' ||
        typeof result?.status !== 'string' ||
        !natural(result?.revision) ||
        result.revision > checkpoint.revision ||
        result.stateChanged !== result.accepted ||
        (result.accepted && !result.delta) ||
        (!result.accepted && result.delta !== undefined) ||
        (result.delta !== undefined &&
          (!validateInventoryStateDeltaPayload(result.delta) ||
            result.delta.requestId !== entry.requestId ||
            result.delta.revision !== result.revision))
      ) throw new Error('Invalid inventory transaction journal.');
      requestIds.add(entry.requestId);
      const cloned = jsonClone(entry);
      this.transactionJournal.set(entry.requestId, cloned);
      this.transactionOrder.push(entry.requestId);
    }
    this.revisionValue = checkpoint.revision;
    this.nextItemSequence = checkpoint.nextItemSequence;
  }

  private restoreContainer(
    input: Readonly<PortableWorldContainerDefinition>,
  ): void {
    if (
      this.containers.has(input.containerId) ||
      !boundedId(input.containerId) ||
      !isGlobalPositionInPartition(
        ICEAWAY_TARGET_WORLD_PARTITION,
        input.worldPosition,
      ) ||
      input.slots.length < 1 ||
      input.slots.length > 128
    ) throw new Error('Invalid or duplicate portable inventory container.');
    const slotIds = new Set<string>();
    for (const slot of input.slots) {
      if (
        !boundedId(slot.slotId, 64) ||
        slotIds.has(slot.slotId) ||
        slot.acceptedTags?.some((tag) =>
          !['PORTABLE', 'TOOL', 'CONSUMABLE', 'RADIO', 'CONSTRUCTION_RESOURCE']
            .includes(tag))
      ) throw new Error('Invalid portable inventory container slot.');
      slotIds.add(slot.slotId);
    }
    this.containers.set(input.containerId, cloneContainer(input));
  }

  private restoreState(
    rawItems: readonly Readonly<PortableItemSnapshot>[],
    rawContents: readonly Readonly<InventoryContentSnapshot>[],
  ): void {
    if (
      rawItems.length > this.maximumItems ||
      rawContents.length > this.maximumContents
    ) throw new Error('Portable inventory state exceeds configured limits.');
    const items: PortableItemSnapshot[] = [];
    const itemById = new Map<string, PortableItemSnapshot>();
    for (const raw of rawItems) {
      const item = sanitizePortableItemSnapshot(raw);
      if (
        !item ||
        itemById.has(item.itemId) ||
        !this.itemDefinitions.has(item.definitionId)
      ) {
        throw new Error('Portable inventory contains an invalid item.');
      }
      items.push(item);
      itemById.set(item.itemId, item);
    }
    const contents: InventoryContentSnapshot[] = [];
    for (const raw of rawContents) {
      const content = sanitizeInventoryContentSnapshot(raw);
      if (!content || !this.contentMatchesDefinition(content, itemById)) {
        throw new Error('Portable inventory contains invalid slot content.');
      }
      contents.push(content);
    }
    const graphFailure = validateInventoryOwnershipGraph(items, contents);
    if (graphFailure) {
      throw new Error(`Invalid portable inventory ownership graph: ${graphFailure}.`);
    }
    this.items.clear();
    this.contents.clear();
    for (const item of items) this.items.set(item.itemId, item);
    for (const content of contents) this.contents.set(content.contentId, content);
  }

  private contentMatchesDefinition(
    content: Readonly<InventoryContentSnapshot>,
    items: ReadonlyMap<string, Readonly<PortableItemSnapshot>>,
  ): boolean {
    const definitions = this.slotDefinitions(content.owner);
    if (!definitions || definitions.length !== content.slots.length) return false;
    const byId = new Map(definitions.map((slot) => [slot.slotId, slot] as const));
    for (const slot of content.slots) {
      const definition = byId.get(slot.slotId);
      if (!definition) return false;
      if (!slot.itemId) continue;
      const item = items.get(slot.itemId);
      const itemDefinition = item && this.itemDefinitions.get(item.definitionId);
      if (!itemDefinition || !itemFitsPortableSlot(itemDefinition, definition)) {
        return false;
      }
    }
    return true;
  }

  private reject(
    status: string,
    replayed = false,
    itemRevision?: number,
  ): InventoryAuthorityOperationResult {
    return {
      accepted: false,
      status,
      stateChanged: false,
      revision: this.revisionValue,
      ...(itemRevision === undefined ? {} : { itemRevision }),
      replayed,
    };
  }

  private remember(
    requestId: TransactionId,
    fingerprint: string,
    result: InventoryAuthorityOperationResult,
  ): InventoryAuthorityOperationResult {
    const { replayed: _replayed, ...storedResult } = jsonClone(result);
    const entry: InventoryTransactionJournalEntry = {
      requestId,
      fingerprint,
      result: storedResult,
    };
    this.transactionJournal.set(requestId, entry);
    this.transactionOrder.push(requestId);
    while (this.transactionOrder.length > this.maximumRememberedTransactions) {
      const expired = this.transactionOrder.shift();
      if (expired) this.transactionJournal.delete(expired);
    }
    return result;
  }
}
