import {
  ZERO_REVISION,
  ZERO_SERVER_TICK,
  nextRevision,
  revision,
  serverTick,
  type Revision,
  type ServerTick,
} from '../netcode/core/NetworkPrimitives';
import { IceBondGrid, type SavedIceBond } from './IceBondGrid';
import { IceCellOwner } from './IceOwnership';

export const ICE_AUTHORITY_FORMAT_VERSION = 2;
export const ICE_AUTHORITY_CHUNK_SIZE = 16;
export const ICE_AUTHORITY_BASELINE_ID = 'iceway-v1-generated-ice';

export enum IceAuthorityField {
  None = 0,
  Thickness = 1 << 0,
  Openness = 1 << 1,
  Snow = 1 << 2,
  ChannelMemory = 1 << 3,
  Owner = 1 << 4,
  FloeMembership = 1 << 5,
  ChannelAge = 1 << 6,
  All =
    Thickness |
    Openness |
    Snow |
    ChannelMemory |
    Owner |
    FloeMembership |
    ChannelAge,
}

export interface IceAuthorityMutableArrays {
  thickness: Float32Array;
  effectiveThickness: Float32Array;
  openness: Float32Array;
  nextOpenness: Float32Array;
  channelMemory: Float32Array;
  nextChannelMemory: Float32Array;
  channelAge: Float32Array;
  nextChannelAge: Float32Array;
  age: Float32Array;
  breakStress: Float32Array;
  snowCover: Float32Array;
  nextSnowCover: Float32Array;
  cellOwner: Uint8Array;
  packBonded: Uint8Array;
  floeIdByCell: Int32Array;
  floeOffsetX: Float32Array;
  floeOffsetZ: Float32Array;
  floeVelocityX: Float32Array;
  floeVelocityZ: Float32Array;
  floeAngle: Float32Array;
}

export interface IceAuthorityBaselineArrays {
  readonly thickness: Float32Array;
  readonly openness: Float32Array;
  readonly snowCover: Float32Array;
  readonly channelMemory: Float32Array;
  readonly channelAge: Float32Array;
  readonly cellOwner: Uint8Array;
  readonly floeIdByCell: Int32Array;
}

export interface PackedIceCell {
  readonly index: number;
  readonly thickness: number;
  readonly openness: number;
  readonly snow: number;
  readonly channelMemory: number;
  /** Whole authority seconds, saturated to uint16 for prediction and refreeze visuals. */
  readonly channelAge: number;
  readonly owner: IceCellOwner;
  readonly floeId: number;
}

/** A field-masked cell change. Values are quantized before journalling. */
export interface PackedIceCellDelta {
  readonly index: number;
  readonly fieldMask: IceAuthorityField;
  readonly thickness?: number;
  readonly openness?: number;
  readonly snow?: number;
  readonly channelMemory?: number;
  readonly channelAge?: number;
  readonly owner?: IceCellOwner;
  readonly floeId?: number;
  readonly causeId?: string;
}

export interface IceAuthorityChunkAddress {
  readonly chunkX: number;
  readonly chunkZ: number;
}

export interface IceAuthorityChunkBaseline extends IceAuthorityChunkAddress {
  readonly revision: Revision;
  readonly topologyRevision: Revision;
  readonly checksum: string;
  /** Cells different from the deterministic authored baseline. */
  readonly changes: readonly PackedIceCell[];
}

export interface IceAuthorityChunkDelta extends IceAuthorityChunkAddress {
  readonly baseRevision: Revision;
  readonly revision: Revision;
  readonly baseTopologyRevision: Revision;
  readonly topologyRevision: Revision;
  readonly serverTick: ServerTick;
  readonly checksum: string;
  readonly changes: readonly PackedIceCellDelta[];
}

export interface IceAuthorityFloeState {
  readonly id: number;
  readonly cells: readonly number[];
  readonly centerX: number;
  readonly centerZ: number;
  readonly offsetX: number;
  readonly offsetZ: number;
  readonly velocityX: number;
  readonly velocityZ: number;
  readonly yaw: number;
  readonly angularVelocity: number;
  readonly pressure: number;
  readonly separationCooldown: number;
  readonly detachedAgeSeconds: number;
  readonly contactBondSeconds: number;
  readonly thermalAnchorSeconds: number;
  readonly seed: number;
  readonly movementRevision: Revision;
}

export type IceFloeLifecycleKind =
  | 'CREATE'
  | 'SPLIT'
  | 'MERGE'
  | 'REATTACH'
  | 'REMOVE';

export interface IceFloeLifecycleEvent {
  readonly eventId: string;
  readonly kind: IceFloeLifecycleKind;
  readonly topologyRevision: Revision;
  readonly serverTick: ServerTick;
  readonly floeId: number;
  readonly sourceFloeIds: readonly number[];
  readonly floe?: IceAuthorityFloeState;
  readonly causeId?: string;
}

export interface IceFloeMovementSnapshot {
  readonly floeId: number;
  readonly movementRevision: Revision;
  readonly serverTick: ServerTick;
  readonly centerX: number;
  readonly centerZ: number;
  readonly offsetX: number;
  readonly offsetZ: number;
  readonly velocityX: number;
  readonly velocityZ: number;
  readonly yaw: number;
  readonly angularVelocity: number;
  readonly pressure: number;
}

export interface IceAuthorityCheckpointCell extends PackedIceCell {
  /** Full precision authority values; client wire data remains quantized. */
  readonly rawThickness?: number;
  readonly rawOpenness?: number;
  readonly rawSnow?: number;
  readonly rawChannelMemory?: number;
  readonly channelAge: number;
  readonly age: number;
  readonly breakStress: number;
  readonly packBonded: boolean;
  readonly floeOffsetX: number;
  readonly floeOffsetZ: number;
  readonly floeVelocityX: number;
  readonly floeVelocityZ: number;
  readonly floeAngle: number;
}

export interface IceAuthorityCheckpoint {
  readonly version: 1 | 2;
  readonly baselineId: string;
  readonly formatVersion: 1 | typeof ICE_AUTHORITY_FORMAT_VERSION;
  readonly columns: number;
  readonly rows: number;
  readonly cellSize: number;
  readonly simulationTime: number;
  readonly lastCommittedTick: ServerTick;
  readonly nextFloeId: number;
  readonly cells: readonly IceAuthorityCheckpointCell[];
  readonly bonds: readonly SavedIceBond[];
  readonly floes: readonly IceAuthorityFloeState[];
  readonly chunks: readonly {
    chunkX: number;
    chunkZ: number;
    revision: Revision;
    topologyRevision: Revision;
  }[];
}

export interface IceAuthorityStateDiagnostics {
  readonly cells: number;
  readonly chunks: number;
  readonly modifiedCells: number;
  readonly pendingCells: number;
  readonly pendingTopologyChunks: number;
  readonly retainedJournalEntries: number;
  readonly retainedLifecycleEvents: number;
  readonly floes: number;
  readonly lastCommittedTick: ServerTick;
  readonly totalCommittedCells: number;
}

export interface IceAuthorityStateOptions {
  readonly columns: number;
  readonly rows: number;
  readonly cellSize: number;
  readonly baselineId?: string;
  readonly maximumJournalEntries?: number;
  readonly maximumLifecycleEvents?: number;
}

interface MutableChunkState {
  revision: Revision;
  topologyRevision: Revision;
}

interface PendingCell {
  fields: IceAuthorityField;
  causeId?: string;
}

interface MutableIceAuthorityFloeState {
  id: number;
  cells: number[];
  centerX: number;
  centerZ: number;
  offsetX: number;
  offsetZ: number;
  velocityX: number;
  velocityZ: number;
  yaw: number;
  angularVelocity: number;
  pressure: number;
  separationCooldown: number;
  detachedAgeSeconds: number;
  contactBondSeconds: number;
  thermalAnchorSeconds: number;
  seed: number;
  movementRevision: Revision;
}

const finitePositiveInteger = (value: number): boolean =>
  Number.isSafeInteger(value) && value > 0;

const clamp = (value: number, minimum: number, maximum: number): number =>
  Math.max(minimum, Math.min(maximum, value));

const unitByte = (value: number): number =>
  Math.round(clamp(Number.isFinite(value) ? value : 0, 0, 1) * 255);

const byteUnit = (value: number): number => clamp(value, 0, 255) / 255;

const secondsU16 = (value: number): number =>
  Math.round(clamp(Number.isFinite(value) ? value : 0, 0, 65_535));

const safeFloeId = (value: number): number =>
  Number.isSafeInteger(value) && value >= 1 ? value : -1;

const safeFinite = (value: number, fallback = 0): number =>
  Number.isFinite(value) ? value : fallback;

const boundedCauseId = (value: string | undefined): string | undefined =>
  value && value.length <= 160 ? value : undefined;

const cloneFloe = (
  floe: Readonly<MutableIceAuthorityFloeState>,
): IceAuthorityFloeState => ({
  ...floe,
  cells: [...floe.cells],
});

const sortedUniqueCells = (
  cells: readonly number[],
  count: number,
): number[] => [...new Set(cells)]
  .filter((index) => Number.isSafeInteger(index) && index >= 0 && index < count)
  .sort((left, right) => left - right);

/**
 * Renderer-free owner of canonical ice cell and floe state.
 *
 * Simulation code mutates the typed arrays and marks affected fields. A
 * commit compares wire-quantized values against the previous commit, so
 * cosmetic dirty notifications and sub-quantization changes cannot create
 * false network traffic. The raw arrays retain sub-quantization accumulation.
 */
export class IceAuthorityState {
  public readonly columns: number;
  public readonly rows: number;
  public readonly count: number;
  public readonly cellSize: number;
  public readonly width: number;
  public readonly height: number;
  public readonly baselineId: string;
  public readonly bonds: IceBondGrid;

  private readonly arraysValue: IceAuthorityMutableArrays;
  private readonly baseline: IceAuthorityBaselineArrays;
  private readonly committedThickness: Uint8Array;
  private readonly committedOpenness: Uint8Array;
  private readonly committedSnow: Uint8Array;
  private readonly committedChannelMemory: Uint8Array;
  private readonly committedChannelAge: Uint16Array;
  private readonly committedOwner: Uint8Array;
  private readonly committedFloeId: Int32Array;
  private readonly chunks: MutableChunkState[];
  private readonly pendingCells = new Map<number, PendingCell>();
  private readonly pendingTopologyChunks = new Map<number, string | undefined>();
  private readonly journal: IceAuthorityChunkDelta[] = [];
  private readonly lifecycleJournal: IceFloeLifecycleEvent[] = [];
  private readonly floes = new Map<number, MutableIceAuthorityFloeState>();
  private lastCommittedTick = ZERO_SERVER_TICK;
  private simulationTime = 0;
  private nextFloeId = 1;
  private totalCommittedCells = 0;
  private lifecycleSequence = 0;

  private readonly maximumJournalEntries: number;
  private readonly maximumLifecycleEvents: number;

  public constructor(options: Readonly<IceAuthorityStateOptions>) {
    if (
      !finitePositiveInteger(options.columns) ||
      !finitePositiveInteger(options.rows) ||
      !Number.isFinite(options.cellSize) ||
      options.cellSize <= 0
    ) throw new Error('Ice authority dimensions must be positive and finite.');
    const journalSize = options.maximumJournalEntries ?? 4_096;
    const lifecycleSize = options.maximumLifecycleEvents ?? 2_048;
    if (!finitePositiveInteger(journalSize) || !finitePositiveInteger(lifecycleSize)) {
      throw new Error('Ice authority journal limits must be positive integers.');
    }
    this.columns = options.columns;
    this.rows = options.rows;
    this.count = this.columns * this.rows;
    this.cellSize = options.cellSize;
    this.width = this.columns * this.cellSize;
    this.height = this.rows * this.cellSize;
    this.baselineId = options.baselineId ?? ICE_AUTHORITY_BASELINE_ID;
    if (this.baselineId.length < 1 || this.baselineId.length > 160) {
      throw new Error('Ice authority baseline ID must contain 1-160 characters.');
    }
    this.maximumJournalEntries = journalSize;
    this.maximumLifecycleEvents = lifecycleSize;
    const count = this.count;
    const floeIdByCell = new Int32Array(count);
    floeIdByCell.fill(-1);
    this.arraysValue = {
      thickness: new Float32Array(count),
      effectiveThickness: new Float32Array(count),
      openness: new Float32Array(count),
      nextOpenness: new Float32Array(count),
      channelMemory: new Float32Array(count),
      nextChannelMemory: new Float32Array(count),
      channelAge: new Float32Array(count),
      nextChannelAge: new Float32Array(count),
      age: new Float32Array(count),
      breakStress: new Float32Array(count),
      snowCover: new Float32Array(count),
      nextSnowCover: new Float32Array(count),
      cellOwner: new Uint8Array(count),
      packBonded: new Uint8Array(count),
      floeIdByCell,
      floeOffsetX: new Float32Array(count),
      floeOffsetZ: new Float32Array(count),
      floeVelocityX: new Float32Array(count),
      floeVelocityZ: new Float32Array(count),
      floeAngle: new Float32Array(count),
    };
    const baselineFloeIds = new Int32Array(count);
    baselineFloeIds.fill(-1);
    this.baseline = {
      thickness: new Float32Array(count),
      openness: new Float32Array(count),
      snowCover: new Float32Array(count),
      channelMemory: new Float32Array(count),
      channelAge: new Float32Array(count),
      cellOwner: new Uint8Array(count),
      floeIdByCell: baselineFloeIds,
    };
    this.committedThickness = new Uint8Array(count);
    this.committedOpenness = new Uint8Array(count);
    this.committedSnow = new Uint8Array(count);
    this.committedChannelMemory = new Uint8Array(count);
    this.committedChannelAge = new Uint16Array(count);
    this.committedOwner = new Uint8Array(count);
    this.committedFloeId = new Int32Array(count);
    this.committedFloeId.fill(-1);
    const chunkColumns = Math.ceil(this.columns / ICE_AUTHORITY_CHUNK_SIZE);
    const chunkRows = Math.ceil(this.rows / ICE_AUTHORITY_CHUNK_SIZE);
    this.chunks = Array.from(
      { length: chunkColumns * chunkRows },
      (): MutableChunkState => ({
        revision: ZERO_REVISION,
        topologyRevision: ZERO_REVISION,
      }),
    );
    this.bonds = new IceBondGrid(this.columns, this.rows);
    this.establishBaseline();
  }

  /** Mutable access is deliberately confined to the simulation owner. */
  public mutableArrays(): IceAuthorityMutableArrays {
    return this.arraysValue;
  }

  public baselineArrays(): IceAuthorityBaselineArrays {
    return this.baseline;
  }

  public replaceOpennessBuffers(
    current: Float32Array,
    next: Float32Array,
  ): void {
    this.assertArrayLength(current);
    this.assertArrayLength(next);
    this.arraysValue.openness = current;
    this.arraysValue.nextOpenness = next;
  }

  public replaceChannelBuffers(
    memory: Float32Array,
    nextMemory: Float32Array,
    age: Float32Array,
    nextAge: Float32Array,
  ): void {
    for (const array of [memory, nextMemory, age, nextAge]) this.assertArrayLength(array);
    this.arraysValue.channelMemory = memory;
    this.arraysValue.nextChannelMemory = nextMemory;
    this.arraysValue.channelAge = age;
    this.arraysValue.nextChannelAge = nextAge;
  }

  public replaceSnowBuffers(current: Float32Array, next: Float32Array): void {
    this.assertArrayLength(current);
    this.assertArrayLength(next);
    this.arraysValue.snowCover = current;
    this.arraysValue.nextSnowCover = next;
  }

  public replaceFloeMembershipBuffer(floeIdByCell: Int32Array): void {
    this.assertArrayLength(floeIdByCell);
    this.arraysValue.floeIdByCell = floeIdByCell;
  }

  /** Captures the authored deterministic field after generation, before play. */
  public establishBaseline(): void {
    const arrays = this.arraysValue;
    this.baseline.thickness.set(arrays.thickness);
    this.baseline.openness.set(arrays.openness);
    this.baseline.snowCover.set(arrays.snowCover);
    this.baseline.channelMemory.set(arrays.channelMemory);
    this.baseline.channelAge.set(arrays.channelAge);
    this.baseline.cellOwner.set(arrays.cellOwner);
    this.baseline.floeIdByCell.set(arrays.floeIdByCell);
    this.pendingCells.clear();
    this.pendingTopologyChunks.clear();
    this.journal.length = 0;
    this.lifecycleJournal.length = 0;
    this.lastCommittedTick = ZERO_SERVER_TICK;
    this.totalCommittedCells = 0;
    for (const chunk of this.chunks) {
      chunk.revision = ZERO_REVISION;
      chunk.topologyRevision = ZERO_REVISION;
    }
    this.captureCommittedWireState();
  }

  public markCellDirty(
    index: number,
    fields: IceAuthorityField = IceAuthorityField.All,
    causeId?: string,
  ): void {
    if (!this.validIndex(index) || fields === IceAuthorityField.None) return;
    const existing = this.pendingCells.get(index);
    this.pendingCells.set(index, {
      fields: (existing?.fields ?? IceAuthorityField.None) | fields,
      causeId: boundedCauseId(causeId) ?? existing?.causeId,
    });
  }

  public markCellsDirty(
    indices: readonly number[],
    fields: IceAuthorityField = IceAuthorityField.All,
    causeId?: string,
  ): void {
    for (const index of indices) this.markCellDirty(index, fields, causeId);
  }

  public markTopologyDirtyForCells(
    indices: readonly number[],
    causeId?: string,
  ): void {
    for (const index of indices) {
      if (!this.validIndex(index)) continue;
      this.pendingTopologyChunks.set(
        this.chunkIndexForCell(index),
        boundedCauseId(causeId),
      );
      this.markCellDirty(
        index,
        IceAuthorityField.Owner | IceAuthorityField.FloeMembership,
        causeId,
      );
    }
  }

  /** Drops uncommitted local notifications when ownership moves to a remote authority. */
  public discardPendingMutations(): void {
    this.pendingCells.clear();
    this.pendingTopologyChunks.clear();
  }

  public writeCell(
    index: number,
    change: Readonly<Partial<{
      thickness: number;
      openness: number;
      snow: number;
      channelMemory: number;
      channelAge: number;
      owner: IceCellOwner;
      floeId: number;
    }>>,
    causeId?: string,
  ): boolean {
    if (!this.validIndex(index)) return false;
    let fields = IceAuthorityField.None;
    const arrays = this.arraysValue;
    if (Number.isFinite(change.thickness)) {
      arrays.thickness[index] = clamp(change.thickness!, 0, 1);
      fields |= IceAuthorityField.Thickness;
    }
    if (Number.isFinite(change.openness)) {
      arrays.openness[index] = clamp(change.openness!, 0, 1);
      fields |= IceAuthorityField.Openness;
    }
    if (Number.isFinite(change.snow)) {
      arrays.snowCover[index] = clamp(change.snow!, 0, 1);
      fields |= IceAuthorityField.Snow;
    }
    if (Number.isFinite(change.channelMemory)) {
      arrays.channelMemory[index] = clamp(change.channelMemory!, 0, 1);
      fields |= IceAuthorityField.ChannelMemory;
    }
    if (Number.isFinite(change.channelAge)) {
      arrays.channelAge[index] = clamp(change.channelAge!, 0, 65_535);
      fields |= IceAuthorityField.ChannelAge;
    }
    if (
      change.owner === IceCellOwner.OpenWater ||
      change.owner === IceCellOwner.StaticPack ||
      change.owner === IceCellOwner.DetachedFloe ||
      change.owner === IceCellOwner.CoarseIce
    ) {
      arrays.cellOwner[index] = change.owner;
      fields |= IceAuthorityField.Owner;
    }
    if (change.floeId !== undefined) {
      arrays.floeIdByCell[index] = safeFloeId(change.floeId);
      fields |= IceAuthorityField.FloeMembership;
    }
    if (fields === IceAuthorityField.None) return false;
    this.markCellDirty(index, fields, causeId);
    return true;
  }

  public readCell(index: number): PackedIceCell | undefined {
    if (!this.validIndex(index)) return undefined;
    return this.packCell(index);
  }

  public readBaselineCell(index: number): PackedIceCell | undefined {
    if (!this.validIndex(index)) return undefined;
    return {
      index,
      thickness: unitByte(this.baseline.thickness[index]!),
      openness: unitByte(this.baseline.openness[index]!),
      snow: unitByte(this.baseline.snowCover[index]!),
      channelMemory: unitByte(this.baseline.channelMemory[index]!),
      channelAge: secondsU16(this.baseline.channelAge[index]!),
      owner: this.safeOwner(this.baseline.cellOwner[index]),
      floeId: safeFloeId(this.baseline.floeIdByCell[index]!),
    };
  }

  public commitTick(tick: ServerTick): readonly IceAuthorityChunkDelta[] {
    if (tick < this.lastCommittedTick) {
      throw new Error('Ice authority tick cannot move backwards.');
    }
    const byChunk = new Map<number, PackedIceCellDelta[]>();
    for (const [index, pending] of [...this.pendingCells].sort((a, b) => a[0] - b[0])) {
      const change = this.changedFields(index, pending);
      if (!change) continue;
      const chunkIndex = this.chunkIndexForCell(index);
      const changes = byChunk.get(chunkIndex) ?? [];
      changes.push(change);
      byChunk.set(chunkIndex, changes);
      this.acceptCommitted(index, change.fieldMask);
    }
    const touchedChunks = new Set([
      ...byChunk.keys(),
      ...this.pendingTopologyChunks.keys(),
    ]);
    const deltas: IceAuthorityChunkDelta[] = [];
    for (const chunkIndex of [...touchedChunks].sort((a, b) => a - b)) {
      const chunk = this.chunks[chunkIndex]!;
      const baseRevision = chunk.revision;
      const baseTopologyRevision = chunk.topologyRevision;
      const changes = byChunk.get(chunkIndex) ?? [];
      if (changes.length > 0) chunk.revision = nextRevision(chunk.revision);
      if (this.pendingTopologyChunks.has(chunkIndex)) {
        chunk.topologyRevision = nextRevision(chunk.topologyRevision);
      }
      const address = this.chunkAddress(chunkIndex);
      const baseline = this.createChunkBaseline(address.chunkX, address.chunkZ);
      deltas.push({
        ...address,
        baseRevision,
        revision: chunk.revision,
        baseTopologyRevision,
        topologyRevision: chunk.topologyRevision,
        serverTick: tick,
        checksum: baseline.checksum,
        changes,
      });
    }
    this.pendingCells.clear();
    this.pendingTopologyChunks.clear();
    this.lastCommittedTick = tick;
    this.totalCommittedCells += deltas.reduce(
      (total, delta) => total + delta.changes.length,
      0,
    );
    this.journal.push(...deltas);
    if (this.journal.length > this.maximumJournalEntries) {
      this.journal.splice(0, this.journal.length - this.maximumJournalEntries);
    }
    return deltas.map((delta) => this.cloneDelta(delta));
  }

  public createChunkBaseline(
    chunkX: number,
    chunkZ: number,
  ): IceAuthorityChunkBaseline {
    const chunkIndex = this.validateChunkAddress(chunkX, chunkZ);
    const chunk = this.chunks[chunkIndex]!;
    const changes: PackedIceCell[] = [];
    this.forEachChunkCell(chunkX, chunkZ, (index) => {
      if (!this.cellEqualsBaseline(index)) changes.push(this.packCell(index));
    });
    return {
      chunkX,
      chunkZ,
      revision: chunk.revision,
      topologyRevision: chunk.topologyRevision,
      changes,
      checksum: this.chunkChecksum(
        chunkX,
        chunkZ,
        chunk.revision,
        chunk.topologyRevision,
        changes,
      ),
    };
  }

  public createBaselinesForAllChunks(): readonly IceAuthorityChunkBaseline[] {
    return this.chunks.map((_chunk, index) => {
      const address = this.chunkAddress(index);
      return this.createChunkBaseline(address.chunkX, address.chunkZ);
    });
  }

  public journalSince(
    tick: ServerTick,
    interestedChunkIndices?: ReadonlySet<number>,
  ): readonly IceAuthorityChunkDelta[] {
    return this.journal
      .filter((entry) =>
        entry.serverTick > tick &&
        (!interestedChunkIndices || interestedChunkIndices.has(
          this.validateChunkAddress(entry.chunkX, entry.chunkZ),
        )))
      .map((entry) => this.cloneDelta(entry));
  }

  public replaceFloes(
    nextFloes: readonly Readonly<Omit<IceAuthorityFloeState, 'movementRevision'>>[],
    tick: ServerTick,
    causeId?: string,
  ): readonly IceFloeLifecycleEvent[] {
    const previous = new Map(this.floes);
    const next = new Map<number, MutableIceAuthorityFloeState>();
    for (const candidate of [...nextFloes].sort((a, b) => a.id - b.id)) {
      const prior = previous.get(candidate.id);
      const normalized = this.normalizeFloe(candidate, prior?.movementRevision);
      if (!normalized || next.has(normalized.id)) continue;
      if (prior && this.floeMovementChanged(prior, normalized)) {
        normalized.movementRevision = nextRevision(prior.movementRevision);
      }
      next.set(normalized.id, normalized);
      this.nextFloeId = Math.max(this.nextFloeId, normalized.id + 1);
    }
    const oldOwners = this.membershipOwners(previous);
    const newOwners = this.membershipOwners(next);
    const parentChildren = new Map<number, Set<number>>();
    for (const [cell, oldId] of oldOwners) {
      const newId = newOwners.get(cell);
      if (newId === undefined) continue;
      const children = parentChildren.get(oldId) ?? new Set<number>();
      children.add(newId);
      parentChildren.set(oldId, children);
    }
    const affected = new Set<number>();
    for (const cell of new Set([...oldOwners.keys(), ...newOwners.keys()])) {
      if (oldOwners.get(cell) !== newOwners.get(cell)) affected.add(cell);
    }
    if (affected.size > 0) this.markTopologyDirtyForCells([...affected], causeId);
    const topologyRevision = this.nextGlobalTopologyRevision();
    const events: IceFloeLifecycleEvent[] = [];
    for (const floe of next.values()) {
      const sources = [...new Set(floe.cells
        .map((cell) => oldOwners.get(cell))
        .filter((id): id is number => id !== undefined))]
        .sort((a, b) => a - b);
      const existed = previous.has(floe.id);
      const changedMembership = !existed || !this.sameCells(
        previous.get(floe.id)!.cells,
        floe.cells,
      );
      if (!changedMembership) continue;
      let kind: IceFloeLifecycleKind = 'CREATE';
      if (sources.length > 1) kind = 'MERGE';
      else if (sources.length === 1 && (parentChildren.get(sources[0]!)?.size ?? 0) > 1) {
        kind = 'SPLIT';
      } else if (existed) {
        // Membership can shrink/grow while retaining identity; reliable CREATE
        // is the canonical topology replacement for that stable ID.
        kind = 'CREATE';
      }
      events.push(this.makeLifecycleEvent(
        kind,
        floe.id,
        sources,
        topologyRevision,
        tick,
        floe,
        causeId,
      ));
    }
    for (const floe of previous.values()) {
      if (next.has(floe.id)) continue;
      const overlaps = floe.cells.some((cell) => newOwners.has(cell));
      const reattached = !overlaps && floe.cells.some(
        (cell) => this.arraysValue.cellOwner[cell] === IceCellOwner.StaticPack,
      );
      events.push(this.makeLifecycleEvent(
        reattached ? 'REATTACH' : 'REMOVE',
        floe.id,
        [floe.id],
        topologyRevision,
        tick,
        undefined,
        causeId,
      ));
    }
    this.floes.clear();
    for (const [id, floe] of next) this.floes.set(id, floe);
    this.lifecycleJournal.push(...events);
    if (this.lifecycleJournal.length > this.maximumLifecycleEvents) {
      this.lifecycleJournal.splice(
        0,
        this.lifecycleJournal.length - this.maximumLifecycleEvents,
      );
    }
    return events.map((event) => this.cloneLifecycle(event));
  }

  public updateFloeMovement(
    floeId: number,
    update: Readonly<Partial<Pick<
      IceAuthorityFloeState,
      | 'centerX'
      | 'centerZ'
      | 'offsetX'
      | 'offsetZ'
      | 'velocityX'
      | 'velocityZ'
      | 'yaw'
      | 'angularVelocity'
      | 'pressure'
    >>>,
    tick: ServerTick,
  ): IceFloeMovementSnapshot | undefined {
    const floe = this.floes.get(floeId);
    if (!floe) return undefined;
    let changed = false;
    for (const key of [
      'centerX', 'centerZ', 'offsetX', 'offsetZ', 'velocityX', 'velocityZ',
      'yaw', 'angularVelocity', 'pressure',
    ] as const) {
      const value = update[key];
      if (!Number.isFinite(value) || value === floe[key]) continue;
      floe[key] = key === 'pressure' ? clamp(value!, 0, 1) : value!;
      changed = true;
    }
    if (!changed) return undefined;
    floe.movementRevision = nextRevision(floe.movementRevision);
    return this.movementSnapshot(floe, tick);
  }

  public listFloes(): readonly IceAuthorityFloeState[] {
    return [...this.floes.values()]
      .sort((a, b) => a.id - b.id)
      .map(cloneFloe);
  }

  public movementSnapshots(
    tick: ServerTick,
    center?: Readonly<{ x: number; z: number; radius: number }>,
  ): readonly IceFloeMovementSnapshot[] {
    return [...this.floes.values()]
      .filter((floe) => !center || Math.hypot(
        floe.centerX + floe.offsetX - center.x,
        floe.centerZ + floe.offsetZ - center.z,
      ) <= Math.max(0, center.radius))
      .sort((a, b) => a.id - b.id)
      .map((floe) => this.movementSnapshot(floe, tick));
  }

  public lifecycleSince(tick: ServerTick): readonly IceFloeLifecycleEvent[] {
    return this.lifecycleJournal
      .filter((event) => event.serverTick > tick)
      .map((event) => this.cloneLifecycle(event));
  }

  public setSimulationTime(value: number): void {
    if (Number.isFinite(value)) this.simulationTime = Math.max(0, value);
  }

  public getSimulationTime(): number {
    return this.simulationTime;
  }

  public allocateFloeId(): number {
    return this.nextFloeId++;
  }

  public exportCheckpoint(): IceAuthorityCheckpoint {
    const cells: IceAuthorityCheckpointCell[] = [];
    for (let index = 0; index < this.count; index += 1) {
      if (!this.cellHasCheckpointState(index)) continue;
      cells.push({
        ...this.packCell(index),
        rawThickness: safeFinite(this.arraysValue.thickness[index]!),
        rawOpenness: safeFinite(this.arraysValue.openness[index]!),
        rawSnow: safeFinite(this.arraysValue.snowCover[index]!),
        rawChannelMemory: safeFinite(this.arraysValue.channelMemory[index]!),
        channelAge: safeFinite(this.arraysValue.channelAge[index]!),
        age: safeFinite(this.arraysValue.age[index]!),
        breakStress: safeFinite(this.arraysValue.breakStress[index]!),
        packBonded: this.arraysValue.packBonded[index] === 1,
        floeOffsetX: safeFinite(this.arraysValue.floeOffsetX[index]!),
        floeOffsetZ: safeFinite(this.arraysValue.floeOffsetZ[index]!),
        floeVelocityX: safeFinite(this.arraysValue.floeVelocityX[index]!),
        floeVelocityZ: safeFinite(this.arraysValue.floeVelocityZ[index]!),
        floeAngle: safeFinite(this.arraysValue.floeAngle[index]!),
      });
    }
    return {
      version: 2,
      baselineId: this.baselineId,
      formatVersion: ICE_AUTHORITY_FORMAT_VERSION,
      columns: this.columns,
      rows: this.rows,
      cellSize: this.cellSize,
      simulationTime: this.simulationTime,
      lastCommittedTick: this.lastCommittedTick,
      nextFloeId: this.nextFloeId,
      cells,
      bonds: this.bonds.exportSparse(),
      floes: this.listFloes(),
      chunks: this.chunks.map((chunk, index) => ({
        ...this.chunkAddress(index),
        revision: chunk.revision,
        topologyRevision: chunk.topologyRevision,
      })),
    };
  }

  public restoreCheckpoint(checkpoint: Readonly<IceAuthorityCheckpoint>): boolean {
    if (
      (checkpoint.version !== 1 && checkpoint.version !== 2) ||
      checkpoint.baselineId !== this.baselineId ||
      (checkpoint.formatVersion !== 1 &&
        checkpoint.formatVersion !== ICE_AUTHORITY_FORMAT_VERSION) ||
      checkpoint.columns !== this.columns ||
      checkpoint.rows !== this.rows ||
      checkpoint.cellSize !== this.cellSize ||
      !Array.isArray(checkpoint.cells) ||
      !Array.isArray(checkpoint.bonds) ||
      !Array.isArray(checkpoint.floes) ||
      !Array.isArray(checkpoint.chunks)
    ) return false;
    this.restoreBaselineArrays();
    this.bonds.clear();
    this.floes.clear();
    for (const cell of checkpoint.cells) {
      if (!this.validIndex(cell.index)) continue;
      const index = cell.index;
      const arrays = this.arraysValue;
      arrays.thickness[index] =
        checkpoint.version >= 2 && Number.isFinite(cell.rawThickness)
          ? clamp(cell.rawThickness!, 0, 1)
          : byteUnit(cell.thickness);
      arrays.effectiveThickness[index] = arrays.thickness[index]!;
      arrays.openness[index] =
        checkpoint.version >= 2 && Number.isFinite(cell.rawOpenness)
          ? clamp(cell.rawOpenness!, 0, 1)
          : byteUnit(cell.openness);
      arrays.channelMemory[index] =
        checkpoint.version >= 2 && Number.isFinite(cell.rawChannelMemory)
          ? clamp(cell.rawChannelMemory!, 0, 1)
          : byteUnit(cell.channelMemory);
      arrays.channelAge[index] = safeFinite(cell.channelAge);
      arrays.age[index] = safeFinite(cell.age);
      arrays.breakStress[index] = safeFinite(cell.breakStress);
      arrays.snowCover[index] =
        checkpoint.version >= 2 && Number.isFinite(cell.rawSnow)
          ? clamp(cell.rawSnow!, 0, 1)
          : byteUnit(cell.snow);
      arrays.cellOwner[index] = cell.owner;
      arrays.floeIdByCell[index] = safeFloeId(cell.floeId);
      arrays.packBonded[index] = cell.packBonded ? 1 : 0;
      arrays.floeOffsetX[index] = safeFinite(cell.floeOffsetX);
      arrays.floeOffsetZ[index] = safeFinite(cell.floeOffsetZ);
      arrays.floeVelocityX[index] = safeFinite(cell.floeVelocityX);
      arrays.floeVelocityZ[index] = safeFinite(cell.floeVelocityZ);
      arrays.floeAngle[index] = safeFinite(cell.floeAngle);
    }
    arraysCopyCurrentToNext(this.arraysValue);
    this.bonds.importSparse(checkpoint.bonds);
    for (const floe of checkpoint.floes) {
      const normalized = this.normalizeFloe(floe, floe.movementRevision);
      if (normalized && !this.floes.has(normalized.id)) {
        this.floes.set(normalized.id, normalized);
      }
    }
    for (const chunk of this.chunks) {
      chunk.revision = ZERO_REVISION;
      chunk.topologyRevision = ZERO_REVISION;
    }
    for (const saved of checkpoint.chunks) {
      try {
        const index = this.validateChunkAddress(saved.chunkX, saved.chunkZ);
        this.chunks[index] = {
          revision: revision(saved.revision),
          topologyRevision: revision(saved.topologyRevision),
        };
      } catch {
        return false;
      }
    }
    this.simulationTime = Math.max(0, safeFinite(checkpoint.simulationTime));
    this.lastCommittedTick = serverTick(checkpoint.lastCommittedTick);
    this.nextFloeId = Math.max(
      1,
      Number.isSafeInteger(checkpoint.nextFloeId) ? checkpoint.nextFloeId : 1,
      ...[...this.floes.keys()].map((id) => id + 1),
    );
    this.pendingCells.clear();
    this.pendingTopologyChunks.clear();
    this.journal.length = 0;
    this.lifecycleJournal.length = 0;
    this.captureCommittedWireState();
    return true;
  }

  public diagnostics(): IceAuthorityStateDiagnostics {
    let modifiedCells = 0;
    for (let index = 0; index < this.count; index += 1) {
      if (!this.cellEqualsBaseline(index)) modifiedCells += 1;
    }
    return {
      cells: this.count,
      chunks: this.chunks.length,
      modifiedCells,
      pendingCells: this.pendingCells.size,
      pendingTopologyChunks: this.pendingTopologyChunks.size,
      retainedJournalEntries: this.journal.length,
      retainedLifecycleEvents: this.lifecycleJournal.length,
      floes: this.floes.size,
      lastCommittedTick: this.lastCommittedTick,
      totalCommittedCells: this.totalCommittedCells,
    };
  }

  private normalizeFloe(
    floe: Readonly<Omit<IceAuthorityFloeState, 'movementRevision'>> | Readonly<IceAuthorityFloeState>,
    movementRevision: Revision = ZERO_REVISION,
  ): MutableIceAuthorityFloeState | undefined {
    if (!Number.isSafeInteger(floe.id) || floe.id < 1) return undefined;
    const cells = sortedUniqueCells(floe.cells, this.count);
    if (cells.length === 0) return undefined;
    return {
      id: floe.id,
      cells,
      centerX: safeFinite(floe.centerX),
      centerZ: safeFinite(floe.centerZ),
      offsetX: safeFinite(floe.offsetX),
      offsetZ: safeFinite(floe.offsetZ),
      velocityX: safeFinite(floe.velocityX),
      velocityZ: safeFinite(floe.velocityZ),
      yaw: safeFinite(floe.yaw),
      angularVelocity: safeFinite(floe.angularVelocity),
      pressure: clamp(safeFinite(floe.pressure), 0, 1),
      separationCooldown: Math.max(0, safeFinite(floe.separationCooldown)),
      detachedAgeSeconds: Math.max(0, safeFinite(floe.detachedAgeSeconds)),
      contactBondSeconds: Math.max(0, safeFinite(floe.contactBondSeconds)),
      thermalAnchorSeconds: Math.max(0, safeFinite(floe.thermalAnchorSeconds)),
      seed: clamp(safeFinite(floe.seed), 0, 1),
      movementRevision,
    };
  }

  private membershipOwners(
    floes: ReadonlyMap<number, Readonly<MutableIceAuthorityFloeState>>,
  ): Map<number, number> {
    const result = new Map<number, number>();
    for (const floe of [...floes.values()].sort((a, b) => a.id - b.id)) {
      for (const cell of floe.cells) if (!result.has(cell)) result.set(cell, floe.id);
    }
    return result;
  }

  private makeLifecycleEvent(
    kind: IceFloeLifecycleKind,
    floeId: number,
    sourceFloeIds: readonly number[],
    topologyRevision: Revision,
    tick: ServerTick,
    floe: Readonly<MutableIceAuthorityFloeState> | undefined,
    causeId: string | undefined,
  ): IceFloeLifecycleEvent {
    this.lifecycleSequence += 1;
    return {
      eventId: `ice-floe:${Number(tick)}:${this.lifecycleSequence}`,
      kind,
      topologyRevision,
      serverTick: tick,
      floeId,
      sourceFloeIds: [...sourceFloeIds],
      floe: floe ? cloneFloe(floe) : undefined,
      causeId: boundedCauseId(causeId),
    };
  }

  private nextGlobalTopologyRevision(): Revision {
    let maximum = 0;
    for (const chunk of this.chunks) maximum = Math.max(maximum, chunk.topologyRevision);
    return revision(maximum + 1);
  }

  private movementSnapshot(
    floe: Readonly<MutableIceAuthorityFloeState>,
    tick: ServerTick,
  ): IceFloeMovementSnapshot {
    return {
      floeId: floe.id,
      movementRevision: floe.movementRevision,
      serverTick: tick,
      centerX: floe.centerX,
      centerZ: floe.centerZ,
      offsetX: floe.offsetX,
      offsetZ: floe.offsetZ,
      velocityX: floe.velocityX,
      velocityZ: floe.velocityZ,
      yaw: floe.yaw,
      angularVelocity: floe.angularVelocity,
      pressure: floe.pressure,
    };
  }

  private floeMovementChanged(
    previous: Readonly<MutableIceAuthorityFloeState>,
    next: Readonly<MutableIceAuthorityFloeState>,
  ): boolean {
    return previous.centerX !== next.centerX ||
      previous.centerZ !== next.centerZ ||
      previous.offsetX !== next.offsetX ||
      previous.offsetZ !== next.offsetZ ||
      previous.velocityX !== next.velocityX ||
      previous.velocityZ !== next.velocityZ ||
      previous.yaw !== next.yaw ||
      previous.angularVelocity !== next.angularVelocity ||
      previous.pressure !== next.pressure;
  }

  private changedFields(
    index: number,
    pending: Readonly<PendingCell>,
  ): PackedIceCellDelta | undefined {
    const packed = this.packCell(index);
    let fieldMask = IceAuthorityField.None;
    if (
      pending.fields & IceAuthorityField.Thickness &&
      packed.thickness !== this.committedThickness[index]
    ) fieldMask |= IceAuthorityField.Thickness;
    if (
      pending.fields & IceAuthorityField.Openness &&
      packed.openness !== this.committedOpenness[index]
    ) fieldMask |= IceAuthorityField.Openness;
    if (
      pending.fields & IceAuthorityField.Snow &&
      packed.snow !== this.committedSnow[index]
    ) fieldMask |= IceAuthorityField.Snow;
    if (
      pending.fields & IceAuthorityField.ChannelMemory &&
      packed.channelMemory !== this.committedChannelMemory[index]
    ) fieldMask |= IceAuthorityField.ChannelMemory;
    if (
      pending.fields & IceAuthorityField.ChannelAge &&
      packed.channelAge !== this.committedChannelAge[index]
    ) fieldMask |= IceAuthorityField.ChannelAge;
    if (
      pending.fields & IceAuthorityField.Owner &&
      packed.owner !== this.committedOwner[index]
    ) fieldMask |= IceAuthorityField.Owner;
    if (
      pending.fields & IceAuthorityField.FloeMembership &&
      packed.floeId !== this.committedFloeId[index]
    ) fieldMask |= IceAuthorityField.FloeMembership;
    if (fieldMask === IceAuthorityField.None) return undefined;
    return {
      index,
      fieldMask,
      thickness: fieldMask & IceAuthorityField.Thickness ? packed.thickness : undefined,
      openness: fieldMask & IceAuthorityField.Openness ? packed.openness : undefined,
      snow: fieldMask & IceAuthorityField.Snow ? packed.snow : undefined,
      channelMemory: fieldMask & IceAuthorityField.ChannelMemory
        ? packed.channelMemory
        : undefined,
      channelAge: fieldMask & IceAuthorityField.ChannelAge
        ? packed.channelAge
        : undefined,
      owner: fieldMask & IceAuthorityField.Owner ? packed.owner : undefined,
      floeId: fieldMask & IceAuthorityField.FloeMembership ? packed.floeId : undefined,
      causeId: pending.causeId,
    };
  }

  private acceptCommitted(index: number, fields: IceAuthorityField): void {
    const packed = this.packCell(index);
    if (fields & IceAuthorityField.Thickness) this.committedThickness[index] = packed.thickness;
    if (fields & IceAuthorityField.Openness) this.committedOpenness[index] = packed.openness;
    if (fields & IceAuthorityField.Snow) this.committedSnow[index] = packed.snow;
    if (fields & IceAuthorityField.ChannelMemory) {
      this.committedChannelMemory[index] = packed.channelMemory;
    }
    if (fields & IceAuthorityField.ChannelAge) {
      this.committedChannelAge[index] = packed.channelAge;
    }
    if (fields & IceAuthorityField.Owner) this.committedOwner[index] = packed.owner;
    if (fields & IceAuthorityField.FloeMembership) this.committedFloeId[index] = packed.floeId;
  }

  private packCell(index: number): PackedIceCell {
    return {
      index,
      thickness: unitByte(this.arraysValue.thickness[index]!),
      openness: unitByte(this.arraysValue.openness[index]!),
      snow: unitByte(this.arraysValue.snowCover[index]!),
      channelMemory: unitByte(this.arraysValue.channelMemory[index]!),
      channelAge: secondsU16(this.arraysValue.channelAge[index]!),
      owner: this.safeOwner(this.arraysValue.cellOwner[index]),
      floeId: safeFloeId(this.arraysValue.floeIdByCell[index]!),
    };
  }

  private cellEqualsBaseline(index: number): boolean {
    const current = this.packCell(index);
    return current.thickness === unitByte(this.baseline.thickness[index]!) &&
      current.openness === unitByte(this.baseline.openness[index]!) &&
      current.snow === unitByte(this.baseline.snowCover[index]!) &&
      current.channelMemory === unitByte(this.baseline.channelMemory[index]!) &&
      current.channelAge === secondsU16(this.baseline.channelAge[index]!) &&
      current.owner === this.safeOwner(this.baseline.cellOwner[index]) &&
      current.floeId === safeFloeId(this.baseline.floeIdByCell[index]!);
  }

  private cellHasCheckpointState(index: number): boolean {
    if (!this.cellEqualsBaseline(index)) return true;
    const arrays = this.arraysValue;
    return arrays.channelAge[index] !== 0 ||
      arrays.age[index] !== 0 ||
      arrays.breakStress[index] !== 0 ||
      arrays.packBonded[index] !== 0 ||
      arrays.floeOffsetX[index] !== 0 ||
      arrays.floeOffsetZ[index] !== 0 ||
      arrays.floeVelocityX[index] !== 0 ||
      arrays.floeVelocityZ[index] !== 0 ||
      arrays.floeAngle[index] !== 0;
  }

  private captureCommittedWireState(): void {
    for (let index = 0; index < this.count; index += 1) {
      const packed = this.packCell(index);
      this.committedThickness[index] = packed.thickness;
      this.committedOpenness[index] = packed.openness;
      this.committedSnow[index] = packed.snow;
      this.committedChannelMemory[index] = packed.channelMemory;
      this.committedChannelAge[index] = packed.channelAge;
      this.committedOwner[index] = packed.owner;
      this.committedFloeId[index] = packed.floeId;
    }
  }

  private restoreBaselineArrays(): void {
    const arrays = this.arraysValue;
    arrays.thickness.set(this.baseline.thickness);
    arrays.effectiveThickness.set(this.baseline.thickness);
    arrays.openness.set(this.baseline.openness);
    arrays.channelMemory.set(this.baseline.channelMemory);
    arrays.channelAge.set(this.baseline.channelAge);
    arrays.snowCover.set(this.baseline.snowCover);
    arrays.cellOwner.set(this.baseline.cellOwner);
    arrays.floeIdByCell.set(this.baseline.floeIdByCell);
    arrays.age.fill(0);
    arrays.breakStress.fill(0);
    arrays.packBonded.fill(0);
    arrays.floeOffsetX.fill(0);
    arrays.floeOffsetZ.fill(0);
    arrays.floeVelocityX.fill(0);
    arrays.floeVelocityZ.fill(0);
    arrays.floeAngle.fill(0);
  }

  private chunkChecksum(
    chunkX: number,
    chunkZ: number,
    chunkRevision: Revision,
    topologyRevision: Revision,
    changes: readonly PackedIceCell[],
  ): string {
    let hash = 0x811c9dc5;
    const accept = (value: number): void => {
      let remaining = value | 0;
      for (let byte = 0; byte < 4; byte += 1) {
        hash ^= remaining & 0xff;
        hash = Math.imul(hash, 0x01000193) >>> 0;
        remaining >>= 8;
      }
    };
    accept(chunkX);
    accept(chunkZ);
    accept(chunkRevision);
    accept(topologyRevision);
    for (const cell of changes) {
      accept(cell.index);
      accept(cell.thickness);
      accept(cell.openness);
      accept(cell.snow);
      accept(cell.channelMemory);
      accept(cell.channelAge);
      accept(cell.owner);
      accept(cell.floeId);
    }
    return hash.toString(16).padStart(8, '0');
  }

  private cloneDelta(delta: Readonly<IceAuthorityChunkDelta>): IceAuthorityChunkDelta {
    return {
      ...delta,
      changes: delta.changes.map((change) => ({ ...change })),
    };
  }

  private cloneLifecycle(event: Readonly<IceFloeLifecycleEvent>): IceFloeLifecycleEvent {
    return {
      ...event,
      sourceFloeIds: [...event.sourceFloeIds],
      floe: event.floe ? { ...event.floe, cells: [...event.floe.cells] } : undefined,
    };
  }

  private sameCells(left: readonly number[], right: readonly number[]): boolean {
    return left.length === right.length && left.every((cell, index) => cell === right[index]);
  }

  private safeOwner(value: number | undefined): IceCellOwner {
    return value === IceCellOwner.StaticPack ||
      value === IceCellOwner.DetachedFloe ||
      value === IceCellOwner.CoarseIce
      ? value
      : IceCellOwner.OpenWater;
  }

  private validIndex(index: number): boolean {
    return Number.isSafeInteger(index) && index >= 0 && index < this.count;
  }

  private assertArrayLength(array: ArrayLike<number>): void {
    if (array.length !== this.count) throw new Error('Ice authority array length mismatch.');
  }

  private chunkIndexForCell(index: number): number {
    const column = index % this.columns;
    const row = Math.floor(index / this.columns);
    const chunkX = Math.floor(column / ICE_AUTHORITY_CHUNK_SIZE);
    const chunkZ = Math.floor(row / ICE_AUTHORITY_CHUNK_SIZE);
    return chunkZ * Math.ceil(this.columns / ICE_AUTHORITY_CHUNK_SIZE) + chunkX;
  }

  private chunkAddress(chunkIndex: number): IceAuthorityChunkAddress {
    const chunkColumns = Math.ceil(this.columns / ICE_AUTHORITY_CHUNK_SIZE);
    return {
      chunkX: chunkIndex % chunkColumns,
      chunkZ: Math.floor(chunkIndex / chunkColumns),
    };
  }

  private validateChunkAddress(chunkX: number, chunkZ: number): number {
    const chunkColumns = Math.ceil(this.columns / ICE_AUTHORITY_CHUNK_SIZE);
    const chunkRows = Math.ceil(this.rows / ICE_AUTHORITY_CHUNK_SIZE);
    if (
      !Number.isSafeInteger(chunkX) ||
      !Number.isSafeInteger(chunkZ) ||
      chunkX < 0 ||
      chunkZ < 0 ||
      chunkX >= chunkColumns ||
      chunkZ >= chunkRows
    ) throw new Error('Ice authority chunk address is outside the field.');
    return chunkZ * chunkColumns + chunkX;
  }

  private forEachChunkCell(
    chunkX: number,
    chunkZ: number,
    visitor: (index: number) => void,
  ): void {
    const startColumn = chunkX * ICE_AUTHORITY_CHUNK_SIZE;
    const startRow = chunkZ * ICE_AUTHORITY_CHUNK_SIZE;
    for (
      let row = startRow;
      row < Math.min(this.rows, startRow + ICE_AUTHORITY_CHUNK_SIZE);
      row += 1
    ) {
      for (
        let column = startColumn;
        column < Math.min(this.columns, startColumn + ICE_AUTHORITY_CHUNK_SIZE);
        column += 1
      ) visitor(row * this.columns + column);
    }
  }
}

const arraysCopyCurrentToNext = (arrays: IceAuthorityMutableArrays): void => {
  arrays.nextOpenness.set(arrays.openness);
  arrays.nextChannelMemory.set(arrays.channelMemory);
  arrays.nextChannelAge.set(arrays.channelAge);
  arrays.nextSnowCover.set(arrays.snowCover);
};
