  public setActive(active: boolean): void {
    const changed = this.active !== active;
    this.active = active;
    this.root.visible = active;
    if (active && changed) {
      this.resourcePresentationAccumulator = 1;
      this.trackPresentationAccumulator = 1;
      this.syncCampPresentation(true);
      this.campSmokePreviousHeat.clear();
      for (const fire of this.simulation.firePits) {
        this.campSmokePreviousHeat.set(
          this.fireKey(fire.x, fire.z),
          fire.stage === 'LIT' ? fire.heatLevel ?? 0 : 0,
        );
      }
    }
  }

