  public isWeatherShelteredAt(position: Readonly<{
    x: number;
    y: number;
    z: number;
  }>): boolean {
    if (!this.active) return false;
    return this.simulation.shelters.some((shelter) =>
      shelter.stage >= 3 &&
      Math.hypot(position.x - shelter.x, position.z - shelter.z) <= 2.45 &&
      position.y <= this.terrain.sampleHeight(shelter.x, shelter.z) + 2.55
    );
  }

  public listSnowObstacleDescriptors(): readonly SnowObstacleDescriptor[] {
    if (!this.active) return [];
    const resourceObstacles = this.simulation.resources.flatMap((node) => {
      if (node.state === 'DEPLETED' || node.kind === 'FALLEN_BRANCHES' ||
        node.kind === 'BURIED_FOOD') return [];
      const tree = node.kind === 'TREE';
      return [{
        id: `wilderness-resource:${node.id}`,
        owner: 'GAMEPLAY' as const,
        x: node.x,
        z: node.z,
        width: tree ? 1.4 * node.scale : 1.1 * node.scale,
        depth: tree ? 1.4 * node.scale : 1.05 * node.scale,
        height: tree ? 4.6 * node.scale : node.kind === 'ROCK' ? 1.25 * node.scale : 0.75,
        porosity: tree ? 0.58 : node.kind === 'BERRY_SHRUB' ? 0.5 : 0.12,
        snowCatch: tree ? 0.78 : 0.9,
      }];
    });
    // One in four visual-only trees contributes physical lee shaping. This is
    // dense enough to make forest belts read in the snow while keeping the
    // low-frequency obstacle registry comfortably bounded.
    const promotedScenery = this.promotedSceneryTreeIndices();
    const sceneryObstacles = WILDERNESS_SCENERY_TREES.flatMap((tree, index) =>
      index % 4 === 0 && !promotedScenery.has(index)
        ? [{
            id: `wilderness-scenery-tree:${index}`,
            owner: 'GAMEPLAY' as const,
            x: tree.x,
            z: tree.z,
            width: 1.35 * tree.scale,
            depth: 1.35 * tree.scale,
            height: 4.4 * tree.scale,
            yawRadians: tree.heading,
            porosity: 0.62,
            snowCatch: 0.72,
          }]
        : []);
    const shelterObstacles = this.simulation.shelters.map((shelter, index) => ({
      id: `wilderness-shelter:${index}`,
      owner: 'GAMEPLAY' as const,
      x: shelter.x,
      z: shelter.z,
      width: 3.25,
      depth: 3.05,
      height: 2.45,
      yawRadians: shelter.heading,
      porosity: shelter.stage >= 3 ? 0.12 : 0.56,
      snowCatch: shelter.stage >= 3 ? 1.15 : 0.72,
    }));
    return [...resourceObstacles, ...sceneryObstacles, ...shelterObstacles];
  }

  public sampleWeatherExposure(
    x: number,
    z: number,
    windX: number,
    windZ: number,
  ): number {
    let shelter = 0;
    for (const patch of WILDERNESS_FOREST_PATCHES) {
      const nx = (x - patch.x) / patch.radiusX;
      const nz = (z - patch.z) / patch.radiusZ;
      const density = clamp(1 - Math.hypot(nx, nz), 0, 1);
      shelter = Math.max(shelter, density * 0.34);
    }
    for (const cliff of WILDERNESS_CLIFF_FEATURES) {
      const dx = x - cliff.x;
      const dz = z - cliff.z;
      const distance = Math.hypot(dx, dz);
      if (distance > 12 * cliff.scale) continue;
      const length = Math.max(0.001, distance);
      const downwind = (dx / length) * windX + (dz / length) * windZ;
      if (downwind <= 0.15) continue;
      shelter = Math.max(
        shelter,
        downwind * clamp(1 - distance / (12 * cliff.scale), 0, 1) * 0.48,
      );
    }
    for (const built of this.simulation.shelters) {
      if (built.stage < 2) continue;
      const distance = Math.hypot(x - built.x, z - built.z);
      shelter = Math.max(
        shelter,
        clamp(1 - distance / 5.5, 0, 1) * (built.stage >= 3 ? 0.72 : 0.42),
      );
    }
    return clamp(1 - shelter, 0.22, 1);
  }

