import type { IceClass } from './IceWorldTypes';

export type SolidIceClass = 'thin' | 'medium' | 'thick';
export type IceVisualProfileId = 'current' | 'joyful-v1';
export type IceMaterialDebugMode =
  | 'normal'
  | 'thickness'
  | 'weights';

export interface IceVisualBlendWeights {
  thin: number;
  medium: number;
  thick: number;
}

export interface IceVisualStyle {
  iceClass: SolidIceClass;
  weights: IceVisualBlendWeights;
  color: number;
  sideColor: number;
  opacity: number;
  heightScale: number;
  roughness: number;
}

export const ICE_THICKNESS_THRESHOLDS = {
  medium: 0.58,
  thick: 0.76,
} as const;

export const ICE_VISUAL_TRANSITIONS = {
  thinToMediumStart: 0.48,
  thinToMediumEnd: 0.66,
  mediumToThickStart: 0.68,
  mediumToThickEnd: 0.84,
  maximumBoundaryShift: 0.014,
} as const;

export interface IceVisualTarget {
  color: number;
  sideColor: number;
  opacity: number;
  heightScale: number;
  roughness: number;
}

type IceVisualTargets = Readonly<Record<
  SolidIceClass,
  Readonly<IceVisualTarget>
>>;

