export const ICE_VISUAL_PROFILES: Readonly<
  Record<IceVisualProfileId, IceVisualTargets>
> = Object.freeze({
  current: CURRENT_VISUAL_TARGETS,
  'joyful-v1': JOYFUL_V1_VISUAL_TARGETS,
});

export const DEFAULT_ICE_VISUAL_PROFILE_ID: IceVisualProfileId =
  'joyful-v1';

const clamp = (
  value: number,
  minimum: number,
  maximum: number,
): number => Math.max(minimum, Math.min(maximum, value));

const smoothstep = (
  start: number,
  end: number,
  value: number,
): number => {
  const amount = clamp((value - start) / (end - start), 0, 1);
  return amount * amount * (3 - 2 * amount);
};

const blendChannel = (
  shift: number,
  weights: Readonly<IceVisualBlendWeights>,
  targets: IceVisualTargets,
): number => {
  const thin = (targets.thin.color >> shift) & 0xff;
  const medium =
    (targets.medium.color >> shift) & 0xff;
  const thick = (targets.thick.color >> shift) & 0xff;
  return Math.round(
    thin * weights.thin +
      medium * weights.medium +
      thick * weights.thick,
  );
};

const blendSideChannel = (
  shift: number,
  weights: Readonly<IceVisualBlendWeights>,
  targets: IceVisualTargets,
): number => {
  const thin =
    (targets.thin.sideColor >> shift) & 0xff;
  const medium =
    (targets.medium.sideColor >> shift) & 0xff;
  const thick =
    (targets.thick.sideColor >> shift) & 0xff;
  return Math.round(
    thin * weights.thin +
      medium * weights.medium +
      thick * weights.thick,
  );
};

const blendHex = (
  weights: Readonly<IceVisualBlendWeights>,
  side: boolean,
  targets: IceVisualTargets,
): number => {
  const channel = side ? blendSideChannel : blendChannel;
  return (
    (channel(16, weights, targets) << 16) |
    (channel(8, weights, targets) << 8) |
    channel(0, weights, targets)
  );
};

const blendTargetValue = (
  key: 'opacity' | 'heightScale' | 'roughness',
  weights: Readonly<IceVisualBlendWeights>,
  targets: IceVisualTargets,
): number =>
  targets.thin[key] * weights.thin +
  targets.medium[key] * weights.medium +
  targets.thick[key] * weights.thick;

export const classifySolidIce = (
  thickness: number,
): SolidIceClass => {
  if (thickness < ICE_THICKNESS_THRESHOLDS.medium) return 'thin';
  if (thickness < ICE_THICKNESS_THRESHOLDS.thick) return 'medium';
  return 'thick';
};

export const classifyIceSurface = (
  thickness: number,
  openness: number,
  resistance: number,
): IceClass => {
  if (openness > 0.82 || resistance < 0.08) return 'open';
  if (openness > 0.62 && resistance < 0.3) return 'channel';
  return classifySolidIce(thickness);
};

export const getIceVisualBlendWeights = (
  thickness: number,
  boundaryNoise = 0,
): IceVisualBlendWeights => {
  const clampedThickness = clamp(thickness, 0, 1);
  const boundaryShift =
    clamp(boundaryNoise, -1, 1) *
    ICE_VISUAL_TRANSITIONS.maximumBoundaryShift;
  const mediumProgress = smoothstep(
    ICE_VISUAL_TRANSITIONS.thinToMediumStart +
      boundaryShift,
    ICE_VISUAL_TRANSITIONS.thinToMediumEnd +
      boundaryShift,
    clampedThickness,
  );
  const thickProgress = smoothstep(
    ICE_VISUAL_TRANSITIONS.mediumToThickStart +
      boundaryShift,
    ICE_VISUAL_TRANSITIONS.mediumToThickEnd +
      boundaryShift,
    clampedThickness,
  );
  const thin = 1 - mediumProgress;
  const thick = thickProgress;
  return {
    thin,
    medium: Math.max(0, 1 - thin - thick),
    thick,
  };
};

export const getIceVisualStyle = (
  thickness: number,
  boundaryNoise = 0,
  profileId: IceVisualProfileId = 'current',
): IceVisualStyle => {
  const weights = getIceVisualBlendWeights(
    thickness,
    boundaryNoise,
  );
  const targets = ICE_VISUAL_PROFILES[profileId];
  return {
    iceClass: classifySolidIce(thickness),
    weights,
    color: blendHex(weights, false, targets),
    sideColor: blendHex(weights, true, targets),
    opacity: blendTargetValue('opacity', weights, targets),
    heightScale: blendTargetValue('heightScale', weights, targets),
    roughness: blendTargetValue('roughness', weights, targets),
  };
};

export const getIceThicknessOpacity = (
  thickness: number,
  boundaryNoise = 0,
  profileId: IceVisualProfileId = 'current',
): number =>
  getIceVisualStyle(
    thickness,
    boundaryNoise,
    profileId,
  ).opacity;
