export interface ReplicatedIceCell {
  readonly index: number;
  readonly thickness: number;
  readonly openness: number;
  readonly snow: number;
  readonly channelMemory: number;
  readonly channelAge: number;
  readonly owner: IceCellOwner;
  readonly floeId: number;
}

export interface ReplicatedIceCellDelta extends Omit<PackedIceCellDelta, 'index'> {
  readonly index: number;
}

export interface PackedIceCellRun {
  readonly startIndex: number;
  /** Seven values per cell: thickness, openness, snow, memory, age, owner, floeId. */
  readonly values: readonly number[];
}

export interface PackedIceDeltaRun {
  readonly startIndex: number;
  /** One variable-length [fieldMask, fields...] tuple per consecutive cell. */
  readonly cells: readonly (readonly number[])[];
  readonly causeIds?: readonly (string | null)[];
}

export interface ReplicatedIceChunkBaseline {
  readonly chunkX: number;
  readonly chunkZ: number;
  readonly revision: Revision;
  readonly topologyRevision: Revision;
  readonly checksum: string;
  readonly runs: readonly PackedIceCellRun[];
}

export interface ReplicatedIceChunkDelta {
  readonly chunkX: number;
  readonly chunkZ: number;
  readonly baseRevision: Revision;
  readonly revision: Revision;
  readonly baseTopologyRevision: Revision;
  readonly topologyRevision: Revision;
  readonly checksum: string;
  readonly runs: readonly PackedIceDeltaRun[];
}

