const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const integer = (value: unknown, minimum: number, maximum: number): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) &&
  value >= minimum && value <= maximum;
const finite = (value: unknown, minimum = -1e9, maximum = 1e9): value is number =>
  typeof value === 'number' && Number.isFinite(value) &&
  value >= minimum && value <= maximum;
const text = (value: unknown, maximum: number): value is string =>
  typeof value === 'string' && value.length > 0 && value.length <= maximum;
const validOwner = (value: unknown): value is IceCellOwner =>
  value === IceCellOwner.OpenWater || value === IceCellOwner.StaticPack ||
  value === IceCellOwner.DetachedFloe || value === IceCellOwner.CoarseIce;

const localIndex = (globalIndex: number, columns: number): number => {
  const column = globalIndex % columns;
  const row = Math.floor(globalIndex / columns);
  return (row % ICE_AUTHORITY_CHUNK_SIZE) * ICE_AUTHORITY_CHUNK_SIZE +
    (column % ICE_AUTHORITY_CHUNK_SIZE);
};

const appendHash = (current: number, value: number): number => {
  let hash = current;
  let remaining = value | 0;
  for (let byte = 0; byte < 4; byte += 1) {
    hash ^= remaining & 0xff;
    hash = Math.imul(hash, 0x01000193) >>> 0;
    remaining >>= 8;
  }
  return hash;
};

export const iceChunkChecksum = (
  chunkX: number,
  chunkZ: number,
  chunkRevision: Revision,
  topologyRevision: Revision,
  cells: readonly ReplicatedIceCell[],
): string => {
  let hash = 0x811c9dc5;
  for (const value of [chunkX, chunkZ, chunkRevision, topologyRevision]) {
    hash = appendHash(hash, value);
  }
  for (const cell of [...cells].sort((a, b) => a.index - b.index)) {
    for (const value of [
      cell.index, cell.thickness, cell.openness, cell.snow,
      cell.channelMemory, cell.channelAge, cell.owner, cell.floeId,
    ]) hash = appendHash(hash, value);
  }
  return hash.toString(16).padStart(8, '0');
};

export const packIceCellRuns = (
  cells: readonly ReplicatedIceCell[],
): readonly PackedIceCellRun[] => {
  const sorted = [...cells].sort((a, b) => a.index - b.index);
  const runs: Array<{ startIndex: number; values: number[] }> = [];
  let previousIndex = -2;
  const seen = new Set<number>();
  for (const cell of sorted) {
    validateCell(cell);
    if (seen.has(cell.index)) throw new Error('Duplicate ice cell.');
    seen.add(cell.index);
    const previous = runs[runs.length - 1];
    if (!previous || cell.index !== previousIndex + 1) {
      runs.push({ startIndex: cell.index, values: [] });
    }
    runs[runs.length - 1]!.values.push(
      cell.thickness,
      cell.openness,
      cell.snow,
      cell.channelMemory,
      cell.channelAge,
      cell.owner,
      cell.floeId,
    );
    previousIndex = cell.index;
  }
  return runs;
};

export const unpackIceCellRuns = (
  runs: readonly PackedIceCellRun[],
): readonly ReplicatedIceCell[] => {
  const result: ReplicatedIceCell[] = [];
  const seen = new Set<number>();
  for (const run of runs) {
    if (
      !integer(run.startIndex, 0, 255) ||
      !Array.isArray(run.values) ||
      run.values.length === 0 ||
      run.values.length % 7 !== 0 ||
      run.values.length > 1_792
    ) throw new Error('Invalid packed ice cell run.');
    for (let offset = 0; offset < run.values.length; offset += 7) {
      const cell: ReplicatedIceCell = {
        index: run.startIndex + offset / 7,
        thickness: run.values[offset]!,
        openness: run.values[offset + 1]!,
        snow: run.values[offset + 2]!,
        channelMemory: run.values[offset + 3]!,
        channelAge: run.values[offset + 4]!,
        owner: run.values[offset + 5] as IceCellOwner,
        floeId: run.values[offset + 6]!,
      };
      validateCell(cell);
      if (seen.has(cell.index)) throw new Error('Overlapping packed ice cell run.');
      seen.add(cell.index);
      result.push(cell);
    }
  }
  return result.sort((a, b) => a.index - b.index);
};

const encodeDeltaValues = (change: Readonly<ReplicatedIceCellDelta>): number[] => {
  const values: number[] = [change.fieldMask];
  if (change.fieldMask & IceAuthorityField.Thickness) values.push(change.thickness!);
  if (change.fieldMask & IceAuthorityField.Openness) values.push(change.openness!);
  if (change.fieldMask & IceAuthorityField.Snow) values.push(change.snow!);
  if (change.fieldMask & IceAuthorityField.ChannelMemory) values.push(change.channelMemory!);
  if (change.fieldMask & IceAuthorityField.ChannelAge) values.push(change.channelAge!);
  if (change.fieldMask & IceAuthorityField.Owner) values.push(change.owner!);
  if (change.fieldMask & IceAuthorityField.FloeMembership) values.push(change.floeId!);
  return values;
};

export const packIceDeltaRuns = (
  changes: readonly ReplicatedIceCellDelta[],
): readonly PackedIceDeltaRun[] => {
  const sorted = [...changes].sort((a, b) => a.index - b.index);
  const runs: Array<{
    startIndex: number;
    cells: number[][];
    causeIds: Array<string | null>;
  }> = [];
  const seen = new Set<number>();
  let previousIndex = -2;
  for (const change of sorted) {
    validateDeltaCell(change);
    if (seen.has(change.index)) throw new Error('Duplicate ice delta cell.');
    seen.add(change.index);
    if (!runs.length || change.index !== previousIndex + 1) {
      runs.push({ startIndex: change.index, cells: [], causeIds: [] });
    }
    const run = runs[runs.length - 1]!;
    run.cells.push(encodeDeltaValues(change));
    run.causeIds.push(change.causeId ?? null);
    previousIndex = change.index;
  }
  return runs.map((run) => ({
    startIndex: run.startIndex,
    cells: run.cells,
    ...(run.causeIds.some(Boolean) ? { causeIds: run.causeIds } : {}),
  }));
};

export const unpackIceDeltaRuns = (
  runs: readonly PackedIceDeltaRun[],
): readonly ReplicatedIceCellDelta[] => {
  const changes: ReplicatedIceCellDelta[] = [];
  const seen = new Set<number>();
  for (const run of runs) {
    if (
      !integer(run.startIndex, 0, 255) ||
      !Array.isArray(run.cells) ||
      run.cells.length < 1 ||
      run.cells.length > 256 ||
      (run.causeIds !== undefined &&
        (!Array.isArray(run.causeIds) || run.causeIds.length !== run.cells.length))
    ) throw new Error('Invalid packed ice delta run.');
    for (let offset = 0; offset < run.cells.length; offset += 1) {
      const index = run.startIndex + offset;
      const values = run.cells[offset];
      if (!Array.isArray(values) || values.length < 2 || values.length > 8) {
        throw new Error('Invalid packed ice delta values.');
      }
      const mask = values[0];
      if (!integer(mask, 1, IceAuthorityField.All) || (mask & ~IceAuthorityField.All) !== 0) {
        throw new Error('Invalid ice delta field mask.');
      }
      let cursor = 1;
      const take = (): number => values[cursor++]!;
      const change: ReplicatedIceCellDelta = {
        index,
        fieldMask: mask,
        ...(mask & IceAuthorityField.Thickness ? { thickness: take() } : {}),
        ...(mask & IceAuthorityField.Openness ? { openness: take() } : {}),
        ...(mask & IceAuthorityField.Snow ? { snow: take() } : {}),
        ...(mask & IceAuthorityField.ChannelMemory ? { channelMemory: take() } : {}),
        ...(mask & IceAuthorityField.ChannelAge ? { channelAge: take() } : {}),
        ...(mask & IceAuthorityField.Owner ? { owner: take() as IceCellOwner } : {}),
        ...(mask & IceAuthorityField.FloeMembership ? { floeId: take() } : {}),
        ...(run.causeIds?.[offset] ? { causeId: run.causeIds[offset]! } : {}),
      };
      if (cursor !== values.length) throw new Error('Ice delta field count mismatch.');
      validateDeltaCell(change);
      if (seen.has(index)) throw new Error('Overlapping packed ice delta run.');
      seen.add(index);
      changes.push(change);
    }
  }
  return changes.sort((a, b) => a.index - b.index);
};

const validateCell = (cell: Readonly<ReplicatedIceCell>): void => {
  if (
    !integer(cell.index, 0, 255) ||
    !integer(cell.thickness, 0, 255) ||
    !integer(cell.openness, 0, 255) ||
    !integer(cell.snow, 0, 255) ||
    !integer(cell.channelMemory, 0, 255) ||
    !integer(cell.channelAge, 0, 65_535) ||
    !validOwner(cell.owner) ||
    !integer(cell.floeId, -1, 2_147_483_647)
  ) throw new Error('Invalid replicated ice cell.');
};

const validateDeltaCell = (cell: Readonly<ReplicatedIceCellDelta>): void => {
  if (!integer(cell.index, 0, 255)) throw new Error('Invalid ice delta index.');
  const mask = cell.fieldMask;
  if (!integer(mask, 1, IceAuthorityField.All) || (mask & ~IceAuthorityField.All) !== 0) {
    throw new Error('Invalid ice delta mask.');
  }
  const byteField = (flag: IceAuthorityField, value: unknown): boolean =>
    !(mask & flag) || integer(value, 0, 255);
  if (
    !byteField(IceAuthorityField.Thickness, cell.thickness) ||
    !byteField(IceAuthorityField.Openness, cell.openness) ||
    !byteField(IceAuthorityField.Snow, cell.snow) ||
    !byteField(IceAuthorityField.ChannelMemory, cell.channelMemory) ||
    (Boolean(mask & IceAuthorityField.ChannelAge) &&
      !integer(cell.channelAge, 0, 65_535)) ||
    (Boolean(mask & IceAuthorityField.Owner) && !validOwner(cell.owner)) ||
    (Boolean(mask & IceAuthorityField.FloeMembership) &&
      !integer(cell.floeId, -1, 2_147_483_647)) ||
    (cell.causeId !== undefined && !text(cell.causeId, 160))
  ) throw new Error('Invalid ice delta field value.');
};

export const replicatedIceBaselineChunk = (
  chunk: Readonly<IceAuthorityChunkBaseline>,
  columns: number,
): ReplicatedIceChunkBaseline => {
  const cells = chunk.changes.map((cell): ReplicatedIceCell => ({
    ...cell,
    index: localIndex(cell.index, columns),
  }));
  return {
    chunkX: chunk.chunkX,
    chunkZ: chunk.chunkZ,
    revision: chunk.revision,
    topologyRevision: chunk.topologyRevision,
    checksum: iceChunkChecksum(
      chunk.chunkX,
      chunk.chunkZ,
      chunk.revision,
      chunk.topologyRevision,
      cells,
    ),
    runs: packIceCellRuns(cells),
  };
};

export const replicatedIceDeltaChunk = (
  delta: Readonly<IceAuthorityChunkDelta>,
  full: Readonly<IceAuthorityChunkBaseline>,
  columns: number,
): ReplicatedIceChunkDelta => {
  const changes = delta.changes.map((change): ReplicatedIceCellDelta => ({
    ...change,
    index: localIndex(change.index, columns),
  }));
  const fullCells = full.changes.map((cell): ReplicatedIceCell => ({
    ...cell,
    index: localIndex(cell.index, columns),
  }));
  return {
    chunkX: delta.chunkX,
    chunkZ: delta.chunkZ,
    baseRevision: delta.baseRevision,
    revision: delta.revision,
    baseTopologyRevision: delta.baseTopologyRevision,
    topologyRevision: delta.topologyRevision,
    checksum: iceChunkChecksum(
      delta.chunkX,
      delta.chunkZ,
      delta.revision,
      delta.topologyRevision,
      fullCells,
    ),
    runs: packIceDeltaRuns(changes),
  };
};

const validateChunkBaseline = (input: unknown): ReplicatedIceChunkBaseline | undefined => {
  if (
    !isRecord(input) ||
    !integer(input.chunkX, 0, 65_535) ||
    !integer(input.chunkZ, 0, 65_535) ||
    !integer(input.revision, 0, Number.MAX_SAFE_INTEGER) ||
    !integer(input.topologyRevision, 0, Number.MAX_SAFE_INTEGER) ||
    !text(input.checksum, 32) ||
    !Array.isArray(input.runs) ||
    input.runs.length > 256
  ) return undefined;
  try {
    const runs = input.runs.map((run) => {
      if (!isRecord(run) || !Array.isArray(run.values)) throw new Error();
      return { startIndex: run.startIndex as number, values: [...run.values] as number[] };
    });
    const cells = unpackIceCellRuns(runs);
    const chunk = {
      chunkX: input.chunkX,
      chunkZ: input.chunkZ,
      revision: revision(input.revision),
      topologyRevision: revision(input.topologyRevision),
      checksum: input.checksum,
      runs,
    };
    if (iceChunkChecksum(
      chunk.chunkX,
      chunk.chunkZ,
      chunk.revision,
      chunk.topologyRevision,
      cells,
    ) !== chunk.checksum) return undefined;
    return chunk;
  } catch {
    return undefined;
  }
};

const validateChunkDelta = (input: unknown): ReplicatedIceChunkDelta | undefined => {
  if (
    !isRecord(input) ||
    !integer(input.chunkX, 0, 65_535) ||
    !integer(input.chunkZ, 0, 65_535) ||
    !integer(input.baseRevision, 0, Number.MAX_SAFE_INTEGER) ||
    !integer(input.revision, 0, Number.MAX_SAFE_INTEGER) ||
    !integer(input.baseTopologyRevision, 0, Number.MAX_SAFE_INTEGER) ||
    !integer(input.topologyRevision, 0, Number.MAX_SAFE_INTEGER) ||
    input.revision < input.baseRevision ||
    input.topologyRevision < input.baseTopologyRevision ||
    !text(input.checksum, 32) ||
    !Array.isArray(input.runs) ||
    input.runs.length > 256
  ) return undefined;
  try {
    const runs = input.runs.map((run) => {
      if (!isRecord(run) || !Array.isArray(run.cells)) throw new Error();
      return {
        startIndex: run.startIndex as number,
        cells: run.cells.map((cell) => {
          if (!Array.isArray(cell)) throw new Error();
          return [...cell] as number[];
        }),
        ...(run.causeIds !== undefined
          ? { causeIds: [...(run.causeIds as Array<string | null>)] }
          : {}),
      };
    });
    unpackIceDeltaRuns(runs);
    return {
      chunkX: input.chunkX,
      chunkZ: input.chunkZ,
      baseRevision: revision(input.baseRevision),
      revision: revision(input.revision),
      baseTopologyRevision: revision(input.baseTopologyRevision),
      topologyRevision: revision(input.topologyRevision),
      checksum: input.checksum,
      runs,
    };
  } catch {
    return undefined;
  }
};

export const validateIceBaselinePartPayload = (
  input: unknown,
): IceBaselinePartPayload | undefined => {
  if (
    !isRecord(input) || input.version !== 1 || input.kind !== 'ICE_BASELINE_PART' ||
    (input.scope !== 'FULL' && input.scope !== 'CHUNK_RESYNC') ||
    !text(input.baselineId, 160) ||
    input.formatVersion !== ICE_AUTHORITY_FORMAT_VERSION ||
    !text(input.worldDatasetHash, 256) ||
    !integer(input.columns, 1, 16_384) || !integer(input.rows, 1, 16_384) ||
    !finite(input.cellSize, 0.01, 10_000) ||
    !text(input.transferId, 160) ||
    !integer(input.partIndex, 0, 4_095) || !integer(input.partCount, 1, 4_096) ||
    input.partIndex >= input.partCount ||
    !integer(input.serverTick, 0, Number.MAX_SAFE_INTEGER) ||
    !Array.isArray(input.chunks) || input.chunks.length > 16
  ) return undefined;
  const chunks = input.chunks.map(validateChunkBaseline);
  if (chunks.some((chunk) => !chunk)) return undefined;
  return {
    version: 1,
    kind: 'ICE_BASELINE_PART',
    scope: input.scope,
    baselineId: input.baselineId,
    formatVersion: ICE_AUTHORITY_FORMAT_VERSION,
    worldDatasetHash: input.worldDatasetHash,
    columns: input.columns,
    rows: input.rows,
    cellSize: input.cellSize,
    transferId: input.transferId,
    partIndex: input.partIndex,
    partCount: input.partCount,
    serverTick: serverTick(input.serverTick),
    chunks: chunks as ReplicatedIceChunkBaseline[],
  };
};

export const validateIceDeltaPayload = (input: unknown): IceDeltaPayload | undefined => {
  if (
    !isRecord(input) || input.version !== 1 || input.kind !== 'ICE_CHUNK_DELTA' ||
    !integer(input.deltaSequence, 1, Number.MAX_SAFE_INTEGER) ||
    !integer(input.serverTick, 0, Number.MAX_SAFE_INTEGER) ||
    !Array.isArray(input.chunks) || input.chunks.length > 64
  ) return undefined;
  const chunks = input.chunks.map(validateChunkDelta);
  if (chunks.some((chunk) => !chunk)) return undefined;
  return {
    version: 1,
    kind: 'ICE_CHUNK_DELTA',
    deltaSequence: input.deltaSequence,
    serverTick: serverTick(input.serverTick),
    chunks: chunks as ReplicatedIceChunkDelta[],
  };
};

export const validateIceChunkResyncRequestPayload = (
  input: unknown,
): IceChunkResyncRequestPayload | undefined => {
  if (
    !isRecord(input) || input.version !== 1 ||
    !integer(input.chunkX, 0, 65_535) || !integer(input.chunkZ, 0, 65_535) ||
    !integer(input.observedRevision, 0, Number.MAX_SAFE_INTEGER) ||
    !integer(input.observedTopologyRevision, 0, Number.MAX_SAFE_INTEGER)
  ) return undefined;
  return {
    version: 1,
    chunkX: input.chunkX,
    chunkZ: input.chunkZ,
    observedRevision: revision(input.observedRevision),
    observedTopologyRevision: revision(input.observedTopologyRevision),
  };
};

const validateFloe = (input: unknown): IceAuthorityFloeState | undefined => {
  if (
    !isRecord(input) || !integer(input.id, 1, 2_147_483_647) ||
    !Array.isArray(input.cells) || input.cells.length < 1 || input.cells.length > 16_384 ||
    !input.cells.every((cell) => integer(cell, 0, 268_435_455)) ||
    new Set(input.cells).size !== input.cells.length ||
    ![input.centerX, input.centerZ, input.offsetX, input.offsetZ,
      input.velocityX, input.velocityZ, input.yaw, input.angularVelocity,
      input.separationCooldown, input.detachedAgeSeconds,
      input.contactBondSeconds, input.thermalAnchorSeconds]
      .every((value) => finite(value)) ||
    !finite(input.pressure, 0, 1) || !finite(input.seed, 0, 1) ||
    !integer(input.movementRevision, 0, Number.MAX_SAFE_INTEGER)
  ) return undefined;
  return {
    id: input.id,
    cells: [...input.cells] as number[],
    centerX: input.centerX as number,
    centerZ: input.centerZ as number,
    offsetX: input.offsetX as number,
    offsetZ: input.offsetZ as number,
    velocityX: input.velocityX as number,
    velocityZ: input.velocityZ as number,
    yaw: input.yaw as number,
    angularVelocity: input.angularVelocity as number,
    pressure: input.pressure as number,
    separationCooldown: input.separationCooldown as number,
    detachedAgeSeconds: input.detachedAgeSeconds as number,
    contactBondSeconds: input.contactBondSeconds as number,
    thermalAnchorSeconds: input.thermalAnchorSeconds as number,
    seed: input.seed as number,
    movementRevision: revision(input.movementRevision),
  };
};

export const validateIceFloeBaselinePayload = (
  input: unknown,
): IceFloeBaselinePayload | undefined => {
  if (
    !isRecord(input) || input.version !== 1 || input.kind !== 'ICE_FLOE_BASELINE' ||
    !integer(input.baselineSequence, 1, Number.MAX_SAFE_INTEGER) ||
    !integer(input.serverTick, 0, Number.MAX_SAFE_INTEGER) ||
    !Array.isArray(input.floes) || input.floes.length > 4_096
  ) return undefined;
  const floes = input.floes.map(validateFloe);
  if (floes.some((floe) => !floe) || new Set(floes.map((floe) => floe!.id)).size !== floes.length) {
    return undefined;
  }
  return {
    version: 1,
    kind: 'ICE_FLOE_BASELINE',
    baselineSequence: input.baselineSequence,
    serverTick: serverTick(input.serverTick),
    floes: floes as IceAuthorityFloeState[],
  };
};

export const validateIceFloeLifecyclePayload = (
  input: unknown,
): IceFloeLifecyclePayload | undefined => {
  if (
    !isRecord(input) || input.version !== 1 || input.kind !== 'ICE_FLOE_LIFECYCLE' ||
    !integer(input.lifecycleSequence, 1, Number.MAX_SAFE_INTEGER) ||
    !integer(input.serverTick, 0, Number.MAX_SAFE_INTEGER) ||
    !Array.isArray(input.events) || input.events.length > 256
  ) return undefined;
  const events: IceFloeLifecycleEvent[] = [];
  for (const raw of input.events) {
    if (
      !isRecord(raw) || !text(raw.eventId, 160) ||
      !['CREATE', 'SPLIT', 'MERGE', 'REATTACH', 'REMOVE'].includes(raw.kind as string) ||
      !integer(raw.topologyRevision, 0, Number.MAX_SAFE_INTEGER) ||
      !integer(raw.serverTick, 0, Number.MAX_SAFE_INTEGER) ||
      !integer(raw.floeId, 1, 2_147_483_647) ||
      !Array.isArray(raw.sourceFloeIds) || raw.sourceFloeIds.length > 256 ||
      !raw.sourceFloeIds.every((id) => integer(id, 1, 2_147_483_647)) ||
      (raw.causeId !== undefined && !text(raw.causeId, 160))
    ) return undefined;
    const parsedFloe = raw.floe === undefined ? undefined : validateFloe(raw.floe);
    if (raw.floe !== undefined && !parsedFloe) return undefined;
    if ((raw.kind === 'REATTACH' || raw.kind === 'REMOVE') && parsedFloe) return undefined;
    if (raw.kind !== 'REATTACH' && raw.kind !== 'REMOVE' && !parsedFloe) return undefined;
    events.push({
      eventId: raw.eventId,
      kind: raw.kind as IceFloeLifecycleEvent['kind'],
      topologyRevision: revision(raw.topologyRevision),
      serverTick: serverTick(raw.serverTick),
      floeId: raw.floeId,
      sourceFloeIds: [...raw.sourceFloeIds] as number[],
      floe: parsedFloe,
      causeId: raw.causeId as string | undefined,
    });
  }
  return {
    version: 1,
    kind: 'ICE_FLOE_LIFECYCLE',
    lifecycleSequence: input.lifecycleSequence,
    serverTick: serverTick(input.serverTick),
    events,
  };
};

export const validateIceFloeMovementPayload = (
  input: unknown,
): IceFloeMovementPayload | undefined => {
  if (
    !isRecord(input) || input.version !== 1 || input.kind !== 'ICE_FLOE_MOVEMENT' ||
    !integer(input.snapshotSequence, 1, Number.MAX_SAFE_INTEGER) ||
    !integer(input.serverTick, 0, Number.MAX_SAFE_INTEGER) ||
    !Array.isArray(input.floes) || input.floes.length > 4_096
  ) return undefined;
  const floes: IceFloeMovementSnapshot[] = [];
  for (const raw of input.floes) {
    if (
      !isRecord(raw) || !integer(raw.floeId, 1, 2_147_483_647) ||
      !integer(raw.movementRevision, 0, Number.MAX_SAFE_INTEGER) ||
      !integer(raw.serverTick, 0, Number.MAX_SAFE_INTEGER) ||
      ![raw.centerX, raw.centerZ, raw.offsetX, raw.offsetZ, raw.velocityX,
        raw.velocityZ, raw.yaw, raw.angularVelocity].every((value) => finite(value)) ||
      !finite(raw.pressure, 0, 1)
    ) return undefined;
    floes.push({
      floeId: raw.floeId,
      movementRevision: revision(raw.movementRevision),
      serverTick: serverTick(raw.serverTick),
      centerX: raw.centerX as number,
      centerZ: raw.centerZ as number,
      offsetX: raw.offsetX as number,
      offsetZ: raw.offsetZ as number,
      velocityX: raw.velocityX as number,
      velocityZ: raw.velocityZ as number,
      yaw: raw.yaw as number,
      angularVelocity: raw.angularVelocity as number,
      pressure: raw.pressure as number,
    });
  }
  return {
    version: 1,
    kind: 'ICE_FLOE_MOVEMENT',
    snapshotSequence: input.snapshotSequence,
    serverTick: serverTick(input.serverTick),
    floes,
  };
};

export const validateIceFractureVisualPayload = (
  input: unknown,
): IceFractureVisualPayload | undefined => {
  if (
    !isRecord(input) || input.version !== 1 || input.kind !== 'ICE_FRACTURE_VISUAL' ||
    !integer(input.serverTick, 0, Number.MAX_SAFE_INTEGER) ||
    !Array.isArray(input.events) || input.events.length > 128
  ) return undefined;
  const events: IceFractureVisualEvent[] = [];
  for (const raw of input.events) {
    if (!isRecord(raw) || !text(raw.eventId, 160) || !isRecord(raw.worldPosition) ||
      !isRecord(raw.worldPosition.chunk) || !isRecord(raw.worldPosition.local) ||
      !integer(raw.worldPosition.chunk.x, -1_000_000, 1_000_000) ||
      !integer(raw.worldPosition.chunk.z, -1_000_000, 1_000_000) ||
      !finite(raw.worldPosition.local.xMetres) ||
      !finite(raw.worldPosition.local.yMetres) ||
      !finite(raw.worldPosition.local.zMetres) ||
      !finite(raw.magnitude, 0, 1_000_000) || !finite(raw.direction) ||
      !integer(raw.seed, 0, 0xffff_ffff) ||
      (raw.causedByEntityId !== undefined && !text(raw.causedByEntityId, 160))) {
      return undefined;
    }
    events.push(raw as unknown as IceFractureVisualEvent);
  }
  return {
    version: 1,
    kind: 'ICE_FRACTURE_VISUAL',
    serverTick: serverTick(input.serverTick),
    events,
  };
};
