const rocks = (
  prefix: string,
  category: 'ROCKS_SMALL' | 'ROCKS_LARGE',
  count: number,
  baseScale: number,
  displayPrefix: string,
): WorldAssetRecipe[] => Array.from({ length: count }, (_, index) => {
  const variant = index + 1;
  const id = `${prefix}_${String(variant).padStart(2, '0')}`;
  const width = baseScale * (0.82 + variant * 0.09);
  const depth = baseScale * (0.72 + ((variant * 3) % 5) * 0.08);
  const height = baseScale * (0.42 + ((variant * 2) % 4) * 0.1);
  return {
    id,
    displayName: `${displayPrefix} ${variant}`,
    icon: variant % 2 === 0 ? '⬟' : '◆',
    category,
    suggestedModelUrl: `assets/world/props/models/${id.toLowerCase().replaceAll('_', '-')}.glb`,
    defaultCollision: { kind: 'BOX', width: width * 1.55, height: height * 1.7, depth: depth * 1.55, offsetY: height * 0.75 },
    parts: [
      part(
        variant >= 4 ? 'DODECAHEDRON_1' : 'DODECAHEDRON_0',
        variant % 3 === 0 ? 'STONE_WARM' : variant % 2 === 0 ? 'STONE_LIGHT' : 'STONE_MID',
        [0, height * 0.65, 0],
        [width, height, depth],
        [variant * 7, variant * 31, variant * 4],
      ),
    ],
  };
});

