import type { GlobalPosition } from '../../world/GlobalPosition';
import { isGlobalPositionInPartition } from '../../world/GlobalPosition';
import { ICEAWAY_TARGET_WORLD_PARTITION } from '../../world/WorldPartitionTypes';
import { serverTick, type ServerTick } from '../core/NetworkPrimitives';

export const INFRASTRUCTURE_REPLICATION_FORMAT_VERSION = 1;
export const MAX_INFRASTRUCTURE_SITES = 128;
export const MAX_INFRASTRUCTURE_MACHINES_PER_SITE = 1_024;
export const MAX_INFRASTRUCTURE_SERVICES_PER_SITE = 1_024;
export const MAX_INFRASTRUCTURE_RECORDS_PER_MESSAGE = 64;

export type InfrastructureMachineOperation =
  | 'generator'
  | 'winch'
  | 'resource-drill'
  | 'deck-crane'
  | 'heating-cable'
  | 'cozium-emitter';

export type InfrastructureMachineStatus =
  | 'DISABLED'
  | 'GENERATING'
  | 'POWERED'
  | 'BROWNOUT'
  | 'UNPOWERED';

export type InfrastructureServiceKind =
  | 'FISHING'
  | 'RESOURCE_EXTRACTION'
  | 'CARGO_HANDLING'
  | 'SNOW_HEATING'
  | 'SNOW_COZIUM';

export interface InfrastructurePowerRuntimeSnapshot {
  readonly networkId: string;
  readonly generation: number;
  readonly demand: number;
  readonly allocated: number;
  readonly curtailed: number;
  readonly coverage: number;
}

export interface InfrastructureMachineRuntimeSnapshot {
  readonly siteId: string;
  readonly pieceId: string;
  readonly moduleId: string;
  readonly operation: InfrastructureMachineOperation;
  readonly runtimeRevision: number;
  readonly configuredEnabled: boolean;
  readonly configuredControl: number;
  readonly status: InfrastructureMachineStatus;
  readonly powerDemand: number;
  readonly powerGeneration: number;
  readonly allocatedPower: number;
  readonly effectiveControl: number;
  readonly serviceOutput: number;
}

export interface InfrastructureServiceRuntimeSnapshot {
  readonly siteId: string;
  readonly serviceId: string;
  readonly sourcePieceId: string;
  readonly kind: InfrastructureServiceKind;
  readonly runtimeRevision: number;
  readonly active: boolean;
  readonly capacity: number;
  readonly worldPosition: GlobalPosition;
  readonly heading: number;
  readonly radiusMetres: number;
}

export interface InfrastructureSiteRuntimeManifest {
  readonly siteId: string;
  readonly revision: number;
  readonly blueprintRevision: number;
  readonly power: InfrastructurePowerRuntimeSnapshot;
  readonly machineCount: number;
  readonly serviceCount: number;
}

export interface InfrastructureSiteRuntimeSnapshot
  extends InfrastructureSiteRuntimeManifest {
  readonly machines: readonly InfrastructureMachineRuntimeSnapshot[];
  readonly services: readonly InfrastructureServiceRuntimeSnapshot[];
}

export interface InfrastructureStateBaselinePartPayload {
  readonly version: 1;
  readonly kind: 'INFRASTRUCTURE_STATE_BASELINE';
  readonly formatVersion: number;
  readonly worldDatasetHash: string;
  readonly transferId: string;
  readonly partIndex: number;
  readonly partCount: number;
  readonly serverTick: ServerTick;
  readonly revision: number;
  readonly sites: readonly InfrastructureSiteRuntimeManifest[];
  readonly totalMachineCount: number;
  readonly machineOffset: number;
  readonly machines: readonly InfrastructureMachineRuntimeSnapshot[];
  readonly totalServiceCount: number;
  readonly serviceOffset: number;
  readonly services: readonly InfrastructureServiceRuntimeSnapshot[];
}

export interface InfrastructureStateDeltaPartPayload {
  readonly version: 1;
  readonly kind: 'INFRASTRUCTURE_STATE_DELTA';
  readonly transferId: string;
  readonly partIndex: number;
  readonly partCount: number;
  readonly baseRevision: number;
  readonly revision: number;
  readonly serverTick: ServerTick;
  readonly site: InfrastructureSiteRuntimeManifest;
  readonly machineOffset: number;
  readonly machines: readonly InfrastructureMachineRuntimeSnapshot[];
  readonly serviceOffset: number;
  readonly services: readonly InfrastructureServiceRuntimeSnapshot[];
}

export interface InfrastructureStateResyncRequestPayload {
  readonly version: 1;
  readonly kind: 'INFRASTRUCTURE_STATE_RESYNC_REQUEST';
  readonly observedRevision: number;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const boundedString = (value: unknown, maximum = 160): value is string =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maximum;
const natural = (value: unknown): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
const finite = (value: unknown, maximum = 1_000_000): value is number =>
  typeof value === 'number' && Number.isFinite(value) && Math.abs(value) <= maximum;
const unit = (value: unknown): value is number =>
  finite(value, 1) && value >= 0 && value <= 1;

const OPERATIONS = new Set<InfrastructureMachineOperation>([
  'generator',
  'winch',
  'resource-drill',
  'deck-crane',
  'heating-cable',
  'cozium-emitter',
]);
const STATUSES = new Set<InfrastructureMachineStatus>([
  'DISABLED',
  'GENERATING',
  'POWERED',
  'BROWNOUT',
  'UNPOWERED',
]);
const SERVICES = new Set<InfrastructureServiceKind>([
  'FISHING',
  'RESOURCE_EXTRACTION',
  'CARGO_HANDLING',
  'SNOW_HEATING',
  'SNOW_COZIUM',
]);

const clonePosition = (position: Readonly<GlobalPosition>): GlobalPosition => ({
  chunk: { ...position.chunk },
  local: { ...position.local },
});

export const cloneInfrastructureMachine = (
  machine: Readonly<InfrastructureMachineRuntimeSnapshot>,
): InfrastructureMachineRuntimeSnapshot => ({ ...machine });

export const cloneInfrastructureService = (
  service: Readonly<InfrastructureServiceRuntimeSnapshot>,
): InfrastructureServiceRuntimeSnapshot => ({
  ...service,
  worldPosition: clonePosition(service.worldPosition),
});

export const cloneInfrastructureManifest = (
  site: Readonly<InfrastructureSiteRuntimeManifest>,
): InfrastructureSiteRuntimeManifest => ({
  ...site,
  power: { ...site.power },
});

export const cloneInfrastructureSite = (
  site: Readonly<InfrastructureSiteRuntimeSnapshot>,
): InfrastructureSiteRuntimeSnapshot => ({
  ...cloneInfrastructureManifest(site),
  machines: site.machines.map(cloneInfrastructureMachine),
  services: site.services.map(cloneInfrastructureService),
});

export const sanitizeInfrastructureMachine = (
  input: unknown,
): InfrastructureMachineRuntimeSnapshot | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.siteId) ||
    !boundedString(input.pieceId) ||
    !boundedString(input.moduleId) ||
    typeof input.operation !== 'string' ||
    !OPERATIONS.has(input.operation as InfrastructureMachineOperation) ||
    !natural(input.runtimeRevision) ||
    typeof input.configuredEnabled !== 'boolean' ||
    !unit(input.configuredControl) ||
    typeof input.status !== 'string' ||
    !STATUSES.has(input.status as InfrastructureMachineStatus) ||
    !finite(input.powerDemand) || input.powerDemand < 0 ||
    !finite(input.powerGeneration) || input.powerGeneration < 0 ||
    !finite(input.allocatedPower) || input.allocatedPower < 0 ||
    !unit(input.effectiveControl) ||
    !finite(input.serviceOutput) || input.serviceOutput < 0
  ) return undefined;
  return {
    siteId: input.siteId,
    pieceId: input.pieceId,
    moduleId: input.moduleId,
    operation: input.operation as InfrastructureMachineOperation,
    runtimeRevision: input.runtimeRevision,
    configuredEnabled: input.configuredEnabled,
    configuredControl: input.configuredControl,
    status: input.status as InfrastructureMachineStatus,
    powerDemand: input.powerDemand,
    powerGeneration: input.powerGeneration,
    allocatedPower: input.allocatedPower,
    effectiveControl: input.effectiveControl,
    serviceOutput: input.serviceOutput,
  };
};

export const sanitizeInfrastructureService = (
  input: unknown,
): InfrastructureServiceRuntimeSnapshot | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.siteId) ||
    !boundedString(input.serviceId) ||
    !boundedString(input.sourcePieceId) ||
    typeof input.kind !== 'string' ||
    !SERVICES.has(input.kind as InfrastructureServiceKind) ||
    !natural(input.runtimeRevision) ||
    typeof input.active !== 'boolean' ||
    !finite(input.capacity) || input.capacity < 0 ||
    !isRecord(input.worldPosition) ||
    !isGlobalPositionInPartition(
      ICEAWAY_TARGET_WORLD_PARTITION,
      input.worldPosition as unknown as GlobalPosition,
    ) ||
    !finite(input.heading, Math.PI * 2) ||
    !finite(input.radiusMetres, 1_000) ||
    input.radiusMetres < 0
  ) return undefined;
  return {
    siteId: input.siteId,
    serviceId: input.serviceId,
    sourcePieceId: input.sourcePieceId,
    kind: input.kind as InfrastructureServiceKind,
    runtimeRevision: input.runtimeRevision,
    active: input.active,
    capacity: input.capacity,
    worldPosition: clonePosition(input.worldPosition as unknown as GlobalPosition),
    heading: input.heading,
    radiusMetres: input.radiusMetres,
  };
};

const sanitizePower = (
  input: unknown,
): InfrastructurePowerRuntimeSnapshot | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.networkId) ||
    !finite(input.generation) || input.generation < 0 ||
    !finite(input.demand) || input.demand < 0 ||
    !finite(input.allocated) || input.allocated < 0 ||
    !finite(input.curtailed) || input.curtailed < 0 ||
    !unit(input.coverage)
  ) return undefined;
  return {
    networkId: input.networkId,
    generation: input.generation,
    demand: input.demand,
    allocated: input.allocated,
    curtailed: input.curtailed,
    coverage: input.coverage,
  };
};

export const sanitizeInfrastructureManifest = (
  input: unknown,
): InfrastructureSiteRuntimeManifest | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.siteId) ||
    !natural(input.revision) ||
    !natural(input.blueprintRevision) ||
    !natural(input.machineCount) ||
    input.machineCount > MAX_INFRASTRUCTURE_MACHINES_PER_SITE ||
    !natural(input.serviceCount) ||
    input.serviceCount > MAX_INFRASTRUCTURE_SERVICES_PER_SITE
  ) return undefined;
  const power = sanitizePower(input.power);
  return power ? {
    siteId: input.siteId,
    revision: input.revision,
    blueprintRevision: input.blueprintRevision,
    power,
    machineCount: input.machineCount,
    serviceCount: input.serviceCount,
  } : undefined;
};

const sanitizeMachineArray = (
  input: unknown,
): InfrastructureMachineRuntimeSnapshot[] | undefined => {
  if (!Array.isArray(input) || input.length > MAX_INFRASTRUCTURE_RECORDS_PER_MESSAGE) {
    return undefined;
  }
  const result: InfrastructureMachineRuntimeSnapshot[] = [];
  const ids = new Set<string>();
  for (const raw of input) {
    const item = sanitizeInfrastructureMachine(raw);
    if (!item || ids.has(`${item.siteId}\u0000${item.pieceId}`)) return undefined;
    ids.add(`${item.siteId}\u0000${item.pieceId}`);
    result.push(item);
  }
  return result;
};

const sanitizeServiceArray = (
  input: unknown,
): InfrastructureServiceRuntimeSnapshot[] | undefined => {
  if (!Array.isArray(input) || input.length > MAX_INFRASTRUCTURE_RECORDS_PER_MESSAGE) {
    return undefined;
  }
  const result: InfrastructureServiceRuntimeSnapshot[] = [];
  const ids = new Set<string>();
  for (const raw of input) {
    const item = sanitizeInfrastructureService(raw);
    if (!item || ids.has(item.serviceId)) return undefined;
    ids.add(item.serviceId);
    result.push(item);
  }
  return result;
};

export const validateInfrastructureSiteRuntime = (
  site: Readonly<InfrastructureSiteRuntimeSnapshot>,
): string | undefined => {
  if (
    site.machines.length !== site.machineCount ||
    site.services.length !== site.serviceCount
  ) return 'COUNT_MISMATCH';
  if (site.machines.some((machine) => machine.siteId !== site.siteId)) {
    return 'FOREIGN_MACHINE';
  }
  if (site.services.some((service) => service.siteId !== site.siteId)) {
    return 'FOREIGN_SERVICE';
  }
  if (new Set(site.machines.map((machine) => machine.pieceId)).size !==
    site.machines.length) return 'DUPLICATE_MACHINE';
  if (new Set(site.services.map((service) => service.serviceId)).size !==
    site.services.length) return 'DUPLICATE_SERVICE';
  const machineIds = new Set(site.machines.map((machine) => machine.pieceId));
  if (site.services.some((service) => !machineIds.has(service.sourcePieceId))) {
    return 'SERVICE_SOURCE_MISSING';
  }
  if (
    site.machines.some((machine) => machine.runtimeRevision > site.revision) ||
    site.services.some((service) => service.runtimeRevision > site.revision)
  ) return 'RECORD_REVISION_AHEAD';
  const close = (left: number, right: number): boolean =>
    Math.abs(left - right) <= 0.00011;
  const generation = site.machines.reduce(
    (total, machine) => total + machine.powerGeneration,
    0,
  );
  const demand = site.machines.reduce(
    (total, machine) => total + machine.powerDemand,
    0,
  );
  const allocated = site.machines.reduce(
    (total, machine) => total + machine.allocatedPower,
    0,
  );
  if (
    !close(site.power.generation, generation) ||
    !close(site.power.demand, demand) ||
    !close(site.power.allocated, allocated) ||
    allocated > generation + 0.00011 ||
    allocated > demand + 0.00011 ||
    !close(site.power.curtailed, Math.max(0, generation - allocated)) ||
    !close(
      site.power.coverage,
      demand <= 0 ? 1 : Math.max(0, Math.min(1, allocated / demand)),
    )
  ) return 'POWER_LEDGER_MISMATCH';
  for (const machine of site.machines) {
    if (
      machine.allocatedPower > machine.powerDemand + 0.00011 ||
      machine.effectiveControl > machine.configuredControl + 0.00011
    ) return 'MACHINE_POWER_OVERALLOCATION';
    if (
      (machine.status === 'DISABLED' || machine.status === 'UNPOWERED') &&
      (!close(machine.allocatedPower, 0) ||
        !close(machine.effectiveControl, 0) ||
        !close(machine.serviceOutput, 0))
    ) return 'INACTIVE_MACHINE_OUTPUT';
    if (
      machine.status === 'BROWNOUT' &&
      (machine.allocatedPower <= 0 ||
        machine.allocatedPower >= machine.powerDemand - 0.00011)
    ) return 'INVALID_BROWNOUT';
    if (
      machine.status === 'GENERATING' &&
      (machine.powerGeneration <= 0 || machine.powerDemand > 0)
    ) return 'INVALID_GENERATOR_STATE';
  }
  const serviceBySource = new Map<string, InfrastructureServiceRuntimeSnapshot>();
  for (const service of site.services) {
    if (serviceBySource.has(service.sourcePieceId)) {
      return 'DUPLICATE_MACHINE_SERVICE';
    }
    serviceBySource.set(service.sourcePieceId, service);
  }
  const expectedServiceKind = (
    operation: InfrastructureMachineOperation,
  ): InfrastructureServiceKind | undefined => {
    switch (operation) {
      case 'winch':
        return 'FISHING';
      case 'resource-drill':
        return 'RESOURCE_EXTRACTION';
      case 'deck-crane':
        return 'CARGO_HANDLING';
      case 'heating-cable':
        return 'SNOW_HEATING';
      case 'cozium-emitter':
        return 'SNOW_COZIUM';
      case 'generator':
        return undefined;
    }
  };
  for (const machine of site.machines) {
    const expectedKind = expectedServiceKind(machine.operation);
    const service = serviceBySource.get(machine.pieceId);
    if (!expectedKind && service) return 'GENERATOR_HAS_SERVICE';
    if (expectedKind && !service) return 'MACHINE_SERVICE_MISSING';
    if (
      service &&
      (service.kind !== expectedKind ||
        !close(service.capacity, machine.serviceOutput) ||
        service.active !== (machine.serviceOutput > 0))
    ) return 'MACHINE_SERVICE_MISMATCH';
  }
  return undefined;
};

export const validateInfrastructureStateBaselinePartPayload = (
  input: unknown,
): InfrastructureStateBaselinePartPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'INFRASTRUCTURE_STATE_BASELINE' ||
    input.formatVersion !== INFRASTRUCTURE_REPLICATION_FORMAT_VERSION ||
    !boundedString(input.worldDatasetHash, 256) ||
    !boundedString(input.transferId) ||
    !natural(input.partIndex) ||
    !natural(input.partCount) || input.partCount < 1 || input.partCount > 4_096 ||
    input.partIndex >= input.partCount ||
    !natural(input.serverTick) ||
    !natural(input.revision) ||
    !Array.isArray(input.sites) || input.sites.length > MAX_INFRASTRUCTURE_SITES ||
    !natural(input.totalMachineCount) ||
    input.totalMachineCount > MAX_INFRASTRUCTURE_SITES * MAX_INFRASTRUCTURE_MACHINES_PER_SITE ||
    !natural(input.machineOffset) ||
    !natural(input.totalServiceCount) ||
    input.totalServiceCount > MAX_INFRASTRUCTURE_SITES * MAX_INFRASTRUCTURE_SERVICES_PER_SITE ||
    !natural(input.serviceOffset)
  ) return undefined;
  const sites: InfrastructureSiteRuntimeManifest[] = [];
  const siteIds = new Set<string>();
  for (const raw of input.sites) {
    const site = sanitizeInfrastructureManifest(raw);
    if (!site || siteIds.has(site.siteId)) return undefined;
    siteIds.add(site.siteId);
    sites.push(site);
  }
  const machines = sanitizeMachineArray(input.machines);
  const services = sanitizeServiceArray(input.services);
  if (
    !machines || !services ||
    input.machineOffset + machines.length > input.totalMachineCount ||
    input.serviceOffset + services.length > input.totalServiceCount
  ) return undefined;
  return {
    version: 1,
    kind: 'INFRASTRUCTURE_STATE_BASELINE',
    formatVersion: INFRASTRUCTURE_REPLICATION_FORMAT_VERSION,
    worldDatasetHash: input.worldDatasetHash,
    transferId: input.transferId,
    partIndex: input.partIndex,
    partCount: input.partCount,
    serverTick: serverTick(input.serverTick),
    revision: input.revision,
    sites,
    totalMachineCount: input.totalMachineCount,
    machineOffset: input.machineOffset,
    machines,
    totalServiceCount: input.totalServiceCount,
    serviceOffset: input.serviceOffset,
    services,
  };
};

export const validateInfrastructureStateDeltaPartPayload = (
  input: unknown,
): InfrastructureStateDeltaPartPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'INFRASTRUCTURE_STATE_DELTA' ||
    !boundedString(input.transferId) ||
    !natural(input.partIndex) ||
    !natural(input.partCount) || input.partCount < 1 || input.partCount > 64 ||
    input.partIndex >= input.partCount ||
    !natural(input.baseRevision) ||
    !natural(input.revision) || input.revision !== input.baseRevision + 1 ||
    !natural(input.serverTick) ||
    !natural(input.machineOffset) ||
    !natural(input.serviceOffset)
  ) return undefined;
  const site = sanitizeInfrastructureManifest(input.site);
  const machines = sanitizeMachineArray(input.machines);
  const services = sanitizeServiceArray(input.services);
  if (
    !site || !machines || !services ||
    input.machineOffset + machines.length > site.machineCount ||
    input.serviceOffset + services.length > site.serviceCount ||
    machines.some((machine) => machine.siteId !== site.siteId) ||
    services.some((service) => service.siteId !== site.siteId)
  ) return undefined;
  return {
    version: 1,
    kind: 'INFRASTRUCTURE_STATE_DELTA',
    transferId: input.transferId,
    partIndex: input.partIndex,
    partCount: input.partCount,
    baseRevision: input.baseRevision,
    revision: input.revision,
    serverTick: serverTick(input.serverTick),
    site,
    machineOffset: input.machineOffset,
    machines,
    serviceOffset: input.serviceOffset,
    services,
  };
};

export const validateInfrastructureStateResyncRequestPayload = (
  input: unknown,
): InfrastructureStateResyncRequestPayload | undefined =>
  isRecord(input) &&
  input.version === 1 &&
  input.kind === 'INFRASTRUCTURE_STATE_RESYNC_REQUEST' &&
  natural(input.observedRevision)
    ? {
        version: 1,
        kind: 'INFRASTRUCTURE_STATE_RESYNC_REQUEST',
        observedRevision: input.observedRevision,
      }
    : undefined;
