import type { GlobalPosition } from '../../world/GlobalPosition';
import { isGlobalPositionInPartition } from '../../world/GlobalPosition';
import { ICEAWAY_TARGET_WORLD_PARTITION } from '../../world/WorldPartitionTypes';
import {
  networkEntityId,
  playerId,
  serverTick,
  transactionId,
  type NetworkEntityId,
  type PlayerId,
  type ServerTick,
  type TransactionId,
} from '../core/NetworkPrimitives';

export const INVENTORY_REPLICATION_FORMAT_VERSION = 1;
export const MAX_PORTABLE_ITEMS = 4_096;
export const MAX_INVENTORY_CONTENTS = 1_024;
export const MAX_INVENTORY_RECORDS_PER_MESSAGE = 64;

export type PortableItemParent =
  | {
      readonly kind: 'WORLD';
      readonly worldPosition: GlobalPosition;
    }
  | {
      readonly kind: 'PLAYER';
      readonly playerId: PlayerId;
      readonly slotId: string;
    }
  | {
      readonly kind: 'VEHICLE_SLOT';
      readonly entityId: NetworkEntityId;
      readonly slotId: string;
    }
  | {
      readonly kind: 'CONTAINER_SLOT';
      readonly containerId: string;
      readonly slotId: string;
    }
  | {
      readonly kind: 'CONSUMED';
      readonly consumedAtTick: ServerTick;
    };

export interface PortableItemSnapshot {
  readonly itemId: string;
  readonly definitionId: string;
  readonly revision: number;
  readonly parent: PortableItemParent;
  readonly durability: number;
}

export type InventoryContentOwner =
  | { readonly kind: 'PLAYER'; readonly playerId: PlayerId }
  | { readonly kind: 'VEHICLE'; readonly entityId: NetworkEntityId }
  | { readonly kind: 'CONTAINER'; readonly containerId: string };

export interface InventorySlotSnapshot {
  readonly slotId: string;
  readonly slotRevision: number;
  readonly itemId?: string;
}

/** Canonical content only; radial order, cursor and menu state are local. */
export interface InventoryContentSnapshot {
  readonly contentId: string;
  readonly owner: InventoryContentOwner;
  readonly revision: number;
  readonly slots: readonly InventorySlotSnapshot[];
}

export interface InventoryStateBaselinePartPayload {
  readonly version: 1;
  readonly kind: 'INVENTORY_STATE_BASELINE';
  readonly formatVersion: number;
  readonly worldDatasetHash: string;
  readonly transferId: string;
  readonly partIndex: number;
  readonly partCount: number;
  readonly serverTick: ServerTick;
  readonly revision: number;
  readonly totalItemCount: number;
  readonly totalContentCount: number;
  readonly itemOffset: number;
  readonly items: readonly PortableItemSnapshot[];
  readonly contentOffset: number;
  readonly contents: readonly InventoryContentSnapshot[];
}

export interface InventoryStateDeltaPayload {
  readonly version: 1;
  readonly kind: 'INVENTORY_STATE_DELTA';
  readonly baseRevision: number;
  readonly revision: number;
  readonly serverTick: ServerTick;
  readonly requestId: TransactionId;
  readonly actorPlayerId: PlayerId;
  readonly operation:
    | 'PICKUP_ITEM'
    | 'PLACE_ITEM'
    | 'STORE_ITEM'
    | 'TAKE_ITEM'
    | 'GIVE_ITEM'
    | 'MOVE_ITEM'
    | 'CONSUME_ITEM'
    | 'CONSTRUCTION_RESERVATION';
  readonly changedItems: readonly PortableItemSnapshot[];
  readonly changedContents: readonly InventoryContentSnapshot[];
}

export interface InventoryStateResyncRequestPayload {
  readonly version: 1;
  readonly kind: 'INVENTORY_STATE_RESYNC_REQUEST';
  readonly observedRevision: number;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

const boundedString = (value: unknown, maximum = 160): value is string =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maximum;

const nonNegativeInteger = (value: unknown): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;

const clonePosition = (position: Readonly<GlobalPosition>): GlobalPosition => ({
  chunk: { ...position.chunk },
  local: { ...position.local },
});

export const clonePortableItemParent = (
  parent: Readonly<PortableItemParent>,
): PortableItemParent => {
  switch (parent.kind) {
    case 'WORLD':
      return { kind: 'WORLD', worldPosition: clonePosition(parent.worldPosition) };
    case 'PLAYER':
      return { ...parent };
    case 'VEHICLE_SLOT':
      return { ...parent };
    case 'CONTAINER_SLOT':
      return { ...parent };
    case 'CONSUMED':
      return { ...parent };
  }
};

export const clonePortableItemSnapshot = (
  item: Readonly<PortableItemSnapshot>,
): PortableItemSnapshot => ({
  ...item,
  parent: clonePortableItemParent(item.parent),
});

export const cloneInventoryContentSnapshot = (
  content: Readonly<InventoryContentSnapshot>,
): InventoryContentSnapshot => ({
  ...content,
  owner: { ...content.owner },
  slots: content.slots.map((slot) => ({ ...slot })),
});

export const inventoryContentIdForOwner = (
  owner: Readonly<InventoryContentOwner>,
): string => {
  switch (owner.kind) {
    case 'PLAYER':
      return `inventory:player:${owner.playerId}`;
    case 'VEHICLE':
      return `inventory:vehicle:${owner.entityId}`;
    case 'CONTAINER':
      return `inventory:container:${owner.containerId}`;
  }
};

const parentSlotKey = (
  parent: Readonly<PortableItemParent>,
): string | undefined => {
  switch (parent.kind) {
    case 'PLAYER':
      return `${inventoryContentIdForOwner(parent)}\u0000${parent.slotId}`;
    case 'VEHICLE_SLOT':
      return `${inventoryContentIdForOwner({
        kind: 'VEHICLE',
        entityId: parent.entityId,
      })}\u0000${parent.slotId}`;
    case 'CONTAINER_SLOT':
      return `${inventoryContentIdForOwner({
        kind: 'CONTAINER',
        containerId: parent.containerId,
      })}\u0000${parent.slotId}`;
    case 'WORLD':
    case 'CONSUMED':
      return undefined;
  }
};

/**
 * Audits the canonical one-parent graph shared by authority, checkpoints and
 * clients. A slotted item must be referenced by exactly one matching slot;
 * world and consumed items must not appear in any slot.
 */
export const validateInventoryOwnershipGraph = (
  items: readonly Readonly<PortableItemSnapshot>[],
  contents: readonly Readonly<InventoryContentSnapshot>[],
): string | undefined => {
  if (items.length > MAX_PORTABLE_ITEMS) return 'ITEM_LIMIT';
  if (contents.length > MAX_INVENTORY_CONTENTS) return 'CONTENT_LIMIT';
  const itemById = new Map<string, Readonly<PortableItemSnapshot>>();
  for (const item of items) {
    if (itemById.has(item.itemId)) return 'DUPLICATE_ITEM_ID';
    itemById.set(item.itemId, item);
  }
  const ownerIds = new Set<string>();
  const occupiedSlots = new Map<string, string>();
  const referencedItems = new Set<string>();
  for (const content of contents) {
    const expectedContentId = inventoryContentIdForOwner(content.owner);
    if (content.contentId !== expectedContentId) return 'NON_CANONICAL_CONTENT_ID';
    if (ownerIds.has(expectedContentId)) return 'DUPLICATE_CONTENT_OWNER';
    ownerIds.add(expectedContentId);
    const slotIds = new Set<string>();
    for (const slot of content.slots) {
      if (slotIds.has(slot.slotId)) return 'DUPLICATE_SLOT_ID';
      slotIds.add(slot.slotId);
      if (!slot.itemId) continue;
      const slotKey = `${content.contentId}\u0000${slot.slotId}`;
      if (occupiedSlots.has(slotKey)) return 'DUPLICATE_OCCUPIED_SLOT';
      if (referencedItems.has(slot.itemId)) return 'ITEM_IN_MULTIPLE_SLOTS';
      const item = itemById.get(slot.itemId);
      if (!item) return 'SLOT_REFERENCES_UNKNOWN_ITEM';
      if (parentSlotKey(item.parent) !== slotKey) return 'PARENT_SLOT_MISMATCH';
      occupiedSlots.set(slotKey, slot.itemId);
      referencedItems.add(slot.itemId);
    }
  }
  for (const item of items) {
    const expectedSlot = parentSlotKey(item.parent);
    if (expectedSlot === undefined) {
      if (referencedItems.has(item.itemId)) return 'UNSLOTTED_ITEM_REFERENCED';
      continue;
    }
    if (!ownerIds.has(expectedSlot.slice(0, expectedSlot.indexOf('\u0000')))) {
      return 'MISSING_PARENT_CONTENT';
    }
    if (occupiedSlots.get(expectedSlot) !== item.itemId) {
      return 'MISSING_PARENT_SLOT_REFERENCE';
    }
  }
  return undefined;
};

const sanitizeParent = (input: unknown): PortableItemParent | undefined => {
  if (!isRecord(input)) return undefined;
  if (input.kind === 'WORLD' && isRecord(input.worldPosition)) {
    const position = input.worldPosition as unknown as GlobalPosition;
    return isGlobalPositionInPartition(ICEAWAY_TARGET_WORLD_PARTITION, position)
      ? { kind: 'WORLD', worldPosition: clonePosition(position) }
      : undefined;
  }
  if (
    input.kind === 'PLAYER' &&
    boundedString(input.playerId) &&
    boundedString(input.slotId, 64)
  ) return {
    kind: 'PLAYER',
    playerId: playerId(input.playerId),
    slotId: input.slotId,
  };
  if (
    input.kind === 'VEHICLE_SLOT' &&
    boundedString(input.entityId) &&
    boundedString(input.slotId, 64)
  ) return {
    kind: 'VEHICLE_SLOT',
    entityId: networkEntityId(input.entityId),
    slotId: input.slotId,
  };
  if (
    input.kind === 'CONTAINER_SLOT' &&
    boundedString(input.containerId) &&
    boundedString(input.slotId, 64)
  ) return {
    kind: 'CONTAINER_SLOT',
    containerId: input.containerId,
    slotId: input.slotId,
  };
  if (input.kind === 'CONSUMED' && nonNegativeInteger(input.consumedAtTick)) {
    return { kind: 'CONSUMED', consumedAtTick: serverTick(input.consumedAtTick) };
  }
  return undefined;
};

export const sanitizePortableItemSnapshot = (
  input: unknown,
): PortableItemSnapshot | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.itemId) ||
    !boundedString(input.definitionId) ||
    !nonNegativeInteger(input.revision) ||
    typeof input.durability !== 'number' ||
    !Number.isFinite(input.durability) ||
    input.durability < 0 ||
    input.durability > 1
  ) return undefined;
  const parent = sanitizeParent(input.parent);
  return parent ? {
    itemId: input.itemId,
    definitionId: input.definitionId,
    revision: input.revision,
    parent,
    durability: input.durability,
  } : undefined;
};

const sanitizeOwner = (input: unknown): InventoryContentOwner | undefined => {
  if (!isRecord(input)) return undefined;
  if (input.kind === 'PLAYER' && boundedString(input.playerId)) {
    return { kind: 'PLAYER', playerId: playerId(input.playerId) };
  }
  if (input.kind === 'VEHICLE' && boundedString(input.entityId)) {
    return { kind: 'VEHICLE', entityId: networkEntityId(input.entityId) };
  }
  if (input.kind === 'CONTAINER' && boundedString(input.containerId)) {
    return { kind: 'CONTAINER', containerId: input.containerId };
  }
  return undefined;
};

export const sanitizeInventoryContentSnapshot = (
  input: unknown,
): InventoryContentSnapshot | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.contentId) ||
    !nonNegativeInteger(input.revision) ||
    !Array.isArray(input.slots) ||
    input.slots.length > 128
  ) return undefined;
  const owner = sanitizeOwner(input.owner);
  if (!owner) return undefined;
  const slotIds = new Set<string>();
  const itemIds = new Set<string>();
  const slots: InventorySlotSnapshot[] = [];
  for (const raw of input.slots) {
    if (
      !isRecord(raw) ||
      !boundedString(raw.slotId, 64) ||
      slotIds.has(raw.slotId) ||
      !nonNegativeInteger(raw.slotRevision) ||
      (raw.itemId !== undefined && !boundedString(raw.itemId)) ||
      (typeof raw.itemId === 'string' && itemIds.has(raw.itemId))
    ) return undefined;
    slotIds.add(raw.slotId);
    if (typeof raw.itemId === 'string') itemIds.add(raw.itemId);
    slots.push({
      slotId: raw.slotId,
      slotRevision: raw.slotRevision,
      ...(typeof raw.itemId === 'string' ? { itemId: raw.itemId } : {}),
    });
  }
  return {
    contentId: input.contentId,
    owner,
    revision: input.revision,
    slots,
  };
};

export const validateInventoryStateBaselinePartPayload = (
  input: unknown,
): InventoryStateBaselinePartPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'INVENTORY_STATE_BASELINE' ||
    input.formatVersion !== INVENTORY_REPLICATION_FORMAT_VERSION ||
    !boundedString(input.worldDatasetHash, 256) ||
    !boundedString(input.transferId) ||
    !nonNegativeInteger(input.partIndex) ||
    !nonNegativeInteger(input.partCount) ||
    input.partCount < 1 ||
    input.partCount > 4_096 ||
    input.partIndex >= input.partCount ||
    !nonNegativeInteger(input.serverTick) ||
    !nonNegativeInteger(input.revision) ||
    !nonNegativeInteger(input.totalItemCount) ||
    input.totalItemCount > MAX_PORTABLE_ITEMS ||
    !nonNegativeInteger(input.totalContentCount) ||
    input.totalContentCount > MAX_INVENTORY_CONTENTS ||
    !nonNegativeInteger(input.itemOffset) ||
    !Array.isArray(input.items) ||
    input.items.length > MAX_INVENTORY_RECORDS_PER_MESSAGE ||
    input.itemOffset + input.items.length > input.totalItemCount ||
    !nonNegativeInteger(input.contentOffset) ||
    !Array.isArray(input.contents) ||
    input.contents.length > MAX_INVENTORY_RECORDS_PER_MESSAGE ||
    input.contentOffset + input.contents.length > input.totalContentCount
  ) return undefined;
  const itemIds = new Set<string>();
  const items: PortableItemSnapshot[] = [];
  for (const raw of input.items) {
    const item = sanitizePortableItemSnapshot(raw);
    if (!item || itemIds.has(item.itemId)) return undefined;
    itemIds.add(item.itemId);
    items.push(item);
  }
  const contentIds = new Set<string>();
  const contents: InventoryContentSnapshot[] = [];
  for (const raw of input.contents) {
    const content = sanitizeInventoryContentSnapshot(raw);
    if (!content || contentIds.has(content.contentId)) return undefined;
    contentIds.add(content.contentId);
    contents.push(content);
  }
  return {
    version: 1,
    kind: 'INVENTORY_STATE_BASELINE',
    formatVersion: INVENTORY_REPLICATION_FORMAT_VERSION,
    worldDatasetHash: input.worldDatasetHash,
    transferId: input.transferId,
    partIndex: input.partIndex,
    partCount: input.partCount,
    serverTick: serverTick(input.serverTick),
    revision: input.revision,
    totalItemCount: input.totalItemCount,
    totalContentCount: input.totalContentCount,
    itemOffset: input.itemOffset,
    items,
    contentOffset: input.contentOffset,
    contents,
  };
};

const OPERATIONS = new Set<InventoryStateDeltaPayload['operation']>([
  'PICKUP_ITEM',
  'PLACE_ITEM',
  'STORE_ITEM',
  'TAKE_ITEM',
  'GIVE_ITEM',
  'MOVE_ITEM',
  'CONSUME_ITEM',
  'CONSTRUCTION_RESERVATION',
]);

export const validateInventoryStateDeltaPayload = (
  input: unknown,
): InventoryStateDeltaPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'INVENTORY_STATE_DELTA' ||
    !nonNegativeInteger(input.baseRevision) ||
    !nonNegativeInteger(input.revision) ||
    input.revision !== input.baseRevision + 1 ||
    !nonNegativeInteger(input.serverTick) ||
    !boundedString(input.requestId) ||
    !boundedString(input.actorPlayerId) ||
    typeof input.operation !== 'string' ||
    !OPERATIONS.has(input.operation as InventoryStateDeltaPayload['operation']) ||
    !Array.isArray(input.changedItems) ||
    input.changedItems.length < 1 ||
    input.changedItems.length > MAX_INVENTORY_RECORDS_PER_MESSAGE ||
    !Array.isArray(input.changedContents) ||
    input.changedContents.length > MAX_INVENTORY_RECORDS_PER_MESSAGE
  ) return undefined;
  const changedItems: PortableItemSnapshot[] = [];
  const itemIds = new Set<string>();
  for (const raw of input.changedItems) {
    const item = sanitizePortableItemSnapshot(raw);
    if (!item || itemIds.has(item.itemId)) return undefined;
    itemIds.add(item.itemId);
    changedItems.push(item);
  }
  const changedContents: InventoryContentSnapshot[] = [];
  const contentIds = new Set<string>();
  for (const raw of input.changedContents) {
    const content = sanitizeInventoryContentSnapshot(raw);
    if (!content || contentIds.has(content.contentId)) return undefined;
    contentIds.add(content.contentId);
    changedContents.push(content);
  }
  return {
    version: 1,
    kind: 'INVENTORY_STATE_DELTA',
    baseRevision: input.baseRevision,
    revision: input.revision,
    serverTick: serverTick(input.serverTick),
    requestId: transactionId(input.requestId),
    actorPlayerId: playerId(input.actorPlayerId),
    operation: input.operation as InventoryStateDeltaPayload['operation'],
    changedItems,
    changedContents,
  };
};

export const validateInventoryStateResyncRequestPayload = (
  input: unknown,
): InventoryStateResyncRequestPayload | undefined =>
  isRecord(input) &&
  input.version === 1 &&
  input.kind === 'INVENTORY_STATE_RESYNC_REQUEST' &&
  nonNegativeInteger(input.observedRevision)
    ? {
        version: 1,
        kind: 'INVENTORY_STATE_RESYNC_REQUEST',
        observedRevision: input.observedRevision,
      }
    : undefined;
