import { clamp } from '../utils/math';
import {
  gamepadAxis,
  gamepadButtonPressed,
  gamepadButtonValue,
  getPrimaryGamepad,
} from './GamepadInput';

export interface PenguinControlCommand {
  forward: number;
  right: number;
  run: boolean;
  /** One-shot grounded jump request; held Space remains available to tools. */
  jump: boolean;
  blower: boolean;
  requestEnterVehicle: boolean;
  aimX?: number;
  aimZ?: number;
}

export interface PenguinTraversalActions {
  readonly jump: boolean;
  readonly flip: number;
  readonly spin: number;
}

const CONTROL_KEYS = new Set([
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'KeyW',
  'KeyA',
  'KeyS',
  'KeyD',
  'KeyF',
  'ShiftLeft',
  'ShiftRight',
  'Space',
  'KeyQ',
  'KeyE',
  'KeyZ',
  'KeyC',
]);

export class PlayerPenguinController {
  private readonly pressed = new Set<string>();
  private enabled = false;
  private virtualBlower = false;
  private virtualForward = 0;
  private virtualRight = 0;
  private aimX?: number;
  private aimZ?: number;
  private enterRequested = false;
  private gamepadEnterPressed = false;
  private jumpRequested = false;
  private gamepadJumpPressed = false;

  public constructor() {
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    window.addEventListener('blur', this.onBlur);
  }

  public setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    this.pressed.clear();
    this.virtualBlower = false;
    this.virtualForward = 0;
    this.virtualRight = 0;
    this.aimX = undefined;
    this.aimZ = undefined;
    this.enterRequested = false;
    this.gamepadEnterPressed = false;
    this.jumpRequested = false;
    this.gamepadJumpPressed = false;
  }

  public setBlowerInput(active: boolean): void {
    this.virtualBlower = active;
  }

  /** Input seam for a future mobile virtual stick. */
  public setVirtualMovement(right: number, forward: number): void {
    this.virtualRight = clamp(right, -1, 1);
    this.virtualForward = clamp(forward, -1, 1);
  }

  public setAimPoint(x: number, z: number): void {
    if (!this.enabled || !Number.isFinite(x) || !Number.isFinite(z)) return;
    this.aimX = x;
    this.aimZ = z;
  }

  public clearAimPoint(): void {
    this.aimX = undefined;
    this.aimZ = undefined;
  }

  public requestEnterVehicle(): void {
    if (this.enabled) this.enterRequested = true;
  }

  /** Touch/controller UI seam matching the one-shot keyboard jump. */
  public requestJump(): void {
    if (this.enabled) this.jumpRequested = true;
  }

  public sampleControls(): PenguinControlCommand {
    if (!this.enabled) {
      return {
        forward: 0,
        right: 0,
        run: false,
        jump: false,
        blower: false,
        requestEnterVehicle: false,
      };
    }
    const keyboardForward =
      (this.isPressed('KeyW', 'ArrowUp') ? 1 : 0) -
      (this.isPressed('KeyS', 'ArrowDown') ? 1 : 0);
    const keyboardRight =
      (this.isPressed('KeyD', 'ArrowRight') ? 1 : 0) -
      (this.isPressed('KeyA', 'ArrowLeft') ? 1 : 0);
    const gamepad = getPrimaryGamepad();
    const gamepadForward = -gamepadAxis(gamepad, 1);
    const gamepadRight = gamepadAxis(gamepad, 0);
    const gamepadEnter = gamepadButtonPressed(gamepad, 2);
    if (gamepadEnter && !this.gamepadEnterPressed) {
      this.enterRequested = true;
    }
    this.gamepadEnterPressed = gamepadEnter;
    const gamepadJump = gamepadButtonPressed(gamepad, 0);
    if (gamepadJump && !this.gamepadJumpPressed) this.jumpRequested = true;
    this.gamepadJumpPressed = gamepadJump;
    const command: PenguinControlCommand = {
      forward: clamp(
        Math.abs(keyboardForward) > 0.01
          ? keyboardForward
          : Math.abs(this.virtualForward) > 0.01
            ? this.virtualForward
            : gamepadForward,
        -1,
        1,
      ),
      right: clamp(
        Math.abs(keyboardRight) > 0.01
          ? keyboardRight
          : Math.abs(this.virtualRight) > 0.01
            ? this.virtualRight
            : gamepadRight,
        -1,
        1,
      ),
      run:
        this.pressed.has('ShiftLeft') ||
        this.pressed.has('ShiftRight') ||
        gamepadButtonPressed(gamepad, 0),
      jump: this.jumpRequested,
      blower:
        this.virtualBlower ||
        this.pressed.has('Space') ||
        gamepadButtonValue(gamepad, 7) > 0.16,
      requestEnterVehicle: this.enterRequested,
      aimX: this.aimX,
      aimZ: this.aimZ,
    };
    this.enterRequested = false;
    this.jumpRequested = false;
    return command;
  }

  public sampleTraversalActions(): PenguinTraversalActions {
    if (!this.enabled) return { jump: false, flip: 0, spin: 0 };
    const gamepad = getPrimaryGamepad();
    return {
      jump: this.pressed.has('Space') || gamepadButtonPressed(gamepad, 0),
      flip:
        (this.pressed.has('KeyE') ? 1 : 0) -
        (this.pressed.has('KeyQ') ? 1 : 0),
      spin:
        (this.pressed.has('KeyC') ? 1 : 0) -
        (this.pressed.has('KeyZ') ? 1 : 0),
    };
  }

  public dispose(): void {
    window.removeEventListener('keydown', this.onKeyDown);
    window.removeEventListener('keyup', this.onKeyUp);
    window.removeEventListener('blur', this.onBlur);
  }

  private isPressed(...codes: string[]): boolean {
    return codes.some((code) => this.pressed.has(code));
  }

  private onKeyDown = (event: KeyboardEvent): void => {
    if (!this.enabled) return;
    if (CONTROL_KEYS.has(event.code)) event.preventDefault();
    this.pressed.add(event.code);
    if (!event.repeat && event.code === 'KeyF') {
      this.enterRequested = true;
    }
    if (!event.repeat && event.code === 'Space') {
      this.jumpRequested = true;
    }
  };

  private onKeyUp = (event: KeyboardEvent): void => {
    this.pressed.delete(event.code);
  };

  private onBlur = (): void => {
    this.pressed.clear();
    this.virtualBlower = false;
    this.virtualForward = 0;
    this.virtualRight = 0;
    this.aimX = undefined;
    this.aimZ = undefined;
    this.enterRequested = false;
    this.gamepadEnterPressed = false;
    this.jumpRequested = false;
    this.gamepadJumpPressed = false;
  };
}
