import type {
  ReplicatedWorldDomainEvent,
  SharedWorldCompactSnapshot,
  WorldDomainEventBatchPayload,
  WorldEventResyncRequestPayload,
  WorldStateBaselinePayload,
  WorldStateDeltaPayload,
} from '../../netcode/protocol/WorldReplication';

export interface WorldReplicationClientDiagnostics {
  readonly completedBaselines: number;
  readonly appliedDeltas: number;
  readonly appliedEvents: number;
  readonly duplicateEvents: number;
  readonly staleMessages: number;
  readonly resyncRequests: number;
  readonly snapshotRevision: number;
  readonly authorityRevision: number;
  readonly eventCursor: number;
}

export type WorldReplicationClientEvent =
  | {
      readonly kind: 'BASELINE';
      readonly payload: Readonly<WorldStateBaselinePayload>;
      readonly snapshot: Readonly<SharedWorldCompactSnapshot>;
    }
  | {
      readonly kind: 'DELTA';
      readonly payload: Readonly<WorldStateDeltaPayload>;
      readonly snapshot: Readonly<SharedWorldCompactSnapshot>;
    }
  | {
      readonly kind: 'EVENTS';
      readonly payload: Readonly<WorldDomainEventBatchPayload>;
      readonly events: readonly Readonly<ReplicatedWorldDomainEvent>[];
    };

const jsonClone = <T>(value: T): T =>
  JSON.parse(JSON.stringify(value)) as T;

/** Read-only client projection of authority-owned quests, NPCs and world state. */
export class WorldReplicationClient {
  private snapshotValue?: SharedWorldCompactSnapshot;
  private eventCursorValue = 0;
  private completedBaselines = 0;
  private appliedDeltas = 0;
  private appliedEvents = 0;
  private duplicateEvents = 0;
  private staleMessages = 0;
  private resyncRequests = 0;
  private resyncPending = false;
  private readonly processedEventIds = new Set<string>();
  private readonly processedEventOrder: string[] = [];

  public constructor(
    private readonly worldDatasetHash: string,
    private readonly requestResync: (
      request: Readonly<WorldEventResyncRequestPayload>,
    ) => void,
  ) {}

  public applyBaseline(
    payload: Readonly<WorldStateBaselinePayload>,
  ): WorldReplicationClientEvent | undefined {
    if (payload.worldDatasetHash !== this.worldDatasetHash) return undefined;
    if (
      this.snapshotValue &&
      (payload.snapshot.revision < this.snapshotValue.revision ||
        payload.snapshot.authorityRevision <
          this.snapshotValue.authorityRevision)
    ) {
      this.staleMessages += 1;
      return undefined;
    }
    this.snapshotValue = jsonClone(payload.snapshot);
    this.eventCursorValue = payload.snapshot.eventCursor;
    this.completedBaselines += 1;
    this.resyncPending = false;
    return {
      kind: 'BASELINE',
      payload,
      snapshot: this.snapshot()!,
    };
  }

  public applyDelta(
    payload: Readonly<WorldStateDeltaPayload>,
  ): WorldReplicationClientEvent | undefined {
    const current = this.snapshotValue;
    if (!current) {
      this.request('FULL');
      return undefined;
    }
    if (payload.revision <= current.revision) {
      this.staleMessages += 1;
      return undefined;
    }
    if (payload.baseRevision !== current.revision) {
      this.request('FULL');
      return undefined;
    }
    if (payload.snapshot.authorityRevision < current.authorityRevision) {
      this.request('FULL');
      return undefined;
    }
    this.snapshotValue = jsonClone(payload.snapshot);
    this.appliedDeltas += 1;
    this.resyncPending = false;
    return {
      kind: 'DELTA',
      payload,
      snapshot: this.snapshot()!,
    };
  }

  public applyEvents(
    payload: Readonly<WorldDomainEventBatchPayload>,
  ): WorldReplicationClientEvent | undefined {
    const cursorFresh = payload.events.filter((event) => {
      if (event.cursor <= this.eventCursorValue) {
        this.duplicateEvents += 1;
        return false;
      }
      return true;
    });
    if (cursorFresh.length === 0) return undefined;
    if (cursorFresh[0]!.cursor !== this.eventCursorValue + 1) {
      this.request('EVENTS');
      return undefined;
    }
    const fresh = cursorFresh.filter((record) => {
      const eventId = record.event.eventId;
      if (this.processedEventIds.has(eventId)) {
        this.duplicateEvents += 1;
        return false;
      }
      this.rememberEventId(eventId);
      return true;
    });
    // A duplicate event ID still consumes its authority cursor. Otherwise the
    // next valid event would look like a gap and cause a resync loop.
    this.eventCursorValue = cursorFresh[cursorFresh.length - 1]!.cursor;
    if (fresh.length === 0) return undefined;
    this.appliedEvents += fresh.length;
    this.resyncPending = false;
    return {
      kind: 'EVENTS',
      payload,
      events: fresh.map((event) => jsonClone(event)),
    };
  }

  public snapshot(): Readonly<SharedWorldCompactSnapshot> | undefined {
    return this.snapshotValue ? jsonClone(this.snapshotValue) : undefined;
  }

  public diagnostics(): WorldReplicationClientDiagnostics {
    return {
      completedBaselines: this.completedBaselines,
      appliedDeltas: this.appliedDeltas,
      appliedEvents: this.appliedEvents,
      duplicateEvents: this.duplicateEvents,
      staleMessages: this.staleMessages,
      resyncRequests: this.resyncRequests,
      snapshotRevision: this.snapshotValue?.revision ?? 0,
      authorityRevision: this.snapshotValue?.authorityRevision ?? 0,
      eventCursor: this.eventCursorValue,
    };
  }

  public reset(): void {
    this.snapshotValue = undefined;
    this.eventCursorValue = 0;
    this.resyncPending = false;
    this.processedEventIds.clear();
    this.processedEventOrder.length = 0;
  }

  private rememberEventId(eventId: string): void {
    this.processedEventIds.add(eventId);
    this.processedEventOrder.push(eventId);
    while (this.processedEventOrder.length > 4_096) {
      const removed = this.processedEventOrder.shift();
      if (removed) this.processedEventIds.delete(removed);
    }
  }

  private request(scope: WorldEventResyncRequestPayload['scope']): void {
    if (this.resyncPending) return;
    this.resyncPending = true;
    this.resyncRequests += 1;
    this.requestResync({
      version: 1,
      kind: 'WORLD_EVENT_RESYNC_REQUEST',
      afterCursor: this.eventCursorValue,
      observedRevision: this.snapshotValue?.revision ?? 0,
      scope,
    });
  }
}
